// Lazy on-demand loaders for heavy libraries so initial boot stays fast ("anti lemot")
let _d3LoadingPromise = null;
window.ensureD3Loaded = async () => {
    if (window.d3) return window.d3;
    if (!_d3LoadingPromise) {
        _d3LoadingPromise = import("d3").then((mod) => {
            const inst = mod?.default && typeof mod.default.select === "function" ? mod.default : mod;
            window.d3 = inst;
            return inst;
        }).catch((err) => {
            _d3LoadingPromise = null;
            console.warn("Gagal memuat modul D3:", err);
            return null;
        });
    }
    return _d3LoadingPromise;
};

let _jsPdfLoadingPromise = null;
window.ensureJsPdfLoaded = async () => {
    if (window.jsPDF && window.autoTable) {
        return { jsPDF: window.jsPDF, autoTable: window.autoTable };
    }
    if (!_jsPdfLoadingPromise) {
        _jsPdfLoadingPromise = Promise.all([
            import("jspdf"),
            import("jspdf-autotable")
        ]).then(([pdfMod, tableMod]) => {
            const pdfClass = pdfMod.jsPDF || pdfMod.default?.jsPDF || pdfMod.default;
            const tableFn = tableMod.default || tableMod.autoTable;
            if (pdfClass) window.jsPDF = pdfClass;
            if (tableFn) window.autoTable = tableFn;
            return { jsPDF: window.jsPDF, autoTable: window.autoTable };
        }).catch((err) => {
            _jsPdfLoadingPromise = null;
            throw err;
        });
    }
    return _jsPdfLoadingPromise;
};

let _html5QrcodeLoadingPromise = null;
window.ensureHtml5QrcodeLoaded = async () => {
    if (window.Html5Qrcode) return window.Html5Qrcode;
    if (!_html5QrcodeLoadingPromise) {
        _html5QrcodeLoadingPromise = import("html5-qrcode").then((mod) => {
            const cls = mod.Html5Qrcode || mod.default?.Html5Qrcode || mod.default;
            if (cls) window.Html5Qrcode = cls;
            return window.Html5Qrcode;
        }).catch((err) => {
            _html5QrcodeLoadingPromise = null;
            console.warn("Gagal memuat modul Html5Qrcode:", err);
            return null;
        });
    }
    return _html5QrcodeLoadingPromise;
};

