// SISTEM SAPU JAGAT (ANTI CACHE & ANTI BUG)
// ==========================================
(function initSapuJagat() {
    const versiTerbaru = "mainstay_clean_v730"; 
    
    try {
        const versiDiHPPembeli = localStorage.getItem('versi_cache_mainstay');
        
        if (versiDiHPPembeli !== versiTerbaru) {
            const savedRole = localStorage.getItem('mainstay_session_role');
            const savedStaff = localStorage.getItem('mainstay_staff_name');
            const savedStaffObj = localStorage.getItem('mainstay_session_staff');
            const savedPin = localStorage.getItem('mainstay_staff_pin');
            const savedIsKasirOpen = localStorage.getItem('mainstay_is_kasir_open');
            const savedActivePanel = localStorage.getItem('mainstay_active_panel');
            const savedOfflineOrders = localStorage.getItem('mainstay_offline_orders');
            const savedSyncQueue = localStorage.getItem('mainstay_pos_sync_queue');

            localStorage.clear();
            sessionStorage.clear();

            if (savedRole) localStorage.setItem('mainstay_session_role', savedRole);
            if (savedStaff) localStorage.setItem('mainstay_staff_name', savedStaff);
            if (savedStaffObj) localStorage.setItem('mainstay_session_staff', savedStaffObj);
            if (savedPin) localStorage.setItem('mainstay_staff_pin', savedPin);
            if (savedIsKasirOpen) localStorage.setItem('mainstay_is_kasir_open', savedIsKasirOpen);
            if (savedActivePanel) localStorage.setItem('mainstay_active_panel', savedActivePanel);
            if (savedOfflineOrders) localStorage.setItem('mainstay_offline_orders', savedOfflineOrders);
            if (savedSyncQueue) localStorage.setItem('mainstay_pos_sync_queue', savedSyncQueue);
            localStorage.setItem('versi_cache_mainstay', versiTerbaru);
        }
    } catch (e) {
        console.log("Browser storage check note:", e);
    }
})();

// ==========================================
// SISTEM MULTI-CABANG: RESOLUSI URL & ISOLASI STORAGE PER CABANG
// ==========================================
(function initBranchContextAndStorageIsolation() {
    const normalizeBranchSlug = (raw) => {
        const cleaned = String(raw || '')
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9_-]/g, '-')
            .replace(/-+/g, '-')
            .replace(/^-|-$/g, '');
        if (!cleaned || cleaned === 'pusat' || cleaned === 'main' || cleaned === 'root' || cleaned === 'default') {
            return 'pusat';
        }
        return cleaned;
    };

    window.normalizeBranchSlug = normalizeBranchSlug;

    let detectedBranch = 'pusat';
    try {
        const params = new URLSearchParams(window.location.search || '');
        const rawParam = params.get('cabang') || params.get('branch') || '';
        detectedBranch = normalizeBranchSlug(rawParam);
    } catch (e) {}

    window.ACTIVE_BRANCH_ID = detectedBranch;
    window.IS_BRANCH_OUTLET = detectedBranch !== 'pusat';
    window.globalBranches = window.globalBranches || {};

    window.getBranchUrl = (branchId) => {
        const cleanId = normalizeBranchSlug(branchId);
        const base = window.location.origin + window.location.pathname;
        if (cleanId === 'pusat') return base;
        return `${base}?cabang=${encodeURIComponent(cleanId)}`;
    };

    if (detectedBranch !== 'pusat') {
        const GLOBAL_STORAGE_KEYS = new Set([
            'versi_cache_mainstay',
            'mainstay_thermal_width',
            'mainstay_last_bt_printer',
            'mainstay_master_owner_jump'
        ]);
        const prefix = `__branch_${detectedBranch}`;
        const origGet = Storage.prototype.getItem;
        const origSet = Storage.prototype.setItem;
        const origRemove = Storage.prototype.removeItem;

        const scopeKey = (k) => {
            const keyStr = String(k || '');
            if (!keyStr || GLOBAL_STORAGE_KEYS.has(keyStr) || keyStr.endsWith(prefix)) return keyStr;
            return `${keyStr}${prefix}`;
        };

        Storage.prototype.getItem = function(key) {
            if (this === window.localStorage) {
                return origGet.call(this, scopeKey(key));
            }
            return origGet.call(this, key);
        };
        Storage.prototype.setItem = function(key, val) {
            if (this === window.localStorage) {
                return origSet.call(this, scopeKey(key), val);
            }
            return origSet.call(this, key, val);
        };
        Storage.prototype.removeItem = function(key) {
            if (this === window.localStorage) {
                return origRemove.call(this, scopeKey(key));
            }
            return origRemove.call(this, key);
        };
    }
})();

// ==========================================
// PENYIMPANAN AMAN ANTI QUOTA-EXCEEDED ERROR
// ==========================================
window.safeSetItem = (key, value) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        if (e && (e.name === 'QuotaExceededError' || e.code === 22 || e.code === 1014 || e.number === -2147024882)) {
            console.warn(`[SafeStorage] Quota exceeded saat menulis key '${key}'. Membersihkan cache lokal lama...`);
            try {
                // 1. Bersihkan foto besar dari log absensi lokal
                const rawLogs = localStorage.getItem('mainstay_attendance_local_logs');
                if (rawLogs) {
                    const parsed = JSON.parse(rawLogs);
                    if (Array.isArray(parsed)) {
                        const sanitized = parsed.slice(0, 15).map(item => {
                            const { foto, buktiIzinFoto, ...rest } = item;
                            return rest;
                        });
                        localStorage.setItem('mainstay_attendance_local_logs', JSON.stringify(sanitized));
                    }
                }
            } catch(e1) {
                try { localStorage.removeItem('mainstay_attendance_local_logs'); } catch(_) {}
            }

            try {
                // 2. Jika key adalah session staff, buang foto base64 besar
                if (key === 'mainstay_session_staff' && typeof value === 'string') {
                    try {
                        const parsed = JSON.parse(value);
                        delete parsed.photo;
                        delete parsed.foto;
                        value = JSON.stringify(parsed);
                    } catch(_) {}
                }
                localStorage.setItem(key, value);
            } catch (retryErr) {
                console.warn(`[SafeStorage] Penyimpanan key '${key}' dilewati setelah pembersihan:`, retryErr);
            }
        } else {
            console.warn(`[SafeStorage] Gagal menulis '${key}':`, e);
        }
    }
};

// Pembersihan instan data bengkak saat startup
(function sanitizeStorageStartup() {
    try {
        const rawLogs = localStorage.getItem('mainstay_attendance_local_logs');
        if (rawLogs && rawLogs.length > 30000) {
            const parsed = JSON.parse(rawLogs);
            if (Array.isArray(parsed)) {
                const sanitized = parsed.slice(0, 20).map(item => {
                    const { foto, buktiIzinFoto, ...rest } = item;
                    return rest;
                });
                localStorage.setItem('mainstay_attendance_local_logs', JSON.stringify(sanitized));
            }
        }
        const staffObj = localStorage.getItem('mainstay_session_staff');
        if (staffObj && staffObj.length > 15000) {
            const parsed = JSON.parse(staffObj);
            delete parsed.photo;
            delete parsed.foto;
            localStorage.setItem('mainstay_session_staff', JSON.stringify(parsed));
        }
    } catch(e) {}
})();

