let deferredPWAInstallPrompt = null;
let updateSWInstance = null;

const isStandalonePWA = () => {
    try {
        return window.matchMedia('(display-mode: standalone)').matches ||
            window.matchMedia('(display-mode: window-controls-overlay)').matches ||
            (window.navigator.standalone === true);
    } catch (e) {
        return false;
    }
};

const isIOSDevice = () => {
    try {
        return /iPad|iPhone|iPod/.test(navigator.userAgent || '') ||
            (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    } catch (e) {
        return false;
    }
};

window._pendingSilentPwaUpdate = false;

const isSafeToAutoReloadPWA = () => {
    try {
        const busyModals = ['checkout-modal', 'modal-struk', 'modal-struk-dapur', 'modal-cetak-universal', 'panel-kasir-manual', 'modal-detail-produk'];
        const hasBusyModal = busyModals.some(id => {
            const el = document.getElementById(id);
            return el && !el.classList.contains('hidden');
        });
        const hasPendingCart = Array.isArray(window.cart) && window.cart.length > 0;
        return !hasBusyModal && !hasPendingCart;
    } catch (e) {
        return true;
    }
};

window.tampilkanBannerUpdatePWA = () => {
    // Banner popup mengambang dinonaktifkan; pembaruan dijalankan otomatis di latar belakang
    window.terapkanUpdatePWA(true);
};

window.terapkanUpdatePWA = async (silent = true) => {
    if (silent && !isSafeToAutoReloadPWA()) {
        window._pendingSilentPwaUpdate = true;
        return;
    }
    window._pendingSilentPwaUpdate = false;
    try {
        if (typeof updateSWInstance === 'function') {
            await updateSWInstance(true);
            return;
        }
        if (window.mainstaySWRegistration && window.mainstaySWRegistration.waiting) {
            window.mainstaySWRegistration.waiting.postMessage({ type: 'SKIP_WAITING' });
        }
    } catch (e) {
        console.warn('[PWA] Update apply fallback:', e);
    }
    if (!silent) {
        window.location.reload();
    }
};

window.safeJsonParse = (rawStr, fallback = null) => {
    try {
        if (rawStr === null || rawStr === undefined || rawStr === '') return fallback;
        const parsed = JSON.parse(rawStr);
        return (parsed === null || parsed === undefined) ? fallback : parsed;
    } catch (e) {
        return fallback;
    }
};

window.debounceUiFn = (fn, waitMs = 150) => {
    let t = null;
    return function(...args) {
        if (t) clearTimeout(t);
        t = setTimeout(() => {
            t = null;
            try { fn.apply(this, args); } catch (e) { console.warn('Debounced render notice:', e); }
        }, waitMs);
    };
};

window.applySwrCatalogMenusData = (rtdbData, fromSwrBgMessage = false) => {
    if (!rtdbData || typeof rtdbData !== 'object') return false;
    if (window._menusLiveLoadedFromRTDB && !fromSwrBgMessage) return false;

    const deletedMenuKeys = window.safeJsonParse(localStorage.getItem('mainstay_deleted_menu_keys'), []);
    const dummyKeys = ['menu_americano', 'menu_thai_tea', 'menu_taro_milk', 'menu_vanilla', 'menu_pukis', 'menu_kopi_susu', 'menu_es_teh', 'menu_matcha'];
    const combined = { ...rtdbData };
    dummyKeys.forEach(k => delete combined[k]);
    if (Array.isArray(deletedMenuKeys)) {
        deletedMenuKeys.forEach(k => delete combined[k]);
    }

    if (Object.keys(combined).length > 0) {
        globalMenus = combined;
        window.globalMenus = combined;
        try { localStorage.setItem('mainstay_cached_menus', JSON.stringify(combined)); } catch (e) {}

        if (currentRole === 'customer') {
            if (typeof window.scheduleCustomerCatalogRender === 'function') window.scheduleCustomerCatalogRender();
            else if (typeof window.renderKatalog === 'function') window.renderKatalog();
        } else if (currentRole === 'kasir' || localStorage.getItem('mainstay_is_kasir_open') === 'true') {
            if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
        }
        return true;
    }
    return false;
};

window.hydrateMenuCatalogSWR = async (fromSwrBgMessage = false) => {
    // 1. Hidrasi instan dari localStorage sebelum network fetch (menghilangkan delay saat koneksi lambat/offline)
    try {
        if (!window._menusLiveLoadedFromRTDB && (!globalMenus || Object.keys(globalMenus).length === 0)) {
            const cachedMenusStr = localStorage.getItem('mainstay_cached_menus');
            if (cachedMenusStr) {
                const cachedMenusObj = JSON.parse(cachedMenusStr);
                if (cachedMenusObj && typeof cachedMenusObj === 'object' && Object.keys(cachedMenusObj).length > 0) {
                    window.applySwrCatalogMenusData(cachedMenusObj, fromSwrBgMessage);
                }
            }
        }
    } catch (_) {}

    try {
        const bid = window.ACTIVE_BRANCH_ID || 'pusat';
        const baseDbUrl = 'https://mainstay-pos-default-rtdb.asia-southeast1.firebasedatabase.app';
        const prefix = bid === 'pusat' ? '' : `/branch_data/${encodeURIComponent(bid)}`;
        const menusUrl = `${baseDbUrl}${prefix}/menus.json`;

        const res = await fetch(menusUrl, { method: 'GET' });
        if (res && res.ok) {
            const rtdbData = await res.json();
            window.applySwrCatalogMenusData(rtdbData, fromSwrBgMessage);
        }

        // Hidrasi paralel master kategori, topping, varian, categories & store_settings melalui cache SWR
        Promise.allSettled([
            fetch(`${baseDbUrl}${prefix}/master_kategori.json`).then(r => r.ok ? r.json() : null),
            fetch(`${baseDbUrl}${prefix}/master_topping.json`).then(r => r.ok ? r.json() : null),
            fetch(`${baseDbUrl}${prefix}/master_varian.json`).then(r => r.ok ? r.json() : null),
            fetch(`${baseDbUrl}${prefix}/categories.json`).then(r => r.ok ? r.json() : null),
            fetch(`${baseDbUrl}${prefix}/store_settings.json`).then(r => r.ok ? r.json() : null)
        ]).then(([katRes, topRes, varRes, catRes, setRes]) => {
            if (katRes.status === 'fulfilled' && katRes.value && !window._menusLiveLoadedFromRTDB) {
                const rawKat = Array.isArray(katRes.value) ? katRes.value : Object.values(katRes.value);
                const cleanKat = rawKat.map(k => (k && typeof k === 'object') ? (k.name || k.nama || k.id) : k).filter(Boolean);
                if (cleanKat.length > 0 && (!window.masterKategori || window.masterKategori.length === 0)) {
                    window.masterKategori = cleanKat;
                    try { localStorage.setItem('master_kategori', JSON.stringify(cleanKat)); } catch (_) {}
                    if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
                }
            }
            if (catRes.status === 'fulfilled' && catRes.value && !window._menusLiveLoadedFromRTDB) {
                const rawCat = Array.isArray(catRes.value) ? catRes.value : Object.values(catRes.value);
                const cleanCat = rawCat.map(c => (c && typeof c === 'object') ? (c.name || c.nama || c.id) : c).filter(Boolean);
                if (cleanCat.length > 0) {
                    const mergedKat = [...new Set([...(window.masterKategori || []), ...cleanCat])];
                    window.masterKategori = mergedKat;
                    try { localStorage.setItem('master_kategori', JSON.stringify(mergedKat)); } catch (_) {}
                    if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
                }
            }
            if (topRes.status === 'fulfilled' && topRes.value && !window._menusLiveLoadedFromRTDB && (!window.masterTopping || window.masterTopping.length === 0)) {
                window.masterTopping = Array.isArray(topRes.value) ? topRes.value : Object.values(topRes.value);
                try { localStorage.setItem('master_topping', JSON.stringify(window.masterTopping)); } catch (_) {}
            }
            if (varRes.status === 'fulfilled' && varRes.value && !window._menusLiveLoadedFromRTDB && (!window.masterVarian || window.masterVarian.length === 0)) {
                window.masterVarian = Array.isArray(varRes.value) ? varRes.value : Object.values(varRes.value);
                try { localStorage.setItem('master_varian', JSON.stringify(window.masterVarian)); } catch (_) {}
            }
            if (setRes.status === 'fulfilled' && setRes.value && typeof setRes.value === 'object' && !window._storeSettingsLoaded) {
                if (typeof window.applyStoreSettingsToUI === 'function') {
                    window.applyStoreSettingsToUI(setRes.value);
                }
            }
        }).catch(() => {});
    } catch (err) {
        // Fallback diam ke localStorage jika offline penuh dan belum pernah tercache SW
    }
};

