// Secondary Firebase App dedicated for Google Drive OAuth (token cached strictly in-memory)
const oauthApp = oauthFirebaseConfig?.projectId
    ? initializeApp(oauthFirebaseConfig, 'mainstay-google-workspace')
    : null;
const oauthAuth = oauthApp ? getAuth(oauthApp) : null;

let _driveAccessToken = null;
let _driveUser = null;
let _driveFolderId = null;
let _driveBackupsCache = [];
let _driveLoadingState = false;
let _driveSyncInProgress = false;
let _driveLastError = '';

if (oauthAuth) {
    onAuthStateChanged(oauthAuth, (user) => {
        if (!user) {
            _driveAccessToken = null;
            _driveUser = null;
            _driveFolderId = null;
            _driveBackupsCache = [];
        } else {
            _driveUser = {
                uid: user.uid,
                email: user.email || '',
                displayName: user.displayName || 'Akun Google',
                photoURL: user.photoURL || ''
            };
        }
        if (document.getElementById('db-drive-status-card') && typeof window.renderGoogleDriveBackupSection === 'function') {
            window.renderGoogleDriveBackupSection();
        }
        if (typeof window._refreshBackupJobsDashboard === 'function') {
            window._refreshBackupJobsDashboard();
        }
    });
}

window.googleDriveAuth = {
    isConfigured() {
        return Boolean(oauthAuth && oauthFirebaseConfig?.projectId);
    },
    isConnected() {
        return Boolean(_driveUser && _driveAccessToken);
    },
    getUser() {
        return _driveUser;
    },
    getAccessToken() {
        return _driveAccessToken;
    },
    clearToken() {
        _driveAccessToken = null;
    },
    async connect() {
        if (!oauthAuth) {
            throw new Error('Konfigurasi Google OAuth belum tersedia.');
        }
        const provider = new GoogleAuthProvider();
        provider.addScope('https://www.googleapis.com/auth/drive.file');
        provider.setCustomParameters({ prompt: 'select_account' });
        const result = await signInWithPopup(oauthAuth, provider);
        const credential = GoogleAuthProvider.credentialFromResult(result);
        const token = credential?.accessToken || null;
        if (!token) {
            throw new Error('Access token Google Drive tidak diterima. Silakan coba masuk ulang.');
        }
        _driveAccessToken = token;
        _driveLastError = '';
        if (result?.user) {
            _driveUser = {
                uid: result.user.uid,
                email: result.user.email || '',
                displayName: result.user.displayName || 'Akun Google',
                photoURL: result.user.photoURL || ''
            };
        }
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(`Google Drive terhubung (${_driveUser?.email || 'Akun Google'})`, 'success');
        }
        await window.mainstayDriveBackup.listBackups({ force: true }).catch(() => {});
        if (typeof window.renderGoogleDriveBackupSection === 'function') {
            window.renderGoogleDriveBackupSection();
        }
        if (typeof window._refreshBackupJobsDashboard === 'function') {
            window._refreshBackupJobsDashboard();
        }
        return _driveUser;
    },
    async ensureValidToken({ interactive = false } = {}) {
        if (_driveAccessToken) return _driveAccessToken;
        if (interactive) {
            await this.connect();
            return _driveAccessToken;
        }
        return null;
    },
    async disconnect() {
        _driveAccessToken = null;
        _driveUser = null;
        _driveFolderId = null;
        _driveBackupsCache = [];
        _driveLastError = '';
        if (oauthAuth) {
            await signOut(oauthAuth);
        }
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi('Koneksi Google Drive telah diputuskan.', 'info');
        }
        if (typeof window.renderGoogleDriveBackupSection === 'function') {
            window.renderGoogleDriveBackupSection();
        }
        if (typeof window._refreshBackupJobsDashboard === 'function') {
            window._refreshBackupJobsDashboard();
        }
    }
};

window.mainstayDriveBackup = {
    FOLDER_NAME: 'Mainstay_POS_Backups',

    async _driveFetch(url, options = {}, { interactive = false } = {}) {
        const token = await window.googleDriveAuth.ensureValidToken({ interactive });
        if (!token) {
            throw new Error('Sesi Google Drive belum aktif. Silakan klik "Sign in with Google".');
        }
        const headers = new Headers(options.headers || {});
        headers.set('Authorization', `Bearer ${token}`);
        const res = await fetch(url, { ...options, headers });
        if (res.status === 401) {
            window.googleDriveAuth.clearToken();
            _driveLastError = 'Sesi token Google Drive kedaluwarsa. Klik hubungkan ulang.';
            if (typeof window.renderGoogleDriveBackupSection === 'function') {
                window.renderGoogleDriveBackupSection();
            }
            throw new Error('Sesi token Google Drive kedaluwarsa (401). Silakan masuk ulang.');
        }
        return res;
    },

    async ensureBackupFolder({ interactive = false } = {}) {
        if (_driveFolderId) return _driveFolderId;
        const q = encodeURIComponent(`name='${this.FOLDER_NAME}' and mimeType='application/vnd.google-apps.folder' and trashed=false`);
        const searchRes = await this._driveFetch(
            `https://www.googleapis.com/drive/v3/files?q=${q}&fields=files(id,name)&pageSize=5`,
            { method: 'GET' },
            { interactive }
        );
        if (!searchRes.ok) {
            const errText = await searchRes.text();
            throw new Error(`Gagal mencari folder Drive: ${searchRes.status} ${errText}`);
        }
        const searchJson = await searchRes.json();
        if (Array.isArray(searchJson.files) && searchJson.files.length > 0) {
            _driveFolderId = searchJson.files[0].id;
            return _driveFolderId;
        }
        const createRes = await this._driveFetch(
            'https://www.googleapis.com/drive/v3/files?fields=id,name',
            {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    name: this.FOLDER_NAME,
                    mimeType: 'application/vnd.google-apps.folder'
                })
            },
            { interactive }
        );
        if (!createRes.ok) {
            const errText = await createRes.text();
            throw new Error(`Gagal membuat folder Drive: ${createRes.status} ${errText}`);
        }
        const created = await createRes.json();
        _driveFolderId = created.id;
        return _driveFolderId;
    },

    async uploadBackupJson(filename, jsonString, { interactive = true } = {}) {
        _driveSyncInProgress = true;
        if (typeof window.renderGoogleDriveBackupSection === 'function') window.renderGoogleDriveBackupSection();
        if (typeof window._refreshBackupJobsDashboard === 'function') window._refreshBackupJobsDashboard();
        try {
            const folderId = await this.ensureBackupFolder({ interactive });
            const metadata = {
                name: filename,
                mimeType: 'application/json',
                parents: [folderId]
            };
            const boundary = `mainstay_bkp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
            const body =
                `--${boundary}\r\n` +
                `Content-Type: application/json; charset=UTF-8\r\n\r\n` +
                `${JSON.stringify(metadata)}\r\n` +
                `--${boundary}\r\n` +
                `Content-Type: application/json; charset=UTF-8\r\n\r\n` +
                `${jsonString}\r\n` +
                `--${boundary}--`;

            const res = await this._driveFetch(
                'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,size,createdTime,webViewLink',
                {
                    method: 'POST',
                    headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },
                    body
                },
                { interactive }
            );
            if (!res.ok) {
                const errText = await res.text();
                throw new Error(`Gagal upload ke Google Drive: ${res.status} ${errText}`);
            }
            const uploaded = await res.json();
            _driveLastError = '';
            window.mainstayBackupEngine?.clearDriveFailure?.();
            await this.listBackups({ force: true }).catch(() => {});
            return uploaded;
        } catch (err) {
            _driveLastError = err.message || 'Gagal mengunggah ke Google Drive.';
            throw err;
        } finally {
            _driveSyncInProgress = false;
            if (typeof window.renderGoogleDriveBackupSection === 'function') window.renderGoogleDriveBackupSection();
            if (typeof window._refreshBackupJobsDashboard === 'function') window._refreshBackupJobsDashboard();
        }
    },

    async listBackups({ interactive = false, force = false } = {}) {
        if (!window.googleDriveAuth.getAccessToken()) {
            if (!interactive) return _driveBackupsCache;
        }
        if (_driveLoadingState && !force) return _driveBackupsCache;
        _driveLoadingState = true;
        _driveLastError = '';
        if (typeof window.renderGoogleDriveBackupSection === 'function') {
            window.renderGoogleDriveBackupSection();
        }
        try {
            const folderId = await this.ensureBackupFolder({ interactive });
            const q = encodeURIComponent(`'${folderId}' in parents and trashed=false`);
            const res = await this._driveFetch(
                `https://www.googleapis.com/drive/v3/files?q=${q}&orderBy=createdTime desc&pageSize=15&fields=files(id,name,size,createdTime,webViewLink)`,
                { method: 'GET' },
                { interactive }
            );
            if (!res.ok) {
                const errText = await res.text();
                throw new Error(`Gagal memuat daftar Drive: ${res.status} ${errText}`);
            }
            const json = await res.json();
            _driveBackupsCache = Array.isArray(json.files) ? json.files : [];
            return _driveBackupsCache;
        } catch (err) {
            _driveLastError = err.message || 'Gagal membaca file Google Drive.';
            return _driveBackupsCache;
        } finally {
            _driveLoadingState = false;
            if (typeof window.renderGoogleDriveBackupSection === 'function') {
                window.renderGoogleDriveBackupSection();
            }
        }
    },

    async downloadBackupFile(fileId, fileName = 'Mainstay_Drive_Backup.json') {
        try {
            const res = await this._driveFetch(
                `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media`,
                { method: 'GET' },
                { interactive: true }
            );
            if (!res.ok) {
                throw new Error(`Gagal mengunduh file (${res.status})`);
            }
            const text = await res.text();
            window.mainstayBackupEngine._triggerDownloadFile(fileName, text, 'application/json;charset=utf-8');
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`File "${fileName}" berhasil diunduh dari Google Drive.`, 'success');
            }
        } catch (err) {
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(err.message || 'Gagal mengunduh dari Google Drive.', 'error');
            }
        }
    },

    deleteBackupFile(fileId, fileName = 'file backup ini') {
        if (typeof window.tampilkanKonfirmasiGlobal !== 'function') return;
        window.tampilkanKonfirmasiGlobal({
            title: 'Hapus Backup di Google Drive?',
            message: `File "${fileName}" akan dihapus permanen dari folder Mainstay_POS_Backups di Google Drive Anda.`,
            subtext: 'Pastikan Anda masih menyimpan salinan lain jika masih dibutuhkan.',
            icon: 'fa-trash-can',
            confirmText: 'Ya, Hapus Permanen',
            cancelText: 'Batal',
            isDanger: true,
            onConfirm: async () => {
                try {
                    const res = await this._driveFetch(
                        `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}`,
                        { method: 'DELETE' },
                        { interactive: true }
                    );
                    if (!res.ok && res.status !== 204) {
                        throw new Error(`Gagal menghapus file (${res.status})`);
                    }
                    _driveBackupsCache = _driveBackupsCache.filter(f => f.id !== fileId);
                    if (typeof window.renderGoogleDriveBackupSection === 'function') {
                        window.renderGoogleDriveBackupSection();
                    }
                    if (typeof window.tampilkanNotifikasi === 'function') {
                        window.tampilkanNotifikasi(`File "${fileName}" dihapus dari Google Drive.`, 'success');
                    }
                } catch (err) {
                    if (typeof window.tampilkanNotifikasi === 'function') {
                        window.tampilkanNotifikasi(err.message || 'Gagal menghapus file Google Drive.', 'error');
                    }
                }
            }
        });
    }
};

const GLOBAL_ROOT_NODES = new Set(['branches', 'master_owner']);
const ref = (database, rawPath = '') => {
    const bid = window.ACTIVE_BRANCH_ID || 'pusat';
    const clean = String(rawPath || '').replace(/^\/+|\/+$/g, '');
    if (!clean) {
        return bid === 'pusat' ? _firebaseRef(database) : _firebaseRef(database, `branch_data/${bid}`);
    }
    const rootNode = clean.split('/')[0];
    if (bid === 'pusat' || GLOBAL_ROOT_NODES.has(rootNode) || clean.startsWith('branch_data/')) {
        return _firebaseRef(database, clean);
    }
    return _firebaseRef(database, `branch_data/${bid}/${clean}`);
};
window._rawFirebaseRef = _firebaseRef;
window.branchDbRef = ref;

// ============================================================================
// FORMATTER METODE PEMBAYARAN SERAGAM (STANDAR: "Tunai")
// ============================================================================
window.formatMetodeBayar = (m) => {
    if (!m) return 'Tunai';
    let str = String(m).trim();
    // Standarkan penyebutan Tunai & bersihkan embel-embel
    str = str.replace(/Cash/gi, 'Tunai')
             .replace(/\(Kasir\)/gi, '')
             .replace(/Tunai\s+Kasir/gi, 'Tunai')
             .trim();
    if (str.toLowerCase() === 'cash' || str.toLowerCase() === 'tunai (kasir)' || str.toLowerCase() === 'tunai kasir' || str === '') {
        return 'Tunai';
    }
    // Standarkan penamaan Pre-Order
    if (str.toLowerCase() === 'preorder' || str.toLowerCase() === 'pre-order') {
        return 'Pre-Order';
    }
    if (/^preorder\s*\((.*?)\)$/i.test(str)) {
        const sub = str.replace(/^preorder\s*\((.*?)\)$/i, '$1').trim();
        const cleanSub = sub.toLowerCase() === 'cash' ? 'Tunai' : sub;
        return `${cleanSub} (Pre-Order)`;
    }
    return str;
};

// ============================================================================
// GENERATOR DRAFT WHATSAPP BUKTI PEMESANAN PRE-ORDER RESMI
// ============================================================================
window.generatePreOrderWhatsAppDraft = (ord) => {
    if (!ord) return '';
    const s = window.storeSettings || window.globalStoreSettings || {};
    const storeTitle = s.store_title || s.receipt_store_name || 'Mainstay Drink';
    const storeAddress = s.footer_address || '';
    const gmapsUrl = s.footer_maps_url || 'https://maps.google.com/?q=-6.9412973,110.5089463';

    const orderCode = String(ord.orderId || ord.id || '-').toUpperCase();
    const custName = ord.customerName || ord.namaPelanggan || ord.name || 'Pelanggan';
    const custPhone = ord.customerPhone || ord.nomorWa || ord.wa || ord.phone || '-';

    // Waktu & Tanggal Pemesanan
    let orderTimeStr = ord.waktu || '';
    let orderDateStr = ord.tanggal || '';
    if (!orderDateStr && ord.timestamp) {
        const d = new Date(ord.timestamp);
        orderDateStr = d.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' });
        orderTimeStr = d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }).replace(/:/g, '.');
    }
    if (!orderDateStr) orderDateStr = new Date().toLocaleDateString('id-ID');
    if (!orderTimeStr) orderTimeStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }).replace(/:/g, '.');

    // Jadwal Pengambilan Pre-Order
    const pickupDate = ord.pickupDate || ord.preOrderDate || '-';
    const pickupTime = ord.pickupTime || ord.preOrderTime || '-';

    // Rincian Menu, Topping, Ukuran, Varian
    const items = Array.isArray(ord.items)
        ? ord.items.filter(Boolean)
        : (ord.items && typeof ord.items === 'object' ? Object.values(ord.items).filter(Boolean) : []);
    let rincianMenu = '';
    items.forEach((it, idx) => {
        const qty = Number(it.qty) || 1;
        const name = String(it.name || it.nama || 'Menu').trim();
        const price = Number(it.price || it.harga || 0);
        const subtotal = Number(it.total) || (price * qty);

        const noteParts = [];
        const rawNote = String(it.notes || it.varian || '').trim();
        if (rawNote && rawNote.toLowerCase() !== 'normal' && rawNote.toLowerCase() !== 'normal ice') {
            noteParts.push(rawNote);
        }
        if (Array.isArray(it.toppings) && it.toppings.length > 0) {
            it.toppings.forEach(t => {
                const ct = (typeof t === 'object' && t !== null) ? String(t.name || t.nama || '').trim() : String(t || '').trim();
                if (ct && !noteParts.some(p => p.toLowerCase() === ct.toLowerCase())) {
                    noteParts.push(ct);
                }
            });
        }
        const notes = noteParts.length > 0 ? `\n    └ _Pilihan/Topping: ${noteParts.join(' + ')}_` : '';

        const subtotalFormatted = typeof window.formatRupiah === 'function' ? window.formatRupiah(subtotal) : 'Rp ' + subtotal.toLocaleString('id-ID');
        rincianMenu += `${idx + 1}. *${qty}x ${name}* (${subtotalFormatted})${notes}\n`;
    });
    if (!rincianMenu) rincianMenu = '- Tidak ada rincian item -\n';

    const totalAmount = Number(ord.totalAmount || ord.total || 0);
    const diskonNominal = Number(ord.diskonVoucher || ord.diskonNominal || ord.discount || 0);
    const voucherName = ord.voucher || ord.kodeVoucher || ord.namaDiskon || 'Promo';
    const subtotalKotor = Number(ord.subtotal || (totalAmount + diskonNominal));
    const fmtRp = (v) => typeof window.formatRupiah === 'function' ? window.formatRupiah(v) : 'Rp ' + Number(v || 0).toLocaleString('id-ID');
    const totalFormatted = fmtRp(totalAmount);
    const diskonLineWA = diskonNominal > 0
        ? `Subtotal       : ${fmtRp(subtotalKotor)}\nDiskon (${voucherName}) : -${fmtRp(diskonNominal)}\n`
        : '';
    const subPayRaw = ord.preOrderSubPay || ord.paymentMethod || ord.metode || 'Tunai';
    const subPay = window.formatMetodeBayar(subPayRaw);
    const isQris = /qris|transfer|bank|gopay|ovo|dana|shopee/i.test(subPayRaw);

    let infoInstruksiBayar = '';
    if (isQris) {
        infoInstruksiBayar = `\n💳 *INSTRUKSI PEMBAYARAN QRIS:*\nMohon untuk mengirimkan *foto / screenshot bukti transfer / QRIS* Kakak di sini ya Kak, agar pesanan segera kami verifikasi dan siapkan. Terima kasih banyak! 🙏\n`;
    } else {
        infoInstruksiBayar = `\n💵 *PEMBAYARAN TUNAI:*\nPembayaran dilakukan secara tunai di kasir saat pengambilan pesanan. Terima kasih banyak! 🙏\n`;
    }

    const alamatLine = storeAddress ? `📌 *Alamat*     : ${storeAddress}\n` : '';

    return `🧾 *BUKTI PEMESANAN PRE-ORDER RESMI*
*${storeTitle.toUpperCase()}*
----------------------------------------
No. Pesanan   : *${orderCode}*
Nama Pemesan  : *${custName}*
No. WhatsApp  : ${custPhone}
Waktu Pesan   : ${orderDateStr} • Pkl ${orderTimeStr} WIB

⏰ *JADWAL PENGAMBILAN PESANAN:*
📅 *Tanggal*    : *${pickupDate}*
⏰ *Jam Ambil*  : *Pkl ${pickupTime} WIB*
📍 *Lokasi Outlet*: ${storeTitle}
${alamatLine}----------------------------------------
📋 *RINCIAN MENU DIPESAN:*
${rincianMenu}----------------------------------------
${diskonLineWA}*TOTAL TAGIHAN : ${totalFormatted}*
Metode Bayar   : *${subPay}*
${infoInstruksiBayar}
⚠️ *TATA CARA PENGAMBILAN:*
1. Pesan WhatsApp ini adalah bukti pemesanan resmi saat pengambilan pesanan di outlet.
2. Tunjukkan bukti chat ini kepada Barista / Kasir di outlet saat tiba.
3. Minuman Anda akan disiapkan segar sesuai jadwal jam pengambilan.

🗺️ *Petunjuk Arah Google Maps:*
${gmapsUrl}

Terima kasih banyak telah memesan di *${storeTitle}*! Ditunggu kedatangannya ya Kak 🙏✨`;
};

// Sanitasi mendalam payload sebelum dikirim ke Firebase RTDB (menghindari crash karena nilai undefined)
window.sanitizeForFirebase = (val) => {
    if (val === undefined) return null;
    if (val === null || typeof val !== 'object') return val;
    if (Array.isArray(val)) {
        return val.map(item => window.sanitizeForFirebase(item));
    }
    const clean = {};
    for (const k of Object.keys(val)) {
        const v = val[k];
        if (v !== undefined) {
            clean[k] = window.sanitizeForFirebase(v);
        }
    }
    return clean;
};

// ============================================================================
// DEEP INDEXEDDB PERSISTENCE LAYER FOR OFFLINE POS & CLIENT ERROR LOGS
// ============================================================================
window._branchIdbStaffCache = window._branchIdbStaffCache || {};

window.mainstayIndexedDB = {
    dbName: 'MainstayPOS_DB',
    dbVersion: 2,
    _dbInstance: null,

    async getDB() {
        if (this._dbInstance) return this._dbInstance;
        return new Promise((resolve, reject) => {
            if (typeof window === 'undefined' || !('indexedDB' in window)) {
                return reject(new Error('IndexedDB tidak didukung pada browser ini'));
            }
            const req = window.indexedDB.open(this.dbName, this.dbVersion);
            req.onupgradeneeded = (event) => {
                const db = event.target.result;
                const tx = event.target.transaction;
                if (!db.objectStoreNames.contains('pending_transactions')) {
                    const st = db.createObjectStore('pending_transactions', { keyPath: 'id' });
                    st.createIndex('timestamp', 'timestamp', { unique: false });
                    st.createIndex('type', 'type', { unique: false });
                    st.createIndex('status', 'status', { unique: false });
                    st.createIndex('branchId', 'branchId', { unique: false });
                } else if (tx) {
                    const st = tx.objectStore('pending_transactions');
                    if (!st.indexNames.contains('branchId')) {
                        st.createIndex('branchId', 'branchId', { unique: false });
                    }
                }
                if (!db.objectStoreNames.contains('offline_orders')) {
                    const st = db.createObjectStore('offline_orders', { keyPath: 'id' });
                    st.createIndex('timestamp', 'timestamp', { unique: false });
                    st.createIndex('status', 'status', { unique: false });
                    st.createIndex('branchId', 'branchId', { unique: false });
                } else if (tx) {
                    const st = tx.objectStore('offline_orders');
                    if (!st.indexNames.contains('branchId')) {
                        st.createIndex('branchId', 'branchId', { unique: false });
                    }
                }
                if (!db.objectStoreNames.contains('client_error_logs')) {
                    const st = db.createObjectStore('client_error_logs', { keyPath: 'id' });
                    st.createIndex('timestamp', 'timestamp', { unique: false });
                    st.createIndex('synced', 'synced', { unique: false });
                }
                if (!db.objectStoreNames.contains('staff_records')) {
                    const st = db.createObjectStore('staff_records', { keyPath: 'compoundKey' });
                    st.createIndex('branchId', 'branchId', { unique: false });
                    st.createIndex('staffKey', 'staffKey', { unique: false });
                    st.createIndex('pin', 'pin', { unique: false });
                } else if (tx) {
                    const st = tx.objectStore('staff_records');
                    if (!st.indexNames.contains('branchId')) st.createIndex('branchId', 'branchId', { unique: false });
                    if (!st.indexNames.contains('staffKey')) st.createIndex('staffKey', 'staffKey', { unique: false });
                    if (!st.indexNames.contains('pin')) st.createIndex('pin', 'pin', { unique: false });
                }
            };
            req.onsuccess = (event) => {
                this._dbInstance = event.target.result;
                resolve(this._dbInstance);
            };
            req.onerror = (event) => {
                reject(event.target.error || new Error('Gagal membuka IndexedDB'));
            };
        });
    },

    async putItem(storeName, item) {
        try {
            const db = await this.getDB();
            return new Promise((resolve, reject) => {
                const tx = db.transaction(storeName, 'readwrite');
                const store = tx.objectStore(storeName);
                const req = store.put(item);
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => reject(req.error);
            });
        } catch (e) {
            console.warn(`[IndexedDB] putItem (${storeName}) error:`, e);
            return null;
        }
    },

    async getAllItems(storeName) {
        try {
            const db = await this.getDB();
            return new Promise((resolve, reject) => {
                const tx = db.transaction(storeName, 'readonly');
                const store = tx.objectStore(storeName);
                const req = store.getAll();
                req.onsuccess = () => resolve(req.result || []);
                req.onerror = () => reject(req.error);
            });
        } catch (e) {
            console.warn(`[IndexedDB] getAllItems (${storeName}) error:`, e);
            return [];
        }
    },

    async deleteItem(storeName, id) {
        try {
            const db = await this.getDB();
            return new Promise((resolve, reject) => {
                const tx = db.transaction(storeName, 'readwrite');
                const store = tx.objectStore(storeName);
                const req = store.delete(id);
                req.onsuccess = () => resolve(true);
                req.onerror = () => reject(req.error);
            });
        } catch (e) {
            console.warn(`[IndexedDB] deleteItem (${storeName}) error:`, e);
            return false;
        }
    },

    async getBranchStaff(branchId = (window.ACTIVE_BRANCH_ID || 'pusat')) {
        const bid = String(branchId || 'pusat');
        try {
            const db = await this.getDB();
            const records = await new Promise((resolve, reject) => {
                const tx = db.transaction('staff_records', 'readonly');
                const store = tx.objectStore('staff_records');
                const idx = store.index('branchId');
                const req = idx.getAll(bid);
                req.onsuccess = () => resolve(req.result || []);
                req.onerror = () => reject(req.error);
            });
            const map = {};
            records.forEach(rec => {
                if (rec && rec.staffKey) {
                    const clean = { ...rec };
                    delete clean.compoundKey;
                    map[rec.staffKey] = clean;
                }
            });
            window._branchIdbStaffCache[bid] = map;
            return map;
        } catch (e) {
            console.warn('[IndexedDB] getBranchStaff error:', e);
            return window._branchIdbStaffCache[bid] || {};
        }
    },

    async syncBranchStaff(branchId = (window.ACTIVE_BRANCH_ID || 'pusat'), staffObj = {}) {
        const bid = String(branchId || 'pusat');
        const safeMap = (staffObj && typeof staffObj === 'object') ? staffObj : {};
        const cacheCopy = {};
        Object.entries(safeMap).forEach(([k, v]) => {
            if (v && typeof v === 'object') {
                cacheCopy[k] = { ...v, staffKey: k, branchId: bid, pin: String(v.pin || '') };
            }
        });
        window._branchIdbStaffCache[bid] = cacheCopy;
        try {
            const db = await this.getDB();
            await new Promise((resolve, reject) => {
                const tx = db.transaction('staff_records', 'readwrite');
                const store = tx.objectStore('staff_records');
                const idx = store.index('branchId');
                const keysReq = idx.getAllKeys(bid);
                keysReq.onsuccess = () => {
                    const existingKeys = keysReq.result || [];
                    existingKeys.forEach(ck => store.delete(ck));
                    Object.entries(cacheCopy).forEach(([k, v]) => {
                        store.put({
                            ...v,
                            compoundKey: `${bid}::${k}`,
                            branchId: bid,
                            staffKey: k,
                            pin: String(v.pin || ''),
                            syncedAt: Date.now()
                        });
                    });
                };
                tx.oncomplete = () => resolve(true);
                tx.onerror = () => reject(tx.error);
            });
            return cacheCopy;
        } catch (e) {
            console.warn('[IndexedDB] syncBranchStaff error:', e);
            return cacheCopy;
        }
    },

    async upsertBranchStaff(branchId = (window.ACTIVE_BRANCH_ID || 'pusat'), staffKey, staffData) {
        const bid = String(branchId || 'pusat');
        if (!staffKey || !staffData) return null;
        const record = {
            ...staffData,
            compoundKey: `${bid}::${staffKey}`,
            branchId: bid,
            staffKey: String(staffKey),
            pin: String(staffData.pin || ''),
            syncedAt: Date.now()
        };
        window._branchIdbStaffCache[bid] = window._branchIdbStaffCache[bid] || {};
        window._branchIdbStaffCache[bid][staffKey] = { ...staffData, staffKey: String(staffKey), branchId: bid, pin: String(staffData.pin || '') };
        await this.putItem('staff_records', record);
        return record;
    },

    async deleteBranchStaff(branchId = (window.ACTIVE_BRANCH_ID || 'pusat'), staffKey) {
        const bid = String(branchId || 'pusat');
        if (!staffKey) return false;
        if (window._branchIdbStaffCache[bid]) {
            delete window._branchIdbStaffCache[bid][staffKey];
        }
        return this.deleteItem('staff_records', `${bid}::${staffKey}`);
    }
};

window.getEffectiveBranchStaffMap = () => {
    const bid = String(window.ACTIVE_BRANCH_ID || 'pusat');
    const rtdbStaff = (typeof globalStaff === 'object' && globalStaff) ? globalStaff : {};
    const idbStaff = (window._branchIdbStaffCache && window._branchIdbStaffCache[bid]) ? window._branchIdbStaffCache[bid] : {};
    if (window._staffLoaded) {
        return { ...idbStaff, ...rtdbStaff };
    }
    return { ...rtdbStaff, ...idbStaff };
};

if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.getBranchStaff === 'function') {
    window.mainstayIndexedDB.getBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat').catch(() => {});
}

// ============================================================================
// CLIENT-SIDE ERROR LOGGER & AUTO-REPORTER KE SERVER
// ============================================================================
window.clientErrorLogger = {
    async logError(errorType, message, detail = {}) {
        const errorItem = {
            id: 'ERR_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
            type: errorType || 'CLIENT_RUNTIME_ERROR',
            message: typeof message === 'string' ? message : (message?.message || JSON.stringify(message)),
            stack: detail?.stack || (message instanceof Error ? message.stack : null),
            detail: detail,
            userAgent: navigator.userAgent,
            online: navigator.onLine,
            timestamp: Date.now(),
            dateStr: new Date().toISOString(),
            synced: false
        };

        if (window.mainstayIndexedDB) {
            window.mainstayIndexedDB.putItem('client_error_logs', errorItem).catch(() => {});
        }

        try {
            const raw = localStorage.getItem('mainstay_client_error_logs');
            const arr = raw ? JSON.parse(raw) : [];
            arr.unshift(errorItem);
            if (arr.length > 50) arr.length = 50;
            localStorage.setItem('mainstay_client_error_logs', JSON.stringify(arr));
        } catch(e) {}

        if (navigator.onLine) {
            window.clientErrorLogger.uploadLogsToServer().catch(() => {});
        }

        return errorItem;
    },

    async uploadLogsToServer() {
        if (!navigator.onLine) return;
        try {
            let logs = [];
            if (window.mainstayIndexedDB) {
                logs = await window.mainstayIndexedDB.getAllItems('client_error_logs');
            }
            if (!logs || logs.length === 0) {
                try {
                    logs = JSON.parse(localStorage.getItem('mainstay_client_error_logs') || '[]');
                } catch(e) {}
            }

            const unSynced = logs.filter(l => !l.synced);
            if (unSynced.length === 0) return;

            for (const log of unSynced) {
                try {
                    if (typeof db !== 'undefined' && typeof set === 'function' && typeof ref === 'function') {
                        await set(ref(db, `client_error_logs/${log.id}`), window.sanitizeForFirebase({
                            ...log,
                            synced: true,
                            uploadedAt: new Date().toISOString()
                        }));
                    }
                    if (window.mainstayIndexedDB) {
                        await window.mainstayIndexedDB.deleteItem('client_error_logs', log.id);
                    }
                } catch(uploadErr) {
                    console.warn('[Error Logger] Gagal upload log error:', uploadErr);
                }
            }

            try {
                localStorage.removeItem('mainstay_client_error_logs');
            } catch(e) {}
        } catch(e) {
            console.warn('[Error Logger] uploadLogsToServer error:', e);
        }
    }
};

window.addEventListener('error', (event) => {
    if (event.message && (event.message.includes('WebSocket') || event.message.includes('vite') || event.message.includes('HMR'))) return;
    window.clientErrorLogger.logError('UNCAUGHT_EXCEPTION', event.message, {
        filename: event.filename,
        lineno: event.lineno,
        colno: event.colno,
        stack: event.error ? event.error.stack : null
    });
});

window.addEventListener('unhandledrejection', (event) => {
    const reason = event.reason;
    const msg = (reason && reason.message) ? reason.message : String(reason);
    if (msg.includes('WebSocket') || msg.includes('vite')) return;
    window.clientErrorLogger.logError('UNHANDLED_PROMISE_REJECTION', msg, {
        stack: reason && reason.stack ? reason.stack : null
    });
});

// ============================================================================
// OFFLINE POS & CLOUD SYNC ENGINE (SERVICE WORKER + INDEXEDDB BACKED)
// ============================================================================
window.posSyncEngine = {
    isSyncing: false,
    
    getPendingQueue: () => {
        try {
            const raw = localStorage.getItem('mainstay_pos_sync_queue');
            const arr = raw ? JSON.parse(raw) : [];
            return Array.isArray(arr) ? arr : [];
        } catch(e) {
            return [];
        }
    },
    
    savePendingQueue: (queue) => {
        try {
            localStorage.setItem('mainstay_pos_sync_queue', JSON.stringify(queue || []));
        } catch(e) {}
        if (typeof window.posSyncEngine.updateSyncUI === 'function') {
            window.posSyncEngine.updateSyncUI();
        }
    },
    
    enqueue: (type, payload, extraData = {}) => {
        const queue = window.posSyncEngine.getPendingQueue();
        const id = payload?.orderId || payload?.id || ('SYNC_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4));
        const activeBranchId = window.ACTIVE_BRANCH_ID || 'pusat';
        
        const existingIdx = queue.findIndex(item => item.id === id);
        const queueItem = {
            id: id,
            branchId: activeBranchId,
            type: type || 'order',
            payload: payload,
            extra: extraData,
            timestamp: Date.now(),
            retries: 0,
            status: 'pending'
        };
        
        if (existingIdx >= 0) {
            queue[existingIdx] = queueItem;
        } else {
            queue.push(queueItem);
        }
        
        window.posSyncEngine.savePendingQueue(queue);
        
        // Simpan mendalam ke IndexedDB object store (terisolasi per cabang)
        if (window.mainstayIndexedDB) {
            window.mainstayIndexedDB.putItem('pending_transactions', queueItem).catch(() => {});
            if (type === 'order' && payload) {
                const normOrder = { id: id, orderId: id, branchId: activeBranchId, ...payload };
                window.mainstayIndexedDB.putItem('offline_orders', normOrder).catch(() => {});
            }
        }

        console.log(`[POS Sync Engine] Transaksi ${id} (${type}) [branch:${activeBranchId}] berhasil dimasukkan ke IndexedDB & antrean offline lokal.`);
        
        // Daftarkan ke background sync service worker jika didukung
        if (window.mainstaySWRegistration && 'sync' in window.mainstaySWRegistration) {
            window.mainstaySWRegistration.sync.register('sync-pos-orders').catch(() => {});
        }
        
        return queueItem;
    },
    
    syncAllPending: async (isManualClick = false) => {
        if (window.posSyncEngine.isSyncing) {
            console.log("[POS Sync Engine] Proses sinkronisasi sedang berjalan...");
            return;
        }
        
        const isOnline = navigator.onLine;
        if (!isOnline) {
            if (isManualClick) {
                alert("Perangkat Anda saat ini masih offline. Transaksi offline tersimpan aman di memori lokal (IndexedDB) dan akan otomatis diunggah saat terhubung internet.");
            }
            window.posSyncEngine.updateSyncUI();
            return;
        }
        
        const activeBranchId = window.ACTIVE_BRANCH_ID || 'pusat';
        let queue = window.posSyncEngine.getPendingQueue().filter(q => !q.branchId || q.branchId === activeBranchId);

        // Pulihkan antrean dari IndexedDB khusus cabang aktif
        if (window.mainstayIndexedDB) {
            try {
                const idbPending = await window.mainstayIndexedDB.getAllItems('pending_transactions');
                if (Array.isArray(idbPending) && idbPending.length > 0) {
                    const knownIds = new Set(queue.map(q => q.id));
                    let added = false;
                    idbPending.forEach(it => {
                        const itemBranch = it?.branchId || 'pusat';
                        if (it && it.id && itemBranch === activeBranchId && !knownIds.has(it.id)) {
                            queue.push(it);
                            knownIds.add(it.id);
                            added = true;
                        }
                    });
                    if (added) {
                        window.posSyncEngine.savePendingQueue(queue);
                    }
                }
            } catch(e) {}
        }

        if (queue.length === 0) {
            if (isManualClick) {
                alert("Semua data POS telah tersinkronisasi penuh dengan server cloud!");
            }
            window.posSyncEngine.updateSyncUI();
            // Unggah log error tersimpan bila ada
            if (window.clientErrorLogger) {
                window.clientErrorLogger.uploadLogsToServer().catch(() => {});
            }
            return;
        }
        
        window.posSyncEngine.isSyncing = true;
        window.posSyncEngine.updateSyncUI();

        // Tampilkan Banner Proaktif Sinkronisasi Cloud
        const totalItems = queue.length;
        window.posSyncEngine.showProactiveBanner(`🌐 Internet Terhubung Kembali!`, `Menyinkronkan ${totalItems} data offline (pesanan, absensi, laci kas) ke server cloud...`, 'syncing');
        
        let syncedCount = 0;
        let remainingQueue = [];
        let currentIndex = 0;
        
        for (const item of queue) {
            currentIndex++;
            try {
                window.posSyncEngine.showProactiveBanner(`🌐 Sinkronisasi Cloud Berjalan...`, `Mengunggah data (${currentIndex}/${totalItems}): ${item.type === 'order' ? 'Pesanan #' + (item.id || '') : (item.type === 'attendance' ? 'Absensi Staf' : (item.type === 'cashflow' ? 'Arus Kas Laci' : 'Poin Member'))}`, 'syncing');

                if (item.type === 'order') {
                    // Ambil status dan data pesanan paling mutakhir dari memori atau penyimpanan offline lokal
                    let latestOrderState = (typeof globalOrders === 'object' && globalOrders && (globalOrders[item.id] || (item.payload && globalOrders[item.payload.orderId]))) || null;
                    if (!latestOrderState) {
                        try {
                            const savedOffline = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
                            latestOrderState = savedOffline.find(o => o.orderId === item.id || o.id === item.id);
                        } catch(e) {}
                    }

                    const targetStatus = (latestOrderState && latestOrderState.status) ? latestOrderState.status : (item.payload && item.payload.status ? item.payload.status : 'pending');
                    const targetItems = (latestOrderState && Array.isArray(latestOrderState.items)) ? latestOrderState.items : (item.payload && item.payload.items ? item.payload.items : []);
                    const targetTotal = (latestOrderState && latestOrderState.total !== undefined) ? latestOrderState.total : (item.payload ? item.payload.total : 0);
                    const targetSubtotal = (latestOrderState && latestOrderState.subtotal !== undefined) ? latestOrderState.subtotal : (item.payload ? item.payload.subtotal : targetTotal);

                    const orderData = { 
                        ...(item.payload || {}),
                        ...(latestOrderState || {}),
                        status: targetStatus,
                        items: targetItems,
                        total: targetTotal,
                        subtotal: targetSubtotal,
                        isOffline: false, 
                        synced: true, 
                        syncedAt: new Date().toISOString() 
                    };
                    
                    // 1. Simpan ke Firebase Realtime Database (/orders) dengan ID unik konsisten (BUKAN push duplikat)
                    await set(ref(db, `orders/${item.id}`), window.sanitizeForFirebase(orderData));
                    
                    // 2. Simpan ke node transaksi dengan ID konsisten
                    await set(ref(db, `transaksi/${item.id}`), window.sanitizeForFirebase(orderData));
                    
                    // 3. Update member atau non-member jika ada di extra
                    if (item.extra && item.extra.memberPhone && item.extra.memberPayload) {
                        await update(ref(db, `members/${item.extra.memberPhone}`), window.sanitizeForFirebase(item.extra.memberPayload));
                        if (window.cachedMembers) {
                            window.cachedMembers[item.extra.memberPhone] = item.extra.memberPayload;
                        }
                        if (window.cachedNonMembers && window.cachedNonMembers[item.extra.memberPhone]) {
                            await remove(ref(db, `non_members/${item.extra.memberPhone}`)).catch(() => {});
                            delete window.cachedNonMembers[item.extra.memberPhone];
                        }
                    } else if (item.extra && item.extra.nonMemberPhone && item.extra.nonMemberPayload) {
                        const alreadyMem = window.cachedMembers && window.cachedMembers[item.extra.nonMemberPhone];
                        if (!alreadyMem) {
                            await update(ref(db, `non_members/${item.extra.nonMemberPhone}`), window.sanitizeForFirebase(item.extra.nonMemberPayload));
                            if (!window.cachedNonMembers) window.cachedNonMembers = {};
                            window.cachedNonMembers[item.extra.nonMemberPhone] = item.extra.nonMemberPayload;
                            globalNonMembers = window.cachedNonMembers;
                        }
                    }
                    
                    // 4. Update status synced di mainstay_offline_orders
                    try {
                        let savedOffline = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
                        if (Array.isArray(savedOffline)) {
                            savedOffline = savedOffline.map(o => (o.orderId === item.id || o.id === item.id) ? { ...o, ...orderData, synced: true, isOffline: false } : o);
                            localStorage.setItem('mainstay_offline_orders', JSON.stringify(savedOffline));
                        }
                    } catch(e) {}
                    
                    // Update juga di memori runtime agar sinkron instan
                    if (typeof globalOrders === 'object' && globalOrders) {
                        globalOrders[item.id] = orderData;
                    }

                    // Hapus item dari IndexedDB setelah sukses diunggah ke Firebase
                    if (window.mainstayIndexedDB) {
                        try {
                            await window.mainstayIndexedDB.deleteItem('pending_transactions', item.id);
                        } catch(e) {}
                    }

                    syncedCount++;
                } else if (item.type === 'member') {
                    if (item.payload && item.payload.phone) {
                        await update(ref(db, `members/${item.payload.phone}`), window.sanitizeForFirebase(item.payload));
                        if (window.mainstayIndexedDB) {
                            try {
                                await window.mainstayIndexedDB.deleteItem('pending_transactions', item.id);
                            } catch(e) {}
                        }
                        syncedCount++;
                    }
                } else if (item.type === 'attendance') {
                    if (item.payload) {
                        const tgl = item.payload.tanggal || new Date().toISOString().split('T')[0];
                        const logKey = item.payload.timestamp || Date.now();
                        await set(ref(db, `attendance/${tgl}/${logKey}`), window.sanitizeForFirebase(item.payload));
                        if (window.mainstayIndexedDB) {
                            try {
                                await window.mainstayIndexedDB.deleteItem('pending_transactions', item.id);
                            } catch(e) {}
                        }
                        syncedCount++;
                    }
                } else if (item.type === 'cashflow') {
                    if (item.payload && item.payload.id) {
                        await set(ref(db, `cashflow/${item.payload.id}`), window.sanitizeForFirebase(item.payload));
                        if (item.payload.tipe === 'keluar') {
                            await set(ref(db, `expenses/${item.payload.id}`), window.sanitizeForFirebase({
                                id: item.payload.id,
                                title: `${item.payload.kategori || 'Operasional'}: ${item.payload.keterangan || 'Operasional Laci Kasir'}`,
                                amount: item.payload.nominal,
                                category: item.payload.kategori || 'Operasional',
                                date: item.payload.date,
                                time: item.payload.time,
                                staff: item.payload.staf,
                                source: 'Ruang Kerja Kasir',
                                timestamp: item.payload.timestamp || Date.now()
                            }));
                        }
                        if (window.mainstayIndexedDB) {
                            try {
                                await window.mainstayIndexedDB.deleteItem('pending_transactions', item.id);
                            } catch(e) {}
                        }
                        syncedCount++;
                    }
                }
            } catch (err) {
                console.warn(`[POS Sync Engine] Gagal sinkron item ${item.id}:`, err);
                item.retries = (item.retries || 0) + 1;
                item.lastError = err.message || 'Network error';
                remainingQueue.push(item);
                if (window.clientErrorLogger) {
                    window.clientErrorLogger.logError('OFFLINE_TRANSACTION_SYNC_FAILURE', err.message || 'Gagal sinkron item offline', {
                        itemId: item.id,
                        itemType: item.type,
                        retries: item.retries
                    });
                }
            }
        }
        
        window.posSyncEngine.isSyncing = false;
        window.posSyncEngine.savePendingQueue(remainingQueue);

        // Unggah log error ke server secara otomatis
        if (window.clientErrorLogger) {
            window.clientErrorLogger.uploadLogsToServer().catch(() => {});
        }
        
        if (syncedCount > 0) {
            console.log(`[POS Sync Engine] Berhasil menyinkronkan ${syncedCount} transaksi offline.`);
            if (typeof window.triggerSyncOnlineHaptic === 'function') {
                window.triggerSyncOnlineHaptic();
            }
            if (typeof window.playScannerBeep === 'function') {
                window.playScannerBeep('success');
            }
            
            // Tampilkan Proactive Success Banner
            window.posSyncEngine.showProactiveBanner(
                `✅ Sinkronisasi Cloud Selesai!`,
                `${syncedCount} data offline (pesanan, absensi, laci kas, poin member) berhasil diunggah ke database utama tanpa konflik.`,
                'success'
            );
            
            if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
            if (typeof window.loadOrders === 'function') window.loadOrders();
            if (typeof window.renderTabArusKas === 'function') window.renderTabArusKas();
            if (typeof window.renderTabShift === 'function') window.renderTabShift();
            if (typeof window.renderRiwayatAbsensiHariIni === 'function') window.renderRiwayatAbsensiHariIni();
            if (typeof window.updateLiveCashDrawer === 'function') window.updateLiveCashDrawer();
            if (typeof window.updateOwnerDashboard === 'function') window.updateOwnerDashboard();
        } else if (remainingQueue.length > 0) {
            window.posSyncEngine.showProactiveBanner(
                `⚠️ Sinkronisasi Tertunda Sebagian`,
                `${remainingQueue.length} data belum tersinkronisasi karena kendala jaringan. Akan dicoba ulang otomatis.`,
                'warning'
            );
        } else {
            window.posSyncEngine.hideProactiveBanner();
        }
    },
    
    showProactiveBanner: (title, subtitle, state = 'syncing') => {
        // PERMINTAAN PENGGUNA: Jangan tampilkan notifikasi / banner sinkronisasi ke pelanggan pada tampilan Self-Order
        if (typeof window.isCustomerViewActive === 'function' && window.isCustomerViewActive()) {
            window.posSyncEngine.hideProactiveBanner();
            return;
        }

        let banner = document.getElementById('pos-proactive-sync-banner');
        if (!banner) {
            banner = document.createElement('div');
            banner.id = 'pos-proactive-sync-banner';
            document.body.appendChild(banner);
        }
        
        banner.className = "fixed top-4 left-1/2 -translate-x-1/2 z-[999999] max-w-lg w-[92%] sm:w-auto px-4 py-3 rounded-2xl shadow-2xl flex items-center gap-3.5 transition-all duration-300 border " +
            (state === 'success' 
                ? "bg-slate-900/95 text-white border-emerald-500/80 shadow-emerald-950/40"
                : (state === 'warning'
                    ? "bg-slate-900/95 text-white border-amber-500/80 shadow-amber-950/40"
                    : "bg-slate-950/95 text-white border-sky-500/80 shadow-sky-950/40"));
        
        let iconHtml = '<i class="fa-solid fa-arrows-rotate fa-spin text-sky-400 text-lg"></i>';
        let badgeColor = 'bg-sky-400';
        if (state === 'success') {
            iconHtml = '<i class="fa-solid fa-cloud-arrow-up text-emerald-400 text-lg"></i>';
            badgeColor = 'bg-emerald-400';
        } else if (state === 'warning') {
            iconHtml = '<i class="fa-solid fa-triangle-exclamation text-amber-400 text-lg"></i>';
            badgeColor = 'bg-amber-400';
        }
        
        banner.innerHTML = `
            <div class="w-10 h-10 rounded-xl bg-white/10 flex items-center justify-center shrink-0">
                ${iconHtml}
            </div>
            <div class="min-w-0 pr-2">
                <div class="flex items-center gap-2">
                    <span class="w-2 h-2 rounded-full ${badgeColor} ${state === 'syncing' ? 'animate-ping' : ''}"></span>
                    <h4 class="text-xs font-black uppercase tracking-wider">${title}</h4>
                </div>
                <p class="text-[11px] font-medium text-slate-200 mt-0.5 leading-snug">${subtitle}</p>
            </div>
            <button type="button" onclick="window.posSyncEngine.hideProactiveBanner()" class="ml-auto w-6 h-6 rounded-full bg-white/10 hover:bg-white/20 text-slate-300 flex items-center justify-center text-xs shrink-0 transition">
                <i class="fa-solid fa-xmark"></i>
            </button>
        `;
        
        if (state === 'success' || state === 'warning') {
            if (window._syncBannerTimeout) clearTimeout(window._syncBannerTimeout);
            window._syncBannerTimeout = setTimeout(() => {
                window.posSyncEngine.hideProactiveBanner();
            }, 4500);
        }
    },
    
    hideProactiveBanner: () => {
        const banner = document.getElementById('pos-proactive-sync-banner');
        if (banner) {
            banner.classList.add('opacity-0', 'translate-y-[-20px]');
            setTimeout(() => banner.remove(), 300);
        }
    },
    
    updateSyncUI: () => {
        const isOnline = navigator.onLine;
        if (typeof window._lastDeviceOnlineStatus === 'boolean' && !window._lastDeviceOnlineStatus && isOnline) {
            if (typeof window.triggerSyncOnlineHaptic === 'function') {
                window.triggerSyncOnlineHaptic();
            }
        }
        window._lastDeviceOnlineStatus = isOnline;

        const queue = window.posSyncEngine.getPendingQueue();
        const pendingCount = queue.length;
        const isSyncing = window.posSyncEngine.isSyncing;
        
        // 1. Header POS Kasir
        const dot = document.getElementById('pos-sync-dot');
        const text = document.getElementById('pos-sync-status-text');
        const badge = document.getElementById('pos-pending-sync-badge');
        const banner = document.getElementById('pos-offline-sync-banner');
        const bannerTitle = document.getElementById('pos-offline-banner-title');
        const bannerSub = document.getElementById('pos-offline-banner-subtitle');
        const bannerCounter = document.getElementById('pos-offline-pending-counter');
        
        if (dot && text) {
            if (isSyncing) {
                dot.className = "w-2 h-2 rounded-full bg-sky-400 animate-ping";
                text.innerText = "Menyinkronkan...";
            } else if (!isOnline) {
                dot.className = "w-2 h-2 rounded-full bg-rose-400 animate-pulse";
                text.innerText = "Mode Offline";
            } else if (pendingCount > 0) {
                dot.className = "w-2 h-2 rounded-full bg-amber-400 animate-pulse";
                text.innerText = "Ada Antrean Offline";
            } else {
                dot.className = "w-2 h-2 rounded-full bg-emerald-400";
                text.innerText = "Online";
            }
        }
        
        if (badge) {
            if (pendingCount > 0) {
                badge.classList.remove('hidden');
                badge.innerText = `${pendingCount} antrean`;
            } else {
                badge.classList.add('hidden');
            }
        }
        
        // 2. Banner Notifikasi POS
        if (banner) {
            if (!isOnline || pendingCount > 0) {
                banner.classList.remove('hidden');
                if (bannerTitle) {
                    bannerTitle.innerText = !isOnline ? "Mode Offline Aktif (POS Siap Digunakan)" : "Ada Transaksi Offline Menunggu Sinkron";
                }
                if (bannerSub) {
                    bannerSub.innerText = isSyncing ? "Sedang mengunggah transaksi ke cloud..." : (!isOnline ? "Transaksi tetap tersimpan di lokal & otomatis disinkronkan saat online" : "Internet telah tersambung, klik Sinkronkan untuk memperbarui data cloud");
                }
                if (bannerCounter) {
                    bannerCounter.innerText = `${pendingCount} Tertunda`;
                }
            } else {
                banner.classList.add('hidden');
            }
        }
    }
};

// =========================================================================
// PWA & OFFLINE-TO-ONLINE SYNC MANAGER (ULTRA-RESILIENT AUTO-SYNC)
// Memastikan saat aplikasi berjalan dalam mode PWA (Standalone/Installed),
// transisi dari offline ke online seketika menyinkronkan seluruh antrean transaksi.
// =========================================================================
window._isPrintingNow = false;
window._lastFocusSyncAt = 0;

window.pwaTriggerSync = async (source = 'auto') => {
    if (window._isPrintingNow) return;
    try {
        if (typeof goOnline === 'function' && db) {
            goOnline(db);
        }
    } catch(e) {}

    // Periksa antrean pesanan lokal yang belum ter-enqueue
    try {
        const savedOffline = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (Array.isArray(savedOffline) && window.posSyncEngine) {
            const queue = window.posSyncEngine.getPendingQueue();
            savedOffline.forEach(off => {
                if (off && (!off.synced || off.isOffline)) {
                    const id = off.orderId || off.id;
                    if (id && !queue.some(q => q.id === id)) {
                        window.posSyncEngine.enqueue('order', off);
                    }
                }
            });
        }
    } catch(e) {}

    if (window.posSyncEngine) {
        window.posSyncEngine.updateSyncUI();
        const queue = window.posSyncEngine.getPendingQueue();
        if (queue.length > 0 && !window.posSyncEngine.isSyncing) {
            console.log(`[PWA AutoSync] Memicu sinkronisasi ${queue.length} data offline via trigger: ${source}`);
            await window.posSyncEngine.syncAllPending(false);
        }
    }
};

// 1. Probe aktif untuk mendeteksi pemulihan internet nyata pada mode PWA
let isPwaProbing = false;
setInterval(async () => {
    if (window._isPrintingNow || !window.posSyncEngine || window.posSyncEngine.isSyncing) return;
    const queue = window.posSyncEngine.getPendingQueue();
    if (queue.length === 0) return;

    if (navigator.onLine && !isPwaProbing) {
        isPwaProbing = true;
        try {
            // Probe nyata ke server untuk memverifikasi paket data benar-benar bisa lewat
            const res = await fetch('/logo-192.png?probe=' + Date.now(), { method: 'HEAD', cache: 'no-store' });
            if (res.ok) {
                if (!window._lastDeviceOnlineStatus) {
                    window._lastDeviceOnlineStatus = true;
                    if (typeof window.perbaruiIndikatorKoneksi === 'function') {
                        window.perbaruiIndikatorKoneksi(true);
                    }
                }
                window.pwaTriggerSync('heartbeat-probe');
            }
        } catch(err) {
            // Masih offline nyata
        } finally {
            isPwaProbing = false;
        }
    }
}, 4000);

// 2. Event Listener PWA Saat Pengguna Membuka Kembali Aplikasi (Resume/Foreground)
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && !window._isPrintingNow) {
        const nowTs = Date.now();
        if (nowTs - (window._lastFocusSyncAt || 0) < 5000) return;
        window._lastFocusSyncAt = nowTs;
        console.log('[PWA Lifecycle] Aplikasi kembali aktif (foreground). Mengecek koneksi & sinkronisasi...');
        window.pwaTriggerSync('visibility-visible');
    }
});

window.addEventListener('focus', () => {
    if (window._isPrintingNow) return;
    const nowTs = Date.now();
    // Cegah pemicuan sinkronisasi berulang saat fokus berpindah akibat klik tombol/dialog/cetak
    if (nowTs - (window._lastFocusSyncAt || 0) < 30000) return;
    window._lastFocusSyncAt = nowTs;
    window.pwaTriggerSync('window-focus');
});

// 3. Listener pesan dari Service Worker Background Sync
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.addEventListener('message', (event) => {
        if (!event.data) return;
        if (event.data.type === 'BACKGROUND_SYNC_TRIGGERED' || event.data.type === 'SYNC_POS_QUEUE') {
            console.log('[PWA SW Message] Background sync sinyal diterima dari Service Worker:', event.data.tag);
            window.pwaTriggerSync('sw-background-sync');
        }
    });
}

// Inisialisasi awal UI sinkronisasi & listener koneksi otomatis
setTimeout(() => {
    if (window.posSyncEngine && typeof window.posSyncEngine.updateSyncUI === 'function') {
        window.posSyncEngine.updateSyncUI();
    }
    window.pwaTriggerSync('initial-check');
}, 800);

// ==========================================
// HAPTIC VIBRATION (OFFLINE -> ONLINE FEEDBACK)
// ==========================================
window.triggerSyncOnlineHaptic = () => {
    if (typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function') {
        try {
            // Getaran taktil singkat dan tegas: 70ms getar, 40ms jeda, 90ms getar
            navigator.vibrate([70, 40, 90]);
        } catch (e) {
            // Abaikan jika browser membatasi getaran atau perangkat tidak mendukung
        }
    }
};

window._lastDeviceOnlineStatus = navigator.onLine;

// Autosinkronisasi instan saat koneksi internet kembali online
window.addEventListener('online', () => {
    console.log('[AutoSync] Jaringan internet terdeteksi online! Memulai sinkronisasi otomatis...');
    window.triggerSyncOnlineHaptic();
    window._lastDeviceOnlineStatus = true;
    try {
        if (typeof goOnline === 'function' && db) goOnline(db);
    } catch(e) {}
    window.pwaTriggerSync('online-event');
    if (window.clientErrorLogger) {
        window.clientErrorLogger.uploadLogsToServer().catch(() => {});
    }
    if (typeof window.perbaruiIndikatorKoneksi === 'function') {
        window.perbaruiIndikatorKoneksi(true);
    }
});

window.addEventListener('offline', () => {
    console.warn('[AutoSync] Jaringan internet terputus. Mode offline kasir aktif otomatis tanpa lag.');
    window._lastDeviceOnlineStatus = false;
    try {
        if (typeof goOffline === 'function' && db) goOffline(db);
    } catch(e) {}
    if (window.posSyncEngine) {
        window.posSyncEngine.updateSyncUI();
        window.posSyncEngine.showProactiveBanner('⚠️ Mode Offline Aktif', 'Koneksi terputus. Seluruh fitur POS kasir tetap beroperasi mulus secara offline.', 'warning');
    }
    if (typeof window.perbaruiIndikatorKoneksi === 'function') {
        window.perbaruiIndikatorKoneksi(false);
    }
});

// ==========================================
// FUNGSI INTI BGM (EARLY DEFENSE & REGISTRATION)
// ==========================================
window.bgm = document.getElementById('bgm-mainstay');
window.bgmIcon = document.getElementById('icon-bgm');
window.btnBgm = document.getElementById('btn-bgm');
window.isBgmPlaying = false;
window.bgmUserPaused = false;

window.isCustomerViewActive = () => {
    try {
        const sessionRole = localStorage.getItem('mainstay_session_role');
        const role = sessionRole || (typeof currentRole !== 'undefined' ? currentRole : 'customer');
        const isPosOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';
        if (role !== 'customer' || isPosOpen) return false;

        const custView = document.getElementById('view-customer');
        if (!custView || custView.classList.contains('hidden') || custView.style.display === 'none') {
            return false;
        }

        const viewKasir = document.getElementById('view-kasir');
        if (viewKasir && !viewKasir.classList.contains('hidden') && viewKasir.style.display !== 'none') return false;

        const viewOwner = document.getElementById('view-owner');
        if (viewOwner && !viewOwner.classList.contains('hidden') && viewOwner.style.display !== 'none') return false;

        const panelKasir = document.getElementById('panel-kasir-manual');
        if (panelKasir && !panelKasir.classList.contains('hidden') && panelKasir.style.display !== 'none') return false;

        const ruangKerja = document.getElementById('ruang-kerja-kasir');
        if (ruangKerja && !ruangKerja.classList.contains('hidden') && ruangKerja.style.display !== 'none') return false;

        const modalLogin = document.getElementById('modal-login');
        if (modalLogin && !modalLogin.classList.contains('hidden') && modalLogin.style.display !== 'none') return false;

        return true;
    } catch (e) {
        return false;
    }
};

window.matikanBGM = () => {
    const audio = document.getElementById('bgm-mainstay') || window.bgm;
    if (audio) {
        try { audio.pause(); } catch(e) {}
    }
    const btn = document.getElementById('btn-bgm') || window.btnBgm;
    if (btn) {
        btn.style.display = 'none';
        btn.classList.add('hidden');
    }
    const icon = document.getElementById('icon-bgm') || window.bgmIcon;
    if (icon) icon.className = "fa-solid fa-volume-xmark text-slate-400";
    window.isBgmPlaying = false;
};

window.cobaPlayBGM = () => {
    if (typeof window.isCustomerViewActive === 'function' && !window.isCustomerViewActive()) {
        window.matikanBGM();
        return;
    }
    if (window.bgmUserPaused) return;

    const audio = document.getElementById('bgm-mainstay') || window.bgm;
    if (!audio) return;
    audio.volume = 0.3;
    audio.play().then(() => {
        const icon = document.getElementById('icon-bgm') || window.bgmIcon;
        if (icon) icon.className = "fa-solid fa-volume-high text-blue-500";
        window.isBgmPlaying = true;
        window.bgmUserPaused = false;
        const btn = document.getElementById('btn-bgm') || window.btnBgm;
        if (btn && window.isCustomerViewActive()) {
            btn.style.display = 'flex';
            btn.classList.remove('hidden');
        }
    }).catch(() => {});
};

window.toggleBGM = () => {
    if (typeof window.isCustomerViewActive === 'function' && !window.isCustomerViewActive()) {
        window.matikanBGM();
        return;
    }
    const audio = document.getElementById('bgm-mainstay') || window.bgm;
    if (!audio) return;
    if (window.isBgmPlaying) {
        audio.pause();
        const icon = document.getElementById('icon-bgm') || window.bgmIcon;
        if (icon) icon.className = "fa-solid fa-volume-xmark text-slate-400";
        window.isBgmPlaying = false;
        window.bgmUserPaused = true;
    } else {
        window.bgmUserPaused = false;
        window.cobaPlayBGM();
    }
};

window.nyalakanBGM = () => {
    if (typeof window.isCustomerViewActive === 'function' && !window.isCustomerViewActive()) {
        window.matikanBGM();
        return;
    }
    const btn = document.getElementById('btn-bgm') || window.btnBgm;
    if (btn) {
        btn.style.display = 'flex';
        btn.classList.remove('hidden');
    }
    if (!window.bgmUserPaused) {
        window.cobaPlayBGM();
    }
};

