let _lastAlertMsg = '';
let _lastAlertTime = 0;
window.alert = (pesan) => {
    const now = Date.now();
    const strPesan = String(pesan || '');
    if (strPesan === _lastAlertMsg && (now - _lastAlertTime) < 1500) {
        return; // Cegah notifikasi ganda / double notif dalam rentang 1.5 detik
    }
    _lastAlertMsg = strPesan;
    _lastAlertTime = now;

    const notifLama = document.getElementById('notif-global');
    if (notifLama) notifLama.remove();

    const isSukses = strPesan.toLowerCase().includes('berhasil') || strPesan.toLowerCase().includes('sukses') || strPesan.toLowerCase().includes('diberikan');
    const bgColor = isSukses ? 'bg-emerald-600' : 'bg-red-600';
    const icon = isSukses ? 'fa-circle-check' : 'fa-triangle-exclamation';

    const notif = document.createElement('div');
    notif.id = 'notif-global';
    notif.className = `fixed top-10 left-0 right-0 mx-auto w-[90%] max-w-sm ${bgColor} text-white px-4 py-3 rounded-xl shadow-lg z-[9999] flex items-center gap-3 font-sans animate-bounce`;
    notif.innerHTML = `<i class="fa-solid ${icon} text-lg"></i> <span class="font-bold text-sm">${strPesan}</span>`;

    document.body.appendChild(notif);
    setTimeout(() => { if (notif) notif.remove(); }, 3000);
};

// ==========================================
// 2. MESIN NUMPAD & OTENTIKASI PIN UTAMA
// ==========================================
window.currentPinInput = typeof window.currentPinInput === 'string' ? window.currentPinInput : "";

const PIN_MAX_ATTEMPTS = 3;
const PIN_BASE_COOLDOWN_SEC = 30;
const PIN_LOCKOUT_STORAGE_KEY = 'mainstay_pin_lockout_state';
let _pinCooldownInterval = null;
let _pinErrorFlashTimeout = null;

function readPinLockoutState() {
    try {
        const raw = localStorage.getItem(PIN_LOCKOUT_STORAGE_KEY);
        if (!raw) return { attempts: 0, lockouts: 0, cooldownUntil: 0 };
        const parsed = JSON.parse(raw);
        return {
            attempts: Number(parsed?.attempts || 0),
            lockouts: Number(parsed?.lockouts || 0),
            cooldownUntil: Number(parsed?.cooldownUntil || 0)
        };
    } catch (e) {
        return { attempts: 0, lockouts: 0, cooldownUntil: 0 };
    }
}

function writePinLockoutState(state) {
    try {
        localStorage.setItem(PIN_LOCKOUT_STORAGE_KEY, JSON.stringify({
            attempts: Number(state.attempts || 0),
            lockouts: Number(state.lockouts || 0),
            cooldownUntil: Number(state.cooldownUntil || 0)
        }));
    } catch (e) {}
}

window.resetPinLockoutState = () => {
    if (_pinCooldownInterval) {
        clearInterval(_pinCooldownInterval);
        _pinCooldownInterval = null;
    }
    writePinLockoutState({ attempts: 0, lockouts: 0, cooldownUntil: 0 });
    window.syncPinModalLockoutUI();
};

window.getRemainingPinCooldownSec = () => {
    const st = readPinLockoutState();
    const diffMs = st.cooldownUntil - Date.now();
    if (diffMs <= 0) {
        if (st.cooldownUntil > 0) {
            writePinLockoutState({ attempts: 0, lockouts: st.lockouts, cooldownUntil: 0 });
        }
        return 0;
    }
    return Math.ceil(diffMs / 1000);
};

window.recordFailedPinAttempt = (customReason = '') => {
    const st = readPinLockoutState();
    const nextAttempts = (st.attempts || 0) + 1;
    if (nextAttempts >= PIN_MAX_ATTEMPTS) {
        const nextLockouts = (st.lockouts || 0) + 1;
        const durationSec = PIN_BASE_COOLDOWN_SEC; // Jeda cooldown keamanan tepat 30 detik setelah 3x salah
        const cooldownUntil = Date.now() + durationSec * 1000;
        writePinLockoutState({ attempts: PIN_MAX_ATTEMPTS, lockouts: nextLockouts, cooldownUntil });
        window.syncPinModalLockoutUI(customReason);
        return { locked: true, remainingSec: durationSec, attemptsLeft: 0 };
    } else {
        writePinLockoutState({ attempts: nextAttempts, lockouts: st.lockouts || 0, cooldownUntil: 0 });
        window.syncPinModalLockoutUI(customReason);
        return { locked: false, remainingSec: 0, attemptsLeft: Math.max(0, PIN_MAX_ATTEMPTS - nextAttempts) };
    }
};

window.syncPinModalLockoutUI = (customNote = '') => {
    const banner = document.getElementById('pin-login-security-banner');
    const titleEl = document.getElementById('pin-login-security-title');
    const subEl = document.getElementById('pin-login-security-sub');
    const numpad = document.getElementById('modal-login-numpad');
    const lockIcon = document.getElementById('pin-login-lock-icon');
    const subtitleEl = document.getElementById('pin-login-subtitle');

    const remainingSec = window.getRemainingPinCooldownSec();
    const st = readPinLockoutState();

    if (numpad) {
        const buttons = numpad.querySelectorAll('button');
        buttons.forEach(btn => {
            btn.disabled = remainingSec > 0;
        });
        numpad.classList.toggle('opacity-50', remainingSec > 0);
    }

    if (lockIcon) {
        if (remainingSec > 0) {
            lockIcon.className = 'w-16 h-16 shrink-0 bg-rose-100 text-rose-600 rounded-[1rem] flex items-center justify-center text-3xl mb-4 mt-2 border border-rose-200 shadow-sm transition-colors duration-200';
            lockIcon.innerHTML = '<i class="fa-solid fa-shield-halved"></i>';
        } else {
            lockIcon.className = 'w-16 h-16 shrink-0 bg-orange-100 text-orange-500 rounded-[1rem] flex items-center justify-center text-3xl mb-4 mt-2 border border-orange-200/50 shadow-sm transition-colors duration-200';
            lockIcon.innerHTML = '<i class="fa-solid fa-lock"></i>';
        }
    }

    if (subtitleEl) {
        subtitleEl.innerText = remainingSec > 0
            ? 'Keamanan aktif sementara karena batas percobaan tercapai'
            : 'Masukkan PIN 6 Digit (Staff atau Master Owner)';
    }

    if (!banner || !titleEl || !subEl) return;

    if (remainingSec > 0) {
        banner.className = 'w-full mb-4 px-3.5 py-2.5 rounded-2xl border border-rose-200 bg-rose-50 text-rose-800 text-center transition-all duration-200';
        titleEl.innerHTML = `<i class="fa-solid fa-hourglass-half mr-1"></i> Akses PIN dikunci sementara (${PIN_MAX_ATTEMPTS}/${PIN_MAX_ATTEMPTS} salah)`;
        subEl.innerText = `Mohon tunggu ${remainingSec} detik sebelum mencoba memasukkan PIN kembali.`;

        if (!_pinCooldownInterval) {
            _pinCooldownInterval = setInterval(() => {
                const rem = window.getRemainingPinCooldownSec();
                if (rem <= 0) {
                    clearInterval(_pinCooldownInterval);
                    _pinCooldownInterval = null;
                    window.syncPinModalLockoutUI();
                } else {
                    const sEl = document.getElementById('pin-login-security-sub');
                    if (sEl) {
                        sEl.innerText = `Mohon tunggu ${rem} detik sebelum mencoba memasukkan PIN kembali.`;
                    }
                }
            }, 1000);
        }
    } else if (st.attempts > 0) {
        const left = Math.max(1, PIN_MAX_ATTEMPTS - st.attempts);
        banner.className = 'w-full mb-4 px-3.5 py-2.5 rounded-2xl border border-amber-200 bg-amber-50 text-amber-900 text-center transition-all duration-200';
        titleEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation text-amber-600 mr-1"></i> ${customNote || 'PIN yang Anda masukkan salah.'}`;
        subEl.innerText = `Sisa percobaan: ${left} dari ${PIN_MAX_ATTEMPTS} kali sebelum jeda keamanan.`;
    } else {
        banner.classList.add('hidden');
        titleEl.innerText = '';
        subEl.innerText = '';
    }
};

window.flashPinErrorIndicator = () => {
    const container = document.getElementById('pin-indicators');
    if (!container) return;
    if (_pinErrorFlashTimeout) clearTimeout(_pinErrorFlashTimeout);
    const dots = container.children;
    for (let i = 0; i < dots.length; i++) {
        dots[i].className = 'w-4 h-4 rounded-full bg-rose-500 scale-110 transition-all duration-200 shadow-sm';
    }
    container.classList.remove('pin-shake');
    void container.offsetWidth;
    container.classList.add('pin-shake');
    _pinErrorFlashTimeout = setTimeout(() => {
        container.classList.remove('pin-shake');
        window.resetNumpad();
    }, 380);
};

if (!window._pinModalKeyboardBound) {
    window._pinModalKeyboardBound = true;
    document.addEventListener('keydown', (e) => {
        const modal = document.getElementById('modal-login');
        if (!modal || modal.classList.contains('hidden')) return;
        if (e.key >= '0' && e.key <= '9') {
            e.preventDefault();
            window.tekanNumpad(e.key);
        } else if (e.key === 'Backspace') {
            e.preventDefault();
            window.hapusSatuNumpad();
        } else if (e.key === 'Escape') {
            e.preventDefault();
            window.closeModalLogin();
        }
    });
}

window.openModalLogin = window.bukaMenuAbsen = () => {
    window.currentPinInput = "";
    window._pendingPinAuth = null;
    window.updateIndikatorPin();
    window.syncPinModalLockoutUI();
    const modal = document.getElementById('modal-login') || document.getElementById('modal-login-absen');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }
};

window.closeModalLogin = window.tutupMenuAbsen = () => {
    if (_pinCooldownInterval) {
        clearInterval(_pinCooldownInterval);
        _pinCooldownInterval = null;
    }
    const modal = document.getElementById('modal-login') || document.getElementById('modal-login-absen');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.tekanNumpad = (angka) => {
    const remSec = window.getRemainingPinCooldownSec();
    if (remSec > 0 || window._isValidatingPin) {
        if (remSec > 0) window.syncPinModalLockoutUI();
        return;
    }
    window.currentPinInput = window.currentPinInput || "";
    if (window.currentPinInput.length < 6) {
        window.currentPinInput += String(angka);
        window.updateIndikatorPin();
        
        if (window.currentPinInput.length === 6) {
            const enteredPin = window.currentPinInput;
            window._isValidatingPin = true;
            setTimeout(async () => {
                try {
                    if (typeof window.validasiOtentikasiPin === 'function') {
                        await window.validasiOtentikasiPin(enteredPin);
                    } else {
                        window._pendingPinAuth = enteredPin;
                    }
                } finally {
                    window._isValidatingPin = false;
                }
            }, 100);
        }
    }
};

window.hapusSatuNumpad = () => {
    if (window.getRemainingPinCooldownSec() > 0) return;
    window.currentPinInput = window.currentPinInput || "";
    if (window.currentPinInput.length > 0) {
        window.currentPinInput = window.currentPinInput.slice(0, -1);
        window.updateIndikatorPin();
    }
};

window.resetNumpad = () => {
    window.currentPinInput = "";
    window._pendingPinAuth = null;
    window.updateIndikatorPin();
};

window.updateIndikatorPin = () => {
    const container = document.getElementById('pin-indicators');
    if (!container) return;
    
    const dots = container.children;
    const len = (window.currentPinInput || "").length;
    for (let i = 0; i < dots.length; i++) {
        if (i < len) {
            dots[i].className = "w-4 h-4 rounded-full bg-orange-500 scale-110 transition-all duration-200 shadow-sm";
        } else {
            dots[i].className = "w-4 h-4 rounded-full bg-slate-200 transition-all duration-200";
        }
    }
};

