// VALIDASI PENJAGAAN AKSES KASIR & ABSENSI
// ==========================================

// 1. Cek apakah toko sudah melakukan rekap tutup harian/shift hari ini
window.cekTokoSudahTutupRekapHariIni = () => {
    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const todayStr = `${yyyy}-${mm}-${dd}`;
    const tutupTgl = localStorage.getItem('mainstay_tutup_rekap_tgl');
    return tutupTgl === todayStr;
};

// 2. Cek apakah seluruh staf operasional sudah absen pulang untuk hari ini
window.cekSemuaStaffSudahAbsenPulang = () => {
    let staffEntries = Object.entries(globalStaff || {});
    if (staffEntries.length === 0 && !window.IS_BRANCH_OUTLET && window.defaultDemoStaff) {
        staffEntries = Object.entries(window.defaultDemoStaff);
    }
    // Filter hanya staf operasional (kecualikan Owner / PIN 888888)
    const operationalStaff = staffEntries.filter(([k, s]) => {
        const role = String(s.role || s.tipeKaryawan || '').toLowerCase();
        const pin = String(s.pin || '');
        return !role.includes('owner') && pin !== '888888';
    });

    if (operationalStaff.length === 0) return false;

    let clockedInCount = 0;
    let allClockedOut = true;

    operationalStaff.forEach(([k, s]) => {
        const duty = typeof window.cekStatusTugasStaf === 'function'
            ? window.cekStatusTugasStaf(s.name || s.nama, s.pin)
            : { hasClockedInToday: false, hasClockedOutToday: false, isOnDuty: false };
        if (duty.hasClockedInToday) {
            clockedInCount++;
            if (!duty.hasClockedOutToday || duty.isOnDuty) {
                allClockedOut = false;
            }
        }
    });

    return (clockedInCount > 0 && allClockedOut);
};

// 3. Cek batas jam operasional toko: Kasir hanya boleh login mulai 1 jam sebelum jam buka toko
window.cekIzinJamOperasionalToko = () => {
    const sSettings = window.storeSettings || JSON.parse(localStorage.getItem('mainstay_store_settings') || '{}');
    const jamBukaStr = String(sSettings.jam_buka || '08:00').trim();
    
    let bukaH = 8, bukaM = 0;
    if (jamBukaStr.includes(':')) {
        const parts = jamBukaStr.split(':');
        bukaH = parseInt(parts[0], 10) || 0;
        bukaM = parseInt(parts[1], 10) || 0;
    }
    const bukaTotalMins = bukaH * 60 + bukaM;
    let allowedStartMins = bukaTotalMins - 60; // 1 jam sebelum jam buka toko
    if (allowedStartMins < 0) allowedStartMins += 24 * 60;

    const now = new Date();
    const nowH = now.getHours();
    const nowM = now.getMinutes();
    const nowTotalMins = nowH * 60 + nowM;

    const allowedH = Math.floor(allowedStartMins / 60);
    const allowedM = allowedStartMins % 60;
    const allowedTimeStr = `${String(allowedH).padStart(2, '0')}:${String(allowedM).padStart(2, '0')}`;
    const nowStr = `${String(nowH).padStart(2, '0')}:${String(nowM).padStart(2, '0')}`;

    if (nowTotalMins < allowedStartMins) {
        return {
            allowed: false,
            reason: `Toko buka pukul ${jamBukaStr} WIB. Kasir hanya dapat login mulai 1 jam sebelum jam buka toko (Pukul ${allowedTimeStr} WIB).\n\n• Jam Sekarang: ${nowStr} WIB\n• Jam Buka Toko: ${jamBukaStr} WIB\n• Waktu Mulai Login Diizinkan: ${allowedTimeStr} WIB`,
            allowedTimeStr,
            jamBukaStr,
            nowStr
        };
    }

    return { allowed: true, allowedTimeStr, jamBukaStr, nowStr };
};

// 4. Cek jadwal shift masing-masing staf: Staf hanya dapat login paling cepat 1 jam sebelum shift
window.cekIzinShiftStaff = (staffObj) => {
    if (!staffObj) return { allowed: false, reason: "Data staf tidak ditemukan." };
    
    // Owner / Master Owner bebas akses kapan saja
    const role = String(staffObj.role || staffObj.tipeKaryawan || '').toLowerCase();
    if (role.includes('owner') || String(staffObj.pin) === '888888') {
        return { allowed: true };
    }

    // Ambil jadwal shift masuk
    const sSettings = window.storeSettings || JSON.parse(localStorage.getItem('mainstay_store_settings') || '{}');
    const defaultOpen = sSettings.jam_buka || '08:00';
    const shiftStr = String(staffObj.shiftIn || staffObj.jamMasuk || defaultOpen).trim();
    
    let shiftH = 8, shiftM = 0;
    if (shiftStr.includes(':')) {
        const parts = shiftStr.split(':');
        shiftH = parseInt(parts[0], 10) || 0;
        shiftM = parseInt(parts[1], 10) || 0;
    }
    const shiftTotalMins = shiftH * 60 + shiftM;
    let allowedStartMins = shiftTotalMins - 60; // Paling cepat 1 jam sebelum shift
    if (allowedStartMins < 0) allowedStartMins += 24 * 60;

    const shiftOutStr = String(staffObj.shiftOut || staffObj.jamPulang || sSettings.jam_tutup || '22:00').trim();

    const now = new Date();
    const nowH = now.getHours();
    const nowM = now.getMinutes();
    const nowTotalMins = nowH * 60 + nowM;

    const jamBukaH = Math.floor(allowedStartMins / 60);
    const jamBukaM = allowedStartMins % 60;
    const allowedTimeStr = `${String(jamBukaH).padStart(2, '0')}:${String(jamBukaM).padStart(2, '0')}`;
    const nowStr = `${String(nowH).padStart(2, '0')}:${String(nowM).padStart(2, '0')}`;

    let isTooEarly = false;
    if (allowedStartMins < shiftTotalMins) {
        if (nowTotalMins < allowedStartMins) {
            isTooEarly = true;
        }
    } else {
        if (nowTotalMins < allowedStartMins && nowTotalMins > shiftTotalMins) {
            isTooEarly = true;
        }
    }

    if (isTooEarly) {
        return {
            allowed: false,
            reason: `Staf hanya dapat login dan absen paling cepat 1 jam sebelum shift dimulai.\n\n• Jadwal Shift Masuk: ${shiftStr} WIB\n• Waktu Mulai Diizinkan: Pukul ${allowedTimeStr} WIB\n• Jam Sekarang: ${nowStr} WIB`,
            shiftIn: shiftStr,
            shiftOut: shiftOutStr,
            allowedTimeStr,
            nowStr
        };
    }

    return {
        allowed: true,
        shiftIn: shiftStr,
        shiftOut: shiftOutStr,
        allowedTimeStr,
        nowStr
    };
};

window.validasiOtentikasiPin = async (pinInput) => {
    const remSec = window.getRemainingPinCooldownSec();
    if (remSec > 0) {
        window.syncPinModalLockoutUI();
        resetNumpad();
        return;
    }

    const masterPin = String(typeof MASTER_PIN !== 'undefined' ? MASTER_PIN : "888888");
    
    // 1. Cek Master Owner (Hardcoded 888888 atau Database Master Owner) -> Bebas akses 24/7
    let isOwnerMatched = (String(pinInput) === masterPin || String(pinInput) === "888888");
    let ownerMatchedName = "Owner";
    if (!isOwnerMatched && typeof globalMasterOwner !== 'undefined' && globalMasterOwner) {
        for (const k in globalMasterOwner) {
            if (String(globalMasterOwner[k]?.pin) === String(pinInput)) {
                isOwnerMatched = true;
                ownerMatchedName = String(globalMasterOwner[k]?.name || "Owner").replace(/\s*\(\s*master\s*\)/i, '').trim() || "Owner";
                break;
            }
        }
    }

    if (isOwnerMatched) {
        window.resetPinLockoutState();
        localStorage.setItem('mainstay_session_role', 'owner');
        localStorage.setItem('mainstay_staff_name', ownerMatchedName);
        
        closeModalLogin();
        resetNumpad();
        if (typeof window.switchRoleView === 'function') {
            window.switchRoleView('owner');
        }
        if (typeof window.tampilkanPopupLoginOwner === 'function') {
            window.tampilkanPopupLoginOwner(ownerMatchedName);
        }
        return;
    }

    // Pastikan data staff cabang sudah dimuat dari Firebase & IndexedDB sebelum memvalidasi PIN Staff
    if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.getBranchStaff === 'function') {
        await window.mainstayIndexedDB.getBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat').catch(() => {});
    }
    if (!window._staffLoaded) {
        try {
            const staffSnap = await get(ref(db, 'staff'));
            globalStaff = staffSnap.exists() ? (staffSnap.val() || {}) : {};
            window.globalStaff = globalStaff;
            window._staffLoaded = true;
            if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.syncBranchStaff === 'function') {
                window.mainstayIndexedDB.syncBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat', globalStaff).catch(() => {});
            }
        } catch (e) {}
    }

    // 2. Cek Database Staff (Khusus cabang: WAJIB pakai data staff cabang sendiri dari Firebase + IndexedDB, tanpa fallback demo/Pusat)
    const effectiveStaffMap = typeof window.getEffectiveBranchStaffMap === 'function' ? window.getEffectiveBranchStaffMap() : (globalStaff || {});
    let foundStaff = null;
    let staffKey = null;

    for (const key in effectiveStaffMap) {
        const staffObj = effectiveStaffMap[key];
        if (!staffObj) continue;
        const staffPin = String(staffObj.pin || staffObj.password || staffObj.pass || "");
        if (staffPin && staffPin === String(pinInput)) {
            foundStaff = staffObj;
            staffKey = key;
            break;
        }
    }

    if (!foundStaff && Object.keys(effectiveStaffMap).length === 0 && !window.IS_BRANCH_OUTLET && window.defaultDemoStaff) {
        for (const key in window.defaultDemoStaff) {
            const staffObj = window.defaultDemoStaff[key];
            if (String(staffObj.pin) === String(pinInput)) {
                foundStaff = staffObj;
                staffKey = key;
                break;
            }
        }
    }

    if (!foundStaff) {
        const failReason = (window.IS_BRANCH_OUTLET && Object.keys(effectiveStaffMap).length === 0)
            ? "Data staff cabang masih kosong."
            : "PIN tidak terdaftar di sistem.";
        const lockRes = window.recordFailedPinAttempt(failReason);
        window.flashPinErrorIndicator();
        if (typeof window.tampilkanNotifikasi === 'function') {
            if (lockRes.locked) {
                window.tampilkanNotifikasi(`PIN salah 3x. Akses dikunci selama ${lockRes.remainingSec} detik.`, 'error');
            } else {
                window.tampilkanNotifikasi(`PIN salah! Sisa percobaan: ${lockRes.attemptsLeft} kali.`, 'warning');
            }
        }
        return;
    }

    // PIN valid ditemukan -> reset riwayat gagal percobaan PIN
    window.resetPinLockoutState();

    const namaStaff = foundStaff.nama || foundStaff.name || "Staff Kasir";
    const staffPin = String(foundStaff.pin || pinInput);

    // GUARDRAIL A: Tidak bisa login ketika toko sudah rekap tutup shift harian
    if (window.cekTokoSudahTutupRekapHariIni()) {
        alert(`⛔ AKSES KASIR DITUTUP\n\nToko telah melakukan rekap tutup shift/harian untuk hari ini.\n\nKasir dapat login kembali besok hari mulai 1 jam sebelum jam buka toko.`);
        resetNumpad();
        return;
    }

    // GUARDRAIL B: Tidak bisa login ketika semua staf operasional sudah absen pulang
    if (window.cekSemuaStaffSudahAbsenPulang()) {
        alert(`⛔ AKSES KASIR DITUTUP\n\nSeluruh staf operasional telah menyelesaikan tugas & absen pulang hari ini.\n\nKasir dapat login kembali besok hari mulai 1 jam sebelum jam buka toko.`);
        resetNumpad();
        return;
    }

    // GUARDRAIL C: Hanya bisa login mulai 1 jam sebelum jam buka toko
    const storeTimeCheck = window.cekIzinJamOperasionalToko();
    if (!storeTimeCheck.allowed) {
        alert(`⛔ AKSES KASIR BELUM DIBUKA\n\n${storeTimeCheck.reason}`);
        resetNumpad();
        return;
    }

    // GUARDRAIL D: Cek jadwal shift individu staf
    const shiftCheck = window.cekIzinShiftStaff(foundStaff);
    if (!shiftCheck.allowed) {
        alert(`⛔ AKSES DITOLAK: BELUM WAKTU SHIFT\n\n${shiftCheck.reason}\n\nSilakan kembali mendekati jadwal shift Anda.`);
        resetNumpad();
        return;
    }

    // GUARDRAIL E: Cek status absensi hari ini staf bersangkutan
    const dutyStatus = typeof window.cekStatusTugasStaf === 'function' 
        ? window.cekStatusTugasStaf(namaStaff, staffPin) 
        : { hasClockedInToday: false, hasClockedOutToday: false, isOnDuty: false };

    // E1: Sudah Absen Pulang hari ini -> Tidak bisa double absen atau login kasir lagi di hari yang sama
    if (dutyStatus.hasClockedOutToday) {
        alert(`⛔ SHIFT SELESAI HARI INI\n\nAnda (${namaStaff}) sudah melakukan Absen Pulang hari ini (Pukul ${dutyStatus.jamPulang || '-'}).\n\nAbsen pulang tidak bisa double dan Anda tidak dapat login kasir kembali pada hari yang sama. Silakan login kembali pada shift besok.`);
        resetNumpad();
        return;
    }

    // E2: Sudah Absen Masuk hari ini (dan belum pulang) -> Langsung masuk tampilan kasir tanpa buka kamera lagi!
    if (dutyStatus.hasClockedInToday && !dutyStatus.hasClockedOutToday) {
        window.activeStaff = { ...foundStaff, key: staffKey };
        window.safeSetItem('mainstay_session_role', 'kasir');
        window.safeSetItem('mainstay_staff_name', namaStaff);
        const staffFoto = foundStaff.photo || foundStaff.foto || foundStaff.avatar || '';
        const cleanS = {
            name: foundStaff.nama || foundStaff.name,
            role: foundStaff.role || foundStaff.tipeKaryawan,
            pin: foundStaff.pin,
            shiftIn: foundStaff.shiftIn,
            shiftOut: foundStaff.shiftOut,
            photo: (staffFoto && staffFoto.length < 80000) ? staffFoto : ''
        };
        window.safeSetItem('mainstay_session_staff', JSON.stringify(cleanS));
        if (typeof window.persistKasirAvatarThumbnail === 'function' && staffFoto) {
            window.persistKasirAvatarThumbnail(namaStaff, staffFoto);
        }

        const elNama = document.getElementById('kasir-active-name');
        if (elNama) elNama.innerText = namaStaff;

        closeModalLogin();
        resetNumpad();
        if (typeof window.switchRoleView === 'function') {
            window.switchRoleView('kasir');
        }
        if (typeof window.updateKasirActiveProfileUI === 'function') {
            window.updateKasirActiveProfileUI(namaStaff);
        }
        alert(`Akses Diberikan. Selamat bertugas kembali, ${namaStaff}! (Sudah absen masuk hari ini)`);
        return;
    }

    // E3: Belum Absen Masuk hari ini -> Buka kamera absen masuk selfie menyesuaikan profil dari PIN
    // Setelah foto selesai, otomatis langsung masuk ke tampilan kasir dengan profil kasir yang login
    window.activeStaff = { ...foundStaff, key: staffKey };
    window.pendingKasirLoginStaff = { ...foundStaff, key: staffKey };
    closeModalLogin();
    resetNumpad();
    
    if (typeof window.bukaKameraAbsensi === 'function') {
        window.bukaKameraAbsensi(foundStaff, 'Masuk', staffPin);
    } else {
        window.safeSetItem('mainstay_session_role', 'kasir');
        window.safeSetItem('mainstay_staff_name', namaStaff);
        const cleanS = { name: foundStaff.nama || foundStaff.name, role: foundStaff.role || foundStaff.tipeKaryawan, pin: foundStaff.pin, shiftIn: foundStaff.shiftIn, shiftOut: foundStaff.shiftOut };
        window.safeSetItem('mainstay_session_staff', JSON.stringify(cleanS));
        if (typeof window.switchRoleView === 'function') window.switchRoleView('kasir');
    }
};

if (window._pendingPinAuth) {
    const queuedPin = window._pendingPinAuth;
    window._pendingPinAuth = null;
    setTimeout(() => {
        if (typeof window.validasiOtentikasiPin === 'function') {
            window.validasiOtentikasiPin(queuedPin);
        }
    }, 50);
}

// ==========================================
// PUSAT KODE TRANSAKSI HARIAN (CSH, KSR, GRB, GFD, SHP, OTH)
// Format: [PREFIX]-[DDMM][3 DIGIT URUTAN GLOBAL HARIAN]
// ==========================================
window.generateDailyOrderId = (channelType = 'CSH') => {
    const now = new Date();
    const dd = String(now.getDate()).padStart(2, '0');
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const ddmm = `${dd}${mm}`;

    let prefix = 'KSR';
    const c = String(channelType || '').toLowerCase().trim();
    if (c === 'self' || c === 'csh' || c === 'customer' || c === 'self_order') {
        prefix = 'CSH';
    } else if (c === 'grab' || c === 'grabfood' || c === 'grb') {
        prefix = 'GRB';
    } else if (c === 'gofood' || c === 'go-food' || c === 'gojek' || c === 'gfd') {
        prefix = 'GFD';
    } else if (c === 'shopee' || c === 'shopeefood' || c === 'shoper' || c === 'shp') {
        prefix = 'SHP';
    } else if (c === 'lainnya' || c === 'oth' || c === 'other') {
        prefix = 'OTH';
    } else if (c === 'ksr' || c === 'kasir' || c === 'biasa' || c === 'manual') {
        prefix = 'KSR';
    }

    let highestSeq = 0;
    const seenOrderKeys = new Set();

    const checkOrder = (ord) => {
        if (!ord) return;
        const ordId = String(ord.orderId || ord.id || '');
        const rawKey = ord.firebaseKey || ord.orderId || ord.id;

        // Cegah duplikasi evaluasi antara globalOrders dan cache offline
        const dedupKey = ordId || rawKey;
        if (dedupKey) {
            if (seenOrderKeys.has(dedupKey)) return;
            seenOrderKeys.add(dedupKey);
        }

        // Cek pola standar: 3 karakter channel, tanda hubung '-', 4 digit DDMM, dan 3 digit nomor urutan harian
        const match = ordId.match(/^[A-Z]{3}-(\d{4})(\d{3})$/i);
        if (match) {
            const datePart = match[1];
            const seqPart = parseInt(match[2], 10);
            if (datePart === ddmm && !isNaN(seqPart) && seqPart > highestSeq) {
                highestSeq = seqPart;
            }
        } else {
            // Evaluasi pesanan hari ini dengan pola ID alternatif
            let isToday = false;
            if (ord.timestamp) {
                const d = new Date(ord.timestamp);
                if (d.getDate() === now.getDate() && d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear()) {
                    isToday = true;
                }
            }
            if (!isToday && ord.tanggal) {
                const dStr = String(ord.tanggal);
                if (dStr.includes(`${dd}/${mm}`) || dStr.includes(`${dd}-${mm}`) || dStr.startsWith(`${dd}`)) {
                    isToday = true;
                }
            }
            if (isToday) {
                const endMatch = ordId.match(/(\d{3})$/);
                if (endMatch) {
                    const seqPart = parseInt(endMatch[1], 10);
                    if (!isNaN(seqPart) && seqPart > highestSeq) {
                        highestSeq = seqPart;
                    }
                }
            }
        }
    };

    if (window.globalOrders && typeof window.globalOrders === 'object') {
        Object.values(window.globalOrders).forEach(checkOrder);
    }
    try {
        const offline = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (Array.isArray(offline)) offline.forEach(checkOrder);
    } catch (e) {}

    // Urutan berikutnya tepat 1 angka di atas nomor urut tertinggi hari ini (1 -> 2 -> 3)
    const nextSeq = Math.max(highestSeq + 1, 1);
    const seqStr = String(nextSeq).padStart(3, '0');

    return `${prefix}-${ddmm}${seqStr}`;
};

// ==========================================
// PUSAT PROFIL & AVATAR KASIR BERTUGAS (HRD & STRUK)
// ==========================================
window.persistKasirAvatarThumbnail = (namaKasir, rawPhoto) => {
    const cleanFoto = (typeof rawPhoto === 'string' && rawPhoto.trim() !== '' && rawPhoto !== 'logo-192.png') ? rawPhoto.trim() : '';
    const cleanName = String(namaKasir || '').replace(/\s*\(\s*master\s*\)/i, '').trim();
    if (!cleanName || !cleanFoto) return;

    const saveCache = (photoStr) => {
        try {
            localStorage.setItem('mainstay_active_kasir_photo', JSON.stringify({
                name: cleanName,
                photo: photoStr,
                ts: Date.now()
            }));
        } catch (_) {}
    };

    if (!cleanFoto.startsWith('data:image/') || cleanFoto.length <= 65000) {
        saveCache(cleanFoto);
        return;
    }

    try {
        const img = new Image();
        img.onload = () => {
            try {
                const maxDim = 160;
                const scale = Math.min(1, maxDim / Math.max(img.width || maxDim, img.height || maxDim));
                const canvas = document.createElement('canvas');
                canvas.width = Math.max(64, Math.round((img.width || maxDim) * scale));
                canvas.height = Math.max(64, Math.round((img.height || maxDim) * scale));
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                    const thumb = canvas.toDataURL('image/jpeg', 0.72);
                    if (thumb) saveCache(thumb);
                }
            } catch (_) {}
        };
        img.src = cleanFoto;
    } catch (_) {}
};

window.getKasirProfileData = (namaKasir) => {
    let targetName = (namaKasir || '').trim();
    if (!targetName) {
        const storedRole = localStorage.getItem('mainstay_session_role');
        const storedStaff = localStorage.getItem('mainstay_staff_name');
        if (storedStaff && storedStaff.trim() !== '' && storedRole !== 'owner') {
            targetName = storedStaff.trim();
        } else if (storedRole === 'owner') {
            targetName = 'Owner';
        } else if (window.activeStaff?.name) {
            targetName = window.activeStaff.name.trim();
        } else if (storedStaff && storedStaff.trim() !== '') {
            targetName = storedStaff.trim();
        } else {
            const elTxt = (document.getElementById('kasir-active-name')?.innerText || '').trim();
            targetName = elTxt || 'Owner';
        }
    }

    targetName = targetName.replace(/\s*\(\s*master\s*\)/i, '').trim();
    const cleanTarget = targetName.toLowerCase();
    const isValidPhoto = (p) => typeof p === 'string' && p.trim() !== '' && p.trim() !== 'logo-192.png';
    const pickPhoto = (obj) => {
        if (!obj || typeof obj !== 'object') return '';
        const candidates = [obj.photo, obj.foto, obj.avatar, obj.faceData, obj.imageUrl];
        for (const c of candidates) {
            if (isValidPhoto(c)) return c.trim();
        }
        return '';
    };

    let resolvedName = targetName;
    let resolvedRole = 'Kasir';
    let resolvedPhoto = '';
    let resolvedPin = window.activeStaff?.pin || '';
    let isStaffFlag = false;
    let isOwnerFlag = false;

    // 1. Cek dari database staff efektif (RTDB + IndexedDB cabang/pusat)
    const effectiveStaff = (typeof window.getEffectiveBranchStaffMap === 'function')
        ? window.getEffectiveBranchStaffMap()
        : (typeof globalStaff === 'object' && globalStaff ? globalStaff : {});

    if (effectiveStaff && typeof effectiveStaff === 'object') {
        const activePin = String(window.activeStaff?.pin || '').trim();
        for (const key in effectiveStaff) {
            const s = effectiveStaff[key];
            if (!s) continue;
            const sName = String(s.name || s.nama || '').trim();
            const sPin = String(s.pin || '').trim();
            const matchByName = sName && sName.toLowerCase() === cleanTarget;
            const matchByPin = !matchByName && activePin && sPin && activePin === sPin && cleanTarget !== 'owner';
            if (matchByName || matchByPin) {
                resolvedName = sName || targetName;
                resolvedRole = s.role || s.tipeKaryawan || s.jabatan || 'Staff Kasir';
                resolvedPhoto = pickPhoto(s);
                resolvedPin = s.pin || resolvedPin;
                isStaffFlag = true;
                break;
            }
        }
    }

    // 2. Cek Master Owner HRD Profil (globalMasterOwner) jika Owner / cocok nama owner
    if (!isStaffFlag && (cleanTarget === 'owner' || cleanTarget.includes('owner'))) {
        resolvedName = 'Owner';
        resolvedRole = 'Owner';
        resolvedPin = resolvedPin || '888888';
        isOwnerFlag = true;
        if (typeof globalMasterOwner === 'object' && globalMasterOwner) {
            for (const key in globalMasterOwner) {
                const o = globalMasterOwner[key];
                if (!o) continue;
                const oPhoto = pickPhoto(o);
                if (oPhoto) resolvedPhoto = oPhoto;
                if (o.pin) resolvedPin = o.pin;
                if (resolvedPhoto) break;
            }
        }
    } else if (!isStaffFlag && typeof globalMasterOwner === 'object' && globalMasterOwner) {
        for (const key in globalMasterOwner) {
            const o = globalMasterOwner[key];
            if (!o) continue;
            const oName = String(o.name || o.nama || '').replace(/\s*\(\s*master\s*\)/i, '').trim();
            if (oName && (oName.toLowerCase() === cleanTarget || cleanTarget.includes(oName.toLowerCase()))) {
                resolvedName = 'Owner';
                resolvedRole = 'Owner';
                resolvedPhoto = pickPhoto(o);
                resolvedPin = o.pin || resolvedPin;
                isOwnerFlag = true;
                break;
            }
        }
    }

    // 3. Fallback ke window.activeStaff jika photo masih kosong dan nama cocok
    if (!resolvedPhoto && window.activeStaff) {
        const activeName = String(window.activeStaff.name || window.activeStaff.nama || '').replace(/\s*\(\s*master\s*\)/i, '').trim().toLowerCase();
        if (!activeName || activeName === cleanTarget || cleanTarget === resolvedName.toLowerCase()) {
            const activePic = pickPhoto(window.activeStaff);
            if (activePic) resolvedPhoto = activePic;
            if (!isStaffFlag && !isOwnerFlag && window.activeStaff.name) {
                resolvedName = String(window.activeStaff.name).replace(/\s*\(\s*master\s*\)/i, '').trim();
                resolvedRole = window.activeStaff.role || 'Kasir';
            }
        }
    }

    // 4. Fallback ke foto selfie Absensi Masuk hari ini (todayAttendanceCache)
    if (!resolvedPhoto && Array.isArray(window.todayAttendanceCache) && window.todayAttendanceCache.length > 0) {
        const matchedLogs = window.todayAttendanceCache.filter(l => {
            if (!l) return false;
            const lName = String(l.nama || l.name || '').replace(/\s*\(\s*master\s*\)/i, '').trim().toLowerCase();
            const lPin = String(l.pin || '').trim();
            const pinMatch = resolvedPin && lPin && String(resolvedPin).trim() === lPin;
            return (lName && lName === cleanTarget) || pinMatch;
        }).sort((a, b) => Number(b.timestamp || 0) - Number(a.timestamp || 0));

        const masukWithPhoto = matchedLogs.find(l => l.tipe === 'Masuk' && pickPhoto(l)) || matchedLogs.find(l => pickPhoto(l));
        if (masukWithPhoto) {
            resolvedPhoto = pickPhoto(masukWithPhoto);
        }
    }

    // 5. Fallback ke thumbnail foto kasir aktif di localStorage (bertahan saat refresh / koneksi lambat)
    if (!resolvedPhoto) {
        try {
            const rawSavedPhoto = localStorage.getItem('mainstay_active_kasir_photo');
            if (rawSavedPhoto) {
                const parsedPhoto = JSON.parse(rawSavedPhoto);
                const savedName = String(parsedPhoto?.name || '').trim().toLowerCase();
                if (savedName && savedName === cleanTarget && isValidPhoto(parsedPhoto?.photo)) {
                    resolvedPhoto = parsedPhoto.photo.trim();
                }
            }
        } catch (_) {}
    }

    // Simpan thumbnail ke cache jika berhasil ditemukan
    if (resolvedPhoto) {
        window.persistKasirAvatarThumbnail(resolvedName, resolvedPhoto);
    }

    return {
        name: resolvedName.toLowerCase() === 'owner' ? 'Owner' : resolvedName,
        role: isOwnerFlag ? 'Owner' : (resolvedRole || 'Kasir'),
        photo: resolvedPhoto || '',
        pin: resolvedPin || '',
        isStaff: isStaffFlag,
        isOwner: isOwnerFlag
    };
};

window.updateKasirActiveProfileUI = (namaKasir) => {
    const profile = window.getKasirProfileData(namaKasir);

    // 1. Update elemen teks nama kasir (bebas dari teks (Master))
    const cleanName = profile.name === 'Owner' ? 'Owner' : profile.name;
    const elNama = document.getElementById('kasir-active-name');
    if (elNama) elNama.innerText = cleanName;
    const petEl = document.getElementById('kasir-nama-petugas');
    if (petEl) petEl.innerText = cleanName === 'Owner' ? 'Owner Bertugas' : `${cleanName} Bertugas`;

    // 2. Update avatar kasir di tab Kasir (Header)
    const imgEl = document.getElementById('kasir-active-avatar-img');
    const iconEl = document.getElementById('kasir-active-avatar-icon');
    if (imgEl) {
        const fotoUrl = (profile.photo && profile.photo.trim() !== '' && profile.photo !== 'logo-192.png') ? profile.photo.trim() : '';
        if (fotoUrl) {
            imgEl.onerror = () => {
                imgEl.classList.add('hidden');
                if (iconEl) iconEl.classList.remove('hidden');
            };
            if (imgEl.getAttribute('src') !== fotoUrl) {
                imgEl.src = fotoUrl;
            }
            imgEl.alt = `Foto ${cleanName}`;
            imgEl.classList.remove('hidden');
            if (iconEl) iconEl.classList.add('hidden');
        } else {
            imgEl.onerror = null;
            imgEl.classList.add('hidden');
            if (iconEl) iconEl.classList.remove('hidden');

            // Jika belum ketemu, tarik log absensi hari ini sekali dari Firebase (jika punya foto selfie absen masuk)
            if (!window._kasirAttendancePhotoFetched && navigator.onLine && typeof get === 'function' && typeof ref === 'function') {
                window._kasirAttendancePhotoFetched = true;
                const now = new Date();
                const tglHariIni = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
                get(ref(db, `attendance/${tglHariIni}`)).then((snap) => {
                    if (snap && snap.exists()) {
                        window.todayAttendanceCache = Object.values(snap.val() || {});
                        window.updateKasirActiveProfileUI(cleanName);
                    }
                }).catch(() => {});
            }
        }
    }
};

