window.bukaGantiKasir = () => {
    const modal = document.getElementById('modal-ganti-kasir');
    const select = document.getElementById('select-ganti-kasir');
    
    // Reset Form
    document.getElementById('pin-ganti-kasir').value = '';
    modal.classList.remove('hidden');
    select.innerHTML = '<option value="">Memuat data staff...</option>';

    const tglSekarang = new Date().toLocaleDateString('id-ID', {year: 'numeric', month: '2-digit', day: '2-digit'}).split('/').reverse().join('-');

    get(ref(db, `attendance/${tglSekarang}`))
        .then(snap => (snap && snap.exists() ? snap.val() : null))
        .then(data => {
            let optionsHtml = `<option value="Owner">👑 Owner</option>`; 
            let staffHadir = new Set(); 

            if(data) {
                Object.values(data).forEach(log => {
                    if(log.tipe === 'Masuk' && log.nama) staffHadir.add(log.nama);
                });
            }

            staffHadir.forEach(nama => {
                optionsHtml += `<option value="${nama}">👤 ${nama} (Hadir)</option>`;
            });

            // Juga tampilkan karyawan lain dari globalStaff jika belum absen tapi terdaftar di HRD
            if (typeof globalStaff === 'object' && globalStaff) {
                Object.values(globalStaff).forEach(s => {
                    if (s && s.name && !staffHadir.has(s.name)) {
                        optionsHtml += `<option value="${s.name}">👤 ${s.name}</option>`;
                    }
                });
            }

            select.innerHTML = optionsHtml;
        }).catch(e => {
            let optionsHtml = `<option value="Owner">👑 Owner</option>`;
            if (typeof globalStaff === 'object' && globalStaff) {
                Object.values(globalStaff).forEach(s => {
                    if (s && s.name) {
                        optionsHtml += `<option value="${s.name}">👤 ${s.name}</option>`;
                    }
                });
            }
            select.innerHTML = optionsHtml;
        });
};

window.prosesGantiKasir = () => {
    const namaDipilih = document.getElementById('select-ganti-kasir').value;
    const pinInput = document.getElementById('pin-ganti-kasir').value.trim();

    if(!namaDipilih) return alert("Peringatan: Pilih nama penginput terlebih dahulu!");
    if(pinInput.length !== 6) return alert("Peringatan: Masukkan 6 digit PIN dengan benar!");

    if(namaDipilih === "Owner") {
        const masterPIN = "888888";
        let isOwnerPinValid = (pinInput === masterPIN);
        if (!isOwnerPinValid && typeof globalMasterOwner === 'object' && globalMasterOwner) {
            for (const k in globalMasterOwner) {
                if (String(globalMasterOwner[k]?.pin) === pinInput) {
                    isOwnerPinValid = true;
                    break;
                }
            }
        }
        
        if(isOwnerPinValid) {
            const ownerProf = window.getKasirProfileData("Owner");
            document.getElementById('kasir-active-name').innerText = "Owner";
            window.safeSetItem('mainstay_staff_name', "Owner");
            activeStaff = { name: "Owner", role: "owner", pin: pinInput };
            window.safeSetItem('mainstay_session_staff', JSON.stringify(activeStaff));
            
            window.updateKasirActiveProfileUI("Owner");
            document.getElementById('modal-ganti-kasir').classList.add('hidden');
            alert("Berhasil! Penginput dialihkan ke Owner.");
        } else {
            alert("Gagal: PIN Owner Salah!");
        }
        
    } else {
        let staffValid = null;
        for (const key in globalStaff) {
            if (globalStaff[key].name === namaDipilih && String(globalStaff[key].pin).trim() === pinInput) {
                staffValid = { ...globalStaff[key], key: key };
                break;
            }
        }

        if(staffValid) {
            const staffPic = staffValid.photo || staffValid.foto || staffValid.avatar || '';
            document.getElementById('kasir-active-name').innerText = staffValid.name;
            window.safeSetItem('mainstay_staff_name', staffValid.name);
            activeStaff = {
                name: staffValid.name,
                role: staffValid.tipeKaryawan || staffValid.role || 'Staff',
                pin: staffValid.pin,
                shiftIn: staffValid.shiftIn,
                shiftOut: staffValid.shiftOut,
                key: staffValid.key,
                photo: (staffPic && staffPic.length < 80000) ? staffPic : ''
            };
            window.activeStaff = activeStaff;
            window.safeSetItem('mainstay_session_staff', JSON.stringify(activeStaff));
            if (typeof window.persistKasirAvatarThumbnail === 'function' && staffPic) {
                window.persistKasirAvatarThumbnail(staffValid.name, staffPic);
            }

            window.updateKasirActiveProfileUI(staffValid.name);
            document.getElementById('modal-ganti-kasir').classList.add('hidden');
            alert(`Berhasil! Penginput dialihkan ke ${staffValid.name}.`);
        } else {
            alert(`Gagal: PIN tidak cocok dengan identitas ${namaDipilih}!`);
        }
    }
};

