// Cek apakah staf sedang 'Sedang Bertugas' (sudah absen masuk dan belum pulang) atau 'Libur'
window.cekStatusTugasStaf = (staffName, staffPin) => {
    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const tglHariIni = `${yyyy}-${mm}-${dd}`;

    let logs = [];
    if (window.todayAttendanceCache && window.todayAttendanceCache.length > 0) {
        logs = window.todayAttendanceCache;
    } else {
        try {
            const local = JSON.parse(localStorage.getItem('mainstay_attendance_local_logs') || '[]');
            logs = local.filter(l => l.tanggal === tglHariIni);
        } catch(e) {}
    }

    // Filter riwayat hari ini khusus untuk staf ini
    const staffLogs = logs.filter(item => {
        const matchName = item.nama && staffName && item.nama.trim().toLowerCase() === staffName.trim().toLowerCase();
        const matchPin = item.pin && staffPin && String(item.pin) === String(staffPin);
        return matchName || matchPin;
    });

    if (staffLogs.length === 0) {
        return {
            isOnDuty: false,
            hasClockedInToday: false,
            statusLabel: 'Libur',
            jamMasuk: null,
            jamPulang: null,
            latest: null
        };
    }

    // Urutkan riwayat dari yang paling baru
    staffLogs.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
    const latest = staffLogs[0];
    const masukRecord = staffLogs.find(l => l.tipe === 'Masuk');
    const pulangRecord = staffLogs.find(l => l.tipe === 'Pulang');

    const isOnDuty = latest.tipe === 'Masuk';
    return {
        isOnDuty: isOnDuty,
        hasClockedInToday: !!masukRecord,
        hasClockedOutToday: !!pulangRecord,
        statusLabel: isOnDuty ? 'Sedang Bertugas' : (pulangRecord ? 'Selesai Shift' : 'Libur'),
        jamMasuk: masukRecord ? (masukRecord.jam || masukRecord.waktu) : null,
        jamPulang: pulangRecord ? (pulangRecord.jam || pulangRecord.waktu) : null,
        latest: latest
    };
};

// Render daftar status staf pada panel absensi (Sedang Bertugas / Libur)
window.renderDaftarStatusStafAbsen = () => {
    const container = document.getElementById('daftar-status-staf-absen');
    const onDutyCountBadge = document.getElementById('staf-on-duty-count');
    if (!container) return;

    const effectiveStaff = typeof window.getEffectiveBranchStaffMap === 'function' ? window.getEffectiveBranchStaffMap() : (globalStaff || {});
    let staffEntries = Object.entries(effectiveStaff);
    if (staffEntries.length === 0 && !window.IS_BRANCH_OUTLET && window.defaultDemoStaff) {
        staffEntries = Object.entries(window.defaultDemoStaff);
    }

    if (staffEntries.length === 0) {
        container.innerHTML = `
            <div class="text-center py-3 bg-white rounded-xl border border-slate-100 p-2 text-slate-400 text-xs font-bold">
                ${window.IS_BRANCH_OUTLET ? 'Belum ada data staff terdaftar di cabang ini.' : 'Belum ada data staf terdaftar di sistem.'}
            </div>
        `;
        if (onDutyCountBadge) onDutyCountBadge.innerText = '0 Sedang Bertugas';
        return;
    }

    let onDutyCount = 0;
    let html = '';

    staffEntries.forEach(([key, s]) => {
        let staffName = s.name || s.nama || 'Karyawan';
        if (staffName === 'Kasir Utama') staffName = 'Ihsan';
        if (staffName === 'Barista Utama') staffName = 'Elmusaqi';
        const role = s.tipeKaryawan || s.role || 'Staff';
        const shiftIn = s.shiftIn || s.jamMasuk || (staffName === 'Ihsan' ? '14:00' : '08:00');
        const duty = window.cekStatusTugasStaf(staffName, s.pin);

        if (duty.isOnDuty) onDutyCount++;

        const photoSrc = s.photo || s.foto || s.faceData;
        const initials = staffName.slice(0, 2).toUpperCase();

        const avatar = photoSrc ? `
            <img src="${photoSrc}" class="w-8 h-8 rounded-full object-cover border border-slate-200 shrink-0">
        ` : `
            <div class="w-8 h-8 rounded-full bg-purple-100 text-purple-700 flex items-center justify-center font-black text-[10px] shrink-0 border border-purple-200">
                ${initials}
            </div>
        `;

        const statusBadge = duty.isOnDuty ? `
            <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300 shadow-2xs">
                <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> Sedang Bertugas
            </span>
        ` : `
            <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black bg-slate-100 text-slate-600 border border-slate-200">
                <span class="w-1.5 h-1.5 rounded-full bg-slate-400"></span> Libur
            </span>
        `;

        const subtext = duty.isOnDuty 
            ? `<span class="text-emerald-700 font-bold">Masuk: ${duty.jamMasuk || '-'} WIB</span>`
            : `<span class="text-slate-400">Shift: ${shiftIn} WIB</span>`;

        html += `
            <div onclick="window.pilihStaffDariRoster('${key}')" class="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-2.5 p-2.5 bg-white rounded-xl border border-slate-200/80 shadow-2xs hover:border-purple-300 hover:bg-purple-50/40 transition cursor-pointer active:scale-[0.99]" title="Klik untuk pilih staf">
                <div class="flex items-center gap-2.5 min-w-0">
                    ${avatar}
                    <div class="min-w-0">
                        <h5 class="text-xs font-black text-slate-800 leading-tight truncate">${staffName}</h5>
                        <p class="text-[9px] font-medium text-slate-500 truncate">${role} • ${subtext}</p>
                    </div>
                </div>
                <div class="shrink-0">
                    ${statusBadge}
                </div>
            </div>
        `;
    });

    container.innerHTML = html;
    if (onDutyCountBadge) {
        onDutyCountBadge.innerText = `${onDutyCount} Sedang Bertugas / ${staffEntries.length} Staf`;
    }
};

window.pilihStaffDariRoster = (staffKey) => {
    const effectiveStaff = typeof window.getEffectiveBranchStaffMap === 'function' ? window.getEffectiveBranchStaffMap() : (globalStaff || {});
    let s = effectiveStaff[staffKey] || (!window.IS_BRANCH_OUTLET && window.defaultDemoStaff && window.defaultDemoStaff[staffKey]);
    if (!s && !window.IS_BRANCH_OUTLET && window.globalMasterOwner && window.globalMasterOwner[staffKey]) {
        s = window.globalMasterOwner[staffKey];
    }
    const selectPin = document.getElementById('select-staff-absen');
    if (selectPin && staffKey) {
        selectPin.value = staffKey;
    }
    if (s && s.pin) {
        const pinEl = document.getElementById('pin-absensi-kamera');
        if (pinEl) pinEl.value = s.pin;
        window.handlePinInputAbsensi(s.pin);
    }
};

