window.cariStaffAbsensi = (pinInput) => {
    const cleanPin = String(pinInput || '').trim();
    if (!cleanPin) return null;

    // 1. Cek di database staff aktif (gabungan Firebase globalStaff + IndexedDB staff_records cabang aktif)
    const effectiveStaff = typeof window.getEffectiveBranchStaffMap === 'function'
        ? window.getEffectiveBranchStaffMap()
        : (globalStaff || {});
    let found = Object.values(effectiveStaff).find(s => s && String(s.pin) === cleanPin);
    if (found) return found;

    // Pada mode Cabang: STRICT ISOLATION - hanya staf yang terdaftar di cabang tersebut yang boleh absen
    if (window.IS_BRANCH_OUTLET) {
        return null;
    }

    // 2. Cek di globalMasterOwner (khusus Pusat)
    if (window.globalMasterOwner) {
        found = Object.values(window.globalMasterOwner || {}).find(o => o && String(o.pin) === cleanPin);
        if (found) return found;
    }

    // 3. Cek di defaultDemoStaff (Hanya di Pusat jika belum ada data HRD)
    if (Object.keys(effectiveStaff).length === 0 && window.defaultDemoStaff) {
        found = Object.values(window.defaultDemoStaff).find(d => String(d.pin) === cleanPin);
        if (found) return found;
    }

    // 4. Cek MASTER_PIN atau PIN default 888888 (khusus Pusat)
    const masterPin = String(typeof MASTER_PIN !== 'undefined' ? MASTER_PIN : "888888");
    if (cleanPin === masterPin || cleanPin === "888888") {
        return {
            name: 'Owner',
            pin: cleanPin,
            tipeKaryawan: 'Owner',
            role: 'Owner',
            shiftIn: '08:00',
            shiftOut: '22:00'
        };
    }

    return null;
};

// Handler perubahan input PIN (otomatis deteksi identitas staf saat 6 digit & auto kamera/kasir)
window.handlePinInputAbsensi = (pinVal) => {
    const cleanPin = String(pinVal || '').replace(/[^0-9]/g, '').slice(0, 6);
    const pinEl = document.getElementById('pin-absensi-kamera');
    if (pinEl && pinEl.value !== cleanPin) pinEl.value = cleanPin;
    
    const notifEl = document.getElementById('absen-error-notif');
    if (notifEl) notifEl.classList.add('hidden');

    const infoCard = document.getElementById('info-staff-terpilih-pin');
    const namaEl = document.getElementById('nama-staff-terpilih-pin');
    const shiftEl = document.getElementById('shift-staff-terpilih-pin');
    const roleEl = document.getElementById('role-staff-terpilih-pin');
    const imgEl = document.getElementById('img-staff-terpilih-pin');
    const initialEl = document.getElementById('initial-staff-terpilih-pin');
    const statusTugasBadge = document.getElementById('status-tugas-badge');
    const selectPin = document.getElementById('select-staff-absen');

    if (cleanPin.length === 6) {
        const staffData = window.cariStaffAbsensi(cleanPin);

        if (staffData) {
            // Cocokkan dropdown jika ada
            if (selectPin) {
                const matchOpt = Array.from(selectPin.options).find(opt => opt.text.includes(staffData.name));
                if (matchOpt) selectPin.value = matchOpt.value;
            }
            
            if (infoCard) {
                infoCard.classList.remove('hidden');
                infoCard.classList.add('flex');
            }
            if (namaEl) namaEl.innerText = staffData.name || 'Karyawan';
            if (shiftEl) shiftEl.innerText = `Shift Masuk: ${staffData.shiftIn || '08:00'} WIB`;
            if (roleEl) roleEl.innerText = staffData.tipeKaryawan || staffData.role || 'Staff';
            
            // Cek Status Tugas Saat Ini (Sedang Bertugas vs Libur)
            const duty = window.cekStatusTugasStaf(staffData.name, staffData.pin);
            if (statusTugasBadge) {
                if (duty.isOnDuty) {
                    statusTugasBadge.className = "inline-flex items-center gap-1 text-[9px] font-black px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 border border-emerald-300";
                    statusTugasBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> Sedang Bertugas`;
                } else {
                    statusTugasBadge.className = "inline-flex items-center gap-1 text-[9px] font-black px-2 py-0.5 rounded-full bg-slate-100 text-slate-600 border border-slate-300";
                    statusTugasBadge.innerHTML = `⚪ Libur`;
                }
            }

            const photoSrc = staffData.photo || staffData.foto;
            if (photoSrc && imgEl) {
                imgEl.src = photoSrc;
                imgEl.classList.remove('hidden');
                if (initialEl) initialEl.classList.add('hidden');
            } else {
                if (imgEl) imgEl.classList.add('hidden');
                if (initialEl) {
                    initialEl.classList.remove('hidden');
                    initialEl.innerText = (staffData.name || 'ST').slice(0, 2).toUpperCase();
                }
            }

            // ==============================================================
            // ALUR INPUT PIN 6-DIGIT (MANUAL CONFIRMATION):
            // Tidak auto-eksekusi! Menampilkan info staf & panduan tombol
            // Staf harus menekan tombol 'ABSEN MASUK' atau 'ABSEN PULANG'
            // ==============================================================
            window.activeStaff = staffData;

            if (duty.hasClockedOutToday) {
                if (notifEl) {
                    const msgEl = document.getElementById('absen-error-notif-msg');
                    if (msgEl) msgEl.innerText = `⛔ Shift Selesai: ${staffData.name} sudah melakukan Absen Pulang hari ini (Pukul ${duty.jamPulang || '-'}). Shift Anda telah berakhir.`;
                    notifEl.className = "w-full mb-2.5 p-3 bg-slate-100 border border-slate-300 rounded-xl text-slate-800 text-xs font-black flex items-center gap-2 shadow-xs transition";
                    notifEl.classList.remove('hidden');
                }
            } else if (duty.hasClockedInToday) {
                if (notifEl) {
                    const msgEl = document.getElementById('absen-error-notif-msg');
                    if (msgEl) msgEl.innerText = `✓ Terverifikasi: ${staffData.name} sedang bertugas (Masuk: ${duty.jamMasuk || '-'}). Tekan tombol ABSEN PULANG di bawah saat shift selesai.`;
                    notifEl.className = "w-full mb-2.5 p-3 bg-blue-50 border border-blue-300 rounded-xl text-blue-800 text-xs font-black flex items-center gap-2 shadow-xs transition";
                    notifEl.classList.remove('hidden');
                }
            } else {
                if (notifEl) {
                    const msgEl = document.getElementById('absen-error-notif-msg');
                    if (msgEl) msgEl.innerText = `✓ Terverifikasi: ${staffData.name} (${staffData.tipeKaryawan || staffData.role || 'Staff'}). Tekan tombol ABSEN MASUK di bawah untuk mulai bertugas.`;
                    notifEl.className = "w-full mb-2.5 p-3 bg-emerald-50 border border-emerald-300 rounded-xl text-emerald-800 text-xs font-black flex items-center gap-2 shadow-xs transition";
                    notifEl.classList.remove('hidden');
                }
            }
        } else {
            // PIN 6 digit tidak ditemukan
            if (infoCard) infoCard.classList.add('hidden');
            if (notifEl) {
                const msgEl = document.getElementById('absen-error-notif-msg');
                if (msgEl) msgEl.innerText = "⛔ PIN Salah: PIN tidak terdaftar di database karyawan!";
                notifEl.className = "w-full mb-2.5 p-3 bg-rose-50 border border-rose-300 rounded-xl text-rose-700 text-xs font-black flex items-center gap-2 shadow-xs transition";
                notifEl.classList.remove('hidden');
            }
        }
    } else if (cleanPin.length === 0) {
        if (selectPin && selectPin.value) {
            window.handleStaffSelectAbsen(selectPin.value, false);
        } else if (infoCard) {
            infoCard.classList.add('hidden');
        }
        if (notifEl) notifEl.classList.add('hidden');
    } else {
        // Kurang dari 6 digit -> sembunyikan notif
        if (notifEl) notifEl.classList.add('hidden');
    }
};

// ==========================================
// VALIDASI PIN & PEMICU KAMERA SELFIE ABSENSI
// ==========================================
window.submitAbsensiPIN = async (tipeAbsen) => {
    const pinInput = document.getElementById('pin-absensi-kamera')?.value?.trim();
    const notifEl = document.getElementById('absen-error-notif');
    const msgEl = document.getElementById('absen-error-notif-msg');

    const showNotif = (pesan, isError = true) => {
        if (notifEl) {
            notifEl.className = isError 
                ? "w-full mb-2.5 p-3 bg-rose-50 border border-rose-300 rounded-xl text-rose-700 text-xs font-black flex items-center gap-2 shadow-xs transition"
                : "w-full mb-2.5 p-3 bg-amber-50 border border-amber-300 rounded-xl text-amber-700 text-xs font-black flex items-center gap-2 shadow-xs transition";
            if (msgEl) msgEl.innerText = pesan;
            notifEl.classList.remove('hidden');
        }
    };

    if (!pinInput || pinInput.length !== 6) {
        showNotif("Peringatan: Ketik 6 digit PIN karyawan Anda di kolom PIN!");
        const pinEl = document.getElementById('pin-absensi-kamera');
        if (pinEl) pinEl.focus();
        return;
    }

    // Sinkronkan & validasi PIN terhadap IndexedDB staff_records cabang aktif + RTDB
    const branchId = window.ACTIVE_BRANCH_ID || 'pusat';
    if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.getBranchStaff === 'function') {
        await window.mainstayIndexedDB.getBranchStaff(branchId).catch(() => {});
    }

    // Cari staf berdasarkan PIN
    let staffAbsen = window.cariStaffAbsensi(pinInput);

    // Jika belum ketemu dari PIN murni, cek dropdown staf terpilih
    if (!staffAbsen) {
        const selectPin = document.getElementById('select-staff-absen');
        const selectedKey = selectPin?.value;
        const effectiveStaff = typeof window.getEffectiveBranchStaffMap === 'function' ? window.getEffectiveBranchStaffMap() : (globalStaff || {});
        if (selectedKey && effectiveStaff[selectedKey]) {
            const s = effectiveStaff[selectedKey];
            if (String(s.pin) === pinInput) {
                staffAbsen = s;
            }
        }
    }

    // VALIDASI 1: Notifikasi jika PIN salah atau staff cabang kosong
    if (!staffAbsen) {
        const effectiveStaff = typeof window.getEffectiveBranchStaffMap === 'function' ? window.getEffectiveBranchStaffMap() : (globalStaff || {});
        if (window.IS_BRANCH_OUTLET && Object.keys(effectiveStaff).length === 0) {
            showNotif("Akses Ditolak: Data staff cabang ini masih kosong! Tambahkan staff terlebih dahulu di menu HRD cabang.");
        } else {
            showNotif("Akses Ditolak: PIN salah atau belum terdaftar di data staff outlet ini!");
        }
        return;
    }

    // VALIDASI 2: Cek Izin Jadwal Shift (Dilarang Masuk/Absen sebelum 1 jam sebelum shift)
    const dutyStatus = typeof window.cekStatusTugasStaf === 'function' 
        ? window.cekStatusTugasStaf(staffAbsen.name, staffAbsen.pin) 
        : { hasClockedInToday: false, hasClockedOutToday: false, isOnDuty: false };

    if (tipeAbsen === 'Masuk') {
        const shiftCheck = typeof window.cekIzinShiftStaff === 'function' 
            ? window.cekIzinShiftStaff(staffAbsen) 
            : { allowed: true };
        if (!shiftCheck.allowed) {
            showNotif(`⛔ Akses Ditolak: Belum Waktu Shift!\n${shiftCheck.reason}`);
            return;
        }

        if (dutyStatus.hasClockedOutToday) {
            showNotif(`⛔ Shift Selesai: ${staffAbsen.name} sudah melakukan Absen Pulang hari ini (Pukul ${dutyStatus.jamPulang || '-'}). Tidak dapat absen masuk double di hari yang sama!`);
            return;
        }

        // Mencegah 'absen masuk' dua kali pada hari yang sama
        if (dutyStatus.hasClockedInToday) {
            showNotif(`⛔ Peringatan: ${staffAbsen.name} sudah melakukan 'Absen Masuk' hari ini (Pukul ${dutyStatus.jamMasuk || '-'}). Absen masuk tidak bisa double pada hari yang sama!`);
            return;
        }
    } else if (tipeAbsen === 'Pulang') {
        if (!dutyStatus.hasClockedInToday) {
            showNotif(`⛔ Peringatan: ${staffAbsen.name} belum melakukan Absen Masuk hari ini. Pastikan Anda melakukan absen masuk terlebih dahulu sebelum absen pulang.`);
            return;
        }
        if (dutyStatus.hasClockedOutToday) {
            showNotif(`⛔ Peringatan: ${staffAbsen.name} sudah melakukan Absen Pulang hari ini (Pukul ${dutyStatus.jamPulang || '-'}). Absen pulang tidak bisa double pada hari yang sama!`);
            return;
        }

        // CEK APAKAH ABSEN PULANG SEBELUM JADWAL SHIFT SELESAI
        const shiftOut = staffAbsen.shiftOut || (window.storeSettings && window.storeSettings.jam_tutup) || '22:00';
        if (shiftOut && shiftOut.includes(':')) {
            const [outH, outM] = shiftOut.split(':').map(v => parseInt(v, 10));
            const now = new Date();
            const nowMins = now.getHours() * 60 + now.getMinutes();
            const shiftOutMins = outH * 60 + outM;

            // Jika waktu sekarang masih sebelum jadwal selesai -> Wajib verifikasi izin Owner!
            if (nowMins < shiftOutMins && typeof window.bukaModalIzinPulangAwal === 'function') {
                window.bukaModalIzinPulangAwal(staffAbsen, pinInput, shiftOut);
                return;
            }
        }
    }

    // Bersihkan notifikasi error
    if (notifEl) notifEl.classList.add('hidden');

    // VALIDASI LOLOS -> NYALAKAN KAMERA UNTUK SELFIE BUKTI KEHADIRAN
    await window.bukaKameraAbsensi(staffAbsen, tipeAbsen, pinInput);
};

// ==========================================
// KONTROL KAMERA (MODAL & INLINE CARD)
// ==========================================
window.currentFacingMode = 'user';

window.toggleCameraFacingMode = async () => {
    window.currentFacingMode = (window.currentFacingMode === 'user' ? 'environment' : 'user');
    if (window.pendingAbsensi) {
        const { staff, tipe, pin } = window.pendingAbsensi;
        await window.bukaKameraAbsensi(staff, tipe, pin);
    } else {
        await window.tesNyalakanKameraInline();
    }
};

window.tesNyalakanKameraInline = async () => {
    const inlineVideo = document.getElementById('inline-attendance-video');
    const placeholder = document.getElementById('inline-camera-placeholder');
    const loading = document.getElementById('inline-camera-loading');
    const overlay = document.getElementById('inline-camera-overlay');
    const controls = document.getElementById('inline-camera-controls');
    const badgeDot = document.getElementById('badge-kamera-inline-dot');
    const badgeStatus = document.getElementById('badge-kamera-inline-status');
    const tipeBadge = document.getElementById('inline-camera-tipe-badge');

    if (loading) loading.classList.remove('hidden');
    if (placeholder) placeholder.classList.add('hidden');

    try {
        window.matikanKameraAbsensi();
        if (!navigator?.mediaDevices?.getUserMedia) {
            throw new Error("Perangkat atau peramban tidak mendukung WebRTC camera.");
        }
        const stream = await navigator.mediaDevices.getUserMedia({
            video: {
                facingMode: window.currentFacingMode,
                width: { ideal: 640 },
                height: { ideal: 480 }
            },
            audio: false
        });

        window.streamKameraAbsensi = stream;
        if (inlineVideo) {
            inlineVideo.srcObject = stream;
            inlineVideo.classList.remove('hidden');
            await inlineVideo.play();
        }
        if (loading) loading.classList.add('hidden');
        if (overlay) overlay.classList.remove('hidden');
        if (controls) controls.classList.remove('hidden');
        if (tipeBadge) tipeBadge.innerText = "TES KAMERA LIVE";
        if (badgeDot) badgeDot.className = "w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse";
        if (badgeStatus) {
            badgeStatus.className = "text-[9px] font-black px-2 py-0.5 rounded-full bg-emerald-950 text-emerald-300 border border-emerald-700";
            badgeStatus.innerText = "🟢 Kamera Aktif";
        }
    } catch (err) {
        console.warn("Akses kamera gagal:", err);
        if (loading) loading.classList.add('hidden');
        if (placeholder) {
            placeholder.classList.remove('hidden');
            placeholder.innerHTML = `
                <div class="w-10 h-10 shrink-0 rounded-full bg-rose-500/20 text-rose-400 flex items-center justify-center text-lg mb-1.5">
                    <i class="fa-solid fa-camera-slash"></i>
                </div>
                <p class="text-xs font-black text-rose-400 mb-0.5">Kamera Tidak Dapat Diakses</p>
                <p class="text-[10px] text-slate-400 max-w-xs mb-2">${err.message || 'Izin kamera ditolak atau hardware tidak ditemukan'}</p>
                <button type="button" onclick="window.tesNyalakanKameraInline()" class="text-[10px] font-bold bg-slate-800 text-amber-300 px-2.5 py-1 rounded-lg border border-slate-700">
                    Coba Lagi
                </button>
            `;
        }
    }
};

// ==========================================
// NYALAKAN KAMERA SETELAH PIN TERVERIFIKASI
// ==========================================
window.bukaKameraAbsensi = async (staffAbsen, tipeAbsen, pinInput) => {
    // VALIDASI KETAT SHIFT: Dilarang absen masuk jika belum 1 jam sebelum jadwal shift
    if (tipeAbsen === 'Masuk') {
        const shiftCheck = typeof window.cekIzinShiftStaff === 'function' 
            ? window.cekIzinShiftStaff(staffAbsen) 
            : { allowed: true };
        if (!shiftCheck.allowed) {
            alert(`⛔ AKSES DITOLAK: BELUM WAKTU SHIFT\n\n${shiftCheck.reason}\n\nSilakan kembali mendekati jadwal shift Anda.`);
            return;
        }
    }

    window.pendingAbsensi = {
        staff: staffAbsen,
        tipe: tipeAbsen,
        pin: pinInput
    };

    // Update Inline Viewfinder Elements
    const inlineVideo = document.getElementById('inline-attendance-video');
    const inlinePlaceholder = document.getElementById('inline-camera-placeholder');
    const inlineLoading = document.getElementById('inline-camera-loading');
    const inlineOverlay = document.getElementById('inline-camera-overlay');
    const inlineControls = document.getElementById('inline-camera-controls');
    const inlineBadgeDot = document.getElementById('badge-kamera-inline-dot');
    const inlineBadgeStatus = document.getElementById('badge-kamera-inline-status');
    const inlineTipeBadge = document.getElementById('inline-camera-tipe-badge');

    // Update Modal Viewfinder Elements (z-[1100])
    const modal = document.getElementById('modal-absensi');
    const badgeTipe = document.getElementById('camera-absen-tipe-badge');
    const staffNameEl = document.getElementById('camera-absen-staff-name');
    const cameraLoading = document.getElementById('camera-loading');
    const modalVideo = document.getElementById('attendance-video');

    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }

    if (badgeTipe) {
        if (tipeAbsen === 'Masuk') {
            badgeTipe.className = "px-3.5 py-1 rounded-full text-xs font-black uppercase tracking-wider bg-emerald-600 text-white shadow-md flex items-center gap-1.5";
            badgeTipe.innerHTML = `<i class="fa-solid fa-right-to-bracket"></i> ABSEN MASUK`;
        } else {
            badgeTipe.className = "px-3.5 py-1 rounded-full text-xs font-black uppercase tracking-wider bg-amber-600 text-white shadow-md flex items-center gap-1.5";
            badgeTipe.innerHTML = `<i class="fa-solid fa-right-from-bracket"></i> ABSEN PULANG`;
        }
    }

    if (inlineTipeBadge) {
        inlineTipeBadge.className = tipeAbsen === 'Masuk' 
            ? "px-2.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider bg-emerald-600 text-white shadow"
            : "px-2.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider bg-amber-600 text-white shadow";
        inlineTipeBadge.innerText = `ABSEN ${tipeAbsen.toUpperCase()}`;
    }

    if (staffNameEl) {
        staffNameEl.innerHTML = `<i class="fa-solid fa-user-check text-emerald-400 mr-1.5"></i> ${staffAbsen.name || 'Karyawan'} <span class="text-xs text-gray-400 font-bold">(${staffAbsen.tipeKaryawan || staffAbsen.role || 'Staff'})</span>`;
    }

    if (cameraLoading) {
        cameraLoading.innerHTML = `
            <i class="fa-solid fa-circle-notch fa-spin text-2xl text-amber-400"></i>
            <span>Menyalakan Kamera...</span>
        `;
        cameraLoading.classList.remove('hidden');
    }
    if (modalVideo) modalVideo.classList.add('hidden');
    if (inlineLoading) inlineLoading.classList.remove('hidden');
    if (inlinePlaceholder) inlinePlaceholder.classList.add('hidden');

    try {
        window.matikanKameraAbsensi();
        if (!navigator?.mediaDevices?.getUserMedia) {
            throw new Error("Peramban tidak mendukung akses kamera WebRTC.");
        }
        const stream = await navigator.mediaDevices.getUserMedia({
            video: {
                facingMode: window.currentFacingMode,
                width: { ideal: 640 },
                height: { ideal: 480 }
            },
            audio: false
        });

        window.streamKameraAbsensi = stream;

        // Pasang stream ke Modal Video
        if (modalVideo) {
            modalVideo.srcObject = stream;
            modalVideo.classList.remove('hidden');
            if (cameraLoading) cameraLoading.classList.add('hidden');
            await modalVideo.play().catch(e => console.warn(e));
        }

        // Pasang stream ke Inline Video
        if (inlineVideo) {
            inlineVideo.srcObject = stream;
            inlineVideo.classList.remove('hidden');
            if (inlineLoading) inlineLoading.classList.add('hidden');
            if (inlineOverlay) inlineOverlay.classList.remove('hidden');
            if (inlineControls) inlineControls.classList.remove('hidden');
            await inlineVideo.play().catch(e => console.warn(e));
        }

        if (inlineBadgeDot) inlineBadgeDot.className = "w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse";
        if (inlineBadgeStatus) {
            inlineBadgeStatus.className = "text-[9px] font-black px-2 py-0.5 rounded-full bg-emerald-950 text-emerald-300 border border-emerald-700";
            inlineBadgeStatus.innerText = "🟢 Siap Jepret";
        }
    } catch (err) {
        console.warn("Akses kamera tidak tersedia:", err);
        if (cameraLoading) {
            cameraLoading.innerHTML = `
                <div class="flex flex-col items-center gap-2 p-3 text-center">
                    <i class="fa-solid fa-camera-slash text-3xl text-amber-400"></i>
                    <p class="text-xs font-black text-white">Kamera Tidak Tersedia</p>
                    <p class="text-[10px] text-slate-400 max-w-xs">${err.message || 'Hardware kamera tidak terhubung atau izin belum diberikan.'}</p>
                    <button type="button" onclick="window.simpanAbsenTanpaKameraFallback()" class="mt-2 px-4 py-2 bg-amber-500 hover:bg-amber-600 text-slate-950 font-black rounded-xl text-xs uppercase shadow-md transition active:scale-95">
                        <i class="fa-solid fa-check"></i> Tetap Lanjutkan Absen
                    </button>
                </div>
            `;
            cameraLoading.classList.remove('hidden');
        }
        if (inlineLoading) inlineLoading.classList.add('hidden');
        if (inlinePlaceholder) {
            inlinePlaceholder.classList.remove('hidden');
            inlinePlaceholder.innerHTML = `
                <p class="text-xs font-bold text-amber-300 mb-1">Akses Kamera Terkendala</p>
                <p class="text-[10px] text-slate-400 mb-2">${err.message || 'Izin kamera dibutuhkan'}</p>
                <button type="button" onclick="window.simpanAbsenTanpaKameraFallback()" class="text-[10px] font-bold bg-amber-500 text-slate-900 px-3 py-1.5 rounded-lg shadow">
                    Lanjut Tanpa Foto
                </button>
            `;
        }
    }
};

// Fallback simpan absensi jika kamera hardware tidak tersedia
window.simpanAbsenTanpaKameraFallback = async () => {
    if (!window.pendingAbsensi) return;
    const { staff, tipe } = window.pendingAbsensi;
    window.closeModalAbsensi();
    await window.eksekusiSimpanAbsensi(staff, tipe, staff.photo || staff.foto || null);
};

// ==========================================
// JEPRET FOTO & OTOMATIS TERINPUT DATANYA
// ==========================================
window.jepretFotoAbsensiKamera = async () => {
    if (!window.pendingAbsensi) {
        // Jika belum ada sesi pending, cek apakah PIN sudah diketik
        const pinInput = document.getElementById('pin-absensi-kamera')?.value?.trim();
        if (pinInput && pinInput.length === 6) {
            await window.submitAbsensiPIN('Masuk');
            return;
        }
        const notifEl = document.getElementById('absen-error-notif');
        const msgEl = document.getElementById('absen-error-notif-msg');
        if (notifEl && msgEl) {
            msgEl.innerText = "Ketik 6 digit PIN karyawan Anda terlebih dahulu lalu tekan Absen Masuk/Pulang!";
            notifEl.className = "w-full mb-2.5 p-3 bg-amber-50 border border-amber-300 rounded-xl text-amber-700 text-xs font-black flex items-center gap-2 shadow-xs transition";
            notifEl.classList.remove('hidden');
        }
        window.closeModalAbsensi();
        return;
    }

    const { staff, tipe } = window.pendingAbsensi;
    const modalVideo = document.getElementById('attendance-video');
    const inlineVideo = document.getElementById('inline-attendance-video');
    
    // Pilih video yang sedang aktif dan punya feed
    const activeVideo = (modalVideo && modalVideo.srcObject && modalVideo.readyState >= 2) 
        ? modalVideo 
        : (inlineVideo && inlineVideo.srcObject && inlineVideo.readyState >= 2 ? inlineVideo : null);

    let fotoBase64 = null;

    if (activeVideo) {
        try {
            const canvas = document.getElementById('canvas-absensi') || document.createElement('canvas');
            // Optimasi resolusi canvas selfie (360x270, JPEG 0.65) agar ukuran file hanya ~15-20 KB
            canvas.width = 360;
            canvas.height = 270;
            const ctx = canvas.getContext('2d');
            
            // Mirror selfie agar tampilan jepret sesuai pandangan pengguna
            ctx.translate(canvas.width, 0);
            ctx.scale(-1, 1);
            ctx.drawImage(activeVideo, 0, 0, canvas.width, canvas.height);
            fotoBase64 = canvas.toDataURL('image/jpeg', 0.65);
        } catch (e) {
            console.warn("Gagal capture gambar selfie:", e);
        }
    }

    // Jika capture video tidak tersedia, buat kartu avatar absensi digital berstempel waktu
    if (!fotoBase64) {
        try {
            const canvas = document.getElementById('canvas-absensi') || document.createElement('canvas');
            canvas.width = 300;
            canvas.height = 300;
            const ctx = canvas.getContext('2d');
            
            // Background Gradasi
            const grad = ctx.createLinearGradient(0, 0, 300, 300);
            grad.addColorStop(0, '#1e293b');
            grad.addColorStop(1, '#0f172a');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, 300, 300);
            
            // Lingkaran Avatar
            ctx.fillStyle = '#6366f1';
            ctx.beginPath();
            ctx.arc(150, 120, 55, 0, Math.PI * 2);
            ctx.fill();
            
            // Inisial
            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 36px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText((staff.name || 'ST').slice(0, 2).toUpperCase(), 150, 120);
            
            // Teks Nama
            ctx.fillStyle = '#f8fafc';
            ctx.font = 'bold 18px sans-serif';
            ctx.fillText(staff.name || 'Karyawan', 150, 205);
            
            // Badge Terverifikasi
            ctx.fillStyle = '#10b981';
            ctx.font = 'bold 12px sans-serif';
            ctx.fillText(`✓ PIN TERVERIFIKASI (${tipe})`, 150, 235);
            
            // Jam Live
            ctx.fillStyle = '#94a3b8';
            ctx.font = '11px sans-serif';
            ctx.fillText(new Date().toLocaleTimeString('id-ID') + ' WIB', 150, 260);
            
            fotoBase64 = canvas.toDataURL('image/jpeg', 0.7);
        } catch(e) {}
    }

    // Matikan kamera & tutup modal
    window.closeModalAbsensi();

    // Otomatis langsung simpan data absensi
    await window.eksekusiSimpanAbsensi(staff, tipe, fotoBase64);
};

// Eksekusi penyimpanan data absensi ke Firebase & lokal
window.eksekusiSimpanAbsensi = async (staffAbsen, tipeAbsen, fotoBase64) => {
    const dutyStatus = typeof window.cekStatusTugasStaf === 'function' 
        ? window.cekStatusTugasStaf(staffAbsen.name, staffAbsen.pin) 
        : { hasClockedInToday: false, hasClockedOutToday: false, isOnDuty: false };

    if (tipeAbsen === 'Masuk') {
        if (dutyStatus.hasClockedInToday) {
            alert(`⛔ GAGAL ABSEN: ${staffAbsen.name} sudah melakukan Absen Masuk hari ini (${dutyStatus.jamMasuk || ''}).\n\nAbsen masuk tidak bisa double pada hari yang sama!`);
            return;
        }
        const shiftCheck = typeof window.cekIzinShiftStaff === 'function' 
            ? window.cekIzinShiftStaff(staffAbsen) 
            : { allowed: true };
        if (!shiftCheck.allowed) {
            alert(`⛔ GAGAL ABSEN: BELUM WAKTU SHIFT\n\n${shiftCheck.reason}`);
            return;
        }
    } else if (tipeAbsen === 'Pulang') {
        if (!dutyStatus.hasClockedInToday) {
            alert(`⛔ GAGAL ABSEN: ${staffAbsen.name} belum melakukan Absen Masuk hari ini. Pastikan Anda melakukan absen masuk terlebih dahulu sebelum absen pulang.`);
            return;
        }
        if (dutyStatus.hasClockedOutToday) {
            alert(`⛔ GAGAL ABSEN: ${staffAbsen.name} sudah melakukan Absen Pulang hari ini (${dutyStatus.jamPulang || ''}).\n\nAbsen pulang tidak bisa double pada hari yang sama!`);
            return;
        }
    }

    const now = new Date();
    const jamStr = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    let statusAbsen = "TEPAT WAKTU";
    let warnaStatus = "green";

    if (tipeAbsen === 'Masuk' && staffAbsen.shiftIn) {
        const shiftTime = staffAbsen.shiftIn.split(':');
        const shiftMins = parseInt(shiftTime[0]) * 60 + parseInt(shiftTime[1]);
        const nowMins = now.getHours() * 60 + now.getMinutes();
        if (nowMins > shiftMins) {
            statusAbsen = "TERLAMBAT";
            warnaStatus = "red";
        }
    } else if (tipeAbsen === 'Pulang') {
        if (window.pendingEarlyDepartureData && window.pendingEarlyDepartureData.isPulangAwal) {
            statusAbsen = "PULANG AWAL (IZIN)";
            warnaStatus = "amber";
        } else {
            statusAbsen = "SELESAI SHIFT";
            warnaStatus = "blue";
        }
    }

    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const tglDatabase = `${yyyy}-${mm}-${dd}`;
    const namaHari = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'][now.getDay()];

    const payloadAbsen = {
        nama: staffAbsen.name || 'Karyawan',
        tipe: tipeAbsen,
        metode: 'Kamera PIN',
        waktu: jamStr,
        jam: jamStr,
        tanggal: tglDatabase,
        hari: namaHari,
        status: statusAbsen,
        role: staffAbsen.tipeKaryawan || staffAbsen.role || 'Staff',
        pin: staffAbsen.pin || '',
        foto: fotoBase64 || staffAbsen.photo || staffAbsen.foto || '',
        timestamp: now.getTime()
    };

    // Metadata izin pulang awal jika ada
    if (window.pendingEarlyDepartureData && window.pendingEarlyDepartureData.isPulangAwal) {
        payloadAbsen.isPulangAwal = true;
        payloadAbsen.alasanPulangAwal = window.pendingEarlyDepartureData.alasan || '';
        payloadAbsen.keteranganPulangAwal = window.pendingEarlyDepartureData.keterangan || '';
        payloadAbsen.buktiIzinFoto = window.pendingEarlyDepartureData.buktiScreenshot || '';
        payloadAbsen.jadwalShiftOut = window.pendingEarlyDepartureData.shiftOut || '';
        window.pendingEarlyDepartureData = null;
    }

    try {
        // 1. Simpan ke Cache Lokal SEGERA (Instan & Zero-Lag Offline tanpa membengkakkan storage)
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_attendance_local_logs') || '[]');
            const localRecord = { ...payloadAbsen };
            // Hindari menyimpan foto base64 raksasa di localStorage browser (kapasitas 5MB)
            if (localRecord.foto && localRecord.foto.length > 5000) {
                localRecord.foto = ''; 
            }
            if (localRecord.buktiIzinFoto && localRecord.buktiIzinFoto.length > 5000) {
                localRecord.buktiIzinFoto = '';
            }
            cached.unshift(localRecord);
            window.safeSetItem('mainstay_attendance_local_logs', JSON.stringify(cached.slice(0, 30)));
            if (!Array.isArray(window.todayAttendanceCache)) window.todayAttendanceCache = [];
            window.todayAttendanceCache.unshift(payloadAbsen);
        } catch(e) {}

        // 2. Kirim ke Firebase Cloud jika Online, atau Enqueue ke posSyncEngine jika Offline
        if (navigator.onLine && window.isAppOnline !== false) {
            set(ref(db, `attendance/${tglDatabase}/${now.getTime()}`), payloadAbsen).catch((err) => {
                console.warn("Kirim absensi ke Firebase gagal (antrekan offline):", err);
                if (window.posSyncEngine && typeof window.posSyncEngine.enqueue === 'function') {
                    window.posSyncEngine.enqueue('attendance', payloadAbsen);
                }
            });
        } else {
            if (window.posSyncEngine && typeof window.posSyncEngine.enqueue === 'function') {
                window.posSyncEngine.enqueue('attendance', payloadAbsen);
            }
        }

        // Reset input PIN & Info Card
        const pinEl = document.getElementById('pin-absensi-kamera');
        if (pinEl) pinEl.value = '';
        const infoCard = document.getElementById('info-staff-terpilih-pin');
        if (infoCard) infoCard.classList.add('hidden');
        window.pendingAbsensi = null;

        // Callback transisi ke kasir setelah popup preview selesai (5 detik atau klik lanjut)
        const namaPetugas = staffAbsen.name || 'Staff Kasir';
        const resolvedBestPhoto = fotoBase64 || staffAbsen.photo || staffAbsen.foto || staffAbsen.avatar || '';
        if (tipeAbsen === 'Masuk' && typeof window.persistKasirAvatarThumbnail === 'function' && resolvedBestPhoto) {
            window.persistKasirAvatarThumbnail(namaPetugas, resolvedBestPhoto);
        }
        const cleanStaffObj = {
            name: staffAbsen.name || '',
            role: staffAbsen.tipeKaryawan || staffAbsen.role || 'Staff',
            tipeKaryawan: staffAbsen.tipeKaryawan || staffAbsen.role || 'Staff',
            pin: staffAbsen.pin || '',
            shiftIn: staffAbsen.shiftIn || '08:00',
            shiftOut: staffAbsen.shiftOut || '16:00',
            key: staffAbsen.key || staffAbsen.id || '',
            photo: (resolvedBestPhoto && resolvedBestPhoto.length < 80000) ? resolvedBestPhoto : ''
        };
        const activeStaffWithPhoto = {
            ...staffAbsen,
            photo: staffAbsen.photo || staffAbsen.foto || resolvedBestPhoto
        };

        const onPreviewDismiss = () => {
            if (tipeAbsen === 'Masuk') {
                window.activeStaff = activeStaffWithPhoto;
                window.safeSetItem('mainstay_session_role', 'kasir');
                window.safeSetItem('mainstay_staff_name', namaPetugas);
                window.safeSetItem('mainstay_session_staff', JSON.stringify(cleanStaffObj));

                const elNama = document.getElementById('kasir-active-name');
                if (elNama) elNama.innerText = namaPetugas;

                if (typeof window.switchRoleView === 'function') {
                    window.switchRoleView('kasir');
                }
                if (typeof window.updateKasirActiveProfileUI === 'function') {
                    window.updateKasirActiveProfileUI(namaPetugas);
                }
            }
        };

        // Jika ini absen Masuk, otomatis set profil kasir bertugas sejak awal
        if (tipeAbsen === 'Masuk') {
            window.activeStaff = activeStaffWithPhoto;
            window.safeSetItem('mainstay_session_role', 'kasir');
            window.safeSetItem('mainstay_staff_name', namaPetugas);
            window.safeSetItem('mainstay_session_staff', JSON.stringify(cleanStaffObj));
            if (typeof window.updateKasirActiveProfileUI === 'function') {
                window.updateKasirActiveProfileUI(namaPetugas);
            }
        }

        // Tampilkan Preview Foto 5 Detik dengan callback otomatis ke kasir
        window.tampilkanPreviewAbsen(
            staffAbsen.name, 
            tipeAbsen, 
            fotoBase64 || staffAbsen.photo || staffAbsen.foto || null, 
            statusAbsen, 
            jamStr, 
            warnaStatus, 
            'Kamera PIN',
            onPreviewDismiss
        );

        // Update Riwayat & Indikator Status Staf
        if (typeof window.renderRiwayatAbsensiHariIni === 'function') {
            await window.renderRiwayatAbsensiHariIni();
        }
        if (typeof window.populateStaffSelectAbsen === 'function') {
            window.populateStaffSelectAbsen();
        }
        if (typeof window.renderDaftarStatusStafAbsen === 'function') {
            window.renderDaftarStatusStafAbsen();
        }
        if (typeof window.cekNotifikasiStaffBelumAbsen === 'function') {
            window.cekNotifikasiStaffBelumAbsen();
        }
        window.pendingKasirLoginStaff = null;
    } catch (err) {
        console.error("Gagal simpan absensi:", err);
        alert("Gagal merekam absensi: " + err.message);
    }
};

// Aliases agar pemanggilan lama tetap kompatibel
window.prosesAbsensiCam = window.jepretFotoAbsensiKamera;
window.submitAbsensiFace = window.submitAbsensiPIN;
window.jepretAbsensi = window.jepretFotoAbsensiKamera;
window.absenCepatManualPIN = window.submitAbsensiPIN;

// ==========================================
// MESIN PREVIEW ABSEN (5 DETIK OTOMATIS)
// ==========================================
window.tampilkanPreviewAbsen = (nama, tipe, foto, status, jam, warna, metode = 'Face Recognition', onDismissCallback = null) => {
    const modal = document.getElementById('modal-preview-absen');
    if (!modal) return;
    modal.classList.remove('hidden');

    window._onPreviewDismissCallback = onDismissCallback || null;

    const fotoImg = document.getElementById('preview-foto');
    const pinIcon = document.getElementById('preview-pin-icon-wrap');
    const metodeText = document.getElementById('preview-metode-text');

    if (foto && (String(foto).startsWith('data:image') || String(foto).startsWith('http'))) {
        if (fotoImg) {
            fotoImg.src = foto;
            fotoImg.classList.remove('hidden');
        }
        if (pinIcon) pinIcon.classList.add('hidden');
    } else {
        if (fotoImg) fotoImg.classList.add('hidden');
        if (pinIcon) {
            pinIcon.classList.remove('hidden');
            pinIcon.classList.add('flex');
        }
    }

    if (metodeText) {
        if (metode === 'PIN') {
            metodeText.className = "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider bg-purple-100 text-purple-800 border border-purple-200";
            metodeText.innerHTML = '<i class="fa-solid fa-key"></i> Metode: Opsi PIN';
        } else {
            metodeText.className = "inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider bg-emerald-100 text-emerald-800 border border-emerald-200";
            metodeText.innerHTML = '<i class="fa-solid fa-camera"></i> Metode: Selfie Kamera PIN';
        }
    }

    const namaEl = document.getElementById('preview-nama');
    if (namaEl) namaEl.innerText = nama;

    const tipeEl = document.getElementById('preview-tipe');
    if (tipeEl) tipeEl.innerText = `ABSEN ${tipe}`;

    const jamEl = document.getElementById('preview-jam');
    if (jamEl) jamEl.innerHTML = `<i class="fa-regular fa-clock mr-1"></i>${jam} WIB`;

    const statusBox = document.getElementById('preview-status-box');
    const statusTeks = document.getElementById('preview-status-teks');
    if (statusTeks) statusTeks.innerText = status;

    if (statusBox && statusTeks) {
        if (warna === 'red') {
            statusBox.className = "w-full p-4 rounded-2xl mb-2 bg-red-50 border border-red-200";
            statusTeks.className = "text-lg font-black text-red-600 uppercase tracking-widest mb-1";
        } else if (warna === 'blue' || status === 'SELESAI SHIFT') {
            statusBox.className = "w-full p-4 rounded-2xl mb-2 bg-blue-50 border border-blue-200";
            statusTeks.className = "text-lg font-black text-blue-600 uppercase tracking-widest mb-1";
        } else if (warna === 'amber' || status.includes('IZIN') || status.includes('AWAL')) {
            statusBox.className = "w-full p-4 rounded-2xl mb-2 bg-amber-50 border border-amber-300";
            statusTeks.className = "text-lg font-black text-amber-700 uppercase tracking-widest mb-1";
        } else {
            statusBox.className = "w-full p-4 rounded-2xl mb-2 bg-green-50 border border-green-200";
            statusTeks.className = "text-lg font-black text-green-600 uppercase tracking-widest mb-1";
        }
    }

    let detik = 5;
    const countEl = document.getElementById('preview-countdown');
    if (countEl) countEl.innerText = detik;

    if (window.previewInterval) clearInterval(window.previewInterval);
    window.previewInterval = setInterval(() => {
        detik--;
        if (countEl) countEl.innerText = detik;
        if (detik <= 0) {
            clearInterval(window.previewInterval);
            modal.classList.add('hidden');
            if (typeof window._onPreviewDismissCallback === 'function') {
                const cb = window._onPreviewDismissCallback;
                window._onPreviewDismissCallback = null;
                cb();
            }
        }
    }, 1000);
};

window.tutupPreviewAbsenManual = () => {
    if (window.previewInterval) clearInterval(window.previewInterval);
    const modal = document.getElementById('modal-preview-absen');
    if (modal) modal.classList.add('hidden');
    if (typeof window._onPreviewDismissCallback === 'function') {
        const cb = window._onPreviewDismissCallback;
        window._onPreviewDismissCallback = null;
        cb();
    }
};

// ==========================================
// POPUP SELAMAT DATANG LOGIN OWNER (3 DETIK)
// ==========================================
window.tutupPopupLoginOwner = () => {
    if (window._ownerLoginPopupInterval) {
        clearInterval(window._ownerLoginPopupInterval);
        window._ownerLoginPopupInterval = null;
    }
    if (window._ownerLoginPopupTimeout) {
        clearTimeout(window._ownerLoginPopupTimeout);
        window._ownerLoginPopupTimeout = null;
    }
    const modal = document.getElementById('modal-owner-login-popup');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.tampilkanPopupLoginOwner = (ownerName = 'Owner') => {
    const modal = document.getElementById('modal-owner-login-popup');
    if (!modal) return;

    window.tutupPopupLoginOwner();

    const titleEl = document.getElementById('owner-login-popup-title');
    const subEl = document.getElementById('owner-login-popup-subtitle');
    const countEl = document.getElementById('owner-login-popup-countdown');
    const barEl = document.getElementById('owner-login-popup-bar');
    const cardEl = document.getElementById('owner-login-popup-card');

    const cleanName = String(ownerName || 'Owner').trim() || 'Owner';
    if (titleEl) titleEl.innerText = `Selamat Bertugas, ${cleanName}!`;
    if (subEl) subEl.innerText = 'Akses penuh Dashboard Master Owner telah aktif.';

    let detik = 3;
    if (countEl) countEl.innerText = detik;

    if (barEl) {
        barEl.style.transitionDuration = '0ms';
        barEl.style.width = '100%';
    }

    modal.classList.remove('hidden');
    modal.classList.add('flex');

    if (cardEl) {
        cardEl.classList.remove('member-fs-card-pop');
        void cardEl.offsetWidth;
        cardEl.classList.add('member-fs-card-pop');
    }

    requestAnimationFrame(() => {
        if (barEl) {
            void barEl.offsetWidth;
            barEl.style.transitionDuration = '3000ms';
            barEl.style.width = '0%';
        }
    });

    window._ownerLoginPopupInterval = setInterval(() => {
        detik--;
        if (countEl) countEl.innerText = Math.max(0, detik);
        if (detik <= 0) {
            window.tutupPopupLoginOwner();
        }
    }, 1000);

    window._ownerLoginPopupTimeout = setTimeout(() => {
        window.tutupPopupLoginOwner();
    }, 3100);
};

// ============================================================================
// 3. DUMMY DATA FALLBACK (Nonaktif - Menu hanya dari database/input nyata)
// ============================================================================
const dummyCatalog = {};

// 4. UTILITY FUNCTIONS (Format Uang & Waktu)
// ============================================================================
const formatRupiah = (number) => {
    const val = Number(number);
    return new Intl.NumberFormat('id-ID', { 
        style: 'currency', 
        currency: 'IDR', 
        minimumFractionDigits: 0 
    }).format(isNaN(val) ? 0 : val);
};

const startClock = () => {
    const clockEl = document.getElementById('live-clock');
    if (typeof window.evaluasiJamOperasionalToko === 'function') {
        window.evaluasiJamOperasionalToko();
    }
    let lastAutoEvalSec = -1;
    if (clockEl) {
        setInterval(() => {
            const now = new Date();
            const timeString = now.toLocaleTimeString('id-ID', { 
                hour: '2-digit', 
                minute: '2-digit', 
                second: '2-digit' 
            });
            clockEl.innerHTML = `${timeString} WIB`;

            // Evaluasi otomatis status buka/tutup toko setiap 5 detik
            const currentSec = now.getSeconds();
            if (currentSec % 5 === 0 && currentSec !== lastAutoEvalSec) {
                lastAutoEvalSec = currentSec;
                if (typeof window.evaluasiJamOperasionalToko === 'function') {
                    window.evaluasiJamOperasionalToko();
                }
            }
        }, 1000);
    }
};

// Membersihkan Navigasi Bawah, Padding, dan Mengunci Logo Lokal
const applyLayoutFixes = () => {
    const bottomNav = document.querySelector('nav');
    if (bottomNav) {
        bottomNav.style.display = 'none';
    }

    const appContainer = document.getElementById('app-container');
    if (appContainer) {
        appContainer.classList.remove('pb-20');
    }
    
    const sections = ['view-customer', 'view-kasir', 'view-owner'];
    sections.forEach(id => {
        const sec = document.getElementById(id);
        if (sec) {
            sec.classList.remove('pb-32');
        }
    });

    // --- KUNCI LOGO LOKAL SECARA PERMANEN ---
    const logoImg = document.getElementById('header-logo-img');
    const logoIcon = document.getElementById('header-logo-icon');
    
    if (logoImg) {
        logoImg.src = 'logo-192.png'; // Panggil langsung dari folder lokal
        logoImg.classList.remove('hidden'); // Paksa gambar untuk selalu tampil
    }
    if (logoIcon) {
        logoIcon.classList.add('hidden'); // Sembunyikan icon dummy bawaan HTML
    }
};

// ============================================================================
// 5. FIREBASE REAL-TIME LISTENERS
// ============================================================================
const initFirebaseListeners = () => {
    // 5-PRE. Listener Global Registry Cabang (Branches)
    onValue(_firebaseRef(db, 'branches'), (snapshot) => {
        const raw = snapshot.exists() ? (snapshot.val() || {}) : {};
        window.globalBranches = raw;
        const bid = window.ACTIVE_BRANCH_ID || 'pusat';
        if (bid !== 'pusat' && raw[bid]) {
            const branchInfo = raw[bid];
            const activeBadge = document.getElementById('owner-active-branch-badge');
            if (activeBadge) {
                activeBadge.innerText = branchInfo.name || bid;
            }
            // Pastikan banner lokasi & storeSettings terisi info cabang jika belum disetel manual
            if (typeof window.applyStoreSettingsToUI === 'function') {
                window.applyStoreSettingsToUI(window.storeSettings || {});
            }
        }
        if (currentRole === 'owner' && typeof window.renderOwnerBranchesSection === 'function') {
            window.renderOwnerBranchesSection();
        }
    });

    // 5-PRE-B. Sinkronisasi Real-Time Pengaturan Pusat sebagai Default Header & Footer Cabang
    if (window.ACTIVE_BRANCH_ID && window.ACTIVE_BRANCH_ID !== 'pusat') {
        onValue(_firebaseRef(db, 'store_settings'), (pusatSnap) => {
            window.pusatStoreSettings = pusatSnap.exists() ? (pusatSnap.val() || {}) : {};
            if (typeof window.applyStoreSettingsToUI === 'function' && (window.rawBranchStoreSettings || window.storeSettings)) {
                window.applyStoreSettingsToUI(window.rawBranchStoreSettings || window.storeSettings);
            }
        });
    }

    // 5A-0. Hidrasi Cepat Katalog Menu via Service Worker Stale-While-Revalidate
    if (typeof window.hydrateMenuCatalogSWR === 'function') {
        window.hydrateMenuCatalogSWR(false);
    }

    // 5A. Listener Database: Menus (Firebase Realtime Database)
    onValue(ref(db, 'menus'), (snapshot) => {
        window._menusLiveLoadedFromRTDB = true;
        let rtdbData = snapshot.exists() ? (snapshot.val() || {}) : {};
        console.log(`[Carousel/Promo RTDB] Received ${Object.keys(rtdbData).length} menus from RTDB`);

        const deletedMenuKeys = window.safeJsonParse(localStorage.getItem('mainstay_deleted_menu_keys'), []);
        const dummyKeys = ['menu_americano', 'menu_thai_tea', 'menu_taro_milk', 'menu_vanilla', 'menu_pukis', 'menu_kopi_susu', 'menu_es_teh', 'menu_matcha'];
        let combined = {};
        if (Object.keys(rtdbData).length > 0) {
            combined = { ...rtdbData };
            dummyKeys.forEach(k => {
                if (combined[k]) {
                    delete combined[k];
                    try { remove(ref(db, `menus/${k}`)).catch(() => {}); } catch(e) {}
                }
            });
        }
        if (Array.isArray(deletedMenuKeys)) {
            deletedMenuKeys.forEach(k => delete combined[k]);
        }
        dummyKeys.forEach(k => delete combined[k]);
        globalMenus = combined;
        window.globalMenus = globalMenus;
        console.log(`[Carousel/Promo Menus Loaded] Total ${Object.keys(globalMenus).length} items`, Object.keys(globalMenus));
        try { localStorage.setItem('mainstay_cached_menus', JSON.stringify(globalMenus)); } catch(e) {}
        
        if (currentRole === 'customer') {
            if (typeof window.scheduleCustomerCatalogRender === 'function') window.scheduleCustomerCatalogRender();
            else if (typeof window.renderKatalog === 'function') window.renderKatalog();
        }
        if (currentRole === 'owner' && document.getElementById('owner-menu-list')) {
            if (typeof window.renderPanelMenu === 'function') window.renderPanelMenu();
        }
        if (currentRole === 'kasir' || localStorage.getItem('mainstay_is_kasir_open') === 'true') {
            if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
        }
        if (typeof window.renderTabResepMenu === 'function' && document.getElementById('content-tab-resep') && !document.getElementById('content-tab-resep').classList.contains('hidden')) {
            window.renderTabResepMenu();
        }
    }, (err) => {
        console.warn("Firebase menus listener error:", err);
        if (currentRole === 'customer') {
            if (typeof window.scheduleCustomerCatalogRender === 'function') window.scheduleCustomerCatalogRender();
            else if (typeof window.renderKatalog === 'function') window.renderKatalog();
        }
    });

    let lastOrderCount = 0; // Tambahan untuk melacak pesanan baru
    let isInitialLoad = true; // Flag untuk mencegah toast saat load pertama

    // 5B. Listener Database Orders (SNAPSHOT STREAM REAL-TIME)
    onValue(ref(db, 'orders'), (snapshot) => {
        const remoteData = snapshot.exists() ? (snapshot.val() || {}) : {};
        Object.keys(remoteData).forEach(k => {
            if (remoteData[k] && typeof remoteData[k] === 'object') {
                remoteData[k].firebaseKey = k;
            }
        });
        const merged = { ...remoteData };
        try {
            const cachedOffline = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            if (Array.isArray(cachedOffline)) {
                cachedOffline.forEach(ord => {
                    if (!ord) return;
                    const ordId = String(ord.orderId || ord.id || '');
                    const k = ord.firebaseKey || ord.orderId || ord.id;
                    
                    // Cari apakah sudah ada entri pesanan yang sama di remoteData
                    const existingKey = Object.keys(merged).find(mk => {
                        const ex = merged[mk];
                        if (!ex) return false;
                        return (
                            (ordId && (ex.id === ordId || ex.orderId === ordId)) ||
                            (ord.firebaseKey && (mk === ord.firebaseKey || ex.firebaseKey === ord.firebaseKey))
                        );
                    });

                    if (existingKey) {
                        // Jika sudah ada di database, gunakan data dengan update terbaru agar status tidak ter-reset
                        const existing = merged[existingKey];
                        const offTime = ord.updatedAt || ord.timestamp || 0;
                        const remTime = existing.updatedAt || existing.timestamp || 0;
                        if (offTime >= remTime) {
                            merged[existingKey] = { ...existing, ...ord };
                        }
                    } else if (k) {
                        merged[k] = ord;
                    }
                });
            }
        } catch (e) {}

        const newOrderCount = Object.keys(merged).length;
        
        // Logika untuk mendeteksi pesanan baru tanpa duplikasi
        window._notifiedOrderIds = window._notifiedOrderIds || new Set();
        if (!isInitialLoad && newOrderCount > lastOrderCount && currentRole === 'kasir') {
            const orderKeys = Object.keys(merged);
            const latestOrderKey = orderKeys[orderKeys.length - 1];
            const latestOrder = merged[latestOrderKey];
            const uniqueOrderId = String((latestOrder && (latestOrder.id || latestOrder.orderId)) || latestOrderKey);
            
            // Pastikan statusnya pending (pesanan benar-benar baru) dan belum pernah dibunyikan notifnya
            if (latestOrder && (latestOrder.status === 'Pending' || latestOrder.status === 'pending') && !window._notifiedOrderIds.has(uniqueOrderId)) {
                window._notifiedOrderIds.add(uniqueOrderId);
                if (typeof window.tampilkanToastPesananBaru === 'function') {
                    window.tampilkanToastPesananBaru(latestOrder);
                }
                if (typeof window.playOrderNotificationSound === 'function') {
                    window.playOrderNotificationSound();
                }
            }
        }
        
        globalOrders = merged;
        window.globalOrders = merged;
        window._latestOrdersSnapshot = merged;
        lastOrderCount = newOrderCount;
        isInitialLoad = false;

        // Bersihkan otomatis pesanan masuk & dapur yang sudah beda hari (hanya untuk staf/owner, bukan HP pelanggan)
        if (currentRole !== 'customer' && typeof window.bersihkanOrderanMasukDanDapurBedaHari === 'function') {
            window.bersihkanOrderanMasukDanDapurBedaHari();
        }

        if (currentRole === 'kasir' && typeof window.renderKasirOrders === 'function') { 
            window.renderKasirOrders(); 
            window.updateLiveCashDrawer(); 
        }
        if (currentRole === 'owner' && typeof window.updateOwnerDashboard === 'function') {
            window.updateOwnerDashboard();
        }
        
        // AUTO-UPDATE REAL-TIME: Hanya jalankan ulang laporan D3 jika panel Laporan sedang aktif
        if (window._laporanPanelActive && typeof window.onLaporanOrdersSnapshotUpdate === 'function') {
            window.onLaporanOrdersSnapshotUpdate(globalOrders);
        }
    });

    // 5C. Listener Database: Staff
    onValue(ref(db, 'staff'), (snapshot) => {
        window._staffLoaded = true;
        if (snapshot.exists()) {
            globalStaff = snapshot.val() || {};
        } else {
            globalStaff = {};
        }
        window.globalStaff = globalStaff;
        try {
            localStorage.setItem('mainstay_cached_staff', JSON.stringify(globalStaff));
        } catch(e) {}
        if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.syncBranchStaff === 'function') {
            window.mainstayIndexedDB.syncBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat', globalStaff).catch(() => {});
        }

        // Jika di cabang dan data staff cabang kosong, pastikan sesi kasir lama (jika ada) langsung dicabut
        if (window.IS_BRANCH_OUTLET && Object.keys(globalStaff).length === 0) {
            const savedR = localStorage.getItem('mainstay_session_role');
            if (currentRole === 'kasir' || savedR === 'kasir') {
                try {
                    document.documentElement.classList.remove('app-role-kasir', 'app-pos-open');
                    localStorage.removeItem('mainstay_session_role');
                    localStorage.removeItem('mainstay_session_staff');
                    localStorage.removeItem('mainstay_staff_name');
                    localStorage.removeItem('mainstay_is_kasir_open');
                } catch(e) {}
                window.activeStaff = null;
                if (typeof window.switchRoleView === 'function') {
                    window.switchRoleView('customer');
                }
            }
        }

        if (currentRole === 'owner' && (document.getElementById('owner-staff-list') || document.getElementById('form-hrd-container') || document.getElementById('form-hrd-owner-container'))) {
            window.renderPanelHRD();
        }
        if (typeof window.updateKasirActiveProfileUI === 'function') {
            window.updateKasirActiveProfileUI();
        }
        if (typeof window.populateStaffSelectAbsen === 'function') {
            window.populateStaffSelectAbsen();
        }
        if (typeof window.renderDaftarStatusStafAbsen === 'function') {
            window.renderDaftarStatusStafAbsen();
        }
        if (typeof window.cekNotifikasiStaffBelumAbsen === 'function') {
            window.cekNotifikasiStaffBelumAbsen(false);
        }
    });

    // 5C2. Listener Database: Master Owner
    onValue(ref(db, 'master_owner'), (snapshot) => {
        if (snapshot.exists()) {
            globalMasterOwner = snapshot.val() || {};
        } else {
            globalMasterOwner = {};
        }
        window.globalMasterOwner = globalMasterOwner;

        if (currentRole === 'owner' && (document.getElementById('owner-staff-list') || document.getElementById('form-hrd-container') || document.getElementById('form-hrd-owner-container'))) {
            window.renderPanelHRD();
        }
        if (typeof window.updateKasirActiveProfileUI === 'function') {
            window.updateKasirActiveProfileUI();
        }
    });

    // 5D. Listener Database: Inventory
    onValue(ref(db, 'inventory_raw'), (snapshot) => {
        if (snapshot.exists()) {
            globalInventory = snapshot.val();
        } else {
            globalInventory = {};
        }

        // Jalankan pengecekan dan notifikasi otomatis stok minimum
        if (typeof window.cekNotifikasiStokMinimum === 'function') {
            window.cekNotifikasiStokMinimum();
        }

        if (currentRole === 'owner' && document.getElementById('owner-inventory-list')) {
            window.renderPanelInventory();
        }
    });

    // 5D-2. Listener Master Topping
    onValue(ref(db, 'master_topping'), (snapshot) => {
        if (snapshot.exists()) {
            const data = snapshot.val();
            window.masterTopping = Array.isArray(data)
                ? data.filter(Boolean).map((item, idx) => (typeof item === 'object' ? { ...item, id: item.id || ('top_' + idx) } : { id: String(item), nama: String(item), harga: 0 }))
                : Object.entries(data || {}).map(([k, v]) => (v && typeof v === 'object' ? { ...v, id: v.id || k } : { id: k, nama: String(v || k), harga: 0 }));
            localStorage.setItem('master_topping', JSON.stringify(window.masterTopping));
            if (typeof window.renderMasterTopping === 'function') window.renderMasterTopping();
            if (typeof window.renderCheckboxTopping === 'function') window.renderCheckboxTopping();
        } else if (!window.masterTopping || window.masterTopping.length === 0) {
            if (typeof window.seedDefaultMasterData === 'function') window.seedDefaultMasterData();
        }
    });

    // 5D-3. Listener Master Varian
    onValue(ref(db, 'master_varian'), (snapshot) => {
        if (snapshot.exists()) {
            const data = snapshot.val();
            window.masterVarian = Array.isArray(data)
                ? data.filter(Boolean).map((item, idx) => (typeof item === 'object' ? { ...item, id: item.id || ('var_' + idx) } : { id: String(item), nama: String(item), opsi: [] }))
                : Object.entries(data || {}).map(([k, v]) => (v && typeof v === 'object' ? { ...v, id: v.id || k } : { id: k, nama: String(v || k), opsi: [] }));
            localStorage.setItem('master_varian', JSON.stringify(window.masterVarian));
            if (typeof window.renderMasterVarian === 'function') window.renderMasterVarian();
            if (typeof window.renderCheckboxVarian === 'function') window.renderCheckboxVarian();
        } else if (!window.masterVarian || window.masterVarian.length === 0) {
            if (typeof window.seedDefaultMasterData === 'function') window.seedDefaultMasterData();
        }
    });

    // 5D-4. Listener Master Kategori & Categories
    onValue(ref(db, 'master_kategori'), (snapshot) => {
        if (snapshot.exists()) {
            const data = snapshot.val();
            const list = Array.isArray(data) ? data : Object.values(data);
            const clean = list.map(k => typeof k === 'object' ? (k.name || k.nama || k.id) : k).filter(Boolean);
            if (clean.length > 0) {
                window.masterKategori = clean;
                localStorage.setItem('master_kategori', JSON.stringify(clean));
                if (typeof window.renderMasterKategori === 'function') window.renderMasterKategori();
                if (typeof window.renderSelectKategori === 'function') window.renderSelectKategori();
                if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
                if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
            }
        } else {
            if (typeof window.sinkronkanSemuaKategori === 'function') {
                window.sinkronkanSemuaKategori();
            }
        }
    });

    onValue(ref(db, 'categories'), (snapshot) => {
        if (snapshot.exists()) {
            const data = snapshot.val();
            const listFromDb = Object.values(data).map(c => typeof c === 'object' ? (c.name || c.nama || c.id) : c).filter(Boolean);
            if (listFromDb.length > 0) {
                const combined = [...new Set([...(window.masterKategori || []), ...listFromDb])];
                window.masterKategori = combined;
                localStorage.setItem('master_kategori', JSON.stringify(combined));
                if (typeof window.renderMasterKategori === 'function') window.renderMasterKategori();
                if (typeof window.renderSelectKategori === 'function') window.renderSelectKategori();
                if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
                if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
            }
        }
    });

    // 5E. Listener Database: Expenses
    onValue(ref(db, 'expenses'), (snapshot) => {
        if (snapshot.exists()) {
            globalExpenses = snapshot.val();
        } else {
            globalExpenses = {};
        }

        if (currentRole === 'owner' && document.getElementById('owner-laporan-list')) {
            window.renderPanelLaporan();
        }
    });

    // 5E-2. Listener Database: Cashflow (Arus Kas Ruang Kerja Kasir)
    onValue(ref(db, 'cashflow'), (snapshot) => {
        if (snapshot.exists()) {
            globalCashflow = snapshot.val();
        } else {
            globalCashflow = {};
        }
        window.globalCashflow = globalCashflow;

        if (typeof window.renderTabArusKas === 'function' && document.getElementById('content-tab-aruskas') && !document.getElementById('content-tab-aruskas').classList.contains('hidden')) {
            window.renderTabArusKas();
        }
        if (typeof window.renderTabShift === 'function' && document.getElementById('content-tab-shift') && !document.getElementById('content-tab-shift').classList.contains('hidden')) {
            window.renderTabShift();
        }
    });

    // 5E-3. Listener Database: Stock Purchases (Riwayat Belanja Kulakan & Modal Stok)
    onValue(ref(db, 'stock_purchases'), (snapshot) => {
        globalStockPurchases = snapshot.exists() ? (snapshot.val() || {}) : {};
        window.globalStockPurchases = globalStockPurchases;

        if (typeof window.renderTabStok === 'function' && document.getElementById('content-tab-stok') && !document.getElementById('content-tab-stok').classList.contains('hidden')) {
            window.renderTabStok();
        }
        if (currentRole === 'owner' && document.getElementById('owner-inventory-list')) {
            window.renderPanelInventory();
        }
        if (window._laporanPanelActive && document.getElementById('hasil-laporan')) {
            window.tarikLaporanKeuangan(true);
        }
    });

    // 5E-3b. Listener Database: Stock Movements Real-Time (Riwayat Per Item Bahan)
    onValue(ref(db, 'stock_movements'), (snapshot) => {
        if (snapshot.exists()) {
            const serverMoves = snapshot.val() || {};
            window.globalStockMovements = { ...serverMoves };
            if (typeof window._saveStockMovementsCache === 'function') {
                window._saveStockMovementsCache();
            }
        } else {
            window.globalStockMovements = {};
        }

        if (typeof window.renderStokKasirHistory === 'function' && document.getElementById('stok-kasir-history-list')) {
            window.renderStokKasirHistory();
        }
        if (window._activeRiwayatStokItemKey && typeof window.renderModalRiwayatStokItemBody === 'function') {
            window.renderModalRiwayatStokItemBody();
        }
    });

    // 5E-4. Listener Root: Finance Config & Target Omzet Multi-Cabang (Master Owner)
    if (typeof window._rawFirebaseRef === 'function' || typeof _firebaseRef === 'function') {
        const rootRefFn = window._rawFirebaseRef || _firebaseRef;
        onValue(rootRefFn(db, 'finance_config'), (snapshot) => {
            if (snapshot.exists()) {
                window.globalFinanceConfig = snapshot.val() || {};
                try {
                    localStorage.setItem('mainstay_finance_config', JSON.stringify(window.globalFinanceConfig));
                } catch (e) {}
            } else {
                window.globalFinanceConfig = null;
            }
            if (typeof window.updateLiveCashDrawer === 'function') {
                window.updateLiveCashDrawer();
            }
            if (window._laporanPanelActive && document.getElementById('hasil-laporan') && typeof window.tarikLaporanKeuangan === 'function') {
                window.tarikLaporanKeuangan(true);
            }
        });
    }

    // 5E-5. Listener Database: Activity Logs Real-Time (Audit Akuntabilitas Staf)
    onValue(ref(db, 'activity_logs'), (snapshot) => {
        if (snapshot.exists()) {
            const serverLogs = snapshot.val() || {};
            window.globalActivityLogs = { ...serverLogs };
            try {
                const entries = Object.entries(window.globalActivityLogs)
                    .sort((a, b) => Number(b[1]?.timestamp || 0) - Number(a[1]?.timestamp || 0))
                    .slice(0, 400);
                localStorage.setItem('mainstay_activity_logs_cache', JSON.stringify(Object.fromEntries(entries)));
            } catch (e) {}
        } else {
            window.globalActivityLogs = {};
        }

        if (!window._hasScheduledActivityCleanup && typeof window.cleanupOldActivityLogs === 'function') {
            window._hasScheduledActivityCleanup = true;
            const runCleanup = () => window.cleanupOldActivityLogs(30).catch(() => {});
            if (typeof window.requestIdleCallback === 'function') {
                window.requestIdleCallback(runCleanup, { timeout: 2500 });
            } else {
                setTimeout(runCleanup, 1500);
            }
        }

        const tabAktivitas = document.getElementById('content-tab-aktivitas');
        if (tabAktivitas && !tabAktivitas.classList.contains('hidden') && typeof window.renderTabAktivitas === 'function') {
            window.renderTabAktivitas();
        }
    });

    // 5F. Listener Setelan Toko (Status Buka/Tutup & Indikator)
    onValue(ref(db, 'store_settings'), (snapshot) => {
        window._storeSettingsLoaded = true;
        if (snapshot.exists()) {
            const settings = snapshot.val();
            window.storeSettings = settings;
            try {
                localStorage.setItem('mainstay_store_settings', JSON.stringify(settings));
            } catch(e) {}
            
            // A. Update Variabel Global langsung dari server
            isStoreOpen = settings.isStoreOpen !== false;
            window.statusTokoRealtime = isStoreOpen;
            try {
                localStorage.setItem('mainstay_is_store_open', String(isStoreOpen));
            } catch(e) {}

        // --- TEMBAK LANGSUNG KE FISIK SAKELAR (GARANSI 100%) ---
        setTimeout(() => {
            if (typeof window.updateVisualToggle === 'function') {
                window.updateVisualToggle(isStoreOpen);
            }
            document.querySelectorAll('.toggle-kedai').forEach(sakelar => {
                sakelar.checked = isStoreOpen;
            });
        }, 300);

            
            // B. Deteksi dan Ubah Teks/Warna Indikator di Sebelah Jam
            const clockEl = document.getElementById('live-clock');
            if (clockEl && clockEl.nextElementSibling) {
                const statusEl = clockEl.nextElementSibling;
                if (isStoreOpen) {
                    statusEl.className = "text-[9px] text-green-500 font-bold uppercase tracking-wider";
                    statusEl.innerHTML = '<i class="fa-solid fa-circle text-[7px] animate-pulse"></i> Buka';
                } else {
                    statusEl.className = "text-[9px] text-red-500 font-bold uppercase tracking-wider";
                    statusEl.innerHTML = '<i class="fa-solid fa-circle text-[7px]"></i> Tutup';
                }
            }
            
            // C. Tampilkan Banner Merah Melintang "Toko Tutup"
            const bannerTutup = document.getElementById('store-closed-banner');
            if (bannerTutup) {
                isStoreOpen ? bannerTutup.classList.add('hidden') : bannerTutup.classList.remove('hidden');
            }
            if (currentRole === 'customer') {
                if (typeof window.scheduleCustomerCatalogRender === 'function') window.scheduleCustomerCatalogRender();
                else if (typeof window.renderKatalog === 'function') window.renderKatalog();
            }
            
            // D. Sinkronisasi visual sakelar status operasional tanpa merusak form edit
            if (typeof window.updateVisualToggle === 'function') {
                window.updateVisualToggle(isStoreOpen);
            }

            // E. Sinkronisasi Pengaturan Member & Points Loyalty
            window.loyaltyConfig = {
                targetStamp: 5,
                minSpend: 0,
                expiryDays: 30,
                waGroupLink: '',
                welcomeMsg: 'Halo {nama}! Selamat telah bergabung menjadi Member Resmi Mainstay Drink. Kumpulkan Points setiap pembelian dan tukarkan hadiah menarik!',
                rewardMsg: 'Selamat {nama}! Kamu telah mengumpulkan cukup Points. Silakan tukarkan minuman gratis atau voucher favoritmu di kedai Mainstay Drink!',
                ...(settings.loyalty_config || {})
            };
            if (typeof window.populateLoyaltySettingsForm === 'function') {
                window.populateLoyaltySettingsForm();
            }
            if (typeof window.renderOwnerCustomerTable === 'function' && document.getElementById('owner-customer-tbody')) {
                window.renderOwnerCustomerTable();
            }

            // F. Sinkronisasi Identitas, Branding, Carousel & Footer Toko
            if (typeof window.applyStoreSettingsToUI === 'function') {
                window.applyStoreSettingsToUI(settings);
            }

            // G. Evaluasi Otomatis Jadwal Tutup Kedai Realtime (HANYA untuk staf/owner, bukan dari HP pelanggan!)
            if (typeof window.evaluasiJamOperasionalToko === 'function' && currentRole !== 'customer') {
                window.evaluasiJamOperasionalToko();
            }
            if (typeof window.updateLiveCashDrawer === 'function') {
                window.updateLiveCashDrawer();
            }
        } else if (window.ACTIVE_BRANCH_ID && window.ACTIVE_BRANCH_ID !== 'pusat') {
            const branchMeta = (window.globalBranches || {})[window.ACTIVE_BRANCH_ID] || {};
            get(_firebaseRef(db, 'store_settings')).then((pusatSnap) => {
                const ps = pusatSnap.exists() ? (pusatSnap.val() || {}) : {};
                window.pusatStoreSettings = ps;
                const fallbackSettings = {
                    ...ps,
                    store_logo: ps.store_logo || 'logo-192.png',
                    receipt_logo: ps.receipt_logo || ps.store_logo || 'logo-192.png',
                    store_title: ps.store_title || 'Mainstay Drink',
                    store_tagline: ps.store_tagline || 'Sistem Kasir Terpadu',
                    banner_location_label: branchMeta.name || 'Lokasi Cabang',
                    banner_location_text: branchMeta.location || 'Alamat cabang belum diatur di Setting Toko',
                    promo_marquee: branchMeta.marquee || ps.promo_marquee || 'Selamat datang di Mainstay Drink! Nikmati kesegaran minuman andalanmu hari ini.',
                    carousel_slides: ps.carousel_slides || [],
                    isStoreOpen: branchMeta.status !== 'inactive'
                };
                window.rawBranchStoreSettings = fallbackSettings;
                window.storeSettings = fallbackSettings;
                if (typeof window.applyStoreSettingsToUI === 'function') {
                    window.applyStoreSettingsToUI(fallbackSettings);
                }
            }).catch(() => {});
        }
    });

    // 5G. Listener Database: Members (Tanpa data dummy otomatis saat loading/kosong)
    onValue(ref(db, 'members'), (snapshot) => {
        window._membersLoaded = true;
        const deletedCustomerKeys = JSON.parse(localStorage.getItem('mainstay_deleted_customer_keys') || '[]');
        if (snapshot.exists() && Object.keys(snapshot.val() || {}).length > 0) {
            const data = { ...snapshot.val() };
            deletedCustomerKeys.forEach(k => delete data[k]);
            window.cachedMembers = data;
        } else {
            window.cachedMembers = {};
        }
        globalMembers = window.cachedMembers;
        if (typeof window.renderOwnerCustomerTable === 'function' && document.getElementById('owner-customer-tbody')) {
            window.renderOwnerCustomerTable();
        }
        if (typeof window.updateOwnerMemberStats === 'function') {
            window.updateOwnerMemberStats();
        }
    });

    // 5H. Listener Database: Non-Members (Tanpa data dummy otomatis saat loading/kosong)
    onValue(ref(db, 'non_members'), (snapshot) => {
        window._nonMembersLoaded = true;
        const deletedCustomerKeys = JSON.parse(localStorage.getItem('mainstay_deleted_customer_keys') || '[]');
        if (snapshot.exists() && Object.keys(snapshot.val() || {}).length > 0) {
            const data = { ...snapshot.val() };
            deletedCustomerKeys.forEach(k => delete data[k]);
            window.cachedNonMembers = data;
        } else {
            window.cachedNonMembers = {};
        }
        globalNonMembers = window.cachedNonMembers;
        if (typeof window.renderOwnerCustomerTable === 'function' && document.getElementById('owner-customer-tbody')) {
            window.renderOwnerCustomerTable();
        }
        if (typeof window.updateOwnerMemberStats === 'function') {
            window.updateOwnerMemberStats();
        }
    });

    // 5I. Listener Database: Loyalty Rewards (Tanpa data dummy otomatis saat loading/kosong)
    onValue(ref(db, 'loyalty_rewards'), (snapshot) => {
        window._loyaltyRewardsLoaded = true;
        const deletedRewardKeys = JSON.parse(localStorage.getItem('mainstay_deleted_reward_keys') || '[]');
        if (snapshot.exists() && Object.keys(snapshot.val() || {}).length > 0) {
            const data = { ...snapshot.val() };
            deletedRewardKeys.forEach(k => delete data[k]);
            window.cachedLoyaltyRewards = data;
        } else {
            window.cachedLoyaltyRewards = {};
        }
        globalLoyaltyRewards = window.cachedLoyaltyRewards;
        if (typeof window.renderLoyaltyRewardsCatalog === 'function' && document.getElementById('rewards-catalog-list')) {
            window.renderLoyaltyRewardsCatalog();
        }
        if (typeof window.renderOwnerRewardTiers === 'function' && document.getElementById('owner-reward-tiers-tbody')) {
            window.renderOwnerRewardTiers();
        }
        if (typeof window.updateOwnerMemberStats === 'function') {
            window.updateOwnerMemberStats();
        }
    });

    // 5J. Listener Database: Vouchers
    onValue(ref(db, 'vouchers'), (snapshot) => {
        window.cachedVouchers = snapshot.val() || {};
        globalVouchers = window.cachedVouchers;
        try { localStorage.setItem('mainstay_cached_vouchers', JSON.stringify(window.cachedVouchers)); } catch(e) {}
    });
}; // <-- Kurung ini sangat penting untuk menutup fungsi utama initFirebaseListeners

// ==========================================
// MODUL TOGGLE STATUS KEDAI (FINAL STABIL)
// ==========================================

window.updateVisualToggle = (statusBuka) => {
    isStoreOpen = Boolean(statusBuka);
    window.statusTokoRealtime = isStoreOpen;

    // 1. Sinkronkan semua input checkbox .toggle-kedai
    document.querySelectorAll('.toggle-kedai').forEach(sakelar => {
        sakelar.checked = isStoreOpen;
    });

    // 2. Sinkronkan bg & knob custom toggle jika ada
    const bgToggle = document.getElementById('bg-toggle-kedai');
    const knobToggle = document.getElementById('knob-toggle-kedai');
    if (bgToggle && knobToggle) {
        if (isStoreOpen) {
            bgToggle.classList.remove('bg-red-500');
            bgToggle.classList.add('bg-green-500');
            knobToggle.classList.remove('translate-x-0');
            knobToggle.classList.add('translate-x-3.5');
        } else {
            bgToggle.classList.remove('bg-green-500');
            bgToggle.classList.add('bg-red-500');
            knobToggle.classList.remove('translate-x-3.5');
            knobToggle.classList.add('translate-x-0');
        }
    }

    // 3. Sinkronkan tombol toggle di panel pengaturan owner
    const btnToko = document.getElementById('toggle-toko-btn');
    if (btnToko) {
        btnToko.className = `w-14 h-8 rounded-full transition-colors duration-300 ${isStoreOpen ? 'bg-emerald-500' : 'bg-slate-300'} relative shadow-inner flex items-center px-1 shrink-0`;
        const knob = btnToko.querySelector('div');
        if (knob) {
            knob.className = `w-6 h-6 bg-white rounded-full shadow-sm transform transition-transform duration-300 ${isStoreOpen ? 'translate-x-6' : 'translate-x-0'}`;
        }
    }
    const txtStatus = document.getElementById('toggle-toko-status-text');
    if (txtStatus) {
        txtStatus.innerText = isStoreOpen ? 'TOKO SEDANG BUKA' : 'TOKO SEDANG TUTUP';
        txtStatus.className = `text-xs font-black uppercase ${isStoreOpen ? 'text-emerald-600' : 'text-rose-600'}`;
    }

    // 4. Sinkronkan indikator Buka/Tutup di sebelah jam
    const clockEl = document.getElementById('live-clock');
    if (clockEl && clockEl.nextElementSibling) {
        const statusEl = clockEl.nextElementSibling;
        if (isStoreOpen) {
            statusEl.className = "text-[9px] text-green-500 font-bold uppercase tracking-wider";
            statusEl.innerHTML = '<i class="fa-solid fa-circle text-[7px] animate-pulse"></i> Buka';
        } else {
            statusEl.className = "text-[9px] text-red-500 font-bold uppercase tracking-wider";
            statusEl.innerHTML = '<i class="fa-solid fa-circle text-[7px]"></i> Tutup';
        }
    }

    // 5. Sinkronkan banner merah "Toko Tutup"
    const bannerTutup = document.getElementById('store-closed-banner');
    if (bannerTutup) {
        if (isStoreOpen) bannerTutup.classList.add('hidden');
        else bannerTutup.classList.remove('hidden');
    }

    // 6. Sembunyikan atau tampilkan keranjang floating & promo carousel
    const cartFloating = document.getElementById('btn-cart-floating');
    if (cartFloating && !isStoreOpen) {
        cartFloating.classList.add('hidden');
    }
};

window.setStoreOpenStatus = async (statusBuka, options = {}) => {
    isStoreOpen = Boolean(statusBuka);
    window.statusTokoRealtime = isStoreOpen;
    window.storeSettings = window.storeSettings || {};
    window.storeSettings.isStoreOpen = isStoreOpen;

    // Jika diubah manual oleh Owner/Kasir agar BUKA di luar jam jadwal, beri masa toleransi manual 12 jam
    const isAutoCall = Boolean(options && options.isAuto);
    if (!isAutoCall) {
        window.storeSettings.manual_open_override_until = isStoreOpen ? (Date.now() + 12 * 60 * 60 * 1000) : 0;
    }

    try {
        localStorage.setItem('mainstay_store_settings', JSON.stringify(window.storeSettings));
        localStorage.setItem('mainstay_is_store_open', String(isStoreOpen));
    } catch(e) {}

    window.updateVisualToggle(isStoreOpen);

    if (typeof window.renderKatalog === 'function') {
        window.renderKatalog();
    }
    if (typeof window.renderPromoBestsellerCarousel === 'function') {
        window.renderPromoBestsellerCarousel();
    }

    try {
        const updatePayload = { isStoreOpen: isStoreOpen };
        if (!isAutoCall) {
            updatePayload.manual_open_override_until = window.storeSettings.manual_open_override_until || 0;
        }
        await update(ref(db, 'store_settings'), updatePayload);
    } catch (error) {
        console.warn("RTDB store status update warning:", error);
    }
};

window.ubahStatusKedai = async (elemenSakelar) => {
    const statusBaru = elemenSakelar.checked;
    await window.setStoreOpenStatus(statusBaru, { isAuto: false });
};

window.toggleStatusToko = async () => {
    await window.setStoreOpenStatus(!isStoreOpen, { isAuto: false });
};

// ==========================================
// EVALUASI OTOMATIS JADWAL BUKA/TUTUP KEDAI (AUTO-CLOSE)
// ==========================================
window.evaluasiJamOperasionalToko = (forceUpdate = false) => {
    // KRITIKAL:
    // 1. Jangan pernah jalankan evaluasi auto-close dari tampilan pelanggan (scan QR meja/voucher/menu)!
    //    Pelanggan hanya mengikuti status isStoreOpen langsung dari server Firebase.
    // 2. Jangan pernah jalankan sebelum Firebase store_settings benar-benar selesai dimuat!
    if (currentRole === 'customer' || !window._storeSettingsLoaded) {
        return;
    }

    const s = window.storeSettings || JSON.parse(localStorage.getItem('mainstay_store_settings') || '{}');
    
    // Cek toggle nyala/mati fitur otomatis buka tutup toko
    if (s.auto_schedule_active === false) {
        return;
    }

    // Jika owner baru saja membuka toko secara manual (override aktif), jangan otomatis tutup sendiri
    const manualUntil = Number(s.manual_open_override_until || 0);
    if (!forceUpdate && manualUntil > Date.now() && isStoreOpen) {
        return;
    }

    const jamBukaStr = String(s.jam_buka || '10:00').trim();
    const jamTutupStr = String(s.jam_tutup || '22:00').trim();

    if (!jamBukaStr || !jamTutupStr || !jamBukaStr.includes(':') || !jamTutupStr.includes(':')) {
        return;
    }

    const [bukaH, bukaM] = jamBukaStr.split(':').map(v => parseInt(v) || 0);
    const [tutupH, tutupM] = jamTutupStr.split(':').map(v => parseInt(v) || 0);

    const openMins = bukaH * 60 + bukaM;
    const closeMins = tutupH * 60 + tutupM;

    const now = new Date();
    const nowMins = now.getHours() * 60 + now.getMinutes();

    let shouldBeOpen = false;
    if (openMins < closeMins) {
        shouldBeOpen = (nowMins >= openMins && nowMins < closeMins);
    } else if (openMins > closeMins) {
        shouldBeOpen = (nowMins >= openMins || nowMins < closeMins);
    } else {
        shouldBeOpen = true;
    }

    if (!shouldBeOpen && (isStoreOpen || window.statusTokoRealtime !== false)) {
        console.log(`[AutoStore] Jam operasional kedai telah berakhir (${jamTutupStr} WIB). Menutup toko otomatis.`);
        window.setStoreOpenStatus(false, { isAuto: true });
        const bannerTutup = document.getElementById('store-closed-banner');
        if (bannerTutup) {
            bannerTutup.classList.remove('hidden');
            const p = bannerTutup.querySelector('p');
            if (p) {
                p.innerText = `Kedai Otomatis Tutup (Jam Operasional: ${jamBukaStr} - ${jamTutupStr} WIB). Menu tidak dapat dipesan hingga jam buka kembali.`;
            }
        }
    } else if (shouldBeOpen && (!isStoreOpen || window.statusTokoRealtime === false) && forceUpdate) {
        console.log(`[AutoStore] Jam operasional kedai telah dimulai (${jamBukaStr} WIB). Membuka toko otomatis.`);
        window.setStoreOpenStatus(true, { isAuto: true });
    }
};

window.toggleAutoScheduleToko = async (status) => {
    window.storeSettings = window.storeSettings || {};
    window.storeSettings.auto_schedule_active = Boolean(status);
    try {
        localStorage.setItem('mainstay_store_settings', JSON.stringify(window.storeSettings));
        await update(ref(db, 'store_settings'), { auto_schedule_active: Boolean(status) });
    } catch(e) {}
    
    // Update switch UI & badges
    const chk = document.getElementById('fset-auto-schedule');
    if (chk) chk.checked = Boolean(status);
    const badge = document.getElementById('auto-schedule-status-badge');
    if (badge) {
        badge.className = `text-[9px] font-black px-2.5 py-0.5 rounded-full ${status ? 'bg-emerald-100 text-emerald-800 border border-emerald-300' : 'bg-slate-200 text-slate-700 border border-slate-300'}`;
        badge.innerText = status ? 'OTOMATIS AKTIF' : 'MANUAL PENUH (NONAKTIF)';
    }

    if (status) {
        window.evaluasiJamOperasionalToko(true);
        alert("✅ Fitur Otomatis Buka & Tutup Toko DIAKTIFKAN.\n\nToko akan otomatis buka dan tutup secara mandiri mengikuti jadwal jam operasional kedai.");
    } else {
        alert("ℹ️ Fitur Otomatis Buka & Tutup Toko DINONAKTIFKAN.\n\nSistem beralih ke mode MANUAL PENUH. Status toko tidak akan berubah otomatis kecuali diubah manual oleh Owner.");
    }
};

