window.filterKategori = (kategori, btnEl) => {
    activeCategoryFilter = kategori;
    
    // Reset semua tombol kategori ke mode putih
    const allBtns = document.querySelectorAll('.cat-btn');
    allBtns.forEach(btn => {
        btn.className = "cat-btn bg-white text-gray-600 border border-gray-200 px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap shadow-sm hover:bg-slate-50 transition";
    });
    
    // Ubah tombol yang sedang diklik menjadi orange aktif
    if (btnEl) {
        btnEl.className = "cat-btn active bg-amber-500 text-white px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap shadow-sm transition";
    }
    
    window.renderKatalog();
};

// ---------------------------------------------------------
// PENCARIAN TERAKHIR (RECENT SEARCHES)
// ---------------------------------------------------------
window.cekEnterSearch = (event) => {
    if (event.key === 'Enter') {
        const val = event.target.value.trim();
        if (val !== "") {
            window.saveRecentSearch(val);
        }
        event.target.blur(); // Hilangkan fokus keyboard mobile
    }
};

window.saveRecentSearch = (keyword) => {
    let recent = JSON.parse(localStorage.getItem('mainstay_recent_searches') || '[]');
    // Hapus jika sudah ada agar yang terbaru pindah ke depan
    recent = recent.filter(item => item.toLowerCase() !== keyword.toLowerCase());
    recent.unshift(keyword);
    // Maksimal simpan 5
    if (recent.length > 5) recent.pop();
    localStorage.setItem('mainstay_recent_searches', JSON.stringify(recent));
    window.renderRecentSearches();
};

window.renderRecentSearches = () => {
    const container = document.getElementById('recent-search-container');
    const list = document.getElementById('recent-search-list');
    if (!container || !list) return;

    const recent = JSON.parse(localStorage.getItem('mainstay_recent_searches') || '[]');
    if (recent.length === 0) {
        container.classList.add('hidden');
        return;
    }

    container.classList.remove('hidden');
    list.innerHTML = '';
    recent.forEach(keyword => {
        list.innerHTML += `
            <button onclick="applyRecentSearch('${keyword}')" class="bg-white border border-slate-200 text-slate-600 px-3 py-1.5 rounded-full text-[10px] font-bold shadow-sm hover:bg-amber-50 hover:text-amber-600 hover:border-amber-200 transition-all active:scale-95">
                ${keyword}
            </button>
        `;
    });
};

window.applyRecentSearch = (keyword) => {
    const searchInput = document.getElementById('search-menu');
    if (searchInput) {
        searchInput.value = keyword;
        window.renderKatalog();
        
        // Pindahkan pencarian ini kembali ke urutan teratas karena baru saja digunakan
        window.saveRecentSearch(keyword);
    }
};

window.clearRecentSearches = () => {
    localStorage.removeItem('mainstay_recent_searches');
    window.renderRecentSearches();
};

// ---------------------------------------------------------
// 2A-1. KALKULASI HARGA DISKON & PROMO
// ---------------------------------------------------------
window.getMenuEffectivePrice = (menu) => {
    if (!menu) return 0;
    const basePrice = Number(menu.price) || 0;
    
    let isPromo = false;
    if (menu.isPromo === true || menu.isPromo === 'true' || menu.promo === true || menu.isDiskon === true) isPromo = true;

    const discNominal = Number(menu.discountNominal) || 0;
    const discPercent = Number(menu.discountPercent) || 0;
    const promoPrice = Number(menu.promoPrice) || 0;

    // Otomatis aktifkan promo jika ada potongan nominal atau persentase diskon
    if (discNominal > 0 || discPercent > 0 || (promoPrice > 0 && promoPrice < basePrice)) {
        isPromo = true;
    }

    if (!isPromo) return basePrice;

    if (discNominal > 0) {
        return Math.max(0, basePrice - discNominal);
    }
    if (discPercent > 0) {
        return Math.max(0, Math.round(basePrice * (1 - discPercent / 100)));
    }
    if (promoPrice > 0 && promoPrice < basePrice) {
        return promoPrice;
    }
    return basePrice;
};

// ---------------------------------------------------------
// 2A-2. RENDER CAROUSEL PRODUK BEST SELLER & PROMO SPESIAL
// ---------------------------------------------------------
window.renderPromoBestsellerCarousel = () => {
    const section = document.getElementById('section-promo-bestseller');
    const container = document.getElementById('container-promo-bestseller');
    if (!container) {
        console.warn("[Carousel Diagnostic] container-promo-bestseller element not found in DOM");
        return;
    }

    const menuKeys = Object.keys(globalMenus || {});
    console.log(`[Carousel Diagnostic] Checking ${menuKeys.length} total menus in memory`);

    if (menuKeys.length === 0) {
        if (section) section.classList.add('hidden');
        return;
    }

    const isClosed = !isStoreOpen || window.statusTokoRealtime === false;
    if (isClosed) {
        if (section) section.classList.add('hidden');
        return;
    }

    // Filter produk yang ditandai Best Seller ATAU Promo Diskon
    let featuredKeys = menuKeys.filter(key => {
        const m = globalMenus[key];
        if (!m || m.isAvailable === false) return false;

        let isBS = false;
        for (const prop in m) {
            if (prop.toLowerCase().includes('best')) {
                if (m[prop] === true || m[prop] === 'true' || m[prop] === 1) isBS = true;
            }
        }
        if (m.isBestSeller === true || m.isBestSeller === 'true' || m.bestSeller === true) isBS = true;

        let isPr = false;
        if (m.isPromo === true || m.isPromo === 'true' || m.promo === true || m.isDiskon === true) isPr = true;
        const nom = Number(m.discountNominal) || 0;
        const pct = Number(m.discountPercent) || 0;
        const pPrice = Number(m.promoPrice) || 0;
        if (nom > 0 || pct > 0 || (pPrice > 0 && pPrice < Number(m.price))) {
            isPr = true;
        }

        return isBS || isPr;
    });

    console.log(`[Carousel Diagnostic] Found ${featuredKeys.length} featured (Best Seller/Promo) menus:`, featuredKeys);

    // Jika belum ada yang ditandai khusus di database, ambil 4 menu pertama
    if (featuredKeys.length === 0) {
        featuredKeys = menuKeys.filter(k => globalMenus[k] && globalMenus[k].isAvailable !== false).slice(0, 4);
        console.log(`[Carousel Diagnostic] Fallback to first ${featuredKeys.length} available menus`);
    }

    if (featuredKeys.length === 0) {
        if (section) section.classList.add('hidden');
        return;
    }

    if (section) section.classList.remove('hidden');
    container.innerHTML = '';
    const promoCards = [];

    featuredKeys.forEach(key => {
        const menu = globalMenus[key];
        const effPrice = window.getMenuEffectivePrice(menu);
        const hasDiscount = ((menu.isPromo === true || menu.isPromo === 'true') || effPrice < menu.price) && effPrice < menu.price;
        
        let isBS = false;
        for (const prop in menu) {
            if (prop.toLowerCase().includes('best') && (menu[prop] === true || menu[prop] === 'true' || menu[prop] === 1)) {
                isBS = true;
            }
        }
        if (menu.isBestSeller === true || menu.isBestSeller === 'true' || menu.bestSeller === true) isBS = true;

        const imgUrl = (menu.imageUrl && menu.imageUrl.trim() !== '') ? menu.imageUrl : 'logo-192.png';
        const clickAction = isClosed ? "window.tokoSedangTutupAlert()" : `bukaModalDetail('${key}')`;

        let discountTag = '';
        if (hasDiscount) {
            const hematNominal = Number(menu.price) - effPrice;
            const label = menu.promoLabel || (menu.discountPercent ? `-${menu.discountPercent}%` : `Hemat Rp ${hematNominal.toLocaleString('id-ID')}`);
            discountTag = `
                <span class="absolute top-2 left-2 bg-gradient-to-r from-rose-600 to-amber-500 text-white text-[9px] font-black px-2 py-0.5 rounded-lg shadow-sm z-10 flex items-center gap-1 uppercase tracking-wider">
                    <i class="fa-solid fa-tag text-[8px]"></i> ${label}
                </span>`;
        }

        let bestSellerTag = '';
        if (isBS && !isClosed) {
            bestSellerTag = `
                <span class="absolute top-2 right-2 bg-gradient-to-r from-amber-500 to-orange-500 text-slate-900 text-[9px] font-black px-2 py-0.5 rounded-lg shadow-sm z-10 flex items-center gap-1 uppercase tracking-wider">
                    <i class="fa-solid fa-fire text-amber-900 text-[8px]"></i> BEST
                </span>`;
        }

        let priceHtml = '';
        if (hasDiscount) {
            priceHtml = `
                <div class="flex flex-col">
                    <span class="text-[9px] text-slate-400 line-through leading-tight">Rp ${Number(menu.price).toLocaleString('id-ID')}</span>
                    <span class="text-xs font-black text-rose-600 leading-tight">Rp ${effPrice.toLocaleString('id-ID')}</span>
                </div>`;
        } else {
            priceHtml = `<span class="text-xs font-black ${isClosed ? 'text-slate-400' : 'text-amber-600'}">${formatRupiah(menu.price)}</span>`;
        }

        const card = `
            <div onclick="${clickAction}" class="w-48 sm:w-52 shrink-0 bg-white rounded-2xl p-2.5 shadow-sm border border-amber-100/90 flex flex-col justify-between cursor-pointer group hover:-translate-y-1 hover:shadow-md transition duration-200 select-none">
                <div>
                    <div class="w-full aspect-[4/3] bg-slate-100 rounded-xl overflow-hidden relative mb-2">
                        <img src="${imgUrl}" alt="${menu.name}" loading="lazy" decoding="async" class="w-full h-full object-cover group-hover:scale-105 transition duration-300" onerror="this.src='logo-192.png'">
                        ${discountTag}
                        ${bestSellerTag}
                        ${isClosed ? '<span class="absolute inset-0 bg-slate-900/40 backdrop-blur-[1px] flex items-center justify-center text-white text-[10px] font-black"><i class="fa-solid fa-lock mr-1"></i> Tutup</span>' : ''}
                    </div>
                    <div class="px-1">
                        <span class="text-[9px] font-bold text-amber-600 uppercase tracking-wider">${menu.category || 'Menu'}</span>
                        <h4 class="text-xs font-black text-slate-800 leading-tight line-clamp-1 mt-0.5 mb-1">${menu.name}</h4>
                        <p class="text-[9px] text-slate-500 font-medium line-clamp-1 mb-2">${menu.description || 'Pilihan favorit segar & nikmat'}</p>
                    </div>
                </div>
                <div class="px-1 pt-1.5 border-t border-slate-100 flex items-center justify-between mt-auto">
                    ${priceHtml}
                    <button class="px-2.5 py-1 rounded-lg bg-amber-500 hover:bg-amber-600 text-white font-black text-[10px] flex items-center gap-1 shadow-2xs active:scale-95 transition">
                        <i class="fa-solid fa-plus text-[9px]"></i> Pesan
                    </button>
                </div>
            </div>
        `;
        promoCards.push(card);
    });

    container.innerHTML = promoCards.join('');
    window.initPromoCarouselAutoScroll();
};

window.scrollPromoCarousel = (direction) => {
    const container = document.getElementById('container-promo-bestseller');
    if (!container) return;
    const offset = direction === 'left' ? -220 : 220;
    container.scrollBy({ left: offset, behavior: 'smooth' });
};

window.initPromoCarouselAutoScroll = () => {
    if (window._promoScrollInterval) clearInterval(window._promoScrollInterval);
    const container = document.getElementById('container-promo-bestseller');
    if (!container) return;

    let isHovered = false;
    container.onmouseenter = () => { isHovered = true; };
    container.onmouseleave = () => { isHovered = false; };
    container.ontouchstart = () => { isHovered = true; };
    container.ontouchend = () => { setTimeout(() => { isHovered = false; }, 2500); };

    window._promoScrollInterval = setInterval(() => {
        if (isHovered || !container || container.children.length <= 1) return;
        const maxScroll = container.scrollWidth - container.clientWidth;
        if (container.scrollLeft >= maxScroll - 15) {
            container.scrollTo({ left: 0, behavior: 'smooth' });
        } else {
            container.scrollBy({ left: 220, behavior: 'smooth' });
        }
    }, 3500);
};

// ---------------------------------------------------------
// 2B. RENDER GRID KATALOG MENU
// ---------------------------------------------------------
window.debouncedRenderKatalog = window.debounceUiFn(() => {
    if (typeof window.renderKatalog === 'function') window.renderKatalog();
}, 140);

window.renderKatalog = () => {
    // Tampilkan recent searches setiap kali katalog dirender
    if (typeof window.renderRecentSearches === 'function') {
        window.renderRecentSearches();
    }
    
    // --- NYALAKAN TOMBOL KATEGORI DINAMIS OTOMATIS ---
    if(typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();

    // --- RENDER CAROUSEL PROMO & BEST SELLER OTOMATIS ---
    if(typeof window.renderPromoBestsellerCarousel === 'function') window.renderPromoBestsellerCarousel();

    const grid = document.getElementById('menu-grid');
    const searchInput = document.getElementById('search-menu');
    const searchQuery = searchInput ? searchInput.value.toLowerCase() : '';

    if (!grid) return;

    grid.innerHTML = ''; // Kosongkan state loading
    let menuKeys = Object.keys(globalMenus || {});

    if (menuKeys.length === 0) {
        try {
            const cached = localStorage.getItem('mainstay_cached_menus');
            if (cached) {
                const parsed = JSON.parse(cached);
                if (parsed && typeof parsed === 'object' && Object.keys(parsed).length > 0) {
                    globalMenus = parsed;
                    menuKeys = Object.keys(globalMenus);
                }
            }
        } catch(e) {}
    }

    if (menuKeys.length === 0) {
        grid.innerHTML = `
            <div class="col-span-full text-center py-10 text-gray-400 font-bold">
                Belum ada menu di database.
            </div>`;
        return;
    }

    const isClosed = !isStoreOpen || window.statusTokoRealtime === false;

    if (isClosed) {
        const s = window.storeSettings || {};
        const hoursText = s.store_hours || (s.jam_buka && s.jam_tutup ? `${s.hari_operasional || 'Setiap Hari'} (${s.jam_buka} - ${s.jam_tutup} ${s.zona_waktu || 'WIB'})` : 'Setiap Hari (10:00 - 22:00 WIB)');
        grid.innerHTML = `
            <div class="col-span-full py-12 px-6 bg-white rounded-3xl border border-rose-200 shadow-sm text-center flex flex-col items-center justify-center space-y-4 animate-fade-in my-2">
                <div class="w-20 h-20 rounded-full bg-rose-50 border border-rose-200 text-rose-500 flex items-center justify-center text-3xl shadow-inner">
                    <i class="fa-solid fa-store-slash"></i>
                </div>
                <div class="space-y-1.5 max-w-md">
                    <span class="inline-flex items-center gap-1.5 bg-rose-100 text-rose-700 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-wider">
                        <i class="fa-solid fa-circle text-[6px] animate-pulse"></i> Sedang Tidak Menerima Pesanan
                    </span>
                    <h3 class="text-lg font-black text-slate-800">Kedai Sedang Tutup</h3>
                    <p class="text-xs text-slate-500 font-medium leading-relaxed">Mohon maaf, saat ini kedai sedang tutup sementara dan menu tidak dapat diakses untuk pemesanan.</p>
                </div>
                <div class="p-3.5 bg-amber-50 rounded-2xl border border-amber-200 text-amber-900 text-xs font-bold inline-flex items-center gap-2 shadow-2xs">
                    <i class="fa-solid fa-clock text-amber-600 text-sm"></i>
                    <span>Jam Operasional: <strong>${hoursText}</strong></span>
                </div>
                <p class="text-[11px] text-slate-400 font-medium">Silakan kunjungi kami kembali pada jam operasional kedai. Terima kasih!</p>
            </div>
        `;

        const cartBtn = document.getElementById('btn-cart-floating');
        if (cartBtn) cartBtn.classList.add('hidden');
        const promoCarousel = document.getElementById('section-promo-bestseller');
        if (promoCarousel) promoCarousel.classList.add('hidden');
        return;
    }

    const promoCarousel = document.getElementById('section-promo-bestseller');
    if (promoCarousel) promoCarousel.classList.remove('hidden');

    const cardsHtml = [];

window.menuHabisAlert = (namaMenu) => {
    if (typeof window.showNotification === 'function') {
        window.showNotification(`Mohon maaf, menu "${namaMenu || 'ini'}" saat ini sedang HABIS / tidak tersedia 🙏`, 'warning');
    } else {
        alert(`Mohon maaf, menu "${namaMenu || 'ini'}" saat ini sedang HABIS / tidak tersedia 🙏`);
    }
};

    menuKeys.forEach(key => {
        const menu = globalMenus[key];

        // Lewati (skip) jika tidak sesuai dengan filter kategori aktif
        if (activeCategoryFilter !== 'all' && (!menu.category || menu.category.toLowerCase() !== activeCategoryFilter.toLowerCase())) return;

        // Lewati jika tidak sesuai dengan kata kunci pencarian
        if (searchQuery && !menu.name.toLowerCase().includes(searchQuery)) return;

        // Evaluasi ketersediaan menu (default: true jika undefined)
        const isMenuAvailable = menu.isAvailable !== false;

        // Gunakan placeholder jika url gambar kosong
        const imgUrl = (menu.imageUrl && menu.imageUrl.trim() !== '') ? menu.imageUrl : 'logo-192.png';

        const safeMenuName = (menu.name || '').replace(/'/g, "\\'");
        const clickAction = isClosed 
            ? "window.tokoSedangTutupAlert()" 
            : (!isMenuAvailable 
                ? `window.menuHabisAlert('${safeMenuName}')` 
                : `bukaModalDetail('${key}')`);

        const cardClass = isClosed 
            ? "w-full bg-slate-50/95 rounded-2xl p-2 shadow-xs border border-slate-200 flex flex-col cursor-not-allowed opacity-65 filter grayscale-[0.4] relative select-none"
            : (!isMenuAvailable
                ? "w-full bg-slate-50/90 rounded-2xl p-2 shadow-xs border border-rose-200/60 flex flex-col cursor-pointer opacity-70 filter grayscale-[0.3] relative select-none group hover:border-rose-300 transition duration-200"
                : "w-full bg-white rounded-2xl p-2 shadow-sm border border-gray-100 flex flex-col cursor-pointer group hover:-translate-y-1 active:scale-95 hover:shadow-md transition duration-200");

        // Hitung harga efektif setelah promo/diskon
        const effPrice = window.getMenuEffectivePrice(menu);
        const hasDiscount = (menu.isPromo === true || menu.isPromo === 'true') && effPrice < menu.price;

        let promoBadge = '';
        if (hasDiscount && isMenuAvailable) {
            const hemat = Number(menu.price) - effPrice;
            const promoLbl = menu.promoLabel || (menu.discountPercent ? `-${menu.discountPercent}%` : `Hemat Rp ${hemat.toLocaleString('id-ID')}`);
            promoBadge = `<span class="absolute top-2 right-2 bg-gradient-to-r from-rose-600 to-amber-500 text-white text-[8px] font-black px-2 py-0.5 rounded shadow z-10 flex items-center gap-1 uppercase tracking-wider"><i class="fa-solid fa-tag text-[7px]"></i>${promoLbl}</span>`;
        }

        let priceDisplay = '';
        if (hasDiscount && isMenuAvailable) {
            priceDisplay = `
                <div class="flex flex-col">
                    <span class="text-[9px] text-gray-400 line-through leading-tight">Rp ${Number(menu.price).toLocaleString('id-ID')}</span>
                    <span class="text-sm font-black text-rose-600 leading-tight">Rp ${effPrice.toLocaleString('id-ID')}</span>
                </div>
            `;
        } else {
            priceDisplay = `<span class="text-sm font-black ${isClosed || !isMenuAvailable ? 'text-slate-400' : 'text-amber-500'}">${formatRupiah(menu.price)}</span>`;
        }

        // Rancang Card HTML Menu dengan lazy decoding
        const cardHtml = `
            <div onclick="${clickAction}" class="${cardClass}">
                <div class="w-full aspect-square bg-slate-100 rounded-xl overflow-hidden relative mb-2">
                    <img src="${imgUrl}" alt="${menu.name}" loading="lazy" decoding="async" class="w-full h-full object-cover ${isClosed || !isMenuAvailable ? '' : 'group-hover:scale-105 transition duration-300'}" onerror="this.src='logo-192.png'">
                    ${menu.isBestSeller && !isClosed && isMenuAvailable ? '<span class="absolute top-2 left-2 bg-red-500 text-white text-[8px] font-black px-2 py-1 rounded-md shadow-sm z-10 flex items-center gap-0.5"><i class="fa-solid fa-fire text-[7px]"></i>BEST</span>' : ''}
                    ${promoBadge}
                    ${!isMenuAvailable ? '<span class="absolute inset-0 bg-slate-900/40 backdrop-blur-[0.5px] flex items-center justify-center z-10 rounded-xl"><span class="bg-rose-600 text-white text-[9px] font-black px-2.5 py-1 rounded-full shadow-md uppercase tracking-wider flex items-center gap-1"><i class="fa-solid fa-ban text-[8px]"></i> HABIS</span></span>' : ''}
                    ${isClosed ? '<span class="absolute top-2 right-2 bg-red-600/95 text-white text-[8px] font-black px-2 py-0.5 rounded shadow z-10 uppercase tracking-wider flex items-center gap-1"><i class="fa-solid fa-lock text-[7px]"></i> Tutup</span>' : ''}
                </div>
                
                <div class="px-1 flex-1 flex flex-col justify-between">
                    <div>
                        <h3 class="text-xs font-black ${!isMenuAvailable ? 'text-slate-600' : 'text-gray-900'} leading-tight mb-0.5">${menu.name}</h3>
                        <p class="text-[9px] font-medium text-gray-500 leading-tight line-clamp-2 mt-0.5 mb-1 h-[26px] overflow-hidden">${menu.description || ''}</p>
                    </div>
                    
                    <div class="mt-2 flex justify-between items-end">
                        ${priceDisplay}
                        ${isClosed 
                            ? '<span class="w-6 h-6 shrink-0 bg-slate-200 text-slate-400 rounded-full flex items-center justify-center text-[10px]"><i class="fa-solid fa-ban"></i></span>'
                            : (!isMenuAvailable
                                ? '<span class="px-2 py-0.5 bg-rose-100 text-rose-700 font-black text-[9px] rounded-full flex items-center gap-1">Habis</span>'
                                : '<button class="w-6 h-6 shrink-0 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center text-[10px]"><i class="fa-solid fa-plus"></i></button>')
                        }
                    </div>
                </div>
            </div>
        `;
        
        cardsHtml.push(cardHtml);
    });

    if (cardsHtml.length === 0) {
        grid.innerHTML = `
            <div class="col-span-full text-center py-10 text-gray-400 font-bold">
                Tidak ada menu yang sesuai dengan filter atau kata kunci pencarian.
            </div>`;
    } else {
        grid.innerHTML = cardsHtml.join('');
    }
};
// ---------------------------------------------------------
// 2C. MODAL DETAIL & KUSTOMISASI MINUMAN
// ---------------------------------------------------------
// ==========================================
// PAKET MESIN POP-UP, QTY, HARGA & KERANJANG
// ==========================================

window._realBukaModalDetail = (key) => {
    if (!navigator.onLine || window.isAppOnline === false) {
        alert("Mode Offline: Pemesanan mandiri tidak tersedia saat jaringan offline. Silakan lakukan pemesanan langsung di meja Kasir POS.");
        return;
    }
    if (!isStoreOpen || window.statusTokoRealtime === false) {
        window.tokoSedangTutupAlert();
        return;
    }
    const allM = (typeof window.globalMenus !== 'undefined' && window.globalMenus) 
        || (typeof globalMenus !== 'undefined' && globalMenus) 
        || JSON.parse(localStorage.getItem('mainstay_cached_menus') || '{}');
    const menu = allM[key] || Object.values(allM).find(m => m && (m.id === key || m.key === key));
    if (!menu) return;

    currentDetailMenu = { key: key, ...menu };
    detailQty = 1;

    const modal = document.getElementById('modal-detail') || document.querySelector('.modal');
    if (!modal) return;

    // A. SUNTIK CSS UNTUK MENGHILANGKAN VARIAN HTML BAWAAN
    if (!document.getElementById('css-penghancur-varian')) {
        const style = document.createElement('style');
        style.id = 'css-penghancur-varian';
        style.innerHTML = `
            #modal-detail label:not(#wadah-modal-varian label),
            #modal-detail .uppercase:not(#wadah-modal-varian .uppercase) { display: none !important; }
            #wadah-modal-varian label { display: flex !important; }
            #wadah-modal-varian .uppercase { display: block !important; }
        `;
        document.head.appendChild(style);
    }

    // B. SINKRONISASI GAMBAR
    const img = modal.querySelector('img');
    if (img) {
        img.src = (menu.imageUrl && menu.imageUrl.trim() !== '') ? menu.imageUrl : 'logo-192.png';
        img.onerror = () => { img.src = 'logo-192.png'; };
    }

    // C. SINKRONISASI JUDUL & DESKRIPSI
    const allTags = modal.querySelectorAll('*');
    allTags.forEach(el => {
        if (el.children.length === 0) {
            if (el.dataset.target === 'title' || el.innerText.trim() === 'Nama Menu' || el.innerText.trim() === 'Thai Tea Original') {
                el.innerText = menu.name;
                el.dataset.target = 'title';
            }
            if (el.dataset.target === 'desc' || el.innerText.includes('Deskripsi menu') || el.innerText.includes('Teh Thailand asli')) {
                el.innerText = menu.description ? menu.description : 'Tidak ada deskripsi untuk menu ini.';
                el.dataset.target = 'desc';
            }
        }
    });

    // D. BANGUN WADAH VARIAN DINAMIS
    let wadahVarian = document.getElementById('wadah-modal-varian');
    if (!wadahVarian) {
        wadahVarian = document.createElement('div');
        wadahVarian.id = 'wadah-modal-varian';
        // Beri margin bawah (mb-28) dan padding bawah (pb-8) agar ruang scroll ekstra luas dan tidak menabrak footer
        wadahVarian.className = 'w-full mb-28 pb-8 max-h-[60vh] overflow-y-auto px-1';

        const qtyBlock = document.getElementById('detail-qty');
        if (qtyBlock) {
            const footer = qtyBlock.closest('.flex.items-center.justify-between') || qtyBlock.parentElement.parentElement;
            if (footer && footer.parentElement) footer.parentElement.insertBefore(wadahVarian, footer);
        }
    }

    // E. TARIK DATA VARIAN & TOPPING DARI DATABASE
    let vHtml = '';
    
    // 1. Tarik Data Varian (HANYA jika menu memiliki varian yang dicentang di katalog owner)
    const hasVarian = menu.hasVariant === true || (menu.hasVariant !== false && Array.isArray(menu.varianIds) && menu.varianIds.length > 0);
    const linkedVarianIds = hasVarian 
        ? (Array.isArray(menu.varianIds) && menu.varianIds.length > 0 ? menu.varianIds : (menu.hasVariant === true && Array.isArray(menu.varian) ? menu.varian : [])) 
        : [];

    let filteredVar = linkedVarianIds.map(vid => typeof window.resolveVarian === 'function' ? window.resolveVarian(vid) : null).filter(Boolean);

    // 2. Tarik Data Topping (HANYA jika menu memiliki topping yang dicentang di katalog owner)
    const hasTopping = menu.hasTopping === true || (menu.hasTopping !== false && Array.isArray(menu.toppingIds) && menu.toppingIds.length > 0);
    const linkedToppingIds = hasTopping
        ? (Array.isArray(menu.toppingIds) && menu.toppingIds.length > 0 ? menu.toppingIds : (menu.hasTopping === true && Array.isArray(menu.toppings) ? menu.toppings : []))
        : [];

    let filteredTop = linkedToppingIds.map(tid => typeof window.resolveTopping === 'function' ? window.resolveTopping(tid) : null).filter(Boolean);

    if (filteredVar.length > 0 || filteredTop.length > 0) {
        // Render Tampilan Varian Berdasarkan Grup Independen (Ukuran Cup, Level Gula, Level Es)
        // Setiap grup memiliki name unik berkode index (detail_grp_[vIndex]_[rawId])
        // agar titik radio pilihan di Ukuran Cup tidak pernah hilang saat memilih Kadar Es/Gula
        filteredVar.forEach((v, vIndex) => {
            const rawId = String(v.id || v.name || v.nama || ('var_' + vIndex)).toLowerCase().replace(/[^a-z0-9_-]/g, '_');
            const vGroupName = `detail_grp_${vIndex}_${rawId}`;
            const vName = v.name || v.nama || `Varian ${vIndex + 1}`;
            vHtml += `
                <div class="mb-4 bg-slate-50 p-3 rounded-xl border border-slate-200">
                    <label class="text-xs font-black text-slate-700 uppercase block mb-2 flex items-center gap-1.5">
                        <i class="fa-solid fa-layer-group text-amber-600"></i> ${vName}
                    </label>
                    <div class="grid grid-cols-2 gap-2">
            `;
            (v.opsi || []).forEach((o, idx) => {
                const extraPrice = Number(o.harga || o.price || 0);
                const hargaOpsi = extraPrice > 0 ? ` (+Rp ${extraPrice.toLocaleString('id-ID')})` : '';
                const optName = o.namaOpsi || o.name || o.nama || '';
                const radioId = `detail_radio_${vIndex}_${idx}`;
                vHtml += `
                    <label for="${radioId}" class="flex items-center gap-2 p-2.5 bg-white border border-slate-200 rounded-xl cursor-pointer hover:border-amber-400 has-[:checked]:border-amber-500 has-[:checked]:bg-amber-50/70 has-[:checked]:ring-1 has-[:checked]:ring-amber-500 transition shadow-sm">
                        <input type="radio" id="${radioId}" name="${vGroupName}" value="${optName}" data-group-name="${vName}" data-harga="${extraPrice}" ${idx === 0 ? 'checked' : ''} class="w-4 h-4 text-amber-500 focus:ring-amber-400 border-slate-300" onchange="window.hitungTotalHargaDetail()">
                        <div class="min-w-0 flex-1">
                            <span class="text-xs font-bold text-slate-800 block leading-tight truncate">${optName}</span>
                            <span class="text-[10px] text-amber-600 font-medium">${hargaOpsi || 'Normal'}</span>
                        </div>
                    </label>
                `;
            });
            vHtml += `</div></div>`;
        });

        // Render Tampilan Extra Topping (Boba, Keju, Telur, dll)
        if (filteredTop.length > 0) {
            vHtml += `
                <div class="mb-4 bg-amber-50/50 p-3 rounded-xl border border-amber-200">
                    <label class="text-xs font-black text-amber-800 uppercase block mb-2 flex items-center gap-1.5">
                        <i class="fa-solid fa-cheese text-amber-600"></i> Extra Topping (Opsional)
                    </label>
                    <div class="grid grid-cols-2 gap-2">
            `;
            filteredTop.forEach((t, tIdx) => {
                const extraPrice = Number(t.harga || t.price || 0);
                const topName = t.nama || t.name || 'Topping';
                const topId = t.id || ('top_' + tIdx);
                const cbId = `detail_cb_${tIdx}`;
                vHtml += `
                    <label for="${cbId}" class="flex items-center gap-2 p-2.5 bg-white border border-slate-200 rounded-xl cursor-pointer hover:border-amber-400 has-[:checked]:border-amber-500 has-[:checked]:bg-amber-50/70 transition shadow-sm">
                        <input type="checkbox" id="${cbId}" name="detail_topping_${topId}" value="${topName}" data-nama="${topName}" data-harga="${extraPrice}" class="w-4 h-4 text-amber-500 focus:ring-amber-400 rounded border-slate-300" onchange="window.hitungTotalHargaDetail()">
                        <div class="min-w-0 flex-1">
                            <span class="text-xs font-bold text-slate-800 block leading-tight truncate">${topName}</span>
                            <span class="text-[10px] text-amber-600 font-bold">+Rp ${extraPrice.toLocaleString('id-ID')}</span>
                        </div>
                    </label>
                `;
            });
            vHtml += `</div></div>`;
        }

    } else {
        vHtml = '<p class="text-xs text-slate-400 italic text-center py-2">Tidak ada varian/topping.</p>';
    }
    wadahVarian.innerHTML = vHtml;
    
    const qtyEl = document.getElementById('detail-qty');
    if (qtyEl) qtyEl.innerText = detailQty;

    window.hitungTotalHargaDetail();
    modal.classList.remove('hidden');
    modal.classList.add('flex');
};

window.bukaModalDetail = window._realBukaModalDetail;
if (window._pendingModalDetailKey) {
    const _queuedKey = window._pendingModalDetailKey;
    delete window._pendingModalDetailKey;
    setTimeout(() => {
        if (typeof window.bukaModalDetail === 'function') {
            window.bukaModalDetail(_queuedKey);
        }
    }, 50);
}

window.closeModalDetail = () => {
    const modal = document.getElementById('modal-detail') || document.querySelector('.modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.ubahQtyDetail = (amount) => {
    if (detailQty + amount >= 1) {
        detailQty += amount;
        const qtyEl = document.getElementById('detail-qty');
        if (qtyEl) qtyEl.innerText = detailQty;
        window.hitungTotalHargaDetail();
    }
};

window.hitungTotalHargaDetail = () => {
    if (!currentDetailMenu) return;
    let base = (typeof window.getMenuEffectivePrice === 'function')
        ? window.getMenuEffectivePrice(currentDetailMenu)
        : (Number(currentDetailMenu.price) || 0);

    const inputs = document.querySelectorAll('#wadah-modal-varian input:checked');
    inputs.forEach(input => {
        base += Number(input.dataset.harga) || 0;
    });

    let total = base * (detailQty || 1);

    // 1. Tembak langsung ke Tombol Tambah-nya
    const btnTambah = document.querySelector('#modal-detail button.bg-amber-500');
    if (btnTambah) {
         btnTambah.innerHTML = `
            <div class="flex items-center justify-center gap-2 w-full whitespace-nowrap">
                <i class="fa-solid fa-cart-plus text-lg"></i>
                <span class="bg-white/20 border border-white/20 px-2 py-0.5 rounded-lg font-black text-[14px] tracking-wide">
                    Rp ${total.toLocaleString('id-ID')}
                </span>
            </div>
         `;
    }

    // 2. Tembak juga elemen teks harga (jika ada) agar tidak error
    const priceSpan = document.getElementById('detail-total-price');
    if (priceSpan && priceSpan.tagName !== 'BUTTON') {
         priceSpan.innerText = 'Rp ' + total.toLocaleString('id-ID');
    }
};
window.tambahKeKeranjang = () => {
    if (!navigator.onLine || window.isAppOnline === false) {
        alert("Mode Offline: Pemesanan mandiri tidak tersedia saat jaringan offline. Silakan lakukan pemesanan langsung di meja Kasir POS.");
        return;
    }
    if (!currentDetailMenu) return;

    const origBasePrice = Number(currentDetailMenu.price) || 0;
    const effBasePrice = (typeof window.getMenuEffectivePrice === 'function')
        ? window.getMenuEffectivePrice(currentDetailMenu)
        : origBasePrice;

    let extraPrice = 0;
    let notesArr = [];

    const inputs = document.querySelectorAll('#wadah-modal-varian input:checked');
    inputs.forEach(input => {
        extraPrice += Number(input.dataset.harga) || 0;
        notesArr.push(input.value);
    });

    const itemPrice = effBasePrice + extraPrice;
    const origItemPrice = Math.max(itemPrice, origBasePrice + extraPrice);

    cart.push({
        id: currentDetailMenu.key,
        name: currentDetailMenu.name,
        qty: detailQty,
        price: itemPrice,
        originalPrice: origItemPrice,
        total: itemPrice * (detailQty || 1),
        notes: notesArr.join(', '),
        imageUrl: (currentDetailMenu.imageUrl && currentDetailMenu.imageUrl.trim() !== '') ? currentDetailMenu.imageUrl : 'logo-192.png'
    });

    if (typeof window.updateCartBadge === 'function') window.updateCartBadge(true);
    if (typeof window.closeModalDetail === 'function') window.closeModalDetail();
};

window.triggerCartBadgePulseShake = (el) => {
    if (!el) return;
    if (el._cartAnimTimer) {
        clearTimeout(el._cartAnimTimer);
        el._cartAnimTimer = null;
    }
    el.classList.remove('cart-badge-pulse-shake');
    void el.offsetWidth;
    el.classList.add('cart-badge-pulse-shake');
    const onEnd = () => {
        el.classList.remove('cart-badge-pulse-shake');
        el.removeEventListener('animationend', onEnd);
        if (el._cartAnimTimer) {
            clearTimeout(el._cartAnimTimer);
            el._cartAnimTimer = null;
        }
    };
    el.addEventListener('animationend', onEnd);
    el._cartAnimTimer = setTimeout(onEnd, 520);
};

window.triggerCartBadgePulse = (el) => {
    if (!el) return;
    if (el._cartPulseTimer) {
        clearTimeout(el._cartPulseTimer);
        el._cartPulseTimer = null;
    }
    if (el._cartPulseRaf) {
        cancelAnimationFrame(el._cartPulseRaf);
        el._cartPulseRaf = null;
    }
    el.classList.remove('cart-badge-pulse');
    const playPulse = () => {
        el._cartPulseRaf = null;
        void el.offsetWidth;
        el.classList.add('cart-badge-pulse');
        const onEnd = () => {
            el.classList.remove('cart-badge-pulse');
            el.removeEventListener('animationend', onEnd);
            if (el._cartPulseTimer) {
                clearTimeout(el._cartPulseTimer);
                el._cartPulseTimer = null;
            }
        };
        el.addEventListener('animationend', onEnd);
        el._cartPulseTimer = setTimeout(onEnd, 720);
    };
    el._cartPulseRaf = requestAnimationFrame(playPulse);
};

window.updateCartBadge = (forcePulse = false) => {
    const btnCart = document.getElementById('btn-cart-floating');
    const badge = document.getElementById('cart-badge');
    const isOnline = navigator.onLine && window.isAppOnline !== false;

    if (btnCart && badge) {
        const prevCount = Number(badge.dataset.lastCount || 0);
        const prevTotalQty = Number(badge.dataset.lastTotalQty || 0);
        const nextCount = cart.length;
        const nextTotalQty = cart.reduce((sum, item) => sum + Math.max(1, Number(item?.qty) || 1), 0);
        if (nextCount > 0 && isOnline) {
            btnCart.classList.remove('hidden');
            btnCart.classList.add('flex');
            badge.innerText = nextCount;
            badge.dataset.lastCount = String(nextCount);
            badge.dataset.lastTotalQty = String(nextTotalQty);
            if (forcePulse === true || nextCount > prevCount || nextTotalQty > prevTotalQty) {
                if (typeof window.triggerCartBadgePulse === 'function') {
                    window.triggerCartBadgePulse(badge);
                } else {
                    window.triggerCartBadgePulseShake(badge);
                }
            }
        } else {
            btnCart.classList.add('hidden');
            btnCart.classList.remove('flex');
            badge.dataset.lastCount = '0';
            badge.dataset.lastTotalQty = '0';
        }
    }
};

window.hapusItemKeranjang = (index) => {
    cart.splice(index, 1);
    window.updateCartBadge();
    
    // Jika keranjang kosong setelah dihapus, tutup modal checkout
    if (cart.length === 0) {
        window.closeModalCheckout();
    } else {
        window.bukaModalCheckout(); // Render ulang daftar
    }
};

// ==========================================
// 1. MODAL CHECKOUT & RENDER KERANJANG
// ==========================================
window.bukaModalCheckout = () => {
    if (!navigator.onLine || window.isAppOnline === false) {
        alert("Mode Offline: Pemesanan mandiri tidak tersedia saat perangkat offline. Silakan lakukan pemesanan langsung di meja Kasir POS.");
        return;
    }
    const listEl = document.getElementById('checkout-list');
    if (!listEl) return;
    
    listEl.innerHTML = '';
    let grandTotal = 0;

    cart.forEach((item, index) => {
        // Cegah error jika total harganya belum terbaca
        const hargaTotal = Number(item.total) || 0;
        grandTotal += hargaTotal;

        const qtyNum = Math.max(1, Number(item.qty) || 1);
        const menuAsli = globalMenus[item.id];
        const imgUrl = (menuAsli && menuAsli.imageUrl) ? menuAsli.imageUrl : 'logo-192.png';

        let origUnit = Number(item.originalPrice || 0);
        if ((!origUnit || origUnit <= Number(item.price || 0)) && menuAsli && typeof window.getMenuEffectivePrice === 'function') {
            const mOrig = Number(menuAsli.price || menuAsli.harga || 0);
            const mEff = Number(window.getMenuEffectivePrice(menuAsli));
            if (mOrig > mEff) {
                origUnit = Number(item.price || 0) + (mOrig - mEff);
            }
        }
        const origTotal = origUnit > Number(item.price || 0) ? (origUnit * qtyNum) : hargaTotal;
        const hasItemDiscount = !item.isLoyaltyReward && origTotal > hargaTotal;
        const savedAmount = Math.max(0, origTotal - hargaTotal);
        const savedPct = origTotal > 0 ? Math.round((savedAmount / origTotal) * 100) : 0;

        const html = `
            <div class="flex items-center gap-3 py-3 border-b border-slate-100 last:border-0 relative ${hasItemDiscount ? 'bg-emerald-50/40 -mx-1 px-2 rounded-xl border border-emerald-200/70' : ''}">
                <div class="w-14 h-14 bg-slate-50 rounded-xl overflow-hidden shrink-0 shadow-sm border border-slate-200/50 flex items-center justify-center">
                    <img src="${imgUrl}" alt="${item.name}" class="w-full h-full object-cover" onerror="this.onerror=null; this.src='logo-192.png'">
                </div>
                
                <div class="flex-1 pr-8 min-w-0">
                    <h4 class="text-xs font-black text-slate-800 leading-tight mb-0.5 flex items-center gap-1.5 flex-wrap">
                        <span>${item.name}</span>
                        ${item.isLoyaltyReward ? '<span class="bg-emerald-100 text-emerald-800 text-[9px] font-black px-2 py-0.5 rounded-full inline-flex items-center gap-1"><i class="fa-solid fa-gift"></i> GRATIS</span>' : ''}
                        ${hasItemDiscount ? `<span class="bg-emerald-100 text-emerald-800 border border-emerald-200 text-[9px] font-black px-1.5 py-0.5 rounded-md inline-flex items-center gap-1"><i class="fa-solid fa-tag text-[8px]"></i> Diskon -${savedPct}%</span>` : ''}
                    </h4>
                    <p class="text-[9px] text-slate-500 font-medium leading-snug mb-1">${item.notes || ''}</p>
                    
                    <div class="flex items-center flex-wrap gap-2.5 mt-1.5">
                        ${item.isLoyaltyReward ? `
                            <span class="text-[10px] font-black text-emerald-700 bg-emerald-50 border border-emerald-200 px-2.5 py-0.5 rounded-lg">1 Klaim Hadiah</span>
                            <span class="text-[11px] font-black text-emerald-600 tabular-nums">Rp 0 (${item.costSessions || 1} Sesi)</span>
                        ` : `
                            <div class="flex items-center gap-2 bg-slate-50 rounded-lg border border-slate-200 shadow-sm px-1.5 py-0.5">
                                <button onclick="window.ubahQtyKeranjang(${index}, -1)" class="w-5 h-5 flex justify-center items-center text-slate-400 hover:text-amber-500 transition">
                                    <i class="fa-solid fa-minus text-[9px]"></i>
                                </button>
                                <span class="text-[10px] font-black text-slate-800 w-3 text-center tabular-nums">${item.qty}</span>
                                <button onclick="window.ubahQtyKeranjang(${index}, 1)" class="w-5 h-5 flex justify-center items-center text-slate-400 hover:text-amber-500 transition">
                                    <i class="fa-solid fa-plus text-[9px]"></i>
                                </button>
                            </div>
                            <div class="flex items-center gap-1.5 tabular-nums flex-wrap">
                                ${hasItemDiscount ? `<span class="text-[10px] text-slate-400 line-through">Rp ${origTotal.toLocaleString('id-ID')}</span>` : ''}
                                <span class="text-[11px] font-black ${hasItemDiscount ? 'text-emerald-700' : 'text-slate-800'}">Rp ${hargaTotal.toLocaleString('id-ID')}</span>
                                ${hasItemDiscount ? `<span class="text-[9px] font-bold text-emerald-600">(Hemat Rp ${savedAmount.toLocaleString('id-ID')})</span>` : ''}
                            </div>
                        `}
                    </div>
                </div>

                <button onclick="window.hapusItemKeranjang(${index})" class="absolute right-1 top-1/2 -translate-y-1/2 w-7 h-7 shrink-0 flex items-center justify-center text-red-400 hover:text-red-600 bg-red-50 hover:bg-red-100 rounded-full transition shadow-sm">
                    <i class="fa-solid fa-trash-can text-sm"></i>
                </button>
            </div>
        `;
        listEl.insertAdjacentHTML('beforeend', html);
    });

    // Hitung potongan diskon voucher jika ada yang aktif di checkout
    let diskonVoucher = 0;
    const bannerVoucher = document.getElementById('co-active-voucher-banner');
    const badgeVoucher = document.getElementById('co-voucher-badge');
    const inputVoucher = document.getElementById('co-voucher-code');

    // Auto-fill voucher dari link jika ada pending URL voucher
    if (!window.appliedCheckoutVoucher && window.pendingUrlVoucher && inputVoucher && !inputVoucher.value) {
        inputVoucher.value = window.pendingUrlVoucher;
    }

    if (window.appliedCheckoutVoucher && grandTotal > 0) {
        const v = window.appliedCheckoutVoucher;
        const minOrder = Number(v.minPembelian || 0);
        if (grandTotal >= minOrder) {
            if (v.tipe === 'persen') {
                diskonVoucher = Math.round(grandTotal * Number(v.nilai || 0) / 100);
            } else {
                diskonVoucher = Number(v.nilai || 0);
            }
            diskonVoucher = Math.min(grandTotal, diskonVoucher);

            if (bannerVoucher) {
                const nilaiStr = v.tipe === 'persen' ? `${v.nilai}%` : `Rp ${Number(v.nilai || 0).toLocaleString('id-ID')}`;
                bannerVoucher.className = "p-2.5 bg-emerald-50 border border-emerald-300 rounded-xl flex items-center justify-between text-xs animate-scale-up";
                bannerVoucher.innerHTML = `
                    <div class="flex items-center gap-2">
                        <span class="w-7 h-7 shrink-0 rounded-lg bg-emerald-500 text-white flex items-center justify-center text-xs font-black shadow-2xs">
                            <i class="fa-solid fa-ticket"></i>
                        </span>
                        <div>
                            <span class="font-mono font-black text-emerald-950">${v.kode}</span>
                            <span class="text-[10px] text-emerald-700 block font-bold">Hemat: -Rp ${diskonVoucher.toLocaleString('id-ID')} (${nilaiStr})</span>
                        </div>
                    </div>
                    <button type="button" onclick="window.hapusVoucherCheckout()" title="Batalkan Voucher" class="w-6 h-6 shrink-0 rounded-full bg-emerald-100 hover:bg-rose-100 text-emerald-800 hover:text-rose-600 font-black flex items-center justify-center transition active:scale-90">
                        <i class="fa-solid fa-xmark text-xs"></i>
                    </button>
                `;
                bannerVoucher.classList.remove('hidden');
            }
            if (badgeVoucher) badgeVoucher.classList.remove('hidden');
        } else {
            if (bannerVoucher) {
                bannerVoucher.className = "p-2 bg-amber-50 border border-amber-200 rounded-xl text-[10px] font-bold text-amber-800";
                bannerVoucher.innerText = `⚠️ Min. belanja untuk voucher "${v.kode}" adalah Rp ${minOrder.toLocaleString('id-ID')}`;
                bannerVoucher.classList.remove('hidden');
            }
            if (badgeVoucher) badgeVoucher.classList.add('hidden');
        }
    } else {
        if (bannerVoucher) {
            bannerVoucher.classList.add('hidden');
            bannerVoucher.innerHTML = '';
        }
        if (badgeVoucher) badgeVoucher.classList.add('hidden');
    }

    const finalGrandTotal = Math.max(0, grandTotal - diskonVoucher);
    const coDiscRow = document.getElementById('checkout-discount-row');
    const coDiscLbl = document.getElementById('checkout-discount-label');
    const coDiscVal = document.getElementById('checkout-discount-val');
    if (coDiscRow) {
        if (diskonVoucher > 0 && window.appliedCheckoutVoucher) {
            const vKode = window.appliedCheckoutVoucher.kode || window.appliedCheckoutVoucher.code || 'Promo';
            if (coDiscLbl) coDiscLbl.innerHTML = `<i class="fa-solid fa-tag"></i> Diskon (${vKode})`;
            if (coDiscVal) coDiscVal.innerText = `-Rp ${diskonVoucher.toLocaleString('id-ID')}`;
            coDiscRow.classList.remove('hidden');
        } else {
            coDiscRow.classList.add('hidden');
        }
    }

    const totalEl = document.getElementById('checkout-total');
    if (totalEl) {
        if (diskonVoucher > 0) {
            totalEl.innerHTML = `<span class="line-through text-slate-400 text-xs font-bold mr-1.5">Rp ${grandTotal.toLocaleString('id-ID')}</span><span class="text-emerald-600 font-black">Rp ${finalGrandTotal.toLocaleString('id-ID')}</span>`;
        } else {
            totalEl.innerText = 'Rp ' + grandTotal.toLocaleString('id-ID');
        }
    }

    const modal = document.getElementById('checkout-modal');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }

    // Periksa status member aktif di nomor WA checkout jika sudah terisi
    const coPhoneVal = document.getElementById('co-phone')?.value;
    if (typeof window.cekMemberCheckout === 'function' && coPhoneVal) {
        window.cekMemberCheckout(coPhoneVal);
    }
};

// ==========================================
// KLAIM & BATAL VOUCHER CHECKOUT PELANGGAN
// ==========================================
window.appliedCheckoutVoucher = null;
window.pendingUrlVoucher = null;

window.klaimVoucherCheckout = (presetCode = null) => {
    const inputEl = document.getElementById('co-voucher-code');
    const kode = String(presetCode || (inputEl ? inputEl.value : '')).trim().toUpperCase();

    if (!kode) {
        alert("Ketik kode promo atau voucher terlebih dahulu!");
        return;
    }

    const allVouchers = window.cachedVouchers || globalVouchers || {};
    let matched = Object.values(allVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === kode);

    if (!matched && window.currentMemberData && window.currentMemberData.vouchers) {
        matched = Object.values(window.currentMemberData.vouchers).find(v => String(v.kode || v.code || '').toUpperCase() === kode);
    }

    if (!matched) {
        alert(`Kupon atau voucher "${kode}" tidak valid atau tidak ditemukan.`);
        return;
    }

    if (matched.status === 'nonaktif') {
        alert(`Voucher "${kode}" saat ini sedang dinonaktifkan.`);
        return;
    }

    if (matched.berlakuHingga) {
        const exp = new Date(matched.berlakuHingga);
        if (!isNaN(exp.getTime()) && exp.setHours(23,59,59,999) < Date.now()) {
            alert(`Voucher "${kode}" sudah melewati batas masa berlaku (kedaluwarsa).`);
            return;
        }
    }

    const subtotal = cart.reduce((sum, item) => sum + (Number(item.total) || 0), 0);
    const minOrder = Number(matched.minPembelian) || 0;
    if (subtotal < minOrder) {
        alert(`Minimal pembelian untuk menggunakan voucher ini adalah Rp ${minOrder.toLocaleString('id-ID')} (Total belanja saat ini: Rp ${subtotal.toLocaleString('id-ID')}).`);
        return;
    }

    // VALIDASI TARGET AUDIENS (publik, member, perorangan)
    const rawPhone = document.getElementById('co-phone')?.value || '';
    const cleanPhone = rawPhone.replace(/\D/g, '');
    let standardPhone = cleanPhone;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);

    const isMemberCheck = document.getElementById('co-member')?.checked;
    const isRegisteredMember = Boolean((window.cachedMembers && (window.cachedMembers[standardPhone] || window.cachedMembers[cleanPhone])));

    if (matched.targetAudience === 'member') {
        if (!isMemberCheck && !isRegisteredMember) {
            alert(`⭐ Voucher "${kode}" KHUSUS MEMBER RESMI!\n\nSilakan centang 'Daftar Member' di formulir pemesanan atau masukkan nomor WhatsApp yang telah terdaftar sebagai member.`);
            document.getElementById('co-member')?.focus();
            return;
        }
    } else if (matched.targetAudience === 'perorangan' || matched.targetAudience === 'khusus') {
        const isFromDirectLinkOrQR = matched.appliedVia === 'qr' || matched.appliedVia === 'link' || (window.pendingUrlVoucher === kode);
        
        let isPhoneMatched = false;
        if (matched.waList) {
            const listWa = matched.waList.split(',').map(n => n.replace(/\D/g, '')).filter(Boolean);
            isPhoneMatched = listWa.some(n => {
                let std = n;
                if (std.startsWith('62')) std = '0' + std.slice(2);
                return (std === standardPhone || n === cleanPhone || (standardPhone && n.endsWith(standardPhone.slice(-8))));
            });
        }

        if (!isPhoneMatched && !isFromDirectLinkOrQR) {
            alert(`👤 Voucher "${kode}" adalah Kupon Personal Perorangan.\n\nVoucher ini hanya berlaku untuk nomor WhatsApp penerima khusus (${matched.waList || 'Nomor Tertentu'}) atau harus dibuka melalui tautan/QR code voucher.`);
            return;
        }
    }

    window.appliedCheckoutVoucher = matched;
    if (inputEl) inputEl.value = '';
    window.bukaModalCheckout();
    alert(`🎉 Voucher "${kode}" Berhasil Digunakan!\nPotongan diskon otomatis diterapkan pada total pesanan.`);
};

window.hapusVoucherCheckout = () => {
    const prevRewardId = window.appliedCheckoutVoucher && window.appliedCheckoutVoucher.fromLoyaltyRewardId;
    if (prevRewardId && Array.isArray(cart)) {
        const idx = cart.findIndex(i => i.isLoyaltyReward && i.rewardId === prevRewardId);
        if (idx >= 0) {
            cart.splice(idx, 1);
            if (typeof window.updateCartBadge === 'function') window.updateCartBadge();
        }
    }
    window.appliedCheckoutVoucher = null;
    window.bukaModalCheckout();
};

window.handleAutoApplyVoucherUrl = (voucherCode) => {
    if (!voucherCode) return;
    const cleanCode = voucherCode.toUpperCase().trim();
    window.pendingUrlVoucher = cleanCode;

    const tryApply = async () => {
        let allVouchers = window.cachedVouchers || globalVouchers || {};
        let matched = Object.values(allVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === cleanCode);
        
        // Coba periksa langsung ke Firebase jika belum termuat di cache lokal
        if (!matched && typeof get === 'function' && typeof ref === 'function' && db) {
            try {
                const snap = await get(ref(db, 'vouchers'));
                if (snap.exists()) {
                    window.cachedVouchers = snap.val() || {};
                    globalVouchers = window.cachedVouchers;
                    allVouchers = window.cachedVouchers;
                    matched = Object.values(allVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === cleanCode);
                }
            } catch (e) {}
        }

        if (matched) {
            if (matched.status === 'nonaktif') return;
            matched.appliedVia = 'link';
            window.appliedCheckoutVoucher = matched;
            
            const diskonTeks = matched.tipe === 'persen' 
                ? `${matched.nilai}%` 
                : `Rp ${Number(matched.nilai || 0).toLocaleString('id-ID')}`;

            // Tampilkan floating toast banner pemberitahuan auto-apply
            const toast = document.createElement('div');
            toast.className = "fixed bottom-5 left-1/2 -translate-x-1/2 z-[9999] bg-slate-900 text-white px-4 py-3 rounded-2xl shadow-2xl border border-indigo-500/60 flex items-center gap-3 animate-bounce max-w-sm w-[90%]";
            toast.innerHTML = `
                <div class="w-8 h-8 rounded-xl bg-indigo-500 text-white flex items-center justify-center text-sm font-black shrink-0">
                    <i class="fa-solid fa-ticket"></i>
                </div>
                <div class="flex-1 min-w-0">
                    <p class="text-xs font-black text-amber-300">Voucher "${cleanCode}" Terpasang!</p>
                    <p class="text-[10px] text-slate-300">Potongan diskon ${diskonTeks} otomatis berlaku saat checkout.</p>
                </div>
                <button onclick="this.parentElement.remove()" class="text-slate-400 hover:text-white text-xs font-bold p-1">✕</button>
            `;
            document.body.appendChild(toast);
            setTimeout(() => toast?.remove(), 6000);
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => setTimeout(tryApply, 800));
    } else {
        setTimeout(tryApply, 800);
    }
};

// ==========================================
// 2. MESIN PENGHITUNG PLUS MINUS
// ==========================================
window.ubahQtyKeranjang = (index, perubahan) => {
    const item = cart[index];
    if (!item) return;

    if (item.isLoyaltyReward) {
        // Item klaim hadiah tidak bisa diubah qty-nya, hanya bisa dihapus
        return;
    }

    item.qty += perubahan;

    if (item.qty <= 0) {
        if (typeof window.hapusItemKeranjang === 'function') {
            window.hapusItemKeranjang(index);
        }
    } else {
        item.total = Number(item.price) * Number(item.qty);
        window.bukaModalCheckout();
        if (typeof window.updateCartBadge === 'function') {
            window.updateCartBadge(perubahan > 0);
        }
    }
};

// ==========================================
// 3. FUNGSI TUTUP MODAL (BAWAAN ASLI)
// ==========================================
window.closeModalCheckout = () => {
    const modal = document.getElementById('checkout-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.prosesCheckout = async () => {
    // BLOKIR TOTAL PEMESANAN MANDIRI SAAT OFFLINE
    if (!navigator.onLine || window.isAppOnline === false) {
        alert("Mode Offline: Pemesanan mandiri tidak tersedia saat jaringan offline. Silakan lakukan pemesanan langsung di meja Kasir POS.");
        return;
    }

    if (cart.length === 0) {
        return alert('Keranjang masih kosong!');
    }

    // --- GEMBOK WAJIB ISI NAMA ---
    const elemenNama = document.getElementById('co-name');
    if (elemenNama && elemenNama.value.trim() === '') {
        alert('Tunggu dulu! Nama Pelanggan wajib diisi.');
        elemenNama.focus(); // Arahkan kursor otomatis ke kolom nama
        return; // Hentikan proses checkout agar tidak lolos
    }
    // -----------------------------

    const inputName = elemenNama.value;
    const inputPhone = document.getElementById('co-phone') ? document.getElementById('co-phone').value : '';
    const paymentRadio = document.querySelector('input[name="co_payment"]:checked');
    const isMemberJoin = document.getElementById('co-member') ? document.getElementById('co-member').checked : false;
    const cleanPhone = String(inputPhone || '').replace(/\D/g, '');

    // MANDATORY WA BROADCAST GATE CHECK jika daftar member baru di checkout
    if (isMemberJoin) {
        if (!cleanPhone || cleanPhone.length < 9) {
            alert('Nomor WhatsApp wajib diisi minimal 9 digit untuk pendaftaran Member!');
            document.getElementById('co-phone')?.focus();
            return;
        }
        const waConfirmCheck = document.getElementById('co-member-wa-confirm');
        if (!waConfirmCheck || !waConfirmCheck.checked) {
            alert('Langkah Wajib: Untuk mengaktifkan Member, silakan gabung ke Grup WhatsApp Broadcast Resmi Mainstay dan centang konfirmasi!');
            return;
        }
    }
    
    const customerName = inputName ? inputName.trim() : 'Hamba Allah';
    const customerPhone = cleanPhone || '-';
    const paymentMethod = paymentRadio ? window.formatMetodeBayar(paymentRadio.value) : 'Tunai';
    const isPreOrder = (paymentMethod === 'PreOrder' || (paymentRadio && paymentRadio.value === 'PreOrder'));
    let preDate = '';
    let preTime = '';
    let preSubPay = 'Tunai';

    if (isPreOrder) {
        if (!inputName || inputName.trim().length < 2 || inputName.trim().toLowerCase() === 'hamba allah') {
            alert("Pesanan Pre-Order WAJIB menyertakan Nama Pemesan yang jelas!");
            const nameEl = document.getElementById('co-name') || document.getElementById('customer-name-input');
            if (nameEl) nameEl.focus();
            return;
        }
        if (!cleanPhone || cleanPhone.replace(/\D/g, '').length < 8) {
            alert("Pesanan Pre-Order WAJIB menyertakan Nomor WhatsApp aktif pemesan!");
            const phoneEl = document.getElementById('co-phone') || document.getElementById('customer-phone-input');
            if (phoneEl) phoneEl.focus();
            return;
        }

        const dateEl = document.getElementById('co-preorder-date');
        const timeEl = document.getElementById('co-preorder-time');
        const subPayEl = document.querySelector('input[name="co_preorder_subpay"]:checked');

        preDate = dateEl ? dateEl.value : '';
        preTime = timeEl ? timeEl.value : '';
        preSubPay = window.formatMetodeBayar(subPayEl ? subPayEl.value : 'Tunai');

        if (!preDate) {
            alert("Harap tentukan tanggal pengambilan pesanan Pre-Order!");
            if (dateEl) dateEl.focus();
            return;
        }

        const todayObj = new Date();
        const todayStr = `${todayObj.getFullYear()}-${String(todayObj.getMonth() + 1).padStart(2, '0')}-${String(todayObj.getDate()).padStart(2, '0')}`;
        const maxLimit = new Date();
        maxLimit.setDate(maxLimit.getDate() + 7);
        const maxLimitStr = `${maxLimit.getFullYear()}-${String(maxLimit.getMonth() + 1).padStart(2, '0')}-${String(maxLimit.getDate()).padStart(2, '0')}`;

        if (preDate < todayStr) {
            alert("Tanggal pengambilan pre-order tidak boleh di masa lampau!");
            if (dateEl) dateEl.focus();
            return;
        }
        if (preDate > maxLimitStr) {
            alert("Tanggal pengambilan pre-order maksimal 1 minggu dari hari ini!");
            if (dateEl) dateEl.focus();
            return;
        }

        if (!preTime) {
            alert("Harap tentukan jam pengambilan pesanan Pre-Order!");
            if (timeEl) timeEl.focus();
            return;
        }
    }

    const grandTotal = cart.reduce((sum, item) => sum + item.total, 0);

    // Hitung potongan voucher jika ada voucher aktif
    let finalPayTotal = grandTotal;
    let diskonNominal = 0;
    if (window.appliedCheckoutVoucher && grandTotal > 0) {
        const v = window.appliedCheckoutVoucher;
        if (grandTotal >= (Number(v.minPembelian) || 0)) {
            if (v.tipe === 'persen') {
                diskonNominal = Math.round(grandTotal * (Number(v.nilai) || 0) / 100);
            } else {
                diskonNominal = Number(v.nilai) || 0;
            }
            diskonNominal = Math.min(grandTotal, diskonNominal);
            finalPayTotal = Math.max(0, grandTotal - diskonNominal);
        }
    }

    // Generate Order ID dengan format: CSH-DDMM-SEQ
    const orderId = typeof window.generateDailyOrderId === 'function' ? window.generateDailyOrderId('CSH') : `CSH-${String(new Date().getDate()).padStart(2, '0')}${String(new Date().getMonth() + 1).padStart(2, '0')}001`;

    const now = new Date();
    const nowTimeStr = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }).replace(/:/g, '.');
    const nowDateStr = now.toLocaleDateString('id-ID');

    // Siapkan Data Transaksi (Payload)
    const payload = {
        id: orderId,
        orderId: orderId,
        customerName: customerName,
        namaPelanggan: customerName,
        customerPhone: customerPhone,
        nomorWa: customerPhone,
        items: cart.map(it => ({ ...it })),
        total: finalPayTotal,
        totalAmount: finalPayTotal,
        subtotal: grandTotal,
        diskonVoucher: diskonNominal,
        voucher: window.appliedCheckoutVoucher ? (window.appliedCheckoutVoucher.kode || window.appliedCheckoutVoucher.code) : null,
        paymentMethod: paymentMethod,
        metode: isPreOrder ? `PreOrder (${preSubPay})` : paymentMethod,
        status: isPreOrder ? 'preorder' : 'pending',
        isPreOrder: isPreOrder,
        pickupDate: preDate,
        pickupTime: preTime,
        preOrderSubPay: preSubPay,
        isPaid: isPreOrder ? false : true,
        paymentStatus: isPreOrder ? 'menunggu_konfirmasi' : 'lunas',
        preOrderPaymentConfirmed: isPreOrder ? false : true,
        timestamp: Date.now(),
        waktu: nowTimeStr,
        tanggal: nowDateStr,
        isNewMember: isMemberJoin,
        nomorMeja: (typeof window.isQrMejaFeatureEnabled === 'function' && window.isQrMejaFeatureEnabled())
            ? (String(window.activeCustomerTable || '').trim() || null)
            : null,
        table: (typeof window.isQrMejaFeatureEnabled === 'function' && window.isQrMejaFeatureEnabled())
            ? (String(window.activeCustomerTable || '').trim() || null)
            : null,
        tipePesanan: isPreOrder ? 'preorder' : 'csh',
        channel: isPreOrder ? 'preorder' : 'csh',
        kasir: localStorage.getItem('mainstay_staff_name') || 'Self Order'
    };

    // Sinkronkan instan ke memori lokal kasir
    if (typeof globalOrders !== 'undefined') {
        globalOrders[orderId] = payload;
        window._latestOrdersSnapshot = globalOrders;
    }
    if (typeof window.globalOrders === 'object') {
        window.globalOrders[orderId] = payload;
    }
    try {
        let savedOrders = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (!Array.isArray(savedOrders)) savedOrders = [];
        savedOrders = savedOrders.filter(o => (o.orderId || o.id) !== orderId);
        savedOrders.unshift(payload);
        localStorage.setItem('mainstay_offline_orders', JSON.stringify(savedOrders));
    } catch(e) {}
    if (typeof window.renderKasirOrders === 'function') {
        window.renderKasirOrders();
    }

    // Tampilkan Indikator Loading pada Tombol
    const btnCheckout = document.querySelector('#checkout-modal button[onclick="prosesCheckout()"]');
    const originalBtnText = btnCheckout ? btnCheckout.innerHTML : '';
    if (btnCheckout) {
        btnCheckout.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i> MEMPROSES...';
        btnCheckout.disabled = true;
    }

    let isOfflineOrder = !navigator.onLine;
    let memberPayload = null;
    let nonMemberPayload = null;
    const standardPhone = cleanPhone.startsWith('62') ? ('0' + cleanPhone.slice(2)) : cleanPhone;

    try {
        // CUSTOMER SEGMENTATION & PURE POINTS ENGINE (/members vs /non_members)
        const existingMember = standardPhone ? ((window.cachedMembers && (window.cachedMembers[standardPhone] || window.cachedMembers[cleanPhone])) || null) : null;
        const isMember = Boolean(existingMember || isMemberJoin);

        if (isMember && standardPhone) {
            const claimedPoints = cart.filter(i => i.isLoyaltyReward).reduce((sum, item) => sum + (Number(item.costPoints) || (Number(item.costSessions || 1) * 10)), 0);
            const prevPoints = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(existingMember) : 0;
            const remainingPoints = Math.max(0, prevPoints - claimedPoints);
            const earnedPoints = 5; // Dapatkan 5 Points setiap order
            const newPoints = remainingPoints + earnedPoints;

            memberPayload = {
                phone: standardPhone,
                name: customerName,
                points: newPoints,
                poin: newPoints,
                totalOrders: Number(existingMember?.totalOrders || 0) + 1,
                totalSpent: Number(existingMember?.totalSpent || 0) + finalPayTotal,
                lastActive: Date.now(),
                registeredAt: existingMember?.registeredAt || Date.now(),
                waGroupJoined: true,
                accStatus: existingMember ? (existingMember.accStatus || 'approved') : 'pending_acc',
                accDeadlineHours: existingMember ? (existingMember.accDeadlineHours || 24) : 24,
                accRequestedAt: existingMember ? (existingMember.accRequestedAt || Date.now()) : Date.now(),
                hasJoinScreenshot: Boolean(document.getElementById('co-member-wa-confirm')?.checked || existingMember?.hasJoinScreenshot),
                vouchers: existingMember?.vouchers || {}
            };

            if (window.cachedMembers) {
                window.cachedMembers[standardPhone] = memberPayload;
            }
        } else if (!isMember && standardPhone.length >= 8 && customerName && customerName.toLowerCase() !== 'hamba allah') {
            // Pelanggan mencantumkan Nama + No. WA namun TIDAK daftar member -> otomatis catat ke Non-Member
            const prevNonMember = (window.cachedNonMembers && (window.cachedNonMembers[standardPhone] || window.cachedNonMembers[cleanPhone])) || {};
            nonMemberPayload = {
                id: standardPhone,
                phone: standardPhone,
                name: customerName,
                totalOrders: Number(prevNonMember.totalOrders || 0) + 1,
                totalSpent: Number(prevNonMember.totalSpent || 0) + finalPayTotal,
                firstSeen: prevNonMember.firstSeen || Date.now(),
                lastOrderDate: Date.now(),
                lastActive: Date.now(),
                lastChannel: isPreOrder ? 'PreOrder' : 'Self-Order',
                isMember: false,
                vouchers: prevNonMember.vouchers || {}
            };
            if (!window.cachedNonMembers) window.cachedNonMembers = {};
            window.cachedNonMembers[standardPhone] = nonMemberPayload;
            globalNonMembers = window.cachedNonMembers;
        }

        if (navigator.onLine) {
            try {
                await push(ref(db, 'orders'), payload);
                if (memberPayload && standardPhone) {
                    await update(ref(db, `members/${standardPhone}`), memberPayload);
                    if (window.cachedNonMembers && (window.cachedNonMembers[standardPhone] || window.cachedNonMembers[cleanPhone])) {
                        await remove(ref(db, `non_members/${standardPhone}`)).catch(() => {});
                        delete window.cachedNonMembers[standardPhone];
                    }
                } else if (nonMemberPayload && standardPhone) {
                    await update(ref(db, `non_members/${standardPhone}`), nonMemberPayload);
                }
            } catch (netErr) {
                console.warn("Gagal kirim ke server realtime, alihkan ke antrean offline:", netErr);
                isOfflineOrder = true;
            }
        }

        if (isOfflineOrder) {
            payload.isOffline = true;
            payload.synced = false;
            window.posSyncEngine.enqueue('order', payload, {
                memberPhone: memberPayload ? standardPhone : '',
                memberPayload,
                nonMemberPhone: nonMemberPayload ? standardPhone : '',
                nonMemberPayload
            });
        }
        
        // Panggil popup pesanan berhasil (dengan status offline jika tanpa internet)
        window.tampilkanPopupBerhasil(orderId, paymentMethod, finalPayTotal, customerName);
        
        // Reset Keranjang, Form & Voucher
        cart = [];
        window.appliedCheckoutVoucher = null;
        if(document.getElementById('co-name')) document.getElementById('co-name').value = '';
        if(document.getElementById('co-phone')) document.getElementById('co-phone').value = '';
        if(document.getElementById('co-voucher-code')) document.getElementById('co-voucher-code').value = '';
        if(document.getElementById('co-member')) document.getElementById('co-member').checked = false;
        if(document.getElementById('co-member-wa-confirm')) document.getElementById('co-member-wa-confirm').checked = false;
        if (document.getElementById('co-wa-proof-status')) document.getElementById('co-wa-proof-status').classList.add('hidden');
        
        const bannerVoucher = document.getElementById('co-active-voucher-banner');
        if (bannerVoucher) { bannerVoucher.innerHTML = ''; bannerVoucher.classList.add('hidden'); }
        const badgeVoucher = document.getElementById('co-voucher-badge');
        if (badgeVoucher) badgeVoucher.classList.add('hidden');

        const statusBox = document.getElementById('co-member-status-box');
        if (statusBox) { statusBox.innerHTML = ''; statusBox.classList.add('hidden'); }
        const waGateBox = document.getElementById('co-wa-gate-box');
        if (waGateBox) waGateBox.classList.add('hidden');
        const joinContainer = document.getElementById('co-member-join-container');
        if (joinContainer) joinContainer.classList.remove('hidden');
        
        window.updateCartBadge();
        window.closeModalCheckout();
        
    } catch (error) {
        console.error("Checkout Handler Note:", error);
        // Tetap pastikan pesanan tersimpan secara lokal
        payload.isOffline = true;
        payload.synced = false;
        window.posSyncEngine.enqueue('order', payload);
        window.tampilkanPopupBerhasil(orderId, paymentMethod, finalPayTotal, customerName);
        cart = [];
        window.updateCartBadge();
        window.closeModalCheckout();
    } finally {
        // Kembalikan tombol ke keadaan semula
        btnCheckout.innerHTML = originalBtnText;
        btnCheckout.disabled = false;
    }
};
// ============================================================================
// MAINSTAY DRINK POS - TAHAP 3: SYSTEM ROUTING & STRICT LOGIN GATE
// ============================================================================

window.switchRoleView = (role) => {

    // --- SISTEM ANTI REFRESH (SESSION MEMORY) & VISIBILITAS KONTROL MELAYANG ---
    const fab = document.getElementById('fab-kasir-container');
    const btnBgm = document.getElementById('btn-bgm');

    if (role === 'customer') {
        document.documentElement.classList.remove('app-role-kasir', 'app-pos-open', 'app-role-owner');
        // HANYA hapus sesi jika pengguna secara eksplisit meminta keluar (misal saat logout)
        if (window._isExplicitRoleSwitch) {
            localStorage.removeItem('mainstay_session_role');
            localStorage.removeItem('mainstay_session_staff');
            localStorage.removeItem('mainstay_staff_name');
            localStorage.removeItem('mainstay_is_kasir_open');
            localStorage.removeItem('mainstay_active_panel');
            window._isExplicitRoleSwitch = false;
        }
        if (fab) {
            fab.classList.add('hidden');
            fab.classList.remove('flex');
        }
        if (btnBgm) {
            btnBgm.classList.remove('hidden');
        }
    } else if (role === 'kasir') {
        document.documentElement.classList.remove('app-role-owner');
        document.documentElement.classList.add('app-role-kasir');
        localStorage.setItem('mainstay_session_role', 'kasir');
        
        // Mute volume DILARANG muncul di kasir
        if (btnBgm) {
            btnBgm.classList.add('hidden');
            btnBgm.style.display = 'none';
        }
        // Tombol melayang kasir hanya muncul jika modal POS manual sedang tidak terbuka penuh
        const isPosOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';
        if (fab) {
            if (isPosOpen) {
                fab.classList.add('hidden');
                fab.classList.remove('flex');
            } else {
                fab.classList.remove('hidden');
                fab.classList.add('flex');
            }
        }
    } else if (role === 'owner') {
        document.documentElement.classList.remove('app-role-kasir', 'app-pos-open');
        document.documentElement.classList.add('app-role-owner');
        localStorage.setItem('mainstay_session_role', 'owner');
        
        // BLOKIR TOTAL: Tombol kasir & tombol mute volume TIDAK BOLEH muncul di Master Owner
        if (fab) {
            fab.classList.add('hidden');
            fab.classList.remove('flex');
        }
        if (btnBgm) {
            btnBgm.classList.add('hidden');
            btnBgm.style.display = 'none';
        }
    }
    // --------------------------------------------
    // --- PUSAT KENDALI: BGM & ALWAYS ON DISPLAY ---
    if (role === 'kasir') {
        if (typeof window.matikanBGM === 'function') window.matikanBGM();
        if (typeof window.requestWakeLock === 'function') window.requestWakeLock();
    } else if (role === 'owner') {
        if (typeof window.matikanBGM === 'function') window.matikanBGM();
        if (typeof window.releaseWakeLock === 'function') window.releaseWakeLock();
    } else {
        if (typeof window.nyalakanBGM === 'function') window.nyalakanBGM();
        if (typeof window.releaseWakeLock === 'function') window.releaseWakeLock();
    }
    // ----------------------------------------------

    // Sembunyikan semua section layar terlebih dahulu
    // ... (kode Mas Ihsan lanjut ke bawah seperti aslinya)
    document.getElementById('view-customer').classList.add('hidden');
    document.getElementById('view-kasir').classList.add('hidden');
    document.getElementById('view-owner').classList.add('hidden');
    
    // Set role yang aktif saat ini
    currentRole = role;
    
    // Tampilkan layar yang dituju
    const targetViewEl = document.getElementById(`view-${role}`);
    if (targetViewEl) {
        targetViewEl.classList.remove('hidden');
        if (role === 'kasir') {
            targetViewEl.classList.remove('view-kasir-anim-enter');
            void targetViewEl.offsetWidth;
            targetViewEl.classList.add('view-kasir-anim-enter');
        }
    }

    // Memicu render data spesifik jika perlu
        
        // 1. JIKA BALIK KE LAYAR PELANGGAN (LOGOUT)
        if (role === 'customer') {
            // Memaksa render ulang katalog agar tidak muter-muter
            if (typeof window.renderKatalog === 'function') {
                window.renderKatalog();
            } else if (typeof window.renderMenuCustomer === 'function') {
                window.renderMenuCustomer();
            }
            
        }

        // 2. JIKA MASUK KE LAYAR KASIR (LOGIN)
        if (role === 'kasir') {
            if (typeof window.updateKasirActiveProfileUI === 'function') {
                window.updateKasirActiveProfileUI(window.activeStaff?.name || localStorage.getItem('mainstay_staff_name'));
            }
            if (typeof window.renderKasirOrders === 'function') {
                window.renderKasirOrders();
            }
            if (typeof window.updateLiveCashDrawer === 'function') {
                window.updateLiveCashDrawer();
            }
            
            // --- PANCINGAN SUPER TOGGLE (ANTI-GAGAL) ---
            let hitunganPancingan = 0;
            const paksaSinkron = setInterval(() => {
                if (typeof window.updateVisualToggle === 'function' && typeof isStoreOpen !== 'undefined') {
                    window.updateVisualToggle(isStoreOpen);
                }
                hitunganPancingan++;
                if (hitunganPancingan >= 4) {
                    clearInterval(paksaSinkron);
                }
            }, 250); 
            // ------------------------------------
        }
    
    if (role === 'owner') {
        if (typeof window.updateOwnerDashboard === 'function') {
            window.updateOwnerDashboard();
        }
    }
};

window.bukaModalLogin = () => {
    window.currentPinInput = "";
    window._pendingPinAuth = null;
    window._isValidatingPin = false;
    if (typeof window.updateIndikatorPin === 'function') {
        window.updateIndikatorPin();
    }
    const modal = document.getElementById('modal-login');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }
    
    // Reset nilai input dan sinkronkan status keamanan cooldown
    const pinInput = document.getElementById('login-pin');
    if (pinInput) pinInput.value = '';
    
    const errorEl = document.getElementById('login-error');
    if (errorEl) errorEl.classList.add('hidden');
    if (typeof window.syncPinModalLockoutUI === 'function') {
        window.syncPinModalLockoutUI();
    }
};

window.closeModalLogin = () => {
    if (_pinCooldownInterval) {
        clearInterval(_pinCooldownInterval);
        _pinCooldownInterval = null;
    }
    const modal = document.getElementById('modal-login');
    if (modal) {
        modal.classList.remove('flex');
        modal.classList.add('hidden');
    }
};

window.prosesLogin = async () => {
    if (typeof window.getRemainingPinCooldownSec === 'function' && window.getRemainingPinCooldownSec() > 0) {
        window.syncPinModalLockoutUI();
        return;
    }

    const pinInput = document.getElementById('login-pin');
    const pin = pinInput ? pinInput.value : '';
    const errorEl = document.getElementById('login-error');
    const btnLogin = document.querySelector('#modal-login button[onclick="prosesLogin()"]');
    
    if (errorEl) errorEl.classList.add('hidden'); 
    
    // Tampilkan Indikator Loading di tombol
    const originalBtnText = btnLogin ? btnLogin.innerHTML : 'Masuk Sistem';
    if (btnLogin) {
        btnLogin.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i> Memvalidasi...';
        btnLogin.disabled = true;
    }
    
    try {
        // 1. Cek Master PIN Owner (Bypass Database / Hardcoded 888888 atau Database Master Owner)
        let isOwnerLogin = (pin === MASTER_PIN || pin === "888888");
        let ownerSessionName = "Owner";
        if (!isOwnerLogin && typeof globalMasterOwner !== 'undefined' && globalMasterOwner) {
            for (const k in globalMasterOwner) {
                if (String(globalMasterOwner[k]?.pin) === String(pin)) {
                    isOwnerLogin = true;
                    ownerSessionName = String(globalMasterOwner[k]?.name || "Owner").replace(/\s*\(\s*master\s*\)/i, '').trim() || "Owner";
                    break;
                }
            }
        }
        if (isOwnerLogin) {
            if (typeof window.resetPinLockoutState === 'function') window.resetPinLockoutState();
            localStorage.setItem('mainstay_session_role', 'owner');
            localStorage.setItem('mainstay_staff_name', ownerSessionName);
            window.closeModalLogin();
            window.switchRoleView('owner');
            if (typeof window.tampilkanPopupLoginOwner === 'function') {
                window.tampilkanPopupLoginOwner(ownerSessionName);
            }
            return;
        }

        // 2. Fetch PIN Darurat (Emergency PIN) secara Real-Time dari Firebase
        const settingsSnap = await get(ref(db, 'store_settings'));
        if (settingsSnap.exists()) {
            const settingsData = settingsSnap.val();
            if (settingsData.emergency_pin && settingsData.emergency_pin === pin) {
                if (typeof window.resetPinLockoutState === 'function') window.resetPinLockoutState();
                localStorage.setItem('mainstay_session_role', 'owner');
                localStorage.setItem('mainstay_staff_name', 'Owner');
                window.closeModalLogin();
                window.switchRoleView('owner');
                if (typeof window.tampilkanPopupLoginOwner === 'function') {
                    window.tampilkanPopupLoginOwner('Owner');
                }
                return;
            }
        }

        // 3. Cek PIN Staff (Kasir) langsung dari database staff cabang aktif + IndexedDB
        if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.getBranchStaff === 'function') {
            await window.mainstayIndexedDB.getBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat').catch(() => {});
        }
        if (!window._staffLoaded) {
            try {
                const staffSnap = await get(ref(db, 'staff'));
                globalStaff = staffSnap.exists() ? (staffSnap.val() || {}) : {};
                window.globalStaff = globalStaff;
                window._staffLoaded = true;
                if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.syncBranchStaff === 'function') {
                    window.mainstayIndexedDB.syncBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat', globalStaff).catch(() => {});
                }
            } catch (e) {}
        }
        const effectiveStaffMap = typeof window.getEffectiveBranchStaffMap === 'function' ? window.getEffectiveBranchStaffMap() : (globalStaff || {});
        let authenticatedStaff = null;
        Object.keys(effectiveStaffMap).forEach(key => {
            if (effectiveStaffMap[key] && String(effectiveStaffMap[key].pin) === String(pin)) {
                authenticatedStaff = { id: key, ...effectiveStaffMap[key] };
            }
        });

        // 4. Eksekusi Hasil Login
        if (authenticatedStaff) {
            if (typeof window.resetPinLockoutState === 'function') window.resetPinLockoutState();
            activeStaff = authenticatedStaff;
            
            // Simpan Sesi Persistent Kasir
            window.safeSetItem('mainstay_session_role', 'kasir');
            window.safeSetItem('mainstay_staff_name', activeStaff.name);
            const cleanS = { name: activeStaff.name, role: activeStaff.role || activeStaff.tipeKaryawan, pin: activeStaff.pin };
            window.safeSetItem('mainstay_session_staff', JSON.stringify(cleanS));
            
            // Update nama dan foto kasir di UI Header Kasir
            if (typeof window.updateKasirActiveProfileUI === 'function') {
                window.updateKasirActiveProfileUI(activeStaff.name);
            }
            
            window.closeModalLogin();
            window.switchRoleView('kasir');
        } else {
            // Jika PIN tidak cocok dengan siapapun (salah) -> Catat percobaan gagal & terapkan limit
            if (typeof window.recordFailedPinAttempt === 'function') {
                window.recordFailedPinAttempt('PIN tidak cocok dengan data Staff/Owner.');
            }
            if (errorEl) errorEl.classList.remove('hidden');
        }
    } catch (error) {
        console.error("Login Error:", error);
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi("Gagal memvalidasi ke database. Pastikan koneksi internet lancar.", "error");
        }
    } finally {
        // Kembalikan tombol ke keadaan semula jika gagal masuk
        if (btnLogin) {
            btnLogin.innerHTML = originalBtnText;
            btnLogin.disabled = false;
        }
    }
};

window.prosesLogout = (role) => {
    // Memanggil pop-up kustom yang elegan
    window.tampilkanPopupLogout();
};

