window.tanyaDanKirimWaPesanan = (orderKey) => {
    let order = (globalOrders && globalOrders[orderKey]) || null;
    if (!order && globalOrders) {
        order = Object.values(globalOrders).find(o => o && (o.orderId === orderKey || o.id === orderKey));
    }
    if (!order) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            order = cached.find(o => (o.orderId || o.id) === orderKey);
        } catch(e) {}
    }
    if (!order) return alert("Data pesanan tidak ditemukan.");

    let hpClean = '';
    const rawCustHp = order.customerPhone || order.noHp || order.phone || order.wa || '';
    if (rawCustHp && String(rawCustHp).trim().length >= 8) {
        hpClean = String(rawCustHp).replace(/[^0-9]/g, '');
        if (hpClean.startsWith('0')) hpClean = '62' + hpClean.substring(1);
    }
    if (!hpClean || hpClean.length < 8) {
        const rawOwner = (window.storeSettings && (window.storeSettings.wa_owner || window.storeSettings.social_wa)) || '628977099557';
        hpClean = String(rawOwner).replace(/[^0-9]/g, '');
        if (hpClean.startsWith('0')) hpClean = '62' + hpClean.substring(1);
        if (!hpClean) hpClean = '628977099557';
    }

    const custName = order.customerName || order.namaPelanggan || 'Pelanggan';
    const orderCode = String(order.orderId || order.id || orderKey).toUpperCase();
    const totalNominal = Number(order.totalAmount || order.total || 0);
    const payMethod = order.paymentMethod || order.metode || order.preOrderSubPay || 'QRIS';
    const isQris = /qris|transfer|bank|gopay|ovo|dana|shopee/i.test(payMethod);
    const storeTitle = (window.storeSettings && window.storeSettings.store_title) || 'Mainstay Drink';

    let rincianMenu = '';
    const items = Array.isArray(order.items) ? order.items : [];
    items.forEach(it => {
        rincianMenu += `▪️ ${it.qty || 1}x ${it.name || it.nama}\n`;
    });

    let sapaan = '';
    if (isQris) {
        sapaan = `Halo Kak *${custName}* 👋\n\nPesanan Kakak sudah masuk di kasir *${storeTitle}*:\n\n*Kode Pesanan:* ${orderCode}\n*Rincian:*\n${rincianMenu}\n*Total Tagihan:* *${formatRupiah(totalNominal)}*\n*Metode Pembayaran:* *QRIS*\n\n💳 *MOHON KIRIMKAN BUKTI BAYAR QRIS:*\nMohon untuk segera mengirimkan foto / screenshot bukti transfer / QRIS Kakak di sini ya Kak, agar pesanan segera kami verifikasi dan proses di dapur. Terima kasih banyak! 🙏`;
    } else {
        sapaan = `Halo Kak *${custName}* 👋\n\nPesanan Kakak sudah masuk di kasir *${storeTitle}*:\n\n*Kode Pesanan:* ${orderCode}\n*Rincian:*\n${rincianMenu}\n*Total Tagihan:* *${formatRupiah(totalNominal)}*\n*Metode Pembayaran:* *Tunai / Cash*\n\n💵 *KONFIRMASI PEMBAYARAN:*\nSilakan lakukan pembayaran tunai di kasir ya Kak agar pesanan dapat segera diproses di dapur. Terima kasih! 🙏`;
    }

    const waUrl = "https://wa.me/" + hpClean + "?text=" + encodeURIComponent(sapaan);
    window.open(waUrl, '_blank');
};

window.potongStokOtomatisDariOrder = async (targetOrder, safeKey, actualFirebaseKey) => {
    if (!targetOrder || targetOrder.stockDeducted) return null;
    if (!globalInventory || typeof globalInventory !== 'object') return null;

    // Tandai langsung agar tidak pernah double-deduct meski diklik cepat
    targetOrder.stockDeducted = true;
    const deductedAt = Date.now();
    targetOrder.stockDeductedAt = deductedAt;

    const invKeys = Object.keys(globalInventory || {});
    if (invKeys.length === 0) return {};

    const resolveInvKey = (rawKey, rawName) => {
        if (rawKey && globalInventory[rawKey]) return rawKey;
        const cleanName = String(rawName || '').toLowerCase().trim();
        if (!cleanName) return null;
        let match = invKeys.find(k => String(globalInventory[k]?.name || '').toLowerCase().trim() === cleanName);
        if (match) return match;
        match = invKeys.find(k => {
            const n = String(globalInventory[k]?.name || '').toLowerCase().trim();
            return n.length >= 3 && (n.includes(cleanName) || cleanName.includes(n));
        });
        return match || null;
    };

    const resolveMenuObj = (cartItem) => {
        const menus = (typeof globalMenus === 'object' && globalMenus) ? globalMenus : (window.globalMenus || {});
        const candidates = [
            cartItem?.rawMenuKey,
            cartItem?.menuKey,
            cartItem?.id,
            cartItem?.key && String(cartItem.key).includes('_') ? String(cartItem.key).split('_')[0] : cartItem?.key
        ].filter(Boolean);
        for (const cid of candidates) {
            if (menus[cid]) return menus[cid];
        }
        const cleanCartName = String(cartItem?.name || cartItem?.nama || '')
            .replace(/\s*\([^)]*\)/g, '')
            .toLowerCase()
            .trim();
        if (cleanCartName) {
            return Object.values(menus).find(m => m && String(m.name || m.nama || '').toLowerCase().trim() === cleanCartName) || null;
        }
        return null;
    };

    const deductions = {};
    const addDeduction = (invKey, qtyToDeduct) => {
        if (!invKey || !globalInventory[invKey]) return;
        const q = Number(qtyToDeduct) || 0;
        if (q <= 0) return;
        deductions[invKey] = Math.round(((deductions[invKey] || 0) + q) * 1000) / 1000;
    };

    const applyMenuRecipeOrFallback = (menuObj, itemNameStr, multQty) => {
        if (menuObj && menuObj.isPackage && Array.isArray(menuObj.packageItems) && menuObj.packageItems.length > 0 && (!Array.isArray(menuObj.resep) || menuObj.resep.length === 0)) {
            const menus = (typeof globalMenus === 'object' && globalMenus) ? globalMenus : (window.globalMenus || {});
            menuObj.packageItems.forEach(pkgItem => {
                const subMenu = menus[pkgItem.id] || Object.values(menus).find(m => m && String(m.name || m.nama || '').toLowerCase().trim() === String(pkgItem.name || '').toLowerCase().trim());
                applyMenuRecipeOrFallback(subMenu, pkgItem.name || '', multQty * (Number(pkgItem.qty) || 1));
            });
            return;
        }

        if (menuObj && Array.isArray(menuObj.resep) && menuObj.resep.length > 0) {
            menuObj.resep.forEach(ing => {
                const perUnitQty = Number(ing?.qty) || 0;
                if (perUnitQty <= 0) return;
                const invKey = resolveInvKey(ing.itemKey, ing.itemName);
                if (invKey) {
                    addDeduction(invKey, perUnitQty * multQty);
                }
            });
        } else {
            // Fallback untuk menu lama yang belum memiliki konfigurasi resep bahan baku
            const cupKey = invKeys.find(k => {
                const inv = globalInventory[k];
                const n = String(inv?.name || '').toLowerCase();
                const c = String(inv?.category || '').toLowerCase();
                return n.includes('cup') || n.includes('gelas') || c.includes('packaging');
            });
            if (cupKey) addDeduction(cupKey, multQty);

            const itemNamaLower = String(itemNameStr || '').toLowerCase();
            invKeys.forEach(k => {
                const invNameLower = String(globalInventory[k]?.name || '').toLowerCase();
                if (invNameLower.length >= 3 && itemNamaLower.includes(invNameLower)) {
                    addDeduction(k, multQty);
                }
            });
        }
    };

    const items = Array.isArray(targetOrder.items) ? targetOrder.items : [];
    items.forEach(cartItem => {
        const itemQty = Number(cartItem?.qty) || 1;
        const menuObj = resolveMenuObj(cartItem);
        const itemNameStr = cartItem?.name || cartItem?.nama || menuObj?.name || '';
        applyMenuRecipeOrFallback(menuObj, itemNameStr, itemQty);

        // Deduksi topping tambahan yang dipilih pelanggan
        const chosenToppings = Array.isArray(cartItem?.toppings) ? cartItem.toppings : [];
        chosenToppings.forEach(topName => {
            const topNameLower = String(topName || '').toLowerCase().trim();
            if (!topNameLower) return;
            const topKey = invKeys.find(k => {
                const n = String(globalInventory[k]?.name || '').toLowerCase().trim();
                return n.length >= 2 && (n.includes(topNameLower) || topNameLower.includes(n));
            });
            if (topKey) {
                addDeduction(topKey, itemQty);
            }
        });
    });

    targetOrder.stockDeductions = deductions;

    const orderCode = String(targetOrder.orderId || targetOrder.id || safeKey || '');
    const alertCriticalItems = [];
    const writePromises = [];

    for (const [invKey, amount] of Object.entries(deductions)) {
        const inv = globalInventory[invKey];
        if (!inv) continue;
        const currentQty = Number(inv.qty) || 0;
        const minQty = Number(inv.minQty !== undefined ? inv.minQty : 5);
        const newQty = Math.max(0, Math.round((currentQty - amount) * 1000) / 1000);
        const costPerUnit = Number(inv.costPrice || inv.avgCostPerUnit || inv.modalPerUnit || 0);
        const newTotalModal = Math.round(newQty * costPerUnit);

        inv.qty = newQty;
        if (costPerUnit > 0) {
            inv.totalStockModal = newTotalModal;
        }

        if (newQty <= minQty) {
            alertCriticalItems.push({
                key: invKey,
                name: inv.name || 'Bahan Baku',
                qty: newQty,
                min: minQty,
                unit: inv.unit || 'Pcs',
                category: inv.category || 'Bahan'
            });
        }

        const unitLabel = inv.unit || 'Pcs';
        const orderCustomer = targetOrder.customerName || targetOrder.namaPelanggan || 'Umum';
        const orderCashier = targetOrder.kasir || targetOrder.cashier || targetOrder.inputBy || 'Kasir';

        if (typeof window.catatRiwayatPergerakanStok === 'function') {
            writePromises.push(window.catatRiwayatPergerakanStok({
                itemKey: invKey,
                itemName: inv.name || 'Bahan Baku',
                type: 'sale',
                qtyDelta: -amount,
                beforeQty: currentQty,
                afterQty: newQty,
                unit: unitLabel,
                source: 'order_sale',
                reason: `Transaksi Order #${orderCode || safeKey} (${orderCustomer})`,
                orderId: orderCode || safeKey || '',
                staffName: orderCashier
            }).catch(() => {}));
        }

        if (typeof db !== 'undefined' && db) {
            const invUpdatePayload = {
                qty: newQty,
                lastDeduction: new Date().toISOString(),
                lastOrderId: orderCode
            };
            if (costPerUnit > 0) invUpdatePayload.totalStockModal = newTotalModal;
            writePromises.push(update(ref(db, `inventory_raw/${invKey}`), invUpdatePayload).catch(() => {}));
        }
    }

    try {
        localStorage.setItem('mainstay_cached_inventory', JSON.stringify(globalInventory));
    } catch (e) {}

    if (writePromises.length > 0) {
        await Promise.all(writePromises);
    }

    if (typeof window.renderPanelInventory === 'function' && document.getElementById('owner-inventory-list')) {
        window.renderPanelInventory();
    }
    if (typeof window.renderTabStok === 'function' && document.getElementById('stok-kasir-list')) {
        window.renderTabStok();
    }

    if (typeof window.cekNotifikasiStokMinimum === 'function') {
        window.cekNotifikasiStokMinimum({
            showToast: alertCriticalItems.length > 0,
            newlyCritical: alertCriticalItems
        });
    }

    return deductions;
};

window.updateOrderStatus = async (orderKey, newStatus) => {
    try {
        const safeKey = String(orderKey || '').trim();
        if (!safeKey) return;

        // Cari order untuk animasi arah perpindahan Tab Masuk -> Dapur -> Selesai (tanpa popup konfirmasi preorder di Tab Masuk)
        let preCheckOrder = (globalOrders && globalOrders[safeKey]) || null;
        if (!preCheckOrder && globalOrders) {
            preCheckOrder = Object.values(globalOrders).find(o => o && (
                o.orderId === safeKey || o.id === safeKey || o.firebaseKey === safeKey ||
                String(o.orderId || '').toUpperCase() === safeKey.toUpperCase()
            )) || null;
        }

        // Efek animasi transisi geser arah Masuk -> Dapur -> Selesai
        const prevStatus = String(preCheckOrder?.status || '').toLowerCase();
        const stepIndex = (st) => {
            if (typeof window.isSelesaiStatus === 'function' && window.isSelesaiStatus(st)) return 2;
            if (typeof window.isProsesStatus === 'function' && window.isProsesStatus(st)) return 1;
            return 0;
        };
        const dirForward = stepIndex(newStatus) >= stepIndex(prevStatus);
        try {
            const cardEl = document.getElementById(`order-card-${safeKey}`);
            if (cardEl) {
                cardEl.classList.add(dirForward ? 'order-card-slide-out-left' : 'order-card-slide-out-right');
                await new Promise(r => setTimeout(r, 210));
            }
        } catch (e) {}

        const nowTs = Date.now();
        window._recentlyMovedOrder = {
            keys: [safeKey, String(preCheckOrder?.orderId || '').toUpperCase(), String(preCheckOrder?.id || '')].filter(Boolean),
            dir: dirForward ? 'next' : 'prev',
            ts: nowTs
        };
        let targetOrder = null;
        let actualFirebaseKey = safeKey;
        const isSelesaiNow = (typeof window.isSelesaiStatus === 'function') ? window.isSelesaiStatus(newStatus) : (newStatus === 'selesai');
        const selesaiTs = isSelesaiNow ? nowTs : null;
        const waktuSelesaiStr = isSelesaiNow ? new Date().toLocaleTimeString('id-ID') : null;

        // 1. Temukan order target di globalOrders
        if (globalOrders && globalOrders[safeKey]) {
            targetOrder = globalOrders[safeKey];
            targetOrder.status = newStatus;
            targetOrder.updatedAt = nowTs;
            if (isSelesaiNow) {
                targetOrder.selesaiTimestamp = selesaiTs;
                targetOrder.waktuSelesai = waktuSelesaiStr;
            }
            if (targetOrder.firebaseKey) actualFirebaseKey = targetOrder.firebaseKey;
        } else if (globalOrders) {
            for (const [k, ord] of Object.entries(globalOrders)) {
                if (ord && (k === safeKey || ord.orderId === safeKey || ord.id === safeKey || ord.firebaseKey === safeKey ||
                    String(ord.orderId || '').toUpperCase() === safeKey.toUpperCase() ||
                    String(ord.id || '').toUpperCase() === safeKey.toUpperCase())) {
                    ord.status = newStatus;
                    ord.updatedAt = nowTs;
                    if (isSelesaiNow) {
                        ord.selesaiTimestamp = selesaiTs;
                        ord.waktuSelesai = waktuSelesaiStr;
                    }
                    targetOrder = ord;
                    actualFirebaseKey = ord.firebaseKey || k;
                    break;
                }
            }
        }

        // 1B. Jika belum ada di globalOrders, cari di cache offline
        if (!targetOrder) {
            try {
                const offlineList = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
                const foundOff = offlineList.find(o => o && (o.id === safeKey || o.orderId === safeKey || o.firebaseKey === safeKey || String(o.orderId || '').toUpperCase() === safeKey.toUpperCase()));
                if (foundOff) {
                    targetOrder = { ...foundOff, status: newStatus, updatedAt: nowTs };
                    if (isSelesaiNow) {
                        targetOrder.selesaiTimestamp = selesaiTs;
                        targetOrder.waktuSelesai = waktuSelesaiStr;
                    }
                    globalOrders[safeKey] = targetOrder;
                    if (foundOff.firebaseKey) actualFirebaseKey = foundOff.firebaseKey;
                }
            } catch (e) {}
        }

        // 1C. Saat orderan berstatus 'selesai', potong stok gudang otomatis berdasarkan resep menu & topping (real-time + idempoten)
        if (isSelesaiNow && targetOrder && !targetOrder.stockDeducted && typeof window.potongStokOtomatisDariOrder === 'function') {
            await window.potongStokOtomatisDariOrder(targetOrder, safeKey, actualFirebaseKey);
        }

        // 2. Sinkronkan seluruh entri pesanan dengan ID yang sama di memori
        if (globalOrders && targetOrder) {
            const matchIds = [safeKey, actualFirebaseKey, targetOrder.id, targetOrder.orderId, targetOrder.firebaseKey].filter(Boolean);
            Object.values(globalOrders).forEach(o => {
                if (o && (matchIds.includes(o.id) || matchIds.includes(o.orderId) || matchIds.includes(o.firebaseKey) || (o.orderId && String(o.orderId).toUpperCase() === safeKey.toUpperCase()))) {
                    o.status = newStatus;
                    o.updatedAt = nowTs;
                    if (isSelesaiNow) {
                        o.selesaiTimestamp = selesaiTs;
                        o.waktuSelesai = waktuSelesaiStr;
                        if (targetOrder.stockDeducted) {
                            o.stockDeducted = true;
                            o.stockDeductedAt = targetOrder.stockDeductedAt;
                            o.stockDeductions = targetOrder.stockDeductions;
                        }
                    }
                }
            });
        }

        // 3. Simpan pembaruan status ke cache lokal offline
        try {
            let saved = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            let foundInSaved = false;
            saved = saved.map(o => {
                const matchIds = [safeKey, actualFirebaseKey, targetOrder?.id, targetOrder?.orderId, targetOrder?.firebaseKey].filter(Boolean);
                if (o && (matchIds.includes(o.id) || matchIds.includes(o.orderId) || matchIds.includes(o.firebaseKey) || (o.orderId && String(o.orderId).toUpperCase() === safeKey.toUpperCase()))) {
                    foundInSaved = true;
                    const updated = { ...o, status: newStatus, updatedAt: nowTs };
                    if (isSelesaiNow) {
                        updated.selesaiTimestamp = selesaiTs;
                        updated.waktuSelesai = waktuSelesaiStr;
                        if (targetOrder?.stockDeducted) {
                            updated.stockDeducted = true;
                            updated.stockDeductedAt = targetOrder.stockDeductedAt;
                            updated.stockDeductions = targetOrder.stockDeductions;
                        }
                    }
                    return updated;
                }
                return o;
            });
            if (!foundInSaved && targetOrder) {
                saved.push({ ...targetOrder, status: newStatus, updatedAt: nowTs, selesaiTimestamp: selesaiTs, waktuSelesai: waktuSelesaiStr });
            }
            localStorage.setItem('mainstay_offline_orders', JSON.stringify(saved));
        } catch (e) {}

        // 4. Sinkronkan status ke antrean posSyncEngine jika pesanan dibuat saat offline
        try {
            if (window.posSyncEngine && typeof window.posSyncEngine.getPendingQueue === 'function') {
                const queue = window.posSyncEngine.getPendingQueue();
                let queueChanged = false;
                const matchIds = [safeKey, actualFirebaseKey, targetOrder?.id, targetOrder?.orderId, targetOrder?.firebaseKey].filter(Boolean);
                queue.forEach(item => {
                    if (item.type === 'order' && (matchIds.includes(item.id) || (item.payload && (matchIds.includes(item.payload.id) || matchIds.includes(item.payload.orderId))))) {
                        if (item.payload) {
                            item.payload.status = newStatus;
                            item.payload.updatedAt = nowTs;
                            if (isSelesaiNow) {
                                item.payload.selesaiTimestamp = selesaiTs;
                                item.payload.waktuSelesai = waktuSelesaiStr;
                                if (targetOrder?.stockDeducted) {
                                    item.payload.stockDeducted = true;
                                    item.payload.stockDeductedAt = targetOrder.stockDeductedAt;
                                }
                            }
                        }
                        queueChanged = true;
                    }
                });
                if (queueChanged) {
                    window.posSyncEngine.savePendingQueue(queue);
                }
            }
        } catch (e) {}

        // 5. Segarkan UI seketika
        if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
        if (typeof window.updateLiveCashDrawer === 'function') window.updateLiveCashDrawer();
        if (typeof window.updateOwnerDashboard === 'function') window.updateOwnerDashboard();

        // 6. Update di Firebase Realtime Database
        const updatePayload = { status: newStatus, updatedAt: nowTs };
        if (isSelesaiNow) {
            updatePayload.selesaiTimestamp = selesaiTs;
            updatePayload.waktuSelesai = waktuSelesaiStr;
            if (targetOrder?.stockDeducted) {
                updatePayload.stockDeducted = true;
                updatePayload.stockDeductedAt = targetOrder.stockDeductedAt || nowTs;
            }
        }

        try {
            if (typeof db !== 'undefined' && db) {
                const orderRef = ref(db, `orders/${safeKey}`);
                await update(orderRef, updatePayload);
                if (actualFirebaseKey && actualFirebaseKey !== safeKey) {
                    const fbRef = ref(db, `orders/${actualFirebaseKey}`);
                    await update(fbRef, updatePayload);
                }
            }
        } catch (errKey) {}

        // 7. Sinkronkan juga ke Firestore jika tersedia
        if (typeof firestoreDb !== 'undefined' && firestoreDb) {
            try {
                await setDoc(doc(firestoreDb, "orders", String(safeKey)), updatePayload, { merge: true });
                await setDoc(doc(firestoreDb, "transaksi", String(safeKey)), updatePayload, { merge: true });
                if (actualFirebaseKey && actualFirebaseKey !== safeKey) {
                    await setDoc(doc(firestoreDb, "orders", String(actualFirebaseKey)), updatePayload, { merge: true });
                }
            } catch (fsErr) {
                console.warn("Firestore status update:", fsErr);
            }
        }
    } catch (error) {
        console.error("Update Status Error:", error);
    }
};

// ==========================================
// MODAL KONFIRMASI GLOBAL MODERN (PENGGANTI CONFIRM NATIVE)
// ==========================================
window.tampilkanKonfirmasiGlobal = ({
    title = "Konfirmasi Tindakan",
    message = "Apakah Anda yakin ingin melanjutkan tindakan ini?",
    subtext = "Tindakan ini permanen dan tidak dapat dibatalkan.",
    icon = "fa-trash-can",
    confirmText = "Ya, Lanjutkan",
    cancelText = "Batal",
    isDanger = true,
    onConfirm = null,
    onCancel = null
}) => {
    const modalLama = document.getElementById('popup-konfirmasi-global');
    if (modalLama) modalLama.remove();

    const modal = document.createElement('div');
    modal.id = 'popup-konfirmasi-global';
    modal.className = "fixed inset-0 z-[999999] bg-slate-950/75 backdrop-blur-md flex items-center justify-center p-4 opacity-0 transition-opacity duration-300";

    const ringBg = isDanger ? 'bg-rose-50 text-rose-500 border-rose-100 ring-rose-100/60' : 'bg-amber-50 text-amber-500 border-amber-100 ring-amber-100/60';
    const confirmBtnClass = isDanger 
        ? 'bg-gradient-to-r from-rose-600 to-red-600 hover:from-rose-700 hover:to-red-700 text-white shadow-lg shadow-rose-500/25' 
        : 'bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-slate-900 shadow-lg shadow-amber-500/25';

    modal.innerHTML = `
        <div class="bg-white w-full max-w-sm rounded-[2rem] p-6 flex flex-col items-center text-center shadow-2xl border border-slate-100 ring-1 ring-black/5 transform scale-95 transition-all duration-300">
            <div class="w-16 h-16 shrink-0 rounded-2xl ${ringBg} flex items-center justify-center text-2xl mb-4 border shadow-inner ring-4">
                <i class="fa-solid ${icon}"></i>
            </div>
            <h3 class="text-base sm:text-lg font-black text-slate-900 tracking-tight mb-1.5">${title}</h3>
            <p class="text-xs font-bold text-slate-600 mb-1 px-2 leading-relaxed">${message}</p>
            ${subtext ? `<p class="text-[11px] text-slate-400 font-medium mb-6 px-2 leading-relaxed">${subtext}</p>` : '<div class="mb-5"></div>'}
            
            <div class="flex gap-2.5 w-full">
                ${cancelText ? `
                <button id="btn-global-modal-cancel" type="button" class="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-black py-3 rounded-xl transition text-xs tracking-wider uppercase active:scale-95">
                    ${cancelText}
                </button>
                ` : ''}
                <button id="btn-global-modal-confirm" type="button" class="${cancelText ? 'flex-1' : 'w-full'} ${confirmBtnClass} font-black py-3 rounded-xl transition text-xs tracking-wider uppercase active:scale-95 flex items-center justify-center gap-1.5">
                    <i class="fa-solid ${icon} text-xs"></i> <span>${confirmText}</span>
                </button>
            </div>
        </div>
    `;

    document.body.appendChild(modal);

    setTimeout(() => {
        modal.classList.remove('opacity-0');
        const box = modal.querySelector('div');
        if (box) box.classList.remove('scale-95');
    }, 10);

    const closeSelf = () => {
        modal.classList.add('opacity-0');
        const box = modal.querySelector('div');
        if (box) box.classList.add('scale-95');
        setTimeout(() => modal.remove(), 250);
    };

    const cancelBtn = document.getElementById('btn-global-modal-cancel');
    if (cancelBtn) {
        cancelBtn.onclick = () => {
            closeSelf();
            if (typeof onCancel === 'function') onCancel();
        };
    }

    const confirmBtn = document.getElementById('btn-global-modal-confirm');
    if (confirmBtn) {
        confirmBtn.onclick = async () => {
            confirmBtn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin text-xs"></i> <span>Memproses...</span>';
            confirmBtn.disabled = true;
            if (cancelBtn) cancelBtn.disabled = true;

            try {
                if (typeof onConfirm === 'function') {
                    await onConfirm();
                }
                closeSelf();
            } catch (err) {
                console.error('Konfirmasi Error:', err);
                confirmBtn.innerHTML = `<i class="fa-solid ${icon} text-xs"></i> <span>${confirmText}</span>`;
                confirmBtn.disabled = false;
                if (cancelBtn) cancelBtn.disabled = false;
            }
        };
    }
};

window.tampilkanAlertGlobal = (msg, title = "Pemberitahuan", icon = "fa-circle-info") => {
    window.tampilkanKonfirmasiGlobal({
        title: title,
        message: msg,
        subtext: "",
        icon: icon,
        confirmText: "Mengerti",
        cancelText: null,
        isDanger: false,
        onConfirm: () => {}
    });
};

window.tampilkanNotifikasi = window.showNotification = (message, type = 'info', durationMs = 2800) => {
    try {
        let container = document.getElementById('mainstay-floating-toast-stack');
        if (!container) {
            container = document.createElement('div');
            container.id = 'mainstay-floating-toast-stack';
            container.className = 'fixed top-4 right-4 z-[9999999] flex flex-col gap-2 max-w-xs w-[calc(100vw-2rem)] pointer-events-none';
            document.body.appendChild(container);
        }

        const palette = {
            success: 'bg-emerald-600 text-white border-emerald-400',
            error: 'bg-rose-600 text-white border-rose-400',
            warning: 'bg-amber-500 text-slate-950 border-amber-300',
            info: 'bg-slate-900 text-white border-slate-700'
        };
        const iconMap = {
            success: 'fa-circle-check',
            error: 'fa-circle-exclamation',
            warning: 'fa-triangle-exclamation',
            info: 'fa-circle-info'
        };
        const t = palette[type] ? type : 'info';

        const toast = document.createElement('div');
        toast.className = `${palette[t]} px-3.5 py-2.5 rounded-2xl shadow-2xl border text-xs font-black flex items-center gap-2.5 pointer-events-auto transition-all duration-300 opacity-0 translate-y-1`;

        const iconEl = document.createElement('i');
        iconEl.className = `fa-solid ${iconMap[t]} text-sm shrink-0`;

        const msgEl = document.createElement('span');
        msgEl.className = 'flex-1 leading-snug break-words';
        msgEl.textContent = String(message || '');

        toast.appendChild(iconEl);
        toast.appendChild(msgEl);
        container.appendChild(toast);

        requestAnimationFrame(() => {
            toast.classList.remove('opacity-0', 'translate-y-1');
        });

        setTimeout(() => {
            toast.classList.add('opacity-0', 'translate-y-1');
            setTimeout(() => toast.remove(), 260);
        }, durationMs);
    } catch (e) {
        console.log('[Notif]', type, message);
    }
};

// Safe modern interceptor for native window.alert to eliminate ugly browser alert popups
try {
    window.alert = function(message) {
        try {
            const strMsg = String(message || '');
            const isDanger = strMsg.includes('⛔') || strMsg.includes('Gagal') || strMsg.includes('Ditolak') || strMsg.includes('Salah') || strMsg.includes('Tutup');
            const isSuccess = strMsg.includes('✅') || strMsg.includes('Berhasil') || strMsg.includes('Selamat') || strMsg.includes('Diberikan');
            const icon = isDanger ? 'fa-circle-exclamation' : (isSuccess ? 'fa-circle-check' : 'fa-bell');
            const title = isDanger ? 'Peringatan Sistem' : (isSuccess ? 'Berhasil' : 'Pemberitahuan');
            window.tampilkanKonfirmasiGlobal({
                title: title,
                message: strMsg,
                subtext: '',
                icon: icon,
                confirmText: 'Mengerti',
                cancelText: null,
                isDanger: isDanger,
                onConfirm: () => {}
            });
        } catch(e) {
            console.warn('Native alert intercepted:', message);
        }
    };
} catch(e) {}

window.batalOrder = async (orderKey) => {
    const safeKey = String(orderKey || '').trim();
    if (!safeKey) return;

    let ord = (globalOrders && globalOrders[safeKey]) || (window.globalOrders && window.globalOrders[safeKey]) || null;
    let actualFirebaseKey = safeKey;

    if (!ord && globalOrders) {
        for (const [k, v] of Object.entries(globalOrders)) {
            if (v && (v.orderId === safeKey || v.id === safeKey || k === safeKey || (v.orderId && safeKey.includes(v.orderId)))) {
                ord = v;
                actualFirebaseKey = k;
                break;
            }
        }
    }
    const code = (ord && (ord.orderId || ord.id)) || safeKey;
    const name = (ord && (ord.customerName || ord.namaPelanggan)) || 'Pelanggan';

    if (typeof window.tampilkanKonfirmasiGlobal === 'function') {
        window.tampilkanKonfirmasiGlobal({
            title: "Batalkan Pesanan?",
            message: `Apakah Anda yakin ingin membatalkan & menghapus pesanan #${code} (${name})?`,
            subtext: "Pesanan yang dibatalkan akan langsung dihapus dari antrean kasir.",
            icon: "fa-ban",
            confirmText: "Ya, Batalkan",
            cancelText: "Batal / Kembali",
            isDanger: true,
            onConfirm: async () => {
                await window.eksekusiBatalOrder(safeKey, actualFirebaseKey);
            }
        });
    } else {
        await window.eksekusiBatalOrder(safeKey, actualFirebaseKey);
    }
};

window.eksekusiBatalOrder = async (orderKey, actualFirebaseKey = null) => {
    try {
        const key1 = String(orderKey || '').trim();
        const key2 = String(actualFirebaseKey || '').trim();

        // 0. Ambil snapshot data pesanan sebelum dihapus untuk Activity Log
        let deletedOrderSnapshot = null;
        if (globalOrders) {
            if (key1 && globalOrders[key1]) deletedOrderSnapshot = { ...globalOrders[key1] };
            else if (key2 && globalOrders[key2]) deletedOrderSnapshot = { ...globalOrders[key2] };
            else {
                for (const v of Object.values(globalOrders)) {
                    if (v && (v.orderId === key1 || v.id === key1 || v.orderId === key2 || v.id === key2)) {
                        deletedOrderSnapshot = { ...v };
                        break;
                    }
                }
            }
        }

        // 1. Bersihkan seketika dari state globalOrders agar kartu langsung lenyap tanpa klik ganda
        if (globalOrders) {
            if (key1 && globalOrders[key1]) delete globalOrders[key1];
            if (key2 && globalOrders[key2]) delete globalOrders[key2];
            for (const [k, v] of Object.entries(globalOrders)) {
                if (v && (v.orderId === key1 || v.id === key1 || v.orderId === key2 || v.id === key2)) {
                    delete globalOrders[k];
                }
            }
        }

        try {
            let saved = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            saved = saved.filter(o => o.orderId !== key1 && o.id !== key1 && o.firebaseKey !== key1 && o.orderId !== key2 && o.id !== key2 && o.firebaseKey !== key2);
            localStorage.setItem('mainstay_offline_orders', JSON.stringify(saved));
        } catch (e) {}

        try {
            if (window.posSyncEngine && typeof window.posSyncEngine.getPendingQueue === 'function') {
                const queue = window.posSyncEngine.getPendingQueue().filter(it => it.id !== key1 && it.id !== key2 && (!it.payload || (it.payload.id !== key1 && it.payload.orderId !== key1 && it.payload.id !== key2 && it.payload.orderId !== key2)));
                window.posSyncEngine.savePendingQueue(queue);
            }
        } catch(e) {}

        // 2. Refresh UI kasir seketika
        if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
        if (typeof window.updateLiveCashDrawer === 'function') window.updateLiveCashDrawer();

        // 3. Hapus dari Firebase RTDB di semua kemungkinan alias key
        const keysToRemove = new Set([key1, key2].filter(Boolean));
        for (const k of keysToRemove) {
            try {
                await remove(ref(db, 'orders/' + k));
            } catch(e) {}
        }

        if (typeof window.catatLogAktivitas === 'function') {
            const oCode = (deletedOrderSnapshot && (deletedOrderSnapshot.orderId || deletedOrderSnapshot.id)) || key1 || key2;
            const oCust = (deletedOrderSnapshot && (deletedOrderSnapshot.customerName || deletedOrderSnapshot.namaPelanggan)) || 'Pelanggan';
            const oTotal = Number(deletedOrderSnapshot?.totalAmount ?? deletedOrderSnapshot?.total ?? 0);
            const oStatus = String(deletedOrderSnapshot?.status || 'pending');
            const oItemCount = Array.isArray(deletedOrderSnapshot?.items) ? deletedOrderSnapshot.items.length : 0;
            window.catatLogAktivitas({
                category: 'order_deletion',
                actionType: 'Order Deletion',
                targetType: 'order',
                targetKey: key2 || key1,
                targetName: `#${oCode} (${oCust})`,
                beforeVal: `${oStatus.toUpperCase()} • ${formatRupiah(oTotal)}`,
                afterVal: 'Dihapus / Dibatalkan',
                summary: `Pesanan #${oCode} a.n. ${oCust}${oItemCount ? ` (${oItemCount} item)` : ''} senilai ${formatRupiah(oTotal)} dibatalkan & dihapus.`
            });
        }

        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(`Pesanan #${key1} berhasil dibatalkan.`, "info");
        }
    } catch (error) {
        console.error("Void Order Error:", error);
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi("Gagal membatalkan pesanan.", "error");
        }
    }
};

