window._editingOrderKey = null;
window._editingOrderItems = [];
window._editingOrderDiskon = 0;
window._editingOrderCustomer = '';
window._editingItemVarianIndex = null;
window._editingItemVarianState = null;

// ==========================================
// MESIN SUARA NOTIFIKASI TERPUSAT (ANTI DOUBLE / ANTI ECHO)
// ==========================================
// ==========================================
// MESIN SUARA NOTIFIKASI PESANAN & WEB AUDIO CHIME
// ==========================================
window.playNotificationChimeWebAudio = () => {
    try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        if (ctx.state === 'suspended') {
            ctx.resume();
        }
        const now = ctx.currentTime;
        
        // Nada 1: 784 Hz (G5)
        const osc1 = ctx.createOscillator();
        const gain1 = ctx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(783.99, now);
        gain1.gain.setValueAtTime(0.25, now);
        gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
        osc1.connect(gain1);
        gain1.connect(ctx.destination);
        osc1.start(now);
        osc1.stop(now + 0.35);

        // Nada 2: 1046.5 Hz (C6)
        const osc2 = ctx.createOscillator();
        const gain2 = ctx.createGain();
        osc2.type = 'sine';
        osc2.frequency.setValueAtTime(1046.50, now + 0.12);
        gain2.gain.setValueAtTime(0.3, now + 0.12);
        gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.55);
        osc2.connect(gain2);
        gain2.connect(ctx.destination);
        osc2.start(now + 0.12);
        osc2.stop(now + 0.55);
    } catch (e) {
        console.log('Web Audio Chime notice:', e);
    }
};

window.playOrderNotificationSound = () => {
    const now = Date.now();
    if (window._lastSoundPlayedAt && (now - window._lastSoundPlayedAt < 2000)) {
        return; // Debounce suara cepat dalam 2 detik
    }
    window._lastSoundPlayedAt = now;
    
    // Bunyikan sintesis instan Web Audio Chime terlebih dahulu (100% andal di semua browser)
    window.playNotificationChimeWebAudio();
    
    // Bunyikan juga file audio notif MP3 jika didukung browser
    try {
        const notifSound = new Audio('/notif-mainstay.mp3');
        notifSound.volume = 0.8;
        notifSound.play().catch(() => {});
    } catch (e) {}
};
// HELPER UNIVERSAL: PENCARIAN MENU KATALOG PRESISI & TOLERAN
window.findMenuInKatalog = (it) => {
    if (!it) return null;
    if (typeof globalMenus !== 'object' || !globalMenus) return null;

    // 1. Cek langsung via id atau rawMenuKey
    if (it.rawMenuKey && globalMenus[it.rawMenuKey]) {
        return { key: it.rawMenuKey, ...globalMenus[it.rawMenuKey] };
    }
    if (it.id && globalMenus[it.id]) {
        return { key: it.id, ...globalMenus[it.id] };
    }

    // 2. Jika id atau key adalah composite (cth: "-O123_Large_Boba")
    const cleanId = typeof it.id === 'string' ? it.id : '';
    const cleanKey = typeof it.key === 'string' ? it.key : '';
    if (cleanId.includes('_')) {
        const prefix = cleanId.split('_')[0];
        if (globalMenus[prefix]) return { key: prefix, ...globalMenus[prefix] };
    }
    if (cleanKey.includes('_')) {
        const prefix = cleanKey.split('_')[0];
        if (globalMenus[prefix]) return { key: prefix, ...globalMenus[prefix] };
    }

    // 3. Cari berdasarkan nama menu secara toleran
    let searchName = String(it.name || it.nama || '').trim();
    searchName = searchName.replace(/\s*\([^)]*\)\s*/g, '').trim().toLowerCase();

    const entries = Object.entries(globalMenus);

    // 3a. Exact match
    for (const [k, m] of entries) {
        if (!m) continue;
        const mName = String(m.name || m.nama || '').trim().toLowerCase();
        if (mName && mName === searchName) {
            return { key: k, ...m };
        }
    }

    // 3b. StartsWith atau contains match
    for (const [k, m] of entries) {
        if (!m) continue;
        const mName = String(m.name || m.nama || '').trim().toLowerCase();
        if (mName && (searchName.includes(mName) || mName.includes(searchName))) {
            return { key: k, ...m };
        }
    }

    // 3c. Token overlap match (cth: "taro" cocok dengan "Taro Boba" atau "Taro Milk Tea")
    const tokens = searchName.split(/\s+/).filter(t => t.length >= 3);
    if (tokens.length > 0) {
        for (const [k, m] of entries) {
            if (!m) continue;
            const mName = String(m.name || m.nama || '').trim().toLowerCase();
            if (tokens.some(tok => mName.includes(tok))) {
                return { key: k, ...m };
            }
        }
    }

    return null;
};

window.bukaModalEditPesananMasuk = (orderKey) => {
    let order = (globalOrders && globalOrders[orderKey]) || null;
    if (!order && globalOrders) {
        order = Object.values(globalOrders).find(o => o && (o.id === orderKey || o.orderId === orderKey || o.firebaseKey === orderKey));
    }
    if (!order) {
        try {
            const saved = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            order = saved.find(o => o.id === orderKey || o.orderId === orderKey || o.firebaseKey === orderKey);
        } catch(e) {}
    }
    if (!order) {
        alert("Data pesanan tidak ditemukan.");
        return;
    }

    window._editingOrderKey = orderKey;
    window._editingOrderCustomer = order.customerName || order.namaPelanggan || 'Pelanggan';
    window._editingOrderItems = JSON.parse(JSON.stringify(order.items || []));
    window._editingOrderDiskon = Number(order.diskonVoucher || 0);

    // Normalisasi setiap item agar struktur varian & topping seragam
    window._editingOrderItems.forEach(it => {
        if (!it.qty) it.qty = 1;
        if (!it.name) it.name = it.nama || 'Menu';
        if (!it.nama) it.nama = it.name;

        // Cari menu di katalog master secara akurat
        const menuRef = window.findMenuInKatalog(it);
        if (menuRef) {
            it.rawMenuKey = menuRef.key || it.rawMenuKey || '';
            if (menuRef.key) it.id = menuRef.key;
            if (!it.basePrice) {
                it.basePrice = Number(menuRef.price || menuRef.harga || it.price || 0);
            }
        } else {
            if (!it.basePrice) {
                it.basePrice = Number(it.price || 0);
            }
        }
        if (!it.price) it.price = (Number(it.total) && it.qty) ? Math.round(Number(it.total) / it.qty) : (it.basePrice || 0);
        if (!it.total) it.total = Number(it.price) * Number(it.qty);
        
        // Ekstrak topping menjadi array
        if (!it.toppings) it.toppings = [];
        if (typeof it.toppings === 'string') {
            it.toppings = it.toppings.split(',').map(s => s.trim()).filter(Boolean);
        }
        if (!it.varian && it.notes) it.varian = it.notes;
    });

    let modal = document.getElementById('modal-edit-pesanan-masuk');
    if (modal) modal.remove();

    modal = document.createElement('div');
    modal.id = 'modal-edit-pesanan-masuk';
    modal.className = "fixed inset-0 z-[99999] bg-slate-950/75 backdrop-blur-md flex items-center justify-center p-3 sm:p-4 opacity-0 transition-opacity duration-300";
    
    document.body.appendChild(modal);

    window.renderModalEditPesananContent();

    setTimeout(() => {
        modal.classList.remove('opacity-0');
        const box = modal.querySelector('div');
        if (box) box.classList.remove('scale-95');
    }, 10);
};

window.tutupModalEditPesananMasuk = () => {
    const modal = document.getElementById('modal-edit-pesanan-masuk');
    if (!modal) return;
    modal.classList.add('opacity-0');
    const box = modal.querySelector('div');
    if (box) box.classList.add('scale-95');
    setTimeout(() => {
        if (modal) modal.remove();
        window._editingOrderKey = null;
        window._editingOrderItems = [];
    }, 250);
};

