window.tambahQtyItemEditPesanan = (idx) => {
    if (window._editingOrderItems && window._editingOrderItems[idx]) {
        window._editingOrderItems[idx].qty = (window._editingOrderItems[idx].qty || 1) + 1;
        window._editingOrderItems[idx].total = (Number(window._editingOrderItems[idx].price) || 0) * window._editingOrderItems[idx].qty;
        window.renderModalEditPesananContent();
    }
};

window.kurangQtyItemEditPesanan = (idx) => {
    if (window._editingOrderItems && window._editingOrderItems[idx]) {
        if (window._editingOrderItems[idx].qty > 1) {
            window._editingOrderItems[idx].qty -= 1;
            window._editingOrderItems[idx].total = (Number(window._editingOrderItems[idx].price) || 0) * window._editingOrderItems[idx].qty;
        } else {
            window._editingOrderItems.splice(idx, 1);
        }
        window.renderModalEditPesananContent();
    }
};

window.hapusItemEditPesanan = (idx) => {
    if (window._editingOrderItems && window._editingOrderItems[idx]) {
        window._editingOrderItems.splice(idx, 1);
        window.renderModalEditPesananContent();
    }
};

window.tambahItemTerpilihKeEdit = () => {
    const select = document.getElementById('select-tambah-menu-edit');
    const menuKey = select?.value;
    if (!menuKey) {
        if (typeof window.tampilkanKonfirmasiGlobal === 'function') {
            window.tampilkanKonfirmasiGlobal({
                title: "Pilih Menu Terlebih Dahulu",
                message: "Silakan pilih menu dari daftar katalog sebelum menekan tombol Tambah.",
                subtext: "Gunakan menu pilihan untuk menentukan produk yang ingin ditambahkan ke pesanan ini.",
                icon: "fa-mug-hot",
                confirmText: "Mengerti",
                cancelText: "Tutup",
                isDanger: false,
                onConfirm: () => {
                    select?.focus();
                }
            });
        }
        return;
    }
    const menu = (globalMenus && globalMenus[menuKey]);
    if (!menu) return;

    const basePrice = Number(menu.price || menu.harga || 0);
    const newItem = {
        id: menuKey,
        rawMenuKey: menuKey,
        name: menu.name || menu.nama || 'Menu Baru',
        basePrice: basePrice,
        price: basePrice,
        qty: 1,
        total: basePrice,
        varian: 'Standard',
        toppings: [],
        notes: '',
        imageUrl: menu.imageUrl || 'logo-192.png'
    };

    window._editingOrderItems.push(newItem);
    const newIdx = window._editingOrderItems.length - 1;
    window.renderModalEditPesananContent();

    // Langsung buka modal pilihan varian & topping untuk item baru ini
    window.bukaModalEditItemVarianTopping(newIdx);
};

// ==========================================
// SUB-MODAL EDIT VARIAN & TOPPING PER ITEM
// ==========================================
window.bukaModalEditItemVarianTopping = (itemIndex) => {
    const it = window._editingOrderItems && window._editingOrderItems[itemIndex];
    if (!it) return;

    window._editingItemVarianIndex = itemIndex;

    // Temukan referensi menu di katalog secara presisi & toleran
    const menuRef = (typeof window.findMenuInKatalog === 'function') 
        ? window.findMenuInKatalog(it) 
        : ((globalMenus && (globalMenus[it.id] || globalMenus[it.rawMenuKey])) || null);

    const basePrice = Number(it.basePrice || menuRef?.price || menuRef?.harga || it.price || 0);

    // Ambil daftar varian yang tersedia sesuai menu (sama persis dengan self order & POS)
    let variantsList = [];
    if (menuRef) {
        const hasVarian = menuRef.hasVariant === true || (menuRef.hasVariant !== false && Array.isArray(menuRef.varianIds) && menuRef.varianIds.length > 0);
        const linkedVarianIds = hasVarian 
            ? (Array.isArray(menuRef.varianIds) && menuRef.varianIds.length > 0 ? menuRef.varianIds : (menuRef.hasVariant === true && Array.isArray(menuRef.varian) ? menuRef.varian : [])) 
            : [];
        if (linkedVarianIds.length > 0) {
            variantsList = linkedVarianIds.map(vid => typeof window.resolveVarian === 'function' ? window.resolveVarian(vid) : null).filter(Boolean);
        }
    }

    // Ambil daftar topping yang tersedia sesuai menu (sama persis dengan self order & POS)
    let toppingsList = [];
    if (menuRef) {
        const hasTopping = menuRef.hasTopping === true || (menuRef.hasTopping !== false && Array.isArray(menuRef.toppingIds) && menuRef.toppingIds.length > 0);
        let linkedToppingIds = [];
        if (hasTopping) {
            if (Array.isArray(menuRef.toppingIds) && menuRef.toppingIds.length > 0) {
                linkedToppingIds = menuRef.toppingIds;
            } else if (Array.isArray(menuRef.toppings) && menuRef.toppings.length > 0) {
                linkedToppingIds = menuRef.toppings;
            }
        }
        if (linkedToppingIds.length > 0) {
            toppingsList = linkedToppingIds.map(tid => typeof window.resolveTopping === 'function' ? window.resolveTopping(tid) : null).filter(Boolean);
        }
    }

    // Inisialisasi state pilihan varian
    const selectedVariants = {};
    const currentNotesStr = String(it.varian || it.notes || '').toLowerCase();

    variantsList.forEach((v, vIndex) => {
        const vGroupName = v.name || v.nama || `Varian ${vIndex + 1}`;
        const opsiArr = v.opsi || [];
        
        // Cari opsi yang sedang aktif berdasarkan string catatan sebelumnya
        let chosenOptIndex = 0;
        opsiArr.forEach((opt, oIdx) => {
            const optName = String(opt.namaOpsi || opt.name || opt.nama || '').toLowerCase();
            if (optName && currentNotesStr.includes(optName)) {
                chosenOptIndex = oIdx;
            }
        });

        const activeOpt = opsiArr[chosenOptIndex] || { namaOpsi: 'Normal', harga: 0 };
        selectedVariants[vIndex] = {
            groupName: vGroupName,
            optionName: activeOpt.namaOpsi || activeOpt.name || activeOpt.nama || 'Normal',
            extraPrice: Number(activeOpt.harga || activeOpt.price || 0),
            optionIndex: chosenOptIndex
        };
    });

    // Inisialisasi state pilihan topping
    const selectedToppings = {};
    const currentToppingsArr = Array.isArray(it.toppings) ? it.toppings : [];
    toppingsList.forEach((top, tIdx) => {
        const topName = top.nama || top.name || 'Topping';
        const topPrice = Number(top.harga || top.price || 0);
        const topId = String(top.id || topName).replace(/[^a-zA-Z0-9_-]/g, '_');
        
        const isChecked = currentToppingsArr.some(t => String(t).toLowerCase() === topName.toLowerCase()) || currentNotesStr.includes(topName.toLowerCase());
        if (isChecked) {
            selectedToppings[topId] = {
                id: topId,
                toppingName: topName,
                extraPrice: topPrice
            };
        }
    });

    window._editingItemVarianState = {
        itemIndex: itemIndex,
        basePrice: basePrice,
        variantsList: variantsList,
        toppingsList: toppingsList,
        selectedVariants: selectedVariants,
        selectedToppings: selectedToppings
    };

    let subModal = document.getElementById('modal-edit-item-varian');
    if (subModal) subModal.remove();

    subModal = document.createElement('div');
    subModal.id = 'modal-edit-item-varian';
    subModal.className = "fixed inset-0 z-[100000] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-3 sm:p-4 opacity-0 transition-opacity duration-300";

    document.body.appendChild(subModal);

    window.renderSubModalVarianContent();

    setTimeout(() => {
        subModal.classList.remove('opacity-0');
        const box = subModal.querySelector('div');
        if (box) box.classList.remove('scale-95');
    }, 10);
};

window.renderSubModalVarianContent = () => {
    const subModal = document.getElementById('modal-edit-item-varian');
    if (!subModal || !window._editingItemVarianState) return;

    const state = window._editingItemVarianState;
    const it = window._editingOrderItems[state.itemIndex];
    if (!it) return;

    let variantsHtml = '';
    state.variantsList.forEach((v, vIndex) => {
        const vGroupName = v.name || v.nama || `Varian ${vIndex + 1}`;
        const selectedOptIdx = state.selectedVariants[vIndex]?.optionIndex || 0;

        variantsHtml += `
            <div class="bg-slate-50 p-3 rounded-2xl border border-slate-200">
                <label class="text-[10px] font-black text-slate-700 uppercase block mb-2 flex items-center gap-1.5">
                    <i class="fa-solid fa-layer-group text-indigo-500"></i> ${vGroupName}
                </label>
                <div class="grid grid-cols-2 gap-2">
                    ${(v.opsi || []).map((opt, oIndex) => {
                        const isSelected = selectedOptIdx === oIndex;
                        const optName = opt.namaOpsi || opt.name || opt.nama || '';
                        const optHarga = Number(opt.harga || opt.price || 0);
                        const hargaText = optHarga > 0 ? ` (+${formatRupiah(optHarga)})` : '';
                        
                        return `
                            <button type="button" onclick="window.pilihVarianEditItem(${vIndex}, ${oIndex}, '${optName.replace(/'/g, "\\'")}', ${optHarga})" class="flex items-center gap-2 p-2 rounded-xl text-left transition select-none ${isSelected ? 'bg-indigo-50 border-2 border-indigo-600 shadow-xs' : 'bg-white border border-slate-200 hover:border-slate-300'}">
                                <span class="w-4 h-4 rounded-full border-2 ${isSelected ? 'border-indigo-600 bg-white flex items-center justify-center' : 'border-slate-300 bg-white'} shrink-0">
                                    ${isSelected ? '<span class="w-2 h-2 rounded-full bg-indigo-600"></span>' : ''}
                                </span>
                                <div class="min-w-0 flex-1">
                                    <span class="text-xs font-bold text-slate-800 block leading-tight truncate">${optName}</span>
                                    <span class="text-[9px] ${optHarga > 0 ? 'text-indigo-600 font-bold' : 'text-slate-400 font-medium'}">${hargaText || 'Normal'}</span>
                                </div>
                            </button>
                        `;
                    }).join('')}
                </div>
            </div>
        `;
    });

    if (!variantsHtml) {
        variantsHtml = `
            <div class="bg-slate-50 p-3 rounded-2xl border border-slate-200 text-center py-2.5">
                <p class="text-[11px] text-slate-400 font-bold"><i class="fa-solid fa-layer-group text-slate-300 mr-1"></i> Menu ini tidak memiliki varian khusus.</p>
            </div>
        `;
    }

    let toppingsHtml = '';
    if (state.toppingsList && state.toppingsList.length > 0) {
        toppingsHtml = `
            <div class="bg-slate-50 p-3 rounded-2xl border border-slate-200">
                <label class="text-[10px] font-black text-slate-700 uppercase block mb-2 flex items-center gap-1.5">
                    <i class="fa-solid fa-cookie text-amber-500"></i> Pilihan Extra Topping:
                </label>
                <div class="grid grid-cols-2 gap-2">
                    ${state.toppingsList.map((top, tIdx) => {
                        const topName = top.nama || top.name || 'Topping';
                        const topPrice = Number(top.harga || top.price || 0);
                        const topId = String(top.id || topName).replace(/[^a-zA-Z0-9_-]/g, '_');
                        const isChecked = !!state.selectedToppings[topId];

                        return `
                            <button type="button" onclick="window.toggleToppingEditItem('${topId}', '${topName.replace(/'/g, "\\'")}', ${topPrice})" class="flex items-center gap-2 p-2 rounded-xl text-left transition select-none ${isChecked ? 'bg-amber-50 border-2 border-amber-500 shadow-xs' : 'bg-white border border-slate-200 hover:border-slate-300'}">
                                <span class="w-4 h-4 rounded-md border-2 ${isChecked ? 'border-amber-500 bg-amber-500 text-white flex items-center justify-center' : 'border-slate-300 bg-white'} shrink-0 text-[10px]">
                                    ${isChecked ? '<i class="fa-solid fa-check"></i>' : ''}
                                </span>
                                <div class="min-w-0 flex-1">
                                    <span class="text-xs font-bold text-slate-800 block leading-tight truncate">${topName}</span>
                                    <span class="text-[9px] text-amber-600 font-bold">+${formatRupiah(topPrice)}</span>
                                </div>
                            </button>
                        `;
                    }).join('')}
                </div>
            </div>
        `;
    } else {
        toppingsHtml = `
            <div class="bg-slate-50 p-3 rounded-2xl border border-slate-200 text-center py-2.5">
                <p class="text-[11px] text-slate-400 font-bold"><i class="fa-solid fa-cookie text-slate-300 mr-1"></i> Menu ini tidak menyediakan topping tambahan.</p>
            </div>
        `;
    }

    // Hitung total harga baru per item
    let extraVarianTotal = 0;
    Object.values(state.selectedVariants || {}).forEach(v => {
        extraVarianTotal += Number(v.extraPrice || 0);
    });
    let extraToppingTotal = 0;
    Object.values(state.selectedToppings || {}).forEach(t => {
        extraToppingTotal += Number(t.extraPrice || 0);
    });
    const calculatedUnitPrice = state.basePrice + extraVarianTotal + extraToppingTotal;

    subModal.innerHTML = `
        <div class="bg-white w-full max-w-md rounded-[2rem] p-5 sm:p-6 shadow-2xl border border-slate-100 flex flex-col max-h-[90vh] transform scale-95 transition-all duration-300">
            <div class="flex items-center justify-between border-b border-slate-100 pb-3 mb-3">
                <div class="flex items-center gap-2.5">
                    <div class="w-10 h-10 shrink-0 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center text-lg font-black border border-amber-100">
                        <i class="fa-solid fa-sliders"></i>
                    </div>
                    <div>
                        <h3 class="text-sm font-black text-slate-900 leading-tight">Sesuaikan Varian & Topping</h3>
                        <p class="text-[10px] text-slate-400 font-bold">${it.name} (Dasar: ${formatRupiah(state.basePrice)})</p>
                    </div>
                </div>
                <button type="button" onclick="window.tutupSubModalVarian()" class="w-8 h-8 shrink-0 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-500 flex items-center justify-center transition active:scale-90">
                    <i class="fa-solid fa-xmark text-sm"></i>
                </button>
            </div>

            <div class="flex-1 overflow-y-auto pr-1 space-y-3 mb-4 hide-scrollbar">
                ${variantsHtml}
                ${toppingsHtml}
            </div>

            <!-- Preview Total Harga Satuan Baru -->
            <div class="p-3 bg-amber-50/70 border border-amber-200 rounded-2xl mb-4 flex items-center justify-between">
                <div>
                    <span class="text-[10px] font-black uppercase text-amber-800 tracking-wide block">Harga Satuan Baru:</span>
                    <span class="text-[9px] text-slate-500 font-bold">Dasar (${formatRupiah(state.basePrice)}) + Opsi (${formatRupiah(extraVarianTotal + extraToppingTotal)})</span>
                </div>
                <span class="text-base font-black text-amber-700">${formatRupiah(calculatedUnitPrice)}</span>
            </div>

            <div class="flex gap-2.5">
                <button type="button" onclick="window.tutupSubModalVarian()" class="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-black py-3 rounded-xl transition text-xs tracking-wider uppercase active:scale-95">
                    Batal
                </button>
                <button type="button" onclick="window.simpanVarianEditItem()" class="flex-1 bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-slate-950 font-black py-3 rounded-xl shadow-lg shadow-amber-500/25 transition text-xs tracking-wider uppercase active:scale-95 flex items-center justify-center gap-1.5">
                    <i class="fa-solid fa-check"></i> Terapkan ke Pesanan
                </button>
            </div>
        </div>
    `;
};

window.pilihVarianEditItem = (vIndex, oIndex, optName, optHarga) => {
    if (!window._editingItemVarianState) return;
    const v = window._editingItemVarianState.variantsList[vIndex];
    const vGroupName = v ? (v.name || v.nama || `Varian ${vIndex + 1}`) : `Varian ${vIndex + 1}`;
    
    window._editingItemVarianState.selectedVariants[vIndex] = {
        groupName: vGroupName,
        optionName: optName,
        extraPrice: Number(optHarga || 0),
        optionIndex: oIndex
    };
    window.renderSubModalVarianContent();
};

window.toggleToppingEditItem = (topId, topName, topPrice) => {
    if (!window._editingItemVarianState) return;
    if (window._editingItemVarianState.selectedToppings[topId]) {
        delete window._editingItemVarianState.selectedToppings[topId];
    } else {
        window._editingItemVarianState.selectedToppings[topId] = {
            id: topId,
            toppingName: topName,
            extraPrice: Number(topPrice || 0)
        };
    }
    window.renderSubModalVarianContent();
};

window.tutupSubModalVarian = () => {
    const subModal = document.getElementById('modal-edit-item-varian');
    if (!subModal) return;
    subModal.classList.add('opacity-0');
    const box = subModal.querySelector('div');
    if (box) box.classList.add('scale-95');
    setTimeout(() => {
        if (subModal) subModal.remove();
        window._editingItemVarianIndex = null;
        window._editingItemVarianState = null;
    }, 250);
};

window.simpanVarianEditItem = () => {
    if (!window._editingItemVarianState) return;
    const state = window._editingItemVarianState;
    const it = window._editingOrderItems[state.itemIndex];
    if (!it) return;

    let extraVarianTotal = 0;
    const varianLabels = [];
    Object.values(state.selectedVariants || {}).forEach(v => {
        extraVarianTotal += Number(v.extraPrice || 0);
        if (v.optionName) {
            varianLabels.push(v.groupName ? `${v.groupName}: ${v.optionName}` : v.optionName);
        }
    });

    let extraToppingTotal = 0;
    const toppingNames = [];
    Object.values(state.selectedToppings || {}).forEach(t => {
        extraToppingTotal += Number(t.extraPrice || 0);
        toppingNames.push(t.toppingName);
    });

    const newUnitPrice = state.basePrice + extraVarianTotal + extraToppingTotal;
    const varianStr = varianLabels.length > 0 ? varianLabels.join(', ') : 'Standard';
    let notesStr = varianStr;
    if (toppingNames.length > 0) {
        notesStr += ` + ${toppingNames.join(', ')}`;
    }

    it.price = newUnitPrice;
    it.total = newUnitPrice * (it.qty || 1);
    it.varian = varianStr;
    it.toppings = toppingNames;
    it.notes = notesStr;

    window.tutupSubModalVarian();
    window.renderModalEditPesananContent();
};

window.simpanEditPesananMasuk = async () => {
    const orderKey = window._editingOrderKey;
    if (!orderKey) return;

    if (!window._editingOrderItems || window._editingOrderItems.length === 0) {
        // Tampilkan modal peringatan di DEPAN pop-up edit menu masuk (z-index tinggi)
        let existingWarn = document.getElementById('dialog-pesanan-kosong-warning');
        if (existingWarn) existingWarn.remove();
        const warnModal = document.createElement('div');
        warnModal.id = 'dialog-pesanan-kosong-warning';
        warnModal.className = "fixed inset-0 z-[100010] bg-slate-950/75 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in";
        warnModal.innerHTML = `
            <div class="bg-white rounded-[2rem] p-6 max-w-sm w-full shadow-2xl border border-rose-100 flex flex-col items-center text-center space-y-4 transform scale-100 transition-all">
                <div class="w-16 h-16 shrink-0 rounded-2xl bg-rose-50 text-rose-500 border border-rose-200 flex items-center justify-center text-3xl shadow-inner">
                    <i class="fa-solid fa-triangle-exclamation animate-bounce"></i>
                </div>
                <div class="space-y-1">
                    <h3 class="text-base font-black text-slate-900">Pesanan Tidak Boleh Kosong!</h3>
                    <p class="text-xs text-slate-500 leading-relaxed">
                        Item pesanan tidak boleh 0. Silakan pilih dan tambahkan minimal 1 menu dari katalog sebelum menyimpan perubahan.
                    </p>
                </div>
                <div class="w-full pt-1">
                    <button type="button" onclick="document.getElementById('dialog-pesanan-kosong-warning')?.remove(); const sel = document.getElementById('select-tambah-menu-edit'); if (sel) { sel.focus(); sel.classList.add('ring-2', 'ring-rose-500'); setTimeout(() => sel.classList.remove('ring-2', 'ring-rose-500'), 2000); }" class="w-full bg-blue-600 hover:bg-blue-700 active:scale-95 text-white font-black py-3 rounded-xl transition text-xs tracking-wider uppercase shadow-md shadow-blue-500/25">
                        <i class="fa-solid fa-plus mr-1"></i> Oke, Tambah Menu
                    </button>
                </div>
            </div>
        `;
        document.body.appendChild(warnModal);
        return;
    }

    const newItems = window._editingOrderItems;
    const subtotal = newItems.reduce((sum, it) => sum + (Number(it.total) || 0), 0);
    const diskon = Number(window._editingOrderDiskon || 0);
    const newTotal = Math.max(0, subtotal - diskon);

    let targetOrder = (globalOrders && globalOrders[orderKey]) || null;
    let actualFirebaseKey = orderKey;

    if (targetOrder) {
        targetOrder.items = newItems;
        targetOrder.subtotal = subtotal;
        targetOrder.total = newTotal;
        targetOrder.totalAmount = newTotal;
        targetOrder.updatedAt = Date.now();
        if (targetOrder.firebaseKey) actualFirebaseKey = targetOrder.firebaseKey;
    }

    // Update seluruh entri pesanan dengan ID yang sama di memori
    if (globalOrders) {
        const matchIds = [orderKey, actualFirebaseKey, targetOrder?.id, targetOrder?.orderId, targetOrder?.firebaseKey].filter(Boolean);
        Object.values(globalOrders).forEach(o => {
            if (o && (matchIds.includes(o.id) || matchIds.includes(o.orderId) || matchIds.includes(o.firebaseKey))) {
                o.items = newItems;
                o.subtotal = subtotal;
                o.total = newTotal;
                o.totalAmount = newTotal;
                o.updatedAt = Date.now();
            }
        });
    }

    // Update di localStorage offline orders
    try {
        let saved = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        saved = saved.map(o => {
            if (o.orderId === orderKey || o.id === orderKey || o.firebaseKey === orderKey ||
                (targetOrder && (o.id === targetOrder.id || o.orderId === targetOrder.orderId || o.firebaseKey === targetOrder.firebaseKey))) {
                return {
                    ...o,
                    items: newItems,
                    subtotal: subtotal,
                    total: newTotal,
                    totalAmount: newTotal,
                    updatedAt: Date.now()
                };
            }
            return o;
        });
        localStorage.setItem('mainstay_offline_orders', JSON.stringify(saved));
    } catch(e) {}

    // Update di antrean offline sync engine jika ada
    try {
        if (window.posSyncEngine && typeof window.posSyncEngine.getPendingQueue === 'function') {
            const queue = window.posSyncEngine.getPendingQueue();
            let queueChanged = false;
            const matchIds = [orderKey, actualFirebaseKey, targetOrder?.id, targetOrder?.orderId, targetOrder?.firebaseKey].filter(Boolean);
            queue.forEach(item => {
                if (item.type === 'order' && (matchIds.includes(item.id) || (item.payload && (matchIds.includes(item.payload.id) || matchIds.includes(item.payload.orderId))))) {
                    if (item.payload) {
                        item.payload.items = newItems;
                        item.payload.subtotal = subtotal;
                        item.payload.total = newTotal;
                        item.payload.totalAmount = newTotal;
                        item.payload.updatedAt = Date.now();
                    }
                    queueChanged = true;
                }
            });
            if (queueChanged) {
                window.posSyncEngine.savePendingQueue(queue);
            }
        }
    } catch(e) {}

    // Update ke Firebase Realtime Database pada nodes orders dan transaksi
    const updatePayload = {
        items: newItems,
        subtotal: subtotal,
        total: newTotal,
        totalAmount: newTotal,
        updatedAt: Date.now()
    };

    try {
        await update(ref(db, `orders/${orderKey}`), updatePayload);
        await update(ref(db, `transaksi/${orderKey}`), updatePayload);
    } catch(e) {}

    if (actualFirebaseKey && actualFirebaseKey !== orderKey) {
        try {
            await update(ref(db, `orders/${actualFirebaseKey}`), updatePayload);
            await update(ref(db, `transaksi/${actualFirebaseKey}`), updatePayload);
        } catch(e) {}
    }

    // Refresh seluruh UI
    if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
    if (typeof window.updateLiveCashDrawer === 'function') window.updateLiveCashDrawer();
    if (typeof window.updateOwnerDashboard === 'function') window.updateOwnerDashboard();

    window.tutupModalEditPesananMasuk();
    alert("Pesanan berhasil diperbarui dengan rincian varian & topping terbaru.");
};

// ==========================================
// TOAST NOTIFIKASI PESANAN BARU (KASIR)
// ==========================================
window.tampilkanToastPesananBaru = (orderData, force = false) => {
    if (!orderData) return;

    const customer = orderData.nama_pelanggan || orderData.customerName || 'Pelanggan';
    const amount = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(orderData.total || orderData.totalAmount || 0);
    const antrean = orderData.nomor_antrean || orderData.orderId || '-';
    const codeStr = String(antrean || orderData.orderId || orderData.id || '').toUpperCase();

    // Pencegahan mutlak notifikasi ganda / duplicate toast jika bukan force
    window._notifiedToastOrderIds = window._notifiedToastOrderIds || new Set();
    if (!force && codeStr && window._notifiedToastOrderIds.has(codeStr)) {
        return;
    }
    if (codeStr) {
        window._notifiedToastOrderIds.add(codeStr);
        window._notifiedOrderIds = window._notifiedOrderIds || new Set();
        window._notifiedOrderIds.add(codeStr);
    }

    // Mainkan suara notifikasi tunggal ter-debounce
    if (typeof window.playOrderNotificationSound === 'function') {
        window.playOrderNotificationSound();
    }

    // Buat container toast jika belum ada
    let toastContainer = document.getElementById('toast-container');
    if (!toastContainer) {
        toastContainer = document.createElement('div');
        toastContainer.id = 'toast-container';
        toastContainer.className = 'fixed top-4 right-4 z-[999999] flex flex-col gap-2 pointer-events-none';
        document.body.appendChild(toastContainer);
    }

    let toastBorder = 'border-l-4 border-slate-700';
    let toastIconBg = 'bg-slate-100 text-slate-700';
    let channelBadge = '<span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-slate-700 text-white">Lainnya</span>';

    const tipeStr = String(orderData.tipePesanan || orderData.channel || orderData.source || '').toLowerCase();
    const custStr = String(customer || '').toLowerCase();

    if (codeStr.startsWith('GRB') || codeStr.includes('GRAB') || tipeStr.includes('grab') || custStr.includes('grab')) {
        toastBorder = 'border-l-4 border-[#064e3b]';
        toastIconBg = 'bg-emerald-100 text-[#064e3b]';
        channelBadge = '<span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-[#064e3b] text-white"><i class="fa-solid fa-motorcycle mr-1 text-emerald-300"></i>GrabFood</span>';
    } else if (codeStr.startsWith('GFD') || codeStr.includes('GOFOOD') || codeStr.includes('GOJEK') || tipeStr.includes('go') || custStr.includes('gofood')) {
        toastBorder = 'border-l-4 border-[#22c55e]';
        toastIconBg = 'bg-green-100 text-green-700';
        channelBadge = '<span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-[#22c55e] text-slate-950 font-black"><i class="fa-solid fa-motorcycle mr-1"></i>GoFood</span>';
    } else if (codeStr.startsWith('SHP') || codeStr.includes('SHOPEE') || tipeStr.includes('shopee') || custStr.includes('shopee')) {
        toastBorder = 'border-l-4 border-[#f97316]';
        toastIconBg = 'bg-orange-100 text-[#f97316]';
        channelBadge = '<span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-[#f97316] text-white"><i class="fa-solid fa-bag-shopping mr-1 text-orange-200"></i>Shopee</span>';
    } else if (codeStr.startsWith('KSR') || tipeStr.includes('kasir') || tipeStr.includes('biasa')) {
        toastBorder = 'border-l-4 border-blue-600';
        toastIconBg = 'bg-blue-100 text-blue-700';
        channelBadge = '<span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-blue-600 text-white">Kasir POS</span>';
    } else if (codeStr.startsWith('CSH') || tipeStr.includes('self') || tipeStr.includes('csh')) {
        toastBorder = 'border-l-4 border-purple-600';
        toastIconBg = 'bg-purple-100 text-purple-700';
        channelBadge = '<span class="text-[9px] font-black px-1.5 py-0.5 rounded bg-purple-600 text-white">Self-Order</span>';
    }

    // Buat elemen toast
    const toast = document.createElement('div');
    toast.className = `bg-white rounded-xl shadow-2xl ${toastBorder} p-3.5 flex items-center gap-3 w-80 transform translate-x-full transition-all duration-500 pointer-events-auto`;
    
    toast.innerHTML = `
        <div class="w-10 h-10 ${toastIconBg} rounded-full flex items-center justify-center shrink-0">
            <i class="fa-solid fa-bell animate-bounce"></i>
        </div>
        <div class="flex-1 min-w-0">
            <div class="flex items-center gap-1.5 mb-0.5">
                ${channelBadge}
                <h4 class="text-xs font-black text-slate-800 truncate">Pesanan Masuk!</h4>
            </div>
            <p class="text-[10px] text-slate-500 font-bold truncate">#${codeStr} • ${customer}</p>
        </div>
        <div class="text-right shrink-0">
            <p class="text-[10px] font-black text-slate-800">${amount}</p>
        </div>
    `;

    toastContainer.appendChild(toast);

    // Animasi masuk (slide in & pulse)
    setTimeout(() => {
        toast.classList.remove('translate-x-full');
        toast.classList.add('translate-x-0', 'animate-pulse');
    }, 10);

    // Hapus toast otomatis setelah 4 detik
    setTimeout(() => {
        toast.classList.remove('translate-x-0', 'animate-pulse');
        toast.classList.add('translate-x-full');
        setTimeout(() => {
            toast.remove();
        }, 500);
    }, 4000);
};

window.updateLiveCashDrawer = () => {
    const ringkasan = typeof window.hitungRingkasanLaciHariIni === 'function'
        ? window.hitungRingkasanLaciHariIni()
        : { totalOmzet: 0, cashSales: 0, notaCount: 0, expectedCash: 0 };

    const omzetEl = document.getElementById('kasir-omzet-total');
    const drawerEl = document.getElementById('kasir-drawer-target');
    const completedEl = document.getElementById('kasir-completed-count');

    if (omzetEl) omzetEl.innerText = formatRupiah(ringkasan.totalOmzet);
    if (drawerEl) drawerEl.innerText = formatRupiah(ringkasan.expectedCash);
    if (completedEl) completedEl.innerText = `${ringkasan.notaCount} Order`;

    // Perbarui indikator visual shift (Hijau = Aktif, Merah = Tutup)
    const indShift = document.getElementById('indikator-shift-kasir');
    if (indShift) {
        const isClosed = typeof window.cekTokoSudahTutupRekapHariIni === 'function' && window.cekTokoSudahTutupRekapHariIni();
        if (isClosed) {
            indShift.className = 'w-2.5 h-2.5 rounded-full bg-rose-500 ring-2 ring-rose-200 shadow-xs';
            indShift.title = 'Shift Ditutup (Merah)';
        } else {
            indShift.className = 'w-2.5 h-2.5 rounded-full bg-emerald-500 ring-2 ring-emerald-200 shadow-xs animate-pulse';
            indShift.title = 'Shift Aktif (Hijau)';
        }
    }

    // Perbarui Progres Target Omzet Harian & Tingkatan Bonus Staff di Dashboard Kasir (TANPA modal/HPP/profit owner)
    const s = window.storeSettings || JSON.parse(localStorage.getItem('mainstay_store_settings') || '{}');
    const activeBid = window.ACTIVE_BRANCH_ID || 'pusat';
    const kasirTargetSummary = typeof window.computeKasirSafeBranchTarget === 'function'
        ? window.computeKasirSafeBranchTarget(activeBid)
        : null;

    let targetHarian = Number(kasirTargetSummary?.targetHarian || s.target_omzet_harian || 0);
    if (!targetHarian && typeof globalMasterOwner === 'object' && globalMasterOwner) {
        const ownerWithTarget = Object.values(globalMasterOwner).find(o => Number(o?.target || 0) > 0);
        if (ownerWithTarget) targetHarian = Number(ownerWithTarget.target || 0);
    }

    const milestonesData = kasirTargetSummary || (s.target_milestones && typeof s.target_milestones === 'object' ? s.target_milestones : null);
    const tahap1 = Number(milestonesData?.tahap1Bep || 0);
    const tahap2 = Number(milestonesData?.tahap2Toko || targetHarian || 0);
    const tahap3 = Number(milestonesData?.tahap3Bonus || 0);
    const bonusNominal = Number(milestonesData?.bonusNominal || 0);

    const rawTiers = Array.isArray(milestonesData?.bonusTiers) && milestonesData.bonusTiers.length > 0
        ? milestonesData.bonusTiers
        : (typeof window.normalizeBonusTiers === 'function'
            ? window.normalizeBonusTiers([], tahap2 || targetHarian, bonusNominal, tahap3)
            : []);
    const bonusTiers = Array.isArray(rawTiers)
        ? [...rawTiers].filter(t => Number(t?.minOmzet || 0) > 0).sort((a, b) => Number(a.minOmzet) - Number(b.minOmzet))
        : [];

    if (!targetHarian && bonusTiers.length > 0) {
        targetHarian = Number(bonusTiers[0].minOmzet || 0);
    }

    const elTargetNom = document.getElementById('kasir-target-omzet-nominal');
    const elTargetPct = document.getElementById('kasir-target-omzet-pct');
    const elTargetBar = document.getElementById('kasir-target-omzet-bar');
    const elTargetSisa = document.getElementById('kasir-target-omzet-sisa');
    const elBonusBanner = document.getElementById('kasir-staff-bonus-banner');
    const elMilestones = document.getElementById('kasir-target-milestones');

    if (elTargetNom && elTargetPct && elTargetBar && elTargetSisa) {
        const currentOmzet = Number(ringkasan.totalOmzet || 0);
        const hasAnyTarget = targetHarian > 0 || bonusTiers.length > 0;

        if (elMilestones) {
            elMilestones.classList.add('hidden');
            elMilestones.innerHTML = '';
        }

        if (hasAnyTarget) {
            if (bonusTiers.length > 0) {
                const reachedTiers = bonusTiers.filter(t => currentOmzet >= Number(t.minOmzet || 0));
                const activeReachedTier = reachedTiers.length > 0 ? reachedTiers[reachedTiers.length - 1] : null;
                const nextTier = bonusTiers.find(t => currentOmzet < Number(t.minOmzet || 0)) || null;
                const highestTier = bonusTiers[bonusTiers.length - 1];
                const earnedBonus = activeReachedTier ? Number(activeReachedTier.bonusStaff || 0) : 0;

                const activeBarTarget = Number(nextTier ? nextTier.minOmzet : (highestTier?.minOmzet || targetHarian || 0));
                const rawPct = activeBarTarget > 0 ? Math.round((currentOmzet / activeBarTarget) * 100) : 0;
                const barPct = Math.min(100, Math.max(0, rawPct));
                const sisaKeNext = Math.max(0, activeBarTarget - currentOmzet);

                elTargetNom.innerText = formatRupiah(activeBarTarget);
                elTargetPct.innerText = `${rawPct}%`;
                elTargetBar.style.width = `${barPct}%`;

                if (!nextTier && activeReachedTier) {
                    elTargetPct.className = 'font-black text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200 tabular-nums shrink-0';
                    elTargetBar.className = 'h-full bg-gradient-to-r from-emerald-500 to-teal-500 rounded-full transition-all duration-500';
                    elTargetSisa.innerText = `Target maksimal tercapai (${activeReachedTier.label})`;
                    elTargetSisa.className = 'text-[10px] font-bold text-emerald-700 leading-snug';
                } else if (activeReachedTier) {
                    elTargetPct.className = 'font-black text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200 tabular-nums shrink-0';
                    elTargetBar.className = 'h-full bg-gradient-to-r from-emerald-500 to-teal-500 rounded-full transition-all duration-500';
                    elTargetSisa.innerText = `${activeReachedTier.label} tercapai • Kurang ${formatRupiah(sisaKeNext)} ke ${nextTier.label}`;
                    elTargetSisa.className = 'text-[10px] font-bold text-emerald-700 leading-snug';
                } else {
                    elTargetPct.className = 'font-black text-amber-700 bg-amber-50 px-2 py-0.5 rounded-md border border-amber-200 tabular-nums shrink-0';
                    elTargetBar.className = 'h-full bg-gradient-to-r from-amber-400 to-orange-500 rounded-full transition-all duration-500';
                    elTargetSisa.innerText = `Kurang ${formatRupiah(sisaKeNext)} untuk ${nextTier.label}`;
                    elTargetSisa.className = 'text-[10px] font-bold text-slate-500 leading-snug';
                }

                if (elBonusBanner) {
                    if (earnedBonus > 0) {
                        elBonusBanner.classList.remove('hidden');
                        elBonusBanner.className = 'rounded-lg border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 flex items-center justify-between gap-2 text-[11px]';
                        elBonusBanner.innerHTML = `
                            <span class="font-bold text-emerald-900 truncate"><i class="fa-solid fa-circle-check text-emerald-600 mr-1"></i>Bonus Staff (${activeReachedTier.label})</span>
                            <span class="font-black text-emerald-700 tabular-nums shrink-0">+${formatRupiah(earnedBonus)}</span>
                        `;
                    } else if (Number(bonusTiers[0]?.bonusStaff || 0) > 0) {
                        const firstTarget = bonusTiers[0];
                        elBonusBanner.classList.remove('hidden');
                        elBonusBanner.className = 'rounded-lg border border-slate-200 bg-slate-50 px-2.5 py-1.5 flex items-center justify-between gap-2 text-[11px]';
                        elBonusBanner.innerHTML = `
                            <span class="font-semibold text-slate-600 truncate">Bonus ${firstTarget.label} (${formatRupiah(firstTarget.minOmzet)})</span>
                            <span class="font-black text-amber-700 tabular-nums shrink-0">+${formatRupiah(firstTarget.bonusStaff)}</span>
                        `;
                    } else {
                        elBonusBanner.classList.add('hidden');
                        elBonusBanner.innerHTML = '';
                    }
                }
            } else {
                const rawPct = Math.round((currentOmzet / targetHarian) * 100);
                const barPct = Math.min(100, Math.max(0, rawPct));
                const sisa = Math.max(0, targetHarian - currentOmzet);

                elTargetNom.innerText = formatRupiah(targetHarian);
                elTargetPct.innerText = `${rawPct}%`;
                elTargetBar.style.width = `${barPct}%`;

                if (tahap3 > 0 && currentOmzet >= tahap3) {
                    elTargetPct.className = 'font-black text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200 tabular-nums shrink-0';
                    elTargetBar.className = 'h-full bg-gradient-to-r from-emerald-500 to-teal-500 rounded-full transition-all duration-500';
                    elTargetSisa.innerText = `Target tercapai (+${formatRupiah(currentOmzet - tahap3)})`;
                    elTargetSisa.className = 'text-[10px] font-bold text-emerald-700 leading-snug';
                } else if (rawPct >= 100) {
                    elTargetPct.className = 'font-black text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200 tabular-nums shrink-0';
                    elTargetBar.className = 'h-full bg-gradient-to-r from-emerald-500 to-teal-500 rounded-full transition-all duration-500';
                    elTargetSisa.innerText = tahap3 > targetHarian
                        ? `Target tercapai • Kejar +${formatRupiah(tahap3 - currentOmzet)} lagi untuk bonus`
                        : `Target omzet hari ini tercapai (+${formatRupiah(currentOmzet - targetHarian)})`;
                    elTargetSisa.className = 'text-[10px] font-bold text-emerald-700 leading-snug';
                } else {
                    elTargetPct.className = 'font-black text-amber-700 bg-amber-50 px-2 py-0.5 rounded-md border border-amber-200 tabular-nums shrink-0';
                    elTargetBar.className = 'h-full bg-gradient-to-r from-amber-400 to-orange-500 rounded-full transition-all duration-500';
                    elTargetSisa.innerText = `Kurang ${formatRupiah(sisa)} lagi untuk mencapai target`;
                    elTargetSisa.className = 'text-[10px] font-bold text-slate-500 leading-snug';
                }

                if (elBonusBanner) {
                    if (bonusNominal > 0) {
                        const hitBonus = tahap3 > 0 ? currentOmzet >= tahap3 : currentOmzet >= targetHarian;
                        elBonusBanner.classList.remove('hidden');
                        elBonusBanner.className = hitBonus
                            ? 'rounded-lg border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 flex items-center justify-between gap-2 text-[11px]'
                            : 'rounded-lg border border-slate-200 bg-slate-50 px-2.5 py-1.5 flex items-center justify-between gap-2 text-[11px]';
                        elBonusBanner.innerHTML = `
                            <span class="${hitBonus ? 'font-bold text-emerald-900' : 'font-semibold text-slate-600'} truncate">${hitBonus ? '<i class="fa-solid fa-circle-check text-emerald-600 mr-1"></i>Bonus Staff Tercapai' : 'Bonus Staff Jika Tercapai'}</span>
                            <span class="font-black ${hitBonus ? 'text-emerald-700' : 'text-amber-700'} tabular-nums shrink-0">+${formatRupiah(bonusNominal)}</span>
                        `;
                    } else {
                        elBonusBanner.classList.add('hidden');
                        elBonusBanner.innerHTML = '';
                    }
                }
            }
        } else {
            elTargetNom.innerText = 'Belum diatur';
            elTargetPct.innerText = '-';
            elTargetBar.style.width = '0%';
            elTargetSisa.innerText = 'Atur target omzet harian di Panel Master Owner';
            elTargetSisa.className = 'text-[10px] font-bold text-slate-400 leading-snug';
            if (elBonusBanner) {
                elBonusBanner.classList.add('hidden');
                elBonusBanner.innerHTML = '';
            }
        }
    }
};

