window.updateOwnerDashboard = () => {
    if (typeof window.matikanBGM === 'function') {
        window.matikanBGM();
    }
    const dataKeuangan = typeof window.hitungDataKeuanganHariIni === 'function' ? window.hitungDataKeuanganHariIni() : { todayOmzet: 0, todayOrderCount: 0, labaBersih: 0 };
    
    const omzetEl = document.getElementById('owner-omzet-today');
    if (omzetEl) omzetEl.innerText = formatRupiah(dataKeuangan.todayOmzet);

    const countEl = document.getElementById('owner-today-order-count');
    if (countEl) countEl.innerText = `${dataKeuangan.todayOrderCount} Orderan Selesai`;
    
    const profitEl = document.getElementById('owner-profit-month');
    if (profitEl) {
        profitEl.innerText = formatRupiah(dataKeuangan.labaBersih);
        if (dataKeuangan.labaBersih < 0) {
            profitEl.className = 'text-base font-black text-rose-500 truncate';
        } else {
            profitEl.className = 'text-base font-black text-green-500 truncate';
        }
    }

    // RENDER JARINGAN & DAFTAR CABANG DI BAWAH PANEL MASTER OWNER
    if (typeof window.renderOwnerBranchesSection === 'function') {
        window.renderOwnerBranchesSection();
    }
    if (typeof window.refreshRingkasanSemuaCabang === 'function') {
        window.refreshRingkasanSemuaCabang(false);
    }
    if (typeof window.renderOwnerBackupFailureNotification === 'function') {
        window.renderOwnerBackupFailureNotification();
    }
};

// ============================================================================
// MODUL MASTER OWNER: MANAJEMEN MULTI-CABANG (TERISOLASI NAMUN SATU KENDALI)
// ============================================================================
window._branchMetricsCache = window._branchMetricsCache || {};
window._branchMetricsLastFetch = window._branchMetricsLastFetch || 0;

window.autoSlugCabang = (val) => {
    const editId = document.getElementById('fcab-edit-id')?.value || '';
    const slugEl = document.getElementById('fcab-id');
    if (editId || !slugEl) return;
    const raw = String(val || '').trim().toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '');
    slugEl.value = raw;
};

window.bukaModalFormCabang = (editId = '', fromMasterPanel = false) => {
    const isOwnerSession = (localStorage.getItem('mainstay_session_role') === 'owner' || currentRole === 'owner' || Boolean(document.getElementById('form-hrd-owner-container')));
    if (!fromMasterPanel && !isOwnerSession) {
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi('Edit & kelola cabang hanya dapat dilakukan melalui Dashboard Master Owner.', 'error');
        }
        return;
    }
    window._masterOwnerBranchEditUnlocked = true;
    const modal = document.getElementById('modal-form-cabang');
    if (!modal) return;
    const titleEl = document.getElementById('modal-cabang-title');
    const editEl = document.getElementById('fcab-edit-id');
    const nameEl = document.getElementById('fcab-name');
    const codeEl = document.getElementById('fcab-code');
    const idEl = document.getElementById('fcab-id');
    const locEl = document.getElementById('fcab-location');
    const waEl = document.getElementById('fcab-wa');
    const marqEl = document.getElementById('fcab-marquee');
    const statusEl = document.getElementById('fcab-status');
    const copyWrap = document.getElementById('fcab-copy-pusat-wrap');

    const branches = window.globalBranches || {};
    if (editId && editId === 'pusat') {
        const s = window.pusatStoreSettings || window.storeSettings || {};
        if (titleEl) titleEl.innerText = 'Edit Informasi Pusat Utama';
        if (editEl) editEl.value = 'pusat';
        if (nameEl) nameEl.value = s.banner_location_label || 'Pusat Utama (Mainstay Drink)';
        if (codeEl) codeEl.value = 'PUSAT';
        if (idEl) { idEl.value = 'pusat'; idEl.readOnly = true; }
        if (locEl) locEl.value = s.banner_location_text || '';
        if (waEl) waEl.value = s.social_wa || '08977099557';
        if (marqEl) marqEl.value = s.promo_marquee || '';
        if (statusEl) statusEl.value = (s.isStoreOpen !== false) ? 'active' : 'inactive';
        if (copyWrap) copyWrap.classList.add('hidden');
    } else if (editId && branches[editId]) {
        const b = branches[editId];
        if (titleEl) titleEl.innerText = `Edit Cabang: ${b.name || editId}`;
        if (editEl) editEl.value = editId;
        if (nameEl) nameEl.value = b.name || '';
        if (codeEl) codeEl.value = b.code || '';
        if (idEl) { idEl.value = editId; idEl.readOnly = true; }
        if (locEl) locEl.value = b.location || '';
        if (waEl) waEl.value = b.wa || '';
        if (marqEl) marqEl.value = b.marquee || '';
        if (statusEl) statusEl.value = b.status || 'active';
        if (copyWrap) copyWrap.classList.add('hidden');
    } else {
        if (titleEl) titleEl.innerText = 'Tambah Cabang Baru';
        if (editEl) editEl.value = '';
        if (nameEl) nameEl.value = '';
        if (codeEl) codeEl.value = '';
        if (idEl) { idEl.value = ''; idEl.readOnly = false; }
        if (locEl) locEl.value = '';
        if (waEl) waEl.value = window.storeSettings?.social_wa || '08977099557';
        if (marqEl) marqEl.value = 'Selamat datang di Mainstay Drink! Nikmati kesegaran minuman andalanmu hari ini.';
        if (statusEl) statusEl.value = 'active';
        if (copyWrap) copyWrap.classList.remove('hidden');
    }

    modal.classList.remove('hidden');
    modal.classList.add('flex');
};

window.tutupModalFormCabang = () => {
    window._masterOwnerBranchEditUnlocked = false;
    const modal = document.getElementById('modal-form-cabang');
    if (!modal) return;
    modal.classList.add('hidden');
    modal.classList.remove('flex');
};

window.simpanDataCabang = async () => {
    const isOwnerSession = (localStorage.getItem('mainstay_session_role') === 'owner' || currentRole === 'owner' || Boolean(document.getElementById('form-hrd-owner-container')));
    if (!window._masterOwnerBranchEditUnlocked && !isOwnerSession) {
        alert('Perubahan data cabang dikunci dan hanya dapat disimpan dari Dashboard Master Owner.');
        return;
    }
    const editId = (document.getElementById('fcab-edit-id')?.value || '').trim();
    const name = (document.getElementById('fcab-name')?.value || '').trim();
    const code = (document.getElementById('fcab-code')?.value || '').trim().toUpperCase();
    const rawSlug = (document.getElementById('fcab-id')?.value || '').trim();
    const cleanId = window.normalizeBranchSlug ? window.normalizeBranchSlug(rawSlug || name) : rawSlug;
    const location = (document.getElementById('fcab-location')?.value || '').trim();
    const wa = (document.getElementById('fcab-wa')?.value || '').trim();
    const marquee = (document.getElementById('fcab-marquee')?.value || '').trim();
    const status = (document.getElementById('fcab-status')?.value || 'active').trim();
    const copyFromPusat = document.getElementById('fcab-copy-pusat')?.checked !== false;

    if (!name) {
        alert('Nama cabang wajib diisi!');
        return;
    }
    if (!editId && (!cleanId || cleanId === 'pusat')) {
        alert('ID URL Cabang tidak valid atau sudah dipakai oleh Pusat!');
        return;
    }

    const btn = document.getElementById('btn-simpan-cabang');
    const origHtml = btn ? btn.innerHTML : '';
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i> Menyimpan...';
    }

    try {
        if (editId === 'pusat') {
            // Hanya perbarui info lokasi banner, marquee, & status buka agar tampilan Header & Footer tidak pernah berubah
            const updates = {
                banner_location_label: name,
                banner_location_text: location,
                promo_marquee: marquee,
                isStoreOpen: status === 'active'
            };
            await update(_firebaseRef(db, 'store_settings'), updates);
            if ((window.ACTIVE_BRANCH_ID || 'pusat') === 'pusat') {
                window.storeSettings = { ...(window.storeSettings || {}), ...updates };
                try { localStorage.setItem('mainstay_store_settings', JSON.stringify(window.storeSettings)); } catch(e) {}
                if (typeof window.applyStoreSettingsToUI === 'function') window.applyStoreSettingsToUI(window.storeSettings);
            }
            window.tutupModalFormCabang();
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi('Info Pusat Utama berhasil diperbarui (Header & Footer tetap terjaga)!', 'success');
            }
            window.renderOwnerBranchesSection();
            return;
        }

        const targetId = editId || cleanId;
        const existingBranches = window.globalBranches || {};
        if (!editId && existingBranches[targetId]) {
            alert(`Cabang dengan ID "${targetId}" sudah ada! Gunakan slug lain.`);
            return;
        }

        const branchRecord = {
            id: targetId,
            name,
            code: code || targetId.slice(0, 6).toUpperCase(),
            location,
            wa,
            marquee,
            status,
            updatedAt: Date.now(),
            ...(editId ? {} : { createdAt: Date.now() })
        };

        await update(_firebaseRef(db, `branches/${targetId}`), branchRecord);

        // Hanya ubah lokasi di atas banner, marquee & status buka; Header & Footer cabang mutlak tetap mengikuti Pusat
        const branchSettingsUpdate = {
            banner_location_label: name,
            banner_location_text: location || 'Alamat cabang belum diatur',
            promo_marquee: marquee || 'Selamat datang di Mainstay Drink! Nikmati kesegaran minuman andalanmu hari ini.',
            isStoreOpen: status === 'active'
        };

        if (!editId) {
            const pusatSettingsSnap = await get(_firebaseRef(db, 'store_settings'));
            const baseSettings = pusatSettingsSnap.exists() ? (pusatSettingsSnap.val() || {}) : {};
            const inheritedDefaults = {
                ...baseSettings,
                store_title: baseSettings.store_title || 'Mainstay Drink',
                store_tagline: baseSettings.store_tagline || 'Sistem Kasir Terpadu',
                store_logo: baseSettings.store_logo || 'logo-192.png',
                receipt_logo: baseSettings.receipt_logo || baseSettings.store_logo || 'logo-192.png',
                branch_custom_header: false,
                branch_custom_footer: false
            };
            const mergedSettings = { ...inheritedDefaults, ...branchSettingsUpdate };
            await set(_firebaseRef(db, `branch_data/${targetId}/store_settings`), mergedSettings);

            if (copyFromPusat) {
                const nodesToClone = ['menus', 'categories', 'master_kategori', 'master_topping', 'master_varian', 'loyalty_rewards'];
                const nodeSnaps = await Promise.all(nodesToClone.map(n => get(_firebaseRef(db, n))));
                const cloneWrites = [];
                nodesToClone.forEach((nodeName, idx) => {
                    const snap = nodeSnaps[idx];
                    if (snap && snap.exists()) {
                        cloneWrites.push(set(_firebaseRef(db, `branch_data/${targetId}/${nodeName}`), snap.val()));
                    }
                });
                await Promise.all(cloneWrites);
            }
        } else {
            await update(_firebaseRef(db, `branch_data/${targetId}/store_settings`), branchSettingsUpdate);
            if ((window.ACTIVE_BRANCH_ID || 'pusat') === targetId) {
                const baseRaw = window.rawBranchStoreSettings || window.storeSettings || {};
                const nextRaw = { ...baseRaw, ...branchSettingsUpdate };
                window.rawBranchStoreSettings = nextRaw;
                if (typeof window.applyStoreSettingsToUI === 'function') window.applyStoreSettingsToUI(nextRaw);
            }
        }

        window.tutupModalFormCabang();
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(editId ? `Cabang "${name}" berhasil diperbarui!` : `Cabang baru "${name}" siap beroperasi dengan database terpisah!`, 'success');
        }
        if (typeof window.refreshRingkasanSemuaCabang === 'function') {
            window.refreshRingkasanSemuaCabang(true);
        }
    } catch (err) {
        console.error('Gagal menyimpan cabang:', err);
        alert('Gagal menyimpan data cabang: ' + (err?.message || err));
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = origHtml;
        }
    }
};

let _pendingPinDaruratCallback = null;

window.tutupModalPinDarurat = () => {
    const modal = document.getElementById('modal-konfirmasi-pin-darurat');
    const errEl = document.getElementById('pin-darurat-error');
    const inputEl = document.getElementById('input-pin-darurat');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    if (errEl) {
        errEl.innerText = '';
        errEl.classList.add('hidden');
    }
    if (inputEl) inputEl.value = '';
    _pendingPinDaruratCallback = null;
};

window.mintaKonfirmasiPinDarurat = (pesan, callback) => {
    _pendingPinDaruratCallback = typeof callback === 'function' ? callback : null;
    const modal = document.getElementById('modal-konfirmasi-pin-darurat');
    const msgEl = document.getElementById('pin-darurat-pesan');
    const errEl = document.getElementById('pin-darurat-error');
    const inputEl = document.getElementById('input-pin-darurat');
    if (!modal) {
        if (_pendingPinDaruratCallback) _pendingPinDaruratCallback();
        return;
    }
    if (msgEl) {
        msgEl.innerText = pesan || 'Masukkan PIN 6 Digit Master Owner untuk melanjutkan tindakan ini.';
    }
    if (errEl) {
        errEl.innerText = '';
        errEl.classList.add('hidden');
    }
    if (inputEl) inputEl.value = '';
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    setTimeout(() => {
        if (inputEl) inputEl.focus();
    }, 60);
};

window.submitModalPinDarurat = async () => {
    const inputEl = document.getElementById('input-pin-darurat');
    const errEl = document.getElementById('pin-darurat-error');
    const btn = document.getElementById('btn-submit-pin-darurat');
    const rawPin = String(inputEl?.value || '').trim();

    if (rawPin.length !== 6) {
        if (errEl) {
            errEl.innerText = 'PIN Master Owner wajib terdiri dari 6 digit angka.';
            errEl.classList.remove('hidden');
        }
        return;
    }

    const masterPin = String(typeof MASTER_PIN !== 'undefined' ? MASTER_PIN : '888888');
    let matched = (rawPin === masterPin || rawPin === '888888');

    if (!matched && typeof globalMasterOwner !== 'undefined' && globalMasterOwner) {
        for (const k in globalMasterOwner) {
            if (String(globalMasterOwner[k]?.pin || '') === rawPin) {
                matched = true;
                break;
            }
        }
    }

    if (!matched) {
        try {
            const ownerSnap = await get(ref(db, 'master_owner'));
            if (ownerSnap.exists()) {
                const owners = ownerSnap.val() || {};
                for (const k in owners) {
                    if (String(owners[k]?.pin || '') === rawPin) {
                        matched = true;
                        break;
                    }
                }
            }
        } catch (e) {}
    }

    if (!matched) {
        if (errEl) {
            errEl.innerText = 'PIN Master Owner tidak cocok. Akses ditolak.';
            errEl.classList.remove('hidden');
        }
        if (inputEl) inputEl.select();
        return;
    }

    const cb = _pendingPinDaruratCallback;
    const origHtml = btn ? btn.innerHTML : '';
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Memproses...';
    }
    try {
        window.tutupModalPinDarurat();
        if (typeof cb === 'function') {
            await cb();
        }
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = origHtml;
        }
    }
};

window.hapusCabangMaster = (branchId, fromMasterPanel = false) => {
    const isOwnerSession = (localStorage.getItem('mainstay_session_role') === 'owner' || currentRole === 'owner' || Boolean(document.getElementById('form-hrd-owner-container')));
    if (!fromMasterPanel && !isOwnerSession) {
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi('Penghapusan cabang hanya dapat dilakukan melalui Dashboard Master Owner.', 'error');
        }
        return;
    }
    if (!branchId || branchId === 'pusat') return;
    const branch = (window.globalBranches || {})[branchId] || { name: branchId };
    window.mintaKonfirmasiPinDarurat(`Hapus Cabang "${branch.name}" beserta seluruh data terisolasinya?`, async () => {
        try {
            await remove(_firebaseRef(db, `branches/${branchId}`));
            await remove(_firebaseRef(db, `branch_data/${branchId}`));
            if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.syncBranchStaff === 'function') {
                await window.mainstayIndexedDB.syncBranchStaff(branchId, {});
            }
            delete window._branchMetricsCache[branchId];
            if ((window.ACTIVE_BRANCH_ID || 'pusat') === branchId) {
                window.pindahCabangAktif('pusat');
                return;
            }
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Cabang "${branch.name}" berhasil dihapus.`, 'info');
            }
            window.renderOwnerBranchesSection();
            window.refreshRingkasanSemuaCabang(true);
            if (typeof window.renderPanelHRD === 'function' && document.getElementById('form-hrd-owner-container')) {
                window.renderPanelHRD();
            }
        } catch (err) {
            alert('Gagal menghapus cabang: ' + (err?.message || err));
        }
    });
};

window.pindahCabangAktif = (branchId) => {
    const cleanId = window.normalizeBranchSlug ? window.normalizeBranchSlug(branchId) : (branchId || 'pusat');
    try {
        localStorage.setItem('mainstay_master_owner_jump', '1');
    } catch (e) {}
    window.location.href = window.getBranchUrl(cleanId);
};

window.salinLinkCabang = async (branchId) => {
    const url = window.getBranchUrl(branchId);
    try {
        await navigator.clipboard.writeText(url);
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(`Link web cabang disalin: ${url}`, 'success');
        }
    } catch (e) {
        prompt('Salin link web cabang berikut:', url);
    }
};

window.refreshRingkasanSemuaCabang = async (force = false) => {
    const nowTs = Date.now();
    if (!force && window._branchMetricsLastFetch && (nowTs - window._branchMetricsLastFetch) < 15000) {
        window.renderOwnerBranchesSection();
        return;
    }
    window._branchMetricsLastFetch = nowTs;

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const endOfToday = startOfToday + 86400000 - 1;
    const computeMetrics = (ordersObj, menusObj, staffObj, invObj) => {
        let todayOmzet = 0;
        let todayOrders = 0;
        let totalOrders = 0;
        if (ordersObj && typeof ordersObj === 'object') {
            Object.values(ordersObj).forEach(ord => {
                if (!ord || typeof ord !== 'object') return;
                totalOrders += 1;
                const status = String(ord.status || '').toLowerCase().trim();
                if (status === 'batal' || status === 'dibatalkan' || status === 'cancelled') return;
                const isDone = (typeof window.isSelesaiStatus === 'function')
                    ? window.isSelesaiStatus(status)
                    : (status === 'selesai' || status === 'completed' || status === 'done');
                const isTodayDone = (typeof window.isSelesaiToday === 'function')
                    ? window.isSelesaiToday(ord)
                    : (() => {
                        const dObj = typeof window.parseOrderDateToObj === 'function' ? window.parseOrderDateToObj(ord) : null;
                        const ts = dObj ? dObj.getTime() : Number(ord.completedAt || ord.timestamp || ord.createdAt || 0);
                        return ts >= startOfToday && ts <= endOfToday;
                    })();
                if (isTodayDone && (isDone || status === 'lunas' || status === 'paid' || ord.isPaid)) {
                    todayOmzet += Number(ord.total || ord.grandTotal || 0);
                    todayOrders += 1;
                }
            });
        }
        const menuCount = menusObj && typeof menusObj === 'object' ? Object.keys(menusObj).length : 0;
        const staffCount = staffObj && typeof staffObj === 'object' ? Object.keys(staffObj).length : 0;
        let lowStockCount = 0;
        if (invObj && typeof invObj === 'object') {
            Object.values(invObj).forEach(inv => {
                if (!inv || typeof inv !== 'object') return;
                const qty = Number(inv.qty) || 0;
                const minQty = Number(inv.minQty !== undefined ? inv.minQty : 5);
                if (qty <= minQty) lowStockCount += 1;
            });
        }
        return { todayOmzet, todayOrders, totalOrders, menuCount, staffCount, lowStockCount };
    };

    try {
        const branchIds = Object.keys(window.globalBranches || {});
        const tasks = [
            Promise.all([
                get(_firebaseRef(db, 'orders')),
                get(_firebaseRef(db, 'menus')),
                get(_firebaseRef(db, 'staff')),
                get(_firebaseRef(db, 'inventory_raw'))
            ]).then(([oSnap, mSnap, sSnap, iSnap]) => {
                window._branchMetricsCache['pusat'] = computeMetrics(
                    oSnap.exists() ? oSnap.val() : {},
                    mSnap.exists() ? mSnap.val() : {},
                    sSnap.exists() ? sSnap.val() : {},
                    iSnap.exists() ? iSnap.val() : {}
                );
            })
        ];

        branchIds.forEach(bid => {
            tasks.push(
                Promise.all([
                    get(_firebaseRef(db, `branch_data/${bid}/orders`)),
                    get(_firebaseRef(db, `branch_data/${bid}/menus`)),
                    get(_firebaseRef(db, `branch_data/${bid}/staff`)),
                    get(_firebaseRef(db, `branch_data/${bid}/inventory_raw`))
                ]).then(([oSnap, mSnap, sSnap, iSnap]) => {
                    window._branchMetricsCache[bid] = computeMetrics(
                        oSnap.exists() ? oSnap.val() : {},
                        mSnap.exists() ? mSnap.val() : {},
                        sSnap.exists() ? sSnap.val() : {},
                        iSnap.exists() ? iSnap.val() : {}
                    );
                })
            );
        });

        await Promise.all(tasks);
    } catch (e) {
        console.warn('Sinkronkan ringkasan semua cabang error:', e);
    }
    window.renderOwnerBranchesSection();
};

window.renderOwnerBranchesSection = () => {
    const listEl = document.getElementById('owner-branch-list');
    if (!listEl) return;

    const branches = window.globalBranches || {};
    const activeBid = window.ACTIVE_BRANCH_ID || 'pusat';
    const pusatSettings = window.storeSettings || {};

    const items = [
        {
            id: 'pusat',
            name: (activeBid === 'pusat' && pusatSettings.store_title) ? pusatSettings.store_title : 'Pusat Utama (Mainstay Drink)',
            code: 'PUSAT',
            location: (activeBid === 'pusat' ? (pusatSettings.banner_location_text || pusatSettings.footer_address) : '') || 'Outlet Pusat Utama',
            status: 'active',
            isPusat: true
        },
        ...Object.keys(branches).map(bid => ({
            id: bid,
            ...(branches[bid] || {}),
            isPusat: false
        }))
    ];

    let totalAllOmzet = 0;
    let totalAllOrders = 0;
    let activeOutletCount = 0;

    items.forEach(b => {
        if (b.status !== 'inactive') activeOutletCount += 1;
        const m = window._branchMetricsCache[b.id] || { todayOmzet: 0, todayOrders: 0, menuCount: 0, staffCount: 0, lowStockCount: 0 };
        totalAllOmzet += Number(m.todayOmzet || 0);
        totalAllOrders += Number(m.todayOrders || 0);
    });

    const badgeCountEl = document.getElementById('owner-branch-count-badge');
    if (badgeCountEl) badgeCountEl.innerHTML = `&middot; ${items.length} Outlet`;
    const allCountEl = document.getElementById('owner-allbranch-count');
    if (allCountEl) allCountEl.innerText = `${activeOutletCount} Aktif`;
    const allOmzetEl = document.getElementById('owner-allbranch-omzet');
    if (allOmzetEl) allOmzetEl.innerText = formatRupiah(totalAllOmzet);
    const allOrdersEl = document.getElementById('owner-allbranch-orders');
    if (allOrdersEl) allOrdersEl.innerText = `${totalAllOrders} Order`;

    listEl.innerHTML = items.map(b => {
        const isCurrent = b.id === activeBid;
        const isInactive = b.status === 'inactive';
        const metrics = window._branchMetricsCache[b.id] || { todayOmzet: 0, todayOrders: 0, menuCount: 0, staffCount: 0, lowStockCount: 0 };
        const branchUrl = window.getBranchUrl(b.id);
        const escId = String(b.id).replace(/'/g, "\\'");

        return `
            <div class="bg-white rounded-2xl border ${isCurrent ? 'border-indigo-400 ring-2 ring-indigo-500/15' : 'border-slate-200'} p-4 shadow-xs space-y-3 transition">
                <!-- Header Cabang -->
                <div class="flex items-start gap-3">
                    <div class="w-10 h-10 rounded-xl ${b.isPusat ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'} flex items-center justify-center text-base shrink-0">
                        <i class="fa-solid ${b.isPusat ? 'fa-crown' : 'fa-store'}"></i>
                    </div>
                    <div class="min-w-0 flex-1">
                        <h4 class="text-sm font-black text-slate-900 leading-snug break-words">${b.name || b.id}</h4>
                        <div class="flex items-center flex-wrap gap-x-1.5 gap-y-0.5 text-[10px] font-bold mt-0.5">
                            ${b.code ? `<span class="text-slate-500 uppercase tracking-wide">${b.code}</span><span class="text-slate-300">&middot;</span>` : ''}
                            <span class="${isInactive ? 'text-rose-600' : 'text-emerald-600'}">${isInactive ? 'Nonaktif' : 'Aktif'}</span>
                            <span class="text-slate-300">&middot;</span>
                            <span class="${(metrics.staffCount || 0) > 0 ? 'text-purple-600' : 'text-slate-400'}">${metrics.staffCount || 0} Staf</span>
                            ${(metrics.lowStockCount || 0) > 0 ? `<span class="text-slate-300">&middot;</span><span class="text-rose-600">${metrics.lowStockCount} Stok Kritis</span>` : ''}
                            ${isCurrent ? `<span class="text-slate-300">&middot;</span><span class="text-indigo-600 font-black">Sedang Dikelola</span>` : ''}
                        </div>
                    </div>
                </div>

                <!-- Alamat & Link Cabang -->
                <div class="space-y-1 text-[11px]">
                    <p class="text-slate-600 font-medium flex items-start gap-2 leading-snug">
                        <i class="fa-solid fa-location-dot text-rose-500 text-xs shrink-0 mt-0.5"></i>
                        <span class="min-w-0 break-words">${b.location || 'Lokasi belum diisi'}</span>
                    </p>
                    <p class="text-indigo-600 font-mono text-[10px] flex items-center gap-2 min-w-0">
                        <i class="fa-solid fa-globe text-[11px] text-indigo-400 shrink-0"></i>
                        <span class="truncate">${branchUrl}</span>
                    </p>
                </div>

                <!-- Ringkasan Metrik Cabang (Terpisah agar judul & icon tidak gepeng) -->
                <div class="grid grid-cols-3 gap-2 bg-slate-50 rounded-xl p-2.5 border border-slate-100">
                    <div class="min-w-0">
                        <p class="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Omzet Hari Ini</p>
                        <p class="text-xs font-black text-emerald-600 mt-0.5 tabular-nums truncate">${formatRupiah(metrics.todayOmzet || 0)}</p>
                    </div>
                    <div class="min-w-0 border-l border-slate-200 pl-2.5">
                        <p class="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Order</p>
                        <p class="text-xs font-black text-slate-800 mt-0.5 tabular-nums truncate">${metrics.todayOrders || 0} Order</p>
                    </div>
                    <div class="min-w-0 border-l border-slate-200 pl-2.5">
                        <p class="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Katalog</p>
                        <p class="text-xs font-black text-slate-800 mt-0.5 tabular-nums truncate">${metrics.menuCount || 0} Menu</p>
                    </div>
                </div>

                <!-- Tombol Aksi Cabang -->
                <div class="flex items-center justify-between gap-2 pt-2 border-t border-slate-100 flex-wrap">
                    <div class="flex items-center gap-1.5 flex-wrap">
                        ${!isCurrent ? `
                            <button type="button" onclick="window.pindahCabangAktif('${escId}')" class="px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-[11px] font-black inline-flex items-center gap-1.5 transition active:scale-95 cursor-pointer whitespace-nowrap shrink-0">
                                <i class="fa-solid fa-right-to-bracket shrink-0"></i>
                                <span>Kelola Cabang</span>
                            </button>
                        ` : `
                            <span class="px-3 py-1.5 rounded-xl bg-indigo-50 text-indigo-700 border border-indigo-200 text-[11px] font-black inline-flex items-center gap-1.5 whitespace-nowrap shrink-0">
                                <i class="fa-solid fa-circle-check shrink-0"></i>
                                <span>Aktif Sekarang</span>
                            </span>
                        `}
                        <a href="${branchUrl}" target="_blank" rel="noopener noreferrer" class="px-3 py-1.5 rounded-xl bg-amber-50 hover:bg-amber-100 text-amber-800 border border-amber-200 text-[11px] font-bold inline-flex items-center gap-1.5 transition active:scale-95 whitespace-nowrap shrink-0">
                            <i class="fa-solid fa-up-right-from-square shrink-0"></i>
                            <span>Buka Web</span>
                        </a>
                        <button type="button" onclick="window.salinLinkCabang('${escId}')" class="px-3 py-1.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-[11px] font-bold inline-flex items-center gap-1.5 transition active:scale-95 cursor-pointer whitespace-nowrap shrink-0">
                            <i class="fa-solid fa-link shrink-0"></i>
                            <span>Salin Link</span>
                        </button>
                    </div>
                    <div class="flex items-center gap-1.5 shrink-0">
                        <button type="button" onclick="window.bukaModalFormCabang('${escId}', true)" class="px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-[11px] font-black inline-flex items-center gap-1.5 transition active:scale-95 cursor-pointer whitespace-nowrap shrink-0">
                            <i class="fa-solid fa-pen-to-square shrink-0"></i>
                            <span>Edit</span>
                        </button>
                        ${!b.isPusat ? `
                            <button type="button" onclick="window.hapusCabangMaster('${escId}', true)" class="px-3 py-1.5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white text-[11px] font-black inline-flex items-center gap-1.5 transition active:scale-95 cursor-pointer whitespace-nowrap shrink-0">
                                <i class="fa-solid fa-trash-can shrink-0"></i>
                                <span>Hapus</span>
                            </button>
                        ` : ''}
                    </div>
                </div>
            </div>
        `;
    }).join('');
};

window.closePanel = () => {
    // --- HAPUS INGATAN LACI SAAT KELUAR ---
    localStorage.removeItem('mainstay_active_panel');
    window._laporanPanelActive = false;

    const currentRole = localStorage.getItem('mainstay_session_role') || 'customer';
    if (currentRole === 'customer') {
        if (typeof window.nyalakanBGM === 'function') window.nyalakanBGM();
        const btnBgm = document.getElementById('btn-bgm');
        if (btnBgm) btnBgm.classList.remove('hidden');
    } else {
        if (typeof window.matikanBGM === 'function') window.matikanBGM();
        const btnBgm = document.getElementById('btn-bgm');
        if (btnBgm) {
            btnBgm.classList.add('hidden');
            btnBgm.style.display = 'none';
        }
    }

    const container = document.getElementById('owner-inner-panels-container');
    if (container) {
        container.innerHTML = '';
    }
    if (typeof window.renderOwnerBackupFailureNotification === 'function') {
        window.renderOwnerBackupFailureNotification();
    }

    // Kembalikan tombol mengambang kasir HANYA jika berada di peran kasir
    const fab = document.getElementById('fab-kasir-container');
    const isPosOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';
    if (currentRole === 'kasir' && !isPosOpen) {
        if (fab) {
            fab.classList.remove('hidden');
            fab.classList.add('flex');
        }
    } else if (fab) {
        fab.classList.add('hidden');
        fab.classList.remove('flex');
    }
};

window.bukaPanelMasterOwner = () => {
    window.activeHrdTab = 'owner';
    if (typeof window.openPanel === 'function') {
        window.openPanel('panel-hrd');
    } else if (typeof window.renderPanelHRD === 'function') {
        window.renderPanelHRD();
    }
    setTimeout(() => {
        const formEl = document.getElementById('form-hrd-owner-container');
        if (formEl) {
            formEl.scrollIntoView({ behavior: 'smooth' });
            formEl.classList.add('ring-4', 'ring-amber-300');
            setTimeout(() => formEl.classList.remove('ring-4', 'ring-amber-300'), 1500);
        }
    }, 250);
};

// Router Utama untuk membuka 8 Modul
window.openPanel = (panelId) => {
    // --- SIMPAN INGATAN LACI (Berlaku untuk SEMUA laci) ---
    localStorage.setItem('mainstay_active_panel', panelId);

    // Kunci tombol melayang kasir dan tombol BGM agar tidak bocor ke dalam modal
    const fab = document.getElementById('fab-kasir-container');
    if (fab) {
        fab.classList.add('hidden');
        fab.classList.remove('flex');
    }
    const btnBgm = document.getElementById('btn-bgm');
    if (btnBgm) {
        btnBgm.classList.add('hidden');
        btnBgm.style.display = 'none';
    }

    const functionMap = {
        'panel-menu': () => { if (typeof window.renderPanelMenu === 'function') window.renderPanelMenu(); },
        'panel-hrd': () => { if (typeof window.renderPanelHRD === 'function') window.renderPanelHRD(); },
        'panel-master-owner': () => {
            window.activeHrdTab = 'owner';
            if (typeof window.renderPanelHRD === 'function') {
                window.renderPanelHRD();
            }
            setTimeout(() => {
                const formEl = document.getElementById('form-hrd-owner-container');
                if (formEl) {
                    formEl.scrollIntoView({ behavior: 'smooth' });
                    formEl.classList.add('ring-4', 'ring-amber-300');
                    setTimeout(() => formEl.classList.remove('ring-4', 'ring-amber-300'), 1500);
                }
            }, 250);
        },
        'panel-inventory': () => { if (typeof window.renderPanelInventory === 'function') window.renderPanelInventory(); },
        'panel-laporan': () => { if (typeof window.renderPanelLaporan === 'function') window.renderPanelLaporan('laporan'); },
        'panel-manajemen-keuangan': () => { if (typeof window.renderPanelManajemenKeuangan === 'function') window.renderPanelManajemenKeuangan(); },
        'panel-aktivitas': () => { if (typeof window.renderPanelAktivitasOwner === 'function') window.renderPanelAktivitasOwner(); },
        'panel-promo': () => { if (typeof window.renderPanelPromo === 'function') window.renderPanelPromo(); },
        'panel-settings': () => { if (typeof window.renderPanelSettings === 'function') window.renderPanelSettings(); },
        'panel-member': () => {
            if (typeof window.renderPanelMember === 'function') {
                window.renderPanelMember();
            } else {
                console.warn('renderPanelMember is not ready');
            }
        },
        'panel-database': () => { if (typeof window.renderPanelDatabase === 'function') window.renderPanelDatabase(); },
        'panel-log-absen': () => { if (typeof window.lihatLogAbsensi === 'function') window.lihatLogAbsensi(); },
        'panel-ojol': () => { if (typeof window.renderPanelOjol === 'function') window.renderPanelOjol(); },
        'panel-qr-meja': () => { if (typeof window.renderPanelQrMeja === 'function') window.renderPanelQrMeja(); }
    };
    
    // Panggil fungsi render sesuai ID tombol yang diklik (Anti-Blank Fallback Protection)
    if (functionMap[panelId]) {
        try {
            functionMap[panelId]();
        } catch (panelErr) {
            console.error('[Panel Anti-Blank Error]', panelId, panelErr);
            const panelContainer = document.getElementById('owner-inner-panels-container');
            if (panelContainer) {
                panelContainer.innerHTML = `
                    <div class="fixed inset-0 bg-slate-50 z-[300] flex flex-col fade-in">
                        <div class="bg-slate-900 text-white p-4 flex items-center gap-3 shrink-0">
                            <button type="button" onclick="closePanel()" class="w-10 h-10 shrink-0 bg-slate-800 rounded-xl hover:bg-slate-700 transition flex items-center justify-center">
                                <i class="fa-solid fa-arrow-left"></i>
                            </button>
                            <h2 class="font-black text-base">Pemulihan Panel</h2>
                        </div>
                        <div class="flex-1 p-6 flex flex-col items-center justify-center text-center gap-3">
                            <div class="w-14 h-14 rounded-2xl bg-amber-100 text-amber-600 flex items-center justify-center text-2xl">
                                <i class="fa-solid fa-shield-heart"></i>
                            </div>
                            <h3 class="text-sm font-black text-slate-900">Panel sedang disinkronkan ulang</h3>
                            <p class="text-xs text-slate-500 max-w-xs">Terjadi kendala sementara saat memuat data. Tekan Muat Ulang untuk memulihkan tampilan.</p>
                            <div class="flex items-center gap-2 mt-2">
                                <button type="button" onclick="openPanel('${panelId}')" class="px-4 py-2 rounded-xl bg-amber-500 hover:bg-amber-600 text-slate-950 font-black text-xs cursor-pointer">Muat Ulang Panel</button>
                                <button type="button" onclick="closePanel()" class="px-4 py-2 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold text-xs cursor-pointer">Kembali</button>
                            </div>
                        </div>
                    </div>`;
            }
        }
    } else {
        // Layar Fallback jika panel belum dikembangkan
        document.getElementById('owner-inner-panels-container').innerHTML = `
            <div class="fixed inset-0 bg-slate-50 z-[300] flex flex-col fade-in">
                <div class="bg-gray-900 text-white p-4 flex items-center gap-3">
                    <button onclick="closePanel()" class="w-10 h-10 shrink-0 bg-gray-800 rounded-xl hover:bg-gray-700 transition">
                        <i class="fa-solid fa-arrow-left"></i>
                    </button>
                    <h2 class="font-black text-lg">Panel Belum Siap</h2>
                </div>
                <div class="flex-1 p-5 flex flex-col items-center justify-center text-center text-gray-400">
                    <i class="fa-solid fa-person-digging text-5xl mb-4 text-amber-500"></i>
                    <p class="font-bold text-sm">Modul ini dalam tahap antrean pengembangan.</p>
                </div>
            </div>`;
    }
};

// --- FUNGSI CRUD DATABASE UNIVERSAL (Re-usable untuk semua panel) ---

window.simpanNode = async (nodeString, payload) => {
    // Validasi Keamanan Sederhana
    if (!payload.name && !payload.desc && !payload.emergency_pin) {
        return alert("Peringatan: Formulir data tidak boleh kosong!");
    }
    
    // Indikator visual bisa ditambahkan di sini jika perlu
    try {
        // Push data baru secara dinamis ke node tabel yang dituju
        await push(ref(db, nodeString), payload);
        alert('Sukses! Data baru berhasil ditambahkan ke Database Firebase.');
        
        // Refresh (Render Ulang) Panel yang sedang terbuka agar data langsung muncul
        if (nodeString === 'menus' && typeof window.renderPanelMenu === 'function') window.renderPanelMenu();
        if (nodeString === 'staff' && typeof window.renderPanelHRD === 'function') window.renderPanelHRD();
        if (nodeString === 'inventory_raw' && typeof window.renderPanelInventory === 'function') window.renderPanelInventory();
        if (nodeString === 'expenses' && typeof window.renderPanelLaporan === 'function') window.renderPanelLaporan();
        
    } catch (error) {
        console.error("Firebase Insert Error:", error);
        alert("Terjadi kesalahan! Gagal menyimpan data ke database.");
    }
};

window.hapusNode = async (nodeString, dataKey, callbackFunctionName) => {
    let nodeLabel = 'Data Ini';
    if (nodeString === 'menus') nodeLabel = 'Menu Katalog';
    else if (nodeString === 'staff') nodeLabel = 'Staff / Barista';
    else if (nodeString === 'inventory_raw') nodeLabel = 'Bahan Baku Stok';
    else if (nodeString === 'expenses') nodeLabel = 'Catatan Pengeluaran';

    window.tampilkanKonfirmasiGlobal({
        title: `Hapus ${nodeLabel}?`,
        message: `Apakah Anda yakin ingin menghapus ${nodeLabel} ini secara permanen?`,
        subtext: "Data akan terhapus langsung dari database cloud dan penyimpanan lokal.",
        icon: "fa-trash-can",
        confirmText: "Ya, Hapus",
        isDanger: true,
        onConfirm: async () => {
            const deletedMenuObj = (nodeString === 'menus' && globalMenus) ? { ...(globalMenus[dataKey] || {}) } : null;
            const deletedInvObj = (nodeString === 'inventory_raw' && globalInventory) ? { ...(globalInventory[dataKey] || {}) } : null;

            // Eksekusi hapus data ke Firebase
            await remove(ref(db, `${nodeString}/${dataKey}`)); 

            if (nodeString === 'menus') {
                delete globalMenus[dataKey];
                if (window.globalMenus) delete window.globalMenus[dataKey];
                const deletedMenuKeys = JSON.parse(localStorage.getItem('mainstay_deleted_menu_keys') || '[]');
                if (!deletedMenuKeys.includes(dataKey)) {
                    deletedMenuKeys.push(dataKey);
                    localStorage.setItem('mainstay_deleted_menu_keys', JSON.stringify(deletedMenuKeys));
                }
                localStorage.setItem('mainstay_menus_initialized', 'true');
                try { localStorage.setItem('mainstay_cached_menus', JSON.stringify(globalMenus)); } catch(e) {}
                if (typeof window.renderKatalog === 'function') window.renderKatalog();
                if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
                if (typeof window.renderPromoBestsellerCarousel === 'function') window.renderPromoBestsellerCarousel();
                if (typeof window.catatLogAktivitas === 'function' && deletedMenuObj) {
                    const mName = deletedMenuObj.name || deletedMenuObj.nama || dataKey;
                    const mPrice = Number(deletedMenuObj.price || 0);
                    window.catatLogAktivitas({
                        category: 'menu_edit',
                        actionType: 'Menu Deletion',
                        targetType: 'menu',
                        targetKey: dataKey,
                        targetName: mName,
                        beforeVal: formatRupiah(mPrice),
                        afterVal: 'Dihapus',
                        summary: `Menghapus menu "${mName}" (${formatRupiah(mPrice)}) dari katalog.`
                    });
                }
            } else if (nodeString === 'inventory_raw') {
                if (globalInventory && globalInventory[dataKey]) delete globalInventory[dataKey];
                if (typeof window.catatLogAktivitas === 'function' && deletedInvObj) {
                    const iName = deletedInvObj.name || dataKey;
                    const iQty = Number(deletedInvObj.qty || 0);
                    const iUnit = deletedInvObj.unit || 'Pcs';
                    window.catatLogAktivitas({
                        category: 'stock_adjustment',
                        actionType: 'Manual Stock Adjustment',
                        targetType: 'inventory',
                        targetKey: dataKey,
                        targetName: iName,
                        beforeVal: `${iQty} ${iUnit}`,
                        afterVal: 'Dihapus',
                        summary: `Menghapus bahan baku "${iName}" (sisa stok ${iQty} ${iUnit}) dari gudang.`
                    });
                }
            } else if (nodeString === 'staff') {
                if (typeof globalStaff === 'object' && globalStaff) delete globalStaff[dataKey];
                if (window.globalStaff) delete window.globalStaff[dataKey];
                try { localStorage.setItem('mainstay_cached_staff', JSON.stringify(globalStaff || {})); } catch(e) {}
                if (window.mainstayIndexedDB && typeof window.mainstayIndexedDB.deleteBranchStaff === 'function') {
                    await window.mainstayIndexedDB.deleteBranchStaff(window.ACTIVE_BRANCH_ID || 'pusat', dataKey);
                }
                if (typeof window.populateStaffSelectAbsen === 'function') window.populateStaffSelectAbsen();
                if (typeof window.renderDaftarStatusStafAbsen === 'function') window.renderDaftarStatusStafAbsen();
                if (typeof window.updateOwnerDashboard === 'function') window.updateOwnerDashboard();
            } else if (nodeString === 'master_owner') {
                if (typeof globalMasterOwner !== 'undefined' && globalMasterOwner) delete globalMasterOwner[dataKey];
                if (window.globalMasterOwner) delete window.globalMasterOwner[dataKey];
            }

            // Muat ulang daftar tampilan secara otomatis
            if (typeof window[callbackFunctionName] === 'function') {
                window[callbackFunctionName]();
            }
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`${nodeLabel} berhasil dihapus.`, 'info');
            } else {
                alert(`Berhasil! ${nodeLabel} telah dihapus.`);
            }
        }
    });
};

window.hapusSemuaDummyMenu = async () => {
    if (!confirm('Hapus seluruh menu dummy/contoh bawaan sistem? Menu asli buatan Anda tidak akan terhapus.')) return;
    const dummyKeys = ['menu_americano', 'menu_thai_tea', 'menu_taro_milk', 'menu_vanilla', 'menu_pukis', 'menu_kopi_susu', 'menu_es_teh', 'menu_matcha'];
    const deletedMenus = JSON.parse(localStorage.getItem('mainstay_deleted_menu_keys') || '[]');
    for (const k of dummyKeys) {
        await remove(ref(db, `menus/${k}`)).catch(() => {});
        delete globalMenus[k];
        if (window.globalMenus) delete window.globalMenus[k];
        if (!deletedMenus.includes(k)) deletedMenus.push(k);
    }
    localStorage.setItem('mainstay_deleted_menu_keys', JSON.stringify(deletedMenus));
    localStorage.setItem('mainstay_menus_initialized', 'true');
    try { localStorage.setItem('mainstay_cached_menus', JSON.stringify(globalMenus)); } catch(e) {}
    
    if (typeof window.renderPanelMenu === 'function') window.renderPanelMenu();
    if (typeof window.renderKatalog === 'function') window.renderKatalog();
    if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
    if (typeof window.renderPromoBestsellerCarousel === 'function') window.renderPromoBestsellerCarousel();
    alert('Menu dummy bawaan berhasil dihapus.');
};

