window.toggleFormPaketGabungan = (isChecked, existingMenu = null) => {
    const wrap = document.getElementById('wadah-opsi-paket-gabungan');
    if (!wrap) return;
    if (isChecked) {
        wrap.classList.remove('hidden');
        const pkgItemsRaw = existingMenu ? existingMenu.packageItems : [];
        const pkgItemsNorm = Array.isArray(pkgItemsRaw)
            ? pkgItemsRaw
            : (pkgItemsRaw && typeof pkgItemsRaw === 'object' ? Object.values(pkgItemsRaw) : []);
        window.renderDaftarProdukPaket(pkgItemsNorm);
        
        if (existingMenu) {
            const diskonTipe = existingMenu.packageDiscountType || 'nominal';
            const radio = document.querySelector(`input[name="fm_paket_diskon_tipe"][value="${diskonTipe}"]`);
            if (radio) radio.checked = true;

            const valInput = document.getElementById('fm-paket-diskon-val');
            if (valInput) valInput.value = existingMenu.packageDiscountValue || '';

            const gratisSelect = document.getElementById('fm-paket-gratis-select');
            if (gratisSelect && existingMenu.packageFreeProductId) {
                gratisSelect.value = existingMenu.packageFreeProductId;
            }
        }
        window.updateKalkulasiPaketGabungan();
    } else {
        wrap.classList.add('hidden');
    }
};

window.renderDaftarProdukPaket = (selectedItems = []) => {
    const container = document.getElementById('wadah-pilihan-produk-paket');
    const gratisSelect = document.getElementById('fm-paket-gratis-select');
    if (!container) return;

    const currentEditKey = window.editMenuKeyTarget;
    const selectedMap = new Map();
    const listSelected = Array.isArray(selectedItems)
        ? selectedItems
        : (selectedItems && typeof selectedItems === 'object' ? Object.values(selectedItems) : []);
    listSelected.forEach(it => {
        if (it && typeof it === 'object' && it.id) {
            selectedMap.set(String(it.id), Number(it.qty) || 1);
        } else if (typeof it === 'string' && it.trim()) {
            selectedMap.set(it.trim(), 1);
        }
    });

    const menusList = Object.entries(globalMenus || {});
    let optionsHtml = '';
    let gratisOptionsHtml = '<option value="">-- Pilih Produk Bonus Gratis --</option>';

    menusList.forEach(([key, m]) => {
        if (!m) return;
        // Hindari nesting paket ke dalam dirinya sendiri
        if (key === currentEditKey) return;
        const isBundle = m.isPackage || m.category === 'Paket Hemat';
        if (isBundle) return;

        const isChecked = selectedMap.has(key);
        const qty = selectedMap.get(key) || 1;
        const name = (m.name || m.nama || 'Produk').trim();
        const price = Number(m.price || m.harga || 0);

        optionsHtml += `
            <div class="flex items-center justify-between gap-2 p-2 rounded-lg hover:bg-purple-50/70 border border-slate-100 transition">
                <label class="flex items-center gap-2 cursor-pointer flex-1 min-w-0">
                    <input type="checkbox" class="checkbox-paket-item w-4 h-4 text-purple-600 rounded border-purple-300" 
                        data-id="${key}" data-name="${name.replace(/"/g, '&quot;')}" data-price="${price}" 
                        ${isChecked ? 'checked' : ''} onchange="window.updateKalkulasiPaketGabungan()">
                    <div class="truncate">
                        <span class="text-xs font-bold text-slate-800">${name}</span>
                        <span class="text-[10px] text-purple-700 font-semibold block">Rp ${price.toLocaleString('id-ID')}</span>
                    </div>
                </label>
                <div class="flex items-center gap-1 shrink-0">
                    <span class="text-[10px] text-slate-500 font-medium">Qty:</span>
                    <input type="number" min="1" max="99" value="${qty}" 
                        class="input-paket-qty w-12 text-center bg-slate-50 border border-purple-200 rounded p-1 text-xs font-bold text-slate-800 focus:outline-none focus:border-purple-500" 
                        data-id="${key}" oninput="window.updateKalkulasiPaketGabungan()">
                </div>
            </div>
        `;

        gratisOptionsHtml += `<option value="${key}">${name} (Rp ${price.toLocaleString('id-ID')})</option>`;
    });

    if (optionsHtml === '') {
        container.innerHTML = `<p class="text-[11px] text-slate-400 p-2 italic text-center">Belum ada menu produk lain yang tersedia.</p>`;
    } else {
        container.innerHTML = optionsHtml;
    }

    if (gratisSelect) {
        gratisSelect.innerHTML = gratisOptionsHtml;
    }
};

window.updateKalkulasiPaketGabungan = () => {
    const checkedCheckboxes = document.querySelectorAll('.checkbox-paket-item:checked');
    const labelCount = document.getElementById('label-paket-item-count');
    if (labelCount) {
        labelCount.innerText = `${checkedCheckboxes.length} produk dipilih`;
    }

    let totalHargaAsli = 0;
    checkedCheckboxes.forEach(cb => {
        const key = cb.dataset.id;
        const price = Number(cb.dataset.price) || 0;
        const qtyInput = document.querySelector(`.input-paket-qty[data-id="${key}"]`);
        const qty = Number(qtyInput ? qtyInput.value : 1) || 1;
        totalHargaAsli += (price * qty);
    });

    const tipeRadio = document.querySelector('input[name="fm_paket_diskon_tipe"]:checked');
    const diskonTipe = tipeRadio ? tipeRadio.value : 'nominal';
    const wadahDiskon = document.getElementById('wadah-paket-input-diskon');
    const wadahGratis = document.getElementById('wadah-paket-gratis-produk');
    const lblDiskon = document.getElementById('lbl-paket-diskon-val');
    const inputDiskonVal = document.getElementById('fm-paket-diskon-val');

    let finalPrice = totalHargaAsli;

    if (diskonTipe === 'gratis_produk') {
        if (wadahDiskon) wadahDiskon.classList.add('hidden');
        if (wadahGratis) wadahGratis.classList.remove('hidden');
        finalPrice = totalHargaAsli;
    } else {
        if (wadahDiskon) wadahDiskon.classList.remove('hidden');
        if (wadahGratis) wadahGratis.classList.add('hidden');
        const diskonVal = Number(inputDiskonVal ? inputDiskonVal.value : 0) || 0;

        if (diskonTipe === 'persen') {
            if (lblDiskon) lblDiskon.innerText = "Persentase Diskon Paket (%):";
            if (inputDiskonVal) inputDiskonVal.placeholder = "Cth: 15";
            const potongan = Math.round(totalHargaAsli * (Math.min(100, Math.max(0, diskonVal)) / 100));
            finalPrice = Math.max(0, totalHargaAsli - potongan);
        } else {
            if (lblDiskon) lblDiskon.innerText = "Nominal Diskon Paket (Rp):";
            if (inputDiskonVal) inputDiskonVal.placeholder = "Cth: 5000";
            finalPrice = Math.max(0, totalHargaAsli - diskonVal);
        }
    }

    const elTotalAsli = document.getElementById('paket-total-harga-asli');
    if (elTotalAsli) elTotalAsli.innerText = `Rp ${totalHargaAsli.toLocaleString('id-ID')}`;

    const elFinalPreview = document.getElementById('paket-final-price-preview');
    if (elFinalPreview) elFinalPreview.innerText = `Rp ${finalPrice.toLocaleString('id-ID')}`;

    const priceInput = document.getElementById('fm-price');
    if (priceInput && (checkedCheckboxes.length > 0 || finalPrice > 0)) {
        priceInput.value = finalPrice;
    }
};

