// ---------------------------------------------------------
// MODUL 3: GUDANG / INVENTORY RAW (/inventory_raw) & NOTIFIKASI
// ---------------------------------------------------------
window.inventoryActiveFilter = 'all';
window.inventorySearchTerm = '';
window.editInventoryKeyTarget = null;

// Fungsi untuk update kuantitas stok bahan baku langsung ke Firebase
window.updateStokInventory = async (key, delta, options = {}) => {
    if (!globalInventory || !globalInventory[key]) return;
    const currentItem = globalInventory[key];
    const currentQty = Number(currentItem.qty) || 0;
    const minQty = Number(currentItem.minQty !== undefined ? currentItem.minQty : 5);
    const newQty = Math.max(0, Number((currentQty + Number(delta)).toFixed(2)));
    const wasSafe = currentQty > minQty;
    const isNowCritical = newQty <= minQty;
    const unit = currentItem.unit || 'Pcs';

    try {
        await update(ref(db, `inventory_raw/${key}`), {
            qty: newQty,
            lastUpdated: new Date().toISOString()
        });

        // Update local object immediately for smooth UI
        globalInventory[key].qty = newQty;

        if (!options?.skipActivityLog && currentQty !== newQty) {
            const signedDelta = Number(delta) > 0 ? `+${delta}` : String(delta);
            if (typeof window.catatRiwayatPergerakanStok === 'function') {
                window.catatRiwayatPergerakanStok({
                    itemKey: key,
                    itemName: currentItem.name || 'Bahan Baku',
                    type: Number(delta) > 0 ? 'restock' : 'adjustment',
                    qtyDelta: Number(delta),
                    beforeQty: currentQty,
                    afterQty: newQty,
                    unit,
                    source: 'quick_stepper',
                    reason: `Penyesuaian stok cepat (${signedDelta} ${unit})`
                });
            }
            if (typeof window.catatLogAktivitas === 'function') {
                window.catatLogAktivitas({
                    category: 'stock_adjustment',
                    actionType: 'Manual Stock Adjustment',
                    targetType: 'inventory',
                    targetKey: key,
                    targetName: currentItem.name || 'Bahan Baku',
                    beforeVal: `${currentQty} ${unit}`,
                    afterVal: `${newQty} ${unit}`,
                    summary: `Penyesuaian stok cepat (${signedDelta} ${unit}): ${currentQty} -> ${newQty} ${unit}`
                });
            }
        }

        if (typeof window.cekNotifikasiStokMinimum === 'function') {
            window.cekNotifikasiStokMinimum({
                showToast: wasSafe && isNowCritical,
                newlyCritical: wasSafe && isNowCritical ? [{
                    key,
                    name: currentItem.name || 'Bahan Baku',
                    qty: newQty,
                    min: minQty,
                    unit: unit,
                    category: currentItem.category || 'Bahan'
                }] : []
            });
        }
        if (typeof window.renderPanelInventory === 'function' && document.getElementById('owner-inventory-list')) {
            window.renderPanelInventory();
        }
        if (typeof window.renderTabStok === 'function' && document.getElementById('stok-kasir-list')) {
            window.renderTabStok();
        }
        if (!options?.skipActivityLog && typeof window.tampilkanNotifikasi === 'function') {
            const signedD = Number(delta) > 0 ? `+${delta}` : String(delta);
            window.tampilkanNotifikasi(`Stok "${currentItem.name || 'Bahan'}" (${signedD} ${unit}) menjadi ${newQty} ${unit}.`, 'success', 2200);
        }
    } catch (err) {
        console.error("Gagal update stok inventory:", err);
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi("Gagal mengupdate stok: " + err.message, "error");
        }
    }
};

// ============================================================================
// POPUP MODERN: ATUR JUMLAH STOK BAHAN BAKU INVENTARIS
// ============================================================================
window._activeStokKey = null;

window.pilihAlasanSetStok = (reasonTxt) => {
    const inp = document.getElementById('set-stok-reason-input');
    if (inp) {
        inp.value = reasonTxt || '';
        inp.focus();
    }
};

window.updateSetStokDeltaPreview = () => {
    const key = window._activeStokKey;
    const inputQty = document.getElementById('set-stok-input-qty');
    const deltaEl = document.getElementById('set-stok-delta-preview');
    const warnBox = document.getElementById('set-stok-warning-box');
    if (!key || !globalInventory || !globalInventory[key] || !inputQty) return;

    const currentItem = globalInventory[key];
    const curQty = Number(currentItem.qty) || 0;
    const minQty = Number(currentItem.minQty !== undefined ? currentItem.minQty : 5);
    const unit = currentItem.unit || 'Pcs';
    const nextQty = Math.max(0, Number(inputQty.value) || 0);
    const diff = Number((nextQty - curQty).toFixed(2));

    if (warnBox) {
        if (nextQty <= minQty) warnBox.classList.remove('hidden');
        else warnBox.classList.add('hidden');
    }
    if (deltaEl) {
        if (diff === 0) {
            deltaEl.innerText = 'Tidak berubah';
            deltaEl.className = 'text-[10px] font-black px-2 py-0.5 rounded-md bg-slate-100 text-slate-500 tabular-nums';
        } else if (diff > 0) {
            deltaEl.innerText = `+${diff} ${unit}`;
            deltaEl.className = 'text-[10px] font-black px-2 py-0.5 rounded-md bg-emerald-100 text-emerald-700 tabular-nums';
        } else {
            deltaEl.innerText = `${diff} ${unit}`;
            deltaEl.className = 'text-[10px] font-black px-2 py-0.5 rounded-md bg-rose-100 text-rose-700 tabular-nums';
        }
    }
};

window.setStokInventoryLangsung = (key) => {
    if (!globalInventory || !globalInventory[key]) return;
    const currentItem = globalInventory[key];
    window._activeStokKey = key;

    const modal = document.getElementById('modal-set-stok-modern');
    const namaEl = document.getElementById('set-stok-nama');
    const katEl = document.getElementById('set-stok-kategori');
    const curBadgeEl = document.getElementById('set-stok-current-badge');
    const unitLabelEl = document.getElementById('set-stok-unit-label');
    const inputQty = document.getElementById('set-stok-input-qty');
    const reasonEl = document.getElementById('set-stok-reason-input');
    const minThresholdEl = document.getElementById('set-stok-min-threshold');

    const curQty = Number(currentItem.qty) || 0;
    const unit = currentItem.unit || 'Pcs';
    const minQty = Number(currentItem.minQty !== undefined ? currentItem.minQty : 5);

    if (namaEl) namaEl.innerText = currentItem.name || 'Bahan Baku';
    if (katEl) katEl.innerText = `${currentItem.category || 'Bahan Baku'} • Satuan: ${unit}`;
    if (curBadgeEl) curBadgeEl.innerText = `${curQty} ${unit}`;
    if (unitLabelEl) unitLabelEl.innerText = unit;
    if (minThresholdEl) minThresholdEl.innerText = minQty;
    if (inputQty) inputQty.value = curQty;
    if (reasonEl) reasonEl.value = '';

    window.updateSetStokDeltaPreview();

    if (inputQty) {
        inputQty.oninput = () => {
            window.updateSetStokDeltaPreview();
        };
    }

    if (modal) {
        modal.classList.remove('hidden');
        if (inputQty) {
            setTimeout(() => {
                inputQty.focus();
                inputQty.select();
            }, 100);
        }
    }
};

window.ubahStepStokModern = (delta) => {
    const inputQty = document.getElementById('set-stok-input-qty');
    if (!inputQty || !window._activeStokKey || !globalInventory[window._activeStokKey]) return;

    let cur = Number(inputQty.value) || 0;
    cur = Math.max(0, Number((cur + Number(delta)).toFixed(2)));
    inputQty.value = cur;
    window.updateSetStokDeltaPreview();
};

window.resetStokModernKeNol = () => {
    const inputQty = document.getElementById('set-stok-input-qty');
    if (!inputQty) return;
    inputQty.value = 0;
    window.updateSetStokDeltaPreview();
    inputQty.focus();
};

window.eksekusiSimpanStokModern = async () => {
    const key = window._activeStokKey;
    if (!key || !globalInventory || !globalInventory[key]) {
        window.tutupModalSetStokModern();
        return;
    }

    const currentItem = globalInventory[key];
    const inputQty = document.getElementById('set-stok-input-qty');
    const reasonEl = document.getElementById('set-stok-reason-input');
    const newQty = Math.max(0, Number(inputQty ? inputQty.value : 0) || 0);
    const reasonTxt = String(reasonEl?.value || '').trim();

    const currentQty = Number(currentItem.qty) || 0;
    const minQty = Number(currentItem.minQty !== undefined ? currentItem.minQty : 5);
    const wasSafe = currentQty > minQty;
    const isNowCritical = newQty <= minQty;
    const diff = Number((newQty - currentQty).toFixed(2));
    const diffStr = diff > 0 ? `+${diff}` : String(diff);

    try {
        await update(ref(db, `inventory_raw/${key}`), {
            qty: newQty,
            lastUpdated: new Date().toISOString()
        });

        globalInventory[key].qty = newQty;

        const unitLabel = currentItem.unit || 'Pcs';
        const noteSuffix = reasonTxt ? ` (${reasonTxt})` : '';
        if (typeof window.catatRiwayatPergerakanStok === 'function' && diff !== 0) {
            const isWasteReason = /rusak|pecah|basi|tumpah|waste/i.test(reasonTxt);
            window.catatRiwayatPergerakanStok({
                itemKey: key,
                itemName: currentItem.name || 'Bahan Baku',
                type: isWasteReason && diff < 0 ? 'waste' : (diff > 0 ? 'restock' : 'adjustment'),
                qtyDelta: diff,
                beforeQty: currentQty,
                afterQty: newQty,
                unit: unitLabel,
                source: 'manual_opname',
                reason: reasonTxt || `Ubah stok manual (${diffStr} ${unitLabel})`
            });
        }
        if (typeof window.catatLogAktivitas === 'function') {
            window.catatLogAktivitas({
                category: 'stock_adjustment',
                actionType: 'Manual Stock Adjustment',
                targetType: 'inventory',
                targetKey: key,
                targetName: currentItem.name || 'Bahan Baku',
                beforeVal: `${currentQty} ${unitLabel}`,
                afterVal: `${newQty} ${unitLabel}`,
                summary: `Ubah stok manual "${currentItem.name || 'Bahan'}" (${diff === 0 ? '0' : diffStr} ${unitLabel}): ${currentQty} -> ${newQty} ${unitLabel}${noteSuffix}`,
                extra: reasonTxt ? { reason: reasonTxt, delta: diff } : { delta: diff }
            });
        }

        if (typeof window.cekNotifikasiStokMinimum === 'function') {
            window.cekNotifikasiStokMinimum({
                showToast: wasSafe && isNowCritical,
                newlyCritical: wasSafe && isNowCritical ? [{
                    key,
                    name: currentItem.name || 'Bahan Baku',
                    qty: newQty,
                    min: minQty,
                    unit: unitLabel,
                    category: currentItem.category || 'Bahan'
                }] : []
            });
        }

        if (typeof window.renderPanelInventory === 'function' && document.getElementById('owner-inventory-list')) {
            window.renderPanelInventory();
        }
        if (typeof window.renderTabStok === 'function' && document.getElementById('stok-kasir-list')) {
            window.renderTabStok();
        }

        window.tutupModalSetStokModern();
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(`Stok "${currentItem.name || 'Bahan'}" diubah: ${currentQty} → ${newQty} ${unitLabel} (Tercatat di Log).`, 'success', 3200);
        }
        if (typeof window.playScannerBeep === 'function') window.playScannerBeep('success');
    } catch (err) {
        console.error("Gagal set stok modern:", err);
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi("Gagal memperbarui stok: " + err.message, "error");
        }
    }
};

window.tutupModalSetStokModern = () => {
    const modal = document.getElementById('modal-set-stok-modern');
    if (modal) modal.classList.add('hidden');
    window._activeStokKey = null;
};

window.updatePreviewModalInventory = () => {
    const qty = Number(document.getElementById('fi-qty')?.value || 0);
    const unitCost = Number(document.getElementById('fi-cost-price')?.value || 0);
    const unit = (document.getElementById('fi-unit')?.value || 'Satuan').trim() || 'Satuan';
    const previewEl = document.getElementById('fi-total-cost-preview');
    if (previewEl) {
        const total = Math.max(0, Math.round(qty * unitCost));
        previewEl.innerText = `Rp ${total.toLocaleString('id-ID')} (${qty || 0} ${unit} × Rp ${unitCost.toLocaleString('id-ID')})`;
    }
};

// Fungsi Form Create & Edit Bahan Baku ke Firebase
window.simpanInventoryBaru = async () => {
    const nameEl = document.getElementById('fi-name');
    const qtyEl = document.getElementById('fi-qty');
    const unitEl = document.getElementById('fi-unit');
    const minQtyEl = document.getElementById('fi-min-qty');
    const catEl = document.getElementById('fi-cat');
    const costPriceEl = document.getElementById('fi-cost-price');
    const recordPurchaseEl = document.getElementById('fi-record-purchase');

    if (!nameEl || !qtyEl) return;
    const name = nameEl.value.trim();
    const qty = Number(qtyEl.value);
    const unit = unitEl ? (unitEl.value.trim() || 'Pcs') : 'Pcs';
    const minQty = minQtyEl ? (Number(minQtyEl.value) || 5) : 5;
    const category = catEl ? (catEl.value.trim() || 'Bahan Baku') : 'Bahan Baku';
    const costPrice = costPriceEl ? Math.max(0, Number(costPriceEl.value) || 0) : 0;
    const shouldRecordPurchase = recordPurchaseEl ? recordPurchaseEl.checked : false;

    if (!name) return alert("Nama bahan baku wajib diisi!");
    if (isNaN(qty) || qty < 0) return alert("Jumlah stok awal wajib berupa angka!");

    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const isoToday = `${yyyy}-${mm}-${dd}`;
    const staffName = String(localStorage.getItem('mainstay_staff_name') || 'Owner').replace(/\s*\(\s*master\s*\)/i, '').trim() || 'Owner';

    const payload = {
        name,
        qty,
        unit,
        minQty,
        category,
        costPrice,
        totalStockModal: Math.round(qty * costPrice),
        updatedAt: now.toISOString()
    };

    try {
        const isEditMode = Boolean(window.editInventoryKeyTarget);
        let savedKey = window.editInventoryKeyTarget;
        let purchasedQty = qty;
        let oldQtySnapshot = 0;

        if (savedKey) {
            const oldItem = (globalInventory && globalInventory[savedKey]) || {};
            oldQtySnapshot = Number(oldItem.qty) || 0;
            purchasedQty = qty > oldQtySnapshot ? (qty - oldQtySnapshot) : qty;
            await update(ref(db, `inventory_raw/${savedKey}`), payload);
            window.editInventoryKeyTarget = null;
        } else {
            payload.createdAt = now.toISOString();
            const pushedRef = await push(ref(db, 'inventory_raw'), payload);
            savedKey = pushedRef ? pushedRef.key : ('inv_' + Date.now());
        }

        if (typeof window.catatLogAktivitas === 'function') {
            if (isEditMode) {
                window.catatLogAktivitas({
                    category: 'stock_adjustment',
                    actionType: 'Manual Stock Adjustment',
                    targetType: 'inventory',
                    targetKey: savedKey || '',
                    targetName: name,
                    beforeVal: `${oldQtySnapshot} ${unit}`,
                    afterVal: `${qty} ${unit}`,
                    summary: oldQtySnapshot !== qty
                        ? `Edit stok gudang "${name}": ${oldQtySnapshot} -> ${qty} ${unit}`
                        : `Edit detail bahan baku "${name}" (stok ${qty} ${unit})`
                });
            } else {
                window.catatLogAktivitas({
                    category: 'stock_adjustment',
                    actionType: 'Manual Stock Adjustment',
                    targetType: 'inventory',
                    targetKey: savedKey || '',
                    targetName: name,
                    beforeVal: '0',
                    afterVal: `${qty} ${unit}`,
                    summary: `Tambah bahan baku baru "${name}" dengan stok awal ${qty} ${unit}`
                });
            }
        }

        if (shouldRecordPurchase && costPrice > 0 && purchasedQty > 0) {
            const totalCost = Math.round(purchasedQty * costPrice);
            await push(ref(db, 'stock_purchases'), {
                itemKey: savedKey || '',
                itemName: name,
                category,
                qty: purchasedQty,
                unit,
                unitCost: costPrice,
                totalCost,
                date: isoToday,
                isoDate: isoToday,
                timestamp: now.getTime(),
                staffName,
                source: 'owner_gudang',
                note: 'Input / Update Gudang Owner'
            });
        }

        alert(isEditMode
            ? `Bahan baku "${name}" berhasil diperbarui!`
            : `Bahan baku "${name}" berhasil disimpan ke database!`);

        // Reset Form
        nameEl.value = '';
        qtyEl.value = '';
        if (unitEl) unitEl.value = '';
        if (minQtyEl) minQtyEl.value = '5';
        if (costPriceEl) costPriceEl.value = '';
        if (recordPurchaseEl) recordPurchaseEl.checked = true;
        window.updatePreviewModalInventory();

        if (typeof window.cekNotifikasiStokMinimum === 'function') {
            window.cekNotifikasiStokMinimum();
        }
        if (typeof window.renderPanelInventory === 'function') {
            window.renderPanelInventory();
        }
    } catch (err) {
        console.error("Error simpan inventory:", err);
        alert("Gagal menyimpan ke Firebase: " + err.message);
    }
};

// Memasukkan data bahan baku yang dipilih ke form edit
window.editInventoryItem = (key) => {
    if (!globalInventory || !globalInventory[key]) return;
    const item = globalInventory[key];
    window.editInventoryKeyTarget = key;

    const nameEl = document.getElementById('fi-name');
    const qtyEl = document.getElementById('fi-qty');
    const unitEl = document.getElementById('fi-unit');
    const minQtyEl = document.getElementById('fi-min-qty');
    const catEl = document.getElementById('fi-cat');
    const costPriceEl = document.getElementById('fi-cost-price');
    const recordPurchaseEl = document.getElementById('fi-record-purchase');
    const formTitle = document.getElementById('fi-form-title');
    const submitBtn = document.getElementById('fi-btn-submit');
    const cancelBtn = document.getElementById('fi-btn-cancel');

    if (nameEl) nameEl.value = item.name || '';
    if (qtyEl) qtyEl.value = item.qty !== undefined ? item.qty : 0;
    if (unitEl) unitEl.value = item.unit || '';
    if (minQtyEl) minQtyEl.value = item.minQty !== undefined ? item.minQty : 5;
    if (catEl && item.category) catEl.value = item.category;
    if (costPriceEl) costPriceEl.value = item.costPrice !== undefined && item.costPrice !== null ? item.costPrice : '';
    if (recordPurchaseEl) recordPurchaseEl.checked = false;
    window.updatePreviewModalInventory();

    if (formTitle) formTitle.innerHTML = `<i class="fa-solid fa-pen-to-square text-indigo-500 mr-1.5"></i> Edit Bahan Baku: <span class="text-indigo-600">${item.name}</span>`;
    if (submitBtn) {
        submitBtn.innerHTML = `<i class="fa-solid fa-floppy-disk mr-1"></i> Simpan Perubahan`;
        submitBtn.className = "w-full bg-indigo-600 text-white py-3.5 rounded-xl font-black text-xs shadow-md hover:bg-indigo-700 transition tracking-wider uppercase";
    }
    if (cancelBtn) cancelBtn.classList.remove('hidden');

    const formContainer = document.getElementById('fi-form-container');
    if (formContainer) formContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

// Membatalkan mode edit bahan baku
