// =========================================================
// SISTEM NOTIFIKASI OTOMATIS WHATSAPP KE OWNER (STOK KRITIS)
// =========================================================
window.formatNomorWAInternasional = (noWA) => {
    let clean = String(noWA || '').trim().replace(/[-+ \(\)\.]/g, "");
    if (clean.startsWith("0")) {
        clean = "62" + clean.substring(1);
    } else if (clean.startsWith("8")) {
        clean = "62" + clean;
    }
    return clean;
};

window.getNomorWhatsAppOwner = () => {
    // 0. Cek dari Pengaturan Toko (store_settings.wa_owner)
    if (window.storeSettings && window.storeSettings.wa_owner && String(window.storeSettings.wa_owner).trim().length >= 8) {
        return {
            noWA: String(window.storeSettings.wa_owner).trim(),
            ownerName: window.storeSettings.store_title ? `Owner ${window.storeSettings.store_title}` : 'Owner Mainstay'
        };
    }
    // 1. Cek dari akun Master Owner terdaftar di database HRD
    if (typeof globalMasterOwner !== 'undefined' && globalMasterOwner) {
        for (const k in globalMasterOwner) {
            const wa = globalMasterOwner[k]?.wa;
            if (wa && String(wa).trim().length >= 8) {
                return {
                    noWA: String(wa).trim(),
                    ownerName: globalMasterOwner[k]?.name || 'Owner Mainstay'
                };
            }
        }
    }
    // 2. Cek override lokal jika ada
    const savedWa = localStorage.getItem('mainstay_owner_wa_restock');
    if (savedWa && savedWa.length >= 8) {
        return {
            noWA: savedWa,
            ownerName: 'Owner Mainstay'
        };
    }
    // 3. Fallback default no WhatsApp Owner/Resto
    return {
        noWA: '08977099557',
        ownerName: 'Master Owner'
    };
};

// Hubungi Owner via WhatsApp (Respon Cepat Staf Kasir ke Owner)
window.hubungiOwnerViaWa = () => {
    const { noWA, ownerName } = window.getNomorWhatsAppOwner();
    const cleanWa = window.formatNomorWAInternasional(noWA);
    const staffName = localStorage.getItem('mainstay_staff_name') || 'Kasir';
    const storeName = (window.storeSettings && window.storeSettings.store_title) || 'Mainstay Drink';
    const msg = `Halo ${ownerName}, saya ${staffName} (Staf Kasir ${storeName}).\nMohon info / respon cepat terkait operasional kedai saat ini.\nTerima kasih.`;
    window.open(`https://wa.me/${cleanWa}?text=${encodeURIComponent(msg)}`, '_blank');
};

window.kirimNotifikasiWaOwnerStokKritis = (options = {}) => {
    const rawKeys = Object.keys(globalInventory || {});
    let lowStockItems = [];

    if (options.singleKey && globalInventory && globalInventory[options.singleKey]) {
        const item = globalInventory[options.singleKey];
        const qty = Number(item.qty) || 0;
        const min = Number(item.minQty !== undefined ? item.minQty : 5);
        lowStockItems.push({
            key: options.singleKey,
            name: item.name || 'Bahan Baku',
            qty,
            min,
            unit: item.unit || 'Pcs',
            category: item.category || 'Bahan Baku'
        });
    } else {
        rawKeys.forEach(key => {
            const item = globalInventory[key];
            if (!item) return;
            const qty = Number(item.qty) || 0;
            const min = Number(item.minQty !== undefined ? item.minQty : 5);
            if (qty <= min) {
                lowStockItems.push({
                    key,
                    name: item.name || 'Bahan Baku',
                    qty,
                    min,
                    unit: item.unit || 'Pcs',
                    category: item.category || 'Bahan Baku'
                });
            }
        });
    }

    if (lowStockItems.length === 0) {
        const { noWA, ownerName } = window.getNomorWhatsAppOwner();
        const cleanWA = window.formatNomorWAInternasional(noWA);
        if (confirm(`Semua stok bahan baku saat ini dalam kondisi AMAN (tidak ada stok kritis).\n\nApakah Anda ingin membuka WhatsApp untuk chat/konsultasi langsung dengan Owner (${ownerName})?`)) {
            const pesan = encodeURIComponent(`Halo Kak ${ownerName}, saya dari bagian Gudang Mainstay Drink ingin berkonsultasi mengenai inventaris & stok bahan baku...`);
            window.open(`https://api.whatsapp.com/send?phone=${cleanWA}&text=${pesan}`, '_blank');
        }
        return;
    }

    const { noWA, ownerName } = window.getNomorWhatsAppOwner();
    const cleanWA = window.formatNomorWAInternasional(noWA);

    const now = new Date();
    const waktuStr = now.toLocaleDateString('id-ID', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });

    let pesan = `🚨 *PERINGATAN STOK KRITIS - MAINSTAY DRINK* 🚨\n\n`;
    pesan += `Halo Kak *${ownerName}*, sistem mendeteksi ada *${lowStockItems.length} bahan baku* yang telah mencapai/di bawah batas minimum (level kritis). Mohon segera dijadwalkan *RESTOCK*:\n\n`;

    lowStockItems.forEach((item, idx) => {
        const statusBadge = item.qty <= 0 ? '🔴 *HABIS (0)*' : '⚠️ *KRITIS*';
        pesan += `${idx + 1}. *${item.name}*\n`;
        pesan += `   • Sisa Stok: *${item.qty} ${item.unit}*\n`;
        pesan += `   • Batas Minimum: ${item.min} ${item.unit}\n`;
        pesan += `   • Status: ${statusBadge}\n`;
        pesan += `   • Kategori: ${item.category}\n\n`;
    });

    pesan += `⏰ *Waktu Pengecekan:* ${waktuStr} WIB\n`;
    pesan += `💡 *Tindakan:* Mohon segera lakukan pemesanan kembali (purchase order) ke supplier agar operasional gerai tetap lancar.\n\n`;
    pesan += `_Otomatis dikirim via Sistem POS & Inventory Mainstay Drink_`;

    const encodedPesan = encodeURIComponent(pesan);
    const waUrl = `https://api.whatsapp.com/send?phone=${cleanWA}&text=${encodedPesan}`;

    // Tampilkan Modal Interaktif / Konfirmasi Langsung Kirim
    window.tampilkanModalKirimWaStok(cleanWA, ownerName, lowStockItems, waUrl, pesan);
};

