window._financeHubActiveTab = window._financeHubActiveTab || 'pengeluaran';

window.renderLaporanTargetStatusStrip = (state) => {
    const strip = document.getElementById('lap-target-status-strip');
    if (!strip || !state) return;
    const selectedBid = state.scope && state.scope !== 'global' ? state.scope : (window.ACTIVE_BRANCH_ID || 'pusat');
    const p = typeof window.getMergedBranchFinanceParam === 'function' ? window.getMergedBranchFinanceParam(selectedBid) : { hariBukaBulan: 26, sewaBulanan: 0, persenSinkingFund: 5, persenTargetProfit: 25, nominalBonusHarian: 50000, targetBonusExtraPct: 10, bobotPersen: 100 };
    const cfg = typeof window.getFinanceConfig === 'function' ? window.getFinanceConfig() : { splitMode: 'rata', centralSharedOpsMonthly: 0 };
    const matchedStat = (state.perOutletStats || []).find(o => o.id === selectedBid) || state.perOutletStats?.[0] || {};
    const daysR = Math.max(1, state.daysInRange || 1);
    const estKul = Math.round(((matchedStat.kulakan || 0) / daysR) * p.hariBukaBulan);
    const estOps = Math.round(((matchedStat.bebanOps || 0) / daysR) * p.hariBukaBulan);
    const estGaji = Number(matchedStat.gajiBulanan || 0);
    const allOutlets = [{ id: 'pusat' }, ...Object.keys(window.globalBranches || {}).map(id => ({ id }))];
    const totalWeight = allOutlets.reduce((s, o) => s + (window.getMergedBranchFinanceParam ? window.getMergedBranchFinanceParam(o.id).bobotPersen : 100), 0) || 1;
    const weightShare = cfg.splitMode === 'bobot' ? (p.bobotPersen / totalWeight) : (1 / Math.max(1, allOutlets.length));
    const centralAlloc = Math.round(Number(cfg.centralSharedOpsMonthly || 0) * weightShare);
    const totalBiaya = estKul + estOps + estGaji + p.sewaBulanan + centralAlloc;
    const bebanSinking = totalBiaya + Math.round(totalBiaya * (p.persenSinkingFund / 100));
    const profitRp = Math.round(bebanSinking * (p.persenTargetProfit / 100));
    const t1 = Math.max(0, Math.round(bebanSinking / p.hariBukaBulan));
    const baseT2 = Math.max(0, Math.round((bebanSinking + profitRp) / p.hariBukaBulan));
    const roll = typeof window.computeMonthlyRolloverForBundle === 'function'
        ? window.computeMonthlyRolloverForBundle(matchedStat.rawBundle?.orders || window.globalOrders || {}, baseT2, p.hariBukaBulan)
        : { todayActual: 0, rolloverPerHari: 0 };
    const t2 = baseT2 + (roll.rolloverPerHari || 0);
    const t3 = Math.round(t2 * (1 + (p.targetBonusExtraPct / 100)));

    strip.innerHTML = `
        <div class="p-2.5 rounded-xl bg-white/10 border border-white/10">
            <span class="text-slate-300 font-bold block">Tahap 1: Titik Impas Biaya</span>
            <span class="text-xs font-black text-amber-300 mt-0.5 block">${formatUang(t1)} / hari</span>
        </div>
        <div class="p-2.5 rounded-xl bg-white/10 border border-white/10">
            <span class="text-slate-300 font-bold block">Tahap 2: Target Profit Owner</span>
            <span class="text-xs font-black text-emerald-300 mt-0.5 block">${formatUang(t2)} / hari</span>
        </div>
        <div class="p-2.5 rounded-xl bg-white/10 border border-white/10">
            <span class="text-slate-300 font-bold block">Tahap 3: Bonus Tim (${formatUang(p.nominalBonusHarian)})</span>
            <span class="text-xs font-black text-sky-300 mt-0.5 block">${formatUang(t3)} / hari</span>
        </div>
    `;
};

window.ensureFinanceHubDataState = async (forceRefresh = false) => {
    if (!forceRefresh && window._currentLaporanState && Array.isArray(window._currentLaporanState.perOutletStats)) {
        return window._currentLaporanState;
    }
    const today = new Date();
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, '0');
    const dd = String(today.getDate()).padStart(2, '0');
    const startDate = `${yyyy}-${mm}-01`;
    const endDate = `${yyyy}-${mm}-${dd}`;
    const daysInRange = Math.max(1, today.getDate());

    const activeScope = window.IS_BRANCH_OUTLET ? (window.ACTIVE_BRANCH_ID || 'pusat') : 'global';
    const { scope, scopeLabel, bundles } = await window.fetchFinancialBundleForScope(activeScope);

    const perOutletStats = [];
    const recentExpenses = [];

    bundles.forEach(bundle => {
        const st = {
            id: bundle.id,
            label: bundle.label,
            kulakan: 0,
            bebanOps: 0,
            gajiBulanan: 0,
            rawBundle: bundle
        };
        Object.values(bundle.stockPurchases || {}).forEach(p => {
            if (!p || typeof p !== 'object') return;
            const dt = typeof parseOrderDateToObj === 'function' ? parseOrderDateToObj(p) : null;
            if (!dt) return;
            const iso = formatLocalIsoDate(dt);
            if (iso >= startDate && iso <= endDate) st.kulakan += Number(p.totalCost || 0);
        });
        Object.entries(bundle.expenses || {}).forEach(([ek, exp]) => {
            if (!exp || typeof exp !== 'object') return;
            const nom = Number(exp.amount || exp.nominal || 0);
            if (nom <= 0) return;
            const dt = typeof parseOrderDateToObj === 'function' ? parseOrderDateToObj(exp) : null;
            const iso = dt ? formatLocalIsoDate(dt) : (exp.isoDate || exp.date || '');
            if (iso >= startDate && iso <= endDate && !exp.isKulakanStok) {
                st.bebanOps += nom;
            }
            recentExpenses.push({
                key: ek,
                outletId: bundle.id,
                outletLabel: bundle.label,
                category: exp.category || 'Operasional',
                note: exp.description || exp.title || exp.category || '-',
                amount: nom,
                channel: exp.paymentChannel || 'tunai',
                isoDate: iso || '-',
                timestamp: Number(exp.timestamp || 0)
            });
        });
        Object.values(bundle.staff || {}).forEach(s => {
            if (!s || typeof s !== 'object') return;
            const baseSalary = Number(s.salary || 0);
            const uangMakanHarian = Math.max(0, Number(s.uangMakanHarian || 0));
            if (baseSalary <= 0 && uangMakanHarian <= 0) return;
            const payLower = String(s.payType || 'Per Bulan').toLowerCase();
            const shiftHours = typeof parseShiftDurationHours === 'function' ? parseShiftDurationHours(s.shiftIn, s.shiftOut) : 8;
            const bParam = typeof window.getMergedBranchFinanceParam === 'function' ? window.getMergedBranchFinanceParam(bundle.id) : { hariBukaBulan: 26 };
            let mBase = 0;
            if (baseSalary > 0) {
                if (payLower.includes('hari')) mBase = Math.round(baseSalary * bParam.hariBukaBulan);
                else if (payLower.includes('jam')) mBase = Math.round(baseSalary * shiftHours * bParam.hariBukaBulan);
                else mBase = Math.round(baseSalary);
            }
            st.gajiBulanan += mBase + Math.round(uangMakanHarian * bParam.hariBukaBulan);
        });
        perOutletStats.push(st);
    });

    recentExpenses.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
    window._financeHubRecentExpenses = recentExpenses;
    window._financeHubBundles = bundles;

    window._currentLaporanState = {
        ...(window._currentLaporanState || {}),
        scope,
        scopeLabel,
        startDate,
        endDate,
        daysInRange,
        perOutletStats
    };
    return window._currentLaporanState;
};

