    const s = window.resolveEffectiveBranchSettings ? window.resolveEffectiveBranchSettings(rawSettings) : rawSettings;
    window._tempCarouselSlides = (s.carousel_slides && Array.isArray(s.carousel_slides) && s.carousel_slides.length > 0)
