    const bannerLocationText = s.banner_location_text !== undefined ? s.banner_location_text : (((window.globalBranches || {})[window.ACTIVE_BRANCH_ID || '']?.location) || (window.ACTIVE_BRANCH_ID && window.ACTIVE_BRANCH_ID !== 'pusat' ? '' : (s.footer_address || '')));
    const footerAddress = s.footer_address !== undefined ? s.footer_address : 'Jl. Menoreh Utara IX No.14, Sampangan, Kec. Gajahmungkur, Kota Semarang, Jawa Tengah 50232';
    const footerMapsUrl = s.footer_maps_url || 'https://maps.app.goo.gl/3QW7bBw7yN2x7w2A6';
    const footerMapsIframe = s.footer_maps_iframe || 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3960.0526970420993!2d110.39050517587635!3d-7.003080468593452!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e708b53cfeb86c7%3A0xebe7847c23a7fa48!2sMainstay%20drink!5e0!3m2!1sid!2sid!4v1741634580000!5m2!1sid!2sid';
    const footerMapsInput = s.footer_maps_input || s.footer_maps_iframe || s.footer_maps_url || 'https://maps.google.com/maps?q=-6.9412973,110.5089463&t=&z=18&ie=UTF8&iwloc=&output=embed';
    const embedPreviewUrl = window.convertAnyMapsUrlToEmbed(footerMapsInput);
    const socialWa = s.social_wa || '08977099557';
    const socialIg = s.social_ig || '@mainstay.drink';
    const socialTiktok = s.social_tiktok || '@mainstaydrink';
    const footerCopyright = s.footer_copyright || '&copy; 2026 Mainstay Drink. Hak Cipta Dilindungi.';
    const waOwner = s.wa_owner || '08977099557';
    const ownerEmail = s.owner_email || '';
    const autoPdfReport = s.auto_pdf_report_email === true;
    const pdfReportFreq = s.pdf_report_frequency || 'harian';
    const targetOmzetHarian = Number(s.target_omzet_harian || 0) || '';
    const receiptFooter = s.receipt_footer !== undefined ? s.receipt_footer : 'Terima kasih atas kunjungan Anda!\nNikmati kesegaran minuman kami.';
    const receiptSocialHandles = s.receipt_social_handles || '';
    const receiptHolidayGreeting = s.receipt_holiday_greeting || '';
    const thermalMargins = typeof window.getThermalReceiptMargins === 'function'
