    const carouselLogoSize = (window.CAROUSEL_LOGO_SIZE_MAP && window.CAROUSEL_LOGO_SIZE_MAP[s.carousel_logo_size]) ? s.carousel_logo_size : 'md';
    const carouselLogoOpacity = Math.max(20, Math.min(100, Number(s.carousel_logo_opacity ?? 94) || 94));
    const escAttr = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const previewCombinedReceiptFooter = typeof window.getFormattedReceiptFooter === 'function'
