                <div class="flex items-center gap-2 shrink-0">
                    <span id="store-settings-save-indicator" class="hidden px-2.5 py-1.5 rounded-xl bg-emerald-500/20 border border-emerald-400/40 text-emerald-200 text-[10px] font-black items-center gap-1 whitespace-nowrap">
                        <i class="fa-solid fa-circle-check text-emerald-400"></i>
                        <span>Tersimpan</span>
                    </span>
                    <button type="button" id="btn-save-store-top" onclick="window.simpanSemuaPengaturanToko()" class="bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white text-xs font-black px-4 py-2 rounded-xl flex items-center gap-1.5 shadow-sm transition cursor-pointer whitespace-nowrap">
                        <i class="fa-solid fa-floppy-disk"></i> <span>Simpan</span>
                    </button>
                </div>
