// 1. ENGINE PERHITUNGAN POINTS & LOYALTY (Simple Points System)
window.getMemberPoints = (member) => {
    if (!member) return 0;
    if (typeof member.points === 'number' && !isNaN(member.points)) return member.points;
    if (typeof member.poin === 'number' && !isNaN(member.poin)) return member.poin;
    const sessions = Number(member.sessions || 0);
    const stamps = Number(member.stamps || 0);
    return (sessions * 10) + (stamps * 2);
};

window.hitungStampDanSesi = (stampsLama = 0, sesiLama = 0, tambahStamp = 1, pointsLama = null) => {
    const curPoints = (pointsLama !== null && pointsLama !== undefined && !isNaN(pointsLama))
        ? Number(pointsLama)
        : ((Number(sesiLama || 0) * 10) + (Number(stampsLama || 0) * 2));
    const addedPoints = Number(tambahStamp || 1) * 2;
    const newPoints = curPoints + addedPoints;
    return {
        stamps: 0,
        sessions: Math.floor(newPoints / 10),
        newSessionsAdded: 0,
        points: newPoints
    };
};

