window.kirimBuktiGabungMemberWA = async (source = 'register') => {
    const mode = source === 'checkout' ? 'checkout' : 'register';
    const prefix = mode === 'checkout' ? 'co-wa' : 'reg-wa';

    const nameEl = document.getElementById(mode === 'checkout' ? 'co-name' : 'reg-member-name');
    const phoneEl = document.getElementById(mode === 'checkout' ? 'co-phone' : 'reg-member-phone');
    const confirmEl = document.getElementById(mode === 'checkout' ? 'co-member-wa-confirm' : 'reg-wa-confirm-check');
    const statusBox = document.getElementById(`${prefix}-proof-status`);

    const nama = (nameEl?.value || '').trim();
    const rawPhone = (phoneEl?.value || '').trim();
    const cleanPhone = rawPhone.replace(/\D/g, '');

    if (!nama) {
        alert('Silakan isi Nama Lengkap terlebih dahulu sebelum mengirim draft ACC ke WhatsApp!');
        nameEl?.focus();
        return;
    }
    if (!cleanPhone || cleanPhone.length < 9) {
        alert('Silakan isi Nomor WhatsApp aktif (minimal 9 digit) sebelum mengirim draft ACC!');
        phoneEl?.focus();
        return;
    }

    const ownerInfo = typeof window.getNomorWhatsAppOwner === 'function'
        ? window.getNomorWhatsAppOwner()
        : { noWA: '628977099557', ownerName: 'Owner / Admin Mainstay' };

    const cleanOwnerWA = typeof window.formatNomorWAInternasional === 'function'
        ? window.formatNomorWAInternasional(ownerInfo.noWA)
        : (String(ownerInfo.noWA || '628977099557').replace(/\D/g, '').replace(/^0/, '62') || '628977099557');

    const storeTitle = (window.storeSettings && (window.storeSettings.store_title || window.storeSettings.store_name)) || 'Mainstay Drink';
    const waktuStr = new Date().toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) + ' WIB';
    const jalurDaftar = mode === 'checkout' ? 'Checkout Pesanan + Daftar Member' : 'Formulir Daftar Member';

    const draftPesan =
        `Halo Admin/Owner *${storeTitle}*, 👋\n` +
        `Saya ingin mengirimkan *Draft Pengajuan & Screenshot Bukti Gabung Grup WA* untuk aktivasi *ACC Member Baru* (maks. *1x24 jam*).\n\n` +
        `📋 *DATA CALON MEMBER:*\n` +
        `• Nama Lengkap: *${nama}*\n` +
        `• No. WhatsApp: *${rawPhone}*\n` +
        `• Jalur Daftar: ${jalurDaftar}\n` +
        `• Status Grup WA: Sudah bergabung ke Grup WA Broadcast Resmi ✅\n` +
        `• Waktu Pengajuan: ${waktuStr}\n\n` +
        `📸 *Bukti Screenshot:* Saya lampirkan foto screenshot bukti gabung Grup WA berbarengan dengan pesan draft ini.\n\n` +
        `Mohon bantuannya untuk ACC member saya agar saldo *Points* aktif ya Kak. Terima kasih! 🙏`;

    const waUrl = `https://wa.me/${cleanOwnerWA}?text=${encodeURIComponent(draftPesan)}`;
    const popupWin = window.open(waUrl, '_blank');
    if (!popupWin) {
        window.location.href = waUrl;
    }

    if (confirmEl) confirmEl.checked = true;

    if (statusBox) {
        statusBox.innerHTML = `
            <p>✅ Draft pengajuan <b>ACC 1x24 Jam</b> sudah dibuka ke WhatsApp Admin (<b>+${cleanOwnerWA}</b>). Silakan lampirkan/kirim screenshot bukti gabung grup Anda berbarengan di chat WhatsApp tersebut.</p>
        `;
        statusBox.classList.remove('hidden');
    }
};

