// 4. INSTANT CLAIM & AUTO-APPLY REWARDS KE KERANJANG DI CHECKOUT
window.cekMemberCheckout = (rawPhone) => {
    const phone = String(rawPhone || '').replace(/\D/g, '');
    const statusBox = document.getElementById('co-member-status-box');
    const joinContainer = document.getElementById('co-member-join-container');
    if (!statusBox) return;

    if (phone.length < 9) {
        statusBox.classList.add('hidden');
        statusBox.innerHTML = '';
        if (joinContainer) joinContainer.classList.remove('hidden');
        return;
    }

    const members = window.cachedMembers || {};
    const member = members[phone];

    if (member) {
        if (joinContainer) joinContainer.classList.add('hidden');
        statusBox.classList.remove('hidden');

        const memberPoints = window.getMemberPoints(member);
        const rewards = Object.values(window.cachedLoyaltyRewards || {}).filter(r => r.isActive !== false);

        let claimHtml = '';
        if (memberPoints > 0) {
            const claimable = rewards.filter(r => {
                const reqPts = Number(r.pointsRequired || (Number(r.sesiRequired || 1) * 10));
                return reqPts <= memberPoints;
            });
            if (claimable.length > 0) {
                claimHtml = `
                    <div class="mt-2.5 pt-2 border-t border-amber-200">
                        <p class="text-[10px] font-black text-amber-900 uppercase tracking-wide mb-1.5 flex items-center gap-1">
                            <i class="fa-solid fa-gift text-amber-600"></i> Hadiah Siap Ditukarkan (Gratis Rp 0):
                        </p>
                        <div class="space-y-1.5 max-h-36 overflow-y-auto pr-1">
                            ${claimable.map(rew => {
                                const reqPts = Number(rew.pointsRequired || (Number(rew.sesiRequired || 1) * 10));
                                const rewNama = rew.nama || rew.title || 'Hadiah';
                                const discVal = Number(rew.discountValue || 0);
                                const discBadge = rew.tipe === 'diskon' && discVal > 0
                                    ? (rew.discountType === 'persen' ? `Diskon ${discVal}%` : `Potongan Rp ${discVal.toLocaleString('id-ID')}`)
                                    : '';
                                return `
                                <div class="flex items-center justify-between bg-white p-2 rounded-xl border border-amber-200 shadow-xs">
                                    <div class="min-w-0 flex-1 pr-2">
                                        <p class="text-xs font-black text-slate-800 truncate">${rewNama}</p>
                                        <p class="text-[9px] text-amber-700 font-bold">Biaya: ${reqPts} Points ${discBadge ? `&bull; <span class="text-emerald-700">${discBadge}</span>` : ''} &bull; Berlaku ${rew.validityDays || 30} Hari</p>
                                    </div>
                                    <button type="button" onclick="window.klaimRewardKeKeranjang('${rew.id}', '${rewNama.replace(/'/g, "\\'")}', ${reqPts})" class="bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white font-black text-[10px] px-2.5 py-1.5 rounded-lg transition shrink-0 shadow-xs">
                                        ${discBadge ? 'Pakai Diskon' : 'Klaim (Rp 0)'}
                                    </button>
                                </div>
                                `;
                            }).join('')}
                        </div>
                    </div>
                `;
            } else {
                claimHtml = `
                    <p class="text-[10px] text-amber-800 font-medium mt-1.5">
                        Anda memiliki <strong>${memberPoints} Points</strong>. Kumpulkan lebih banyak Points untuk menukarkan hadiah di katalog!
                    </p>
                `;
            }
        } else {
            claimHtml = `
                <p class="text-[10px] text-amber-800 font-medium mt-1.5">
                    Points Anda saat ini: <strong>0 Points</strong>. Dapatkan Points otomatis di setiap pesanan!
                </p>
            `;
        }

        statusBox.innerHTML = `
            <div class="bg-gradient-to-r from-amber-50 to-orange-50 border border-amber-300 rounded-xl p-3 shadow-xs">
                <div class="flex items-center justify-between">
                    <div class="flex items-center gap-2">
                        <div class="w-7 h-7 shrink-0 bg-amber-500 text-white rounded-lg flex items-center justify-center text-xs font-black shadow-xs">
                            <i class="fa-solid fa-crown"></i>
                        </div>
                        <div>
                            <p class="text-xs font-black text-slate-900 leading-tight">Member: ${member.name || phone}</p>
                            <p class="text-[10px] text-amber-700 font-bold">Status: Aktif &bull; Poin Loyalitas</p>
                        </div>
                    </div>
                    <span class="bg-amber-500 text-white text-[10px] font-black px-2.5 py-1 rounded-full shadow-xs">
                        ⭐ ${memberPoints} Points
                    </span>
                </div>
                ${claimHtml}
            </div>
        `;
    } else {
        statusBox.classList.add('hidden');
        statusBox.innerHTML = '';
        if (joinContainer) joinContainer.classList.remove('hidden');
    }
};

window.klaimRewardKeKeranjang = (rewardId, rewardNama, rewardPoints) => {
    const exists = cart.find(i => i.isLoyaltyReward && i.rewardId === rewardId);
    if (exists) {
        return alert(`Hadiah "${rewardNama}" sudah ada di keranjang Anda!`);
    }

    const rew = (window.cachedLoyaltyRewards || {})[rewardId] || {};
    const pts = Number(rewardPoints || rew.pointsRequired || 10);
    const isDiscountReward = rew.tipe === 'diskon' && Number(rew.discountValue || 0) > 0;
    const discVal = Number(rew.discountValue || 0);
    const discType = rew.discountType === 'persen' ? 'persen' : 'nominal';
    const minOrder = Number(rew.minOrder || 0);
    const discLabel = isDiscountReward
        ? (discType === 'persen' ? `Diskon ${discVal}%` : `Potongan Rp ${discVal.toLocaleString('id-ID')}`)
        : '';

    const rewardItem = {
        id: 'reward_' + (rewardId || Date.now()),
        name: isDiscountReward ? `[VOUCHER HADIAH] ${rewardNama} (${discLabel})` : `[HADIAH] ${rewardNama}`,
        price: 0,
        qty: 1,
        total: 0,
        isLoyaltyReward: true,
        rewardId: rewardId,
        costPoints: pts,
        costSessions: Math.max(1, Math.ceil(pts / 10)),
        discountType: isDiscountReward ? discType : null,
        discountValue: isDiscountReward ? discVal : 0,
        notes: isDiscountReward
            ? `Klaim Voucher ${discLabel} (Tukar ${pts} Points)`
            : `Klaim Hadiah Loyalty (Tukar ${pts} Points)`
    };

    cart.push(rewardItem);

    if (isDiscountReward) {
        window.appliedCheckoutVoucher = {
            kode: `POIN-${String(rewardId || 'REWARD').replace(/^rew_?/i, '').slice(-6).toUpperCase()}`,
            nama: rewardNama,
            tipe: discType,
            nilai: discVal,
            minPembelian: minOrder,
            fromLoyaltyRewardId: rewardId
        };
    }

    if (typeof window.updateCartBadge === 'function') window.updateCartBadge(true);
    if (typeof window.bukaModalCheckout === 'function') window.bukaModalCheckout();
    if (isDiscountReward) {
        alert(`Voucher "${rewardNama}" (${discLabel}) berhasil diterapkan ke pesanan Anda!`);
    } else {
        alert(`Hadiah "${rewardNama}" berhasil dimasukkan ke keranjang seharga Rp 0!`);
    }
};

