window.getConfiguredLoyaltyTiers = () => {
    const rawSaved = window.loyaltyConfig?.tiers;
    const savedMap = {};
    if (Array.isArray(rawSaved)) {
        rawSaved.forEach(item => {
            if (item && item.id) savedMap[item.id] = item;
        });
    } else if (rawSaved && typeof rawSaved === 'object') {
        Object.entries(rawSaved).forEach(([k, v]) => {
            if (v && typeof v === 'object') savedMap[v.id || k] = { ...v, id: v.id || k };
        });
    }

    return window.DEFAULT_MEMBER_TIERS.map(def => {
        const ov = savedMap[def.id] || {};
        const perksList = Array.isArray(ov.perks)
            ? ov.perks.map(p => String(p || '').trim()).filter(Boolean)
            : (typeof ov.perks === 'string' ? ov.perks.split('\n').map(s => s.trim()).filter(Boolean) : def.perks);

        let claimableRewards = [];
        if (Array.isArray(ov.claimableRewards)) {
            claimableRewards = ov.claimableRewards
                .filter(item => item && String(item.label || '').trim())
                .map(item => ({
                    rewardType: window.LOYALTY_REWARD_TYPES[item.rewardType] ? item.rewardType : 'free_drink',
                    label: String(item.label || '').trim(),
                    description: String(item.description || '').trim(),
                    rewardId: String(item.rewardId || '').trim(),
                    pointsCost: Math.max(0, Number(item.pointsCost || 0) || 0)
                }));
        } else if (ov.rewards !== undefined) {
            const legacyArr = Array.isArray(ov.rewards)
                ? ov.rewards.map(r => String(r || '').trim()).filter(Boolean)
                : String(ov.rewards || '').split('\n').map(s => s.trim()).filter(Boolean);
            claimableRewards = legacyArr.map(lbl => ({
                rewardType: /diskon|potongan|voucher/i.test(lbl) ? (/\%/.test(lbl) ? 'discount_percent' : 'discount_nominal') : (/topping/i.test(lbl) ? 'free_topping' : (/poin/i.test(lbl) ? 'bonus_points' : 'free_drink')),
                label: lbl,
                description: '',
                rewardId: '',
                pointsCost: 0
            }));
        } else {
            claimableRewards = (def.claimableRewards || []).map(c => ({ ...c }));
        }

        const rewardsList = claimableRewards.length > 0
            ? claimableRewards.map(c => c.label)
            : (ov.rewards !== undefined
                ? (Array.isArray(ov.rewards) ? ov.rewards.map(r => String(r || '').trim()).filter(Boolean) : [])
                : (def.rewards || []));

        const termsList = ov.terms !== undefined
            ? (Array.isArray(ov.terms)
                ? ov.terms.map(s => String(s || '').trim()).filter(Boolean)
                : String(ov.terms || '').split('\n').map(s => s.trim()).filter(Boolean))
            : (def.terms || []);

        const themeKey = window.MEMBER_TIER_THEMES[ov.cardTheme] ? ov.cardTheme : def.cardTheme;
        return {
            id: def.id,
            name: String(ov.name || def.name).trim() || def.name,
            minPoints: Math.max(0, Number(ov.minPoints !== undefined ? ov.minPoints : def.minPoints) || 0),
            cardTheme: themeKey,
            theme: window.MEMBER_TIER_THEMES[themeKey] || window.MEMBER_TIER_THEMES.gold,
            tierDescription: String(ov.tierDescription !== undefined ? ov.tierDescription : (def.tierDescription || '')).trim(),
            perks: perksList.length > 0 ? perksList : def.perks,
            rewards: rewardsList,
            claimableRewards,
            terms: termsList
        };
    }).sort((a, b) => a.minPoints - b.minPoints);
};

window.getMemberTierInfo = (member) => {
    const tiers = window.getConfiguredLoyaltyTiers();
    const points = member ? (typeof window.getMemberPoints === 'function' ? window.getMemberPoints(member) : Number(member.points || 0)) : 0;
    const overrideId = member?.tierOverride ? String(member.tierOverride).trim().toLowerCase() : '';

    let currentTierIdx = 0;
    let isManualOverride = false;
    if (overrideId) {
        const ovIdx = tiers.findIndex(t => t.id === overrideId);
        if (ovIdx >= 0) {
            currentTierIdx = ovIdx;
            isManualOverride = true;
        }
    }
    if (!isManualOverride) {
        tiers.forEach((t, idx) => {
            if (points >= t.minPoints) currentTierIdx = idx;
        });
    }

    const currentTier = tiers[currentTierIdx] || tiers[0];
    const nextTier = tiers[currentTierIdx + 1] || null;
    return { tiers, currentTier, currentTierIdx, nextTier, points, isManualOverride };
};

window.cekStampMember = async () => {
    const phoneInput = document.getElementById('stamp-phone-check');
    const clearBtn = document.getElementById('btn-clear-stamp-phone');
    const feedbackEl = document.getElementById('stamp-check-feedback');
    const feedbackTitle = document.getElementById('stamp-feedback-title');
    const feedbackDesc = document.getElementById('stamp-feedback-desc');
    const feedbackRegBtn = document.getElementById('btn-stamp-feedback-register');
    const resultArea = document.getElementById('stamp-result-area');

    const rawPhone = phoneInput ? phoneInput.value : '';
    const rawDigits = String(rawPhone || '').replace(/\D/g, '');
    const cleanLookup = typeof window.normalizeMemberPhone === 'function'
        ? window.normalizeMemberPhone(rawPhone)
        : (rawDigits.startsWith('62') ? '0' + rawDigits.slice(2) : rawDigits);

    if (clearBtn) {
        clearBtn.classList.toggle('hidden', rawPhone.trim().length === 0);
    }

    const showFeedback = (title, desc, allowRegister = false) => {
        if (resultArea) resultArea.classList.add('hidden');
        if (feedbackTitle) feedbackTitle.innerText = title;
        if (feedbackDesc) feedbackDesc.innerText = desc;
        if (feedbackRegBtn) feedbackRegBtn.classList.toggle('hidden', !allowRegister);
        if (feedbackEl) feedbackEl.classList.remove('hidden');
    };

    if (!cleanLookup || cleanLookup.length < 9) {
        window._lastCheckedMissingPhone = '';
        showFeedback(
            rawDigits.length === 0 ? 'Nomor WhatsApp Belum Diisi' : 'Nomor WhatsApp Kurang Lengkap',
            'Masukkan nomor WhatsApp yang valid (minimal 9 digit) untuk memeriksa kartu member, atau tekan Ulang Input Nomor.',
            false
        );
        if (phoneInput) phoneInput.focus();
        return;
    }

    const members = window.cachedMembers || {};
    const match = typeof window.cariMemberByPhone === 'function' ? window.cariMemberByPhone(cleanLookup) : null;
    let member = (match && match.member) || members[rawDigits] || members[cleanLookup] || null;
    let resolvedPhone = (match && match.standardPhone) || cleanLookup;

    if (!member && typeof navigator !== 'undefined' && navigator.onLine !== false) {
        try {
            const snap = await get(ref(db, `members/${cleanLookup}`));
            if (snap.exists()) {
                member = snap.val();
                window.cachedMembers = window.cachedMembers || {};
                window.cachedMembers[cleanLookup] = member;
                resolvedPhone = cleanLookup;
            } else if (rawDigits && rawDigits !== cleanLookup) {
                const snapRaw = await get(ref(db, `members/${rawDigits}`));
                if (snapRaw.exists()) {
                    member = snapRaw.val();
                    window.cachedMembers = window.cachedMembers || {};
                    window.cachedMembers[rawDigits] = member;
                    resolvedPhone = cleanLookup;
                }
            }
        } catch (err) {
            console.warn('Fallback lookup member RTDB gagal:', err);
        }
    }

    if (!member) {
        window._lastCheckedMissingPhone = cleanLookup;
        showFeedback(
            'Nomor Member Tidak Terdaftar',
            `Nomor "${rawPhone.trim() || cleanLookup}" belum terdaftar sebagai Member Mainstay. Anda dapat mengulang input nomor lain atau mendaftar sebagai Member baru.`,
            true
        );
        return;
    }

    window._lastCheckedMissingPhone = '';
    if (feedbackEl) feedbackEl.classList.add('hidden');
    if (!resultArea) return;
    resultArea.classList.remove('hidden');

    const tierInfo = window.getMemberTierInfo(member);
    const tiers = tierInfo.tiers;
    window.MEMBER_LOYALTY_TIERS = tiers;

    const displayName = member.name || member.nama || 'Member Mainstay';
    const displayPhone = member.phone || resolvedPhone || cleanLookup;
    const points = tierInfo.points;
    const bonusPoints = Math.max(0, Math.min(points, Number(member.bonusPoints ?? member.poinBonus ?? 0)));
    const basePoints = Math.max(0, points - bonusPoints);
    const isPendingAcc = member.accStatus === 'pending_acc';

    const currentTierIdx = tierInfo.currentTierIdx;
    const currentTier = tierInfo.currentTier;
    const nextTier = tierInfo.nextTier;
    const activeTheme = currentTier.theme || window.MEMBER_TIER_THEMES.gold;

    let progressPercent = 100;
    if (nextTier) {
        const span = Math.max(1, nextTier.minPoints - currentTier.minPoints);
        const gained = Math.max(0, points - currentTier.minPoints);
        progressPercent = Math.max(6, Math.min(100, Math.round((gained / span) * 100)));
    }

    const expiryDays = Number(window.loyaltyConfig?.expiryDays ?? 365);
    let expiryLabel = 'Aktif Selamanya';
    if (expiryDays > 0) {
        const baseTs = Number(member.lastActive || member.registeredAt || Date.now());
        const expDate = new Date(baseTs + (expiryDays * 86400000));
        const dd = String(expDate.getDate()).padStart(2, '0');
        const mm = String(expDate.getMonth() + 1).padStart(2, '0');
        const yyyy = expDate.getFullYear();
        expiryLabel = `Exp: ${dd}/${mm}/${yyyy}`;
    }

    const storeSettingsObj = window.storeSettings || window.defaultStoreSettings || {};
    const storeShortName = String(storeSettingsObj.store_title || storeSettingsObj.store_name || 'Mainstay').split(/\s+/)[0] || 'Mainstay';

    const qrPayload = `member:${displayPhone}`;
    let qrUrl = '';
    let qrThumbUrl = '';
    try {
        if (window.QRCode && typeof window.QRCode.toDataURL === 'function') {
            qrUrl = await window.QRCode.toDataURL(qrPayload, {
                width: 420,
                margin: 1,
                errorCorrectionLevel: 'M',
                color: { dark: '#0f172a', light: '#ffffff' }
            });
            qrThumbUrl = await window.QRCode.toDataURL(qrPayload, {
                width: 320,
                margin: 0,
                errorCorrectionLevel: 'M',
                color: { dark: '#0f172a', light: '#ffffff' }
            });
        } else {
            qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=1&data=${encodeURIComponent(qrPayload)}`;
            qrThumbUrl = `https://api.qrserver.com/v1/create-qr-code/?size=320x320&margin=0&data=${encodeURIComponent(qrPayload)}`;
        }
    } catch (err) {
        qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=1&data=${encodeURIComponent(qrPayload)}`;
        qrThumbUrl = qrUrl;
    }

    window._activeMemberCardData = {
        name: displayName,
        phone: displayPhone,
        points,
        basePoints,
        bonusPoints,
        tierName: currentTier.name,
        tierId: currentTier.id,
        tierIdx: currentTierIdx,
        tierTheme: activeTheme,
        expiryLabel,
        isPendingAcc,
        member,
        qrUrl,
        qrThumbUrl
    };
    window._activeViewedTierIdx = currentTierIdx;
    window._memberBreakdownExpanded = true;

    const stepperEl = document.getElementById('member-tier-stepper');
    const carouselEl = document.getElementById('member-tier-card-carousel');

    if (carouselEl) {
        carouselEl.innerHTML = tiers.map((t, idx) => {
            const tTheme = t.theme || window.MEMBER_TIER_THEMES.gold;
            const isCurrent = idx === currentTierIdx;
            const isUnlocked = idx <= currentTierIdx || points >= t.minPoints;
            const gapPts = Math.max(0, t.minPoints - points);
            const deltaFromCurrent = t.minPoints - currentTier.minPoints;

            let cardProgressPct = 100;
            let cardStatusText = `Selamat! Kamu anggota ${t.name}!`;
            if (isCurrent) {
                cardProgressPct = progressPercent;
                cardStatusText = nextTier
                    ? `+${Math.max(1, nextTier.minPoints - points).toLocaleString('id-ID')} poin lagi ke ${nextTier.name}`
                    : `Selamat! Kamu anggota ${currentTier.name}!`;
            } else if (!isUnlocked) {
                cardProgressPct = t.minPoints > 0 ? Math.max(5, Math.min(99, Math.round((points / t.minPoints) * 100))) : 0;
                cardStatusText = `Kurang ${gapPts.toLocaleString('id-ID')} poin lagi untuk membuka ${t.name}`;
            } else {
                cardProgressPct = 100;
                cardStatusText = `Tier ${t.name} sudah terbuka (${t.minPoints}+ poin)`;
            }

            const statusChip = isCurrent
                ? `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200"><i class="fa-solid fa-crown text-amber-500"></i> Tier Aktif Anda</span>`
                : (isUnlocked
                    ? `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-sky-100 text-sky-800 border border-sky-200"><i class="fa-solid fa-circle-check"></i> Sudah Terbuka</span>`
                    : `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-slate-200 text-slate-700 border border-slate-300"><i class="fa-solid fa-lock"></i> Terkunci (+${gapPts} Poin)</span>`);

            const diffCompareNote = isCurrent
                ? `Anda sedang berada di tier <strong>${t.name}</strong> (minimal ${t.minPoints} poin).`
                : (deltaFromCurrent > 0
                    ? `Naik level butuh <strong>+${deltaFromCurrent.toLocaleString('id-ID')} poin</strong> dari syarat ${currentTier.name} (${t.minPoints}+ poin).`
                    : `Tingkat di bawah ${currentTier.name} (${t.minPoints}+ poin) — seluruh keuntungannya sudah aktif.`);

            const leftQrOrLockHtml = isUnlocked
                ? `
                    <button type="button" onclick="window.bukaKartuMemberFullscreenLandscape()" class="member-loyalty-qr-btn relative z-10 rounded-xl bg-white hover:bg-amber-50 active:scale-95 p-[4px] shadow-sm border border-white/85 flex flex-col items-center justify-center gap-0.5 transition cursor-pointer group mx-auto" title="Klik untuk memperbesar QR Member">
                        <img ${isCurrent ? 'id="member-card-qr-img"' : ''} src="${qrThumbUrl || qrUrl}" alt="QR Member" class="w-[46px] h-[46px] sm:w-[52px] sm:h-[52px] aspect-square rounded-[4px] bg-white object-contain block mx-auto">
                        <span class="text-[7px] font-black text-slate-900 group-hover:text-amber-700 leading-none flex items-center justify-center gap-0.5 pt-0.5 whitespace-nowrap">
                            <i class="fa-solid fa-expand text-[6.5px]"></i> Zoom QR
                        </span>
                    </button>
                `
                : `
                    <div class="member-loyalty-qr-btn relative z-10 rounded-xl bg-slate-950/35 backdrop-blur-xs p-1.5 border border-white/25 flex flex-col items-center justify-center gap-1 text-center mx-auto">
                        <span class="w-6 h-6 rounded-full bg-white/20 flex items-center justify-center text-white text-[10px]">
                            <i class="fa-solid fa-lock"></i>
                        </span>
                        <span class="text-[7.5px] font-black text-white leading-tight">${t.minPoints}+ Poin</span>
                    </div>
                `;

            return `
                <div data-tier-card="${t.id}" data-tier-idx="${idx}" class="flex-none w-full snap-center space-y-2.5 min-w-0">
                    <!-- Rectangular Landscape / Portrait Adaptive Loyalty Card -->
                    <div ${isCurrent ? 'id="member-ktp-card"' : ''} class="member-card-content member-loyalty-card w-full min-h-[192px] sm:min-h-[214px] rounded-2xl border ${isCurrent ? 'border-amber-300/90 shadow-md' : 'border-slate-200/90 shadow-sm'} bg-white overflow-hidden flex items-stretch select-none">
                        <!-- Left / Top Tier Accent Strip -->
                        <div class="member-loyalty-strip w-[96px] sm:w-[108px] shrink-0 relative overflow-hidden flex flex-col justify-between gap-2 pl-2.5 pr-4 py-3 text-white" style="background: ${tTheme.stripGradient};">
                            <div class="w-20 h-20 rounded-full bg-black/10 absolute -right-8 top-8 pointer-events-none"></div>
                            <div class="w-20 h-20 rounded-full bg-black/10 absolute -left-6 top-20 pointer-events-none"></div>

                            <div class="relative z-10 flex flex-col items-start px-0.5 w-full">
                                <span ${isCurrent ? 'id="member-card-brand-label"' : ''} class="text-[11px] font-black tracking-tight text-white drop-shadow-xs leading-tight break-words">${storeShortName}</span>
                                <span class="text-[8px] font-extrabold text-white/95 tracking-wide mt-0.5 uppercase">${t.name} Card</span>
                            </div>

                            ${leftQrOrLockHtml}
                        </div>

                        <!-- Right / Bottom Crisp White Content Panel -->
                        <div class="member-card-content member-loyalty-body flex-1 min-w-0 bg-white rounded-l-[1.15rem] -ml-2.5 relative z-10 pl-4 pr-3.5 py-3 sm:pl-4 sm:pr-4 sm:py-3 flex flex-col justify-between gap-1.5">
                            <!-- Top Row: Title + Member Name/Phone -->
                            <div class="flex items-start justify-between gap-2">
                                <div class="min-w-0">
                                    <p class="text-[10px] sm:text-[11px] font-bold text-slate-800 leading-tight">${isCurrent ? 'Total Poin Kamu' : `Kartu Tier ${t.name}`}</p>
                                    <span class="text-[9px] font-extrabold uppercase tracking-wide" style="color: ${tTheme.accentText};">${t.minPoints}+ Poin</span>
                                </div>
                                <div class="text-right min-w-0">
                                    <p ${isCurrent ? 'id="stamp-member-name"' : ''} class="text-[10px] sm:text-[11px] font-black text-slate-900 leading-tight break-words">${displayName}</p>
                                    <p ${isCurrent ? 'id="stamp-member-phone"' : ''} class="text-[9px] font-mono font-semibold text-slate-500 leading-tight tabular-nums">${displayPhone}</p>
                                </div>
                            </div>

                            <!-- Hero Poin Row + Toggle + Riwayat -->
                            <div class="flex items-center justify-between gap-2">
                                <div class="flex items-center gap-1.5 min-w-0">
                                    <h3 ${isCurrent ? 'id="member-card-total-points"' : ''} class="text-xl sm:text-2xl font-black text-slate-900 tracking-tight tabular-nums leading-none">${points.toLocaleString('id-ID')} poin</h3>
                                    ${isCurrent ? `
                                        <button type="button" id="btn-toggle-member-breakdown" onclick="window.toggleMemberCardBreakdown()" class="w-6 h-6 shrink-0 rounded-full bg-slate-200/80 hover:bg-slate-300 text-slate-600 flex items-center justify-center transition cursor-pointer" aria-expanded="true" title="Tampilkan/Sembunyikan Rincian Poin">
                                            <i id="member-breakdown-chevron" class="fa-solid fa-chevron-up text-[9px] transition-transform duration-200"></i>
                                        </button>
                                    ` : ''}
                                </div>
                                <button type="button" onclick="window.toggleRiwayatPoinMember()" class="shrink-0 py-1 px-1.5 text-[11px] font-extrabold text-[#e65100] hover:text-[#bf360c] flex items-center gap-0.5 transition cursor-pointer whitespace-nowrap">
                                    <span>Riwayat</span>
                                    <i class="fa-solid fa-chevron-right text-[9px]"></i>
                                </button>
                            </div>

                            <!-- Compact Breakdown -->
                            <div ${isCurrent ? 'id="member-card-breakdown"' : ''} class="grid grid-cols-2 divide-x divide-slate-200/80 py-1">
                                <div class="pr-2 min-w-0">
                                    <p class="text-[9px] font-semibold text-slate-500 leading-tight">${isCurrent ? 'Poin Dasar' : 'Syarat Tier'}</p>
                                    <p ${isCurrent ? 'id="member-card-base-points"' : ''} class="text-xs sm:text-sm font-black text-slate-900 tabular-nums leading-tight">${isCurrent ? `${basePoints.toLocaleString('id-ID')} poin` : `${t.minPoints.toLocaleString('id-ID')} poin`}</p>
                                    <p ${isCurrent ? 'id="member-card-expiry-text"' : ''} class="text-[9px] font-medium text-slate-400 leading-tight mt-0.5">${isCurrent ? expiryLabel : `Tier ke-${idx + 1}`}</p>
                                </div>
                                <div class="pl-2.5 min-w-0">
                                    <p class="text-[9px] font-semibold text-slate-500 leading-tight">${isCurrent ? 'Poin Bonus' : 'Status Tier'}</p>
                                    <p ${isCurrent ? 'id="member-card-bonus-points"' : ''} class="text-xs sm:text-sm font-black text-slate-900 tabular-nums leading-tight">${isCurrent ? `${bonusPoints.toLocaleString('id-ID')} poin` : (isUnlocked ? 'Terbuka' : `+${gapPts} poin`)}</p>
                                    <p ${isCurrent ? 'id="stamp-session-badge"' : ''} class="text-[9px] font-bold leading-tight mt-0.5" style="color: ${tTheme.accentText};">${isPendingAcc ? 'Menunggu ACC (1x24j)' : `Tingkat ${t.name}${isCurrent && tierInfo.isManualOverride ? ' ★' : ''}`}</p>
                                </div>
                            </div>

                            <!-- Tier Progress Bar & Footer -->
                            <div class="space-y-1">
                                <div class="w-full h-2 rounded-full bg-slate-100 overflow-hidden">
                                    <div ${isCurrent ? 'id="member-tier-progress-fill"' : ''} class="h-full rounded-full transition-all duration-500" style="width: ${cardProgressPct}%; background: ${tTheme.progressGradient};"></div>
                                </div>
                                <div class="flex items-center justify-between gap-1.5">
                                    <p ${isCurrent ? 'id="member-tier-status-text"' : ''} class="text-[10px] font-bold text-slate-700 leading-tight flex-1 min-w-0">${cardStatusText}</p>
                                    <span ${isCurrent ? 'id="stamp-count-text"' : ''} class="text-[9px] font-black tabular-nums shrink-0" style="color: ${tTheme.accentText};">${points} Poin • ${t.name}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- Perbedaan, Hadiah & Keunggulan Tier (Ikut Slide Bareng Kartu di Atas) -->
                    <div class="member-tier-rewards-panel rounded-2xl border ${isCurrent ? 'border-amber-200 bg-amber-50/55' : 'border-slate-200 bg-slate-50/90'}">
                        <div class="flex items-center justify-between gap-2 flex-wrap">
                            <div class="flex items-center gap-1.5 min-w-0">
                                <span class="w-6 h-6 rounded-lg text-white flex items-center justify-center text-[10px] shrink-0 shadow-2xs" style="background: ${tTheme.pillBg};">
                                    <i class="fa-solid ${isUnlocked ? 'fa-crown' : 'fa-lock'}"></i>
                                </span>
                                <span class="text-xs font-black text-slate-900 leading-tight">Keunggulan &amp; Hadiah Tier ${t.name}</span>
                            </div>
                            ${statusChip}
                        </div>
                        <p class="text-[10px] font-medium text-slate-600 leading-snug bg-white/85 border border-slate-200/70 rounded-xl px-2.5 py-1.5">${diffCompareNote}${t.tierDescription ? ` <span class="text-slate-500">• ${String(t.tierDescription).replace(/</g, '&lt;')}</span>` : ''}</p>
                        ${((Array.isArray(t.claimableRewards) && t.claimableRewards.length > 0) || (Array.isArray(t.rewards) && t.rewards.length > 0)) ? `
                            <div class="rounded-xl border ${isUnlocked ? 'border-amber-200/90 bg-white' : 'border-slate-200/80 bg-white/70'} p-2.5 space-y-2">
                                <div class="flex items-center justify-between gap-1.5 flex-wrap">
                                    <span class="text-[10px] font-black uppercase tracking-wide flex items-center gap-1 ${isUnlocked ? 'text-amber-700' : 'text-slate-500'}">
                                        <i class="fa-solid fa-gift"></i> Hadiah yang Bisa Diklaim Tier ${t.name}
                                    </span>
                                    <span class="text-[9px] font-extrabold px-1.5 py-0.5 rounded shrink-0 ${isUnlocked ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}">${isUnlocked ? 'Siap Diklaim' : `${t.minPoints}+ Poin`}</span>
                                </div>
                                <div class="member-tier-rewards-grid">
                                    ${(t.claimableRewards && t.claimableRewards.length > 0 ? t.claimableRewards : t.rewards.map(r => ({ rewardType: 'free_drink', label: r, description: '', rewardId: '', pointsCost: 0 }))).map(cr => {
                                        const tMeta = window.getLoyaltyRewardTypeMeta(cr.rewardType);
                                        const linkedReward = cr.rewardId ? (window.cachedLoyaltyRewards || {})[cr.rewardId] : null;
                                        const ptsNeed = Number(cr.pointsCost || linkedReward?.pointsRequired || 0);
                                        const canDirectClaim = isUnlocked && linkedReward && points >= ptsNeed;
                                        const safeLbl = String(cr.label || linkedReward?.nama || 'Hadiah').replace(/'/g, "\\'");
                                        const rewardDesc = String(cr.description || '').trim();
                                        return `
                                            <div class="flex flex-col gap-1 max-w-full px-2.5 py-1.5 rounded-xl text-[10px] font-bold border break-words ${isUnlocked ? 'bg-amber-50/90 border-amber-200 text-slate-900' : 'bg-slate-100 border-slate-200 text-slate-500'}">
                                                <div class="flex items-center gap-1.5 flex-wrap">
                                                    <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[8.5px] font-black border shrink-0 ${isUnlocked ? tMeta.badgeClass : 'bg-slate-200 text-slate-500 border-slate-300'}">
                                                        <i class="fa-solid ${isUnlocked ? tMeta.icon : 'fa-lock'} text-[8px]"></i> ${tMeta.label}
                                                    </span>
                                                    <span class="min-w-0 font-black break-words">${String(cr.label || '').replace(/</g, '&lt;')}</span>
                                                    ${ptsNeed > 0 ? `<span class="text-[8.5px] font-black text-amber-700 shrink-0">(${ptsNeed}p)</span>` : ''}
                                                    ${canDirectClaim ? `
                                                        <button type="button" onclick="window.klaimRewardKeKeranjang('${linkedReward.id}', '${safeLbl}', ${ptsNeed}); window.closeModalStamp();" class="ml-auto px-1.5 py-0.5 rounded bg-emerald-600 hover:bg-emerald-700 text-white text-[8.5px] font-black shrink-0 cursor-pointer">Klaim</button>
                                                    ` : (isUnlocked && linkedReward ? `<button type="button" onclick="document.getElementById('member-claimable-list')?.scrollIntoView({behavior:'smooth', block:'nearest'})" class="ml-auto px-1.5 py-0.5 rounded bg-amber-500 text-slate-950 text-[8.5px] font-black shrink-0 cursor-pointer">Lihat</button>` : '')}
                                                </div>
                                                ${rewardDesc ? `<p class="text-[9.5px] font-medium leading-snug ${isUnlocked ? 'text-slate-600' : 'text-slate-400'}">${rewardDesc.replace(/</g, '&lt;')}</p>` : ''}
                                            </div>
                                        `;
                                    }).join('')}
                                </div>
                            </div>
                        ` : ''}
                        <ul class="space-y-1.5">
                            ${t.perks.map(p => `
                                <li class="flex items-start gap-1.5 text-[11px] leading-snug ${isUnlocked ? 'text-slate-800 font-semibold' : 'text-slate-500'}">
                                    <i class="fa-solid ${isUnlocked ? 'fa-circle-check text-emerald-600' : 'fa-lock text-slate-400'} mt-0.5 shrink-0 text-[10px]"></i>
                                    <span class="min-w-0 break-words">${p}</span>
                                </li>
                            `).join('')}
                        </ul>
                        ${Array.isArray(t.terms) && t.terms.length > 0 ? `
                            <div class="rounded-xl border border-slate-200 bg-white/90 px-2.5 py-2 space-y-1">
                                <p class="text-[9.5px] font-black uppercase tracking-wide text-slate-600 flex items-center gap-1">
                                    <i class="fa-solid fa-file-contract text-indigo-500"></i> Syarat &amp; Ketentuan Klaim Tier ${t.name}
                                </p>
                                <ul class="space-y-0.5 text-[10px] text-slate-600 font-medium leading-snug">
                                    ${t.terms.map(sk => `
                                        <li class="flex items-start gap-1.5">
                                            <span class="text-indigo-500 font-black">•</span>
                                            <span class="min-w-0 break-words">${sk}</span>
                                        </li>
                                    `).join('')}
                                </ul>
                            </div>
                        ` : ''}
                    </div>
                </div>
            `;
        }).join('');

        // Bind horizontal swipe scroll sync -> otomatis aktifkan & animasikan tombol kategori tier di atas!
        if (!carouselEl._tierScrollBound) {
            carouselEl._tierScrollBound = true;
            carouselEl.addEventListener('scroll', () => {
                clearTimeout(carouselEl._scrollDeb);
                carouselEl._scrollDeb = setTimeout(() => {
                    const slides = Array.from(carouselEl.querySelectorAll('[data-tier-card]'));
                    if (!slides.length) return;
                    const center = carouselEl.scrollLeft + (carouselEl.clientWidth / 2);
                    let bestIdx = 0;
                    let bestDist = Infinity;
                    slides.forEach((s, i) => {
                        const mid = s.offsetLeft + (s.offsetWidth / 2);
                        const d = Math.abs(center - mid);
                        if (d < bestDist) {
                            bestDist = d;
                            bestIdx = i;
                        }
                    });
                    if (window._activeViewedTierIdx !== bestIdx) {
                        window._activeViewedTierIdx = bestIdx;
                        window._renderMemberTierStepper(bestIdx);
                        window._syncTierSliderIndicators(bestIdx);
                    }
                }, 70);
            });
        }
    }

    if (typeof window._renderMemberTierStepper === 'function') {
        window._renderMemberTierStepper(currentTierIdx);
    }
    if (typeof window._syncTierSliderIndicators === 'function') {
        window._syncTierSliderIndicators(currentTierIdx);
    }

    // Geser carousel tepat ke kartu tier aktif milik member
    if (carouselEl) {
        requestAnimationFrame(() => {
            const slides = Array.from(carouselEl.querySelectorAll('[data-tier-card]'));
            const activeSlide = slides[currentTierIdx];
            if (activeSlide) {
                const left = Math.max(0, activeSlide.offsetLeft - (carouselEl.clientWidth - activeSlide.offsetWidth) / 2);
                carouselEl.scrollTo({ left, behavior: 'auto' });
            }
        });
    }

    if (typeof window.applyMemberCardDisplayMode === 'function') {
        window.applyMemberCardDisplayMode();
    }
    document.getElementById('member-points-history-panel')?.classList.add('hidden');

    // Render daftar hadiah yang siap diklaim oleh member ini
    const claimListEl = document.getElementById('member-claimable-list');
    if (claimListEl) {
        const rewards = Object.values(window.cachedLoyaltyRewards || {}).filter(r => r.isActive !== false);
        const claimable = rewards.filter(r => {
            const reqPts = Number(r.pointsRequired || (Number(r.sesiRequired || 1) * 10));
            return reqPts <= points;
        });

        if (points <= 0) {
            claimListEl.innerHTML = `
                <div class="text-center py-3 text-[11px] text-slate-500 font-medium">
                    Belum ada Points yang dapat ditukarkan.<br>Kumpulkan Points tiap belanja untuk membuka hadiah gratis!
                </div>
            `;
        } else if (claimable.length === 0) {
            claimListEl.innerHTML = `
                <div class="text-center py-3 text-[11px] text-slate-500 font-medium">
                    Anda memiliki <strong>${points} Points</strong>, kumpulkan lebih banyak Points untuk menukar hadiah di katalog.
                </div>
            `;
        } else {
            claimListEl.innerHTML = claimable.map(rew => {
                const reqPts = Number(rew.pointsRequired || (Number(rew.sesiRequired || 1) * 10));
                const rewNama = rew.nama || rew.title || 'Hadiah';
                const discVal = Number(rew.discountValue || 0);
                const discBadge = rew.tipe === 'diskon' && discVal > 0
                    ? (rew.discountType === 'persen' ? `Diskon ${discVal}%` : `Potongan Rp ${discVal.toLocaleString('id-ID')}`)
                    : '';
                return `
                <div class="flex items-center justify-between gap-2 p-2.5 bg-slate-50 rounded-xl border border-slate-200">
                    <div class="min-w-0 pr-2">
                        <p class="text-xs font-black text-slate-900 break-words leading-snug">${rewNama}</p>
                        <p class="text-[10px] text-amber-700 font-bold">Biaya: ${reqPts} Points${discBadge ? ` &bull; <span class="text-indigo-700">${discBadge}</span>` : ''}</p>
                    </div>
                    <button onclick="window.klaimRewardKeKeranjang('${rew.id}', '${rewNama.replace(/'/g, "\\'")}', ${reqPts}); window.closeModalStamp();" class="bg-amber-500 hover:bg-amber-600 active:scale-95 text-white font-black text-[10px] px-3 py-2 min-h-[36px] rounded-lg shadow-xs transition shrink-0 cursor-pointer">
                        ${discBadge ? 'Pakai Voucher' : 'Klaim (Rp 0)'}
                    </button>
                </div>
                `;
            }).join('');
        }
    }
};

window.toggleMemberCardBreakdown = () => {
    const breakdown = document.getElementById('member-card-breakdown');
    const chevron = document.getElementById('member-breakdown-chevron');
    const btn = document.getElementById('btn-toggle-member-breakdown');
    if (!breakdown) return;
    const willCollapse = !breakdown.classList.contains('hidden');
    breakdown.classList.toggle('hidden', willCollapse);
    if (chevron) chevron.style.transform = willCollapse ? 'rotate(180deg)' : 'rotate(0deg)';
    if (btn) btn.setAttribute('aria-expanded', willCollapse ? 'false' : 'true');
};

window.toggleRiwayatPoinMember = (forceOpen = null) => {
    const panel = document.getElementById('member-points-history-panel');
    const listEl = document.getElementById('member-points-history-list');
    if (!panel || !listEl) return;

    const shouldOpen = forceOpen !== null ? Boolean(forceOpen) : panel.classList.contains('hidden');
    if (!shouldOpen) {
        panel.classList.add('hidden');
        return;
    }

    const active = window._activeMemberCardData;
    if (!active) return;

    const targetNormPhone = typeof window.normalizeMemberPhone === 'function'
        ? window.normalizeMemberPhone(active.phone)
        : String(active.phone || '').replace(/\D/g, '');

    const ordersMap = (typeof globalOrders !== 'undefined' && globalOrders) ? globalOrders : (window.globalOrders || {});
    const memberOrders = Object.values(ordersMap)
        .filter(ord => {
            if (!ord || typeof ord !== 'object') return false;
            const op = typeof window.normalizeMemberPhone === 'function'
                ? window.normalizeMemberPhone(ord.phone || ord.customerPhone || ord.memberPhone || '')
                : String(ord.phone || ord.customerPhone || ord.memberPhone || '').replace(/\D/g, '');
            return op && op === targetNormPhone;
        })
        .sort((a, b) => Number(b.timestamp || b.createdAt || 0) - Number(a.timestamp || a.createdAt || 0))
        .slice(0, 12);

    const rowsHtml = [];
    memberOrders.forEach(ord => {
        const ts = Number(ord.timestamp || ord.createdAt || Date.now());
        const tglStr = new Date(ts).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
        const totalRp = Number(ord.total || ord.grandTotal || 0).toLocaleString('id-ID');
        const earned = Number(ord.pointsEarned || 0);
        const used = Number(ord.pointsUsed || 0);
        const ptsText = used > 0 ? `-${used} poin` : (earned > 0 ? `+${earned} poin` : 'Transaksi');
        const ptsCls = used > 0 ? 'text-rose-600' : 'text-emerald-600';
        rowsHtml.push(`
            <div class="flex items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-50 border border-slate-100">
                <div class="min-w-0">
                    <p class="text-[11px] font-black text-slate-800 truncate">Pesanan ${ord.id ? '#' + String(ord.id).slice(-5) : ''}</p>
                    <p class="text-[10px] font-medium text-slate-400">${tglStr} • Rp ${totalRp}</p>
                </div>
                <span class="text-[11px] font-black tabular-nums shrink-0 ${ptsCls}">${ptsText}</span>
            </div>
        `);
    });

    if (active.member?.registeredAt) {
        const regStr = new Date(active.member.registeredAt).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
        rowsHtml.push(`
            <div class="flex items-center justify-between gap-2 p-2.5 rounded-xl bg-amber-50/60 border border-amber-100">
                <div class="min-w-0">
                    <p class="text-[11px] font-black text-amber-900">Pendaftaran Member Resmi</p>
                    <p class="text-[10px] font-medium text-amber-700">${regStr}</p>
                </div>
                <span class="text-[11px] font-black text-amber-700 tabular-nums shrink-0">Aktif</span>
            </div>
        `);
    }

    if (rowsHtml.length === 0) {
        listEl.innerHTML = `<p class="text-center py-3 text-[11px] text-slate-500 font-medium">Saldo aktif saat ini ${active.points} poin. Riwayat transaksi terbaru akan tercatat otomatis di sini.</p>`;
    } else {
        listEl.innerHTML = rowsHtml.join('');
    }

    panel.classList.remove('hidden');
    panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
};

window._renderMemberTierStepper = (selectedIdx = 0) => {
    const stepperEl = document.getElementById('member-tier-stepper');
    const tiers = window.MEMBER_LOYALTY_TIERS || window.getConfiguredLoyaltyTiers();
    const active = window._activeMemberCardData;
    const points = active ? Number(active.points || 0) : 0;
    const ownedTierIdx = active ? Number(active.tierIdx || 0) : 0;
    if (!stepperEl || !tiers.length) return;

    stepperEl.innerHTML = tiers.map((t, idx) => {
        const isSelected = idx === selectedIdx;
        const isCurrentOwned = idx === ownedTierIdx;
        const isUnlocked = idx <= ownedTierIdx || points >= t.minPoints;
        const tTheme = t.theme || window.MEMBER_TIER_THEMES.gold;

        if (isSelected) {
            return `
                <button type="button" data-tier-btn="${t.id}" onclick="window.previewTierInfoMember('${t.id}')" class="tier-stepper-btn tier-btn-active flex-1 min-w-[78px] shrink-0 min-h-[36px] px-3 py-1 rounded-full text-white text-[11px] font-black flex items-center justify-center gap-1.5 cursor-pointer whitespace-nowrap scale-[1.03]" style="background: ${tTheme.pillBg};">
                    <span class="tier-btn-icon w-4 h-4 rounded-full bg-white flex items-center justify-center text-[9px] shrink-0 shadow-2xs" style="color: ${tTheme.accentText};">
                        <i class="fa-solid ${isCurrentOwned ? 'fa-check' : (isUnlocked ? 'fa-crown' : 'fa-lock')}"></i>
                    </span>
                    <span>${t.name}</span>
                </button>
            `;
        }

        const iconClass = isCurrentOwned
            ? 'fa-solid fa-check-circle text-amber-500'
            : (isUnlocked ? 'fa-solid fa-circle-check text-emerald-500' : 'fa-solid fa-lock text-slate-400');

        return `
            <button type="button" data-tier-btn="${t.id}" onclick="window.previewTierInfoMember('${t.id}')" class="tier-stepper-btn flex-1 min-w-[74px] shrink-0 min-h-[34px] px-2.5 py-1 rounded-full text-slate-600 hover:text-slate-900 bg-slate-100/90 hover:bg-amber-50/90 text-[11px] font-bold flex items-center justify-center gap-1 active:scale-95 cursor-pointer whitespace-nowrap border border-slate-200/80">
                <i class="tier-btn-icon ${iconClass} text-[10px] shrink-0"></i>
                <span>${t.name}</span>
            </button>
        `;
    }).join('');
};

window._syncTierSliderIndicators = (activeIdx) => {
    const dotsEl = document.getElementById('member-tier-slider-dots');
    const tiers = window.MEMBER_LOYALTY_TIERS || window.getConfiguredLoyaltyTiers();
    if (!dotsEl) return;
    dotsEl.innerHTML = tiers.map((t, idx) => `
        <button type="button" onclick="window.previewTierInfoMember('${t.id}')" aria-label="Lihat kartu ${t.name}" class="h-1.5 rounded-full transition-all duration-300 cursor-pointer ${idx === activeIdx ? 'w-6 bg-amber-500 shadow-2xs' : 'w-1.5 bg-slate-300 hover:bg-slate-400'}"></button>
    `).join('');
};

window.geserTierCardSlider = (dir = 1) => {
    const tiers = window.MEMBER_LOYALTY_TIERS || window.getConfiguredLoyaltyTiers();
    if (!tiers.length) return;
    const curIdx = typeof window._activeViewedTierIdx === 'number' ? window._activeViewedTierIdx : 0;
    const nextIdx = Math.max(0, Math.min(tiers.length - 1, curIdx + Number(dir || 1)));
    const nextTier = tiers[nextIdx];
    if (nextTier) {
        window.previewTierInfoMember(nextTier.id);
    }
};

window.previewTierInfoMember = (tierId) => {
    const tiers = window.MEMBER_LOYALTY_TIERS || window.getConfiguredLoyaltyTiers();
    window.MEMBER_LOYALTY_TIERS = tiers;
    const targetIdx = Math.max(0, tiers.findIndex(t => t.id === tierId));
    const target = tiers[targetIdx] || tiers[0];
    const carouselEl = document.getElementById('member-tier-card-carousel');
    if (!target) return;

    window._activeViewedTierIdx = targetIdx;
    window._renderMemberTierStepper(targetIdx);
    window._syncTierSliderIndicators(targetIdx);

    if (carouselEl) {
        const selectedSlide = carouselEl.querySelector(`[data-tier-card="${target.id}"]`);
        if (selectedSlide) {
            const left = Math.max(0, selectedSlide.offsetLeft - (carouselEl.clientWidth - selectedSlide.offsetWidth) / 2);
            carouselEl.scrollTo({ left, behavior: 'smooth' });
        }
    }
};

window.lihatKeuntunganTierMember = () => {
    const active = window._activeMemberCardData;
    const tierId = active?.tierId || 'classic';
    window.previewTierInfoMember(tierId);
};

window._applyMemberCardLandscapeTransform = () => {
    const modal = document.getElementById('modal-member-card-fullscreen');
    const card = document.getElementById('member-fullscreen-card-inner');
    if (!modal || !card || modal.classList.contains('hidden')) return;

    const ID_CARD_RATIO = 856 / 540; // Proporsi standar kartu KTP / SIM (85.6mm x 54mm)
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let cardW = 540;
    let cardH = 341;

    if (vw < vh) {
        // Layar HP Portrait -> Putar 90 derajat dengan ruang aman untuk tombol Tutup di atas
        const maxVisualW = Math.max(220, vw - 32);
        const maxVisualH = Math.max(330, vh - 128);
        cardW = Math.floor(Math.min(maxVisualH, maxVisualW * ID_CARD_RATIO, 620));
        cardH = Math.round(cardW / ID_CARD_RATIO);
        card.style.transform = 'rotate(90deg)';
    } else {
        // Layar Landscape / Desktop -> Horizontal penuh rasio persegi panjang KTP/SIM
        cardW = Math.floor(Math.max(340, Math.min(vw - 48, (vh - 116) * ID_CARD_RATIO, 640)));
        cardH = Math.round(cardW / ID_CARD_RATIO);
        card.style.transform = 'none';
    }

    card.style.flexShrink = '0';
    card.style.boxSizing = 'border-box';
    card.style.width = cardW + 'px';
    card.style.height = cardH + 'px';
    card.style.minWidth = cardW + 'px';
    card.style.maxWidth = cardW + 'px';
    card.style.minHeight = cardH + 'px';
    card.style.maxHeight = cardH + 'px';
    card.style.margin = '0';
    card.style.transformOrigin = 'center center';
};

window.bukaKartuMemberFullscreenLandscape = () => {
    const data = window._activeMemberCardData;
    const modal = document.getElementById('modal-member-card-fullscreen');
    const card = document.getElementById('member-fullscreen-card-inner');
    if (!modal) return;
    if (!data) {
        alert('Silakan cek data member terlebih dahulu.');
        return;
    }

    const s = window.storeSettings || window.defaultStoreSettings || {};
    const storeName = s.store_title || s.store_name || 'Mainstay Drink';
    const logoUrl = s.store_logo || s.receipt_logo || 'logo-192.png';

    const logoEl = document.getElementById('fs-member-logo');
    const storeEl = document.getElementById('fs-member-store');
    const nameEl = document.getElementById('fs-member-name');
    const phoneEl = document.getElementById('fs-member-phone');
    const ptsEl = document.getElementById('fs-member-points');
    const statusEl = document.getElementById('fs-member-status');
    const qrEl = document.getElementById('fs-member-qr-img');

    const fsStrip = document.querySelector('#member-fullscreen-card-inner > div:first-child');
    if (fsStrip && data.tierTheme?.stripGradient) {
        fsStrip.style.background = data.tierTheme.stripGradient;
    }

    if (logoEl) logoEl.src = logoUrl;
    if (storeEl) storeEl.innerText = String(storeName).toUpperCase();
    if (nameEl) nameEl.innerText = data.name;
    if (phoneEl) phoneEl.innerText = data.phone;
    if (ptsEl) ptsEl.innerText = `${Number(data.points || 0).toLocaleString('id-ID')} poin`;
    if (statusEl) {
        statusEl.innerText = data.isPendingAcc ? 'Menunggu ACC (1x24 Jam)' : `${data.tierName || 'Classic'} • Aktif`;
        statusEl.className = data.isPendingAcc ? 'text-[10.5px] sm:text-xs font-black text-amber-700 mt-0.5' : 'text-[10.5px] sm:text-xs font-black text-amber-800 mt-0.5';
    }
    if (qrEl && (data.qrThumbUrl || data.qrUrl)) qrEl.src = data.qrThumbUrl || data.qrUrl;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    window._applyMemberCardLandscapeTransform();

    if (card) {
        card.classList.remove('member-fs-card-pop');
        void card.offsetWidth;
        card.classList.add('member-fs-card-pop');
    }

    if (!window._memberCardResizeBound) {
        window._memberCardResizeBound = true;
        window.addEventListener('resize', window._applyMemberCardLandscapeTransform);
    }

    try {
        if (modal.requestFullscreen) {
            modal.requestFullscreen().then(() => {
                if (window.screen?.orientation?.lock) {
                    window.screen.orientation.lock('landscape').catch(() => {});
                }
                setTimeout(window._applyMemberCardLandscapeTransform, 120);
            }).catch(() => {});
        }
    } catch (e) {}
};

window.tutupKartuMemberFullscreenLandscape = () => {
    const modal = document.getElementById('modal-member-card-fullscreen');
    const card = document.getElementById('member-fullscreen-card-inner');
    if (card) {
        card.style.width = '';
        card.style.height = '';
        card.style.maxWidth = '';
        card.style.transform = '';
    }
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    try {
        if (window.screen?.orientation?.unlock) window.screen.orientation.unlock();
        if (document.fullscreenElement && document.exitFullscreen) {
            document.exitFullscreen().catch(() => {});
        }
    } catch (e) {}
};

window.normalizeMemberPhone = (rawPhone) => {
    const clean = String(rawPhone || '').replace(/\D/g, '');
    if (!clean) return '';
    return clean.startsWith('62') ? ('0' + clean.slice(2)) : clean;
};

window.cariMemberByPhone = (rawPhone) => {
    const clean = String(rawPhone || '').replace(/\D/g, '');
    if (!clean || clean.length < 8) return null;
    const standardPhone = clean.startsWith('62') ? ('0' + clean.slice(2)) : clean;
    const intlPhone = standardPhone.startsWith('0') ? ('62' + standardPhone.slice(1)) : clean;
    const sources = [window.cachedMembers, (typeof globalMembers !== 'undefined' ? globalMembers : null)].filter(Boolean);

    for (const map of sources) {
        if (map[standardPhone]) return { key: standardPhone, member: map[standardPhone], standardPhone };
        if (map[clean]) return { key: clean, member: map[clean], standardPhone };
        if (map[intlPhone]) return { key: intlPhone, member: map[intlPhone], standardPhone };

        for (const k in map) {
            const m = map[k];
            if (!m || typeof m !== 'object') continue;
            const mPhones = [k, m.phone, m.telepon, m.wa, m.key].map(v => window.normalizeMemberPhone(v)).filter(Boolean);
            if (mPhones.includes(standardPhone)) {
                return { key: k, member: m, standardPhone };
            }
        }
    }
    return null;
};

window.cekDuplikatNomorDaftarMember = () => {
    const phoneInput = document.getElementById('reg-member-phone');
    const warnBox = document.getElementById('reg-member-duplicate-warning');
    const detailEl = document.getElementById('reg-member-duplicate-detail');
    if (!phoneInput || !warnBox) return null;

    const match = window.cariMemberByPhone(phoneInput.value);
    if (match && match.member) {
        const m = match.member;
        const mName = m.name || m.nama || 'Member';
        const mPts = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(m) : Number(m.points ?? m.poin ?? 0);
        phoneInput.classList.remove('border-slate-200', 'focus:border-amber-500');
        phoneInput.classList.add('border-rose-500', 'bg-rose-50/50', 'focus:border-rose-600');
        if (detailEl) {
            detailEl.innerText = `Terdaftar atas nama "${mName}" (${match.standardPhone}) dengan saldo ⭐ ${mPts} Points. Tidak perlu daftar ulang.`;
        }
        warnBox.dataset.foundPhone = match.standardPhone;
        warnBox.classList.remove('hidden');
        return match;
    }

    phoneInput.classList.remove('border-rose-500', 'bg-rose-50/50', 'focus:border-rose-600');
    phoneInput.classList.add('border-slate-200', 'focus:border-amber-500');
    warnBox.classList.add('hidden');
    delete warnBox.dataset.foundPhone;
    return null;
};

window.bukaKartuMemberDariDuplikat = () => {
    const warnBox = document.getElementById('reg-member-duplicate-warning');
    const phoneInput = document.getElementById('reg-member-phone');
    const targetPhone = (warnBox && warnBox.dataset.foundPhone) || window.normalizeMemberPhone(phoneInput ? phoneInput.value : '');
    if (typeof window.switchRewardsModalTab === 'function') {
        window.switchRewardsModalTab('check');
    }
    const checkInput = document.getElementById('stamp-phone-check');
    if (checkInput && targetPhone) checkInput.value = targetPhone;
    if (typeof window.cekStampMember === 'function' && targetPhone) {
        window.cekStampMember();
    }
};

window.submitDaftarMemberBaru = async () => {
    const nameInput = document.getElementById('reg-member-name');
    const phoneInput = document.getElementById('reg-member-phone');
    const waConfirmCheck = document.getElementById('reg-wa-confirm-check');

    const name = nameInput ? nameInput.value.trim() : '';
    const rawPhone = phoneInput ? phoneInput.value : '';
    const phone = window.normalizeMemberPhone(rawPhone);

    if (!name) {
        return alert('Nama lengkap wajib diisi!');
    }
    if (!phone || phone.length < 9) {
        return alert('Nomor WhatsApp wajib diisi minimal 9 digit!');
    }

    // CEK DUPLIKAT NOMOR TERDAFTAR SEBELUM PENDAFTARAN
    let existingMatch = window.cekDuplikatNomorDaftarMember();
    if (!existingMatch) {
        try {
            const snap = await get(ref(db, `members/${phone}`));
            if (snap.exists()) {
                const mVal = snap.val();
                if (!window.cachedMembers) window.cachedMembers = {};
                window.cachedMembers[phone] = mVal;
                existingMatch = window.cekDuplikatNomorDaftarMember() || { key: phone, member: mVal, standardPhone: phone };
            }
        } catch (err) {}
    }

    if (existingMatch && existingMatch.member) {
        const mName = existingMatch.member.name || existingMatch.member.nama || 'Member';
        if (typeof window.showNotif === 'function') {
            window.showNotif(`Nomor WhatsApp ${phone} sudah terdaftar sebagai Member (${mName})!`, 'error');
        }
        alert(`⚠️ Peringatan: Nomor WhatsApp ${phone} sudah terdaftar sebagai Member atas nama "${mName}"!\n\nAnda akan diarahkan ke Kartu Member Anda.`);
        window.switchRewardsModalTab('check');
        const checkInput = document.getElementById('stamp-phone-check');
        if (checkInput) checkInput.value = phone;
        window.cekStampMember();
        return;
    }

    // MANDATORY WA BROADCAST GROUP GATE
    if (!waConfirmCheck || !waConfirmCheck.checked) {
        return alert('Langkah Wajib: Anda harus bergabung ke Grup WhatsApp Broadcast Resmi Mainstay dan mencentang konfirmasi sebelum mengaktifkan keanggotaan member!');
    }

    const prevNonMember = (window.cachedNonMembers && window.cachedNonMembers[phone]) || {};

    const memberPayload = {
        name: name,
        phone: phone,
        points: 5, // Bonus 5 Points pendaftaran member baru
        poin: 5,
        stamps: 0,
        sessions: 0,
        registeredAt: Date.now(),
        lastActive: Date.now(),
        waGroupJoined: true,
        accStatus: 'pending_acc',
        accDeadlineHours: 24,
        accRequestedAt: Date.now(),
        hasJoinScreenshot: true,
        totalOrders: Number(prevNonMember.totalOrders || 0),
        totalSpent: Number(prevNonMember.totalSpent || 0),
        vouchers: prevNonMember.vouchers || {}
    };

    try {
        await update(ref(db, `members/${phone}`), memberPayload);

        // Hapus dari non_members jika sebelumnya ada
        if (window.cachedNonMembers && window.cachedNonMembers[phone]) {
            await remove(ref(db, `non_members/${phone}`));
        }

        alert('Pengajuan Member berhasil dikirim!\n\nPastikan Anda sudah mengirimkan draft & screenshot bukti gabung Grup WA langsung di chat Admin. Keanggotaan akan di-ACC maksimal dalam 1x24 jam (Bonus 5 Points sudah tercatat).');
        
        // Bersihkan form
        if (nameInput) nameInput.value = '';
        if (phoneInput) phoneInput.value = '';
        if (waConfirmCheck) waConfirmCheck.checked = false;
        if (document.getElementById('reg-wa-proof-status')) document.getElementById('reg-wa-proof-status').classList.add('hidden');
        window.cekDuplikatNomorDaftarMember();

        // Buka tab cek Points
        window.switchRewardsModalTab('check');
        const checkInput = document.getElementById('stamp-phone-check');
        if (checkInput) checkInput.value = phone;
        window.cekStampMember();

    } catch (e) {
        console.error('Error daftar member:', e);
        alert('Gagal mendaftar member. Periksa koneksi internet Anda.');
    }
};

