    const lastOverallSuccessTs = Math.max(lastStats.anyAt || 0, lastStats.dailyAt || 0, lastAutoTs || 0, dailyStatus?.at || 0);
    const lastOverallSuccessStr = lastOverallSuccessTs ? new Date(lastOverallSuccessTs).toLocaleString('id-ID') : 'Belum ada backup berhasil';
    const lastDriveSuccessStr = lastStats.driveAt ? new Date(lastStats.driveAt).toLocaleString('id-ID') : 'Belum pernah tersinkron';
