// ============================================================================
// THERMAL PRINTER ESC/POS (Menerapkan ID dari HTML)
// ============================================================================

window.cetakStruk = (orderKey) => {
    const order = globalOrders[orderKey];
    if (!order) return alert('Pesanan tidak ditemukan.');
    
    const s = window.storeSettings || window.globalStoreSettings || window.defaultStoreSettings || {};
    const storeName = s.receipt_store_name || s.store_name || "MAINSTAY DRINK";
    const storePhone = s.receipt_phone || s.store_phone || "08977099557";
    const receiptFooter = (typeof window.getFormattedReceiptFooter === 'function'
        ? window.getFormattedReceiptFooter(s)
        : (s.receipt_footer || "Terima Kasih atas Kunjungan Anda!\nFollow IG: @mainstay.in")).trim();

    const cashierName = order.kasir || order.cashier || order.inputBy || (window.activeStaff?.name || localStorage.getItem('mainstay_staff_name') || 'Owner');
    const kasirProfile = typeof window.getKasirProfileData === 'function' ? window.getKasirProfileData(cashierName) : { name: cashierName, role: 'Kasir', photo: 'logo-192.png' };

    const itemsHtml = (order.items || []).map(i => {
        let rawName = String(i.name || i.nama || 'Item').trim();
        let rawNotes = String(i.notes || i.varian || '').trim();

        // Bersihkan duplikasi: kupas semua kurung berulang di akhir nama item
        let cleanName = rawName;
        const extractedNotes = [];
        while (/\s*\(([^)]+)\)\s*$/.test(cleanName)) {
            const m = cleanName.match(/\s*\(([^)]+)\)\s*$/);
            if (m) {
                const noteVal = m[1].trim();
                if (noteVal && !extractedNotes.includes(noteVal.toLowerCase())) {
                    extractedNotes.push(noteVal.toLowerCase());
                }
                cleanName = cleanName.replace(/\s*\(([^)]+)\)\s*$/, '').trim();
            }
        }

        let finalNoteParts = [];
        const processStr = (s) => {
            if (!s || s.toLowerCase() === 'normal' || s.toLowerCase() === 'normal ice') return;
            if (s.includes(' + ')) {
                s.split(' + ').forEach(part => {
                    const cp = part.trim();
                    if (cp && !finalNoteParts.some(p => p.toLowerCase() === cp.toLowerCase())) {
                        finalNoteParts.push(cp);
                    }
                });
            } else {
                if (!finalNoteParts.some(p => p.toLowerCase() === s.toLowerCase())) {
                    finalNoteParts.push(s);
                }
            }
        };

        if (Array.isArray(i.toppings) && i.toppings.length > 0) {
            i.toppings.forEach(t => {
                const ct = String(t).trim();
                if (ct && !finalNoteParts.some(p => p.toLowerCase() === ct.toLowerCase())) {
                    finalNoteParts.push(ct);
                }
            });
        }

        if (rawNotes) processStr(rawNotes);
        extractedNotes.forEach(en => processStr(en));

        let notesText = '';
        if (finalNoteParts.length > 0) {
            notesText = `<div style="font-size: 9px; font-style: italic; color: #444; margin-left: 8px;">(${finalNoteParts.join(' + ')})</div>`;
        }
        return `
            <div style="margin-bottom: 3px;">
                ${i.qty}x ${cleanName}${notesText}
                <div style="text-align: right; font-size: 10px;">${formatRupiah(i.total || (i.price * i.qty))}</div>
            </div>
        `;
    }).join('');

    const hasLunas = /lunas/i.test(receiptFooter);

    const receiptHtml = `
        <div style="text-align: center; border-bottom: 1px dashed #000; padding-bottom: 5px; margin-bottom: 5px; font-family: monospace;">
            <b style="font-size: 14px;">${storeName}</b><br>
            Tlp: ${storePhone}
        </div>
        
        <!-- Info Kasir Bertugas (Tanpa Foto) -->
        <div style="display: flex; align-items: center; justify-content: space-between; border-bottom: 1px dashed #000; padding-bottom: 4px; margin-bottom: 5px; font-family: monospace; font-size: 10px;">
            <div style="text-align: left;">
                <span style="font-size: 8px; color: #555;">KASIR:</span>
                <b>${kasirProfile.name}</b>
            </div>
            <div style="font-size: 9px; font-weight: bold;">${kasirProfile.role || 'Kasir'}</div>
        </div>

        <div style="font-family: monospace; font-size: 10px;">
            ID: ${order.orderId || order.id || orderKey.slice(-6).toUpperCase()}<br>
            Tgl: ${order.timestamp ? new Date(order.timestamp).toLocaleString('id-ID') : (order.waktu || '-')}<br>
            Pelanggan: ${order.customerName || order.namaPelanggan || 'Umum'}
        </div>
        <div style="border-top: 1px dashed #000; padding-top: 5px; margin-top: 5px; font-family: monospace;">
            ${itemsHtml}
        </div>
        <div style="border-top: 1px dashed #000; padding-top: 5px; margin-top: 5px; font-weight: bold; font-family: monospace;">
            TOTAL: ${formatRupiah(order.totalAmount || order.total || 0)}<br>
            BAYAR: ${order.paymentMethod || order.metode || 'Cash'}
        </div>
        <div style="text-align: center; margin-top: 10px; font-size: 10px; font-family: monospace; white-space: pre-line;">
            <div>${receiptFooter}</div>
            ${!hasLunas ? '<div style="margin-top: 2px; font-weight: bold;">-- LUNAS --</div>' : ''}
        </div>
    `;
    
    if (typeof window.eksekusiPrintThermalUniversal === 'function') {
        window.eksekusiPrintThermalUniversal({
            title: `Struk_${order.orderId || order.id || orderKey.slice(-6).toUpperCase()}`,
            htmlContent: receiptHtml
        });
        return;
    }
    const printArea = document.getElementById('printable-receipt');
    if(printArea) {
        printArea.innerHTML = receiptHtml;
        window.print();
    }
};

// ============================================================================
// INISIALISASI SAAT DOM SELESAI DIMUAT (AKHIR DARI SCRIPT)
// ============================================================================

// --- PEREKAM OTOMATIS SESI & PEMULIHAN ---
if (typeof window.switchRoleView === 'function') {
    const originalSwitchRoleView = window.switchRoleView;
    window.switchRoleView = (role) => {
        if (role === 'kasir') {
            window.safeSetItem('mainstay_session_role', 'kasir');
            if (typeof activeStaff !== 'undefined' && activeStaff) {
                const cleanS = { name: activeStaff.name, role: activeStaff.role || activeStaff.tipeKaryawan, pin: activeStaff.pin };
                window.safeSetItem('mainstay_session_staff', JSON.stringify(cleanS));
            }
            if (!window._hasShownUnclockedWarningOnce && typeof window.cekNotifikasiStaffBelumAbsen === 'function') {
                setTimeout(() => {
                    if (typeof window.cekNotifikasiStaffBelumAbsen === 'function') {
                        window.cekNotifikasiStaffBelumAbsen();
                    }
                }, 1000);
            }
        } else if (role === 'owner') {
            localStorage.setItem('mainstay_session_role', 'owner');
            if (typeof window.tutupSidePopupStaffBelumAbsen === 'function') {
                window.tutupSidePopupStaffBelumAbsen();
            }
        } else if (role === 'customer') {
            if (typeof window.tutupSidePopupStaffBelumAbsen === 'function') {
                window.tutupSidePopupStaffBelumAbsen();
            }
            if (window._isExplicitRoleSwitch) {
                localStorage.removeItem('mainstay_session_role');
                localStorage.removeItem('mainstay_session_staff');
                localStorage.removeItem('mainstay_is_kasir_open');
                window._isExplicitRoleSwitch = false;
                window._hasShownUnclockedWarningOnce = false;
            }
        }
        originalSwitchRoleView(role);
    };
}

const restorePersistentSession = () => {
    const isMasterJump = localStorage.getItem('mainstay_master_owner_jump') === '1';
    if (isMasterJump) {
        try {
            localStorage.removeItem('mainstay_master_owner_jump');
            localStorage.setItem('mainstay_session_role', 'owner');
        } catch (e) {}
    }

    const savedRole = localStorage.getItem('mainstay_session_role');
    const savedStaff = localStorage.getItem('mainstay_session_staff');
    const savedStaffName = localStorage.getItem('mainstay_staff_name') || "Kasir Utama";
    const isKasirManualOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';

    if (savedRole === 'owner') {
        if (typeof window.matikanBGM === 'function') window.matikanBGM();
        window.switchRoleView('owner');
        const activePanel = localStorage.getItem('mainstay_active_panel');
        if (activePanel && typeof window.openPanel === 'function') {
            setTimeout(() => window.openPanel(activePanel), 150);
        }
    } else if (savedRole === 'kasir' || isKasirManualOpen) {
        if (typeof window.matikanBGM === 'function') window.matikanBGM();
        localStorage.setItem('mainstay_session_role', 'kasir');
        if (savedStaff) {
            try {
                window.activeStaff = JSON.parse(savedStaff);
            } catch(e) {
                window.activeStaff = { name: savedStaffName };
            }
        } else {
            window.activeStaff = { name: savedStaffName };
        }

        if (typeof window.updateKasirActiveProfileUI === 'function') {
            window.updateKasirActiveProfileUI(window.activeStaff?.name || savedStaffName);
        } else {
            const nameEl = document.getElementById('kasir-active-name');
            if (nameEl && window.activeStaff) nameEl.innerText = window.activeStaff.name;
            const petEl = document.getElementById('kasir-nama-petugas');
            if (petEl && window.activeStaff) petEl.innerText = window.activeStaff.name;
        }

        window.switchRoleView('kasir');

        // Jika POS Kasir Manual sebelumnya sedang dibuka saat di-refresh:
        if (isKasirManualOpen) {
            setTimeout(() => {
                if (typeof window.bukaPanelKasirManual === 'function') {
                    window.bukaPanelKasirManual();
                }
            }, 100);
        }
    } else {
        window.switchRoleView('customer');
    }
};

// Listener utama yang memicu seluruh ekosistem aplikasi
// --- PASTIKAN STRUKTUR INI BERSIH & AMAN ---
const initApp = () => {
    try {
        applyLayoutFixes();
        startClock();
        initFirebaseListeners(); 
        restorePersistentSession();
        if (currentRole === 'customer') {
            try {
                const cachedSettings = window.storeSettings || JSON.parse(localStorage.getItem('mainstay_store_settings') || '{}');
                if (typeof window.applyStoreSettingsToUI === 'function' && cachedSettings && Object.keys(cachedSettings).length > 0) {
                    window.applyStoreSettingsToUI(cachedSettings);
                }
            } catch(e) {}
            if (typeof window.renderKatalog === 'function') {
                window.renderKatalog();
            }

            // Deteksi otomatis promo voucher dari URL query param (?voucher=... atau ?v=... atau hash #voucher=...)
            try {
                const searchParams = new URLSearchParams(window.location.search);
                const urlVoucher = searchParams.get('voucher') || searchParams.get('v') || searchParams.get('promo');
                if (urlVoucher && typeof window.handleAutoApplyVoucherUrl === 'function') {
                    window.handleAutoApplyVoucherUrl(urlVoucher);
                } else if (window.location.hash) {
                    const hashMatch = window.location.hash.match(/voucher=([a-zA-Z0-9_\-]+)/i);
                    if (hashMatch && typeof window.handleAutoApplyVoucherUrl === 'function') {
                        window.handleAutoApplyVoucherUrl(hashMatch[1]);
                    }
                }

                // Deteksi otomatis nomor meja HANYA jika QR Meja di-scan (URL ?meja=...), tidak dari sisa localStorage
                window.activeCustomerTable = null;
                try {
                    sessionStorage.removeItem('mainstay_customer_table');
                    localStorage.removeItem('mainstay_customer_table');
                } catch (e) {}
                const urlMeja = searchParams.get('meja') || searchParams.get('table') || searchParams.get('m');
                const qrMejaOn = typeof window.isQrMejaFeatureEnabled === 'function' ? window.isQrMejaFeatureEnabled() : true;
                if (urlMeja && qrMejaOn) {
                    const cleanMeja = String(urlMeja).trim().toUpperCase();
                    window.activeCustomerTable = cleanMeja;
                    if (typeof window.tampilkanNotifikasi === 'function') {
                        setTimeout(() => {
                            window.tampilkanNotifikasi(`Selamat datang! Anda memesan dari MEJA ${cleanMeja}`, 'info');
                        }, 600);
                    }
                }
                if (typeof window.renderCustomerActiveTableBar === 'function') {
                    window.renderCustomerActiveTableBar();
                }

                // Deteksi otomatis parameter produk dari QR Display Menu (?menu=...)
                const urlMenu = searchParams.get('menu') || searchParams.get('produk');
                if (urlMenu) {
                    const tryOpenMenu = (attempt = 0) => {
                        const allM = window.globalMenus || (typeof globalMenus !== 'undefined' ? globalMenus : null);
                        const exists = allM && (allM[urlMenu] || Object.values(allM).find(it => it && (it.id == urlMenu || it.key == urlMenu)));
                        if (exists && typeof window.bukaModalDetail === 'function') {
                            window.bukaModalDetail(urlMenu);
                        } else if (attempt < 8) {
                            setTimeout(() => tryOpenMenu(attempt + 1), 350);
                        }
                    };
                    setTimeout(() => tryOpenMenu(0), 500);
                }
            } catch (errParam) {
                console.warn("Catatan parsing parameter URL voucher / meja:", errParam);
            }
        }

        // Jalankan pembersihan data undefined di background hanya saat sesi staf/owner agar boot pelanggan super cepat
        if (currentRole !== 'customer' && typeof window.bersihkanSemuaDataUndefined === 'function') {
            setTimeout(() => {
                window.bersihkanSemuaDataUndefined();
            }, 2500);
        }
    } catch (e) {
        console.error("Error in initApp:", e);
    }
};

window.bersihkanSemuaDataUndefined = async () => {
    try {
        const nodesToCheck = ['vouchers', 'loyalty_rewards', 'members', 'menus', 'menu'];
        for (const nodeName of nodesToCheck) {
            try {
                const snap = await get(ref(db, `${nodeName}/undefined`));
                if (snap.exists()) {
                    await remove(ref(db, `${nodeName}/undefined`));
                    console.log(`[Auto Clean]: Dihapus node ${nodeName}/undefined`);
                }
                const snapNull = await get(ref(db, `${nodeName}/null`));
                if (snapNull.exists()) {
                    await remove(ref(db, `${nodeName}/null`));
                    console.log(`[Auto Clean]: Dihapus node ${nodeName}/null`);
                }
            } catch(e) {}
        }

        try {
            const snapMenu = await get(ref(db, 'menu'));
            if (snapMenu.exists()) {
                await remove(ref(db, 'menu'));
            }
        } catch(e) {}
    } catch(err) {
        console.warn("Pembersihan data undefined:", err);
    }
};

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => setTimeout(initApp, 0));
} else {
    setTimeout(initApp, 0);
}

