window.loginKeKasir = () => {
    // Buka layar kasir
    document.getElementById('layar-kasir').classList.remove('hidden');
    
    // Simpan sesi
    window.safeSetItem('mainstay_session_role', 'kasir');
    const staffData = typeof activeStaff !== 'undefined' && activeStaff 
        ? { name: activeStaff.name, role: activeStaff.role || activeStaff.tipeKaryawan, pin: activeStaff.pin }
        : { name: "Kasir Utama" };
    window.safeSetItem('mainstay_session_staff', JSON.stringify(staffData));
};

window.keluarDariKasir = () => {
    // Tutup layar kasir dan kembali ke mode pelanggan
    document.getElementById('layar-kasir').classList.add('hidden');
    
    // Hapus sesi saat keluar
    localStorage.removeItem('mainstay_session_role');
    localStorage.removeItem('mainstay_session_staff');

    if (typeof matikanKamera === 'function') {
        matikanKamera();
    }

    if (typeof window.renderPromoBestsellerCarousel === 'function') {
        window.renderPromoBestsellerCarousel();
    }
    if (typeof window.renderKatalog === 'function') {
        window.renderKatalog();
    }
};

// ==========================================
// MODUL RUANG KERJA KASIR (SISTEM LENGKAP)
// ==========================================

window.bukaHalamanKerja = () => {
    if (typeof window.matikanBGM === 'function') window.matikanBGM();
    const modal = document.getElementById('ruang-kerja-kasir');
    if (modal) {
        if (modal._rkClosingTimer) {
            clearTimeout(modal._rkClosingTimer);
            modal._rkClosingTimer = null;
        }
        modal.classList.remove('hidden', 'ruang-kerja-anim-exit', 'ruang-kerja-anim-enter');
        modal.classList.add('flex');
        void modal.offsetWidth;
        modal.classList.add('ruang-kerja-anim-enter');
    }
    // Buka tab absensi secara otomatis saat ruang kerja pertama kali dibuka
    switchTabKerja('absensi'); 
};

window.tutupRuangKerja = (immediate = false) => {
    const modal = document.getElementById('ruang-kerja-kasir');
    if (modal) {
        if (modal._rkClosingTimer) {
            clearTimeout(modal._rkClosingTimer);
            modal._rkClosingTimer = null;
        }
        modal.classList.remove('ruang-kerja-anim-enter');
        if (immediate === true || modal.classList.contains('hidden')) {
            modal.classList.add('hidden');
            modal.classList.remove('flex', 'ruang-kerja-anim-exit');
        } else {
            modal.classList.add('ruang-kerja-anim-exit');
            modal._rkClosingTimer = setTimeout(() => {
                modal.classList.add('hidden');
                modal.classList.remove('flex', 'ruang-kerja-anim-exit');
                modal._rkClosingTimer = null;
            }, 200);
        }
    }
    // Matikan kamera jika aktif agar hemat daya dan privasi aman
    if (typeof window.matikanKameraAbsensi === 'function') {
        window.matikanKameraAbsensi();
    }
    if (typeof window.isCustomerViewActive === 'function' && window.isCustomerViewActive()) {
        window.nyalakanBGM();
    }
};

// Fungsi untuk memindah tab dan konten
window.switchTabKerja = (tabName) => {
    const tabs = ['absensi', 'aruskas', 'stok', 'shift', 'resep'];
    
    tabs.forEach(t => {
        // 1. Sembunyikan semua halaman konten
        const contentEl = document.getElementById(`content-tab-${t}`);
        if (contentEl) {
            contentEl.classList.add('hidden');
            contentEl.classList.remove('block', 'ruang-kerja-tab-in');
        }
        
        // 2. Matikan warna aktif di semua tombol tab
        const btn = document.getElementById(`btn-tab-${t}`);
        if (btn) {
            btn.classList.remove('text-blue-600', 'border-blue-600');
            btn.classList.add('text-gray-400', 'border-transparent');
        }
    });

    // 3. Tampilkan halaman konten yang sedang dipilih + animasi masuk halus
    const activeContent = document.getElementById(`content-tab-${tabName}`);
    if (activeContent) {
        activeContent.classList.remove('hidden');
        activeContent.classList.add('block');
        void activeContent.offsetWidth;
        activeContent.classList.add('ruang-kerja-tab-in');
    }
    
    // 4. Warnai tombol tab yang sedang dipilih menjadi biru aktif
    const activeBtn = document.getElementById(`btn-tab-${tabName}`);
    if (activeBtn) {
        activeBtn.classList.remove('text-gray-400', 'border-transparent');
        activeBtn.classList.add('text-blue-600', 'border-blue-600');
    }

    // 5. Trigger inisialisasi & pemuatan data per tab
    if (tabName === 'absensi') {
        window.initTabAbsensi();
    } else {
        // Matikan kamera jika beralih ke tab selain absensi
        if (window.streamKameraAbsensi) {
            window.matikanKameraAbsensi();
        }
    }

    if (tabName === 'aruskas') {
        window.renderTabArusKas();
    } else if (tabName === 'stok') {
        window.renderTabStok();
    } else if (tabName === 'resep') {
        if (typeof window.renderTabResepMenu === 'function') window.renderTabResepMenu();
    } else if (tabName === 'shift') {
        window.renderTabShift();
    }
};

