window._aktivitasFilterCategory = window._aktivitasFilterCategory || 'all';
window._aktivitasFilterShift = window._aktivitasFilterShift || 'all';

window.setFilterAktivitasLog = (filterCat) => {
    window._aktivitasFilterCategory = filterCat || 'all';
    const catSelect = document.getElementById('aktivitas-category-filter');
    if (catSelect && catSelect.value !== window._aktivitasFilterCategory) {
        catSelect.value = window._aktivitasFilterCategory;
    }
    const btns = document.querySelectorAll('#aktivitas-filter-buttons button[data-act-filter]');
    btns.forEach(btn => {
        const isActive = btn.getAttribute('data-act-filter') === window._aktivitasFilterCategory;
        btn.className = isActive
            ? 'min-h-[36px] px-3 py-1.5 rounded-lg text-[11px] font-black bg-slate-900 text-white transition cursor-pointer shrink-0 whitespace-nowrap'
            : 'min-h-[36px] px-3 py-1.5 rounded-lg text-[11px] font-bold bg-slate-100 text-slate-600 hover:bg-slate-200 transition cursor-pointer shrink-0 whitespace-nowrap';
    });
    if (typeof window.renderTabAktivitas === 'function') window.renderTabAktivitas();
};

window.resetFilterAktivitasLog = () => {
    const searchEl = document.getElementById('aktivitas-search-input');
    const catSelect = document.getElementById('aktivitas-category-filter');
    const shiftEl = document.getElementById('aktivitas-shift-filter');
    const typeEl = document.getElementById('aktivitas-action-type-filter');
    const startEl = document.getElementById('aktivitas-date-start');
    const endEl = document.getElementById('aktivitas-date-end');
    if (searchEl) searchEl.value = '';
    if (catSelect) catSelect.value = 'all';
    if (shiftEl) shiftEl.value = 'all';
    if (typeEl) typeEl.value = 'all';
    if (startEl) startEl.value = '';
    if (endEl) endEl.value = '';
    window._aktivitasFilterShift = 'all';
    window.setFilterAktivitasLog('all');
};

window.getFilteredActivityLogsList = () => {
    const logsMap = (window.globalActivityLogs && typeof window.globalActivityLogs === 'object') ? window.globalActivityLogs : {};
    const search = (document.getElementById('aktivitas-search-input')?.value || '').trim().toLowerCase();
    const catSelectVal = (document.getElementById('aktivitas-category-filter')?.value || '').trim();
    const shiftFilter = (document.getElementById('aktivitas-shift-filter')?.value || window._aktivitasFilterShift || 'all').trim().toLowerCase();
    const actionTypeFilter = (document.getElementById('aktivitas-action-type-filter')?.value || 'all').trim();
    const startDateStr = (document.getElementById('aktivitas-date-start')?.value || '').trim();
    const endDateStr = (document.getElementById('aktivitas-date-end')?.value || '').trim();
    const activeCat = catSelectVal || window._aktivitasFilterCategory || 'all';
    window._aktivitasFilterShift = shiftFilter;

    let startBound = null;
    let endBound = null;
    if (startDateStr) {
        const sd = new Date(startDateStr + 'T00:00:00');
        if (!isNaN(sd.getTime())) startBound = sd.getTime();
    }
    if (endDateStr) {
        const ed = new Date(endDateStr + 'T23:59:59.999');
        if (!isNaN(ed.getTime())) endBound = ed.getTime();
    }

    const seen = new Set();
    const items = [];
    Object.entries(logsMap).forEach(([k, log]) => {
        if (!log || typeof log !== 'object') return;
        const ts = Number(log.timestamp || 0);
        const dedupKey = `${ts}|${log.actionType || ''}|${log.targetName || ''}|${log.staffId || ''}`;
        if (seen.has(dedupKey)) return;
        seen.add(dedupKey);
        const shiftMeta = typeof window.resolveOperationalShift === 'function'
            ? window.resolveOperationalShift(ts || Date.now())
            : { shiftId: 'pagi', shiftLabel: 'Shift Pagi' };
        items.push({
            ...log,
            _key: k,
            _ts: ts,
            _shiftId: String(log.shiftId || shiftMeta.shiftId).toLowerCase(),
            _shiftLabel: log.shiftLabel || shiftMeta.shiftLabel
        });
    });

    items.sort((a, b) => b._ts - a._ts);

    return items.filter(item => {
        const cat = String(item.category || 'system');
        if (activeCat === 'stock_adjustment' && cat !== 'stock_adjustment') return false;
        if (activeCat === 'price_menu' && cat !== 'price_change' && cat !== 'menu_edit') return false;
        if (activeCat === 'order_deletion' && cat !== 'order_deletion') return false;
        if (activeCat === 'settings_update' && cat !== 'settings_update') return false;

        if (shiftFilter && shiftFilter !== 'all') {
            if (item._shiftId !== shiftFilter) return false;
        }

        if (actionTypeFilter && actionTypeFilter !== 'all') {
            if (String(item.actionType || '').toLowerCase() !== actionTypeFilter.toLowerCase()) return false;
        }

        if (startBound !== null || endBound !== null) {
            let itemTs = item._ts;
            if ((!itemTs || isNaN(itemTs)) && item.isoDate) {
                const parsed = new Date(item.isoDate + 'T12:00:00');
                if (!isNaN(parsed.getTime())) itemTs = parsed.getTime();
            }
            if (!itemTs || isNaN(itemTs)) return false;
            if (startBound !== null && itemTs < startBound) return false;
            if (endBound !== null && itemTs > endBound) return false;
        }

        if (search) {
            const hay = [
                item.staffName,
                item.staffId,
                item.staffRole,
                item.actionType,
                item.targetName,
                item.summary,
                item.beforeVal,
                item.afterVal,
                item._shiftLabel
            ].join(' ').toLowerCase();
            if (!hay.includes(search)) return false;
        }
        return true;
    });
};

window.renderTabAktivitas = () => {
    const listEl = document.getElementById('aktivitas-log-list');
    const badgeEl = document.getElementById('aktivitas-total-badge');
    if (!listEl) return;

    if (typeof window.cleanupOldActivityLogs === 'function') {
        window.cleanupOldActivityLogs(30);
    }

    const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    const filtered = window.getFilteredActivityLogsList();

    if (badgeEl) {
        badgeEl.innerText = `${filtered.length} Aktivitas`;
    }

    if (filtered.length === 0) {
        listEl.innerHTML = `
            <div class="bg-white p-8 rounded-2xl border border-slate-200 text-center space-y-2">
                <div class="w-12 h-12 rounded-2xl bg-slate-100 text-slate-400 flex items-center justify-center text-xl mx-auto">
                    <i class="fa-solid fa-clipboard-list"></i>
                </div>
                <p class="text-xs sm:text-sm font-black text-slate-700">Tidak Ada Aktivitas Ditemukan</p>
                <p class="text-[11px] text-slate-500 max-w-md mx-auto">Setiap aksi sensitif seperti penyesuaian stok manual, perubahan harga, edit/hapus menu, atau pembatalan pesanan tampil secara real-time di sini (retensi otomatis 30 hari).</p>
            </div>
        `;
        return;
    }

    const badgeStyleFor = (item) => {
        const cat = String(item.category || '');
        if (cat === 'stock_adjustment') return { cls: 'bg-amber-50 text-amber-800 border-amber-200', icon: 'fa-boxes-stacked', catLabel: 'Stok' };
        if (cat === 'price_change') return { cls: 'bg-indigo-50 text-indigo-800 border-indigo-200', icon: 'fa-tags', catLabel: 'Harga' };
        if (cat === 'menu_edit') return { cls: 'bg-blue-50 text-blue-800 border-blue-200', icon: 'fa-utensils', catLabel: 'Menu' };
        if (cat === 'order_deletion') return { cls: 'bg-rose-50 text-rose-800 border-rose-200', icon: 'fa-trash-can', catLabel: 'Pesanan' };
        if (cat === 'settings_update') return { cls: 'bg-emerald-50 text-emerald-800 border-emerald-200', icon: 'fa-sliders', catLabel: 'Setting' };
        return { cls: 'bg-slate-100 text-slate-700 border-slate-200', icon: 'fa-bolt', catLabel: 'Sistem' };
    };

    const shiftBadgeFor = (shiftId) => {
        if (shiftId === 'sore') return 'bg-orange-50 text-orange-700 border-orange-200';
        if (shiftId === 'malam') return 'bg-slate-800 text-slate-100 border-slate-700';
        return 'bg-sky-50 text-sky-700 border-sky-200';
    };

    const html = filtered.slice(0, 200).map(item => {
        const st = badgeStyleFor(item);
        const dt = item._ts ? new Date(item._ts) : null;
        const formattedDate = dt && !isNaN(dt.getTime())
            ? dt.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
            : (item.isoDate || '-');
        const formattedTime = dt && !isNaN(dt.getTime())
            ? dt.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + ' WIB'
            : (item.timeWib || '-');

        const diffHtml = (item.beforeVal || item.afterVal)
            ? `<div class="mt-2 flex flex-wrap items-center gap-1.5 text-[11px] font-bold bg-slate-50 border border-slate-200/80 rounded-xl px-2.5 py-1.5 tabular-nums">
                    ${item.beforeVal ? `<span class="text-slate-500">Sebelum: <span class="text-slate-800">${esc(item.beforeVal)}</span></span>` : ''}
                    ${item.beforeVal && item.afterVal ? `<i class="fa-solid fa-arrow-right text-[9px] text-slate-400"></i>` : ''}
                    ${item.afterVal ? `<span class="text-slate-500">Sesudah: <span class="text-slate-900 font-black">${esc(item.afterVal)}</span></span>` : ''}
               </div>`
            : '';

        return `
            <div class="bg-white p-3.5 sm:p-4 rounded-2xl border border-slate-200 shadow-2xs flex flex-col gap-2 hover:border-slate-300 transition">
                <div class="flex flex-wrap items-center justify-between gap-2">
                    <div class="flex flex-wrap items-center gap-1.5 min-w-0">
                        <span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-black border ${st.cls}">
                            <i class="fa-solid ${st.icon}"></i>
                            <span>${esc(item.actionType || 'System Action')}</span>
                        </span>
                        <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[9px] font-black border ${shiftBadgeFor(item._shiftId)}">
                            <i class="fa-regular fa-sun text-[8px]"></i>
                            <span>${esc(item._shiftLabel || 'Shift Pagi')}</span>
                        </span>
                        ${item.targetName ? `<span class="text-xs font-black text-slate-900 break-words ml-0.5">${esc(item.targetName)}</span>` : ''}
                    </div>
                    <div class="text-[10px] font-bold text-slate-500 flex items-center gap-1.5 tabular-nums shrink-0">
                        <i class="fa-regular fa-clock text-slate-400"></i>
                        <span>${esc(formattedDate)} • ${esc(formattedTime)}</span>
                    </div>
                </div>

                <p class="text-xs text-slate-700 font-medium leading-relaxed">${esc(item.summary || '-')}</p>
                ${diffHtml}

                <div class="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-slate-100 text-[10px]">
                    <div class="flex flex-wrap items-center gap-2 text-slate-600 font-bold">
                        <span class="inline-flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded-md text-slate-800 font-black border border-slate-200 tabular-nums">
                            <i class="fa-solid fa-id-badge text-blue-600"></i> ID Staff: ${esc(item.staffId || '-')}
                        </span>
                        <span><i class="fa-solid fa-user text-slate-400 mr-1"></i>${esc(item.staffName || 'Kasir')}</span>
                        <span class="text-slate-400">• ${esc(item.staffRole || 'Staff')}</span>
                    </div>
                    <span class="text-[10px] font-bold text-slate-400 uppercase">${esc(item.branchId || 'pusat')}</span>
                </div>
            </div>
        `;
    }).join('');

    listEl.innerHTML = html;
};

window.exportActivityLogsCSV = () => {
    const records = window.getFilteredActivityLogsList ? window.getFilteredActivityLogsList() : [];
    if (!records || records.length === 0) {
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi('Belum ada data Activity Logs untuk diekspor ke CSV.', 'info');
        } else {
            alert('Belum ada data Activity Logs untuk diekspor.');
        }
        return;
    }

    const csvEscape = (val) => {
        const str = String(val ?? '').replace(/\r?\n/g, ' ');
        return `"${str.replace(/"/g, '""')}"`;
    };

    const headers = [
        'Timestamp (ISO)',
        'Tanggal',
        'Waktu (WIB)',
        'Shift',
        'Cabang',
        'ID Staff',
        'Nama Staff',
        'Jabatan',
        'Kategori',
        'Tipe Aksi',
        'Target',
        'Nilai Sebelum',
        'Nilai Sesudah',
        'Ringkasan'
    ];

    const rows = records.map(item => {
        const dt = item._ts ? new Date(item._ts) : null;
        const isoFull = dt && !isNaN(dt.getTime()) ? dt.toISOString() : '';
        const tgl = item.isoDate || (dt && !isNaN(dt.getTime()) ? dt.toLocaleDateString('id-ID') : '');
        const wkt = item.timeWib || (dt && !isNaN(dt.getTime()) ? dt.toLocaleTimeString('id-ID') + ' WIB' : '');
        return [
            isoFull,
            tgl,
            wkt,
            item._shiftLabel || '-',
            item.branchId || 'pusat',
            item.staffId || '-',
            item.staffName || '-',
            item.staffRole || '-',
            item.category || '-',
            item.actionType || '-',
            item.targetName || '-',
            item.beforeVal || '-',
            item.afterVal || '-',
            item.summary || '-'
        ].map(csvEscape).join(',');
    });

    const csvContent = '\uFEFF' + [headers.map(csvEscape).join(','), ...rows].join('\r\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const todayIso = new Date().toISOString().slice(0, 10);
    const filename = `mainstay-activity-logs-${window.ACTIVE_BRANCH_ID || 'pusat'}-${todayIso}.csv`;

    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);

    if (typeof window.tampilkanNotifikasi === 'function') {
        window.tampilkanNotifikasi(`Berhasil mengekspor ${records.length} log aktivitas ke ${filename}.`, 'success');
    }
};

window._resepKerjaKategoriFilter = window._resepKerjaKategoriFilter || 'all';

window.setFilterKategoriResepKerja = (cat) => {
    window._resepKerjaKategoriFilter = cat || 'all';
    if (typeof window.renderTabResepMenu === 'function') window.renderTabResepMenu();
};

window.renderTabResepMenu = () => {
    const listEl = document.getElementById('resep-kasir-list');
    const badgeEl = document.getElementById('resep-kasir-total-badge');
    const catWrap = document.getElementById('resep-kasir-cat-filters');
    if (!listEl) return;

    const search = (document.getElementById('resep-kasir-search')?.value || '').trim().toLowerCase();
    const menusMap = (typeof globalMenus === 'object' && globalMenus) ? globalMenus : (window.globalMenus || {});
    const invMap = (typeof globalInventory === 'object' && globalInventory) ? globalInventory : (window.globalInventory || {});
    const allEntries = Object.entries(menusMap).filter(([, m]) => m && m.name);

    const catMap = new Map();
    allEntries.forEach(([, m]) => {
        const c = String(m.category || m.kategori || 'Lainnya').trim();
        if (c && !catMap.has(c.toLowerCase())) catMap.set(c.toLowerCase(), c);
    });
    const activeCat = window._resepKerjaKategoriFilter || 'all';

    if (catWrap) {
        let catBtns = `<button type="button" onclick="window.setFilterKategoriResepKerja('all')" class="min-h-[34px] px-3 py-1 text-[10px] font-black rounded-lg transition shrink-0 whitespace-nowrap ${activeCat === 'all' ? 'bg-emerald-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">Semua (${allEntries.length})</button>`;
        Array.from(catMap.values()).forEach(catName => {
            const isSel = activeCat.toLowerCase() === catName.toLowerCase();
            catBtns += `<button type="button" onclick="window.setFilterKategoriResepKerja('${catName.replace(/'/g, "\\'")}')" class="min-h-[34px] px-3 py-1 text-[10px] font-black rounded-lg transition shrink-0 whitespace-nowrap ${isSel ? 'bg-emerald-600 text-white shadow-xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">${catName}</button>`;
        });
        catWrap.innerHTML = catBtns;
    }

    const filtered = allEntries
        .filter(([, m]) => {
            const catStr = String(m.category || m.kategori || 'Lainnya').trim();
            if (activeCat !== 'all' && catStr.toLowerCase() !== activeCat.toLowerCase()) return false;
            if (!search) return true;
            const nameMatch = String(m.name || '').toLowerCase().includes(search) || catStr.toLowerCase().includes(search);
            const resepMatch = Array.isArray(m.resep) && m.resep.some(r => String(r?.itemName || invMap?.[r?.itemKey]?.name || '').toLowerCase().includes(search));
            const sopMatch = String(m.caraPembuatan || m.cara_pembuatan || m.sop || '').toLowerCase().includes(search);
            return nameMatch || resepMatch || sopMatch;
        })
        .sort((a, b) => String(a[1].name || '').localeCompare(String(b[1].name || '')));

    if (badgeEl) badgeEl.innerText = `${filtered.length} Menu`;

    if (filtered.length === 0) {
        listEl.innerHTML = `
            <div class="col-span-full py-10 px-4 text-center bg-white rounded-2xl border border-slate-200">
                <i class="fa-solid fa-book-open text-3xl text-slate-300 mb-2"></i>
                <p class="text-xs font-bold text-slate-500">Belum ada menu yang cocok dengan pencarian.</p>
            </div>`;
        return;
    }

    listEl.innerHTML = filtered.map(([, m]) => {
        const resep = Array.isArray(m.resep) ? m.resep.filter(r => r && (r.itemName || r.itemKey)) : [];
        const sopRaw = String(m.caraPembuatan || m.cara_pembuatan || m.sop || '').trim();
        const sopLines = sopRaw ? sopRaw.split(/\r?\n/).map(l => l.trim()).filter(Boolean) : [];
        const catLabel = m.category || m.kategori || 'Minuman';
        const imgUrl = m.imageUrl || 'logo-192.png';

        const bahanHtml = resep.length > 0
            ? `<div class="divide-y divide-emerald-100/80 bg-emerald-50/40 rounded-xl border border-emerald-200/70 px-3 py-1">
                ${resep.map(r => {
                    const invObj = (r.itemKey && invMap[r.itemKey]) ? invMap[r.itemKey] : null;
                    const ingName = r.itemName || invObj?.name || r.itemKey || 'Bahan';
                    const ingQty = Number(r.qty || 0);
                    const ingUnit = r.unit || invObj?.unit || 'Pcs';
                    return `
                        <div class="flex items-center justify-between gap-2 py-1.5 text-xs">
                            <span class="font-bold text-slate-700 truncate">${ingName}</span>
                            <span class="font-black text-emerald-800 bg-white border border-emerald-200 px-2 py-0.5 rounded-md tabular-nums shrink-0">${ingQty} ${ingUnit}</span>
                        </div>`;
                }).join('')}
               </div>`
            : `<p class="text-[11px] text-slate-400 italic bg-slate-50 border border-dashed border-slate-200 rounded-xl p-2.5">Bahan &amp; takaran belum diatur oleh Master Owner.</p>`;

        const sopHtml = sopLines.length > 0
            ? `<ol class="space-y-1.5 bg-slate-50 rounded-xl border border-slate-200/80 p-3 text-xs text-slate-700">
                ${sopLines.map((line, i) => {
                    const cleanLine = line.replace(/^\d+[\.\)]\s*/, '');
                    return `<li class="flex items-start gap-2 leading-relaxed">
                        <span class="w-5 h-5 rounded-full bg-blue-600 text-white text-[10px] font-black flex items-center justify-center shrink-0 mt-0.5">${i + 1}</span>
                        <span class="font-semibold flex-1 break-words">${cleanLine}</span>
                    </li>`;
                }).join('')}
               </ol>`
            : `<p class="text-[11px] text-slate-400 italic bg-slate-50 border border-dashed border-slate-200 rounded-xl p-2.5">Cara pembuatan menu belum diisi di Master Owner.</p>`;

        return `
            <div class="bg-white rounded-2xl border border-slate-200 shadow-2xs p-3.5 sm:p-4 flex flex-col gap-3">
                <div class="flex items-center gap-3 pb-2.5 border-b border-slate-100">
                    <div class="w-14 h-14 rounded-xl overflow-hidden bg-slate-100 border border-slate-200 shrink-0">
                        <img src="${imgUrl}" alt="${m.name}" class="w-full h-full object-cover" onerror="this.src='logo-192.png'">
                    </div>
                    <div class="min-w-0 flex-1">
                        <div class="flex items-center gap-1.5 flex-wrap">
                            <span class="px-2 py-0.5 rounded-md bg-slate-100 text-slate-600 text-[9px] font-black uppercase tracking-wider">${catLabel}</span>
                            ${resep.length > 0 ? `<span class="px-2 py-0.5 rounded-md bg-emerald-100 text-emerald-800 text-[9px] font-black">${resep.length} Bahan</span>` : ''}
                        </div>
                        <h5 class="text-sm font-black text-slate-900 leading-snug truncate mt-1">${m.name}</h5>
                    </div>
                </div>

                <div>
                    <p class="text-[10px] font-black text-emerald-800 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                        <i class="fa-solid fa-flask text-emerald-600"></i> Bahan &amp; Takaran
                    </p>
                    ${bahanHtml}
                </div>

                <div>
                    <p class="text-[10px] font-black text-blue-800 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                        <i class="fa-solid fa-list-ol text-blue-600"></i> Cara Pembuatan Menu
                    </p>
                    ${sopHtml}
                </div>
            </div>`;
    }).join('');
};

