window._absensiClockInterval = null;

window.initTabAbsensi = async () => {
    // 1. Jalankan Jam Digital Live
    const updateClock = () => {
        const now = new Date();
        const jamEl = document.getElementById('absen-jam-live');
        const tglEl = document.getElementById('absen-tgl-live');
        if (jamEl) {
            jamEl.innerText = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) + ' WIB';
        }
        if (tglEl) {
            tglEl.innerText = now.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'short', year: 'numeric' });
        }
    };
    updateClock();
    if (!window._absensiClockInterval) {
        window._absensiClockInterval = setInterval(updateClock, 1000);
    }

    // 2. Muat Riwayat Absensi & Sinkronkan Cache Status Hari Ini
    await window.renderRiwayatAbsensiHariIni();

    // 3. Isi Dropdown Nama Karyawan dengan Indikator Status
    window.populateStaffSelectAbsen();

    // 4. Render Daftar Status Staf Hari Ini (Sedang Bertugas / Libur)
    window.renderDaftarStatusStafAbsen();

    // 5. Terapkan Mode Aktif (PIN)
    window.pilihModeAbsensi('pin');
};

window.populateStaffSelectAbsen = () => {
    const selectPin = document.getElementById('select-staff-absen');
    const selectFace = document.getElementById('select-staff-absen-face');
    if (!selectPin && !selectFace) return;
    
    const curValPin = selectPin?.value;
    const curValFace = selectFace?.value;
    const placeholder = '<option value="">-- Pilih Nama Karyawan --</option>';
    
    if (selectPin) selectPin.innerHTML = placeholder;
    if (selectFace) selectFace.innerHTML = placeholder;
    
    const effectiveMap = typeof window.getEffectiveBranchStaffMap === 'function'
        ? window.getEffectiveBranchStaffMap()
        : (globalStaff || {});
    let staffList = Object.entries(effectiveMap);
    if (staffList.length === 0) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_cached_staff') || '{}');
            if (cached && Object.keys(cached).length > 0) {
                staffList = Object.entries(cached);
            }
        } catch(e) {}
    }
    if (staffList.length === 0 && !window.IS_BRANCH_OUTLET && window.defaultDemoStaff) {
        staffList = Object.entries(window.defaultDemoStaff);
    }
    if (staffList.length === 0) {
        const opt = document.createElement('option');
        if (!window.IS_BRANCH_OUTLET) {
            opt.value = "staff_ihsan";
            opt.innerText = "Ihsan (Kasir) • ⚪ Libur";
        } else {
            opt.value = "";
            opt.innerText = "-- Data staff cabang masih kosong --";
        }
        if (selectPin) selectPin.appendChild(opt);
        if (selectFace) selectFace.appendChild(opt.cloneNode(true));
    } else {
        staffList.forEach(([key, s]) => {
            let staffName = s.name || s.nama || 'Karyawan';
            if (staffName === 'Kasir Utama') staffName = 'Ihsan';
            if (staffName === 'Barista Utama') staffName = 'Elmusaqi';
            const role = s.tipeKaryawan || s.role || 'Staff';
            const duty = typeof window.cekStatusTugasStaf === 'function' 
                ? window.cekStatusTugasStaf(staffName, s.pin)
                : { isOnDuty: false };
            const statusLabel = duty.isOnDuty ? '🟢 Sedang Bertugas' : '⚪ Libur';

            const opt = document.createElement('option');
            opt.value = key;
            opt.innerText = `${staffName} (${role}) — ${statusLabel}`;
            if (selectPin) selectPin.appendChild(opt);
            if (selectFace) selectFace.appendChild(opt.cloneNode(true));
        });
    }

    // Set value aktif jika ada staf tersimpan di session
    const savedStaff = localStorage.getItem('mainstay_staff_name');
    if (savedStaff) {
        const match = staffList.find(([_, s]) => s.name === savedStaff);
        if (match) {
            if (selectPin) selectPin.value = match[0];
            if (selectFace) selectFace.value = match[0];
            window.handleStaffSelectAbsen(match[0], false);
        }
    } else if (curValPin || curValFace) {
        const targetVal = curValPin || curValFace;
        if (selectPin) selectPin.value = targetVal;
        if (selectFace) selectFace.value = targetVal;
        window.handleStaffSelectAbsen(targetVal, false);
    }
};

window.handleStaffSelectAbsen = (staffKey, shouldFocusPin = true) => {
    const infoCardPin = document.getElementById('info-staff-terpilih-pin');
    const infoCardFace = document.getElementById('info-staff-terpilih-face');

    if (!staffKey) {
        if (infoCardPin) infoCardPin.classList.add('hidden');
        if (infoCardFace) {
            infoCardFace.classList.add('hidden');
            infoCardFace.classList.remove('flex');
        }
        return;
    }
    
    const effectiveMap = typeof window.getEffectiveBranchStaffMap === 'function'
        ? window.getEffectiveBranchStaffMap()
        : (globalStaff || {});
    let staff = effectiveMap[staffKey] || (!window.IS_BRANCH_OUTLET && window.defaultDemoStaff && window.defaultDemoStaff[staffKey]);
    if (!staff && !window.IS_BRANCH_OUTLET && window.globalMasterOwner && window.globalMasterOwner[staffKey]) {
        staff = window.globalMasterOwner[staffKey];
    }

    if (staff && staff.name) {
        try { localStorage.setItem('mainstay_staff_name', staff.name); } catch(e) {}
    }
    
    // Sinkronkan dropdown Face dan PIN
    const selectFace = document.getElementById('select-staff-absen-face');
    if (selectFace && selectFace.value !== staffKey) selectFace.value = staffKey;

    const selectPin = document.getElementById('select-staff-absen');
    if (selectPin && selectPin.value !== staffKey) selectPin.value = staffKey;

    if (staff) {
        const staffName = staff.name || 'Karyawan';
        const shiftText = `Shift Masuk: ${staff.shiftIn || 'Sesuai Jadwal'} WIB`;
        const roleText = staff.tipeKaryawan || staff.role || 'Staff';
        const photoSrc = staff.photo || staff.foto || staff.faceData;
        const initials = staffName.slice(0, 2).toUpperCase();

        // 1. Update Card Info Staff di Panel PIN
        if (infoCardPin) {
            infoCardPin.classList.remove('hidden');
            infoCardPin.classList.add('flex');
        }
        const namaPin = document.getElementById('nama-staff-terpilih-pin');
        const shiftPin = document.getElementById('shift-staff-terpilih-pin');
        const rolePin = document.getElementById('role-staff-terpilih-pin');
        const imgPin = document.getElementById('img-staff-terpilih-pin');
        const initialPin = document.getElementById('initial-staff-terpilih-pin');
        const statusTugasBadge = document.getElementById('status-tugas-badge');

        if (namaPin) namaPin.innerText = staffName;
        if (shiftPin) shiftPin.innerText = shiftText;
        if (rolePin) rolePin.innerText = roleText;

        // Tampilkan badge status Sedang Bertugas vs Libur
        if (statusTugasBadge && typeof window.cekStatusTugasStaf === 'function') {
            const duty = window.cekStatusTugasStaf(staffName, staff.pin);
            if (duty.isOnDuty) {
                statusTugasBadge.className = "inline-flex items-center gap-1 text-[9px] font-black px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 border border-emerald-300";
                statusTugasBadge.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> Sedang Bertugas`;
            } else {
                statusTugasBadge.className = "inline-flex items-center gap-1 text-[9px] font-black px-2 py-0.5 rounded-full bg-slate-100 text-slate-600 border border-slate-300";
                statusTugasBadge.innerHTML = `⚪ Libur`;
            }
        }

        if (photoSrc && imgPin) {
            imgPin.src = photoSrc;
            imgPin.classList.remove('hidden');
            if (initialPin) initialPin.classList.add('hidden');
        } else {
            if (imgPin) imgPin.classList.add('hidden');
            if (initialPin) {
                initialPin.classList.remove('hidden');
                initialPin.innerText = initials;
            }
        }

        // 2. Update Card Info Staff di Panel Face Recognition (Kompatibilitas)
        if (infoCardFace) {
            infoCardFace.classList.remove('hidden');
            infoCardFace.classList.add('flex');
        }
        const namaFace = document.getElementById('nama-staff-terpilih-face');
        const shiftFace = document.getElementById('shift-staff-terpilih-face');
        const imgFace = document.getElementById('img-staff-terpilih-face');
        const initialFace = document.getElementById('initial-staff-terpilih-face');
        const badgeBiometrik = document.getElementById('badge-status-wajah-staff');

        if (namaFace) namaFace.innerText = staffName;
        if (shiftFace) shiftFace.innerText = shiftText;

        if (photoSrc && imgFace) {
            imgFace.src = photoSrc;
            imgFace.classList.remove('hidden');
            if (initialFace) initialFace.classList.add('hidden');
        } else {
            if (imgFace) imgFace.classList.add('hidden');
            if (initialFace) {
                initialFace.classList.remove('hidden');
                initialFace.innerText = initials;
            }
        }

        const hasFace = !!(staff.faceData || staff.photo || staff.foto);
        if (badgeBiometrik) {
            if (hasFace) {
                badgeBiometrik.innerHTML = `<span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[9px] font-black bg-emerald-100 text-emerald-800 border border-emerald-300 shadow-2xs"><i class="fa-solid fa-circle-check text-emerald-600"></i> Wajah Terdaftar</span>`;
            } else {
                badgeBiometrik.innerHTML = `<span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[9px] font-black bg-amber-100 text-amber-800 border border-amber-300 shadow-2xs"><i class="fa-solid fa-triangle-exclamation text-amber-600"></i> Belum Ada Wajah</span>`;
            }
        }
    }

    if (shouldFocusPin) {
        const pinInput = document.getElementById('pin-absensi-kamera');
        if (pinInput) pinInput.focus();
    }
};

window.handleStaffSelectAbsenFace = (staffKey) => {
    if (!staffKey) return;
    const selectPin = document.getElementById('select-staff-absen');
    if (selectPin && selectPin.value !== staffKey) {
        selectPin.value = staffKey;
    }
    window.handleStaffSelectAbsen(staffKey, false);
};

window.renderRiwayatAbsensiHariIni = async () => {
    const listContainer = document.getElementById('ruang-kerja-absensi-hari-ini');
    const countBadge = document.getElementById('absen-today-count');
    if (!listContainer) return;

    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const tglHariIni = `${yyyy}-${mm}-${dd}`;

    let dataHariIni = [];

    // Ambil dari Firebase
    try {
        const snap = await get(ref(db, `attendance/${tglHariIni}`));
        if (snap.exists()) {
            dataHariIni = Object.values(snap.val());
        }
    } catch(e) {
        console.warn("Gagal tarik attendance firebase, fallback ke cache:", e);
    }

    // Jika kosong, periksa cache lokal
    if (dataHariIni.length === 0) {
        try {
            const localCache = JSON.parse(localStorage.getItem('mainstay_attendance_local_logs') || '[]');
            dataHariIni = localCache.filter(l => l.tanggal === tglHariIni);
        } catch(e) {}
    }

    // Perbarui Cache Log Hari Ini di memori
    window.todayAttendanceCache = dataHariIni;

    if (countBadge) countBadge.innerText = `${dataHariIni.length} Tercatat`;

    // Kalkulasi jumlah per filter status
    const countSemua = dataHariIni.length;
    const countMasuk = dataHariIni.filter(i => i.tipe === 'Masuk').length;
    const countPulang = dataHariIni.filter(i => i.tipe === 'Pulang').length;
    const countTelat = dataHariIni.filter(i => i.status === 'TERLAMBAT' || (i.status && i.status.toLowerCase().includes('terlambat'))).length;

    const badgeSemua = document.getElementById('count-filter-semua');
    const badgeMasuk = document.getElementById('count-filter-Masuk');
    const badgePulang = document.getElementById('count-filter-Pulang');
    const badgeTelat = document.getElementById('count-filter-Terlambat');

    if (badgeSemua) badgeSemua.innerText = countSemua;
    if (badgeMasuk) badgeMasuk.innerText = countMasuk;
    if (badgePulang) badgePulang.innerText = countPulang;
    if (badgeTelat) badgeTelat.innerText = countTelat;

    // Perbarui Tampilan Tombol Filter Aktif (mendatar / horizontal)
    const curFilter = window.filterLogAbsensiAktif || 'semua';
    const filters = ['semua', 'Masuk', 'Pulang', 'Terlambat'];
    const baseAbsenFilterBtn = "min-h-[38px] flex-1 min-w-max shrink-0 whitespace-nowrap py-1.5 px-2.5 text-[10px] font-black rounded-lg transition flex items-center justify-center gap-1.5 cursor-pointer ";

    filters.forEach(f => {
        const btn = document.getElementById(`btn-filter-absen-${f}`);
        if (!btn) return;
        if (f === curFilter) {
            if (f === 'Masuk') {
                btn.className = baseAbsenFilterBtn + "bg-emerald-600 text-white shadow-xs";
            } else if (f === 'Pulang') {
                btn.className = baseAbsenFilterBtn + "bg-blue-600 text-white shadow-xs";
            } else if (f === 'Terlambat') {
                btn.className = baseAbsenFilterBtn + "bg-rose-600 text-white shadow-xs";
            } else {
                btn.className = baseAbsenFilterBtn + "bg-slate-900 text-white shadow-xs";
            }
        } else {
            btn.className = baseAbsenFilterBtn + "text-slate-500 hover:text-slate-800";
        }
    });

    if (dataHariIni.length === 0) {
        listContainer.innerHTML = `
            <div class="text-center py-4 bg-white rounded-xl border border-slate-100 p-3">
                <i class="fa-solid fa-user-clock text-slate-300 text-xl mb-1"></i>
                <p class="text-[11px] font-bold text-slate-400">Belum ada absensi staf hari ini</p>
                <p class="text-[9px] text-slate-400">Gunakan kolom PIN di atas untuk mulai absen.</p>
            </div>
        `;
        if (typeof window.renderDaftarStatusStafAbsen === 'function') {
            window.renderDaftarStatusStafAbsen();
        }
        return;
    }

    // Urutkan data dari terbaru ke terlama
    dataHariIni.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

    // Filter daftar sesuai pilihan tombol
    let filteredData = dataHariIni;
    if (curFilter === 'Masuk') {
        filteredData = dataHariIni.filter(item => item.tipe === 'Masuk');
    } else if (curFilter === 'Pulang') {
        filteredData = dataHariIni.filter(item => item.tipe === 'Pulang');
    } else if (curFilter === 'Terlambat') {
        filteredData = dataHariIni.filter(item => item.status === 'TERLAMBAT' || (item.status && item.status.toLowerCase().includes('terlambat')));
    }

    if (filteredData.length === 0) {
        listContainer.innerHTML = `
            <div class="text-center py-4 bg-white rounded-xl border border-slate-100 p-3">
                <i class="fa-solid fa-filter text-slate-300 text-lg mb-1"></i>
                <p class="text-[11px] font-bold text-slate-500">Tidak ada absensi status "${curFilter}"</p>
                <p class="text-[9px] text-slate-400">Pilih filter 'Semua' untuk melihat riwayat lengkap.</p>
            </div>
        `;
        if (typeof window.renderDaftarStatusStafAbsen === 'function') {
            window.renderDaftarStatusStafAbsen();
        }
        return;
    }

    let html = '';
    filteredData.forEach(item => {
        const isMasuk = item.tipe === 'Masuk';
        const isTelat = item.status === 'TERLAMBAT' || (item.status && item.status.toLowerCase().includes('terlambat'));
        const badgeColor = isTelat 
            ? 'bg-rose-100 text-rose-700 border-rose-200' 
            : (isMasuk ? 'bg-emerald-100 text-emerald-700 border-emerald-200' : 'bg-blue-100 text-blue-700 border-blue-200');
        
        const badgeIcon = isMasuk ? 'fa-right-to-bracket text-emerald-600' : 'fa-right-from-bracket text-blue-600';
        
        const metodeRaw = item.metode || (item.foto ? 'Kamera PIN' : 'PIN');
        const badgeMetode = `
            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[8px] font-black bg-purple-100 text-purple-800 border border-purple-200">
                <i class="fa-solid fa-camera text-purple-600"></i> ${metodeRaw}
            </span>
        `;

        const avatarThumb = item.foto ? `
            <div onclick="window.previewFotoAbsensi && window.previewFotoAbsensi('${encodeURIComponent(item.foto)}', '${item.nama}', '${item.jam || item.waktu || '-'} WIB')" class="w-8 h-8 rounded-lg overflow-hidden border border-slate-200 shadow-2xs shrink-0 cursor-pointer hover:scale-105 transition" title="Klik untuk lihat foto">
                <img src="${item.foto}" alt="${item.nama}" class="w-full h-full object-cover">
            </div>
        ` : `
            <div class="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center text-xs shrink-0 text-slate-500">
                <i class="fa-solid ${badgeIcon}"></i>
            </div>
        `;

        html += `
            <div class="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-2.5 p-2.5 bg-white rounded-xl border border-slate-100 shadow-2xs hover:border-slate-200 transition">
                <div class="flex items-center gap-2.5 min-w-0">
                    ${avatarThumb}
                    <div class="min-w-0">
                        <div class="flex items-center gap-1.5 flex-wrap">
                            <h5 class="text-xs font-black text-slate-800 leading-tight truncate">${item.nama || 'Staf'}</h5>
                            ${badgeMetode}
                        </div>
                        <p class="text-[9px] font-bold text-slate-400 mt-0.5 truncate">${item.role || 'Staff'} • ${item.jam || item.waktu || '-'} WIB</p>
                    </div>
                </div>
                <span class="text-[9px] font-black px-2 py-0.5 rounded-md border shrink-0 whitespace-nowrap ${badgeColor}">
                    ${item.status || (isMasuk ? 'TEPAT WAKTU' : 'SELESAI')}
                </span>
            </div>
        `;
    });

    listContainer.innerHTML = html;
    if (typeof window.renderDaftarStatusStafAbsen === 'function') {
        window.renderDaftarStatusStafAbsen();
    }
};

