window.downloadStrukShift = async () => {
    const snap = window._shiftReceiptSnapshot || {};
    const isA4 = window._shiftPreviewFormat === 'a4';
    const dateTag = snap.date || new Date().toISOString().split('T')[0];
    const kasirTag = (snap.kasir || 'Kasir').replace(/\s+/g, '_');
    const summaryText = `*LAPORAN TUTUP SHIFT - ${snap.storeName || 'MAINSTAY DRINK'}*\n` +
        `Waktu: ${snap.waktuStr || '-'}\nKasir: ${snap.kasir || '-'}\n` +
        `Total Omzet: ${formatRupiah(snap.totalOmzet || 0)} (${snap.notaCount || 0} Trx)\n` +
        `Tunai: ${formatRupiah(snap.cashSales || 0)} | Non-Tunai: ${formatRupiah(snap.qrisSales || 0)}\n` +
        `Uang Seharusnya: ${formatRupiah(snap.expectedCash || 0)} | Fisik: ${formatRupiah(snap.actualCash || 0)}\n` +
        `Selisih: ${snap.selisihTeks || 'SESUAI'}`;

    if (typeof window.shareElementLangsungNative === 'function') {
        await window.shareElementLangsungNative({
            title: isA4 ? 'Laporan Shift A4' : 'Struk Tutup Shift',
            subtitle: `Kasir: ${snap.kasir || 'Kasir'} • ${dateTag}`,
            elementId: isA4 ? 'kertas-shift-a4' : 'kertas-struk-shift',
            filename: `${isA4 ? 'Laporan_Shift_A4' : 'Struk_Shift_Mainstay'}_${dateTag}_${kasirTag}`,
            textSummary: summaryText,
            paperMode: isA4 ? 'a4' : 'thermal',
            triggerBtnId: 'btn-download-shift'
        });
    } else if (typeof window.bukaShareDownloadSheet === 'function') {
        window.bukaShareDownloadSheet({
            title: isA4 ? 'Bagikan Laporan Shift A4' : 'Bagikan Struk Tutup Shift',
            subtitle: `Kasir: ${snap.kasir || 'Kasir'} • ${dateTag}`,
            elementId: isA4 ? 'kertas-shift-a4' : 'kertas-struk-shift',
            filename: `${isA4 ? 'Laporan_Shift_A4' : 'Struk_Shift_Mainstay'}_${dateTag}_${kasirTag}`,
            textSummary: summaryText,
            paperMode: isA4 ? 'a4' : 'thermal'
        });
    }
};

