window.tampilkanPopupBatal = (key) => {
    const popupLama = document.getElementById('popup-batal-custom');
    if (popupLama) popupLama.remove();

    const modal = document.createElement('div');
    modal.id = 'popup-batal-custom';
    modal.className = 'fixed inset-0 z-[999999] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-5 opacity-0 transition-opacity duration-300';

    modal.innerHTML = `
        <div class="bg-white w-full max-w-sm rounded-3xl p-6 flex flex-col items-center text-center shadow-2xl transform scale-95 transition-transform duration-300">
            <div class="w-16 h-16 shrink-0 bg-red-50 text-red-500 rounded-full flex items-center justify-center text-3xl mb-4 shadow-inner border border-red-100">
                <i class="fa-solid fa-ban"></i>
            </div>
            
            <h2 class="text-xl font-black text-slate-800 mb-1">Batalkan Pesanan?</h2>
            <p class="text-xs text-slate-500 font-medium mb-6 px-2 leading-relaxed">
                Tindakan ini tidak dapat diurungkan. Pesanan pelanggan ini akan dihapus dari sistem.
            </p>

            <div class="flex gap-3 w-full">
                <button onclick="window.tutupPopupBatal()" class="flex-1 bg-slate-100 text-slate-700 font-bold py-3 rounded-xl hover:bg-slate-200 transition active:scale-95 text-xs">
                    Kembali
                </button>
                <button onclick="window.eksekusiBatalOrder('${key}')" class="flex-1 bg-red-500 text-white font-bold py-3 rounded-xl hover:bg-red-600 transition shadow-md active:scale-95 text-xs flex justify-center items-center gap-2">
                    <i class="fa-solid fa-trash-can"></i> Ya, Batalkan
                </button>
            </div>
        </div>
    `;

    document.body.appendChild(modal);
    
    // Animasi masuk agar munculnya mulus
    setTimeout(() => {
        modal.classList.remove('opacity-0');
        modal.querySelector('div').classList.remove('scale-95');
    }, 10);
};

window.tutupPopupBatal = () => {
    const modal = document.getElementById('popup-batal-custom');
    if (modal) {
        modal.classList.add('opacity-0');
        modal.querySelector('div').classList.add('scale-95');
        setTimeout(() => modal.remove(), 300);
    }
};

// ==========================================
// TAHAP 1: MESIN DATA MASTER (KATEGORI, TOPPING, VARIAN)
// ==========================================
window.masterKategori = JSON.parse(localStorage.getItem('master_kategori')) || [];
window.masterTopping = JSON.parse(localStorage.getItem('master_topping')) || [];
window.masterVarian = JSON.parse(localStorage.getItem('master_varian')) || [];

// 1. Penerjemah Nama Topping (Menjamin Boba, Telur, Keju tampil normal)
window.resolveTopping = (tid) => {
    if (!tid) return { id: '', nama: 'Topping', harga: 0 };
    if (typeof tid === 'object' && tid !== null) {
        return {
            id: tid.id || '',
            nama: tid.nama || tid.name || 'Topping',
            harga: Number(tid.harga || tid.price || 0)
        };
    }
    const tidStr = String(tid).trim();
    // 1. Cek di master data
    const master = (window.masterTopping || []).find(t => t.id === tidStr || t.nama === tidStr || t.name === tidStr);
    if (master) {
        return { id: master.id, nama: master.nama || master.name, harga: Number(master.harga || 0) };
    }
    // 2. Fallback dictionary untuk ID yang tersimpan di Firebase
    const fallbackDict = {
        'top_1789440807416': { nama: 'Boba', harga: 3000 },
        'top_1789440819591': { nama: 'Telur', harga: 3000 },
        'top_1789440830187': { nama: 'Keju', harga: 3000 },
        'top_jelly': { nama: 'Grass Jelly', harga: 3000 },
        'top_cheese': { nama: 'Cheese Foam', harga: 4000 },
        'top_pudding': { nama: 'Egg Pudding', harga: 3000 },
        'top_oreo': { nama: 'Oreo Crumb', harga: 2000 },
        'top_sosis': { nama: 'Sosis', harga: 3000 }
    };
    if (fallbackDict[tidStr]) {
        return { id: tidStr, ...fallbackDict[tidStr] };
    }
    let cleanName = tidStr.replace(/^top_/, '').replace(/[0-9_]/g, ' ').trim();
    if (!cleanName) cleanName = "Topping Tambahan";
    return { id: tidStr, nama: cleanName, harga: 3000 };
};

// 2. Penerjemah Varian Produk
window.resolveVarian = (vid) => {
    if (!vid) return null;
    if (typeof vid === 'object' && vid !== null && vid.opsi) return vid;
    const vidStr = String(vid).trim();
    const master = (window.masterVarian || []).find(v => v.id === vidStr || v.nama === vidStr || v.name === vidStr);
    if (master) return master;
    const fallbackDict = {
        'var_ukuran': { id: 'var_ukuran', nama: 'PILIH UKURAN', opsi: [{ namaOpsi: 'Regular', harga: 0 }, { namaOpsi: 'Large', harga: 3000 }] },
        'var_es': { id: 'var_es', nama: 'KADAR ES', opsi: [{ namaOpsi: 'Normal Ice', harga: 0 }, { namaOpsi: 'Less Ice', harga: 0 }, { namaOpsi: 'No Ice', harga: 0 }] },
        'var_gula': { id: 'var_gula', nama: 'KADAR GULA', opsi: [{ namaOpsi: 'Normal Sugar (100%)', harga: 0 }, { namaOpsi: 'Less Sugar (50%)', harga: 0 }, { namaOpsi: 'No Sugar (0%)', harga: 0 }] }
    };
    return fallbackDict[vidStr] || null;
};

