// ==========================================
// MESIN SINKRONISASI KATEGORI LENGKAP (REAL-TIME FIREBASE)
// ==========================================
window.sinkronkanSemuaKategori = async () => {
    let list = [];
    if (window.masterKategori && Array.isArray(window.masterKategori)) {
        list.push(...window.masterKategori);
    }
    // Kumpulkan dari menu nyata di database
    if (typeof globalMenus === 'object' && globalMenus) {
        Object.values(globalMenus).forEach(m => {
            if (m && m.category) list.push(m.category);
            if (m && m.kategori) list.push(m.kategori);
        });
    }
    // Kumpulkan dari default
    const defaultList = ['Coffee', 'Tea', 'Milky & Creamy', 'Snacks', 'Signature', 'Non-Coffee', 'Makanan', 'Cake/Kue'];
    list.push(...defaultList);

    const cleanMap = new Map();
    list.forEach(k => {
        if (!k) return;
        const name = (typeof k === 'object' ? (k.name || k.nama || k.id) : String(k)).trim();
        if (name && !cleanMap.has(name.toLowerCase())) {
            cleanMap.set(name.toLowerCase(), name);
        }
    });

    const uniqueKategori = Array.from(cleanMap.values());
    window.masterKategori = uniqueKategori;
    localStorage.setItem('master_kategori', JSON.stringify(uniqueKategori));

    try {
        await set(ref(db, 'master_kategori'), uniqueKategori);
    } catch(e) {}

    if (typeof window.renderMasterKategori === 'function') window.renderMasterKategori();
    if (typeof window.renderSelectKategori === 'function') window.renderSelectKategori();
    if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
    if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
};

// CRUD MASTER KATEGORI
window.tambahMasterKategori = async () => {
    const inputEl = document.getElementById('input-kategori-baru');
    if (!inputEl) return;
    const nama = inputEl.value.trim();
    if (!nama) return alert("Ketik nama kategori baru terlebih dahulu!");

    if (!Array.isArray(window.masterKategori)) window.masterKategori = [];
    const exists = window.masterKategori.some(item => item.toLowerCase() === nama.toLowerCase());
    if (exists) return alert("Kategori ini sudah ada di daftar!");

    window.masterKategori.push(nama);
    inputEl.value = '';
    localStorage.setItem('master_kategori', JSON.stringify(window.masterKategori));

    try {
        await set(ref(db, 'master_kategori'), window.masterKategori);
        const catKey = 'cat_' + nama.toLowerCase().replace(/[^a-z0-9]/g, '_');
        await set(ref(db, 'categories/' + catKey), { id: catKey, name: nama, order: window.masterKategori.length });
    } catch(e) {
        console.warn("Gagal simpan kategori baru:", e);
    }

    window.renderMasterKategori();
    if (typeof window.renderSelectKategori === 'function') window.renderSelectKategori();
    if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
    if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
};

window.editMasterKategori = async (namaLama) => {
    if (!namaLama) return;
    const namaBaru = prompt(`Ubah nama kategori "${namaLama}" menjadi:`, namaLama);
    if (!namaBaru) return;
    const cleanBaru = namaBaru.trim();
    if (!cleanBaru || cleanBaru === namaLama) return;

    if (!Array.isArray(window.masterKategori)) window.masterKategori = [];
    const exists = window.masterKategori.some(item => item.toLowerCase() === cleanBaru.toLowerCase() && item.toLowerCase() !== namaLama.toLowerCase());
    if (exists) return alert("Nama kategori tersebut sudah ada di daftar!");

    // 1. Perbarui array masterKategori
    window.masterKategori = window.masterKategori.map(item => item === namaLama ? cleanBaru : item);
    localStorage.setItem('master_kategori', JSON.stringify(window.masterKategori));

    try {
        // 2. Simpan ke Firebase master_kategori
        await set(ref(db, 'master_kategori'), window.masterKategori);

        // 3. Perbarui semua menu di Firebase yang memakai kategori lama
        if (typeof globalMenus === 'object' && globalMenus) {
            const updates = {};
            Object.keys(globalMenus).forEach(mKey => {
                const m = globalMenus[mKey];
                if (m && (m.category === namaLama || m.kategori === namaLama)) {
                    updates[`menus/${mKey}/category`] = cleanBaru;
                    m.category = cleanBaru;
                }
            });
            if (Object.keys(updates).length > 0) {
                await update(ref(db), updates);
            }
        }

        // 4. Perbarui juga di node /categories
        const catKey = 'cat_' + cleanBaru.toLowerCase().replace(/[^a-z0-9]/g, '_');
        await set(ref(db, 'categories/' + catKey), { id: catKey, name: cleanBaru });

        alert(`Sukses! Kategori "${namaLama}" berhasil diubah menjadi "${cleanBaru}".`);
    } catch(e) {
        console.error("Gagal update kategori di database:", e);
        alert("Gagal memperbarui kategori: " + e.message);
    }

    window.renderMasterKategori();
    if (typeof window.renderSelectKategori === 'function') window.renderSelectKategori();
    if (typeof window.renderPanelMenu === 'function') window.renderPanelMenu();
    if (typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
    if (typeof window.renderKatalog === 'function') window.renderKatalog();
    if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
};

