window.toggleFormPromo = (isActive) => {
    const wadah = document.getElementById('wadah-opsi-promo');
    if (wadah) {
        if (isActive) wadah.classList.remove('hidden');
        else wadah.classList.add('hidden');
    }
    if (typeof window.updateFormPromoPreview === 'function') {
        window.updateFormPromoPreview();
    }
};

window.updateFormPromoPreview = () => {
    const priceEl = document.getElementById('fm-price');
    const typeEl = document.getElementById('fm-promo-type');
    const valEl = document.getElementById('fm-promo-val');
    const resultEl = document.getElementById('promo-calc-result');
    const lblEl = document.getElementById('lbl-promo-val');
    if (!resultEl) return;

    const basePrice = Number(priceEl ? priceEl.value : 0) || 0;
    const type = typeEl ? typeEl.value : 'nominal';
    const val = Number(valEl ? valEl.value : 0) || 0;

    if (lblEl) {
        lblEl.innerText = type === 'percent' ? 'Diskon Persen (%)' : 'Nominal Potongan (Rp)';
    }

    let finalPrice = basePrice;
    if (type === 'percent') {
        const pct = Math.min(100, Math.max(0, val));
        finalPrice = Math.max(0, Math.round(basePrice * (1 - pct / 100)));
    } else {
        finalPrice = Math.max(0, basePrice - Math.min(basePrice, val));
    }

    resultEl.innerHTML = `
        <span class="text-[10px] text-slate-400 line-through mr-1.5">Rp ${basePrice.toLocaleString('id-ID')}</span>
        <span class="text-sm font-black text-rose-600">Rp ${finalPrice.toLocaleString('id-ID')}</span>
    `;
};

