// ==========================================
window.updateMenuHppPreview = () => {
    const priceVal = Number(document.getElementById('fm-price')?.value || 0);
    const hppVal = Number(document.getElementById('fm-hpp')?.value || 0);
    const ojolPct = Math.max(0, Number(document.getElementById('fm-ojol-pct')?.value ?? 20));
    const qrisPct = Math.max(0, Number(document.getElementById('fm-qris-pct')?.value ?? 0.7));
    const wastePct = Math.max(0, Number(document.getElementById('fm-waste-pct')?.value ?? 3));
    const isPromo = document.getElementById('fm-promo')?.checked;
    const promoType = document.getElementById('fm-promo-type')?.value || 'nominal';
    const promoRaw = Number(document.getElementById('fm-promo-val')?.value || 0);
    const valEl = document.getElementById('menu-hpp-margin-value');
    const breakdownEl = document.getElementById('menu-hpp-margin-breakdown');
    if (!valEl) return;

    let sellPrice = priceVal;
    if (isPromo && promoRaw > 0 && priceVal > 0) {
        sellPrice = promoType === 'percent'
            ? Math.max(0, Math.round(priceVal * (1 - Math.min(100, promoRaw) / 100)))
            : Math.max(0, priceVal - promoRaw);
    }

    if (sellPrice <= 0) {
        valEl.innerHTML = '<span class="text-slate-400 font-bold">Isi Harga Jual &amp; HPP</span>';
        if (breakdownEl) breakdownEl.classList.add('hidden');
        return;
    }
    const grossMargin = sellPrice - hppVal;
    const avgFeePct = (ojolPct + qrisPct) / 2;
    const channelFeeRp = Math.round(sellPrice * (avgFeePct / 100));
    const wasteRp = Math.round(sellPrice * (wastePct / 100));
    const netMarginRp = sellPrice - hppVal - channelFeeRp - wasteRp;
    const netMarginPct = Math.round((netMarginRp / sellPrice) * 100);
    const cls = netMarginRp >= 0 ? 'text-emerald-700' : 'text-rose-600';
    valEl.innerHTML = `<span class="${cls}">Rp ${netMarginRp.toLocaleString('id-ID')} / porsi (${netMarginPct}%)</span>`;
    if (breakdownEl) {
        breakdownEl.classList.remove('hidden');
        breakdownEl.innerHTML = `Jual Rp ${sellPrice.toLocaleString('id-ID')} − HPP Rp ${hppVal.toLocaleString('id-ID')} − Avg Ojol/QRIS (${avgFeePct.toFixed(1)}%: Rp ${channelFeeRp.toLocaleString('id-ID')}) − Waste (${wastePct}%: Rp ${wasteRp.toLocaleString('id-ID')}) | Laba Kotor: Rp ${grossMargin.toLocaleString('id-ID')}`;
    }
};

window.renderResepMenuEditor = (recipeItems = []) => {
    const wadah = document.getElementById('wadah-resep-menu');
    if (!wadah) return;
    if (!Array.isArray(recipeItems) || recipeItems.length === 0) {
        wadah.innerHTML = `<p id="resep-empty-hint" class="text-[10px] text-slate-500 italic">Belum ada bahan baku diatur (menggunakan deteksi otomatis standar).</p>`;
        return;
    }
    wadah.innerHTML = '';
    recipeItems.forEach(item => {
        if (item && (item.itemKey || item.itemName)) {
            window.tambahBarisResepMenu(item);
        }
    });
    if (wadah.querySelectorAll('.resep-menu-row').length === 0) {
        wadah.innerHTML = `<p id="resep-empty-hint" class="text-[10px] text-slate-500 italic">Belum ada bahan baku diatur (menggunakan deteksi otomatis standar).</p>`;
    }
};

window.tambahBarisResepMenu = (prefill = null) => {
    const wadah = document.getElementById('wadah-resep-menu');
    if (!wadah) return;
    const emptyHint = wadah.querySelector('#resep-empty-hint') || wadah.querySelector('p');
    if (emptyHint) emptyHint.remove();

    const invEntries = Object.entries(globalInventory || {}).sort((a, b) =>
        String(a[1]?.name || '').localeCompare(String(b[1]?.name || ''))
    );

    if (invEntries.length === 0 && !prefill?.itemKey) {
        wadah.innerHTML = `<p id="resep-empty-hint" class="text-[10px] text-amber-700 bg-amber-50 border border-amber-200 rounded-lg p-2 font-bold">Stok Gudang masih kosong. Tambahkan bahan baku terlebih dahulu di modul Manajemen Stok.</p>`;
        return;
    }

    const selectedKey = prefill?.itemKey || '';
    const prefillName = prefill?.itemName || '';
    const prefillQty = prefill?.qty !== undefined ? prefill.qty : '';
    let selectedUnit = prefill?.unit || 'Pcs';

    let optionsHtml = `<option value="">-- Pilih Bahan Gudang --</option>`;
    let hasMatched = false;
    invEntries.forEach(([k, inv]) => {
        const unit = inv?.unit || 'Pcs';
        const isSel = selectedKey === k || (!selectedKey && prefillName && String(inv?.name || '').toLowerCase() === String(prefillName).toLowerCase());
        if (isSel) {
            hasMatched = true;
            selectedUnit = unit;
        }
        const label = `${inv?.name || k} (Sisa: ${Number(inv?.qty) || 0} ${unit})`;
        optionsHtml += `<option value="${k}" data-name="${String(inv?.name || '').replace(/"/g, '&quot;')}" data-unit="${String(unit).replace(/"/g, '&quot;')}" ${isSel ? 'selected' : ''}>${label}</option>`;
    });
    if (selectedKey && !hasMatched) {
        optionsHtml += `<option value="${selectedKey}" data-name="${String(prefillName || selectedKey).replace(/"/g, '&quot;')}" data-unit="${String(selectedUnit).replace(/"/g, '&quot;')}" selected>${prefillName || selectedKey} (${selectedUnit})</option>`;
    }

    const row = document.createElement('div');
    row.className = 'resep-menu-row flex items-center gap-1.5 bg-white p-2 rounded-xl border border-emerald-200 shadow-2xs';
    row.innerHTML = `
        <select onchange="window.updateUnitBarisResep(this)" class="resep-inv-select flex-1 min-w-0 bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[11px] font-bold text-slate-700 focus:outline-none focus:border-emerald-500">
            ${optionsHtml}
        </select>
        <input type="number" step="any" min="0.001" value="${prefillQty}" placeholder="Takaran" class="resep-qty-input w-20 bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[11px] font-black text-emerald-700 text-center focus:outline-none focus:border-emerald-500">
        <span class="resep-unit-badge text-[10px] font-black text-emerald-800 bg-emerald-100 px-2 py-2 rounded-lg shrink-0 min-w-[44px] text-center">${selectedUnit}</span>
        <button type="button" onclick="window.hapusBarisResepMenu(this)" class="w-8 h-8 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-500 flex items-center justify-center shrink-0 transition" title="Hapus Bahan">
            <i class="fa-solid fa-trash-can text-[11px]"></i>
        </button>
    `;
    wadah.appendChild(row);
};

window.updateUnitBarisResep = (selectEl) => {
    if (!selectEl) return;
    const row = selectEl.closest('.resep-menu-row');
    const badge = row?.querySelector('.resep-unit-badge');
    const opt = selectEl.options[selectEl.selectedIndex];
    if (badge && opt) {
        badge.innerText = opt.dataset.unit || 'Pcs';
    }
};

window.hapusBarisResepMenu = (btnEl) => {
    const row = btnEl?.closest('.resep-menu-row');
    const wadah = document.getElementById('wadah-resep-menu');
    if (row) row.remove();
    if (wadah && wadah.querySelectorAll('.resep-menu-row').length === 0) {
        wadah.innerHTML = `<p id="resep-empty-hint" class="text-[10px] text-slate-500 italic">Belum ada bahan baku diatur (menggunakan deteksi otomatis standar).</p>`;
    }
};

window.kumpulkanResepDariForm = () => {
    const wadah = document.getElementById('wadah-resep-menu');
    if (!wadah) return [];
    const merged = new Map();
    wadah.querySelectorAll('.resep-menu-row').forEach(row => {
        const sel = row.querySelector('.resep-inv-select');
        const qtyInput = row.querySelector('.resep-qty-input');
        const itemKey = sel ? sel.value : '';
        const qty = Number(qtyInput ? qtyInput.value : 0) || 0;
        if (!itemKey || qty <= 0) return;
        const opt = sel.options[sel.selectedIndex];
        const inv = globalInventory?.[itemKey];
        const itemName = inv?.name || opt?.dataset?.name || itemKey;
        const unit = inv?.unit || opt?.dataset?.unit || 'Pcs';
        if (merged.has(itemKey)) {
            const prev = merged.get(itemKey);
            prev.qty = Math.round((prev.qty + qty) * 1000) / 1000;
        } else {
            merged.set(itemKey, { itemKey, itemName, qty, unit });
        }
    });
    return Array.from(merged.values());
};

window.simpanMenuBaru = async () => {
    const namaEl = document.getElementById('fm-name');
    const priceEl = document.getElementById('fm-price');
    const hppEl = document.getElementById('fm-hpp');
    const descEl = document.getElementById('fm-desc');
    const bestSellerEl = document.getElementById('fm-bestseller'); // <--- Sensor Best Seller
    
    const catEl = document.getElementById('fm-cat') || document.getElementById('select-kategori-menu');

    if (!namaEl || !namaEl.value.trim()) return alert("Nama Menu wajib diisi!");
    if (!priceEl || !priceEl.value) return alert("Harga Menu wajib diisi!");

    let kategoriValue = (catEl && catEl.value && catEl.value.trim() !== '') ? catEl.value.trim() : '';
    if (!kategoriValue) {
        kategoriValue = (window.masterKategori && window.masterKategori.length > 0) ? window.masterKategori[0] : 'Coffee';
    }

    // Pastikan kategori yang dipilih tercatat di masterKategori
    if (!Array.isArray(window.masterKategori)) window.masterKategori = [];
    if (!window.masterKategori.some(k => k.toLowerCase() === kategoriValue.toLowerCase())) {
        window.masterKategori.push(kategoriValue);
        localStorage.setItem('master_kategori', JSON.stringify(window.masterKategori));
        try { set(ref(db, 'master_kategori'), window.masterKategori); } catch(e) {}
    }

    const toppingTerpilih = [];
    document.querySelectorAll('.checkbox-topping-menu:checked').forEach(cb => toppingTerpilih.push(cb.value));

    const varianTerpilih = [];
    document.querySelectorAll('.checkbox-varian-menu:checked').forEach(cb => varianTerpilih.push(cb.value));

    const resepTerpilih = typeof window.kumpulkanResepDariForm === 'function' ? window.kumpulkanResepDariForm() : [];
    const caraPembuatanText = (document.getElementById('fm-cara-pembuatan')?.value || '').trim();

    const imgUrlEl = document.getElementById('fm-image-url');
    const imgFileEl = document.getElementById('fm-image-file');
    let finalImageUrl = 'logo-192.png';

    if (imgFileEl && imgFileEl.files.length > 0) {
        const file = imgFileEl.files[0];
        finalImageUrl = await new Promise((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result);
            reader.readAsDataURL(file);
        });
    } else if (imgUrlEl && imgUrlEl.value.trim() !== '') {
        finalImageUrl = imgUrlEl.value.trim();
    }

    const basePrice = Number(priceEl.value) || 0;
    const hppCost = hppEl ? Math.max(0, Number(hppEl.value) || 0) : 0;
    const isBS = bestSellerEl ? bestSellerEl.checked : false;

    // Diskon & Promo
    const promoEl = document.getElementById('fm-promo');
    const promoTypeEl = document.getElementById('fm-promo-type');
    const promoValEl = document.getElementById('fm-promo-val');
    const promoLabelEl = document.getElementById('fm-promo-label');

    const isPromo = promoEl ? promoEl.checked : false;
    const promoType = promoTypeEl ? promoTypeEl.value : 'nominal';
    const promoVal = Number(promoValEl ? promoValEl.value : 0) || 0;
    const promoLabel = promoLabelEl ? promoLabelEl.value.trim() : '';

    let discNominal = 0;
    let discPercent = 0;
    let promoPrice = basePrice;

    if (isPromo && promoVal > 0) {
        if (promoType === 'percent') {
            discPercent = Math.min(100, Math.max(0, promoVal));
            promoPrice = Math.max(0, Math.round(basePrice * (1 - discPercent / 100)));
            discNominal = basePrice - promoPrice;
        } else {
            discNominal = Math.min(basePrice, Math.max(0, promoVal));
            promoPrice = Math.max(0, basePrice - discNominal);
            discPercent = basePrice > 0 ? Math.round((discNominal / basePrice) * 100) : 0;
        }
    }

    const hasVar = varianTerpilih.length > 0;
    const hasTop = toppingTerpilih.length > 0;

    // Paket Gabungan Produk (Bundle / Combo)
    const isPackageEl = document.getElementById('fm-is-package');
    const isPackage = isPackageEl ? isPackageEl.checked : false;
    let packageItems = [];
    let packageDiskonTipe = 'nominal';
    let packageDiskonVal = 0;
    let packageGratisId = null;
    let packageGratisName = '';

    if (isPackage) {
        document.querySelectorAll('.checkbox-paket-item:checked').forEach(cb => {
            const itemId = cb.dataset.id;
            const itemQtyEl = document.querySelector(`.input-paket-qty[data-id="${itemId}"]`);
            const itemQty = Number(itemQtyEl ? itemQtyEl.value : 1) || 1;
            packageItems.push({
                id: itemId,
                name: cb.dataset.name || '',
                price: Number(cb.dataset.price) || 0,
                qty: itemQty
            });
        });

        if (packageItems.length === 0) {
            return alert("Harap pilih minimal 1 produk untuk Menu Paket Gabungan!");
        }

        const diskonRadio = document.querySelector('input[name="fm_paket_diskon_tipe"]:checked');
        packageDiskonTipe = diskonRadio ? diskonRadio.value : 'nominal';
        packageDiskonVal = Number(document.getElementById('fm-paket-diskon-val')?.value || 0);
        const gratisSelect = document.getElementById('fm-paket-gratis-select');
        packageGratisId = gratisSelect ? gratisSelect.value : null;
        if (gratisSelect && gratisSelect.selectedIndex > 0) {
            packageGratisName = gratisSelect.options[gratisSelect.selectedIndex].text.split('(')[0].trim();
        }
    }

    const ojolFeePct = Math.max(0, Number(document.getElementById('fm-ojol-pct')?.value ?? 20));
    const qrisFeePct = Math.max(0, Number(document.getElementById('fm-qris-pct')?.value ?? 0.7));
    const wastePct = Math.max(0, Number(document.getElementById('fm-waste-pct')?.value ?? 3));
    const effSellForMargin = isPromo ? promoPrice : basePrice;
    const netMarginRp = effSellForMargin - hppCost - Math.round(effSellForMargin * (((ojolFeePct + qrisFeePct) / 2) / 100)) - Math.round(effSellForMargin * (wastePct / 100));
    const netMarginPct = effSellForMargin > 0 ? Number(((netMarginRp / effSellForMargin) * 100).toFixed(1)) : 0;

    const payload = {
        name: namaEl.value.trim(),
        description: descEl ? descEl.value.trim() : '',
        price: basePrice,
        hpp: hppCost,
        ojolFeePct,
        qrisFeePct,
        wastePct,
        netMarginRp,
        netMarginPct,
        category: kategoriValue,
        isAvailable: true,
        imageUrl: finalImageUrl, 
        toppingIds: hasTop ? toppingTerpilih : [],
        varianIds: hasVar ? varianTerpilih : [],
        varian: hasVar ? varianTerpilih : [],
        toppings: hasTop ? toppingTerpilih : [],
        resep: resepTerpilih,
        caraPembuatan: caraPembuatanText,
        hasVariant: hasVar,
        hasTopping: hasTop,
        isBestSeller: isBS,
        isPromo: isPromo,
        discountType: promoType,
        discountNominal: discNominal,
        discountPercent: discPercent,
        promoPrice: promoPrice,
        promoLabel: promoLabel,
        isPackage: isPackage,
        packageItems: isPackage ? packageItems : [],
        packageDiscountType: isPackage ? packageDiskonTipe : null,
        packageDiscountValue: isPackage ? packageDiskonVal : 0,
        packageFreeProductId: isPackage ? packageGratisId : null,
        packageFreeProductName: isPackage ? packageGratisName : null
    };

    const operatorName = String(localStorage.getItem('mainstay_staff_name') || 'Owner').replace(/\s*\(\s*master\s*\)/i, '').trim() || 'Owner';
    const effectivePromoPrice = isPromo ? promoPrice : basePrice;

    if (window.editMenuKeyTarget) {
        // 1. JIKA MODE EDIT: Update dan timpa data lama + catat log riwayat perubahan harga
        const targetKey = window.editMenuKeyTarget;
        const oldMenu = globalMenus[targetKey] || {};
        const oldBasePrice = Number(oldMenu.price || 0);
        const oldEffPromo = oldMenu.isPromo ? Number(oldMenu.promoPrice ?? oldBasePrice) : oldBasePrice;
        const priceHistory = Array.isArray(oldMenu.priceHistory) ? [...oldMenu.priceHistory] : [];

        if (priceHistory.length === 0 && oldBasePrice > 0) {
            priceHistory.push({
                oldPrice: oldBasePrice,
                newPrice: oldBasePrice,
                oldPromoPrice: oldEffPromo,
                newPromoPrice: oldEffPromo,
                changedAt: oldMenu.lastPriceChangedAt || Date.now(),
                changedBy: operatorName,
                note: 'Harga Sebelumnya'
            });
        }

        if (oldBasePrice !== basePrice || oldEffPromo !== effectivePromoPrice) {
            priceHistory.push({
                oldPrice: oldBasePrice,
                newPrice: basePrice,
                oldPromoPrice: oldEffPromo,
                newPromoPrice: effectivePromoPrice,
                changedAt: Date.now(),
                changedBy: operatorName,
                note: oldBasePrice !== basePrice ? 'Perubahan Harga Dasar' : 'Perubahan Harga Promo'
            });
            payload.lastPriceChangedAt = Date.now();
        } else if (oldMenu.lastPriceChangedAt) {
            payload.lastPriceChangedAt = oldMenu.lastPriceChangedAt;
        }
        payload.priceHistory = priceHistory;

        const menuRef = ref(db, 'menus/' + targetKey);
        if (!hasVar) {
            try { await set(ref(db, 'menus/' + targetKey + '/varian'), null); } catch(e) {}
            try { await set(ref(db, 'menus/' + targetKey + '/varianIds'), null); } catch(e) {}
        }
        if (!hasTop) {
            try { await set(ref(db, 'menus/' + targetKey + '/toppings'), null); } catch(e) {}
            try { await set(ref(db, 'menus/' + targetKey + '/toppingIds'), null); } catch(e) {}
        }
        if (resepTerpilih.length === 0) {
            try { await set(ref(db, 'menus/' + targetKey + '/resep'), null); } catch(e) {}
        }
        try { await update(menuRef, payload); } catch(e) { console.warn("RTDB update error:", e); }

        globalMenus[targetKey] = { ...payload, key: targetKey };
        if (!hasVar) {
            delete globalMenus[targetKey].varian;
            delete globalMenus[targetKey].varianIds;
        }
        if (!hasTop) {
            delete globalMenus[targetKey].toppings;
            delete globalMenus[targetKey].toppingIds;
        }
        try { localStorage.setItem('mainstay_cached_menus', JSON.stringify(globalMenus)); } catch(e) {}
        console.log("[Catalog Persist Success]", targetKey, payload);
        if (typeof window.catatLogAktivitas === 'function') {
            if (oldBasePrice !== basePrice || oldEffPromo !== effectivePromoPrice) {
                window.catatLogAktivitas({
                    category: 'price_change',
                    actionType: 'Price Change',
                    targetType: 'menu',
                    targetKey: targetKey,
                    targetName: payload.name,
                    beforeVal: `${formatRupiah(oldBasePrice)}${oldMenu.isPromo ? ` (Promo ${formatRupiah(oldEffPromo)})` : ''}`,
                    afterVal: `${formatRupiah(basePrice)}${isPromo ? ` (Promo ${formatRupiah(effectivePromoPrice)})` : ''}`,
                    summary: `Perubahan harga menu "${payload.name}": ${formatRupiah(oldBasePrice)} -> ${formatRupiah(basePrice)}`
                });
            }
            window.catatLogAktivitas({
                category: 'menu_edit',
                actionType: 'Menu Edit',
                targetType: 'menu',
                targetKey: targetKey,
                targetName: payload.name,
                beforeVal: oldMenu.name || payload.name,
                afterVal: `${payload.name} (${payload.category})`,
                summary: `Memperbarui menu "${payload.name}" di katalog (Kategori: ${payload.category}, Harga: ${formatRupiah(basePrice)}).`
            });
        }
        alert('Menu berhasil diupdate!');
        
        // Matikan mode edit & kembalikan tombol jadi warna kuning
        window.editMenuKeyTarget = null;
        const btns = document.querySelectorAll('#owner-inner-panels-container button');
        btns.forEach(btn => {
            if (btn.innerText.toUpperCase().includes('UPDATE')) {
                btn.innerHTML = '<i class="fa-solid fa-save mr-2"></i> SIMPAN KE DATABASE';
                btn.classList.add('bg-amber-500', 'hover:bg-amber-600');
                btn.classList.remove('bg-blue-600', 'hover:bg-blue-700');
            }
        });
        const qrQuickBtn = document.getElementById('btn-qr-edit-menu');
        if (qrQuickBtn) qrQuickBtn.classList.add('hidden');
    } else {
        // 2. JIKA MODE TAMBAH BARU: Buat data baru (Create) + catat harga awal
        payload.lastPriceChangedAt = Date.now();
        payload.priceHistory = [{
            oldPrice: 0,
            newPrice: basePrice,
            oldPromoPrice: 0,
            newPromoPrice: effectivePromoPrice,
            changedAt: payload.lastPriceChangedAt,
            changedBy: operatorName,
            note: 'Harga Awal Menu'
        }];

        const menuRef = ref(db, 'menus');
        let newKey = null;
        try {
            const newRef = await push(menuRef, payload);
            newKey = newRef ? newRef.key : null;
        } catch(e) { console.warn("RTDB push error:", e); }

        if (!newKey) {
            newKey = 'menu_' + Date.now();
        }

        globalMenus[newKey] = { ...payload, key: newKey };
        try { localStorage.setItem('mainstay_cached_menus', JSON.stringify(globalMenus)); } catch(e) {}
        console.log("[Catalog Create Success]", newKey, payload);
        if (typeof window.catatLogAktivitas === 'function') {
            window.catatLogAktivitas({
                category: 'menu_edit',
                actionType: 'Menu Edit',
                targetType: 'menu',
                targetKey: newKey,
                targetName: payload.name,
                beforeVal: '-',
                afterVal: `${payload.name} (${formatRupiah(basePrice)})`,
                summary: `Menambahkan menu baru "${payload.name}" (${payload.category}) dengan harga ${formatRupiah(basePrice)}.`
            });
        }
        alert('Menu baru berhasil disimpan!');
    }

    namaEl.value = '';
    priceEl.value = '';
    if (hppEl) hppEl.value = '';
    if (descEl) descEl.value = '';
    const caraBuatEl = document.getElementById('fm-cara-pembuatan');
    if (caraBuatEl) caraBuatEl.value = '';
    if (typeof window.updateMenuHppPreview === 'function') window.updateMenuHppPreview();
    if (bestSellerEl) bestSellerEl.checked = false;
    if (promoEl) promoEl.checked = false;
    if (promoValEl) promoValEl.value = '';
    if (promoLabelEl) promoLabelEl.value = '';
    window.toggleFormPromo(false);
    const pkgEl = document.getElementById('fm-is-package');
    if (pkgEl) pkgEl.checked = false;
    if (typeof window.toggleFormPaketGabungan === 'function') window.toggleFormPaketGabungan(false);
    if (imgUrlEl) imgUrlEl.value = '';
    if (imgFileEl) imgFileEl.value = '';
    document.querySelectorAll('.checkbox-topping-menu, .checkbox-varian-menu, #fm-bestseller, #fm-promo, #fm-is-package').forEach(cb => cb.checked = false);
    if (typeof window.renderResepMenuEditor === 'function') window.renderResepMenuEditor([]);

    if(typeof window.renderPanelMenu === 'function') window.renderPanelMenu();
    if(typeof window.renderClientKategoriButtons === 'function') window.renderClientKategoriButtons();
    if(typeof window.renderPromoBestsellerCarousel === 'function') window.renderPromoBestsellerCarousel();
    if(typeof window.renderKatalog === 'function') window.renderKatalog();
    if(typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
};
// ==========================================

window.normalizeMenuSelectionTokens = (rawA, rawB) => {
    const out = [];
    const pushItem = (val, keyHint = '') => {
        if (val === null || val === undefined || val === false) return;
        if (val === true && keyHint) {
            out.push({ id: String(keyHint).trim(), raw: keyHint });
            return;
        }
        if (typeof val === 'string' || typeof val === 'number') {
            const s = String(val).trim();
            if (s) out.push({ id: s, raw: val });
            return;
        }
        if (typeof val === 'object') {
            const id = String(val.id || val.key || keyHint || val.nama || val.name || '').trim();
            const nama = String(val.nama || val.name || id || '').trim();
            if (id || nama) out.push({ id: id || nama, nama, obj: val });
        }
    };
    [rawA, rawB].forEach(src => {
        if (!src) return;
        if (Array.isArray(src)) {
            src.forEach(item => pushItem(item));
        } else if (typeof src === 'object') {
            Object.entries(src).forEach(([k, v]) => pushItem(v, k));
        } else if (typeof src === 'string') {
            src.split(',').forEach(part => pushItem(part));
        }
    });
    return out;
};

// ==========================================
// JEMBATAN 2: PENARIK TOPPING (BERSIH & TAHAN EDIT)
// ==========================================
window.renderCheckboxTopping = (explicitSelected = null) => {
    const wadah = document.getElementById('wadah-checkbox-topping');
    if (!wadah) return;

    const currentChecked = Array.from(wadah.querySelectorAll('.checkbox-topping-menu:checked')).map(cb => String(cb.value));
    let selectedTokens = [];
    if (Array.isArray(explicitSelected)) {
        selectedTokens = explicitSelected;
    } else if (window.editMenuKeyTarget && globalMenus[window.editMenuKeyTarget]) {
        const em = globalMenus[window.editMenuKeyTarget];
        selectedTokens = window.normalizeMenuSelectionTokens(em.toppingIds, em.toppings);
    } else {
        selectedTokens = currentChecked.map(id => ({ id }));
    }

    const baseList = Array.isArray(window.masterTopping)
        ? window.masterTopping.filter(Boolean)
        : (window.masterTopping && typeof window.masterTopping === 'object' ? Object.values(window.masterTopping).filter(Boolean) : []);

    const listToRender = [...baseList];
    selectedTokens.forEach(tok => {
        const tokId = String(tok.id || '').trim();
        const tokName = String(tok.nama || tok.name || tokId).trim();
        const exists = listToRender.some(t =>
            String(t.id || '').trim() === tokId ||
            (tokName && String(t.name || t.nama || '').trim().toLowerCase() === tokName.toLowerCase())
        );
        if (!exists && (tokId || tokName)) {
            listToRender.push({
                id: tokId || tokName,
                nama: tok.obj?.nama || tok.obj?.name || tokName || tokId,
                harga: Number(tok.obj?.harga || tok.obj?.price || 0),
                _fromMenu: true
            });
        }
    });

    if (listToRender.length === 0) {
        wadah.innerHTML = '<p class="text-[10px] text-slate-400 italic px-1">Belum ada topping di Data Master.</p>';
        return;
    }

    wadah.innerHTML = listToRender.map(top => {
        const topId = String(top.id || top.nama || top.name || '').trim();
        const topName = String(top.name || top.nama || topId).trim();
        const hrg = Number(top.harga || top.price || 0);
        const isChecked = selectedTokens.some(tok => {
            const tid = String(tok.id || '').trim();
            const tname = String(tok.nama || tok.name || '').trim().toLowerCase();
            return tid === topId || tid.toLowerCase() === topName.toLowerCase() || (tname && tname === topName.toLowerCase());
        });
        return `
        <label class="flex items-center gap-2.5 p-2.5 min-h-[40px] bg-white border ${isChecked ? 'border-amber-400 bg-amber-50/40' : 'border-slate-200'} rounded-xl cursor-pointer hover:bg-amber-50 transition">
            <input type="checkbox" value="${topId}" ${isChecked ? 'checked' : ''} class="checkbox-topping-menu w-4 h-4 text-amber-500 rounded border-gray-300 shrink-0">
            <span class="text-xs font-bold text-slate-700 leading-snug">${topName} <span class="text-[10px] text-emerald-600 ml-1 font-black">(+Rp ${hrg.toLocaleString('id-ID')})</span>${top._fromMenu ? ' <span class="text-[9px] text-amber-700 bg-amber-100 px-1.5 py-0.5 rounded font-bold ml-1">Tersimpan</span>' : ''}</span>
        </label>
        `;
    }).join('');
};

// ==========================================
// JEMBATAN 1: PENARIK KATEGORI (ANTI-NYANGKUT & SINKRON)
// ==========================================
window.renderSelectKategori = () => {
    const catSelect = document.getElementById('fm-cat');
    if (!catSelect) return;

    const semuaMenu = Object.values(globalMenus || {});
    const menuCats = semuaMenu.map(m => m.category || m.kategori).filter(Boolean);
    const masterCats = (window.masterKategori || []).map(k => typeof k === 'object' ? (k.name || k.nama || k.id) : k).filter(Boolean);
    
    const mapUnik = new Map();
    [...masterCats, ...menuCats].forEach(cat => {
        const trimmed = String(cat).trim();
        if (trimmed && !mapUnik.has(trimmed.toLowerCase())) {
            mapUnik.set(trimmed.toLowerCase(), trimmed);
        }
    });

    const daftarKategori = Array.from(mapUnik.values());
    const curValue = catSelect.value;

    if (daftarKategori.length > 0) {
        catSelect.innerHTML = daftarKategori.map(kat => 
            `<option value="${kat}">${kat}</option>`
        ).join('');
        if (curValue && daftarKategori.some(k => k.toLowerCase() === curValue.toLowerCase())) {
            catSelect.value = curValue;
        }
    } else {
        catSelect.innerHTML = '<option value="" disabled selected>-- Belum ada Kategori --</option>';
    }
};

// ==========================================
// JEMBATAN 5: PEWARIS VARIAN (AUTO-RENDER & TAHAN EDIT)
// ==========================================
window.renderCheckboxVarian = (explicitSelected = null) => {
    if (!window.masterVarian || window.masterVarian.length === 0) {
        window.masterVarian = [
            { id: 'var_ukuran', nama: 'PILIH UKURAN', opsi: [{namaOpsi: 'Regular', harga: 0}, {namaOpsi: 'Large', harga: 3000}] },
            { id: 'var_gula', nama: 'KADAR GULA', opsi: [{namaOpsi: 'Normal (100%)', harga: 0}, {namaOpsi: 'Less (50%)', harga: 0}] },
            { id: 'var_es', nama: 'KADAR ES', opsi: [{namaOpsi: 'Normal Ice', harga: 0}, {namaOpsi: 'Less Ice', harga: 0}] }
        ];
        localStorage.setItem('master_varian', JSON.stringify(window.masterVarian));
        if(typeof window.renderMasterVarian === 'function') window.renderMasterVarian();
    }

    const wadah = document.getElementById('wadah-checkbox-varian');
    if (!wadah) return;

    const currentChecked = Array.from(wadah.querySelectorAll('.checkbox-varian-menu:checked')).map(cb => String(cb.value));
    let selectedTokens = [];
    if (Array.isArray(explicitSelected)) {
        selectedTokens = explicitSelected;
    } else if (window.editMenuKeyTarget && globalMenus[window.editMenuKeyTarget]) {
        const em = globalMenus[window.editMenuKeyTarget];
        selectedTokens = window.normalizeMenuSelectionTokens(em.varianIds, em.varian);
    } else {
        selectedTokens = currentChecked.map(id => ({ id }));
    }

    const baseList = Array.isArray(window.masterVarian)
        ? window.masterVarian.filter(Boolean)
        : (window.masterVarian && typeof window.masterVarian === 'object' ? Object.values(window.masterVarian).filter(Boolean) : []);

    const listToRender = [...baseList];
    selectedTokens.forEach(tok => {
        const tokId = String(tok.id || '').trim();
        const tokName = String(tok.nama || tok.name || tokId).trim();
        const exists = listToRender.some(v =>
            String(v.id || '').trim() === tokId ||
            (tokName && String(v.nama || v.name || '').trim().toLowerCase() === tokName.toLowerCase())
        );
        if (!exists && (tokId || tokName)) {
            listToRender.push({
                id: tokId || tokName,
                nama: tok.obj?.nama || tok.obj?.name || tokName || tokId,
                opsi: Array.isArray(tok.obj?.opsi) ? tok.obj.opsi : [],
                _fromMenu: true
            });
        }
    });

    wadah.innerHTML = listToRender.map(v => {
        const varId = String(v.id || v.nama || v.name || '').trim();
        const varName = String(v.nama || v.name || varId).trim();
        const opsiArr = Array.isArray(v.opsi) ? v.opsi : (v.opsi && typeof v.opsi === 'object' ? Object.values(v.opsi) : []);
        const opsiTeks = opsiArr.map(o => {
            const hrg = Number(o.harga || o.price || 0);
            return hrg > 0 ? `${o.namaOpsi || o.name} (+Rp ${hrg.toLocaleString('id-ID')})` : (o.namaOpsi || o.name || '');
        }).filter(Boolean).join(', ');
        const isChecked = selectedTokens.some(tok => {
            const vid = String(tok.id || '').trim();
            const vname = String(tok.nama || tok.name || '').trim().toLowerCase();
            return vid === varId || vid.toLowerCase() === varName.toLowerCase() || (vname && vname === varName.toLowerCase());
        });
        return `
        <label class="flex items-center gap-3 p-3 min-h-[44px] bg-white border ${isChecked ? 'border-blue-400 bg-blue-50/40' : 'border-slate-200'} rounded-xl cursor-pointer hover:border-blue-400 transition shadow-sm">
            <input type="checkbox" value="${varId}" ${isChecked ? 'checked' : ''} class="checkbox-varian-menu w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 shrink-0">
            <div class="flex flex-col min-w-0">
                <span class="text-xs font-black text-slate-700 uppercase leading-snug">${varName}${v._fromMenu ? ' <span class="text-[9px] text-blue-700 bg-blue-100 px-1.5 py-0.5 rounded font-bold normal-case ml-1">Tersimpan</span>' : ''}</span>
                <span class="text-[10px] text-slate-500 leading-snug">${opsiTeks || 'Opsi standar'}</span>
            </div>
        </label>
        `;
    }).join('');
};
// ==========================================
// MESIN PEMBUAT TOMBOL KATEGORI PELANGGAN
// ==========================================
window.renderClientKategoriButtons = () => {
    const container = document.getElementById('container-filter-kategori');
    if (!container) return;

    let activeKat = typeof activeCategoryFilter !== 'undefined' ? activeCategoryFilter : 'all';

    let html = `
        <button onclick="filterKategori('all', this)" class="cat-btn ${activeKat === 'all' ? 'active bg-amber-500 text-white' : 'bg-white text-gray-600 border border-gray-200'} px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap shadow-sm transition">
            Semua Menu
        </button>
    `;

    // Gabungkan kategori dari masterKategori dan dari menu riil
    const semuaMenu = Object.values(globalMenus || {});
    const menuCats = semuaMenu.map(menu => menu.category || menu.kategori).filter(Boolean);
    const masterCats = (window.masterKategori || []).map(k => typeof k === 'object' ? (k.name || k.nama || k.id) : k).filter(Boolean);

    const mapUnik = new Map();
    [...masterCats, ...menuCats].forEach(k => {
        const trimmed = String(k).trim();
        if (trimmed && !mapUnik.has(trimmed.toLowerCase())) {
            mapUnik.set(trimmed.toLowerCase(), trimmed);
        }
    });

    const listKat = Array.from(mapUnik.values());

    listKat.forEach(katName => {
        const isActive = activeKat === katName;
        html += `
            <button onclick="filterKategori('${katName}', this)" class="cat-btn ${isActive ? 'active bg-amber-500 text-white' : 'bg-white text-gray-600 border border-gray-200'} px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap shadow-sm hover:bg-slate-50 transition">
                ${katName}
            </button>
        `;
    });

    container.innerHTML = html;
};

// ==========================================
// PENDETEKSI SESI OTOMATIS (ANTI REFRESH ULTIMATE)
// ==========================================
const restoreSessionRoleUI = () => {
    setTimeout(() => {
        const sesiAktif = localStorage.getItem('mainstay_session_role');
        const isKasirOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';
        if (sesiAktif === 'owner' || sesiAktif === 'kasir' || isKasirOpen) {
            const role = (sesiAktif === 'owner') ? 'owner' : 'kasir';
            if (typeof window.switchRoleView === 'function') {
                window.switchRoleView(role);
            }
            const namaSimpanan = localStorage.getItem('mainstay_staff_name') || "Kasir Utama";
            const elemenNamaKasir = document.getElementById('kasir-nama-petugas');
            if (elemenNamaKasir) {
                elemenNamaKasir.innerText = namaSimpanan;
            }
            if (isKasirOpen && typeof window.bukaPanelKasirManual === 'function') {
                window.bukaPanelKasirManual();
            }
        }
    }, 200);
};

if (document.readyState === 'loading') {
    window.addEventListener('DOMContentLoaded', restoreSessionRoleUI);
} else {
    restoreSessionRoleUI();
}

// ==========================================
// FUNGSI PERSIAPAN MODE EDIT (HIGHLIGHT, ANTI HILANG & PREVIEW GAMBAR)
// ==========================================
window.siapkanEditMenu = (key) => {
    const menu = globalMenus[key];
    if(!menu) return;

    window.editMenuKeyTarget = key;

    // 1. EFEK SOROTAN VISUAL
    document.querySelectorAll('.row-katalog-menu').forEach(el => {
        el.classList.remove('border-blue-500', 'ring-2', 'ring-blue-200', 'bg-blue-50');
        el.classList.add('border-slate-200', 'bg-white');
    });
    const activeRow = document.getElementById(`row-menu-${key}`);
    if (activeRow) {
        activeRow.classList.remove('border-slate-200', 'bg-white');
        activeRow.classList.add('border-blue-500', 'ring-2', 'ring-blue-200', 'bg-blue-50');
    }

    const panel = document.getElementById('owner-inner-panels-container');
    if(!panel) return;

    // Pastikan pilihan kategori, topping, dan varian di form ter-render ulang sebelum pengisian nilai
    if (typeof window.renderSelectKategori === 'function') {
        window.renderSelectKategori();
    }

    const selectedToppings = typeof window.normalizeMenuSelectionTokens === 'function'
        ? window.normalizeMenuSelectionTokens(menu.toppingIds, menu.toppings)
        : [];
    const selectedVarians = typeof window.normalizeMenuSelectionTokens === 'function'
        ? window.normalizeMenuSelectionTokens(menu.varianIds, menu.varian)
        : [];

    if (typeof window.renderCheckboxTopping === 'function') {
        window.renderCheckboxTopping(selectedToppings);
    }
    if (typeof window.renderCheckboxVarian === 'function') {
        window.renderCheckboxVarian(selectedVarians);
    }

    // 2. Isi seluruh field formulir secara eksplisit & akurat
    const fcEdit = typeof window.getFinanceConfig === 'function' ? window.getFinanceConfig() : {};
    const fmName = document.getElementById('fm-name');
    const fmPrice = document.getElementById('fm-price');
    const fmHpp = document.getElementById('fm-hpp');
    const fmCat = document.getElementById('fm-cat');
    const fmOjol = document.getElementById('fm-ojol-pct');
    const fmQris = document.getElementById('fm-qris-pct');
    const fmWaste = document.getElementById('fm-waste-pct');
    const fmDesc = document.getElementById('fm-desc');
    const fmCara = document.getElementById('fm-cara-pembuatan');
    const fmUrl = document.getElementById('fm-image-url');
    const fmFile = document.getElementById('fm-image-file');

    if (fmName) fmName.value = menu.name || menu.nama || '';
    if (fmPrice) fmPrice.value = menu.price !== undefined && menu.price !== null ? menu.price : '';
    if (fmHpp) fmHpp.value = (menu.hpp !== undefined && menu.hpp !== null && Number(menu.hpp) > 0) ? menu.hpp : '';
    if (fmOjol) fmOjol.value = menu.ojolFeePct !== undefined ? menu.ojolFeePct : Number(fcEdit.defaultOjolCommPct ?? 20);
    if (fmQris) fmQris.value = menu.qrisFeePct !== undefined ? menu.qrisFeePct : Number(fcEdit.defaultQrisAdminPct ?? 0.7);
    if (fmWaste) fmWaste.value = menu.wastePct !== undefined ? menu.wastePct : Number(fcEdit.defaultWastePct ?? 3);
    if (fmDesc) fmDesc.value = menu.description || menu.deskripsi || '';
    if (fmCara) fmCara.value = menu.caraPembuatan || menu.cara_pembuatan || menu.sop || '';
    if (fmUrl) fmUrl.value = menu.imageUrl || '';
    if (fmFile) fmFile.value = '';

    if (fmCat) {
        const targetCat = String(menu.category || menu.kategori || '').trim();
        if (targetCat) {
            let found = Array.from(fmCat.options).find(opt =>
                opt.value.toLowerCase() === targetCat.toLowerCase() ||
                opt.text.toLowerCase() === targetCat.toLowerCase()
            );
            if (!found) {
                const opt = document.createElement('option');
                opt.value = targetCat;
                opt.textContent = targetCat;
                fmCat.appendChild(opt);
                fmCat.value = targetCat;
            } else {
                fmCat.value = found.value;
            }
        }
    }

    if (typeof window.updateMenuHppPreview === 'function') window.updateMenuHppPreview();

    // -- PEMBERSIH FORMULIR MASTER AGAR TIDAK NYASAR --
    if (document.getElementById('input-kategori-baru')) document.getElementById('input-kategori-baru').value = '';
    if (document.getElementById('input-topping-nama')) document.getElementById('input-topping-nama').value = '';
    if (document.getElementById('input-topping-harga')) document.getElementById('input-topping-harga').value = '';
    if (document.getElementById('input-varian-nama')) document.getElementById('input-varian-nama').value = '';
    if (document.getElementById('input-varian-opsi')) document.getElementById('input-varian-opsi').value = '';

    // 3. PENGAMANAN MUTLAK BEST SELLER
    let isBS = false;
    for (const prop in menu) {
        if (prop.toLowerCase().includes('best')) {
            if (menu[prop] === true || menu[prop] === 'true') isBS = true;
        }
    }
    const bsCb = document.getElementById('fm-bestseller');
    if (bsCb) bsCb.checked = isBS;

    // 4B. Sinkronisasi Data Promo & Diskon ke Formulir
    const hasPromo = menu.isPromo === true || menu.isPromo === 'true';
    const promoCb = document.getElementById('fm-promo');
    if (promoCb) promoCb.checked = hasPromo;

    const promoTypeEl = document.getElementById('fm-promo-type');
    const promoValEl = document.getElementById('fm-promo-val');
    const promoLabelEl = document.getElementById('fm-promo-label');

    if (promoTypeEl) {
        promoTypeEl.value = menu.discountType || (menu.discountPercent ? 'percent' : 'nominal');
    }
    if (promoValEl) {
        if (menu.discountType === 'percent' || (menu.discountPercent && !menu.discountNominal)) {
            promoValEl.value = menu.discountPercent || '';
        } else {
            promoValEl.value = menu.discountNominal || '';
        }
    }
    if (promoLabelEl) {
        promoLabelEl.value = menu.promoLabel || '';
    }

    if (typeof window.toggleFormPromo === 'function') {
        window.toggleFormPromo(hasPromo);
    }

    // 4C. Sinkronisasi Data Paket Gabungan Produk (Bundle / Combo)
    const hasPackage = menu.isPackage === true || menu.isPackage === 'true' || menu.isPaket === true;
    const pkgCb = document.getElementById('fm-is-package');
    if (pkgCb) pkgCb.checked = hasPackage;
    if (typeof window.toggleFormPaketGabungan === 'function') {
        window.toggleFormPaketGabungan(hasPackage, menu);
    }

    // 4D. Sinkronisasi Resep Bahan Baku Menu (support Array maupun Object map RTDB)
    const resepNorm = Array.isArray(menu.resep)
        ? menu.resep.filter(Boolean)
        : (menu.resep && typeof menu.resep === 'object' ? Object.values(menu.resep).filter(Boolean) : []);
    if (typeof window.renderResepMenuEditor === 'function') {
        window.renderResepMenuEditor(resepNorm);
    }

    // 5. Ubah tombol "SIMPAN" jadi "UPDATE" & tambahkan tombol cepat QR Produk
    const btns = panel.querySelectorAll('button');
    btns.forEach(btn => {
        if (btn.innerText.toUpperCase().includes('SIMPAN')) {
            btn.innerHTML = '<i class="fa-solid fa-check-circle mr-2"></i> UPDATE DATA MENU';
            btn.classList.add('bg-blue-600', 'hover:bg-blue-700');
            btn.classList.remove('bg-amber-500', 'hover:bg-amber-600');
            let qrQuickBtn = document.getElementById('btn-qr-edit-menu');
            if (!qrQuickBtn && btn.parentElement) {
                qrQuickBtn = document.createElement('button');
                qrQuickBtn.type = 'button';
                qrQuickBtn.id = 'btn-qr-edit-menu';
                qrQuickBtn.className = 'w-full mt-2 py-2.5 px-4 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200 rounded-xl font-black text-xs flex items-center justify-center gap-2 transition active:scale-95 cursor-pointer';
                btn.insertAdjacentElement('afterend', qrQuickBtn);
            }
            if (qrQuickBtn) {
                qrQuickBtn.innerHTML = '<i class="fa-solid fa-qrcode"></i> TAMPILKAN / CETAK QR PRODUK INI';
                qrQuickBtn.onclick = () => window.bukaModalQrProduk(key);
                qrQuickBtn.classList.remove('hidden');
            }
        }
    });

    // 6. TAMPILKAN PREVIEW GAMBAR
    if (typeof window.updatePreviewVisual === 'function') {
        window.updatePreviewVisual(menu.imageUrl || '');
    }
    
    // 7. Gulir layar ke atas
    const formArea = panel.querySelector('h2');
    if(formArea) formArea.scrollIntoView({ behavior: 'smooth' });
};

// ==========================================
// MESIN PREVIEW GAMBAR (ANTI GAGAL / OTOMATIS BACA DOM BARU)
// ==========================================
window.updatePreviewVisual = (src) => {
    let wadah = document.getElementById('wadah-preview-gambar');
    const fileInput = document.getElementById('fm-image-file');
    
    // Buat wadah secara instan jika belum ada di dalam form
    if (!wadah && fileInput) {
        wadah = document.createElement('div');
        wadah.id = 'wadah-preview-gambar';
        wadah.className = 'mt-3 p-3 bg-blue-50 border border-blue-200 rounded-xl flex items-center gap-4 shadow-sm';
        wadah.innerHTML = `
            <div class="w-16 h-16 bg-white border-2 border-blue-300 rounded-lg overflow-hidden shrink-0 shadow-sm">
                <img id="img-preview-target" src="" class="w-full h-full object-cover" onerror="this.src='logo-192.png'">
            </div>
            <div class="flex-1">
                <h4 class="text-xs font-black text-blue-800"><i class="fa-solid fa-image mr-1"></i> Preview Gambar</h4>
                <p class="text-[10px] font-medium text-blue-600 mt-0.5">Gambar ini yang akan tampil di katalog.</p>
            </div>
        `;
        // Sisipkan tepat di bawah kotak "Pilih File"
        fileInput.parentElement.insertAdjacentElement('afterend', wadah);
    }

    // Tampilkan/Sembunyikan gambar sesuai data
    if (wadah) {
        const img = document.getElementById('img-preview-target');
        if (src && src.trim() !== '') {
            img.src = src;
            wadah.style.display = 'flex';
        } else {
            wadah.style.display = 'none';
            img.src = '';
        }
    }
};

// Deteksi saat Owner mengetik Link Gambar URL baru
document.addEventListener('input', (e) => {
    if (e.target && e.target.id === 'fm-image-url') {
        window.updatePreviewVisual(e.target.value);
    }
});

// Deteksi saat Owner memilih File Gambar dari Galeri HP
document.addEventListener('change', (e) => {
    if (e.target && e.target.id === 'fm-image-file') {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => window.updatePreviewVisual(event.target.result);
            reader.readAsDataURL(file);
            
            // Kosongkan kolom URL agar sistem tidak bingung/bentrok
            const urlInput = document.getElementById('fm-image-url');
            if(urlInput) urlInput.value = '';
        } else {
            window.updatePreviewVisual('');
        }
    }
});

// ==========================================
// TAHAP 1: MESIN ULASAN GOOGLE MAPS (AUTO-SCROLL)
// ==========================================
window.renderUlasanPelanggan = () => {
    // 1. Cari elemen grid menu untuk tempat menempelkan ulasan di bawahnya
    const menuGrid = document.getElementById('menu-grid');
    if (!menuGrid) return;

    // 2. Buat wadah ulasan jika belum ada
    let reviewWrapper = document.getElementById('review-slider-wrapper');
    if (!reviewWrapper) {
        reviewWrapper = document.createElement('div');
        reviewWrapper.id = 'review-slider-wrapper';
        reviewWrapper.className = 'mt-10 mb-2 px-4 fade-in';
        // Sisipkan tepat di bawah menu-grid (sebelum peta lokasi)
        menuGrid.insertAdjacentElement('afterend', reviewWrapper);
    }

    // 3. Data Dummy (Nanti di Tahap 2 data ini akan diambil dari Firebase)
    let reviews = window.globalReviews || [
        { name: "Naufal Luthfi Fadhlurrohman", text: "minuman kekinian, manis pas, rasa pas, masya Allah", stars: 5, time: "3 minggu yang lalu" },
        { name: "Fauzi Hanif", text: "Minumannya enak bgt, ga sebanding sama harganya yg murah", stars: 5, time: "1 minggu yang lalu" },
        { name: "Nanik Ulifah", text: "Tempatnya nyaman gaes.. you must try it...Minuman enak, nyummy dengan harga yg murce abizz", stars: 5, time: "2 hari yang lalu" },
    ];

    if (reviews.length === 0) {
        reviewWrapper.innerHTML = '';
        return;
    }

    // 4. Rakit Kotak Desain Ala Google Maps
    let htmlSlides = reviews.map(r => {
        let starsHtml = '';
        for(let i=0; i<r.stars; i++) starsHtml += '<i class="fa-solid fa-star text-amber-400 text-[10px]"></i>';
        for(let i=r.stars; i<5; i++) starsHtml += '<i class="fa-solid fa-star text-slate-200 text-[10px]"></i>';
        
        return `
        <div class="w-full shrink-0 px-1">
            <div class="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col gap-2 relative overflow-hidden h-full">
                <div class="absolute top-0 right-0 p-3 opacity-[0.03]"><i class="fa-brands fa-google text-6xl"></i></div>
                <div class="flex items-center justify-between relative z-10">
                    <div class="flex items-center gap-2.5">
                        <div class="w-9 h-9 rounded-full bg-blue-100 text-blue-600 border border-blue-200 flex items-center justify-center font-black text-sm shadow-inner shrink-0">
                            ${r.name.charAt(0).toUpperCase()}
                        </div>
                        <div class="flex flex-col">
                            <span class="text-xs font-black text-slate-800 leading-tight">${r.name}</span>
                            <span class="text-[9px] font-bold text-slate-400 mt-0.5">${r.time}</span>
                        </div>
                    </div>
                    <i class="fa-brands fa-google text-blue-500 shrink-0"></i>
                </div>
                <div class="flex items-center gap-0.5 mt-1 relative z-10">
                    ${starsHtml}
                </div>
                <p class="text-[10.5px] font-medium text-slate-600 leading-relaxed line-clamp-3 mt-1 relative z-10">
                    "${r.text}"
                </p>
            </div>
        </div>
        `;
    }).join('');

    // 5. Suntikkan ke dalam layar
    reviewWrapper.innerHTML = `
        <div class="flex items-center justify-between mb-3 px-1">
            <h3 class="text-xs font-black text-slate-800 tracking-wider uppercase flex items-center">
                <i class="fa-solid fa-star text-amber-500 mr-2"></i> Kata Mereka
            </h3>
            <div class="flex gap-1">
                <div class="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div>
                <div class="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" style="animation-delay: 0.2s"></div>
                <div class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" style="animation-delay: 0.4s"></div>
            </div>
        </div>
        <div class="relative overflow-hidden w-full" id="review-slider-viewport">
            <div id="review-track" class="flex transition-transform duration-700 ease-in-out">
                ${htmlSlides}
            </div>
        </div>
    `;

    // 6. Jalankan Mesin Auto-Scroll (Setiap 3 Detik)
    const track = document.getElementById('review-track');
    let currentIndex = 0;
    const totalSlides = reviews.length;
    
    if(window.reviewInterval) clearInterval(window.reviewInterval);
    
    window.reviewInterval = setInterval(() => {
        if(totalSlides <= 1 || !track) return;
        currentIndex = (currentIndex + 1) % totalSlides;
        track.style.transform = `translateX(-${currentIndex * 100}%)`;
    }, 3000); 
};

