// Fungsi Mengambil Seluruh Arsip Absensi (All Time)
window.fetchLiveLogAbsensi = (isManualRefresh = false) => {
    const btnSync = document.getElementById('btn-sync-absen');
    if (btnSync) {
        btnSync.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> <span class="hidden sm:inline">Memuat...</span>';
    }

    const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];

    get(ref(db, 'attendance'))
        .then(snap => (snap && snap.exists() ? snap.val() : null))
        .then(data => {
            const parsedLogs = [];
            const processedKeys = new Set();

            const parseSingle = (raw, fallbackDate = '', fallbackTs = null) => {
                if (!raw || typeof raw !== 'object') return;
                
                // Normalisasi Tanggal
                let tgl = raw.tanggal || '';
                if (!tgl && fallbackDate && /^\d{4}-\d{2}-\d{2}$/.test(fallbackDate)) {
                    tgl = fallbackDate;
                }

                // Normalisasi Timestamp
                let ts = Number(raw.timestamp || fallbackTs);
                if (!ts || isNaN(ts)) {
                    if (tgl) {
                        ts = new Date(tgl).getTime();
                    } else {
                        ts = Date.now();
                    }
                }

                const d = new Date(ts);
                if (!tgl) {
                    tgl = d.toLocaleDateString('id-ID', {year: 'numeric', month: '2-digit', day: '2-digit'}).split('/').reverse().join('-');
                }

                // Normalisasi Hari
                let hari = raw.hari;
                if (!hari) {
                    hari = dayNames[d.getDay()] || 'Senin';
                }

                // Normalisasi Waktu (Jam:Menit:Detik)
                let waktu = raw.waktu || raw.jam || d.toLocaleTimeString('id-ID', {hour: '2-digit', minute: '2-digit', second: '2-digit'});

                // Normalisasi Tipe
                const rawTipe = (raw.tipe || 'Masuk').toString();
                const tipe = rawTipe.toLowerCase().includes('pulang') ? 'Pulang' : 'Masuk';

                // Normalisasi Status
                let status = raw.status;
                if (!status) {
                    status = tipe === 'Masuk' ? 'TEPAT WAKTU' : 'SELESAI SHIFT';
                }

                const nama = raw.nama || raw.name || 'Karyawan';
                const uniqueKey = `${tgl}_${nama}_${waktu}_${tipe}`;

                if (!processedKeys.has(uniqueKey)) {
                    processedKeys.add(uniqueKey);

                    // Formatted Date e.g. Jumat, 18 Sep 2026
                    const dayNum = String(d.getDate()).padStart(2, '0');
                    const monthStr = monthNames[d.getMonth()] || '';
                    const yearStr = d.getFullYear();
                    const formattedDate = `${hari}, ${dayNum} ${monthStr} ${yearStr}`;

                    parsedLogs.push({
                        id: uniqueKey,
                        nama: nama,
                        tipe: tipe,
                        status: status,
                        waktu: waktu,
                        jam: waktu,
                        hari: hari,
                        tanggal: tgl,
                        formattedDate: formattedDate,
                        foto: raw.foto || '',
                        role: raw.role || raw.tipeKaryawan || 'Staff',
                        timestamp: ts,
                        isPulangAwal: raw.isPulangAwal || false,
                        alasanPulangAwal: raw.alasanPulangAwal || '',
                        keteranganPulangAwal: raw.keteranganPulangAwal || '',
                        buktiIzinFoto: raw.buktiIzinFoto || '',
                        jadwalShiftOut: raw.jadwalShiftOut || ''
                    });
                }
            };

            // Traverse database structure
            if (data && typeof data === 'object') {
                Object.entries(data).forEach(([topKey, topVal]) => {
                    if (!topVal || typeof topVal !== 'object') return;

                    // Jika langsung data absensi record
                    if (topVal.nama && (topVal.tipe || topVal.waktu)) {
                        parseSingle(topVal, topKey);
                    } else {
                        // topKey adalah tanggal YYYY-MM-DD
                        Object.entries(topVal).forEach(([subKey, subVal]) => {
                            if (subVal && typeof subVal === 'object') {
                                parseSingle(subVal, topKey, subKey);
                            }
                        });
                    }
                });
            }

            // Tambahkan juga dari local cache jika ada yang belum tersinkron
            try {
                const localCache = JSON.parse(localStorage.getItem('mainstay_attendance_local_logs') || '[]');
                if (Array.isArray(localCache)) {
                    localCache.forEach(l => parseSingle(l));
                }
            } catch(e) {}

            // Urutkan dari yang paling baru ke yang paling lama (Timestamp Descending)
            parsedLogs.sort((a, b) => b.timestamp - a.timestamp);
            window._attendanceRawLogs = parsedLogs;

            // Populate Dropdown Nama Karyawan
            window.populateFilterAbsenNama();

            // Render hasil filter
            window.renderFilteredLogAbsensi();

            if (btnSync) {
                btnSync.innerHTML = '<i class="fa-solid fa-arrows-rotate"></i> <span class="hidden sm:inline">Sinkron Live</span>';
            }
            if (isManualRefresh) {
                alert(`Sinkronisasi sukses! ${parsedLogs.length} data absensi berhasil dimuat.`);
            }
        })
        .catch(err => {
            console.error("Gagal menarik log absensi:", err);
            // Fallback ke cache lokal
            try {
                const localCache = JSON.parse(localStorage.getItem('mainstay_attendance_local_logs') || '[]');
                if (Array.isArray(localCache) && localCache.length > 0) {
                    window._attendanceRawLogs = localCache;
                    window.populateFilterAbsenNama();
                    window.renderFilteredLogAbsensi();
                } else {
                    const listEl = document.getElementById('list-log-absensi-container');
                    if (listEl) {
                        listEl.innerHTML = `
                            <div class="bg-white p-8 rounded-2xl border border-red-200 text-center">
                                <i class="fa-solid fa-triangle-exclamation text-3xl text-red-500 mb-2"></i>
                                <h4 class="text-sm font-black text-slate-800">Gagal Memuat Log Absensi</h4>
                                <p class="text-xs text-slate-500 mt-1 mb-4">Pastikan koneksi internet stabil lalu coba lagi.</p>
                                <button onclick="window.fetchLiveLogAbsensi(true)" class="bg-blue-600 text-white text-xs font-bold px-4 py-2 rounded-xl">Coba Lagi</button>
                            </div>
                        `;
                    }
                }
            } catch(e) {}

            if (btnSync) {
                btnSync.innerHTML = '<i class="fa-solid fa-arrows-rotate"></i> <span class="hidden sm:inline">Sinkron Live</span>';
            }
        });
};

// Mengisi Pilihan Nama Karyawan
window.populateFilterAbsenNama = () => {
    const selectEl = document.getElementById('filter-absen-nama');
    if (!selectEl) return;

    const names = new Set();
    (window._attendanceRawLogs || []).forEach(l => {
        if (l.nama) names.add(l.nama);
    });

    if (typeof globalStaff === 'object' && globalStaff !== null) {
        Object.values(globalStaff).forEach(s => {
            if (s && s.name) names.add(s.name);
        });
    }

    let optionsHtml = '<option value="">Semua Karyawan</option>';
    Array.from(names).sort().forEach(nama => {
        const selected = window._attendanceFilter.nama === nama ? 'selected' : '';
        optionsHtml += `<option value="${nama}" ${selected}>${nama}</option>`;
    });

    selectEl.innerHTML = optionsHtml;
};

// Mengubah Filter Tertentu
window.onFilterAbsenChange = (key, value) => {
    window._attendanceFilter[key] = value;
    if (key === 'tanggal') {
        window._attendanceFilter.quickDate = value ? 'custom' : 'semua';
        window.updateQuickFilterPills();
    }
    window.renderFilteredLogAbsensi();
};

// Mengubah Jenis Absen (Semua, Masuk, Pulang)
window.setFilterJenisAbsen = (tipe) => {
    window._attendanceFilter.tipe = tipe;
    
    // Update tombol aktif sambil menjaga layout horizontal & ikon
    ['semua', 'masuk', 'pulang'].forEach(t => {
        const btn = document.getElementById(`tab-jenis-${t}`);
        if (!btn) return;
        if (t === tipe.toLowerCase()) {
            btn.className = 'px-3 py-1.5 rounded-lg text-xs font-black transition bg-white text-slate-900 shadow-sm inline-flex items-center gap-1.5 shrink-0 whitespace-nowrap';
        } else {
            btn.className = 'px-3 py-1.5 rounded-lg text-xs font-black transition text-slate-600 hover:text-slate-900 inline-flex items-center gap-1.5 shrink-0 whitespace-nowrap';
        }
    });

    window.renderFilteredLogAbsensi();
};

// Quick Date Filter
window.setQuickFilterTanggal = (preset) => {
    window._attendanceFilter.quickDate = preset;
    const now = new Date();
    const toDateStr = (d) => d.toLocaleDateString('id-ID', {year: 'numeric', month: '2-digit', day: '2-digit'}).split('/').reverse().join('-');

    const inputTanggal = document.getElementById('filter-absen-tanggal');

    if (preset === 'hari_ini') {
        const todayStr = toDateStr(now);
        window._attendanceFilter.tanggal = todayStr;
        if (inputTanggal) inputTanggal.value = todayStr;
    } else if (preset === 'kemarin') {
        const yesterday = new Date(now.getTime() - 86400000);
        const yestStr = toDateStr(yesterday);
        window._attendanceFilter.tanggal = yestStr;
        if (inputTanggal) inputTanggal.value = yestStr;
    } else if (preset === 'semua') {
        window._attendanceFilter.tanggal = '';
        if (inputTanggal) inputTanggal.value = '';
    } else {
        // 7_hari atau 30_hari
        window._attendanceFilter.tanggal = '';
        if (inputTanggal) inputTanggal.value = '';
    }

    window.updateQuickFilterPills();
    window.renderFilteredLogAbsensi();
};

window.updateQuickFilterPills = () => {
    const q = window._attendanceFilter.quickDate;
    ['semua', 'hari_ini', 'kemarin', '7_hari', '30_hari'].forEach(p => {
        const el = document.getElementById(`btn-qf-${p}`);
        if (!el) return;
        if (p === q) {
            el.className = 'px-2.5 py-1 rounded-lg text-[10px] font-black transition bg-blue-600 text-white shadow-sm shrink-0 whitespace-nowrap';
        } else {
            el.className = 'px-2.5 py-1 rounded-lg text-[10px] font-black transition bg-slate-100 text-slate-600 hover:bg-slate-200 shrink-0 whitespace-nowrap';
        }
    });
};

// Reset Seluruh Filter
window.resetFilterAbsensi = () => {
    window._attendanceFilter = {
        tanggal: '',
        hari: '',
        nama: '',
        tipe: 'semua',
        search: '',
        quickDate: 'semua'
    };

    const inTanggal = document.getElementById('filter-absen-tanggal');
    const selHari = document.getElementById('filter-absen-hari');
    const selNama = document.getElementById('filter-absen-nama');
    const inSearch = document.getElementById('filter-absen-search');

    if (inTanggal) inTanggal.value = '';
    if (selHari) selHari.value = '';
    if (selNama) selNama.value = '';
    if (inSearch) inSearch.value = '';

    window.setFilterJenisAbsen('semua');
    window.updateQuickFilterPills();
    window.renderFilteredLogAbsensi();
};

// Merender Log Absensi Berdasarkan Filter Aktif
window.renderFilteredLogAbsensi = () => {
    const filter = window._attendanceFilter;
    const rawLogs = window._attendanceRawLogs || [];
    const now = Date.now();
    const sevenDaysAgo = now - 7 * 86400000;
    const thirtyDaysAgo = now - 30 * 86400000;

    const filtered = rawLogs.filter(log => {
        // 1. Filter Tanggal Spesifik
        if (filter.tanggal) {
            if (log.tanggal !== filter.tanggal) return false;
        } else if (filter.quickDate === '7_hari') {
            if (log.timestamp < sevenDaysAgo) return false;
        } else if (filter.quickDate === '30_hari') {
            if (log.timestamp < thirtyDaysAgo) return false;
        }

        // 2. Filter Hari (Senin, Selasa, dst)
        if (filter.hari) {
            if ((log.hari || '').toLowerCase() !== filter.hari.toLowerCase()) return false;
        }

        // 3. Filter Nama Karyawan
        if (filter.nama) {
            if (log.nama !== filter.nama) return false;
        }

        // 4. Filter Jenis Absen (Masuk vs Pulang)
        if (filter.tipe && filter.tipe !== 'semua') {
            if ((log.tipe || '').toLowerCase() !== filter.tipe.toLowerCase()) return false;
        }

        // 5. Filter Search Kata Kunci
        if (filter.search) {
            const q = filter.search.toLowerCase();
            const hay = `${log.nama} ${log.role} ${log.status} ${log.waktu} ${log.hari} ${log.tanggal}`.toLowerCase();
            if (!hay.includes(q)) return false;
        }

        return true;
    });

    window._attendanceFilteredLogs = filtered;

    // Hitung KPI
    const totalCount = filtered.length;
    let masukCount = 0;
    let pulangCount = 0;
    const uniqueStaff = new Set();

    filtered.forEach(l => {
        if (l.tipe === 'Masuk') masukCount++;
        if (l.tipe === 'Pulang') pulangCount++;
        if (l.nama) uniqueStaff.add(l.nama);
    });

    // Update Angka KPI
    const statTotal = document.getElementById('stat-absen-total');
    const statMasuk = document.getElementById('stat-absen-masuk');
    const statPulang = document.getElementById('stat-absen-pulang');
    const statStaff = document.getElementById('stat-absen-staff');
    const summaryText = document.getElementById('filter-absen-summary-text');

    if (statTotal) statTotal.innerText = Number(totalCount || 0).toLocaleString('id-ID');
    if (statMasuk) statMasuk.innerText = Number(masukCount || 0).toLocaleString('id-ID');
    if (statPulang) statPulang.innerText = Number(pulangCount || 0).toLocaleString('id-ID');
    if (statStaff) statStaff.innerText = Number(uniqueStaff.size || 0).toLocaleString('id-ID');
    if (summaryText) {
        summaryText.innerText = `Menampilkan ${totalCount} dari ${rawLogs.length} riwayat absensi`;
    }

    // Render Kartu Absensi
    const listContainer = document.getElementById('list-log-absensi-container');
    if (!listContainer) return;

    if (filtered.length === 0) {
        listContainer.innerHTML = `
            <div class="bg-white p-12 rounded-3xl border border-slate-200 text-center">
                <div class="w-16 h-16 shrink-0 bg-slate-100 text-slate-400 rounded-3xl flex items-center justify-center mx-auto mb-3.5 text-2xl">
                    <i class="fa-solid fa-clipboard-user"></i>
                </div>
                <h4 class="text-sm font-black text-slate-800">Tidak Ada Data Absensi</h4>
                <p class="text-xs text-slate-500 max-w-sm mx-auto mt-1 mb-4">Tidak ditemukan arsip absensi yang sesuai dengan kriteria filter yang sedang aktif.</p>
                <button onclick="window.resetFilterAbsensi()" class="bg-blue-600 hover:bg-blue-700 text-white text-xs font-black px-5 py-2.5 rounded-xl transition shadow">
                    <i class="fa-solid fa-rotate-left mr-1.5"></i> Reset Semua Filter
                </button>
            </div>
        `;
        return;
    }

    let cardsHtml = '';
    filtered.forEach(log => {
        const isMasuk = log.tipe === 'Masuk';
        const badgeTipe = isMasuk ? `
            <span class="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-emerald-100 text-emerald-800 border border-emerald-200">
                <i class="fa-solid fa-arrow-right-to-bracket text-emerald-600"></i> Masuk
            </span>
        ` : `
            <span class="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[10px] font-black bg-blue-100 text-blue-800 border border-blue-200">
                <i class="fa-solid fa-arrow-right-from-bracket text-blue-600"></i> Pulang
            </span>
        `;

        let badgeStatus = '';
        if (log.status === 'TERLAMBAT') {
            badgeStatus = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-rose-100 text-rose-700 border border-rose-200"><i class="fa-solid fa-triangle-exclamation"></i> Terlambat</span>`;
        } else if (log.status === 'TEPAT WAKTU') {
            badgeStatus = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-emerald-50 text-emerald-700 border border-emerald-200"><i class="fa-solid fa-circle-check"></i> Tepat Waktu</span>`;
        } else if (log.status === 'PULANG AWAL (IZIN)' || log.isPulangAwal) {
            badgeStatus = `
                <button type="button" onclick="window.bukaDetailIzinPulangLog('${log.id}')" class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[9px] font-black bg-amber-100 text-amber-900 border border-amber-300 hover:bg-amber-200 transition shadow-2xs cursor-pointer active:scale-95" title="Klik untuk lihat bukti screenshot izin & alasan">
                    <i class="fa-solid fa-clock-rotate-left text-amber-600"></i> Pulang Awal (Izin) <i class="fa-solid fa-circle-info text-[9px] text-amber-700 ml-0.5"></i>
                </button>
            `;
        } else {
            badgeStatus = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-bold bg-slate-100 text-slate-700">${log.status}</span>`;
        }

        const metodeRaw = log.metode || (log.foto ? 'Face Recognition' : 'PIN');
        const isFace = String(metodeRaw).toLowerCase().includes('face');
        const badgeMetode = isFace ? `
            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-cyan-100 text-cyan-800 border border-cyan-200">
                <i class="fa-solid fa-face-smile text-cyan-600"></i> Face Scan
            </span>
        ` : `
            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black bg-purple-100 text-purple-800 border border-purple-200">
                <i class="fa-solid fa-key text-purple-600"></i> PIN
            </span>
        `;

        const fotoThumbnail = log.foto ? `
            <div onclick="window.previewFotoAbsensi('${encodeURIComponent(log.foto)}', '${log.nama}', '${log.formattedDate} • ${log.waktu} WIB')" class="relative w-14 h-14 rounded-2xl overflow-hidden bg-slate-100 border border-slate-200 shadow-sm shrink-0 cursor-pointer group">
                <img src="${log.foto}" alt="${log.nama}" class="w-full h-full object-cover group-hover:scale-110 transition duration-300">
                <div class="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-xs transition">
                    <i class="fa-solid fa-magnifying-glass-plus"></i>
                </div>
            </div>
        ` : `
            <div class="w-14 h-14 rounded-2xl bg-gradient-to-tr from-slate-200 to-slate-100 flex items-center justify-center text-slate-400 text-xl shrink-0 border border-slate-200">
                <i class="fa-solid fa-user"></i>
            </div>
        `;

        cardsHtml += `
            <div class="bg-white p-3.5 sm:p-4 rounded-2xl border border-slate-200/90 shadow-sm hover:shadow-md transition flex items-center gap-3 sm:gap-4">
                ${fotoThumbnail}
                <div class="flex-1 min-w-0">
                    <div class="flex flex-wrap items-center gap-1.5 mb-1">
                        <h4 class="font-black text-sm text-slate-800 truncate">${log.nama}</h4>
                        <span class="text-[9px] font-bold px-2 py-0.5 bg-slate-100 text-slate-600 rounded-md uppercase">${log.role}</span>
                        ${badgeTipe}
                        ${badgeStatus}
                        ${badgeMetode}
                    </div>
                    <div class="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-slate-500 font-semibold mt-1">
                        <span class="inline-flex items-center gap-1 text-slate-700 font-bold">
                            <i class="fa-regular fa-calendar text-slate-400"></i> ${log.formattedDate}
                        </span>
                        <span class="inline-flex items-center gap-1 bg-slate-100 text-slate-800 px-2 py-0.5 rounded font-black text-[11px]">
                            <i class="fa-regular fa-clock text-blue-500"></i> ${log.waktu} WIB
                        </span>
                    </div>
                </div>
            </div>
        `;
    });

    listContainer.innerHTML = cardsHtml;
};

// Modal Preview Foto Selfie
window.previewFotoAbsensi = (encodedFoto, nama, infoWaktu) => {
    const modal = document.getElementById('modal-foto-absen-preview');
    const img = document.getElementById('modal-foto-img');
    const elNama = document.getElementById('modal-foto-nama');
    const elWaktu = document.getElementById('modal-foto-waktu');
    if (!modal || !img) return;

    img.src = decodeURIComponent(encodedFoto);
    if (elNama) elNama.innerText = `Selfie Absensi: ${nama}`;
    if (elWaktu) elWaktu.innerText = infoWaktu;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
};

// Ekspor Riwayat Absensi ke CSV Profesional (UTF-8 BOM + TOTAL Baris)
window.exportLogAbsenCSV = () => {
    const data = window._attendanceFilteredLogs || [];
    if (data.length === 0) {
        return alert("Peringatan: Tidak ada data absensi untuk diekspor!");
    }

    const esc = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
    const rows = [
        [esc('REKAPITULASI ABSENSI KARYAWAN - MAINSTAY DRINK POS')],
        [esc('Waktu Ekspor:'), esc(new Date().toLocaleString('id-ID') + ' WIB')],
        [],
        [esc('No'), esc('Nama Karyawan'), esc('Jabatan/Role'), esc('Jenis Absen'), esc('Hari'), esc('Tanggal'), esc('Jam (WIB)'), esc('Status')]
    ];

    data.forEach((item, idx) => {
        rows.push([
            idx + 1,
            esc(item.nama || '-'),
            esc(item.role || '-'),
            esc(item.tipe || '-'),
            esc(item.hari || '-'),
            esc(item.tanggal || '-'),
            esc(item.waktu || '-'),
            esc(item.status || '-')
        ]);
    });

    rows.push([
        esc('TOTAL'),
        esc(`${data.length} RECORD ABSENSI`),
        esc('-'), esc('-'), esc('-'), esc('-'), esc('-'), esc('TERDATA')
    ]);

    const csvText = '\uFEFF' + rows.map(r => r.join(',')).join('\r\n');
    const blob = new Blob([csvText], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Rekap_Absensi_Mainstay_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
};

