// 2. Render Menu dari Database ke Layar Kasir
// ==========================================
// 2. KATALOG POS: KATEGORI, FILTER & VARIAN
// ==========================================
let kategoriAktifPOS = 'Semua';
let menuDipilihSementara = null;

window.renderKategoriPOS = (daftarMenu) => {
    const kontainerKat = document.getElementById('pos-kategori-container');
    if (!kontainerKat) return;

    const setKategori = new Set(['Semua']);
    (window.masterKategori || []).forEach(k => {
        const name = typeof k === 'object' ? (k.name || k.nama || k.id) : k;
        if (name) setKategori.add(name);
    });
    if (daftarMenu && Array.isArray(daftarMenu)) {
        daftarMenu.forEach(m => {
            const kat = m.kategori || m.category || m.jenis;
            if (kat) setKategori.add(kat);
        });
    }

    kontainerKat.innerHTML = '';
    setKategori.forEach(kat => {
        const aktif = kategoriAktifPOS.toLowerCase() === kat.toLowerCase();
        kontainerKat.innerHTML += `
            <button onclick="pilihKategoriPOS('${kat}')" class="px-3 py-1.5 rounded-lg text-xs font-bold whitespace-nowrap transition-all active:scale-95 active:opacity-75 ${aktif ? 'bg-indigo-600 text-white shadow' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">
                ${kat}
            </button>
        `;
    });
};

window.pilihKategoriPOS = (kat) => {
    kategoriAktifPOS = kat;
    window.renderKatalogPOS();
};

window.renderKatalogPOS = () => {
    const wadah = document.getElementById('pos-katalog-menu');
    if (!wadah) return;
    wadah.innerHTML = '';
    
    if (typeof globalMenus === 'undefined' || !globalMenus) {
        wadah.innerHTML = `<p class="text-xs text-red-400 col-span-full text-center">Database menu tidak ditemukan!</p>`;
        return;
    }

    const daftarMenu = Array.isArray(globalMenus) 
        ? globalMenus 
        : Object.keys(globalMenus).map(key => ({ key, ...globalMenus[key] }));

    if (daftarMenu.length === 0) {
        wadah.innerHTML = `<p class="text-xs text-slate-400 col-span-full text-center">Belum ada menu di katalog.</p>`;
        return;
    }

    window.renderKategoriPOS(daftarMenu);

    const menuTampil = daftarMenu.filter(m => {
        if (kategoriAktifPOS === 'Semua') return true;
        const kat = m.kategori || m.category || m.jenis || 'Lainnya';
        return kat.toLowerCase() === kategoriAktifPOS.toLowerCase();
    });

    if (menuTampil.length === 0) {
        wadah.innerHTML = `<p class="text-xs text-slate-400 col-span-full text-center">Tidak ada menu dalam kategori ini.</p>`;
        return;
    }

    menuTampil.forEach((menu, index) => {
        const keyUnik = menu.key !== undefined ? menu.key : index;
        const namaMenu = menu.nama || menu.title || menu.name || "Menu Tanpa Nama";
        const hargaAsliMenu = Number(menu.harga || menu.price || menu.cost || 0);
        const hargaMenu = (typeof window.getMenuEffectivePrice === 'function')
            ? Number(window.getMenuEffectivePrice({ ...menu, price: hargaAsliMenu }))
            : hargaAsliMenu;
        const hasDiscPOS = hargaMenu > 0 && hargaMenu < hargaAsliMenu;
        
        // Pindai SEMUA kemungkinan nama field gambar dari database Firebase
        let gambarMenu = menu.gambar || menu.image || menu.img || menu.foto || menu.imgUrl || menu.url || menu.photo || menu.pic;
        
        // Jika masih belum ketemu, cari properti apa saja yang isinya mengandung link gambar
        if (!gambarMenu) {
            for (let k in menu) {
                if (typeof menu[k] === 'string' && (menu[k].startsWith('http') || menu[k].startsWith('data:image') || menu[k].includes('.png') || menu[k].includes('.jpg') || menu[k].includes('.jpeg'))) {
                    gambarMenu = menu[k];
                    break;
                }
            }
        }

        const isAvail = menu.isAvailable !== false;
        const elemenVisual = gambarMenu 
            ? `<div class="relative w-12 h-12 shrink-0"><img src="${gambarMenu}" onerror="this.onerror=null; this.src='logo-192.png';" alt="${namaMenu}" class="w-12 h-12 shrink-0 object-cover rounded-md bg-slate-100 border border-slate-200 ${!isAvail ? 'filter grayscale-[0.5]' : ''}">${!isAvail ? '<span class="absolute inset-0 bg-slate-900/60 rounded-md flex items-center justify-center text-[8px] font-black text-white">HABIS</span>' : ''}</div>`
            : `<div class="w-12 h-12 rounded-md bg-indigo-50 text-indigo-500 flex items-center justify-center shrink-0 border border-indigo-100"><i class="fa-solid fa-utensils text-sm"></i></div>`;

        wadah.innerHTML += `
            <div onclick="klikMenuPOS('${keyUnik}', this)" class="pos-menu-card min-h-[66px] ${!isAvail ? 'bg-slate-100/90 border-rose-200 opacity-75' : (hasDiscPOS ? 'bg-emerald-50/40 border-emerald-300' : 'bg-slate-50 border-slate-200')} border p-2 rounded-xl cursor-pointer hover:bg-indigo-50 hover:border-indigo-300 hover:shadow-md transition-all duration-200 ease-out flex items-center gap-2.5 shadow-sm active:scale-[0.94] active:shadow-sm select-none min-w-0">
                ${elemenVisual}
                <div class="flex flex-col justify-center min-w-0 flex-1">
                    <h4 class="text-[11px] font-bold text-slate-700 leading-tight truncate">${namaMenu}</h4>
                    <div class="flex items-center justify-between gap-1 mt-1 tabular-nums">
                        <div class="flex items-center gap-1 min-w-0">
                            <p class="text-[10px] ${hasDiscPOS ? 'text-emerald-700' : 'text-indigo-600'} font-black truncate">Rp ${hargaMenu.toLocaleString('id-ID')}</p>
                            ${hasDiscPOS ? `<span class="text-[8.5px] text-slate-400 line-through truncate">Rp ${hargaAsliMenu.toLocaleString('id-ID')}</span>` : ''}
                        </div>
                        ${!isAvail ? '<span class="text-[8px] bg-rose-100 text-rose-700 px-1.5 py-0.5 rounded font-black tracking-tight uppercase shrink-0">Habis</span>' : (hasDiscPOS ? '<span class="text-[8px] bg-emerald-100 text-emerald-800 px-1.5 py-0.5 rounded font-black tracking-tight uppercase shrink-0">Promo</span>' : '')}
                    </div>
                </div>
            </div>
        `;
    });
};

window.bukaModalRiwayatHargaMenu = (key) => {
    const m = globalMenus[key];
    if (!m) return;
    const modal = document.getElementById('modal-riwayat-harga-menu');
    const titleEl = document.getElementById('riwayat-harga-menu-title');
    const bodyEl = document.getElementById('riwayat-harga-menu-body');
    if (!modal || !bodyEl) return;

    if (titleEl) titleEl.innerText = `Riwayat Harga: ${m.name || m.nama || 'Menu'}`;
    const logs = Array.isArray(m.priceHistory) ? [...m.priceHistory].reverse() : [];

    if (logs.length === 0) {
        bodyEl.innerHTML = `
            <div class="text-center py-6 bg-white rounded-2xl border border-slate-200">
                <i class="fa-solid fa-clock-rotate-left text-2xl text-slate-300 mb-2"></i>
                <p class="text-xs font-black text-slate-700">Harga Saat Ini: Rp ${Number(m.price || 0).toLocaleString('id-ID')}</p>
                <p class="text-[10px] text-slate-400 mt-1">Belum ada log perubahan harga sebelumnya untuk menu ini.<br>Perubahan harga berikutnya akan otomatis tercatat.</p>
            </div>
        `;
    } else {
        bodyEl.innerHTML = logs.map((entry) => {
            const oldP = Number(entry.oldPrice || 0);
            const newP = Number(entry.newPrice || 0);
            const diff = newP - oldP;
            const timeStr = entry.changedAt
                ? new Date(entry.changedAt).toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })
                : '-';
            let diffBadge = `<span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-slate-100 text-slate-600">Awal</span>`;
            if (oldP > 0 && diff > 0) {
                diffBadge = `<span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-emerald-100 text-emerald-700">+Rp ${diff.toLocaleString('id-ID')}</span>`;
            } else if (oldP > 0 && diff < 0) {
                diffBadge = `<span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-rose-100 text-rose-700">-Rp ${Math.abs(diff).toLocaleString('id-ID')}</span>`;
            }
            return `
                <div class="p-3 bg-white border border-slate-200 rounded-2xl shadow-2xs space-y-1">
                    <div class="flex items-center justify-between gap-2">
                        <span class="text-[10px] font-black text-slate-800">${entry.note || 'Perubahan Harga'}</span>
                        ${diffBadge}
                    </div>
                    <div class="flex items-center justify-between text-xs font-black">
                        <span class="text-slate-400 ${oldP > 0 ? 'line-through' : ''}">${oldP > 0 ? 'Rp ' + oldP.toLocaleString('id-ID') : 'Baru'}</span>
                        <i class="fa-solid fa-arrow-right text-[10px] text-amber-500"></i>
                        <span class="text-indigo-700">Rp ${newP.toLocaleString('id-ID')}</span>
                    </div>
                    <div class="flex items-center justify-between text-[9px] font-bold text-slate-400 pt-1 border-t border-slate-100">
                        <span><i class="fa-regular fa-clock mr-1"></i>${timeStr}</span>
                        <span><i class="fa-solid fa-user-pen mr-1"></i>${entry.changedBy || 'Owner'}</span>
                    </div>
                </div>
            `;
        }).join('');
    }
    modal.classList.remove('hidden');
};

// Delegated Visual Click Feedback untuk Tombol Menu di POS Kasir & Ruang Kerja Kasir
if (!window._posClickFeedbackBound) {
    window._posClickFeedbackBound = true;
    document.addEventListener('click', (ev) => {
        const target = ev.target?.closest?.('#panel-kasir-manual button, #panel-kasir-manual .pos-menu-card, #ruang-kerja-kasir button');
        if (!target) return;
        const isDark = target.className.includes('bg-slate-8') || target.className.includes('bg-slate-9') || target.className.includes('bg-blue-6') || target.className.includes('bg-emerald-6') || target.className.includes('bg-indigo-6');
        const cls = isDark ? 'pos-btn-dark-clicked' : 'pos-btn-clicked';
        target.classList.remove('pos-btn-clicked', 'pos-btn-dark-clicked');
        void target.offsetWidth;
        target.classList.add(cls);
        setTimeout(() => { target.classList.remove(cls); }, 280);
    }, true);
}

window.normalizeMasterIdArray = (val) => {
    if (Array.isArray(val)) return val.filter(Boolean);
    if (val && typeof val === 'object') return Object.values(val).filter(Boolean);
    return [];
};

window.klikMenuPOS = (keyUnik, element) => {
    // Memberikan umpan balik visual instan (flash background + skala singkat) jika element tersedia
    if (element) {
        element.classList.add('bg-indigo-100', 'border-indigo-500', 'scale-95', 'pos-btn-clicked');
        setTimeout(() => {
            element.classList.remove('bg-indigo-100', 'border-indigo-500', 'scale-95', 'pos-btn-clicked');
        }, 220);
    }

    const menu = Array.isArray(globalMenus) 
        ? globalMenus.find((m, idx) => (m.key !== undefined ? m.key == keyUnik : idx == keyUnik)) 
        : globalMenus[keyUnik];

    if (!menu) return;

    const namaMenu = menu.nama || menu.title || menu.name || menu.menu || "Menu Tanpa Nama";
    const hargaAsli = Number(menu.harga || menu.price || menu.cost || menu.nominal || 0);
    const hargaDasar = (typeof window.getMenuEffectivePrice === 'function')
        ? Number(window.getMenuEffectivePrice({ ...menu, price: hargaAsli }))
        : hargaAsli;
    
    const rawVarianIds = window.normalizeMasterIdArray(menu.varianIds || menu.varian || menu.variants || menu.variantIds);
    const isVarianActive = menu.hasVariant === true || (menu.hasVariant !== false && rawVarianIds.length > 0);
    const linkedVarianIds = isVarianActive ? rawVarianIds : [];

    const rawToppingIds = window.normalizeMasterIdArray(menu.toppingIds || menu.toppings || menu.topping);
    const isToppingActive = menu.hasTopping === true || (menu.hasTopping !== false && rawToppingIds.length > 0);
    const linkedToppingIds = isToppingActive ? rawToppingIds : [];

    menuDipilihSementara = {
        key: keyUnik,
        nama: namaMenu,
        hargaDasar,
        hargaAsli,
        hasVariant: isVarianActive && linkedVarianIds.length > 0,
        hasTopping: isToppingActive && linkedToppingIds.length > 0,
        varianIds: linkedVarianIds,
        toppingIds: linkedToppingIds,
        isAvailable: menu.isAvailable !== false,
        menu
    };

    bukaModalVarian(menuDipilihSementara);
};

// =======================================================
// MANAJEMEN STATE STABIL & REAKTIF VARIAN POS KASIR
// Mencegah desinkronisasi atau titik radio hilang/berpindah
// =======================================================
window.posActiveOrderState = {
    menu: null,
    qty: 1,
    selectedVariants: {}, // { [vIndex]: { groupName, optionName, extraPrice, optionIndex } }
    selectedToppings: {}, // { [topId]: { toppingName, extraPrice } }
    variantsList: [],
    toppingsList: []
};

// Fungsi Kontrol Jumlah Produk di Modal POS
window.ubahModalQty = (delta) => {
    const input = document.getElementById('modal-qty-input');
    let val = parseInt(window.posActiveOrderState.qty || (input ? input.value : 1)) || 1;
    val = Math.max(1, val + delta);
    window.posActiveOrderState.qty = val;
    if (input) input.value = val;
    window.updateModalTotalPreview();
};

window.setModalQty = (val) => {
    const input = document.getElementById('modal-qty-input');
    let parsed = parseInt(val) || 1;
    parsed = Math.max(1, parsed);
    window.posActiveOrderState.qty = parsed;
    if (input) input.value = parsed;
    window.updateModalTotalPreview();
};

// Hitung total harga preview dalam modal secara dinamis dari state stabil
window.updateModalTotalPreview = () => {
    const state = window.posActiveOrderState;
    if (!state.menu) return;

    const basePrice = Number(state.menu.hargaDasar || state.menu.harga || state.menu.price || 0);
    
    // Hitung seluruh varian terpilih dari masing-masing grup independen (Ukuran, Level Es, Level Gula, dll)
    let extraVarian = 0;
    Object.values(state.selectedVariants || {}).forEach(v => {
        extraVarian += Number(v.extraPrice || 0);
    });

    // Hitung topping terpilih
    let extraTopping = 0;
    Object.values(state.selectedToppings || {}).forEach(t => {
        extraTopping += Number(t.extraPrice || 0);
    });

    const qty = Math.max(1, parseInt(state.qty) || 1);
    const unitTotal = basePrice + extraVarian + extraTopping;
    const grandTotal = unitTotal * qty;

    const btnText = document.getElementById('btn-konfirmasi-varian-text');
    if (btnText) {
        btnText.innerText = `Tambah (${qty}x) • Rp ${grandTotal.toLocaleString('id-ID')}`;
    }
};

// Handler Pemilihan Opsi Varian Mandiri (Grup Ukuran, Es, Gula saling independen)
window.pilihVarianPOS = (vIndex, oIndex) => {
    const state = window.posActiveOrderState;
    const group = (state.variantsList || [])[vIndex];
    if (!group || !group.opsi || !group.opsi[oIndex]) return;

    const opt = group.opsi[oIndex];
    const vGroupName = group.name || group.nama || `Varian ${vIndex + 1}`;
    const optNama = opt.namaOpsi || opt.name || opt.nama || '';
    const optHarga = Number(opt.harga || opt.price || 0);

    // Update state untuk grup ini TANPA menyentuh grup lainnya sama sekali
    state.selectedVariants[vIndex] = {
        groupName: vGroupName,
        optionName: optNama,
        extraPrice: optHarga,
        optionIndex: oIndex
    };

    // Update tampilan visual kartu & titik radio HANYA di dalam grup vIndex ini
    (group.opsi || []).forEach((_, oi) => {
        const cardEl = document.getElementById(`pos_opt_card_${vIndex}_${oi}`);
        const dotEl = document.getElementById(`pos_radio_dot_${vIndex}_${oi}`);
        if (!cardEl || !dotEl) return;

        if (oi === oIndex) {
            // Aktif Terpilih
            cardEl.className = "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition select-none bg-blue-50/90 border border-blue-600 ring-1 ring-blue-500 shadow-xs";
            dotEl.className = "w-4 h-4 rounded-full border-2 border-blue-600 shrink-0 bg-white flex items-center justify-center";
            dotEl.innerHTML = `<span class="w-2 h-2 rounded-full bg-blue-600"></span>`;
        } else {
            // Tidak Terpilih
            cardEl.className = "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition select-none bg-white border border-slate-200 hover:border-blue-300 hover:bg-slate-50/50";
            dotEl.className = "w-4 h-4 rounded-full border-2 border-slate-300 shrink-0 bg-white flex items-center justify-center";
            dotEl.innerHTML = ``;
        }
    });

    window.updateModalTotalPreview();
};

// Handler Pemilihan Topping Tambahan (Checkbox Mandiri)
window.toggleToppingPOS = (topId, topName, topPrice, tIdx) => {
    const state = window.posActiveOrderState;
    const isSelected = !!state.selectedToppings[topId];

    if (isSelected) {
        delete state.selectedToppings[topId];
    } else {
        state.selectedToppings[topId] = {
            toppingName: topName,
            extraPrice: Number(topPrice || 0)
        };
    }

    const cardEl = document.getElementById(`pos_top_card_${tIdx}`);
    const cbEl = document.getElementById(`pos_top_cb_${tIdx}`);
    if (cardEl && cbEl) {
        if (!isSelected) {
            // Sekarang Terpilih
            cardEl.className = "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition select-none bg-amber-50/90 border border-amber-500 ring-1 ring-amber-400 shadow-xs";
            cbEl.className = "w-4 h-4 rounded border border-amber-500 bg-amber-500 text-white shrink-0 flex items-center justify-center";
            cbEl.innerHTML = `<i class="fa-solid fa-check text-[10px]"></i>`;
        } else {
            // Sekarang Dibatalkan
            cardEl.className = "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition select-none bg-white border border-slate-200 hover:border-amber-400 hover:bg-slate-50/50";
            cbEl.className = "w-4 h-4 rounded border border-slate-300 bg-white shrink-0 flex items-center justify-center";
            cbEl.innerHTML = ``;
        }
    }

    window.updateModalTotalPreview();
};

window.posEditCartIndex = null;

window.bukaModalVarian = (data, existingCartItem = null) => {
    const modal = document.getElementById('modal-varian-pos');
    const titleEl = document.getElementById('modal-menu-title');
    const priceEl = document.getElementById('modal-menu-price');
    const optionsEl = document.getElementById('modal-varian-options');
    const qtyInput = document.getElementById('modal-qty-input');
    const btnText = document.getElementById('btn-konfirmasi-varian-text');
    if (!modal) return;

    if ((!window.masterVarian || window.masterVarian.length === 0 || !window.masterTopping || window.masterTopping.length === 0) && typeof window.seedDefaultMasterData === 'function') {
        window.seedDefaultMasterData();
    }

    const isEditing = Boolean(existingCartItem);
    if (titleEl) {
        titleEl.innerText = (data.nama || data.name || "Menu") + (isEditing ? " (Edit)" : "");
    }
    const hrgDasar = Number(data.hargaDasar || data.harga || data.price || 0);
    const hrgAsli = Number(data.hargaAsli || data.price || data.harga || hrgDasar);
    if (priceEl) {
        if (hrgAsli > hrgDasar) {
            priceEl.innerHTML = `Harga Promo: Rp ${hrgDasar.toLocaleString('id-ID')} <span class="line-through text-slate-400 font-semibold ml-1">Rp ${hrgAsli.toLocaleString('id-ID')}</span>`;
        } else {
            priceEl.innerText = `Harga Dasar: Rp ${hrgDasar.toLocaleString('id-ID')}`;
        }
    }
    const initialQty = isEditing ? Math.max(1, Number(existingCartItem.qty) || 1) : 1;
    if (qtyInput) qtyInput.value = String(initialQty);

    if (btnText) {
        btnText.innerText = isEditing ? "Simpan Perubahan" : "Masukkan Keranjang";
    }

    const toArray = typeof window.normalizeMasterIdArray === 'function'
        ? window.normalizeMasterIdArray
        : (v => Array.isArray(v) ? v.filter(Boolean) : (v && typeof v === 'object' ? Object.values(v).filter(Boolean) : []));

    // A. TARIK DAFTAR VARIAN & TOPPING (Hukung Array maupun Firebase Object Map; saat Edit tetap tampilkan opsi master jika menu belum punya tag spesifik)
    const rawVarIds = toArray(data.varianIds || data.varian || data.variants || data.variantIds);
    const allowVarian = isEditing ? (data.hasVariant !== false) : (data.hasVariant === true || (data.hasVariant !== false && rawVarIds.length > 0));
    let variantsToRender = [];
    if (allowVarian && rawVarIds.length > 0) {
        variantsToRender = rawVarIds.map(vid => typeof window.resolveVarian === 'function' ? window.resolveVarian(vid) : null).filter(Boolean);
    }
    if (isEditing && allowVarian && variantsToRender.length === 0) {
        variantsToRender = Array.isArray(window.masterVarian) ? window.masterVarian.filter(Boolean) : [];
    }

    const rawTopIds = toArray(data.toppingIds || data.toppings || data.topping);
    const allowTopping = isEditing ? (data.hasTopping !== false) : (data.hasTopping === true || (data.hasTopping !== false && rawTopIds.length > 0));
    let toppingsToRender = [];
    if (allowTopping && rawTopIds.length > 0) {
        toppingsToRender = rawTopIds.map(tid => typeof window.resolveTopping === 'function' ? window.resolveTopping(tid) : null).filter(Boolean);
    }
    if (isEditing && allowTopping && toppingsToRender.length === 0) {
        toppingsToRender = Array.isArray(window.masterTopping) ? window.masterTopping.filter(Boolean) : [];
    }

    // B. INISIALISASI STATE ORDER AKTIF
    window.posActiveOrderState = {
        menu: data,
        qty: initialQty,
        selectedVariants: {},
        selectedToppings: {},
        variantsList: variantsToRender,
        toppingsList: toppingsToRender
    };

    // Helper untuk mendeteksi pilihan awal jika sedang edit
    const existingVarianRaw = isEditing ? String(existingCartItem.varian || existingCartItem.notes || '') : '';
    const existingVarianStr = existingVarianRaw.toLowerCase();
    const existingToppings = isEditing && Array.isArray(existingCartItem.toppings) ? existingCartItem.toppings.map(t => String(t).toLowerCase().trim()) : [];
    let extractedCustomNote = '';
    const noteMatch = existingVarianRaw.match(/Catatan:\s*(.+)$/i);
    if (noteMatch && noteMatch[1]) extractedCustomNote = noteMatch[1].trim();

    variantsToRender.forEach((v, vIndex) => {
        const vGroupName = v.name || v.nama || `Varian ${vIndex + 1}`;
        let matchedOptIndex = 0;

        if (isEditing && Array.isArray(v.opsi)) {
            const foundIdx = v.opsi.findIndex(opt => {
                const optNm = String(opt.namaOpsi || opt.name || opt.nama || '').toLowerCase().trim();
                return optNm && existingVarianStr.includes(optNm);
            });
            if (foundIdx >= 0) matchedOptIndex = foundIdx;
        }

        const selectedOpt = (v.opsi && v.opsi[matchedOptIndex]) || (v.opsi && v.opsi[0]) || { namaOpsi: 'Normal', harga: 0 };
        const optNama = selectedOpt.namaOpsi || selectedOpt.name || selectedOpt.nama || 'Normal';
        const optHarga = Number(selectedOpt.harga || selectedOpt.price || 0);

        window.posActiveOrderState.selectedVariants[vIndex] = {
            groupName: vGroupName,
            optionName: optNama,
            extraPrice: optHarga,
            optionIndex: matchedOptIndex
        };
    });

    if (isEditing && toppingsToRender.length > 0) {
        toppingsToRender.forEach((top, tIdx) => {
            const topId = String(top.id || top.nama || ('top_' + tIdx)).replace(/[^a-zA-Z0-9_-]/g, '_');
            const topName = top.nama || top.name || 'Topping';
            const topPrice = Number(top.harga || top.price || 0);
            const isMatch = existingToppings.some(et => et === topName.toLowerCase()) || existingVarianStr.includes(topName.toLowerCase());
            if (isMatch) {
                window.posActiveOrderState.selectedToppings[topId] = {
                    topId: topId,
                    toppingName: topName,
                    extraPrice: topPrice
                };
            }
        });
    }

    // C. BANGUN HTML DENGAN ELEMEN INDEPENDEN TERIKAT STATE
    let htmlOptions = '';

    // Render Grup Varian (Ukuran Cup, Kadar Es, Kadar Gula)
    if (variantsToRender.length > 0) {
        variantsToRender.forEach((v, vIndex) => {
            const vGroupName = v.name || v.nama || `Varian ${vIndex + 1}`;
            htmlOptions += `
                <div class="mb-3 bg-slate-50 p-2.5 rounded-xl border border-slate-200">
                    <label class="text-[10px] font-black text-slate-700 uppercase block mb-1.5 flex items-center gap-1.5">
                        <i class="fa-solid fa-layer-group text-blue-600"></i> ${vGroupName}
                    </label>
                    <div class="grid grid-cols-2 gap-1.5">
            `;

            const currentSelectedIdx = window.posActiveOrderState.selectedVariants[vIndex]?.optionIndex ?? 0;

            (v.opsi || []).forEach((opt, oIndex) => {
                const isSelected = oIndex === currentSelectedIdx;
                const optNama = opt.namaOpsi || opt.name || opt.nama || '';
                const optHarga = Number(opt.harga || opt.price || 0);
                const extraTeks = optHarga > 0 ? ` (+Rp ${optHarga.toLocaleString('id-ID')})` : '';

                const cardClass = isSelected 
                    ? "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition select-none bg-blue-50/90 border border-blue-600 ring-1 ring-blue-500 shadow-xs" 
                    : "flex items-center gap-2 p-2 rounded-lg cursor-pointer transition select-none bg-white border border-slate-200 hover:border-blue-300 hover:bg-slate-50/50";

                const dotClass = isSelected
                    ? "w-4 h-4 rounded-full border-2 border-blue-600 shrink-0 bg-white flex items-center justify-center"
                    : "w-4 h-4 rounded-full border-2 border-slate-300 shrink-0 bg-white flex items-center justify-center";

                const dotContent = isSelected ? `<span class="w-2 h-2 rounded-full bg-blue-600"></span>` : '';

                htmlOptions += `
                    <div id="pos_opt_card_${vIndex}_${oIndex}" onclick="window.pilihVarianPOS(${vIndex}, ${oIndex})" class="${cardClass}">
                        <span id="pos_radio_dot_${vIndex}_${oIndex}" class="${dotClass}">${dotContent}</span>
                        <div class="min-w-0 flex-1">
                            <span class="text-xs font-bold text-slate-800 block leading-tight truncate">${optNama}</span>
                            <span class="text-[9px] text-indigo-600 font-medium">${extraTeks || 'Normal'}</span>
                        </div>
                    </div>
                `;
            });

            htmlOptions += `</div></div>`;
        });
    }

    // Render Grup Topping
    if (toppingsToRender.length > 0) {
        htmlOptions += `
            <div class="bg-slate-50 p-2.5 rounded-xl border border-slate-200">
                <label class="text-[10px] font-black text-slate-700 uppercase block mb-1.5 flex items-center gap-1.5">
                    <i class="fa-solid fa-cheese text-amber-500"></i> Pilih Topping Tambahan (Opsional)
                </label>
                <div class="grid grid-cols-2 gap-1.5">
        `;

        toppingsToRender.forEach((top, tIdx) => {
            const topId = String(top.id || top.nama || ('top_' + tIdx)).replace(/[^a-zA-Z0-9_-]/g, '_');
            const topName = top.nama || top.name || 'Topping';
            const topPrice = Number(top.harga || top.price || 0);
            const isTopSelected = Boolean(window.posActiveOrderState.selectedToppings[topId]);

            const topCardClass = isTopSelected
                ? "flex items-center gap-2 p-2 bg-amber-50/90 border border-amber-500 ring-1 ring-amber-400 rounded-lg cursor-pointer transition select-none shadow-xs"
                : "flex items-center gap-2 p-2 bg-white border border-slate-200 rounded-lg cursor-pointer hover:border-amber-400 hover:bg-slate-50/50 transition select-none";

            const topCbClass = isTopSelected
                ? "w-4 h-4 rounded border border-amber-500 bg-amber-500 text-white shrink-0 flex items-center justify-center text-[10px]"
                : "w-4 h-4 rounded border border-slate-300 bg-white shrink-0 flex items-center justify-center";

            const topCbContent = isTopSelected ? `<i class="fa-solid fa-check text-[10px] text-white"></i>` : '';

            htmlOptions += `
                <div id="pos_top_card_${tIdx}" onclick="window.toggleToppingPOS('${topId}', '${topName}', ${topPrice}, ${tIdx})" class="${topCardClass}">
                    <span id="pos_top_cb_${tIdx}" class="${topCbClass}">${topCbContent}</span>
                    <div class="min-w-0 flex-1">
                        <span class="text-xs font-bold text-slate-800 block leading-tight truncate">${topName}</span>
                        <span class="text-[9px] text-amber-600 font-bold">+Rp ${topPrice.toLocaleString('id-ID')}</span>
                    </div>
                </div>
            `;
        });

        htmlOptions += `</div></div>`;
    }

    if (!htmlOptions) {
        htmlOptions = `<div class="p-3 bg-slate-50 rounded-xl border border-dashed border-slate-200 text-center text-xs text-slate-400 font-medium mb-3"><i class="fa-solid fa-mug-saucer mr-1 text-slate-300"></i> Menu standar tanpa varian tambahan.</div>`;
    }

    htmlOptions += `
        <div class="mt-3 bg-slate-50 p-2.5 rounded-xl border border-slate-200">
            <label for="modal-varian-custom-note" class="text-[10px] font-black text-slate-700 uppercase block mb-1.5 flex items-center gap-1.5">
                <i class="fa-regular fa-note-sticky text-emerald-600"></i> Catatan Khusus Kasir (Opsional)
            </label>
            <input type="text" id="modal-varian-custom-note" value="${extractedCustomNote.replace(/"/g, '&quot;')}" placeholder="Contoh: Es dipisah, tanpa sedotan, extra manis..." class="w-full px-3 py-2 rounded-lg bg-white border border-slate-200 text-xs font-bold text-slate-800 outline-none focus:border-blue-500">
        </div>
    `;

    if (optionsEl) optionsEl.innerHTML = htmlOptions;

    // Perbarui indikator ketersediaan & tombol toggle switch
    window.updateModalMenuAvailabilityUI(data.isAvailable !== false);

    modal.classList.remove('hidden');
    modal.classList.add('flex');

    window.updateModalTotalPreview();
};

window.updateModalMenuAvailabilityUI = (isAvail) => {
    const dot = document.getElementById('modal-menu-avail-dot');
    const label = document.getElementById('modal-menu-avail-label');
    const btn = document.getElementById('btn-toggle-menu-pos');
    const dotSwitch = document.getElementById('btn-toggle-menu-pos-dot');
    if (!dot || !label) return;
    if (isAvail) {
        dot.className = 'w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shrink-0';
        label.className = 'text-xs font-black text-emerald-600';
        label.innerText = 'TERSEDIA';
        if (btn) {
            btn.className = 'relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none bg-emerald-500 shadow-inner';
            btn.setAttribute('aria-checked', 'true');
        }
        if (dotSwitch) dotSwitch.className = 'pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out translate-x-5';
    } else {
        dot.className = 'w-2.5 h-2.5 rounded-full bg-rose-500 shrink-0';
        label.className = 'text-xs font-black text-rose-600';
        label.innerText = 'HABIS / KOSONG';
        if (btn) {
            btn.className = 'relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none bg-slate-300 shadow-inner';
            btn.setAttribute('aria-checked', 'false');
        }
        if (dotSwitch) dotSwitch.className = 'pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out translate-x-0';
    }
};

window.toggleCurrentMenuAvailabilityPOS = async () => {
    const activeMenu = window.posActiveOrderState?.menu;
    if (!activeMenu) return;

    let targetKey = activeMenu.key || activeMenu.id;
    if (!targetKey && globalMenus) {
        const activeName = (activeMenu.nama || activeMenu.name || '').trim().toLowerCase();
        targetKey = Object.keys(globalMenus).find(k => {
            const m = globalMenus[k];
            return m && ((m.nama || m.name || '').trim().toLowerCase() === activeName);
        });
    }
    if (!targetKey) return;

    await window.toggleKetersediaanMenuDariPOS(targetKey);
    const m = (globalMenus && globalMenus[targetKey]);
    const newAvail = m ? (m.isAvailable !== false) : true;
    activeMenu.isAvailable = newAvail;
    window.updateModalMenuAvailabilityUI(newAvail);
};

window.toggleKetersediaanMenuDariPOS = async (keyUnik, forceAvail = null) => {
    let targetKey = String(keyUnik);
    let m = globalMenus ? globalMenus[targetKey] : null;
    if (!m && globalMenus) {
        targetKey = Object.keys(globalMenus).find(k => k == keyUnik || (globalMenus[k] && (globalMenus[k].id == keyUnik || globalMenus[k].key == keyUnik))) || targetKey;
        m = globalMenus[targetKey];
    }
    if (!m) return;

    const currentAvail = m.isAvailable !== false;
    const newAvail = forceAvail !== null ? Boolean(forceAvail) : !currentAvail;
    m.isAvailable = newAvail;

    try {
        localStorage.setItem('mainstay_cached_menus', JSON.stringify(globalMenus));
    } catch(e) {}

    try {
        await set(ref(db, `menus/${targetKey}/isAvailable`), newAvail);
    } catch(e) {
        console.warn("Sync RTDB menu avail error:", e);
    }

    if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
    if (typeof window.renderKatalog === 'function') window.renderKatalog();
    if (typeof window.renderPanelMenu === 'function' && document.getElementById('owner-menu-list')) window.renderPanelMenu();

    if (typeof window.tampilkanNotifikasi === 'function') {
        const menuName = m.nama || m.name || 'Menu';
        window.tampilkanNotifikasi(newAvail ? `Menu "${menuName}" aktif (Tersedia)` : `Menu "${menuName}" ditandai Habis`, newAvail ? 'success' : 'warning');
    }
};

window.bukaModalEditItemKeranjangPOS = (index) => {
    const item = posKeranjang[index];
    if (!item) return;

    window.posEditCartIndex = index;
    let menuData = null;

    const allMenusObj = (typeof window.globalMenus === 'object' && window.globalMenus) 
        ? window.globalMenus 
        : (typeof globalMenus === 'object' && globalMenus) 
            ? globalMenus 
            : null;

    let cleanItemName = String(item.nama || item.name || '').trim();
    while (/\s*\(([^)]+)\)\s*$/.test(cleanItemName)) {
        cleanItemName = cleanItemName.replace(/\s*\(([^)]+)\)\s*$/, '').trim();
    }
    const cleanNameLower = cleanItemName.toLowerCase();

    if (allMenusObj) {
        if (item.rawMenuKey && allMenusObj[item.rawMenuKey]) {
            menuData = { key: item.rawMenuKey, ...allMenusObj[item.rawMenuKey] };
        } else if (item.key && allMenusObj[item.key]) {
            menuData = { key: item.key, ...allMenusObj[item.key] };
        } else {
            const foundEntry = Object.entries(allMenusObj).find(([k, m]) => {
                if (!m) return false;
                const mName = String(m.nama || m.name || '').trim().toLowerCase();
                return mName === cleanNameLower || cleanNameLower.includes(mName) || mName.includes(cleanNameLower);
            });
            if (foundEntry) {
                menuData = { key: foundEntry[0], ...foundEntry[1] };
            }
        }
    }

    if (!menuData) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_cached_menus') || '{}');
            if (item.rawMenuKey && cached[item.rawMenuKey]) {
                menuData = { key: item.rawMenuKey, ...cached[item.rawMenuKey] };
            } else {
                const foundEntry = Object.entries(cached).find(([k, m]) => {
                    if (!m) return false;
                    const mName = String(m.nama || m.name || '').trim().toLowerCase();
                    return mName === cleanNameLower;
                });
                if (foundEntry) {
                    menuData = { key: foundEntry[0], ...foundEntry[1] };
                }
            }
        } catch(e) {}
    }

    if (!menuData) {
        const masterVIds = Array.isArray(window.masterVarian) ? window.masterVarian.map(v => v.id).filter(Boolean) : [];
        const masterTIds = Array.isArray(window.masterTopping) ? window.masterTopping.map(t => t.id).filter(Boolean) : [];
        menuData = {
            key: item.rawMenuKey || ('menu_' + index),
            nama: cleanItemName || item.nama,
            harga: Number(item.hargaAsli || item.harga || 0),
            hargaAsli: Number(item.hargaAsli || item.harga || 0),
            hargaDasar: Number(item.harga || 0),
            hasVariant: true,
            hasTopping: true,
            varianIds: masterVIds,
            toppingIds: masterTIds
        };
    } else {
        const rawHarga = Number(menuData.harga || menuData.price || menuData.cost || item.hargaAsli || item.harga || 0);
        const effHarga = (typeof window.getMenuEffectivePrice === 'function')
            ? Number(window.getMenuEffectivePrice({ ...menuData, price: rawHarga }))
            : rawHarga;
        menuData = {
            ...menuData,
            nama: menuData.nama || menuData.name || cleanItemName,
            hargaAsli: rawHarga,
            hargaDasar: effHarga
        };
    }

    window.bukaModalVarian(menuData, item);
};

window.tutupModalVarian = () => {
    const modal = document.getElementById('modal-varian-pos');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    const btnText = document.getElementById('btn-konfirmasi-varian-text');
    if (btnText) btnText.innerText = 'Masukkan Keranjang';
    menuDipilihSementara = null;
    window.posEditCartIndex = null;
    window.posActiveOrderState = { menu: null, qty: 1, selectedVariants: {}, selectedToppings: {}, variantsList: [], toppingsList: [] };
};

window.konfirmasiTambahVarian = () => {
    const state = window.posActiveOrderState;
    if (!state.menu) return;

    // Jika menu masih berstatus HABIS saat kasir ingin memasukkan ke keranjang
    if (state.menu.isAvailable === false) {
        window.tampilkanKonfirmasiGlobal({
            title: "Menu Berstatus Habis",
            message: `Menu "${state.menu.nama || 'ini'}" saat ini masih ditandai HABIS.`,
            subtext: "Aktifkan menu menjadi TERSEDIA dan masukkan ke keranjang kasir sekarang?",
            icon: "fa-toggle-on",
            confirmText: "Aktifkan & Masukkan",
            cancelText: "Batal",
            isDanger: false,
            onConfirm: async () => {
                await window.toggleCurrentMenuAvailabilityPOS();
                window.konfirmasiTambahVarian();
            }
        });
        return;
    }

    const qty = Math.max(1, parseInt(state.qty) || 1);
    const basePrice = Number(state.menu.hargaDasar || state.menu.harga || state.menu.price || 0);
    const rawAsliBase = Math.max(basePrice, Number(state.menu.hargaAsli || state.menu.price || state.menu.harga || basePrice));

    const varianLabels = [];
    let extraHargaVarian = 0;
    Object.values(state.selectedVariants || {}).forEach(v => {
        extraHargaVarian += Number(v.extraPrice || 0);
        if (v.optionName) {
            varianLabels.push(v.groupName ? `${v.groupName}: ${v.optionName}` : v.optionName);
        }
    });

    const toppingNames = [];
    let extraHargaTopping = 0;
    Object.values(state.selectedToppings || {}).forEach(t => {
        extraHargaTopping += Number(t.extraPrice || 0);
        toppingNames.push(t.toppingName);
    });

    const customNote = (document.getElementById('modal-varian-custom-note')?.value || '').trim();
    let catatanVarian = varianLabels.length > 0 ? varianLabels.join(', ') : "Standard";
    let subKeterangan = catatanVarian;
    if (toppingNames.length > 0) {
        subKeterangan += ` + ${toppingNames.join(', ')}`;
    }
    if (customNote) {
        subKeterangan += ` • Catatan: ${customNote}`;
    }

    const hargaSatuan = basePrice + extraHargaVarian + extraHargaTopping;
    const hargaAsliSatuan = rawAsliBase + extraHargaVarian + extraHargaTopping;
    const namaMenuMurni = state.menu.nama || state.menu.name || "Menu";
    const cartUniqueKey = `${state.menu.key}_${varianLabels.join('|')}_${toppingNames.sort().join('-')}_${customNote}`;

    // Jika sedang dalam mode edit item keranjang kasir
    if (window.posEditCartIndex !== null && window.posEditCartIndex !== undefined && window.posEditCartIndex >= 0 && posKeranjang[window.posEditCartIndex]) {
        const prevQty = Number(posKeranjang[window.posEditCartIndex]?.qty || 0);
        posKeranjang[window.posEditCartIndex] = {
            key: cartUniqueKey,
            nama: namaMenuMurni,
            harga: hargaSatuan,
            hargaAsli: hargaAsliSatuan,
            qty: qty,
            varian: subKeterangan,
            rawMenuKey: state.menu.key || state.menu.id,
            toppings: toppingNames
        };
        window.posEditCartIndex = null;
        window.simpanStateKeranjangPOS();
        renderKeranjangPOS();
        if (qty > prevQty && typeof window.syncPosCartBadges === 'function') {
            window.syncPosCartBadges(true);
        }
        window.tutupModalVarian();
        if (typeof window.showNotification === 'function') {
            window.showNotification("Menu di keranjang berhasil diperbarui!", "success");
        }
        return;
    }

    tambahKeKeranjangPOS(
        cartUniqueKey,
        namaMenuMurni,
        hargaSatuan,
        subKeterangan,
        qty,
        state.menu.key,
        toppingNames,
        hargaAsliSatuan
    );

    window.tutupModalVarian();
};

window.simpanStateKeranjangPOS = () => {
    try {
        const dataJson = JSON.stringify(posKeranjang || []);
        sessionStorage.setItem('mainstay_pos_keranjang', dataJson);
        localStorage.setItem('mainstay_pos_keranjang_backup', dataJson);
    } catch(e) {}
};

window.kosongkanKeranjangPOS = () => {
    if (!posKeranjang || posKeranjang.length === 0) {
        return;
    }
    if (typeof window.tampilkanKonfirmasiGlobal === 'function') {
        window.tampilkanKonfirmasiGlobal({
            title: "Kosongkan Keranjang Kasir?",
            message: "Apakah Anda yakin ingin mengosongkan seluruh pesanan dari keranjang kasir?",
            subtext: "Item yang sudah dipilih akan dihapus dari antrean kasir ini.",
            icon: "fa-trash-can",
            confirmText: "Ya, Kosongkan",
            isDanger: true,
            onConfirm: () => {
                posKeranjang = [];
                window.posAppliedVoucher = null;
                window.simpanStateKeranjangPOS();
                renderKeranjangPOS();
            }
        });
    } else {
        posKeranjang = [];
        window.posAppliedVoucher = null;
        window.simpanStateKeranjangPOS();
        renderKeranjangPOS();
    }
};

window.syncPosCartBadges = (shouldAnimate = false) => {
    const totalItems = Array.isArray(posKeranjang)
        ? posKeranjang.reduce((sum, it) => sum + (Number(it?.qty) || 1), 0)
        : 0;

    const badgeIds = ['pos-cart-badge', 'pos-header-cart-badge', 'kasir-fab-cart-badge'];
    badgeIds.forEach((id) => {
        const el = document.getElementById(id);
        if (!el) return;
        if (totalItems > 0) {
            el.innerText = totalItems;
            el.classList.remove('hidden');
            if (id !== 'pos-cart-badge') el.classList.add('flex');
        } else {
            el.innerText = '0';
            el.classList.add('hidden');
            if (id !== 'pos-cart-badge') el.classList.remove('flex');
        }
    });

    if (shouldAnimate && totalItems > 0 && typeof window.triggerCartBadgePulseShake === 'function') {
        ['pos-cart-badge', 'pos-cart-icon', 'pos-header-cart-badge', 'kasir-fab-cart-badge'].forEach((id) => {
            const targetEl = document.getElementById(id);
            if (targetEl && !targetEl.classList.contains('hidden')) {
                window.triggerCartBadgePulseShake(targetEl);
            }
        });
    }
};

window.tambahKeKeranjangPOS = (key, nama, harga, varian = "Normal", qty = 1, rawMenuKey = null, toppings = [], hargaAsli = null) => {
    const index = posKeranjang.findIndex(item => item.key === key);
    const addedQty = Number(qty) || 1;
    const hrg = Number(harga) || 0;
    const hrgAsli = Math.max(hrg, Number(hargaAsli || hrg));
    if (index > -1) {
        posKeranjang[index].qty += addedQty;
        if (hrgAsli > Number(posKeranjang[index].hargaAsli || posKeranjang[index].harga || 0)) {
            posKeranjang[index].hargaAsli = hrgAsli;
        }
    } else {
        posKeranjang.push({
            key: key,
            nama: nama,
            harga: hrg,
            hargaAsli: hrgAsli,
            qty: addedQty,
            varian: varian,
            rawMenuKey: rawMenuKey,
            toppings: toppings
        });
    }
    window.simpanStateKeranjangPOS();
    renderKeranjangPOS();
    window.syncPosCartBadges(true);
};

window.ubahQtyKeranjangPOS = (index, delta) => {
    if (!posKeranjang[index]) return;
    posKeranjang[index].qty += delta;
    if (posKeranjang[index].qty <= 0) {
        posKeranjang.splice(index, 1);
    }
    window.simpanStateKeranjangPOS();
    renderKeranjangPOS();
    if (Number(delta) > 0) {
        window.syncPosCartBadges(true);
    }
};

window.renderKeranjangPOS = () => {
    const wadah = document.getElementById('pos-keranjang-list');
    const tipePesanan = document.getElementById('pos-tipe-pesanan') ? document.getElementById('pos-tipe-pesanan').value : 'biasa';
    const infoMarkup = document.getElementById('pos-info-markup');
    const badgeMarkup = document.getElementById('pos-badge-markup');
    if (!wadah) return;

    // Pastikan penyimpanan state tersinkronisasi selalu (bahkan saat keranjang 0 item)
    window.simpanStateKeranjangPOS();
    if (typeof window.syncPosCartBadges === 'function') {
        window.syncPosCartBadges(false);
    }

    let subtotalMurni = 0;
    let pengaliHarga = 1;
    if (tipePesanan !== 'biasa') {
        pengaliHarga = 1.20;
        if(infoMarkup) infoMarkup.innerText = "Harga otomatis dinaikkan 20% untuk menyesuaikan potongan S&K Ojol.";
        if(badgeMarkup) badgeMarkup.classList.remove('hidden');
    } else {
        if(infoMarkup) infoMarkup.innerText = "Harga normal tanpa penyesuaian.";
        if(badgeMarkup) badgeMarkup.classList.add('hidden');
    }

    const verifyBanner = document.getElementById('pos-discount-verify-banner');
    const verifyText = document.getElementById('pos-discount-verify-text');

    if (posKeranjang.length === 0) {
        wadah.innerHTML = `<div class="p-4 border-2 border-dashed border-slate-200 rounded-xl text-center bg-slate-50"><p class="text-xs text-slate-500 font-medium">Keranjang masih kosong</p></div>`;
        if (verifyBanner) verifyBanner.classList.add('hidden');
        const posDiscWrapEmpty = document.getElementById('pos-discount-summary');
        if (posDiscWrapEmpty) posDiscWrapEmpty.classList.add('hidden');
        posTotalTagihan = 0;
        const elTotal = document.getElementById('pos-total-tagihan');
        if(elTotal) elTotal.innerText = "Rp 0";
        hitungKembalian();
        return;
    }

    let totalProductDiscount = 0;
    let discountedItemCount = 0;
    let subtotalOriginalMurni = 0;

    wadah.innerHTML = '';
    posKeranjang.forEach((item, i) => {
        let hargaFinalItem = Math.round((item.harga * pengaliHarga) / 100) * 100;
        let subtotalItem = hargaFinalItem * item.qty;
        subtotalMurni += subtotalItem;

        // Cek apakah menu memiliki harga diskon/promo dibanding harga normal katalog
        let rawOrigUnit = Number(item.hargaAsli || 0);
        if ((!rawOrigUnit || rawOrigUnit <= Number(item.harga || 0)) && typeof globalMenus === 'object' && globalMenus) {
            const refM = (item.rawMenuKey && globalMenus[item.rawMenuKey]) || Object.values(globalMenus).find(m => m && (m.key === item.rawMenuKey || m.id === item.rawMenuKey));
            if (refM && typeof window.getMenuEffectivePrice === 'function') {
                const mRaw = Number(refM.price || refM.harga || 0);
                const mEff = Number(window.getMenuEffectivePrice({ ...refM, price: mRaw }));
                if (mRaw > mEff && mEff > 0) {
                    rawOrigUnit = Number(item.harga || 0) + (mRaw - mEff);
                }
            }
        }
        let hargaAsliFinalItem = rawOrigUnit > Number(item.harga || 0)
            ? (Math.round((rawOrigUnit * pengaliHarga) / 100) * 100)
            : hargaFinalItem;
        let subtotalAsliItem = hargaAsliFinalItem * item.qty;
        subtotalOriginalMurni += subtotalAsliItem;

        const hasItemDiscount = hargaAsliFinalItem > hargaFinalItem;
        const itemSavings = hasItemDiscount ? (subtotalAsliItem - subtotalItem) : 0;
        const itemDiscPct = hasItemDiscount && subtotalAsliItem > 0 ? Math.round((itemSavings / subtotalAsliItem) * 100) : 0;
        if (hasItemDiscount) {
            totalProductDiscount += itemSavings;
            discountedItemCount += Number(item.qty || 1);
        }

        let cleanItemName = String(item.nama || item.name || 'Menu').trim();
        while (/\s*\(([^)]+)\)\s*$/.test(cleanItemName)) {
            cleanItemName = cleanItemName.replace(/\s*\(([^)]+)\)\s*$/, '').trim();
        }
        let varianDisplay = String(item.varian || item.notes || '').trim();
        if (varianDisplay.toLowerCase() === 'normal') varianDisplay = '';

        wadah.innerHTML += `
            <div class="border ${hasItemDiscount ? 'bg-emerald-50/35 border-emerald-300' : 'bg-white border-slate-200'} p-2.5 rounded-xl shadow-xs mb-2 min-w-0 transition">
                <div class="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-2.5 mb-2">
                    <div class="min-w-0">
                        <div class="flex items-center gap-1.5 flex-wrap">
                            <h4 class="text-xs font-black text-slate-800 leading-tight truncate">${cleanItemName}</h4>
                            ${hasItemDiscount ? `<span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-emerald-100 text-emerald-800 border border-emerald-200 text-[9px] font-black tabular-nums"><i class="fa-solid fa-tag text-[8px]"></i> Diskon -${itemDiscPct}%</span>` : ''}
                        </div>
                        ${varianDisplay ? `<p class="text-[10px] text-blue-600 font-bold mt-0.5 break-words">${varianDisplay}</p>` : ''}
                        <div class="flex items-center gap-1.5 flex-wrap mt-0.5 tabular-nums">
                            ${hasItemDiscount ? `<span class="text-[10px] text-slate-400 line-through">Rp ${hargaAsliFinalItem.toLocaleString('id-ID')}</span>` : ''}
                            <p class="text-[10px] ${hasItemDiscount ? 'text-emerald-700 font-black' : 'text-slate-500'}">Rp ${hargaFinalItem.toLocaleString('id-ID')} / porsi ${tipePesanan !== 'biasa' ? '<span class="text-[9px] text-blue-500 font-bold">(Ojol)</span>' : ''}</p>
                        </div>
                        ${hasItemDiscount ? `<p class="text-[9.5px] font-black text-emerald-700 mt-0.5 tabular-nums">Verifikasi Hemat: -Rp ${itemSavings.toLocaleString('id-ID')}</p>` : ''}
                    </div>
                    <div class="text-right shrink-0 tabular-nums">
                        ${hasItemDiscount ? `<span class="block text-[9.5px] text-slate-400 line-through">Rp ${subtotalAsliItem.toLocaleString('id-ID')}</span>` : ''}
                        <span class="text-xs font-black ${hasItemDiscount ? 'text-emerald-700' : 'text-blue-600'}">Rp ${subtotalItem.toLocaleString('id-ID')}</span>
                    </div>
                </div>

                <!-- Kontrol Pengatur Kuantitas & Edit di Keranjang -->
                <div class="flex flex-wrap items-center justify-between gap-2 pt-2 border-t ${hasItemDiscount ? 'border-emerald-200/70' : 'border-slate-100'}">
                    <div class="inline-flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg p-0.5 shrink-0">
                        <button onclick="ubahQtyKeranjangPOS(${i}, -1)" title="Kurangi" class="w-8 h-8 shrink-0 rounded-md bg-white hover:bg-slate-100 text-slate-700 font-bold inline-flex items-center justify-center text-xs shadow-2xs active:scale-90 transition">-</button>
                        <span class="min-w-[2rem] text-center text-xs font-black text-slate-800 tabular-nums">${item.qty}</span>
                        <button onclick="ubahQtyKeranjangPOS(${i}, 1)" title="Tambah" class="w-8 h-8 shrink-0 rounded-md bg-white hover:bg-slate-100 text-blue-600 font-bold inline-flex items-center justify-center text-xs shadow-2xs active:scale-90 transition">+</button>
                    </div>

                    <div class="inline-flex items-center gap-1.5 shrink-0">
                        <button type="button" onclick="window.bukaModalEditItemKeranjangPOS(${i})" title="Edit Varian, Topping & Porsi" class="min-h-[34px] px-2.5 py-1 bg-amber-50 hover:bg-amber-100 text-amber-800 border border-amber-300 rounded-lg inline-flex items-center justify-center gap-1.5 text-[11px] font-black transition active:scale-90 shadow-2xs cursor-pointer whitespace-nowrap">
                            <i class="fa-solid fa-pen-to-square text-[10px] text-amber-600"></i>
                            <span>Edit</span>
                        </button>
                        <button onclick="hapusDariKeranjangPOS(${i})" title="Hapus menu ini" class="w-8 h-8 bg-red-50 text-red-500 rounded-lg inline-flex items-center justify-center hover:bg-red-500 hover:text-white transition active:scale-90 shrink-0">
                            <i class="fa-solid fa-trash-can text-[11px]"></i>
                        </button>
                    </div>
                </div>
            </div>
        `;
    });

    // Hitung potongan diskon voucher jika ada yang aktif
    let diskonVoucher = 0;
    if (window.posAppliedVoucher && subtotalMurni > 0) {
        const v = window.posAppliedVoucher;
        const minOrder = Number(v.minPembelian || v.minPurchase || 0);
        if (subtotalMurni >= minOrder) {
            if (v.tipe === 'persen' || v.discountType === 'percentage') {
                diskonVoucher = Math.round(subtotalMurni * Number(v.nilai || v.discountValue || 0) / 100);
                if (v.maksPotongan && diskonVoucher > Number(v.maksPotongan)) {
                    diskonVoucher = Number(v.maksPotongan);
                }
            } else {
                diskonVoucher = Number(v.nilai || v.discountValue || 0);
            }
            diskonVoucher = Math.min(subtotalMurni, diskonVoucher);
        }
    }

    // Render kartu diskon voucher di keranjang jika ada potongan
    if (diskonVoucher > 0 && window.posAppliedVoucher) {
        wadah.innerHTML += `
            <div class="bg-emerald-50 border border-emerald-300 p-2.5 rounded-xl shadow-2xs mb-2 flex items-center justify-between gap-2 animate-fade-in">
                <div class="flex items-center gap-2 min-w-0 flex-1">
                    <span class="w-6 h-6 shrink-0 rounded-lg bg-emerald-600 text-white flex items-center justify-center text-xs font-black">
                        <i class="fa-solid fa-tag"></i>
                    </span>
                    <div class="min-w-0">
                        <h4 class="text-xs font-black text-emerald-950 truncate">Voucher: ${window.posAppliedVoucher.kode || window.posAppliedVoucher.code}</h4>
                        <p class="text-[10px] text-emerald-700 font-bold truncate">${window.posAppliedVoucher.nama || 'Potongan Diskon Kasir'}</p>
                    </div>
                </div>
                <div class="text-right shrink-0">
                    <span class="text-xs font-black text-emerald-700 whitespace-nowrap tabular-nums">- Rp ${diskonVoucher.toLocaleString('id-ID')}</span>
                    <button type="button" onclick="window.hapusVoucherPOS()" class="block ml-auto text-[9px] text-red-500 font-bold hover:underline">Hapus</button>
                </div>
            </div>
        `;
    }

    posTotalTagihan = Math.max(0, subtotalMurni - diskonVoucher);

    // Tampilkan banner verifikasi diskon di atas list keranjang POS
    const totalPotonganSemua = totalProductDiscount + diskonVoucher;
    if (verifyBanner) {
        if (totalPotonganSemua > 0) {
            const parts = [];
            if (totalProductDiscount > 0) {
                parts.push(`${discountedItemCount} porsi harga promo (-Rp ${totalProductDiscount.toLocaleString('id-ID')})`);
            }
            if (diskonVoucher > 0) {
                parts.push(`Voucher (-Rp ${diskonVoucher.toLocaleString('id-ID')})`);
            }
            if (verifyText) {
                verifyText.innerHTML = `Verifikasi Potongan: ${parts.join(' + ')} • <strong>Total Hemat Rp ${totalPotonganSemua.toLocaleString('id-ID')}</strong>`;
            }
            verifyBanner.classList.remove('hidden');
        } else {
            verifyBanner.classList.add('hidden');
        }
    }

    const posDiscWrap = document.getElementById('pos-discount-summary');
    const posSubEl = document.getElementById('pos-subtotal-val');
    const posDiscLbl = document.getElementById('pos-discount-label');
    const posDiscVal = document.getElementById('pos-discount-val');
    if (posDiscWrap) {
        if (totalPotonganSemua > 0) {
            if (posSubEl) posSubEl.innerText = "Rp " + subtotalOriginalMurni.toLocaleString('id-ID');
            if (posDiscLbl) {
                const vNamePos = window.posAppliedVoucher ? (window.posAppliedVoucher.kode || window.posAppliedVoucher.code || 'Voucher') : '';
                if (totalProductDiscount > 0 && diskonVoucher > 0) {
                    posDiscLbl.innerHTML = `<i class="fa-solid fa-tag text-[10px]"></i> Diskon Menu + ${vNamePos}:`;
                } else if (totalProductDiscount > 0) {
                    posDiscLbl.innerHTML = `<i class="fa-solid fa-tag text-[10px]"></i> Potongan Diskon Menu:`;
                } else {
                    posDiscLbl.innerHTML = `<i class="fa-solid fa-tag text-[10px]"></i> Diskon (${vNamePos}):`;
                }
            }
            if (posDiscVal) posDiscVal.innerText = `-Rp ${totalPotonganSemua.toLocaleString('id-ID')}`;
            posDiscWrap.classList.remove('hidden');
        } else {
            posDiscWrap.classList.add('hidden');
        }
    }

    const elTotal = document.getElementById('pos-total-tagihan');
    if(elTotal) elTotal.innerText = "Rp " + posTotalTagihan.toLocaleString('id-ID');
    hitungKembalian();
};

window.hitungUlangTotalKasir = () => {
    renderKeranjangPOS();
};

window.hapusDariKeranjangPOS = (index) => {
    if (posKeranjang && posKeranjang[index] !== undefined) {
        posKeranjang.splice(index, 1);
        window.simpanStateKeranjangPOS();
        renderKeranjangPOS();
    }
};

window.bukaPanelKasirManual = () => {
    if (typeof window.matikanBGM === 'function') window.matikanBGM();
    const panel = document.getElementById('panel-kasir-manual');
    if (panel) {
        if (panel._posClosingTimer) {
            clearTimeout(panel._posClosingTimer);
            panel._posClosingTimer = null;
        }
        panel.classList.remove('hidden', 'pos-panel-anim-exit', 'pos-panel-anim-enter');
        panel.classList.add('flex');
        panel.style.setProperty('display', 'flex', 'important');
        void panel.offsetWidth;
        panel.classList.add('pos-panel-anim-enter');
        
        document.documentElement.classList.add('app-pos-open');
        document.documentElement.classList.add('app-role-kasir');
        document.documentElement.classList.remove('app-role-owner');
        
        localStorage.setItem('mainstay_is_kasir_open', 'true');
        localStorage.setItem('mainstay_session_role', 'kasir');
        
        const fab = document.getElementById('fab-kasir-container');
        if (fab) {
            fab.classList.add('hidden');
            fab.classList.remove('flex');
            fab.style.setProperty('display', 'none', 'important');
        }
        const btnBgm = document.getElementById('btn-bgm');
        if (btnBgm) {
            btnBgm.classList.add('hidden');
            btnBgm.style.display = 'none';
        }
        try {
            if (typeof renderKatalogPOS === 'function') renderKatalogPOS();
            else if (typeof window.renderKatalogPOS === 'function') window.renderKatalogPOS();
        } catch(e) { console.error('Error renderKatalogPOS:', e); }
        
        if (typeof posKeranjang === 'undefined' || posKeranjang === null) {
            try {
                const savedCart = sessionStorage.getItem('mainstay_pos_keranjang');
                posKeranjang = savedCart ? JSON.parse(savedCart) : [];
            } catch(e) {
                posKeranjang = [];
            }
        }
        try {
            if (typeof renderKeranjangPOS === 'function') renderKeranjangPOS();
            else if (typeof window.renderKeranjangPOS === 'function') window.renderKeranjangPOS();
        } catch(e) { console.error('Error renderKeranjangPOS:', e); }
    }
};

window.tutupPanelKasirManual = (immediate = false) => {
    const panel = document.getElementById('panel-kasir-manual');
    if (panel) {
        if (panel._posClosingTimer) {
            clearTimeout(panel._posClosingTimer);
            panel._posClosingTimer = null;
        }
        panel.classList.remove('pos-panel-anim-enter');
        if (immediate === true || panel.classList.contains('hidden')) {
            panel.classList.add('hidden');
            panel.classList.remove('flex', 'pos-panel-anim-exit');
            panel.style.setProperty('display', 'none', 'important');
        } else {
            panel.classList.add('pos-panel-anim-exit');
            panel._posClosingTimer = setTimeout(() => {
                panel.classList.add('hidden');
                panel.classList.remove('flex', 'pos-panel-anim-exit');
                panel.style.setProperty('display', 'none', 'important');
                panel._posClosingTimer = null;
            }, 200);
        }
        
        document.documentElement.classList.remove('app-pos-open');
        localStorage.setItem('mainstay_is_kasir_open', 'false');
        
        const currentRole = localStorage.getItem('mainstay_session_role') || 'kasir';
        const fab = document.getElementById('fab-kasir-container');
        if (currentRole === 'kasir' && fab) {
            fab.classList.remove('hidden');
            fab.classList.add('flex');
            fab.style.removeProperty('display');
        } else if (fab) {
            fab.classList.add('hidden');
            fab.classList.remove('flex');
            fab.style.setProperty('display', 'none', 'important');
        }
        if (currentRole === 'customer' && typeof window.isCustomerViewActive === 'function' && window.isCustomerViewActive()) {
            window.nyalakanBGM();
        } else {
            window.matikanBGM();
        }
    }
};
globalThis.bukaPanelKasirManual = window.bukaPanelKasirManual;
globalThis.tutupPanelKasirManual = window.tutupPanelKasirManual;

window.hitungKembalian = () => {
    const inputUang = document.getElementById('pos-uang-diterima').value;
    const nominalUang = parseInt(inputUang) || 0;
    const kembalian = nominalUang - posTotalTagihan;
    const teksKembalian = document.getElementById('pos-teks-kembalian');
    if(!teksKembalian) return;

    if (posTotalTagihan === 0 || nominalUang === 0) {
        teksKembalian.innerText = "Rp 0";
        teksKembalian.className = "text-3xl font-black text-emerald-400";
    } else if (kembalian < 0) {
        teksKembalian.innerText = "Uang Kurang!";
        teksKembalian.className = "text-3xl font-black text-rose-500";
    } else {
        teksKembalian.innerText = "Rp " + kembalian.toLocaleString('id-ID');
        teksKembalian.className = "text-3xl font-black text-emerald-400";
    }
};

window.setUangCepat = (nominal) => {
    const inputUang = document.getElementById('pos-uang-diterima');
    if(!inputUang) return;
    if (nominal === 'pas') inputUang.value = posTotalTagihan;
    else if (nominal === 'clear') inputUang.value = '';
    else inputUang.value = nominal;
    hitungKembalian();
};

window.toggleSubPayPosPreorder = () => {
    const subPay = document.querySelector('input[name="pos_preorder_subpay"]:checked')?.value || 'Tunai';
    const wadahQris = document.getElementById('pos-qris-container');
    const inputUang = document.getElementById('pos-uang-diterima');
    if (subPay === 'QRIS') {
        if (wadahQris) wadahQris.classList.remove('hidden');
        if (inputUang) {
            inputUang.value = posTotalTagihan;
            inputUang.disabled = true;
        }
        if (typeof hitungKembalian === 'function') hitungKembalian();
    } else {
        if (wadahQris) wadahQris.classList.add('hidden');
        if (inputUang) inputUang.disabled = false;
    }
};

window.toggleMetodeBayarPOS = () => {
    const metodeRadio = document.querySelector('input[name="pos_metode_bayar"]:checked');
    const metode = metodeRadio ? metodeRadio.value : 'Tunai';
    const wadahQris = document.getElementById('pos-qris-container');
    const inputUang = document.getElementById('pos-uang-diterima');
    const posPreorderSec = document.getElementById('pos-preorder-container');

    if (metode === 'PreOrder') {
        if (posPreorderSec) {
            posPreorderSec.classList.remove('hidden');
            const dateInput = document.getElementById('pos-preorder-date');
            if (dateInput) {
                const today = new Date();
                const yyyy = today.getFullYear();
                const mm = String(today.getMonth() + 1).padStart(2, '0');
                const dd = String(today.getDate()).padStart(2, '0');
                const todayStr = `${yyyy}-${mm}-${dd}`;
                
                const maxDate = new Date();
                maxDate.setDate(maxDate.getDate() + 7);
                const maxYyyy = maxDate.getFullYear();
                const maxMm = String(maxDate.getMonth() + 1).padStart(2, '0');
                const maxDd = String(maxDate.getDate()).padStart(2, '0');
                const maxStr = `${maxYyyy}-${maxMm}-${maxDd}`;
                
                dateInput.min = todayStr;
                dateInput.max = maxStr;
                if (!dateInput.value || dateInput.value < todayStr || dateInput.value > maxStr) {
                    dateInput.value = todayStr;
                }
            }
        }
        window.toggleSubPayPosPreorder();
    } else {
        if (posPreorderSec) posPreorderSec.classList.add('hidden');
        if (metode === 'QRIS') {
            if (wadahQris) wadahQris.classList.remove('hidden');
            if (inputUang) {
                inputUang.value = posTotalTagihan;
                inputUang.disabled = true;
            }
            if (typeof hitungKembalian === 'function') hitungKembalian();
        } else {
            if (wadahQris) wadahQris.classList.add('hidden');
            if (inputUang) inputUang.disabled = false;
        }
    }
};

window.prosesOrderanPOS = async () => {
    if (!posKeranjang || posKeranjang.length === 0) {
        alert("Keranjang pesanan masih kosong! Silakan pilih menu terlebih dahulu.");
        return;
    }

    const inputUangEl = document.getElementById('pos-uang-diterima');
    const inputUang = inputUangEl ? inputUangEl.value : '';
    let nominalUang = parseInt(inputUang) || 0;
    const metodeBayarRadio = document.querySelector('input[name="pos_metode_bayar"]:checked');
    const metodeBayarTerpilih = metodeBayarRadio ? metodeBayarRadio.value : 'Tunai';
    const finalTotal = Number(posTotalTagihan) || 0;

    const isPosPreOrder = (metodeBayarTerpilih === 'PreOrder');
    let posPreDate = '';
    let posPreTime = '';
    let posPreSubPay = 'Tunai';

    if (isPosPreOrder) {
        const dateEl = document.getElementById('pos-preorder-date');
        const timeEl = document.getElementById('pos-preorder-time');
        const subPayEl = document.querySelector('input[name="pos_preorder_subpay"]:checked');

        posPreDate = dateEl ? dateEl.value : '';
        posPreTime = timeEl ? timeEl.value : '';
        posPreSubPay = subPayEl ? subPayEl.value : 'Tunai';

        if (!posPreDate) {
            alert("Harap tentukan tanggal pengambilan pesanan Pre-Order!");
            if (dateEl) dateEl.focus();
            return;
        }

        const todayObj = new Date();
        const todayStr = `${todayObj.getFullYear()}-${String(todayObj.getMonth() + 1).padStart(2, '0')}-${String(todayObj.getDate()).padStart(2, '0')}`;
        const maxLimit = new Date();
        maxLimit.setDate(maxLimit.getDate() + 7);
        const maxLimitStr = `${maxLimit.getFullYear()}-${String(maxLimit.getMonth() + 1).padStart(2, '0')}-${String(maxLimit.getDate()).padStart(2, '0')}`;

        if (posPreDate < todayStr) {
            alert("Tanggal pengambilan pre-order tidak boleh di masa lampau!");
            if (dateEl) dateEl.focus();
            return;
        }
        if (posPreDate > maxLimitStr) {
            alert("Tanggal pengambilan pre-order maksimal 1 minggu dari hari ini!");
            if (dateEl) dateEl.focus();
            return;
        }

        if (!posPreTime) {
            alert("Harap tentukan jam pengambilan pesanan Pre-Order!");
            if (timeEl) timeEl.focus();
            return;
        }

        // Pre-Order wajib lunas semua di awal (100%)
        if (posPreSubPay === 'QRIS' || nominalUang <= 0) {
            nominalUang = finalTotal;
            if (inputUangEl) inputUangEl.value = finalTotal;
        }
    } else {
        // Jika metode Tunai dan kasir belum mengisi nominal, otomatis dianggap Uang Pas
        if (metodeBayarTerpilih === 'Tunai' && nominalUang <= 0) {
            nominalUang = finalTotal;
            if (inputUangEl) inputUangEl.value = finalTotal;
        } else if (metodeBayarTerpilih === 'QRIS') {
            nominalUang = finalTotal;
            if (inputUangEl) inputUangEl.value = finalTotal;
        }
    }
    
    if (nominalUang < finalTotal) {
        alert("Nominal uang yang diterima masih kurang dari total tagihan! Pre-order wajib lunas 100%.");
        return;
    }

    const kembalian = Math.max(0, nominalUang - finalTotal);
    const tipePesananEl = document.getElementById('pos-tipe-pesanan');
    const tipePesanan = tipePesananEl ? tipePesananEl.value : 'biasa';
    
    // Format kode pesanan sesuai tipe: KSR, GRB, GFD, SHP, OTH (dan CSH untuk self-order)
    // 4 digit pertama DDMM, 3 digit terakhir nomor urutan masuk global harian
    const idTransaksi = typeof window.generateDailyOrderId === 'function' 
        ? window.generateDailyOrderId(isPosPreOrder ? 'preorder' : tipePesanan) 
        : ("KSR-" + Math.floor(100000 + Math.random() * 900000));
        
    const petugasAktif = String(localStorage.getItem('mainstay_staff_name') || "Owner").replace(/\s*\(\s*master\s*\)/i, '').trim() || "Owner";

    // --- AMBIL DATA DARI FORM KASIR ---
    const inputNama = (document.getElementById('pos-nama')?.value || '').trim();
    const inputWa = (document.getElementById('pos-wa')?.value || '').trim();
    const isMemberCheck = document.getElementById('pos-member')?.checked || false;

    if (isPosPreOrder) {
        if (!inputNama || inputNama.length < 2 || inputNama.toLowerCase() === 'hamba allah') {
            alert("Pesanan Pre-Order WAJIB menyertakan Nama Pelanggan yang jelas!");
            document.getElementById('pos-nama')?.focus();
            return;
        }
        if (!inputWa || inputWa.replace(/\D/g, '').length < 8) {
            alert("Pesanan Pre-Order WAJIB menyertakan Nomor WhatsApp aktif pelanggan!");
            document.getElementById('pos-wa')?.focus();
            return;
        }
    }

    // Jika nama kosong (pada order biasa), gunakan "Hamba Allah"
    const namaPelangganFinal = inputNama ? inputNama : "Hamba Allah";

    const formattedItems = (posKeranjang || []).map(item => {
        let cleanName = String(item.nama || item.name || 'Menu').trim();
        while (/\s*\(([^)]+)\)\s*$/.test(cleanName)) {
            cleanName = cleanName.replace(/\s*\(([^)]+)\)\s*$/, '').trim();
        }
        let cleanVarian = String(item.varian || item.notes || '').trim();
        if (cleanVarian.toLowerCase() === 'normal ice' || cleanVarian.toLowerCase() === 'normal') {
            cleanVarian = 'Normal Ice';
        }
        const rawKey = item.rawMenuKey || (item.key && item.key.includes('_') ? item.key.split('_')[0] : item.key) || item.id || '';
        return {
            key: item.key || item.id || '',
            id: rawKey || item.key || item.id || '',
            rawMenuKey: rawKey,
            nama: cleanName,
            name: cleanName,
            harga: Number(item.harga || item.price || 0),
            price: Number(item.harga || item.price || 0),
            qty: Number(item.qty) || 1,
            varian: cleanVarian || 'Normal',
            notes: cleanVarian || 'Normal',
            toppings: Array.isArray(item.toppings) ? item.toppings : []
        };
    });

    const now = new Date();
    const nowTimeStr = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }).replace(/:/g, '.');
    const nowDateStr = now.toLocaleDateString('id-ID');
    const nowTimestamp = Date.now();

    const subtotalPosKotor = formattedItems.reduce((acc, it) => acc + (it.harga * it.qty), 0);
    const diskonPosNominal = window.posAppliedVoucher ? Math.max(0, subtotalPosKotor - finalTotal) : 0;

    const isPosPreConfirmed = Boolean(document.getElementById('pos-preorder-confirmed')?.checked);
    const posMejaVal = String(window.posActiveTable || document.getElementById('pos-meja-input')?.value || '').trim().toUpperCase();

    const transaksiBaru = {
        id: idTransaksi,
        orderId: idTransaksi,
        waktu: nowTimeStr,
        tanggal: nowDateStr,
        timestamp: nowTimestamp,
        namaPelanggan: namaPelangganFinal,
        customerName: namaPelangganFinal,
        nomorWa: inputWa || '-',
        customerPhone: inputWa || '-',
        ...(posMejaVal ? { nomorMeja: posMejaVal, table: posMejaVal } : {}),
        isMember: isMemberCheck,
        voucher: window.posAppliedVoucher ? (window.posAppliedVoucher.kode || window.posAppliedVoucher.code) : null,
        diskonVoucher: diskonPosNominal,
        subtotal: subtotalPosKotor,
        items: formattedItems,
        total: finalTotal,
        totalAmount: finalTotal,
        bayar: nominalUang,
        kembalian: kembalian,
        metode: isPosPreOrder ? `PreOrder (${posPreSubPay})` : metodeBayarTerpilih,
        paymentMethod: isPosPreOrder ? `PreOrder (${posPreSubPay})` : metodeBayarTerpilih,
        tipePesanan: isPosPreOrder ? 'preorder' : tipePesanan,
        channel: isPosPreOrder ? 'preorder' : tipePesanan,
        kasir: petugasAktif,
        status: isPosPreOrder ? "preorder" : "pending",
        isPreOrder: isPosPreOrder,
        pickupDate: posPreDate,
        pickupTime: posPreTime,
        preOrderSubPay: posPreSubPay,
        isPaid: isPosPreOrder ? isPosPreConfirmed : true,
        paymentStatus: isPosPreOrder ? (isPosPreConfirmed ? 'lunas' : 'menunggu_konfirmasi') : 'lunas',
        preOrderPaymentConfirmed: isPosPreOrder ? isPosPreConfirmed : true,
        stockDeducted: false
    };

    // =========================================================================
    // 1. SIMPAN LANGSUNG KE MEMORI GLOBAL KASIR & LOCALSTORAGE (INSTAN & SEKETIKA)
    // =========================================================================
    if (typeof globalOrders !== 'undefined') {
        globalOrders[idTransaksi] = transaksiBaru;
        window._latestOrdersSnapshot = globalOrders;
    }
    if (typeof window.globalOrders === 'object') {
        window.globalOrders[idTransaksi] = transaksiBaru;
    }

    try {
        let savedOrders = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (!Array.isArray(savedOrders)) savedOrders = [];
        savedOrders = savedOrders.filter(o => (o.orderId || o.id) !== idTransaksi);
        savedOrders.unshift(transaksiBaru);
        localStorage.setItem('mainstay_offline_orders', JSON.stringify(savedOrders));
    } catch (e) {}

    // Reset keranjang POS & Form input
    posKeranjang = [];
    try {
        sessionStorage.removeItem('mainstay_pos_keranjang');
    } catch(e) {}

    // Reset Voucher & Member Scanned POS
    window.posAppliedVoucher = null;
    window.posScannedMember = null;
    const posScannedCard = document.getElementById('pos-scanned-member-card');
    if (posScannedCard) { posScannedCard.classList.add('hidden'); posScannedCard.innerHTML = ''; }
    const posVocBanner = document.getElementById('pos-active-voucher-banner');
    if (posVocBanner) { posVocBanner.classList.add('hidden'); posVocBanner.innerHTML = ''; }

    if (typeof renderKeranjangPOS === 'function') renderKeranjangPOS();
    if (inputUangEl) inputUangEl.value = '';
    if (document.getElementById('pos-nama')) document.getElementById('pos-nama').value = '';
    if (document.getElementById('pos-wa')) document.getElementById('pos-wa').value = '';
    if (typeof window.setPosActiveTable === 'function') window.setPosActiveTable('');
    if (document.getElementById('pos-preorder-confirmed')) document.getElementById('pos-preorder-confirmed').checked = false;

    // Tutup panel form POS kasir manual
    if (typeof window.tutupPanelKasirManual === 'function') {
        window.tutupPanelKasirManual();
    }

    // =========================================================================
    // 2. AKTIFKAN TAMPILAN KASIR & ARAHKAN KE DAFTAR PRE-ORDER / TAB PENDING
    // =========================================================================
    if (isPosPreOrder) {
        if (typeof window.switchRoleView === 'function') {
            window.switchRoleView('kasir');
        }
        if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
        if (typeof window.renderDaftarPreOrder === 'function') window.renderDaftarPreOrder();
        if (typeof window.bukaModalDaftarPreOrder === 'function') window.bukaModalDaftarPreOrder();
        if (typeof window.showNotification === 'function') {
            window.showNotification(`Pesanan Pre-Order ${idTransaksi} berhasil dijadwalkan untuk ${posPreDate} pukul ${posPreTime} WIB (Lunas 100%).`, 'success');
        }
    } else {
        if (typeof window.switchRoleView === 'function') {
            window.switchRoleView('kasir');
        }
        if (typeof window.switchKasirTab === 'function') {
            window.switchKasirTab('tab-pending');
        }

        // Render ulang seluruh komponen UI antrean 4 tab & kas laci
        if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
        if (typeof window.updateLiveCashDrawer === 'function') window.updateLiveCashDrawer();
        if (typeof window.renderOrders === 'function') window.renderOrders();
        if (typeof window.loadOrders === 'function') window.loadOrders();
        if (typeof window.updateOwnerDashboard === 'function') window.updateOwnerDashboard();

        // Registrasi ID pesanan ke Set notifikasi agar tidak memicu double notif saat sync/echo Firebase
        window._notifiedOrderIds = window._notifiedOrderIds || new Set();
        window._notifiedToastOrderIds = window._notifiedToastOrderIds || new Set();
        window._notifiedOrderIds.add(idTransaksi);
        window._notifiedToastOrderIds.add(idTransaksi);

        // Tampilkan notifikasi toast pesanan baru
        if (typeof window.tampilkanToastPesananBaru === 'function') {
            window.tampilkanToastPesananBaru({
                nama_pelanggan: namaPelangganFinal,
                total: finalTotal,
                nomor_antrean: idTransaksi,
                orderId: idTransaksi,
                tipePesanan: tipePesanan,
                status: 'Pending'
            }, true);
        }
    }

    // =========================================================================
    // 3. SINKRONISASI MEMBER & FIREBASE DI BACKGROUND
    // (Pengurangan stok gudang otomatis dipicu real-time saat status order menjadi 'selesai')
    // =========================================================================
    (async () => {

        const rawPhone = String(inputWa || '').trim();
        const cleanDigits = rawPhone.replace(/\D/g, '');
        let standardPhone = cleanDigits;
        if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);
        let memberPayload = null;
        let nonMemberPayload = null;
        if (standardPhone.length >= 8) {
            const existingMember = (window.cachedMembers && (window.cachedMembers[standardPhone] || window.cachedMembers[cleanDigits])) || (window.posScannedMember);
            if (existingMember || isMemberCheck) {
                const claimedPoints = (formattedItems || []).filter(i => i.isLoyaltyReward).reduce((sum, item) => sum + (Number(item.costPoints) || (Number(item.costSessions || 1) * 10)), 0);
                const prevPoints = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(existingMember) : 0;
                const remainingPoints = Math.max(0, prevPoints - claimedPoints);
                const earnedPoints = 5; // Dapatkan 5 Points setiap pesanan
                const newPoints = remainingPoints + earnedPoints;

                memberPayload = {
                    phone: standardPhone,
                    name: namaPelangganFinal,
                    points: newPoints,
                    poin: newPoints,
                    totalOrders: Number(existingMember?.totalOrders || 0) + 1,
                    totalSpent: Number(existingMember?.totalSpent || 0) + finalTotal,
                    lastActive: Date.now(),
                    registeredAt: existingMember?.registeredAt || Date.now(),
                    waGroupJoined: existingMember?.waGroupJoined !== false,
                    vouchers: existingMember?.vouchers || {}
                };

                // Update memori cache lokal agar kasir offline tetap melihat update poin seketika
                if (window.cachedMembers) {
                    window.cachedMembers[standardPhone] = memberPayload;
                }
            } else if (inputNama && inputNama.length >= 2 && inputNama.toLowerCase() !== 'hamba allah') {
                // Pelanggan di Kasir/PreOrder mencantumkan Nama & No. WA tanpa daftar member -> simpan ke Non-Member
                const prevNonMember = (window.cachedNonMembers && (window.cachedNonMembers[standardPhone] || window.cachedNonMembers[cleanDigits])) || {};
                nonMemberPayload = {
                    id: standardPhone,
                    phone: standardPhone,
                    name: namaPelangganFinal,
                    totalOrders: Number(prevNonMember.totalOrders || 0) + 1,
                    totalSpent: Number(prevNonMember.totalSpent || 0) + finalTotal,
                    firstSeen: prevNonMember.firstSeen || Date.now(),
                    lastOrderDate: Date.now(),
                    lastActive: Date.now(),
                    lastChannel: isPosPreOrder ? 'PreOrder POS' : (tipePesanan || 'Kasir POS'),
                    isMember: false,
                    vouchers: prevNonMember.vouchers || {}
                };
                if (!window.cachedNonMembers) window.cachedNonMembers = {};
                window.cachedNonMembers[standardPhone] = nonMemberPayload;
                globalNonMembers = window.cachedNonMembers;
            }
        }

        // Jika koneksi sedang offline, langsung masukkan ke antrean posSyncEngine
        if (!navigator.onLine) {
            transaksiBaru.isOffline = true;
            transaksiBaru.synced = false;
            window.posSyncEngine.enqueue('order', transaksiBaru, {
                memberPhone: memberPayload ? standardPhone : '',
                memberPayload,
                nonMemberPhone: nonMemberPayload ? standardPhone : '',
                nonMemberPayload
            });
            console.log(`[POS Offline Mode] Transaksi ${idTransaksi} disimpan lokal & masuk antrean sinkronisasi.`);
            return;
        }

        try {
            // Sinkronisasi otomatis ke Firestore & RTDB setiap kali online
            if (typeof window.sinkronisasiOrderKeFirestore === 'function') {
                await window.sinkronisasiOrderKeFirestore(transaksiBaru).catch(() => {});
            }
            const orderPushRef = await push(ref(db, 'orders'), transaksiBaru);
            const orderFirebaseKey = orderPushRef?.key;
            if (orderFirebaseKey) {
                transaksiBaru.firebaseKey = orderFirebaseKey;
                transaksiBaru.synced = true;
                globalOrders[orderFirebaseKey] = transaksiBaru;
                if (orderFirebaseKey !== idTransaksi) {
                    delete globalOrders[idTransaksi];
                }
                try {
                    let saved = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
                    saved = saved.map(o => (o.orderId === idTransaksi || o.id === idTransaksi ? { ...o, firebaseKey: orderFirebaseKey, synced: true } : o));
                    localStorage.setItem('mainstay_offline_orders', JSON.stringify(saved));
                } catch (e) {}
                if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
            }
            await push(ref(db, 'transaksi'), transaksiBaru);

            // Update data member atau non-member di cloud jika ada
            if (memberPayload && standardPhone) {
                await update(ref(db, `members/${standardPhone}`), memberPayload);
                if (window.cachedNonMembers && (window.cachedNonMembers[standardPhone] || window.cachedNonMembers[cleanDigits])) {
                    await remove(ref(db, `non_members/${standardPhone}`)).catch(() => {});
                    delete window.cachedNonMembers[standardPhone];
                }
            } else if (nonMemberPayload && standardPhone) {
                await update(ref(db, `non_members/${standardPhone}`), nonMemberPayload);
            }
        } catch (fbErr) {
            console.warn("Gagal simpan online, mengalihkan ke antrean sync offline:", fbErr);
            transaksiBaru.isOffline = true;
            transaksiBaru.synced = false;
            window.posSyncEngine.enqueue('order', transaksiBaru, {
                memberPhone: memberPayload ? standardPhone : '',
                memberPayload,
                nonMemberPhone: nonMemberPayload ? standardPhone : '',
                nonMemberPayload
            });
        }
    })();
};

