window.tambahLogVoicePOS = (rawTranscript, status, detailText, parsedMenu = null, qty = 1) => {
    const waktu = new Date();
    const jam = String(waktu.getHours()).padStart(2, '0');
    const menit = String(waktu.getMinutes()).padStart(2, '0');
    const detik = String(waktu.getSeconds()).padStart(2, '0');
    const timestampStr = `${jam}:${menit}:${detik}`;

    const entry = {
        id: 'vlog_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
        time: timestampStr,
        raw: rawTranscript,
        status: status, // 'success' | 'error'
        detail: detailText,
        menu: parsedMenu,
        qty: qty
    };

    window.posVoiceCommandLogs.unshift(entry);
    if (window.posVoiceCommandLogs.length > 40) {
        window.posVoiceCommandLogs.pop();
    }

    window.renderLogVoicePOS();
};

window.renderLogVoicePOS = () => {
    const container = document.getElementById('pos-voice-transcript-list');
    const badgeCount = document.getElementById('pos-voice-log-count');
    if (badgeCount) {
        badgeCount.innerText = `${window.posVoiceCommandLogs.length} Perintah`;
    }
    if (!container) return;

    if (window.posVoiceCommandLogs.length === 0) {
        container.innerHTML = `
            <div class="p-3 text-center bg-slate-50 border border-dashed border-slate-200 rounded-xl">
                <p class="text-[11px] text-slate-400 font-medium">Belum ada riwayat perintah suara. Tekan tombol <strong class="text-slate-600">Voice Order</strong> di atas untuk memesan.</p>
            </div>
        `;
        return;
    }

    container.innerHTML = window.posVoiceCommandLogs.map(item => {
        const isSuccess = item.status === 'success';
        const escapedRaw = (item.raw || '').replace(/'/g, "\\'");
        return `
            <div class="p-2.5 rounded-xl border ${isSuccess ? 'bg-emerald-50/60 border-emerald-200/80' : 'bg-rose-50/60 border-rose-200/80'} flex items-start justify-between gap-2 transition hover:shadow-2xs">
                <div class="min-w-0 flex-1">
                    <div class="flex items-center gap-1.5 flex-wrap mb-0.5">
                        <span class="text-[9px] font-black font-mono text-slate-500">${item.time}</span>
                        <span class="text-[9px] font-black px-1.5 py-0.2 rounded-md ${isSuccess ? 'bg-emerald-600 text-white' : 'bg-rose-600 text-white'}">
                            ${isSuccess ? 'TERDETEKSI' : 'GAGAL'}
                        </span>
                        <span class="text-[10px] font-bold italic text-slate-800 truncate max-w-[180px]">
                            "${item.raw}"
                        </span>
                    </div>
                    <p class="text-[10px] ${isSuccess ? 'text-emerald-800 font-black' : 'text-rose-700 font-bold'}">
                        ${item.detail}
                    </p>
                </div>
                <button type="button" onclick="window.eksekusiChipVoiceCommand('${escapedRaw}')" class="shrink-0 px-2 py-1 rounded-lg text-[10px] font-bold ${isSuccess ? 'bg-emerald-100 hover:bg-emerald-200 text-emerald-800' : 'bg-rose-100 hover:bg-rose-200 text-rose-800'} transition active:scale-90" title="Ulangi perintah suara ini">
                    <i class="fa-solid fa-rotate-right text-[9px] mr-1"></i> Ulang
                </button>
            </div>
        `;
    }).join('');
};

