window.hentikanVoiceCommandPOS = () => {
    if (posVoiceRecognition) {
        try {
            posVoiceRecognition.stop();
        } catch (e) {}
        posVoiceRecognition = null;
    }
    isPosVoiceListening = false;

    const banner = document.getElementById('pos-voice-cmd-banner');
    if (banner) banner.classList.add('hidden');

    const btn = document.getElementById('btn-pos-voice-cmd');
    if (btn) {
        btn.classList.remove('ring-4', 'ring-rose-400', 'animate-pulse');
    }
    const icon = document.getElementById('icon-pos-voice-cmd');
    if (icon) icon.className = "fa-solid fa-microphone text-sm";
    const label = document.getElementById('label-pos-voice-cmd');
    if (label) label.innerText = "Voice Order";

    // Update Modal
    const modalBtnMic = document.getElementById('modal-btn-mic');
    if (modalBtnMic) {
        modalBtnMic.className = "w-14 h-14 rounded-full bg-gradient-to-tr from-rose-500 to-amber-500 text-white flex items-center justify-center text-xl shadow-lg transition active:scale-95 hover:scale-105 cursor-pointer";
    }
    const modalVoiceRing = document.getElementById('modal-voice-ring');
    if (modalVoiceRing) {
        modalVoiceRing.classList.remove('animate-ping', 'bg-rose-500/30');
        modalVoiceRing.classList.add('bg-rose-500/10');
    }
    const modalActionBtn = document.getElementById('modal-voice-toggle-action');
    if (modalActionBtn) {
        modalActionBtn.innerText = "Mulai Rekam Suara";
        modalActionBtn.className = "px-4 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-black transition active:scale-95 shadow-xs";
    }
    const modalStatus = document.getElementById('modal-voice-status');
    if (modalStatus) {
        modalStatus.innerText = "Mikrofon Berhenti. Tekan untuk bicara kembali.";
    }
};

window.mulaiVoiceCommandPOS = async () => {
    const SpeechRecognitionClass = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognitionClass) {
        alert("Browser ini belum mendukung Web Speech Recognition API secara native. Anda tetap dapat menggunakan Tombol Contoh Suara atau Uji Teks Suara di Asisten!");
        window.bukaModalVoiceHelpPOS();
        return;
    }

    // Permintaan Izin MediaDevices Eksplisit (Pencegahan 'not-allowed' di browser modern)
    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        try {
            const micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            micStream.getTracks().forEach(track => track.stop());
        } catch (permErr) {
            console.warn("Izin mikrofon terhalang:", permErr);
            alert("Akses mikrofon terhalang oleh pengaturan browser atau iframe. Membuka panel contoh perintah suara untuk pengujian langsung.");
            window.bukaModalVoiceHelpPOS();
            return;
        }
    }

    try {
        if (posVoiceRecognition) {
            try { posVoiceRecognition.stop(); } catch (e) {}
            posVoiceRecognition = null;
        }

        posVoiceRecognition = new SpeechRecognitionClass();
        posVoiceRecognition.continuous = false;
        posVoiceRecognition.interimResults = true;
        posVoiceRecognition.lang = window.currentVoiceLang || 'id-ID';
        posVoiceRecognition.maxAlternatives = 3;

        const banner = document.getElementById('pos-voice-cmd-banner');
        if (banner) banner.classList.remove('hidden');

        const statusText = document.getElementById('pos-voice-status-text');
        if (statusText) {
            statusText.className = "text-xs font-black text-rose-300 leading-tight";
            statusText.innerText = "Mendengarkan suara kasir...";
        }

        const transcriptEl = document.getElementById('pos-voice-transcript');
        if (transcriptEl) transcriptEl.innerText = 'Katakan contoh: "Add two Iced Americano" atau "Pesan dua Kopi Susu"';

        const btn = document.getElementById('btn-pos-voice-cmd');
        if (btn) {
            btn.classList.add('ring-4', 'ring-rose-400', 'animate-pulse');
        }
        const icon = document.getElementById('icon-pos-voice-cmd');
        if (icon) icon.className = "fa-solid fa-microphone-lines text-sm animate-bounce text-amber-200";
        const label = document.getElementById('label-pos-voice-cmd');
        if (label) label.innerText = "Mendengarkan...";

        // Update Modal elements
        const modalVoiceRing = document.getElementById('modal-voice-ring');
        if (modalVoiceRing) {
            modalVoiceRing.classList.add('animate-ping', 'bg-rose-500/30');
            modalVoiceRing.classList.remove('bg-rose-500/10');
        }
        const modalActionBtn = document.getElementById('modal-voice-toggle-action');
        if (modalActionBtn) {
            modalActionBtn.innerText = "Hentikan Rekam";
            modalActionBtn.className = "px-4 py-1.5 rounded-xl bg-rose-600 hover:bg-rose-700 text-white text-xs font-black transition active:scale-95 shadow-xs animate-pulse";
        }
        const modalStatus = document.getElementById('modal-voice-status');
        if (modalStatus) {
            modalStatus.innerText = "Mendengarkan... Silakan sebutkan pesanan Anda!";
        }

        let lastRecognizedSpeech = '';
        let hasProcessedThisTurn = false;

        posVoiceRecognition.onstart = () => {
            isPosVoiceListening = true;
            lastRecognizedSpeech = '';
            hasProcessedThisTurn = false;
        };

        posVoiceRecognition.onresult = (event) => {
            let interimTranscript = '';
            let finalTranscript = '';

            for (let i = event.resultIndex; i < event.results.length; ++i) {
                if (event.results[i].isFinal) {
                    finalTranscript += event.results[i][0].transcript;
                } else {
                    interimTranscript += event.results[i][0].transcript;
                }
            }

            const spoken = (finalTranscript || interimTranscript).trim();
            if (spoken) {
                lastRecognizedSpeech = spoken;
                if (transcriptEl) transcriptEl.innerText = `"${spoken}"`;
                const modalTranscript = document.getElementById('modal-voice-transcript');
                if (modalTranscript) modalTranscript.innerText = `"${spoken}"`;
            }

            if (finalTranscript && !hasProcessedThisTurn) {
                hasProcessedThisTurn = true;
                window.prosesPerintahSuaraPOS(finalTranscript);
            }
        };

        posVoiceRecognition.onerror = (event) => {
            console.warn("Speech recognition error:", event.error);
            if (event.error === 'not-allowed') {
                alert("Izin mikrofon belum aktif atau diblokir browser. Anda dapat menggunakan chip contoh suara atau simulasi teks di asisten!");
                window.bukaModalVoiceHelpPOS();
            }
            window.hentikanVoiceCommandPOS();
        };

        posVoiceRecognition.onend = () => {
            isPosVoiceListening = false;
            // Fallback: Jika ada suara terdeteksi tapi belum sempat di-flag isFinal oleh browser
            if (!hasProcessedThisTurn && lastRecognizedSpeech) {
                hasProcessedThisTurn = true;
                window.prosesPerintahSuaraPOS(lastRecognizedSpeech);
            }
            setTimeout(() => {
                if (!isPosVoiceListening) {
                    window.hentikanVoiceCommandPOS();
                }
            }, 2000);
        };

        posVoiceRecognition.start();
    } catch (err) {
        console.error("Gagal memulai speech recognition:", err);
        window.bukaModalVoiceHelpPOS();
        window.hentikanVoiceCommandPOS();
    }
};

window.prosesPerintahSuaraPOS = (spokenText) => {
    if (!spokenText || typeof spokenText !== 'string') return;
    const raw = spokenText.trim();
    if (!raw) return;

    console.log("[POS Voice Command Input]:", raw);

    const banner = document.getElementById('pos-voice-cmd-banner');
    const statusText = document.getElementById('pos-voice-status-text');
    const transcriptEl = document.getElementById('pos-voice-transcript');
    const modalTranscript = document.getElementById('modal-voice-transcript');
    const modalStatus = document.getElementById('modal-voice-status');

    if (banner) banner.classList.remove('hidden');
    if (transcriptEl) transcriptEl.innerText = `"${raw}"`;
    if (modalTranscript) modalTranscript.innerText = `"${raw}"`;

    let textLower = raw.toLowerCase();

    // 1. Ekstrak Kuantitas (Qty) Bilingual (ID & EN)
    const wordNumbers = {
        'sebuah': 1, 'segelas': 1, 'secangkir': 1, 'seporsi': 1, 'satu': 1, 'one': 1, 'a': 1, 'an': 1,
        'dua': 2, 'two': 2,
        'tiga': 3, 'three': 3,
        'empat': 4, 'four': 4,
        'lima': 5, 'five': 5,
        'enam': 6, 'six': 6,
        'tujuh': 7, 'seven': 7,
        'delapan': 8, 'eight': 8,
        'sembilan': 9, 'nine': 9,
        'sepuluh': 10, 'ten': 10
    };

    let qty = 1;

    // Cek angka numerik (1, 2, 3...)
    const numMatch = textLower.match(/\b(\d+)\b/);
    if (numMatch) {
        qty = Math.max(1, parseInt(numMatch[1], 10));
        textLower = textLower.replace(numMatch[0], ' ');
    } else {
        // Cek kata angka
        for (const [word, val] of Object.entries(wordNumbers)) {
            const wordRegex = new RegExp(`\\b${word}\\b`, 'i');
            if (wordRegex.test(textLower)) {
                qty = val;
                textLower = textLower.replace(wordRegex, ' ');
                break;
            }
        }
    }

    // 2. Bersihkan kata-kata perintah / pengantar bilingual
    const stopwords = [
        'add', 'tambah', 'tambahkan', 'order', 'pesan', 'pesankan',
        'beli', 'belikan', 'masukkan', 'input', 'tolong', 'please',
        'can i get', 'give me', 'i want', 'minta', 'mau',
        'cup', 'cups', 'gelas', 'cangkir', 'botol', 'porsi', 'menu', 'item'
    ];
    stopwords.forEach(sw => {
        const swRegex = new RegExp(`\\b${sw}\\b`, 'gi');
        textLower = textLower.replace(swRegex, ' ');
    });

    const targetQuery = textLower.replace(/[^a-z0-9\s]/gi, ' ').replace(/\s+/g, ' ').trim();

    if (!targetQuery) {
        const errMsg = "Sebutkan nama menu kedai (Contoh: 'Add two Iced Americano')";
        if (statusText) {
            statusText.className = "text-xs font-black text-amber-300 leading-tight";
            statusText.innerText = errMsg;
        }
        if (modalStatus) {
            modalStatus.innerText = errMsg;
        }
        window.tambahLogVoicePOS(raw, 'error', 'Perintah tidak mengandung nama menu');
        window.playScannerBeep('error');
        return;
    }

    // 3. Cari Menu yang Paling Cocok di Database (globalMenus, window.globalMenus, dummyCatalog, atau default catalog)
    let menus = {};
    if (typeof globalMenus === 'object' && globalMenus && Object.keys(globalMenus).length > 0) {
        menus = { ...globalMenus };
    }
    if (window.globalMenus && typeof window.globalMenus === 'object' && Object.keys(window.globalMenus).length > 0) {
        menus = { ...menus, ...window.globalMenus };
    }
    if (typeof dummyCatalog === 'object' && dummyCatalog && Object.keys(dummyCatalog).length > 0) {
        menus = { ...dummyCatalog, ...menus };
    }
    if (typeof DEFAULT_MAINSTAY_CATALOG === 'object' && DEFAULT_MAINSTAY_CATALOG) {
        menus = { ...DEFAULT_MAINSTAY_CATALOG, ...menus };
    }

    let bestMatch = null;
    let highestScore = 0;

    const queryTokens = targetQuery.split(' ').filter(t => t.length > 1);

    Object.entries(menus).forEach(([menuKey, menu]) => {
        if (!menu) return;
        const menuName = String(menu.nama || menu.name || '').toLowerCase();
        if (!menuName) return;

        let score = 0;
        const cleanMenuName = menuName.replace(/[^a-z0-9\s]/gi, ' ').replace(/\s+/g, ' ').trim();
        const menuTokens = cleanMenuName.split(' ').filter(t => t.length > 1);

        // A. Match sempurna atau substring
        if (cleanMenuName === targetQuery) {
            score = 100;
        } else if (cleanMenuName.includes(targetQuery)) {
            score = 88;
        } else if (targetQuery.includes(cleanMenuName)) {
            score = 85;
        } else {
            // B. Token overlap
            let matchedTokens = 0;
            queryTokens.forEach(qt => {
                if (menuTokens.some(mt => mt.includes(qt) || qt.includes(mt))) {
                    matchedTokens++;
                }
            });
            if (matchedTokens > 0) {
                score = (matchedTokens / Math.max(queryTokens.length, menuTokens.length)) * 75;
            }
        }

        // C. Khusus menu populer & variasi sebutan bilingual / fonetik
        if ((targetQuery.includes('americano') || targetQuery.includes('amerikano')) && cleanMenuName.includes('americano')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('thai tea') || targetQuery.includes('tai ti') || targetQuery.includes('teh thai') || targetQuery.includes('thai')) && cleanMenuName.includes('thai tea')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('taro') || targetQuery.includes('talas')) && cleanMenuName.includes('taro')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('vanilla') || targetQuery.includes('vanila')) && cleanMenuName.includes('vanilla')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('pukis') || targetQuery.includes('pokis')) && cleanMenuName.includes('pukis')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('kopi susu') || targetQuery.includes('kopsu') || targetQuery.includes('kopi aren')) && cleanMenuName.includes('kopi susu')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('es teh') || targetQuery.includes('teh solo') || targetQuery.includes('es teh jumbo')) && cleanMenuName.includes('es teh')) {
            score = Math.max(score, 95);
        }
        if ((targetQuery.includes('matcha') || targetQuery.includes('maca') || targetQuery.includes('green tea')) && cleanMenuName.includes('matcha')) {
            score = Math.max(score, 95);
        }

        if (score > highestScore) {
            highestScore = score;
            bestMatch = { key: menuKey, menu: menu };
        }
    });

    // Ambang batas kecocokan minimum (35%)
    if (bestMatch && highestScore >= 35) {
        const m = bestMatch.menu;
        const key = bestMatch.key;
        const namaMenu = m.nama || m.name || 'Menu';
        const harga = Number(m.harga || m.price || 0);

        // Masukkan ke keranjang POS Kasir
        const cartKey = `${key}_Standard`;
        window.tambahKeKeranjangPOS(cartKey, namaMenu, harga, "Standard", qty, key, []);
        window.playScannerBeep('success');

        const successDetail = `+${qty}x ${namaMenu} (Rp ${(harga * qty).toLocaleString('id-ID')}) masuk ke keranjang`;
        window.tambahLogVoicePOS(raw, 'success', successDetail, namaMenu, qty);

        if (statusText) {
            statusText.className = "text-xs font-black text-emerald-300 leading-tight";
            statusText.innerText = `✅ Berhasil Tambah: ${qty}x ${namaMenu}`;
        }
        if (transcriptEl) {
            transcriptEl.innerText = `Total: Rp ${(harga * qty).toLocaleString('id-ID')} masuk ke keranjang POS`;
        }
        if (modalStatus) {
            modalStatus.innerText = `✅ Berhasil! +${qty}x ${namaMenu} dimasukkan ke keranjang`;
        }

        // Tampilkan floating toast
        const toast = document.createElement('div');
        toast.className = "fixed top-6 right-6 z-[9999] bg-gradient-to-r from-emerald-600 to-teal-700 text-white px-4 py-3 rounded-2xl shadow-2xl flex items-center gap-3 border border-emerald-400 animate-bounce";
        toast.innerHTML = `
            <div class="w-8 h-8 rounded-xl bg-white/20 flex items-center justify-center text-sm font-black shrink-0">
                <i class="fa-solid fa-microphone"></i>
            </div>
            <div>
                <p class="text-xs font-black">Voice Order Terdeteksi!</p>
                <p class="text-[10px] text-emerald-100">+${qty}x ${namaMenu} (Rp ${(harga * qty).toLocaleString('id-ID')})</p>
            </div>
        `;
        document.body.appendChild(toast);
        setTimeout(() => toast?.remove(), 4000);
    } else {
        window.playScannerBeep('error');
        const errDetail = `Menu "${targetQuery}" tidak cocok dengan katalog kedai`;
        window.tambahLogVoicePOS(raw, 'error', errDetail);

        if (statusText) {
            statusText.className = "text-xs font-black text-rose-300 leading-tight";
            statusText.innerText = `⚠️ Menu "${targetQuery}" tidak ditemukan`;
        }
        if (transcriptEl) {
            transcriptEl.innerText = "Coba sebutkan menu yang tertera di kedai (Cth: 'Add two Iced Americano')";
        }
        if (modalStatus) {
            modalStatus.innerText = `⚠️ Menu "${targetQuery}" tidak ditemukan di sistem`;
        }
    }
};

