// Tutup Modal Scanner POS & Matikan Kamera
window.tutupModalScannerPOS = async () => {
    await window.stopKameraScannerPOS();
    window.isCustomerScanner = false;
    const modal = document.getElementById('modal-scanner-pos');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

// Nyalakan Kamera Pemindai QR Html5Qrcode
window.mulaiKameraScannerPOS = async () => {
    if (isPosScannerRunning) {
        await window.stopKameraScannerPOS();
    }
    const readerEl = document.getElementById('pos-qr-reader');
    if (!readerEl) return;

    const Html5QrcodeClass = window.Html5Qrcode || (typeof window.ensureHtml5QrcodeLoaded === 'function' ? await window.ensureHtml5QrcodeLoaded() : null);
    if (!Html5QrcodeClass) {
        console.warn("Html5Qrcode library tidak ditemukan.");
        const statusEl = document.getElementById('pos-scanner-status');
        if (statusEl) {
            statusEl.className = "text-xs font-bold text-amber-400 text-center mt-3 max-w-xs px-2";
            statusEl.innerText = "Library pemindai tidak termuat. Gunakan input manual nomor/kode di bawah.";
        }
        return;
    }

    try {
        posHtml5QrScanner = new Html5QrcodeClass("pos-qr-reader");
        const qrConfig = {
            fps: 15,
            qrbox: (viewfinderWidth, viewfinderHeight) => {
                const minEdge = Math.min(viewfinderWidth, viewfinderHeight);
                const qrboxSize = Math.max(180, Math.floor(minEdge * 0.75));
                return { width: qrboxSize, height: qrboxSize };
            },
            aspectRatio: 1.0
        };

        await posHtml5QrScanner.start(
            { facingMode: posScannerFacingMode },
            qrConfig,
            (decodedText) => {
                window.prosesHasilScanPOS(decodedText);
            },
            () => {
                // Polling frames
            }
        );
        isPosScannerRunning = true;
        const statusEl = document.getElementById('pos-scanner-status');
        if (statusEl) {
            statusEl.className = "text-xs font-bold text-emerald-400 text-center mt-3 max-w-xs px-2";
            statusEl.innerText = "🟢 Kamera aktif. Arahkan ke QR Member, Produk, Meja, atau Voucher.";
        }
    } catch (err) {
        console.warn("Gagal membuka kamera scanner POS:", err);
        isPosScannerRunning = false;
        const statusEl = document.getElementById('pos-scanner-status');
        if (statusEl) {
            statusEl.className = "text-xs font-bold text-amber-400 text-center mt-3 max-w-xs px-2";
            statusEl.innerText = "Kamera tidak dapat diakses (" + (err.message || 'Izin kamera ditolak') + "). Gunakan Upload Foto QR atau input manual di bawah.";
        }
    }
};

// Matikan Kamera Pemindai
window.stopKameraScannerPOS = async () => {
    if (posHtml5QrScanner) {
        try {
            if (posHtml5QrScanner.isScanning) {
                await posHtml5QrScanner.stop();
            }
            posHtml5QrScanner.clear();
        } catch (e) {
            console.warn("Error stop scanner POS:", e);
        }
        posHtml5QrScanner = null;
    }
    isPosScannerRunning = false;
};

// Putar Kamera (Depan / Belakang)
window.toggleCameraFacingModeScanner = async () => {
    posScannerFacingMode = (posScannerFacingMode === 'environment') ? 'user' : 'environment';
    await window.mulaiKameraScannerPOS();
};

// Pemindai dari Berkas Gambar (Upload QR)
window.handleScanQRFile = async (event) => {
    const file = event?.target?.files?.[0];
    if (!file) return;

    const Html5QrcodeClass = window.Html5Qrcode || (typeof window.ensureHtml5QrcodeLoaded === 'function' ? await window.ensureHtml5QrcodeLoaded() : null);
    if (!Html5QrcodeClass) {
        if (typeof window.tampilkanNotifikasi === 'function') window.tampilkanNotifikasi("Library scanner tidak tersedia.", "error");
        return;
    }

    const statusEl = document.getElementById('pos-scanner-status');
    if (statusEl) {
        statusEl.className = "text-xs font-bold text-sky-400 text-center mt-3 max-w-xs px-2";
        statusEl.innerText = "Memproses berkas gambar QR code...";
    }

    try {
        await window.stopKameraScannerPOS();
        const fileScanner = new Html5QrcodeClass("pos-qr-reader");
        const result = await fileScanner.scanFile(file, false);
        fileScanner.clear();
        if (result) {
            window.prosesHasilScanPOS(result);
        }
    } catch (err) {
        console.warn("Gagal membaca QR dari file:", err);
        window.playScannerBeep('error');
        if (statusEl) {
            statusEl.className = "text-xs font-bold text-rose-400 text-center mt-3 max-w-xs px-2";
            statusEl.innerText = "❌ QR Code tidak terdeteksi pada gambar. Pastikan gambar jelas dan terang.";
        }
    } finally {
        if (event.target) event.target.value = '';
    }
};

// Input Manual Fallback di Bawah Scanner
window.submitManualQRScan = () => {
    const input = document.getElementById('pos-manual-qr-input')?.value?.trim();
    if (!input) {
        if (typeof window.tampilkanNotifikasi === 'function') window.tampilkanNotifikasi("Ketik nomor WA member, meja, menu, atau kode voucher terlebih dahulu!", "warning");
        return;
    }
    window.prosesHasilScanPOS(input);
};

// Helper pencari menu dari payload QR (key / id / nama)
window._findMenuByQrCandidate = (queryVal) => {
    const raw = String(queryVal || '').trim();
    if (!raw) return null;
    const menusMap = (typeof globalMenus === 'object' && globalMenus) ? globalMenus : (window.globalMenus || {});
    if (menusMap[raw]) return { key: raw, menu: menusMap[raw] };

    const lower = raw.toLowerCase();
    for (const [k, m] of Object.entries(menusMap)) {
        if (!m) continue;
        if (String(k).toLowerCase() === lower || String(m.id || '').toLowerCase() === lower || String(m.key || '').toLowerCase() === lower) {
            return { key: k, menu: m };
        }
    }
    for (const [k, m] of Object.entries(menusMap)) {
        if (!m) continue;
        const nm = String(m.name || m.nama || '').trim().toLowerCase();
        if (nm && (nm === lower || nm.includes(lower))) {
            return { key: k, menu: m };
        }
    }
    return null;
};

// Evaluator Hasil Scan QR Code Serbaguna (Produk, Meja, Member, Voucher)
window.prosesHasilScanPOS = async (rawText) => {
    if (!rawText) return;
    const text = String(rawText).trim();
    if (!text) return;

    let candidateType = null;
    let candidateValue = text;

    // 0. Cek Format URL Link (?menu=, ?meja=, ?voucher=)
    if (text.includes('=') || text.startsWith('http://') || text.startsWith('https://')) {
        try {
            const urlObj = new URL(text.startsWith('http') ? text : 'https://dummy.local/' + text.replace(/^\/+/, ''));
            const mParam = urlObj.searchParams.get('menu') || urlObj.searchParams.get('produk') || urlObj.searchParams.get('p') || urlObj.searchParams.get('item');
            const tParam = urlObj.searchParams.get('meja') || urlObj.searchParams.get('table') || urlObj.searchParams.get('m');
            const vParam = urlObj.searchParams.get('voucher') || urlObj.searchParams.get('v') || urlObj.searchParams.get('promo');
            const memParam = urlObj.searchParams.get('member') || urlObj.searchParams.get('wa');
            if (mParam) {
                candidateType = 'produk';
                candidateValue = mParam.trim();
            } else if (tParam) {
                candidateType = 'meja';
                candidateValue = tParam.trim();
            } else if (vParam) {
                candidateType = 'voucher';
                candidateValue = vParam.trim();
            } else if (memParam) {
                candidateType = 'member';
                candidateValue = memParam.trim();
            }
        } catch (e) {
            const mMatch = text.match(/[?&#](?:menu|produk|p|item)=([^&#]+)/i);
            const tMatch = text.match(/[?&#](?:meja|table|m)=([^&#]+)/i);
            const vMatch = text.match(/[?&#](?:voucher|v|promo)=([a-zA-Z0-9_\-]+)/i);
            if (mMatch) {
                candidateType = 'produk';
                candidateValue = decodeURIComponent(mMatch[1]).trim();
            } else if (tMatch) {
                candidateType = 'meja';
                candidateValue = decodeURIComponent(tMatch[1]).trim();
            } else if (vMatch) {
                candidateType = 'voucher';
                candidateValue = vMatch[1].trim();
            }
        }
    }

    // 1. Cek Format JSON
    if (!candidateType && text.startsWith('{') && text.endsWith('}')) {
        try {
            const parsed = JSON.parse(text);
            if (parsed.type === 'menu' || parsed.type === 'produk' || parsed.menuKey || parsed.menuId || parsed.produk) {
                candidateType = 'produk';
                candidateValue = parsed.menuKey || parsed.menuId || parsed.produk || parsed.id || parsed.name;
            } else if (parsed.type === 'meja' || parsed.type === 'table' || parsed.meja || parsed.table || parsed.nomorMeja) {
                candidateType = 'meja';
                candidateValue = parsed.meja || parsed.table || parsed.nomorMeja;
            } else if (parsed.phone || parsed.nomorWa || parsed.type === 'member') {
                candidateType = 'member';
                candidateValue = parsed.phone || parsed.nomorWa || parsed.id;
            } else if (parsed.code || parsed.kode || parsed.voucher || parsed.type === 'voucher') {
                candidateType = 'voucher';
                candidateValue = parsed.code || parsed.kode || parsed.voucher;
            }
        } catch(e) {}
    }

    // 2. Cek Prefix Khusus (menu:, produk:, meja:, table:, member:, voucher:)
    if (!candidateType) {
        const lower = text.toLowerCase();
        if (lower.startsWith('menu:') || lower.startsWith('produk:') || lower.startsWith('product:') || lower.startsWith('item:')) {
            candidateType = 'produk';
            candidateValue = text.split(':').slice(1).join(':').trim();
        } else if (lower.startsWith('meja:') || lower.startsWith('table:') || lower.startsWith('tbl:') || /^meja\s+\S+/i.test(text)) {
            candidateType = 'meja';
            candidateValue = lower.startsWith('meja ') ? text.slice(5).trim() : text.split(/[:\-]/).slice(1).join('-').trim();
        } else if (lower.startsWith('member:') || lower.startsWith('mem-') || lower.startsWith('loyalty:') || lower.startsWith('wa:')) {
            candidateType = 'member';
            candidateValue = text.split(/[:\-]/).slice(1).join('-').trim();
        } else if (lower.startsWith('voucher:') || lower.startsWith('voc-') || lower.startsWith('promo:') || lower.startsWith('gift:')) {
            candidateType = 'voucher';
            candidateValue = text.split(/[:\-]/).slice(1).join('-').trim();
        }
    }

    // === PROSES QR PRODUK MENU ===
    const menuMatch = (candidateType === 'produk' || !candidateType) ? window._findMenuByQrCandidate(candidateValue) : null;
    if (menuMatch) {
        window.playScannerBeep('success');
        const wasCustomer = Boolean(window.isCustomerScanner);
        await window.tutupModalScannerPOS();
        window.isCustomerScanner = false;

        if (wasCustomer) {
            if (typeof window.bukaModalDetail === 'function') {
                window.bukaModalDetail(menuMatch.key);
            }
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Menu "${menuMatch.menu.name || menuMatch.menu.nama}" ditemukan dari QR.`, 'success');
            }
        } else {
            if (typeof window.klikMenuPOS === 'function') {
                window.klikMenuPOS(menuMatch.key);
            }
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Pilih varian & tambahkan "${menuMatch.menu.name || menuMatch.menu.nama}" ke keranjang kasir.`, 'success');
            }
        }
        return;
    }

    // === PROSES QR NOMOR MEJA ===
    if (candidateType === 'meja' && candidateValue) {
        const cleanMeja = String(candidateValue).trim().toUpperCase();
        window.playScannerBeep('success');
        const wasCustomer = Boolean(window.isCustomerScanner);
        await window.tutupModalScannerPOS();
        window.isCustomerScanner = false;

        if (wasCustomer) {
            const qrMejaOn = typeof window.isQrMejaFeatureEnabled === 'function' ? window.isQrMejaFeatureEnabled() : true;
            if (!qrMejaOn) {
                window.activeCustomerTable = null;
                if (typeof window.tampilkanNotifikasi === 'function') {
                    window.tampilkanNotifikasi('Fitur Deteksi Meja sedang dinonaktifkan oleh toko.', 'info');
                }
                return;
            }
            window.activeCustomerTable = cleanMeja;
            if (typeof window.renderCustomerActiveTableBar === 'function') {
                window.renderCustomerActiveTableBar();
            }
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Meja ${cleanMeja} berhasil terdeteksi! Pesanan Anda tercatat untuk Meja ${cleanMeja}.`, 'success');
            }
        } else {
            if (typeof window.setPosActiveTable === 'function') {
                window.setPosActiveTable(cleanMeja);
            }
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Meja ${cleanMeja} berhasil dipasang ke pesanan kasir.`, 'success');
            }
        }
        return;
    }

    // 3. Cek Angka Telepon Member
    const digitsOnly = candidateValue.replace(/\D/g, '');
    let standardPhone = digitsOnly;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);

    const members = window.cachedMembers || {};
    const memberFound = members[standardPhone] || members[digitsOnly] || (digitsOnly.length >= 9 && members[digitsOnly]);

    if (candidateType === 'member' || memberFound || (!candidateType && digitsOnly.length >= 9 && digitsOnly.length <= 15 && !candidateValue.toUpperCase().includes('VOUCHER') && !candidateValue.toUpperCase().includes('HEMAT') && !candidateValue.toUpperCase().includes('DISC'))) {
        // === PROSES SEBAGAI KARTU MEMBER ===
        const phoneToUse = standardPhone || digitsOnly;
        const member = memberFound || members[phoneToUse];

        window.playScannerBeep('success');

        // Jika scanner dipanggil dari sudut pandang Pelanggan (Customer View FAB)
        if (window.isCustomerScanner) {
            await window.tutupModalScannerPOS();
            window.isCustomerScanner = false;
            const phoneInput = document.getElementById('stamp-phone-check');
            if (phoneInput) phoneInput.value = phoneToUse;
            if (typeof window.bukaModalStamp === 'function') {
                window.bukaModalStamp('check');
            }
            if (typeof window.cekStampMember === 'function') {
                window.cekStampMember();
            }
            return;
        }

        // Mode Kasir POS Manual
        const waEl = document.getElementById('pos-wa');
        if (waEl) waEl.value = phoneToUse;
        const memberChk = document.getElementById('pos-member');
        if (memberChk) memberChk.checked = true;

        if (member) {
            const namaEl = document.getElementById('pos-nama');
            if (namaEl) namaEl.value = member.name || '';
            window.cekMemberPOS(phoneToUse);
            await window.tutupModalScannerPOS();
            const curPts = (typeof window.getMemberPoints === 'function')
                ? window.getMemberPoints(member)
                : Number(member.points ?? member.poin ?? ((Number(member.sessions || 0) * 10) + Number(member.stamps || 0)));
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Member Terverifikasi: ${member.name} (${curPts.toLocaleString('id-ID')} Poin).`, 'success');
            }
        } else {
            const namaEl = document.getElementById('pos-nama');
            if (namaEl && !namaEl.value) namaEl.value = 'Pelanggan Baru';
            await window.tutupModalScannerPOS();
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`No. WA ${phoneToUse} terdeteksi — kotak Daftar Member otomatis dicentang.`, 'info');
            }
        }
        return;
    }

    // 4. Cek Voucher Promo / Gift Voucher
    const voucherCode = candidateValue.toUpperCase();
    const allVouchers = window.cachedVouchers || globalVouchers || {};
    let matchedVoucher = Object.values(allVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === voucherCode);

    if (!matchedVoucher && window.posScannedMember && window.posScannedMember.vouchers) {
        matchedVoucher = Object.values(window.posScannedMember.vouchers).find(v => String(v.kode || v.code || '').toUpperCase() === voucherCode);
    }

    if (!matchedVoucher && typeof get === 'function' && typeof ref === 'function' && db) {
        try {
            const snap = await get(ref(db, 'vouchers'));
            if (snap.exists()) {
                window.cachedVouchers = snap.val() || {};
                globalVouchers = window.cachedVouchers;
                matchedVoucher = Object.values(window.cachedVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === voucherCode);
            }
        } catch(e) {}
    }

    if (matchedVoucher) {
        const v = matchedVoucher;
        
        if (v.status === 'nonaktif') {
            window.playScannerBeep('error');
            if (typeof window.tampilkanNotifikasi === 'function') window.tampilkanNotifikasi(`Voucher "${v.kode}" saat ini berstatus NONAKTIF.`, 'warning');
            return;
        }

        if (v.berlakuHingga) {
            const exp = new Date(v.berlakuHingga);
            if (!isNaN(exp.getTime()) && exp.setHours(23,59,59,999) < Date.now()) {
                window.playScannerBeep('error');
                if (typeof window.tampilkanNotifikasi === 'function') window.tampilkanNotifikasi(`Voucher "${v.kode}" telah kedaluwarsa.`, 'error');
                return;
            }
        }

        // Jika scanner dipanggil dari sudut pandang Pelanggan (Customer View FAB)
        if (window.isCustomerScanner) {
            window.playScannerBeep('success');
            await window.tutupModalScannerPOS();
            window.isCustomerScanner = false;
            v.appliedVia = 'qr';
            window.appliedCheckoutVoucher = v;
            window.pendingUrlVoucher = v.kode;
            const nilaiTeks = v.tipe === 'persen' ? `${v.nilai}%` : `Rp ${Number(v.nilai || 0).toLocaleString('id-ID')}`;
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Voucher ${v.kode} (${nilaiTeks}) terpasang di keranjang checkout Anda!`, 'success');
            }
            return;
        }

        // Validasi Target Audiens di Kasir: Publik, Member, Perorangan
        const posWaVal = (document.getElementById('pos-wa')?.value || '').replace(/\D/g, '');
        const isPosMemberChecked = document.getElementById('pos-member')?.checked;
        const hasScannedMember = Boolean(window.posScannedMember);

        if (v.targetAudience === 'member' && !hasScannedMember && !isPosMemberChecked && !posWaVal) {
            const memberChk = document.getElementById('pos-member');
            if (memberChk) memberChk.checked = true;
        } else if (v.targetAudience === 'perorangan' || v.targetAudience === 'khusus') {
            v.appliedVia = 'qr';
            if (v.waList && !posWaVal) {
                const firstWa = v.waList.split(',')[0].trim();
                const posWaEl = document.getElementById('pos-wa');
                if (posWaEl && firstWa) posWaEl.value = firstWa;
            }
        }

        window.playScannerBeep('success');
        window.posAppliedVoucher = v;
        window.renderBannerVoucherPOS(v);
        renderKeranjangPOS();
        await window.tutupModalScannerPOS();

        const nilaiDesc = v.tipe === 'persen' ? `${v.nilai}%` : 'Rp ' + Number(v.nilai || 0).toLocaleString('id-ID');
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(`Voucher ${v.kode} (${nilaiDesc}) berhasil diklaim ke kasir!`, 'success');
        }
        return;
    }

    // 5. Gagal Verifikasi
    window.playScannerBeep('error');
    const statusEl = document.getElementById('pos-scanner-status');
    if (statusEl) {
        statusEl.className = "text-xs font-bold text-rose-400 text-center mt-3 max-w-xs px-2";
        statusEl.innerText = `❌ QR "${text}" tidak dikenali sebagai Produk, Meja, Kartu Member, atau Voucher aktif.`;
    }
};

// Cek Member POS & Render Kartu Info Interaktif
window.cekMemberPOS = (phoneInput) => {
    const raw = String(phoneInput || '').trim();
    const clean = raw.replace(/\D/g, '');
    let standardPhone = clean;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);
    
    const cardEl = document.getElementById('pos-scanned-member-card');
    if (!cardEl) return;

    const members = window.cachedMembers || {};
    const member = members[standardPhone] || members[clean] || members[raw];

    if (!member) {
        window.posScannedMember = null;
        const nonMembers = window.cachedNonMembers || {};
        const nm = standardPhone.length >= 8 ? (nonMembers[standardPhone] || nonMembers[clean] || nonMembers[raw]) : null;
        if (nm) {
            const namaEl = document.getElementById('pos-nama');
            if (namaEl && (!namaEl.value || namaEl.value === 'Hamba Allah') && nm.name) {
                namaEl.value = nm.name;
            }
            cardEl.className = "p-2.5 bg-slate-50 border border-slate-200 rounded-xl shadow-2xs flex items-center justify-between gap-2 min-w-0";
            cardEl.innerHTML = `
                <div class="flex items-center gap-2 min-w-0">
                    <div class="w-7 h-7 rounded-lg bg-sky-100 text-sky-700 font-black text-xs flex items-center justify-center shrink-0">
                        <i class="fa-solid fa-user"></i>
                    </div>
                    <div class="min-w-0">
                        <p class="text-xs font-black text-slate-800 truncate">${nm.name || 'Non-Member'}</p>
                        <p class="text-[9px] font-bold text-slate-500">Pelanggan Non-Member &bull; ${Number(nm.totalOrders || 0)}x Order</p>
                    </div>
                </div>
                <span class="px-2 py-0.5 rounded-md bg-sky-100 text-sky-800 text-[9px] font-black shrink-0">NON-MEMBER</span>
            `;
            cardEl.classList.remove('hidden');
            return;
        }
        cardEl.classList.add('hidden');
        cardEl.innerHTML = '';
        return;
    }

    window.posScannedMember = member;

    // Sinkronkan nama dan centang member jika belum
    const namaEl = document.getElementById('pos-nama');
    if (namaEl && (!namaEl.value || namaEl.value === 'Hamba Allah')) {
        namaEl.value = member.name || '';
    }
    const memberChk = document.getElementById('pos-member');
    if (memberChk) memberChk.checked = true;

    const points = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(member) : Number(member.points || member.poin || 0);
    const memberVouchers = member.vouchers ? Object.values(member.vouchers) : [];

    cardEl.className = "p-3 bg-gradient-to-br from-amber-50 to-orange-50 border border-amber-300 rounded-2xl shadow-xs space-y-2.5 animate-scale-up min-w-0";
    cardEl.innerHTML = `
        <div class="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-2 border-b border-amber-200/60 pb-2">
            <div class="flex items-center gap-2 min-w-0">
                <div class="w-8 h-8 rounded-xl bg-amber-500 text-white font-black text-xs flex items-center justify-center shadow-xs shrink-0">
                    <i class="fa-solid fa-crown"></i>
                </div>
                <div class="min-w-0">
                    <h4 class="text-xs font-black text-slate-800 leading-tight truncate">${member.name || 'Member Terdaftar'}</h4>
                    <span class="text-[9px] font-bold text-amber-700 block truncate">📱 ${member.phone}</span>
                </div>
            </div>
            <span class="px-2 py-0.5 rounded-full text-[9px] font-black bg-amber-200 text-amber-900 border border-amber-300 shrink-0 whitespace-nowrap">
                ⭐ MEMBER RESMI
            </span>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 text-center">
            <div class="p-2 bg-white/80 rounded-xl border border-amber-200 shadow-2xs">
                <span class="text-[9px] font-bold text-slate-500 block uppercase">Saldo Points</span>
                <span class="text-sm font-black text-amber-600 tabular-nums">⭐ ${points} Pts</span>
            </div>
            <div class="p-2 bg-white/80 rounded-xl border border-amber-200 shadow-2xs">
                <span class="text-[9px] font-bold text-slate-500 block uppercase">Status Penukaran</span>
                <span class="text-xs sm:text-sm font-black ${points >= 5 ? 'text-emerald-600 animate-pulse' : 'text-slate-400'}">${points >= 5 ? 'Bisa Tukar Hadiah' : 'Kumpulkan Points'}</span>
            </div>
        </div>

        ${points >= 5 ? `
            <!-- Tombol 1-Click Klaim Hadiah Minuman ke Keranjang Kasir (Tukar 5 Points) -->
            <button type="button" onclick="window.klaimRewardKeKeranjangPOS('${member.phone}')" class="w-full min-h-[40px] py-2 px-3 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 active:scale-95 text-white text-xs font-black rounded-xl shadow-md flex items-center justify-center gap-2 transition">
                <i class="fa-solid fa-gift text-sm shrink-0"></i>
                <span>Tukar 5 Points Hadiah (Rp 0) ke Keranjang</span>
            </button>
        ` : ''}

        ${memberVouchers.length > 0 ? `
            <div class="pt-1 border-t border-amber-200/50 space-y-1.5">
                <span class="text-[9px] font-black text-amber-900 block uppercase">Voucher Hadiah Member:</span>
                <div class="flex flex-wrap gap-1.5">
                    ${memberVouchers.map(v => `
                        <button type="button" onclick="window.klaimVoucherPOSManual('${v.kode || v.code}')" class="min-h-[32px] px-2.5 py-1 bg-white hover:bg-amber-100 border border-amber-300 text-amber-900 rounded-lg text-[10px] font-black inline-flex items-center gap-1 active:scale-95 transition shadow-2xs">
                            <i class="fa-solid fa-ticket text-indigo-500"></i>
                            <span>${v.kode || v.code} (${v.nama || 'Voucher'})</span>
                        </button>
                    `).join('')}
                </div>
            </div>
        ` : ''}
    `;
    cardEl.classList.remove('hidden');
};

// 1-Click Klaim Hadiah Minuman Gratis ke Keranjang Kasir (Tukar Points)
window.klaimRewardKeKeranjangPOS = (memberPhone) => {
    const member = (window.cachedMembers || {})[memberPhone] || window.posScannedMember;
    const curPoints = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(member) : Number(member?.points || 0);
    if (!member || curPoints < 5) {
        alert("Member ini membutuhkan minimal 5 Points untuk menukarkan hadiah minuman.");
        return;
    }

    const alreadyClaimed = posKeranjang.some(item => item.isLoyaltyReward);
    if (alreadyClaimed) {
        alert("Klaim hadiah minuman sudah dimasukkan ke keranjang pesanan ini!");
        return;
    }

    const menuKeys = Object.keys(globalMenus || {});
    let sampleMenu = menuKeys.length > 0 ? globalMenus[menuKeys[0]] : null;
    let rewardName = sampleMenu ? (sampleMenu.nama || sampleMenu.name) : 'Minuman Favorit Member';

    posKeranjang.push({
        key: 'reward_loyalty_' + Date.now(),
        id: 'reward_loyalty_' + Date.now(),
        nama: `🎁 [KLAIM HADIAH] ${rewardName}`,
        name: `🎁 [KLAIM HADIAH] ${rewardName}`,
        harga: 0,
        price: 0,
        qty: 1,
        varian: 'Normal Ice (Gratis)',
        notes: 'Hadiah Tukar 5 Points Loyalitas',
        isLoyaltyReward: true,
        costPoints: 5,
        costSessions: 1,
        toppings: []
    });

    window.playScannerBeep('success');
    renderKeranjangPOS();
    if (typeof window.syncPosCartBadges === 'function') {
        window.syncPosCartBadges(true);
    }
    alert(`🎉 Hadiah Berhasil Ditambahkan!\n\n1 Porsi Minuman Gratis (Rp 0) telah dimasukkan ke keranjang kasir untuk ${member.name} (Tukar 5 Points).`);
};

// Klaim Voucher Manual POS
window.klaimVoucherPOSManual = async (presetCode) => {
    const inputEl = document.getElementById('pos-voucher-code');
    const kode = String(presetCode || (inputEl ? inputEl.value : '')).trim().toUpperCase();

    if (!kode) {
        alert("Ketik kode voucher atau scan QR voucher terlebih dahulu!");
        return;
    }

    const allVouchers = window.cachedVouchers || globalVouchers || {};
    let matched = Object.values(allVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === kode);

    if (!matched && window.posScannedMember && window.posScannedMember.vouchers) {
        matched = Object.values(window.posScannedMember.vouchers).find(v => String(v.kode || v.code || '').toUpperCase() === kode);
    }

    if (!matched && typeof get === 'function' && typeof ref === 'function' && db) {
        try {
            const snap = await get(ref(db, 'vouchers'));
            if (snap.exists()) {
                window.cachedVouchers = snap.val() || {};
                globalVouchers = window.cachedVouchers;
                matched = Object.values(window.cachedVouchers).find(v => String(v.kode || v.code || '').toUpperCase() === kode);
            }
        } catch(e) {}
    }

    if (!matched) {
        window.playScannerBeep('error');
        alert(`Voucher "${kode}" tidak valid atau tidak ditemukan!`);
        return;
    }

    if (matched.status === 'nonaktif') {
        window.playScannerBeep('error');
        alert(`Voucher "${kode}" sedang dinonaktifkan.`);
        return;
    }

    if (matched.berlakuHingga) {
        const exp = new Date(matched.berlakuHingga);
        if (!isNaN(exp.getTime()) && exp.setHours(23,59,59,999) < Date.now()) {
            window.playScannerBeep('error');
            alert(`Voucher "${kode}" sudah melewati batas masa berlaku (kedaluwarsa).`);
            return;
        }
    }

    // Validasi target audiens di kasir (publik, member, perorangan)
    const rawPhone = (document.getElementById('pos-wa')?.value || '').trim();
    const cleanPhone = rawPhone.replace(/\D/g, '');
    let standardPhone = cleanPhone;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);

    const isMemberCheck = document.getElementById('pos-member')?.checked;
    const isRegisteredMember = Boolean(window.posScannedMember || (window.cachedMembers && (window.cachedMembers[standardPhone] || window.cachedMembers[cleanPhone])));

    if (matched.targetAudience === 'member') {
        if (!isMemberCheck && !isRegisteredMember) {
            window.playScannerBeep('error');
            const ok = confirm(`⭐ Voucher "${kode}" KHUSUS MEMBER RESMI!\n\nPelanggan belum terdaftar sebagai member. Apakah ingin mencentang 'Member' untuk pelanggan ini?`);
            if (ok) {
                const memberChk = document.getElementById('pos-member');
                if (memberChk) memberChk.checked = true;
            } else {
                return;
            }
        }
    } else if (matched.targetAudience === 'perorangan' || matched.targetAudience === 'khusus') {
        // "Perorangan bisa penerapan nya via no wa atau qr"
        let isPhoneMatched = false;
        if (matched.waList) {
            const listWa = matched.waList.split(',').map(n => n.replace(/\D/g, '')).filter(Boolean);
            isPhoneMatched = listWa.some(n => {
                let std = n;
                if (std.startsWith('62')) std = '0' + std.slice(2);
                return (std === standardPhone || n === cleanPhone || (standardPhone && n.endsWith(standardPhone.slice(-8))));
            });
        }

        if (!isPhoneMatched) {
            window.playScannerBeep('error');
            const pass = confirm(`👤 Voucher "${kode}" adalah Kupon Personal Perorangan.\n\nTarget No. WA: ${matched.waList || 'Personal'}\nNomor Kasir Saat Ini: ${rawPhone || '(Kosong)'}\n\nJika pelanggan memegang bukti fisik QR code voucher, kasir dapat mengesahkan klaim ini. Lanjutkan klaim voucher?`);
            if (!pass) return;
        }
    }

    window.posAppliedVoucher = matched;
    window.playScannerBeep('success');
    window.renderBannerVoucherPOS(matched);
    renderKeranjangPOS();

    if (inputEl) inputEl.value = '';
};

// Render Banner Voucher Aktif
window.renderBannerVoucherPOS = (v) => {
    const bannerEl = document.getElementById('pos-active-voucher-banner');
    if (!bannerEl) return;

    if (!v) {
        bannerEl.classList.add('hidden');
        bannerEl.innerHTML = '';
        return;
    }

    const nilaiStr = v.tipe === 'persen' ? `${v.nilai}%` : `Rp ${Number(v.nilai || 0).toLocaleString('id-ID')}`;
    bannerEl.className = "p-2 bg-emerald-50 border border-emerald-300 rounded-xl flex items-center justify-between text-xs mt-1.5 animate-scale-up";
    bannerEl.innerHTML = `
        <div class="flex items-center gap-2">
            <span class="w-6 h-6 shrink-0 rounded-lg bg-emerald-500 text-white flex items-center justify-center text-xs font-black shadow-2xs">
                <i class="fa-solid fa-tag"></i>
            </span>
            <div>
                <span class="font-black text-emerald-950">${v.kode}</span>
                <span class="text-[10px] text-emerald-700 block font-bold">Potongan: ${nilaiStr} (${v.nama || 'Voucher Aktif'})</span>
            </div>
        </div>
        <button type="button" onclick="window.hapusVoucherPOS()" title="Batalkan Voucher" class="w-6 h-6 shrink-0 rounded-full bg-emerald-100 hover:bg-rose-100 text-emerald-800 hover:text-rose-600 font-black flex items-center justify-center transition active:scale-90">
            <i class="fa-solid fa-xmark text-xs"></i>
        </button>
    `;
    bannerEl.classList.remove('hidden');
};

// Hapus Voucher dari POS
window.hapusVoucherPOS = () => {
    window.posAppliedVoucher = null;
    window.renderBannerVoucherPOS(null);
    renderKeranjangPOS();
};

// ==========================================
// CAROUSEL AUTO-PLAY & TOUCH CONTROLLER
// ==========================================
(() => {
    let carouselTimer = null;

    function startCarouselTimer() {
        stopCarouselTimer();
        carouselTimer = setInterval(() => {
            if (typeof window.nextCarouselSlide === 'function') {
                window.nextCarouselSlide();
            }
        }, 5000);
    }

    function stopCarouselTimer() {
        if (carouselTimer) {
            clearInterval(carouselTimer);
            carouselTimer = null;
        }
    }

    function initCarousel() {
        const container = document.getElementById('promo-carousel-container');
        if (!container) return;

        // Mouse hover pause/resume
        container.addEventListener('mouseenter', stopCarouselTimer);
        container.addEventListener('mouseleave', startCarouselTimer);

        // Touch swipe support
        let touchStartX = 0;
        let touchEndX = 0;

        container.addEventListener('touchstart', (e) => {
            stopCarouselTimer();
            if (e.changedTouches && e.changedTouches.length > 0) {
                touchStartX = e.changedTouches[0].screenX;
            }
        }, { passive: true });

        container.addEventListener('touchend', (e) => {
            if (e.changedTouches && e.changedTouches.length > 0) {
                touchEndX = e.changedTouches[0].screenX;
                const diff = touchEndX - touchStartX;
                if (Math.abs(diff) > 40) {
                    if (diff < 0) {
                        window.nextCarouselSlide();
                    } else {
                        window.prevCarouselSlide();
                    }
                }
            }
            startCarouselTimer();
        }, { passive: true });

        // Ensure slide 0 is active initially
        if (typeof window.setCarouselSlide === 'function') {
            window.setCarouselSlide(0);
        }

        startCarouselTimer();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCarousel);
    } else {
        initCarousel();
    }
})();


// =========================================================================
// ISOLASI KETAT BGM & SINKRONISASI NOTIFIKASI TOAST LINTAS TAB KASIR
// =========================================================================
window.perbaruiTampilanBtnBGM = function() {
    try {
        const btn = document.getElementById('btn-bgm');
        if (!btn) return;
        const vc = document.getElementById('view-customer');
        const isCustomerView = vc && !vc.classList.contains('hidden');
        const role = localStorage.getItem('mainstay_session_role');
        const isPosOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';
        
        if (role === 'kasir' || role === 'owner' || isPosOpen) {
            btn.classList.add('hidden');
            btn.style.setProperty('display', 'none', 'important');
            return;
        }

        const modalIds = [
            'modal-login', 'checkout-modal', 'modal-detail-produk', 'modal-struk', 'modal-struk-dapur', 'modal-cetak-universal',
            'modal-stamp', 'modal-customer-qr', 'modal-order-tracking', 'modal-ulasan-pelanggan',
            'modal-pilih-meja', 'ruang-kerja-kasir', 'panel-kasir-manual', 'modal-suara-asisten-pos',
            'modal-perhitungan-laba', 'modal-absensi'
        ];
        const isAnyModalOpen = modalIds.some(id => {
            const el = document.getElementById(id);
            return el && !el.classList.contains('hidden') && el.style.display !== 'none';
        });

        if (isCustomerView && !isAnyModalOpen) {
            btn.classList.remove('hidden');
            btn.style.removeProperty('display');
        } else {
            btn.classList.add('hidden');
            btn.style.setProperty('display', 'none', 'important');
        }
    } catch (e) {}
};

// Pasang observer otomatis untuk memantau perubahan kelas/style modal agar tombol BGM selalu sinkron
if (typeof MutationObserver !== 'undefined') {
    const modalObserver = new MutationObserver(() => {
        if (typeof window.perbaruiTampilanBtnBGM === 'function') {
            window.perbaruiTampilanBtnBGM();
        }
    });
    document.addEventListener('DOMContentLoaded', () => {
        ['modal-login', 'checkout-modal', 'modal-detail-produk', 'modal-struk', 'modal-struk-dapur', 'modal-cetak-universal', 'modal-stamp', 'ruang-kerja-kasir', 'panel-kasir-manual'].forEach(id => {
            const el = document.getElementById(id);
            if (el) modalObserver.observe(el, { attributes: true, attributeFilter: ['class', 'style'] });
        });
        window.perbaruiTampilanBtnBGM();
    });
}

// Listener storage lintas tab agar Kasir selalu mendapat Side Pop-Up Toast saat ada orderan masuk dari customer
window.addEventListener('storage', function(e) {
    if (e.key === 'mainstay_last_incoming_order' && e.newValue) {
        try {
            const orderData = JSON.parse(e.newValue);
            const currentRole = localStorage.getItem('mainstay_session_role');
            const vk = document.getElementById('view-kasir');
            const isKasirActive = currentRole === 'kasir' || (vk && !vk.classList.contains('hidden'));
            if (isKasirActive && orderData) {
                if (typeof window.tampilkanToastPesananBaru === 'function') {
                    window.tampilkanToastPesananBaru(orderData, true);
                }
                if (typeof window.renderKasirOrders === 'function') {
                    window.renderKasirOrders();
                }
                if (typeof window.updateLiveCashDrawer === 'function') {
                    window.updateLiveCashDrawer();
                }
            }
        } catch (err) {}
    }
});

