// =========================================================================
// 1. PANEL MEMBER KHUSUS POS KASIR (INDEPENDEN TANPA PENGATURAN OWNER)
// =========================================================================
window.getMemberCardDisplayMode = () => {
    try {
        const saved = localStorage.getItem('mainstay_member_card_layout');
        return saved === 'portrait' ? 'portrait' : 'landscape';
    } catch (e) {
        return 'landscape';
    }
};

window.applyMemberCardDisplayMode = (modeOverride) => {
    const mode = (modeOverride === 'portrait' || modeOverride === 'landscape')
        ? modeOverride
        : window.getMemberCardDisplayMode();
    try {
        localStorage.setItem('mainstay_member_card_layout', mode);
    } catch (e) {}

    ['modal-member-pos', 'modal-stamp'].forEach(modalId => {
        const el = document.getElementById(modalId);
        if (!el) return;
        el.classList.toggle('member-layout-portrait', mode === 'portrait');
        el.classList.toggle('member-layout-landscape', mode !== 'portrait');
    });

    const isPortrait = mode === 'portrait';
    document.querySelectorAll('.member-layout-toggle-label').forEach(lbl => {
        lbl.innerText = isPortrait ? 'Mode: Portrait' : 'Mode: Landscape';
    });
    document.querySelectorAll('.member-layout-toggle-btn i').forEach(icon => {
        icon.className = isPortrait
            ? 'fa-solid fa-grip-vertical text-amber-500'
            : 'fa-solid fa-table-columns text-blue-500';
    });
    return mode;
};

window.toggleMemberCardDisplayMode = () => {
    const nextMode = window.getMemberCardDisplayMode() === 'portrait' ? 'landscape' : 'portrait';
    return window.applyMemberCardDisplayMode(nextMode);
};

window.bukaPanelMemberPOS = (tab = 'list') => {
    const modal = document.getElementById('modal-member-pos');
    if (!modal) return;
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    window.applyMemberCardDisplayMode();
    window.switchTabMemberPOS(tab);
    window.renderListMemberPOS();
};

window.tutupPanelMemberPOS = () => {
    const modal = document.getElementById('modal-member-pos');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.switchTabMemberPOS = (tab) => {
    const tabList = document.getElementById('pos-member-tab-list');
    const tabAdd = document.getElementById('pos-member-tab-add');
    const btnList = document.getElementById('tab-btn-pos-member-list');
    const btnAdd = document.getElementById('tab-btn-pos-member-add');

    if (tab === 'list') {
        if (tabList) tabList.classList.remove('hidden');
        if (tabAdd) tabAdd.classList.add('hidden');
        if (btnList) {
            btnList.className = "flex-1 py-2 rounded-xl bg-white shadow-xs text-blue-700 transition flex items-center justify-center gap-1.5 font-black";
        }
        if (btnAdd) {
            btnAdd.className = "flex-1 py-2 rounded-xl text-slate-500 hover:text-slate-900 transition flex items-center justify-center gap-1.5 font-bold";
        }
    } else {
        if (tabList) tabList.classList.add('hidden');
        if (tabAdd) tabAdd.classList.remove('hidden');
        if (btnAdd) {
            btnAdd.className = "flex-1 py-2 rounded-xl bg-white shadow-xs text-emerald-700 transition flex items-center justify-center gap-1.5 font-black";
        }
        if (btnList) {
            btnList.className = "flex-1 py-2 rounded-xl text-slate-500 hover:text-slate-900 transition flex items-center justify-center gap-1.5 font-bold";
        }
        const nameInput = document.getElementById('pos-add-member-name');
        if (nameInput) setTimeout(() => nameInput.focus(), 100);
    }
};

window.renderListMemberPOS = () => {
    const container = document.getElementById('pos-member-items-container');
    const badgeCount = document.getElementById('pos-member-count-badge');
    const searchInput = document.getElementById('pos-member-search-input');
    if (!container) return;

    window.applyMemberCardDisplayMode();

    const rawMembers = window.cachedMembers || globalMembers || {};
    let memberList = Object.values(rawMembers);

    // Ambil nomor / nama unik
    const uniqueMap = new Map();
    memberList.forEach(m => {
        const key = String(m.phone || m.telepon || m.wa || m.nama || m.name || '').trim();
        if (key && !uniqueMap.has(key)) {
            uniqueMap.set(key, m);
        }
    });
    memberList = Array.from(uniqueMap.values());

    if (badgeCount) badgeCount.innerText = memberList.length;

    const query = String(searchInput?.value || '').toLowerCase().trim();
    if (query) {
        memberList = memberList.filter(m => {
            const nama = String(m.name || m.nama || '').toLowerCase();
            const phone = String(m.phone || m.telepon || m.wa || '').toLowerCase();
            return nama.includes(query) || phone.includes(query);
        });
    }

    if (memberList.length === 0) {
        container.innerHTML = `
            <div class="col-span-full text-center py-8 bg-slate-50 rounded-2xl border border-slate-200">
                <i class="fa-solid fa-user-slash text-2xl text-slate-300 mb-2"></i>
                <p class="text-xs font-bold text-slate-600">Tidak ada member ditemukan</p>
                <p class="text-[10px] text-slate-400 mt-0.5">Daftarkan pelanggan baru lewat tab "+ Daftar Member Baru"</p>
                <button type="button" onclick="window.switchTabMemberPOS('add')" class="mt-3 px-3.5 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-black transition">
                    + Tambah Sekarang
                </button>
            </div>
        `;
        return;
    }

    // Sort alfabetis
    memberList.sort((a, b) => String(a.name || a.nama || '').localeCompare(String(b.name || b.nama || '')));

    let html = '';
    memberList.forEach(m => {
        const nama = m.name || m.nama || 'Pelanggan';
        const phone = m.phone || m.telepon || m.wa || '-';
        const points = Number(m.points || m.poin || 0);
        const tierInfo = typeof window.getMemberTierInfo === 'function' ? window.getMemberTierInfo(m) : null;
        const curTier = tierInfo?.currentTier || { name: 'Classic', rewards: [] };
        const rewardsList = Array.isArray(curTier.rewards) ? curTier.rewards : [];

        html += `
            <div class="member-card-content bg-white rounded-2xl border border-slate-200/90 shadow-2xs hover:border-blue-300 hover:shadow-xs transition">
                <div class="member-pos-identity-row flex items-center gap-2.5 min-w-0 flex-1">
                    <div class="w-9 h-9 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white font-black text-xs flex items-center justify-center shrink-0 shadow-2xs">
                        ${nama.slice(0, 2).toUpperCase()}
                    </div>
                    <div class="min-w-0 flex-1 w-full">
                        <div class="flex items-center flex-wrap gap-1.5">
                            <h4 class="text-xs font-black text-slate-800 leading-tight break-words">${nama}</h4>
                            <span class="text-[9px] font-black px-1.5 py-0.5 bg-indigo-50 text-indigo-700 border border-indigo-200 rounded-md whitespace-nowrap">${curTier.name}</span>
                        </div>
                        <div class="flex items-center flex-wrap gap-1.5 mt-0.5">
                            <span class="text-[10px] font-bold text-slate-500 break-all"><i class="fa-brands fa-whatsapp text-emerald-600"></i> ${phone}</span>
                            <span class="text-[9px] font-black px-1.5 py-0.5 bg-amber-100 text-amber-900 rounded-md whitespace-nowrap">⭐ ${points} Pts</span>
                        </div>
                    </div>
                </div>
                <div class="member-pos-actions-row flex items-center gap-1.5 shrink-0 ml-auto">
                    <button type="button" onclick="window.tambahPointsMemberPOS('${phone}', 5)" class="px-2 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-800 border border-amber-300 rounded-lg text-[10px] font-black transition active:scale-95 whitespace-nowrap" title="+5 Points Cepat">
                        +5 Pts
                    </button>
                    <button type="button" onclick="window.pilihMemberKePOS('${phone}')" class="px-2.5 py-1.5 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white rounded-lg text-[10px] font-black transition flex items-center gap-1 shadow-2xs whitespace-nowrap">
                        <i class="fa-solid fa-check text-[9px]"></i> Pilih
                    </button>
                </div>
                ${rewardsList.length > 0 ? `
                    <div class="member-pos-rewards-strip pt-1.5 border-t border-slate-100">
                        ${rewardsList.map(rw => `
                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-amber-50 border border-amber-200 text-amber-900 text-[9px] font-bold break-words max-w-full">
                                <i class="fa-solid fa-gift text-amber-500 text-[8px] shrink-0"></i>
                                <span>${rw}</span>
                            </span>
                        `).join('')}
                    </div>
                ` : ''}
            </div>
        `;
    });

    container.innerHTML = html;
};

window.pilihMemberKePOS = (phone) => {
    const raw = String(phone || '').trim();
    const clean = raw.replace(/\D/g, '');
    let standardPhone = clean;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);

    const members = window.cachedMembers || globalMembers || {};
    const member = members[standardPhone] || members[clean] || members[raw];

    const inputNama = document.getElementById('pos-nama');
    const inputWA = document.getElementById('pos-wa');
    const chkMember = document.getElementById('pos-member');

    if (member) {
        if (inputNama) inputNama.value = member.name || member.nama || '';
        if (inputWA) inputWA.value = member.phone || standardPhone;
        if (chkMember) chkMember.checked = true;
    } else {
        if (inputWA) inputWA.value = standardPhone;
        if (chkMember) chkMember.checked = true;
    }

    if (typeof window.cekMemberPOS === 'function') {
        window.cekMemberPOS(standardPhone);
    }

    window.tutupPanelMemberPOS();
};

window.cekDuplikatNomorMemberPOS = () => {
    const phoneEl = document.getElementById('pos-add-member-phone');
    const warnBox = document.getElementById('pos-member-duplicate-warning');
    const detailEl = document.getElementById('pos-member-duplicate-detail');
    if (!phoneEl || !warnBox) return null;

    const match = typeof window.cariMemberByPhone === 'function' ? window.cariMemberByPhone(phoneEl.value) : null;
    if (match && match.member) {
        const mName = match.member.name || match.member.nama || 'Member';
        const mPts = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(match.member) : Number(match.member.points ?? match.member.poin ?? 0);
        phoneEl.classList.remove('border-slate-200', 'focus:border-blue-500');
        phoneEl.classList.add('border-rose-500', 'bg-rose-50/50', 'focus:border-rose-600');
        if (detailEl) {
            detailEl.innerText = `Atas nama "${mName}" (${match.standardPhone}) • Saldo ⭐ ${mPts} Points.`;
        }
        warnBox.dataset.foundPhone = match.standardPhone;
        warnBox.classList.remove('hidden');
        return match;
    }

    phoneEl.classList.remove('border-rose-500', 'bg-rose-50/50', 'focus:border-rose-600');
    phoneEl.classList.add('border-slate-200', 'focus:border-blue-500');
    warnBox.classList.add('hidden');
    delete warnBox.dataset.foundPhone;
    return null;
};

window.pakaiMemberDuplikatDiPOS = () => {
    const warnBox = document.getElementById('pos-member-duplicate-warning');
    const phoneEl = document.getElementById('pos-add-member-phone');
    const targetPhone = (warnBox && warnBox.dataset.foundPhone) || (typeof window.normalizeMemberPhone === 'function' ? window.normalizeMemberPhone(phoneEl?.value) : '');
    if (targetPhone && typeof window.pilihMemberKePOS === 'function') {
        window.pilihMemberKePOS(targetPhone);
    }
};

window.simpanMemberBaruPOS = async () => {
    const nameEl = document.getElementById('pos-add-member-name');
    const phoneEl = document.getElementById('pos-add-member-phone');
    const autoApplyEl = document.getElementById('pos-add-auto-apply');

    const nama = nameEl?.value?.trim();
    const rawPhone = phoneEl?.value?.trim();

    if (!nama) return alert("Peringatan: Nama member wajib diisi!");
    if (!rawPhone) return alert("Peringatan: Nomor WhatsApp wajib diisi!");

    const clean = rawPhone.replace(/\D/g, '');
    let standardPhone = clean;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);

    if (standardPhone.length < 9) {
        return alert("Peringatan: Nomor WhatsApp minimal 9 digit!");
    }

    // CEK DUPLIKAT NOMOR MEMBER TERDAFTAR
    let existingMatch = window.cekDuplikatNomorMemberPOS();
    if (!existingMatch) {
        try {
            const snap = await get(ref(db, `members/${standardPhone}`));
            if (snap.exists()) {
                if (!window.cachedMembers) window.cachedMembers = {};
                window.cachedMembers[standardPhone] = snap.val();
                existingMatch = window.cekDuplikatNomorMemberPOS() || { key: standardPhone, member: snap.val(), standardPhone };
            }
        } catch (err) {}
    }

    if (existingMatch && existingMatch.member) {
        const mName = existingMatch.member.name || existingMatch.member.nama || 'Member';
        if (typeof window.showNotif === 'function') {
            window.showNotif(`Nomor WhatsApp ${standardPhone} sudah terdaftar sebagai Member (${mName})!`, 'error');
        }
        return alert(`⚠️ Peringatan: Nomor WhatsApp ${standardPhone} sudah terdaftar sebagai Member atas nama "${mName}"!\n\nSilakan klik "Gunakan Member Ini di Transaksi" atau pilih dari Daftar Member.`);
    }

    const prevNonMember = (window.cachedNonMembers && window.cachedNonMembers[standardPhone]) || {};

    const payload = {
        name: nama,
        nama: nama,
        phone: standardPhone,
        telepon: standardPhone,
        wa: standardPhone,
        points: 10,
        poin: 10,
        totalOrders: Number(prevNonMember.totalOrders || 0),
        totalSpent: Number(prevNonMember.totalSpent || 0),
        registeredAt: Date.now(),
        createdBy: 'Kasir POS'
    };

    try {
        if (!window.cachedMembers) window.cachedMembers = {};
        window.cachedMembers[standardPhone] = payload;

        // Simpan ke Firebase Database jika terkoneksi & bersihkan non_members jika sebelumnya non-member
        try {
            await set(ref(db, `members/${standardPhone}`), payload);
            if (window.cachedNonMembers && window.cachedNonMembers[standardPhone]) {
                await remove(ref(db, `non_members/${standardPhone}`)).catch(() => {});
                delete window.cachedNonMembers[standardPhone];
            }
        } catch(e) {
            console.warn("Simpan member ke DB:", e);
        }

        alert(`✅ Member Berhasil Didaftarkan!\n\nNama: ${nama}\nWhatsApp: ${standardPhone}\nBonus: 10 Points Perdana telah ditambahkan.`);

        if (nameEl) nameEl.value = '';
        if (phoneEl) phoneEl.value = '';
        window.cekDuplikatNomorMemberPOS();

        if (autoApplyEl && autoApplyEl.checked) {
            window.pilihMemberKePOS(standardPhone);
        } else {
            window.switchTabMemberPOS('list');
            window.renderListMemberPOS();
        }
    } catch (err) {
        alert("Gagal mendaftarkan member: " + err.message);
    }
};

window.tambahPointsMemberPOS = async (phone, delta = 5) => {
    const clean = String(phone || '').replace(/\D/g, '');
    let standardPhone = clean;
    if (standardPhone.startsWith('62')) standardPhone = '0' + standardPhone.slice(2);

    const members = window.cachedMembers || globalMembers || {};
    const member = members[standardPhone] || members[clean] || members[phone];

    if (!member) return alert("Member tidak ditemukan!");

    const currentPoints = typeof window.getMemberPoints === 'function' ? window.getMemberPoints(member) : Number(member.points || 0);
    const newPoints = Math.max(0, currentPoints + delta);

    member.points = newPoints;
    member.poin = newPoints;
    member.lastActive = Date.now();

    try {
        await update(ref(db, `members/${standardPhone}`), {
            points: newPoints,
            poin: newPoints,
            lastActive: Date.now()
        });
    } catch(e) {}

    window.renderListMemberPOS();
    if (typeof window.cekMemberPOS === 'function' && document.getElementById('pos-scanned-member-card')) {
        window.cekMemberPOS(standardPhone);
    }
    alert(`⭐ Berhasil menambahkan +${delta} Points untuk ${member.name || 'Member'}!\nTotal Points Saat Ini: ${newPoints} Points`);
};
window.tambahStampMemberPOS = window.tambahPointsMemberPOS;

// =========================================================================
// 2. SIDE POPUP PERINGATAN STAF BELUM ABSEN (MULTI-STAFF ALERT)
// Peringatan HANYA muncul di tampilan kasir, tampil sekali saja di awal sesi kasir,
// dan data profil staf disinkronkan akurat dengan data HRD (Nama, Role, Shift, Foto/Avatar).
// =========================================================================
window._hasShownUnclockedWarningOnce = false;

window.cekNotifikasiStaffBelumAbsen = (force = false) => {
    try {
        // VALIDASI 1: HANYA tampil di tampilan kasir (view-kasir aktif & mainstay_session_role === 'kasir')
        const sessionRole = localStorage.getItem('mainstay_session_role');
        const viewKasir = document.getElementById('view-kasir');
        const isKasirActive = (sessionRole === 'kasir') || (viewKasir && !viewKasir.classList.contains('hidden') && viewKasir.style.display !== 'none');
        
        if (!isKasirActive) {
            window.tutupSidePopupStaffBelumAbsen();
            return;
        }

        // VALIDASI 2: Tampil SEKALI saja diawal sesi kasir hari ini
        const todayDate = new Date().toISOString().slice(0, 10);
        if (sessionStorage.getItem('mainstay_unclocked_warned_' + todayDate)) {
            return;
        }
        if (window._hasShownUnclockedWarningOnce) {
            return;
        }

        // Kumpulkan data profil staf langsung dari HRD & Database Owner
        let staffMap = {};

        // 1. Ambil dari sumber terpadu (Firebase globalStaff + IndexedDB cabang aktif)
        const effectiveMapNotif = typeof window.getEffectiveBranchStaffMap === 'function'
            ? window.getEffectiveBranchStaffMap()
            : (globalStaff || {});
        staffMap = { ...effectiveMapNotif };

        // 2. Fallback dari local cache mainstay_cached_staff jika masih kosong
        if (Object.keys(staffMap).length === 0) {
            try {
                const cached = JSON.parse(localStorage.getItem('mainstay_cached_staff') || '{}');
                if (cached && typeof cached === 'object' && Object.keys(cached).length > 0) {
                    staffMap = { ...cached };
                }
            } catch(e) {}
        }

        // 3. Fallback ke profil staf bawaan jika database belum terisi (hanya untuk Pusat)
        if (Object.keys(staffMap).length === 0 && !window.IS_BRANCH_OUTLET && window.defaultDemoStaff) {
            staffMap = { ...window.defaultDemoStaff };
        }

        const staffList = Object.values(staffMap);

        // Filter staf operasional (non-owner): ambil profil staf riil dari HRD & Owner
        const operationalStaff = staffList.filter(s => {
            if (!s) return false;
            const role = String(s.role || s.tipeKaryawan || s.status || '').toLowerCase();
            const name = String(s.name || s.nama || '').toLowerCase();
            const pin = String(s.pin || '');
            const isOwner = role === 'owner' || role.includes('owner') || name === 'owner' || pin === '888888';
            return !isOwner && pin.length >= 4;
        });

        // Jika tidak ada staf operasional yang terdaftar, tidak perlu peringatan
        if (operationalStaff.length === 0) {
            window.tutupSidePopupStaffBelumAbsen();
            return;
        }

        // Cek siapa saja staf yang belum absen hari ini menggunakan data riil nama & PIN dari profil HRD & Owner
        const unclockedStaff = operationalStaff.filter(s => {
            const staffName = s.name || s.nama || (s.pin === '555555' || s.pin === '654321' ? 'Ihsan' : (s.pin === '123456' ? 'elmusaqi' : 'Staff'));
            const staffPin = s.pin || (staffName.toLowerCase().includes('ihsan') ? '555555' : '123456');
            const duty = typeof window.cekStatusTugasStaf === 'function' 
                ? window.cekStatusTugasStaf(staffName, staffPin) 
                : { hasClockedInToday: false };
            return !duty.hasClockedInToday;
        });

        if (unclockedStaff.length > 0) {
            window.tampilkanSidePopupStaffBelumAbsen(unclockedStaff);
        } else {
            window.tutupSidePopupStaffBelumAbsen();
        }
    } catch (err) {
        console.warn("Gagal cek staf belum absen:", err);
    }
};

window.tampilkanSidePopupStaffBelumAbsen = (list) => {
    // Pastikan sekali lagi hanya muncul bila kasir sedang aktif
    const sessionRole = localStorage.getItem('mainstay_session_role');
    const viewKasir = document.getElementById('view-kasir');
    const isKasirActive = (sessionRole === 'kasir') || (viewKasir && !viewKasir.classList.contains('hidden') && viewKasir.style.display !== 'none');
    if (!isKasirActive) return;

    window._hasShownUnclockedWarningOnce = true;

    const popup = document.getElementById('side-popup-unclocked-staff');
    const container = document.getElementById('side-popup-unclocked-list');
    const subTitle = document.getElementById('side-popup-unclocked-subtitle');
    if (!popup || !container) return;

    if (subTitle) {
        subTitle.innerText = `${list.length} Karyawan Belum Absen Shift Hari Ini`;
    }

    let itemsHtml = '';
    list.forEach(s => {
        // Ambil data profil akurat dari HRD & database Owner (tanpa nama generik peran)
        let staffName = (s.name || s.nama || '').trim();
        if (!staffName || staffName.toLowerCase() === 'kasir utama') {
            staffName = (s.pin === '555555' || s.pin === '654321') ? 'Ihsan' : (s.pin === '123456' ? 'elmusaqi' : 'Staff');
        } else if (staffName.toLowerCase() === 'barista utama') {
            staffName = 'elmusaqi';
        }

        const statusText = (s.status || s.tipeKaryawan || s.role || 'Pegawai Tetap').trim();
        const shiftIn = s.shiftIn || s.jamMasuk || '10:00';
        const shiftOut = s.shiftOut || s.jamPulang || '09:15';
        let photoSrc = s.photo || s.foto || s.faceData;
        if (!photoSrc) {
            if (staffName.toLowerCase().includes('ihsan')) {
                photoSrc = '/assets/aistudio/ihsan_avatar.jpg';
            } else if (staffName.toLowerCase().includes('elmusaqi')) {
                photoSrc = '/assets/aistudio/elmusaqi_avatar.jpg';
            }
        }
        const initial = (staffName.length >= 2 ? staffName.slice(0, 2) : staffName).toUpperCase();
        const pinCode = s.pin || (staffName.toLowerCase().includes('ihsan') ? '555555' : '123456');

        // Badge status sesuai HRD profil
        let roleBadgeColor = 'bg-purple-100 text-purple-700 border-purple-200';
        if (statusText.toLowerCase().includes('tetap')) {
            roleBadgeColor = 'bg-purple-100 text-purple-700 border-purple-200';
        } else if (statusText.toLowerCase().includes('kontrak') || statusText.toLowerCase().includes('part time')) {
            roleBadgeColor = 'bg-blue-100 text-blue-700 border-blue-200';
        }

        const avatarHtml = photoSrc 
            ? `<div class="w-11 h-11 rounded-full overflow-hidden border-2 border-purple-300 shadow-sm shrink-0 bg-slate-100 flex items-center justify-center">
                 <img src="${photoSrc}" class="w-full h-full object-cover" onerror="this.onerror=null; this.src='/assets/aistudio/ihsan_avatar.jpg';">
               </div>`
            : `<div class="w-11 h-11 rounded-full bg-gradient-to-tr from-purple-500 to-indigo-600 text-white font-black text-xs flex items-center justify-center shadow-sm shrink-0 border-2 border-purple-200">${initial}</div>`;

        itemsHtml += `
            <div onclick="window.pilihStaffDariPopupPeringatan('${pinCode}', '${staffName.replace(/'/g, "\\'")}')" class="p-3 bg-white/95 hover:bg-purple-50/50 rounded-2xl border border-slate-200 hover:border-purple-300 flex items-center justify-between gap-3 shadow-2xs cursor-pointer active:scale-[0.99] transition duration-200" title="Klik untuk absen ${staffName}">
                <div class="flex items-center gap-3 min-w-0">
                    ${avatarHtml}
                    <div class="min-w-0">
                        <div class="flex items-center gap-1.5 flex-wrap">
                            <span class="text-xs font-black text-slate-900 truncate leading-tight">${staffName}</span>
                            <span class="text-[9px] font-black px-2 py-0.5 rounded-md border ${roleBadgeColor}">${statusText}</span>
                        </div>
                        <div class="text-[10px] font-bold text-slate-600 flex items-center gap-1 mt-1">
                            <i class="fa-regular fa-clock text-blue-600 text-[10px]"></i>
                            <span>Shift: ${shiftIn} - ${shiftOut} WIB</span>
                        </div>
                    </div>
                </div>
                <button type="button" onclick="event.stopPropagation(); window.pilihStaffDariPopupPeringatan('${pinCode}', '${staffName.replace(/'/g, "\\'")}')" class="text-[10px] font-black bg-gradient-to-r from-rose-500 to-pink-500 hover:from-rose-600 hover:to-pink-600 text-white px-3.5 py-1.5 rounded-full shadow-sm shrink-0 uppercase tracking-wider flex items-center gap-1.5 active:scale-95 transition">
                    <i class="fa-solid fa-camera text-[9px]"></i> ABSEN
                </button>
            </div>
        `;
    });

    container.innerHTML = itemsHtml;
    popup.classList.remove('hidden');
};

window.pilihStaffDariPopupPeringatan = async (pin, name) => {
    window.tutupSidePopupStaffBelumAbsen();
    if (typeof window.bukaHalamanKerja === 'function') {
        window.bukaHalamanKerja();
    }
    if (typeof window.switchTabKerja === 'function') {
        window.switchTabKerja('absensi');
    }
    const pinEl = document.getElementById('pin-absensi-kamera');
    if (pinEl && pin) {
        pinEl.value = pin;
    }
    const selectPin = document.getElementById('select-staff-absen');
    if (selectPin && pin) {
        for (let opt of selectPin.options) {
            if (opt.value === pin || opt.text.includes(name)) {
                selectPin.value = opt.value;
                break;
            }
        }
    }
    if (pin && typeof window.handlePinInputAbsensi === 'function') {
        await window.handlePinInputAbsensi(pin);
    } else if (typeof window.validasiDanMulaiAbsen === 'function') {
        await window.validasiDanMulaiAbsen('Masuk');
    }
};

window.tutupSidePopupStaffBelumAbsen = () => {
    const popup = document.getElementById('side-popup-unclocked-staff');
    if (popup) popup.classList.add('hidden');
    try {
        const todayDate = new Date().toISOString().slice(0, 10);
        sessionStorage.setItem('mainstay_unclocked_warned_' + todayDate, 'true');
    } catch(e) {}
    window._hasShownUnclockedWarningOnce = true;
};

window.arahkanKeAbsensiDariSidePopup = () => {
    window.tutupSidePopupStaffBelumAbsen();
    if (typeof window.bukaHalamanKerja === 'function') {
        window.bukaHalamanKerja();
    }
    if (typeof window.switchTabKerja === 'function') {
        window.switchTabKerja('absensi');
    }
    const pinEl = document.getElementById('pin-absensi-kamera');
    if (pinEl) {
        pinEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => pinEl.focus(), 300);
    }
};

// =========================================================================
// 3. VERIFIKASI & ALUR IZIN ABSEN PULANG SEBELUM JADWAL SELESAI
// =========================================================================
window.bukaModalIzinPulangAwal = (staff, pin, shiftOut) => {
    window._earlyDepartureSession = {
        staff: staff,
        pin: pin,
        shiftOut: shiftOut
    };
    window.pendingEarlyDepartureData = null;

    const modal = document.getElementById('modal-izin-pulang-awal');
    const namaEl = document.getElementById('izin-staff-nama');
    const pinBadge = document.getElementById('izin-staff-pin-badge');
    const descEl = document.getElementById('izin-jadwal-desc');
    const fileInput = document.getElementById('izin-file-bukti');
    const ketTextarea = document.getElementById('izin-keterangan-textarea');
    const alasanSelect = document.getElementById('izin-alasan-select');
    const wrapLainnya = document.getElementById('wrap-izin-alasan-lainnya');
    const inputLainnya = document.getElementById('izin-alasan-lainnya-input');

    if (namaEl) namaEl.innerText = `${staff.name} (${staff.tipeKaryawan || staff.role || 'Staff'})`;
    if (pinBadge) pinBadge.innerText = `PIN: ${pin}`;

    const now = new Date();
    const jamNow = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    if (descEl) {
        descEl.innerHTML = `Jadwal shift Anda selesai pukul <b>${shiftOut} WIB</b>. Saat ini masih pukul <b>${jamNow} WIB</b> (Pulang Lebih Awal). Konfirmasi izin Owner diperlukan!`;
    }

    if (fileInput) fileInput.value = '';
    if (ketTextarea) ketTextarea.value = '';
    if (alasanSelect) alasanSelect.value = 'Sakit / Tidak Enak Badan';
    if (wrapLainnya) wrapLainnya.classList.add('hidden');
    if (inputLainnya) inputLainnya.value = '';

    window.hapusBuktiIzin();
    window.switchTabIzinPulang('belum'); // Default ke Belum Izin untuk kehati-hatian

    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }
};

window.tutupModalIzinPulangAwal = () => {
    const modal = document.getElementById('modal-izin-pulang-awal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    window._earlyDepartureSession = null;
};

window.switchTabIzinPulang = (status) => {
    const secBelum = document.getElementById('section-belum-izin');
    const secSudah = document.getElementById('section-sudah-izin');
    const btnBelum = document.getElementById('btn-status-belum-izin');
    const btnSudah = document.getElementById('btn-status-sudah-izin');

    if (status === 'belum') {
        if (secBelum) secBelum.classList.remove('hidden');
        if (secSudah) secSudah.classList.add('hidden');
        if (btnBelum) {
            btnBelum.className = "py-2.5 px-3 rounded-xl border-2 border-rose-500 bg-rose-50 text-rose-800 font-black text-xs transition flex items-center justify-center gap-1.5 shadow-2xs";
        }
        if (btnSudah) {
            btnSudah.className = "py-2.5 px-3 rounded-xl border-2 border-slate-200 text-slate-600 hover:border-slate-400 font-black text-xs transition flex items-center justify-center gap-1.5";
        }
    } else {
        if (secBelum) secBelum.classList.add('hidden');
        if (secSudah) secSudah.classList.remove('hidden');
        if (btnSudah) {
            btnSudah.className = "py-2.5 px-3 rounded-xl border-2 border-emerald-500 bg-emerald-50 text-emerald-800 font-black text-xs transition flex items-center justify-center gap-1.5 shadow-2xs";
        }
        if (btnBelum) {
            btnBelum.className = "py-2.5 px-3 rounded-xl border-2 border-slate-200 text-slate-600 hover:border-slate-400 font-black text-xs transition flex items-center justify-center gap-1.5";
        }
    }
};

window.kirimPesanWaIzinOwner = () => {
    const session = window._earlyDepartureSession;
    if (!session) return;
    const staff = session.staff;
    const shiftOut = session.shiftOut || '22:00';
    const now = new Date();
    const jamNow = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';

    const { noWA, ownerName } = typeof window.getNomorWhatsAppOwner === 'function' 
        ? window.getNomorWhatsAppOwner() 
        : { noWA: '628977099557', ownerName: 'Owner' };
    const cleanWA = typeof window.formatNomorWAInternasional === 'function' 
        ? window.formatNomorWAInternasional(noWA) 
        : '628977099557';

    const pesan = `Halo ${ownerName},
Saya *${staff.name}* (PIN: *${staff.pin}*, Role: *${staff.tipeKaryawan || staff.role || 'Staff'}*).
Saya ingin meminta izin untuk *pulang lebih awal* dari shift saya hari ini.

• Jadwal Pulang Shift: ${shiftOut} WIB
• Waktu Permohonan: ${jamNow}

Mohon persetujuannya ya Bos. Terima kasih! 🙏`;

    window.open(`https://wa.me/${cleanWA}?text=${encodeURIComponent(pesan)}`, '_blank');
};

window.handleUploadBuktiIzin = (event) => {
    const file = event.target.files && event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function(e) {
        window._tempBuktiIzinBase64 = e.target.result;
        const wrap = document.getElementById('izin-bukti-preview-wrap');
        const img = document.getElementById('izin-bukti-preview-img');
        const status = document.getElementById('izin-file-status');

        if (img) img.src = e.target.result;
        if (wrap) wrap.classList.remove('hidden');
        if (status) {
            status.innerText = "✓ Berhasil diunggah";
            status.className = "text-[9px] text-emerald-600 font-bold";
        }
    };
    reader.readAsDataURL(file);
};

window.hapusBuktiIzin = () => {
    window._tempBuktiIzinBase64 = null;
    const wrap = document.getElementById('izin-bukti-preview-wrap');
    const img = document.getElementById('izin-bukti-preview-img');
    const status = document.getElementById('izin-file-status');
    const fileInput = document.getElementById('izin-file-bukti');

    if (wrap) wrap.classList.add('hidden');
    if (img) img.src = '';
    if (fileInput) fileInput.value = '';
    if (status) {
        status.innerText = "Wajib diunggah";
        status.className = "text-[9px] text-slate-400 font-normal";
    }
};

window.handlePilihanAlasanIzin = (val) => {
    const wrap = document.getElementById('wrap-izin-alasan-lainnya');
    if (wrap) {
        if (val === 'Lainnya') wrap.classList.remove('hidden');
        else wrap.classList.add('hidden');
    }
};

window.batalAbsenPulangAwal = () => {
    window._earlyDepartureSession = null;
    if (typeof window.hapusBuktiIzin === 'function') window.hapusBuktiIzin();
    if (typeof window.tutupModalIzinPulangAwal === 'function') window.tutupModalIzinPulangAwal();
    if (typeof window.showNotification === 'function') {
        window.showNotification("Absen pulang lebih awal dibatalkan.", "info");
    }
};

window.konfirmasiIzinDanBukaKameraPulang = async () => {
    const session = window._earlyDepartureSession;
    if (!session) return alert("Sesi absensi telah berakhir, silakan masukkan PIN kembali.");

    const alasanSelect = document.getElementById('izin-alasan-select')?.value || 'Sakit / Tidak Enak Badan';
    const alasanLainnya = document.getElementById('izin-alasan-lainnya-input')?.value?.trim() || '';
    const keterangan = document.getElementById('izin-keterangan-textarea')?.value?.trim() || '';
    const finalAlasan = (alasanSelect === 'Lainnya') ? (alasanLainnya || 'Alasan Khusus') : alasanSelect;

    if (!window._tempBuktiIzinBase64) {
        alert("Wajib mengunggah bukti screenshot izin WhatsApp dari Owner terlebih dahulu!");
        return;
    }
    if (!keterangan) {
        alert("Wajib mengisi keterangan alasan izin pulang lebih awal!");
        const ketEl = document.getElementById('izin-keterangan-textarea');
        if (ketEl) ketEl.focus();
        return;
    }

    // Simpan metadata izin pulang awal
    window.pendingEarlyDepartureData = {
        isPulangAwal: true,
        alasan: finalAlasan,
        keterangan: keterangan,
        buktiScreenshot: window._tempBuktiIzinBase64,
        shiftOut: session.shiftOut
    };

    const { staff, pin } = session;
    window.tutupModalIzinPulangAwal();

    // Buka kamera selfie absensi pulang
    await window.bukaKameraAbsensi(staff, 'Pulang', pin);
};

// ==========================================
// KONTROLER PESANAN PRE-ORDER KASIR & PELANGGAN
// ==========================================
window.togglePreOrderOptions = (isPreOrder) => {
    const sec = document.getElementById('co-preorder-section');
    if (!sec) return;
    if (isPreOrder) {
        sec.classList.remove('hidden');
        const dateInput = document.getElementById('co-preorder-date');
        if (dateInput) {
            const today = new Date();
            const yyyy = today.getFullYear();
            const mm = String(today.getMonth() + 1).padStart(2, '0');
            const dd = String(today.getDate()).padStart(2, '0');
            const todayStr = `${yyyy}-${mm}-${dd}`;
            
            const maxDate = new Date();
            maxDate.setDate(maxDate.getDate() + 7);
            const maxYyyy = maxDate.getFullYear();
            const maxMm = String(maxDate.getMonth() + 1).padStart(2, '0');
            const maxDd = String(maxDate.getDate()).padStart(2, '0');
            const maxStr = `${maxYyyy}-${maxMm}-${maxDd}`;
            
            dateInput.min = todayStr;
            dateInput.max = maxStr;
            if (!dateInput.value || dateInput.value < todayStr || dateInput.value > maxStr) {
                dateInput.value = todayStr;
            }
        }
    } else {
        sec.classList.add('hidden');
    }
};

window.bukaModalDaftarPreOrder = () => {
    const modal = document.getElementById('modal-daftar-preorder');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }
    window.renderDaftarPreOrder();
};

window.tutupModalDaftarPreOrder = () => {
    const modal = document.getElementById('modal-daftar-preorder');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.renderDaftarPreOrder = () => {
    const container = document.getElementById('container-daftar-preorder');
    const labelTotal = document.getElementById('label-preorder-total');
    if (!container) return;

    // Filter order pre-order yang tersimpan dengan deduplikasi
    const allOrders = Object.values(globalOrders || {});
    const seen = new Set();
    const preOrders = [];

    // Ambil juga dari offline storage dengan pengecekan kode unik
    try {
        const cachedOffline = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (Array.isArray(cachedOffline)) {
            const existingCodes = new Set(allOrders.map(o => String(o.orderId || o.id || '').toUpperCase().trim()).filter(Boolean));
            cachedOffline.forEach(ord => {
                const code = String(ord.orderId || ord.id || '').toUpperCase().trim();
                if (code && !existingCodes.has(code)) {
                    allOrders.push(ord);
                    existingCodes.add(code);
                }
            });
        }
    } catch(e) {}

    allOrders.forEach(ord => {
        if (!ord) return;
        const code = String(ord.orderId || ord.id || '').toUpperCase();
        if (seen.has(code)) return;
        seen.add(code);

        const st = (ord.status || '').toLowerCase().trim();
        const sched = typeof window.getPreOrderSchedule === 'function' ? window.getPreOrderSchedule(ord) : { isPre: false, isHariH: false };
        const isPre = ord.isPreOrder || st === 'preorder' || sched.isPre;

        // Orderan Pre-Order di hari yang sama (Hari H) otomatis masuk ke Tab Masuk bukan di tab/modal pre-order
        if (sched.isHariH) return;

        if (isPre && st !== 'selesai' && st !== 'batal') {
            preOrders.push(ord);
        }
    });

    // Urutkan berdasarkan tanggal & waktu ambil terdekat
    preOrders.sort((a, b) => {
        const dateA = a.pickupDate || '9999-12-31';
        const dateB = b.pickupDate || '9999-12-31';
        if (dateA !== dateB) return dateA.localeCompare(dateB);
        const timeA = a.pickupTime || '23:59';
        const timeB = b.pickupTime || '23:59';
        return timeA.localeCompare(timeB);
    });

    if (labelTotal) {
        labelTotal.innerText = `${preOrders.length} Pesanan Pre-Order Mendatang`;
    }

    // Update badge counter di kasir
    const badgePre = document.getElementById('badge-preorder-count');
    if (badgePre) {
        badgePre.innerText = preOrders.length;
        if (preOrders.length > 0) badgePre.classList.remove('hidden');
        else badgePre.classList.add('hidden');
    }

    if (preOrders.length === 0) {
        container.innerHTML = `
            <div class="py-12 px-4 text-center">
                <div class="w-16 h-16 shrink-0 rounded-3xl bg-amber-100 text-amber-600 flex items-center justify-center text-2xl mx-auto mb-3 shadow-inner">
                    <i class="fa-solid fa-calendar-check"></i>
                </div>
                <h4 class="text-sm font-black text-slate-800 mb-1">Belum Ada Pesanan Pre-Order Mendatang</h4>
                <p class="text-xs text-slate-500 max-w-xs mx-auto">Pesanan Pre-Order hari ini otomatis langsung masuk ke <b>Tab Masuk</b> kasir dengan aksen khusus.</p>
            </div>
        `;
        return;
    }

    let html = '';
    preOrders.forEach(ord => {
        const ordId = ord.orderId || ord.id;
        const custName = ord.namaPelanggan || ord.customerName || 'Pelanggan';
        const custPhone = ord.nomorWa || ord.customerPhone || '-';
        const pickDate = ord.pickupDate || '-';
        const pickTime = ord.pickupTime || '-';
        const subPay = ord.preOrderSubPay || ord.metode || 'Tunai';
        const total = Number(ord.total || ord.totalAmount || 0);
        const preDiskon = Number(ord.diskonVoucher || ord.diskonNominal || ord.discount || 0);
        const preVoucher = ord.voucher || ord.kodeVoucher || ord.namaDiskon || 'Voucher';
        const preSubtotal = Number(ord.subtotal || (total + preDiskon));
        const st = (ord.status || '').toLowerCase().trim();
        const isDispatched = st !== 'preorder';
        const isPayConfirmed = (ord.preOrderPaymentConfirmed === true) || (ord.paymentStatus === 'lunas' && ord.isPaid !== false && ord.paymentStatus !== 'menunggu_konfirmasi');

        const items = Array.isArray(ord.items) ? ord.items : [];
        const itemsListHtml = items.map(it => {
            const qty = Number(it.qty) || 1;
            const nm = it.nama || it.name || 'Menu';
            const varTxt = (it.varian || it.notes) ? ` (${it.varian || it.notes})` : '';
            return `<div class="flex items-center justify-between text-xs py-0.5 text-slate-700">
                <span><b>${qty}x</b> ${nm}${varTxt}</span>
                <span class="font-bold">Rp ${((Number(it.harga || it.price || 0)) * qty).toLocaleString('id-ID')}</span>
            </div>`;
        }).join('');

        html += `
            <div class="p-4 bg-white rounded-2xl border-2 ${isDispatched ? 'border-blue-300 bg-blue-50/20' : (!isPayConfirmed ? 'border-rose-300 bg-rose-50/20' : 'border-amber-300 bg-amber-50/30')} shadow-sm space-y-3">
                <div class="flex items-start justify-between gap-2 border-b border-slate-100 pb-2.5">
                    <div>
                        <div class="flex items-center gap-2 flex-wrap">
                            <span class="text-xs font-black text-slate-900">${custName}</span>
                            <span class="text-[9px] font-black px-2 py-0.5 rounded-full bg-slate-100 text-slate-700 border border-slate-200">${ordId}</span>
                            ${isPayConfirmed ? '<span class="text-[9px] font-black px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 border border-emerald-300"><i class="fa-solid fa-circle-check mr-0.5"></i> LUNAS</span>' : '<span class="text-[9px] font-black px-2 py-0.5 rounded-full bg-rose-100 text-rose-800 border border-rose-200">BELUM KONFIRMASI</span>'}
                            ${isDispatched ? '<span class="text-[9px] font-black px-2 py-0.5 rounded-full bg-blue-100 text-blue-800">Sudah Masuk Antrean</span>' : '<span class="text-[9px] font-black px-2 py-0.5 rounded-full bg-amber-100 text-amber-800">Menunggu Jadwal</span>'}
                        </div>
                        <div class="text-[11px] text-slate-500 font-bold mt-0.5 flex items-center gap-2 flex-wrap">
                            <span><i class="fa-brands fa-whatsapp text-emerald-600"></i> ${custPhone}</span>
                            <span>•</span>
                            ${isPayConfirmed
                                ? `<span class="text-emerald-700 font-black"><i class="fa-solid fa-circle-check"></i> Status Lunas (${subPay})</span>`
                                : `<span class="text-rose-600 font-black"><i class="fa-solid fa-hourglass-half"></i> Menunggu Konfirmasi Bayar (${subPay})</span>`}
                        </div>
                        ${preDiskon > 0 ? `<div class="mt-1 inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-rose-50 border border-rose-200 text-[10px] font-black text-rose-700"><i class="fa-solid fa-tag text-[9px]"></i> Diskon (${preVoucher}): -Rp ${preDiskon.toLocaleString('id-ID')}</div>` : ''}
                    </div>
                    <div class="text-right">
                        <span class="text-[10px] text-slate-500 font-bold block">Total Bayar:</span>
                        ${preDiskon > 0 ? `<span class="text-[10px] text-slate-400 line-through font-bold block">Rp ${preSubtotal.toLocaleString('id-ID')}</span>` : ''}
                        <span class="text-sm font-black ${preDiskon > 0 ? 'text-emerald-600' : 'text-slate-900'}">Rp ${total.toLocaleString('id-ID')}</span>
                    </div>
                </div>

                <div class="p-2.5 bg-white/80 rounded-xl border border-slate-200">
                    <div class="flex items-center gap-2 text-amber-900 font-black text-xs mb-1.5">
                        <i class="fa-solid fa-clock-rotate-left text-amber-600"></i>
                        <span>Jadwal Ambil: <b>${pickDate}</b> pukul <b>${pickTime} WIB</b></span>
                    </div>
                    <div class="divide-y divide-slate-100 pt-1">
                        ${itemsListHtml}
                    </div>
                </div>

                <div class="flex items-center gap-2 pt-1 flex-wrap">
                    ${!isPayConfirmed ? `
                        <button type="button" onclick="window.konfirmasiPembayaranPreOrder('${ordId}')" class="flex-1 min-w-[170px] py-2.5 px-3 bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white font-black text-xs rounded-xl shadow-md transition flex items-center justify-center gap-2 cursor-pointer">
                            <i class="fa-solid fa-money-check-dollar"></i>
                            <span>Konfirmasi Pembayaran</span>
                        </button>
                    ` : ''}
                    ${!isDispatched ? `
                        <button type="button" onclick="window.kirimPreOrderKeTabMasuk('${ordId}')" class="flex-1 min-w-[150px] py-2.5 px-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 active:scale-95 text-white font-black text-xs rounded-xl shadow-md transition flex items-center justify-center gap-2 cursor-pointer">
                            <i class="fa-solid fa-inbox"></i>
                            <span>Masuk ke Tab Masuk</span>
                        </button>
                    ` : `
                        <div class="flex-1 min-w-[150px] py-2 px-3 bg-blue-50 text-blue-700 font-black text-xs rounded-xl text-center border border-blue-200">
                            <i class="fa-solid fa-check"></i> Sudah di Tab Masuk
                        </div>
                    `}
                    ${(() => {
                        const isQrisOrder = /qris|transfer|bank|gopay|ovo|dana|shopee/i.test(subPay);
                        return `
                            <button type="button" onclick="window.kirimBuktiWaPreOrderDirect('${ordId}')" class="px-3 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-black text-xs rounded-xl shadow-xs transition active:scale-95 flex items-center gap-1.5 cursor-pointer" title="${isQrisOrder ? 'Kirim WA Minta Bukti Bayar QRIS' : 'Kirim Bukti Pemesanan Pre-Order ke WhatsApp Pelanggan'}">
                                <i class="fa-brands fa-whatsapp text-sm"></i>
                                <span>${isQrisOrder ? 'Minta Bukti QRIS (WA)' : 'Bukti WA'}</span>
                            </button>
                        `;
                    })()}
                    <button type="button" onclick="window.bukaModalEditPreOrder('${ordId}')" class="px-3 py-2.5 bg-amber-500 hover:bg-amber-600 text-slate-950 font-black text-xs rounded-xl shadow-sm transition active:scale-95 flex items-center gap-1.5 cursor-pointer" title="Edit Menu & Kontak Pre-Order">
                        <i class="fa-solid fa-pen-to-square"></i>
                        <span>Edit</span>
                    </button>
                    <button type="button" onclick="window.printStrukPesanan('${ordId}')" class="p-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs transition active:scale-95" title="Cetak Struk Pre-Order">
                        <i class="fa-solid fa-print"></i>
                    </button>
                </div>
            </div>
        `;
    });

    container.innerHTML = html;
};

window.kirimBuktiWaPreOrderDirect = (orderId) => {
    let order = (typeof globalOrders !== 'undefined' && globalOrders[orderId]) || null;
    if (!order) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            order = cached.find(o => (o.orderId || o.id) === orderId);
        } catch(e) {}
    }
    if (!order) return alert("Data pesanan tidak ditemukan!");
    const draft = window.generatePreOrderWhatsAppDraft(order);
    let hp = String(order.customerPhone || order.nomorWa || order.wa || '').replace(/[^0-9]/g, '');
    if (hp.startsWith('0')) hp = '62' + hp.substring(1);
    if (!hp) {
        hp = prompt("Nomor WhatsApp belum terisi. Masukkan nomor WhatsApp tujuan (contoh: 0812...):");
        if (!hp) return;
        hp = hp.replace(/[^0-9]/g, '');
        if (hp.startsWith('0')) hp = '62' + hp.substring(1);
    }
    window.open(`https://wa.me/${hp}?text=${encodeURIComponent(draft)}`, '_blank');
};

window.konfirmasiPembayaranPreOrder = (orderId, onConfirmedCb = null) => {
    let order = (globalOrders && globalOrders[orderId]) || null;
    let actualKey = orderId;
    if (!order && globalOrders) {
        const entry = Object.entries(globalOrders).find(([, o]) => o && (
            o.orderId === orderId || o.id === orderId || o.firebaseKey === orderId ||
            String(o.orderId || '').toUpperCase() === String(orderId).toUpperCase()
        ));
        if (entry) {
            actualKey = entry[0];
            order = entry[1];
        }
    }
    if (!order) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            order = cached.find(o => o && ((o.orderId || o.id) === orderId || o.firebaseKey === orderId));
        } catch (e) {}
    }
    if (!order) return alert('Data pesanan Pre-Order tidak ditemukan.');

    const oldModal = document.getElementById('modal-konfirmasi-bayar-preorder');
    if (oldModal) oldModal.remove();

    const custName = order.customerName || order.namaPelanggan || 'Pelanggan';
    const orderCode = String(order.orderId || order.id || orderId).toUpperCase();
    const total = Number(order.totalAmount || order.total || 0);
    const curPay = String(order.preOrderSubPay || order.paymentMethod || order.metode || 'QRIS');
    const isQrisDefault = /qris|transfer|bank|gopay|ovo|dana|shopee/i.test(curPay);

    const modalHtml = `
    <div id="modal-konfirmasi-bayar-preorder" class="fixed inset-0 z-[99999] bg-slate-950/75 backdrop-blur-sm flex items-center justify-center p-4 fade-in">
        <div class="bg-white w-full max-w-sm rounded-3xl p-5 shadow-2xl border border-slate-200 space-y-4">
            <div class="flex items-start justify-between gap-2">
                <div class="flex items-center gap-2.5">
                    <div class="w-10 h-10 rounded-2xl bg-emerald-100 text-emerald-700 flex items-center justify-center shrink-0">
                        <i class="fa-solid fa-money-check-dollar text-lg"></i>
                    </div>
                    <div>
                        <h3 class="text-sm font-black text-slate-900">Konfirmasi Bayar Pre-Order</h3>
                        <p class="text-[10px] font-bold text-slate-500">#${orderCode} • ${custName}</p>
                    </div>
                </div>
                <button type="button" onclick="document.getElementById('modal-konfirmasi-bayar-preorder')?.remove()" class="w-8 h-8 shrink-0 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-500 flex items-center justify-center text-xs font-bold">✕</button>
            </div>

            <div class="p-3 rounded-2xl bg-emerald-50 border border-emerald-200 flex items-center justify-between">
                <span class="text-xs font-bold text-emerald-800">Total Tagihan Lunas</span>
                <span class="text-base font-black text-emerald-700">Rp ${total.toLocaleString('id-ID')}</span>
            </div>

            <div class="space-y-2.5">
                <div>
                    <label class="block text-[10px] font-black text-slate-600 uppercase mb-1">Metode Pembayaran Diterima</label>
                    <select id="prepay-method" class="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-black text-slate-800 outline-none focus:border-emerald-500">
                        <option value="QRIS" ${isQrisDefault ? 'selected' : ''}>QRIS / Transfer (Non-Tunai)</option>
                        <option value="Tunai" ${!isQrisDefault ? 'selected' : ''}>Tunai / Cash di Kasir</option>
                    </select>
                </div>
                <div>
                    <label class="block text-[10px] font-black text-slate-600 uppercase mb-1">Catatan Verifikasi (Opsional)</label>
                    <input type="text" id="prepay-note" placeholder="Cth: Bukti transfer / mutasi QRIS sudah dicek" class="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-semibold text-slate-700 outline-none focus:border-emerald-500">
                </div>
            </div>

            <div class="flex items-center gap-2 pt-1">
                <button type="button" onclick="document.getElementById('modal-konfirmasi-bayar-preorder')?.remove()" class="flex-1 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold transition">Batal</button>
                <button type="button" id="btn-submit-prepay-confirm" class="flex-1 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-black shadow-md transition active:scale-95">
                    <i class="fa-solid fa-circle-check mr-1"></i> Konfirmasi Lunas
                </button>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', modalHtml);

    const submitBtn = document.getElementById('btn-submit-prepay-confirm');
    if (submitBtn) {
        submitBtn.onclick = async () => {
            const payChosen = document.getElementById('prepay-method')?.value || 'QRIS';
            const noteChosen = (document.getElementById('prepay-note')?.value || '').trim();
            const officer = String(localStorage.getItem('mainstay_staff_name') || 'Kasir').replace(/\s*\(\s*master\s*\)/i, '').trim() || 'Kasir';
            const confirmedAt = Date.now();
            const patch = {
                isPaid: true,
                paymentStatus: 'lunas',
                preOrderPaymentConfirmed: true,
                preOrderSubPay: payChosen,
                metode: `PreOrder (${payChosen})`,
                paymentMethod: `PreOrder (${payChosen})`,
                preOrderConfirmedBy: officer,
                preOrderConfirmedAt: confirmedAt,
                ...(noteChosen ? { preOrderPaymentNote: noteChosen } : {})
            };

            Object.assign(order, patch);
            if (globalOrders) {
                Object.values(globalOrders).forEach(o => {
                    if (o && (o.orderId === orderCode || o.id === order.id || o.firebaseKey === actualKey)) {
                        Object.assign(o, patch);
                    }
                });
            }
            try {
                let saved = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
                if (Array.isArray(saved)) {
                    saved = saved.map(o => (o && (o.orderId === orderCode || o.id === order.id)) ? { ...o, ...patch } : o);
                    localStorage.setItem('mainstay_offline_orders', JSON.stringify(saved));
                }
            } catch (e) {}

            if (navigator.onLine && typeof db !== 'undefined') {
                try {
                    await update(ref(db, `orders/${actualKey}`), patch);
                    if (order.firebaseKey && order.firebaseKey !== actualKey) {
                        await update(ref(db, `orders/${order.firebaseKey}`), patch);
                    }
                } catch (e) { console.warn('Confirm preorder payment RTDB:', e); }
            }

            document.getElementById('modal-konfirmasi-bayar-preorder')?.remove();
            if (typeof window.renderDaftarPreOrder === 'function') window.renderDaftarPreOrder();
            if (typeof window.renderKasirOrders === 'function') window.renderKasirOrders();
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi(`Pembayaran Pre-Order #${orderCode} (${payChosen}) dikonfirmasi LUNAS!`, 'success');
            }
            if (typeof onConfirmedCb === 'function') {
                onConfirmedCb();
            }
        };
    }
};

window.kirimPreOrderKeTabMasuk = async (orderId) => {
    let order = globalOrders[orderId];
    if (!order) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            order = cached.find(o => (o.orderId || o.id) === orderId);
        } catch(e) {}
    }
    if (!order) {
        alert("Data pesanan tidak ditemukan.");
        return;
    }

    order.status = 'pending';
    order.timestamp = Date.now();
    order.dispatchedFromPreOrder = true;

    globalOrders[orderId] = order;
    if (typeof window.globalOrders === 'object') {
        window.globalOrders[orderId] = order;
    }

    // Update RTDB Firebase jika online
    if (navigator.onLine && typeof db !== 'undefined') {
        try {
            await update(ref(db, `orders/${orderId}`), {
                status: 'pending',
                timestamp: Date.now(),
                dispatchedFromPreOrder: true
            });
        } catch(e) {
            console.warn("RTDB dispatch pre-order error:", e);
        }
    }

    // Update local storage
    try {
        let cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (Array.isArray(cached)) {
            const idx = cached.findIndex(o => (o.orderId || o.id) === orderId);
            if (idx >= 0) {
                cached[idx].status = 'pending';
                cached[idx].timestamp = Date.now();
                cached[idx].dispatchedFromPreOrder = true;
            } else {
                cached.unshift(order);
            }
            localStorage.setItem('mainstay_offline_orders', JSON.stringify(cached));
        }
    } catch(e) {}

    if (typeof window.tutupModalDaftarPreOrder === 'function') {
        window.tutupModalDaftarPreOrder();
    }

    if (typeof window.switchKasirTab === 'function') {
        window.switchKasirTab('tab-pending');
    }

    if (typeof window.playOrderNotificationSound === 'function') {
        window.playOrderNotificationSound();
    }

    window.renderDaftarPreOrder();
    if (typeof window.renderKasirOrders === 'function') {
        window.renderKasirOrders();
    }

    if (typeof window.showNotification === 'function') {
        window.showNotification(`Pesanan Pre-Order ${orderId} berhasil dimasukkan ke Tab Masuk!`, 'success');
    } else {
        alert(`Pesanan Pre-Order ${orderId} berhasil dimasukkan ke Tab Masuk!`);
    }
};

// Alias kompatibilitas
window.kirimPreOrderKeDapur = window.kirimPreOrderKeTabMasuk;

