// ============================================================================
// CONTROLLER: EDIT PESANAN PRE-ORDER (MENU, TOPPING, JADWAL & KONTAK)
// ============================================================================
window._editingPreOrder = null;
window._editingPreOrderId = null;
window._editingPreOrderActualKey = null;
window._lastAddedPreOrderIdx = null;
window._isRemovingPreOrderItem = false;

const normalizePreOrderItemsArray = (rawItems) => {
    const arr = Array.isArray(rawItems)
        ? rawItems.filter(Boolean)
        : (rawItems && typeof rawItems === 'object' ? Object.values(rawItems).filter(Boolean) : []);

    const knownToppingPriceMap = {
        'boba': 3000,
        'jelly': 3000,
        'cheese cream': 5000,
        'pudding': 4000,
        'oreo crumb': 3000,
        'nata de coco': 3000
    };

    return arr.map((it) => {
        const qty = Math.max(1, Number(it.qty) || 1);
        const rawToppings = Array.isArray(it.toppings)
            ? it.toppings
            : (typeof it.toppings === 'string'
                ? it.toppings.split(',').map(s => s.trim()).filter(Boolean)
                : (it.toppings && typeof it.toppings === 'object' ? Object.values(it.toppings).filter(Boolean) : []));

        let toppingsCost = 0;
        rawToppings.forEach(t => {
            if (t && typeof t === 'object' && t.price !== undefined) {
                toppingsCost += Number(t.price) || 0;
            } else {
                const nm = String(typeof t === 'object' ? (t.name || '') : t).toLowerCase().trim();
                toppingsCost += knownToppingPriceMap[nm] || 0;
            }
        });

        const unitPrice = Number(
            it.harga !== undefined ? it.harga
            : (it.price !== undefined ? it.price
            : (it.total !== undefined ? Math.round((Number(it.total) || 0) / qty) : 0))
        ) || 0;

        const basePrice = (it.basePrice !== undefined && it.basePrice !== null)
            ? Number(it.basePrice) || 0
            : (it.hargaAwal !== undefined && it.hargaAwal !== null
                ? Number(it.hargaAwal) || 0
                : Math.max(0, unitPrice - toppingsCost));

        const cleanName = String(it.nama || it.name || 'Menu');
        const cleanVarian = String(it.varian || it.notes || 'Normal Ice');

        return {
            ...it,
            name: cleanName,
            nama: cleanName,
            qty,
            price: unitPrice,
            harga: unitPrice,
            basePrice,
            total: unitPrice * qty,
            varian: cleanVarian,
            notes: cleanVarian,
            toppings: rawToppings
        };
    });
};

window.bukaModalEditPreOrder = (orderId) => {
    let order = (typeof globalOrders === 'object' && globalOrders) ? globalOrders[orderId] : null;
    let actualKey = orderId;
    if (!order && typeof globalOrders === 'object' && globalOrders) {
        const foundEntry = Object.entries(globalOrders).find(([, o]) => o && (
            o.orderId === orderId ||
            o.id === orderId ||
            o.firebaseKey === orderId ||
            String(o.orderId || '').toUpperCase() === String(orderId || '').toUpperCase()
        ));
        if (foundEntry) {
            actualKey = foundEntry[0];
            order = foundEntry[1];
        }
    }
    if (!order) {
        try {
            const cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
            order = cached.find(o => o && ((o.orderId || o.id) === orderId || o.firebaseKey === orderId));
        } catch(e) {}
    }
    if (!order) {
        window.tampilkanNotifikasi('Data pesanan Pre-Order tidak ditemukan.', 'error');
        return;
    }

    window._editingPreOrderId = orderId;
    window._editingPreOrderActualKey = actualKey || orderId;
    window._editingPreOrder = JSON.parse(JSON.stringify(order));
    window._editingPreOrder.items = normalizePreOrderItemsArray(window._editingPreOrder.items);
    window._lastAddedPreOrderIdx = null;
    window._isRemovingPreOrderItem = false;

    const modal = document.getElementById('modal-edit-preorder');
    if (!modal) {
        window.tampilkanNotifikasi('Modal Edit Pre-Order tidak ditemukan.', 'error');
        return;
    }

    modal.dataset.activePreOrderId = String(actualKey || orderId);

    const badgeId = modal.querySelector('#edit-preorder-id-badge');
    const inputNama = modal.querySelector('#edit-preorder-nama');
    const inputWa = modal.querySelector('#edit-preorder-wa');
    const inputDate = modal.querySelector('#edit-preorder-date');
    const inputTime = modal.querySelector('#edit-preorder-time');
    const btnTambahMenu = modal.querySelector('#btn-edit-preorder-tambah-menu');
    const validationBanner = modal.querySelector('#edit-preorder-validation-error');

    if (badgeId) badgeId.innerText = order.orderId || order.id || orderId;
    if (inputNama) inputNama.value = order.namaPelanggan || order.customerName || '';
    if (inputWa) inputWa.value = order.nomorWa || order.customerPhone || '';
    if (inputDate) inputDate.value = order.pickupDate || '';
    if (inputTime) inputTime.value = order.pickupTime || '';
    if (validationBanner) validationBanner.classList.add('hidden');

    [inputNama, inputWa, inputDate, inputTime].forEach((fieldEl) => {
        if (!fieldEl) return;
        fieldEl.classList.remove('border-rose-500', 'ring-2', 'ring-rose-200', 'bg-rose-50/40');
        if (fieldEl.dataset.boundPreOrderValidation !== '1') {
            const onFieldEdit = () => window.validasiFormEditPreOrder(false);
            fieldEl.addEventListener('input', onFieldEdit);
            fieldEl.addEventListener('change', onFieldEdit);
            fieldEl.dataset.boundPreOrderValidation = '1';
        }
    });

    // Bind tombol "+ Tambah Menu" satu kali per instance DOM modal aktif (tanpa duplikasi / tertimpa)
    if (btnTambahMenu && btnTambahMenu.dataset.boundPreOrderAdd !== '1') {
        btnTambahMenu.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const currentModal = btnTambahMenu.closest('#modal-edit-preorder') || document.getElementById('modal-edit-preorder');
            window.tambahItemKePreOrderEdit(currentModal);
        });
        btnTambahMenu.dataset.boundPreOrderAdd = '1';
    }

    window.renderItemsPreOrderEditor();
    window.validasiFormEditPreOrder(false);

    modal.classList.remove('hidden');
    modal.classList.add('flex');
};

window.validasiFormEditPreOrder = (showErrors = true) => {
    const modal = document.getElementById('modal-edit-preorder');
    if (!modal) return { valid: false, errors: ['Modal Edit Pre-Order tidak ditemukan.'], firstInvalidEl: null };

    const inputNama = modal.querySelector('#edit-preorder-nama');
    const inputWa = modal.querySelector('#edit-preorder-wa');
    const inputDate = modal.querySelector('#edit-preorder-date');
    const inputTime = modal.querySelector('#edit-preorder-time');
    const itemsBox = modal.querySelector('#edit-preorder-items-list');
    const banner = modal.querySelector('#edit-preorder-validation-error');
    const bannerText = modal.querySelector('#edit-preorder-validation-text');
    const btnSave = modal.querySelector('#btn-simpan-edit-preorder');

    const namaVal = (inputNama?.value || '').trim();
    const waVal = (inputWa?.value || '').trim();
    const waDigits = waVal.replace(/\D/g, '');
    const dateVal = (inputDate?.value || '').trim();
    const timeVal = (inputTime?.value || '').trim();
    const items = normalizePreOrderItemsArray(window._editingPreOrder?.items);

    const isNamaValid = Boolean(namaVal && namaVal.length >= 2 && namaVal.toLowerCase() !== 'hamba allah');
    const isWaValid = Boolean(waDigits.length >= 8 && waDigits.length <= 15);
    const isDateValid = Boolean(dateVal && /^\d{4}-\d{2}-\d{2}$/.test(dateVal));
    const isTimeValid = Boolean(timeVal && /^\d{2}:\d{2}/.test(timeVal));
    const isItemsValid = Boolean(
        items.length >= 1 &&
        items.every(it => String(it.nama || it.name || '').trim().length > 0 && Number(it.qty) >= 1)
    );

    const errors = [];
    let firstInvalidEl = null;

    const markFieldState = (el, valid) => {
        if (!el) return;
        if (valid) {
            el.classList.remove('border-rose-500', 'ring-2', 'ring-rose-200', 'bg-rose-50/40');
            el.removeAttribute('aria-invalid');
        } else if (showErrors) {
            el.classList.add('border-rose-500', 'ring-2', 'ring-rose-200', 'bg-rose-50/40');
            el.setAttribute('aria-invalid', 'true');
        }
    };

    markFieldState(inputNama, isNamaValid);
    if (!isNamaValid) {
        errors.push('Nama pemesan wajib diisi minimal 2 karakter.');
        if (!firstInvalidEl) firstInvalidEl = inputNama;
    }

    markFieldState(inputWa, isWaValid);
    if (!isWaValid) {
        errors.push('Nomor WhatsApp pemesan wajib diisi (8-15 digit angka).');
        if (!firstInvalidEl) firstInvalidEl = inputWa;
    }

    markFieldState(inputDate, isDateValid);
    if (!isDateValid) {
        errors.push('Tanggal pengambilan Pre-Order wajib dipilih.');
        if (!firstInvalidEl) firstInvalidEl = inputDate;
    }

    markFieldState(inputTime, isTimeValid);
    if (!isTimeValid) {
        errors.push('Jam pengambilan Pre-Order wajib dipilih.');
        if (!firstInvalidEl) firstInvalidEl = inputTime;
    }

    if (itemsBox) {
        if (isItemsValid) {
            itemsBox.classList.remove('ring-2', 'ring-rose-300', 'rounded-2xl', 'p-1');
        } else if (showErrors) {
            itemsBox.classList.add('ring-2', 'ring-rose-300', 'rounded-2xl', 'p-1');
        }
    }
    if (!isItemsValid) {
        errors.push('Pesanan harus memiliki minimal 1 item menu dengan jumlah valid.');
        if (!firstInvalidEl) firstInvalidEl = modal.querySelector('#btn-edit-preorder-tambah-menu') || itemsBox;
    }

    const isAllValid = errors.length === 0;

    if (btnSave) {
        if (!isItemsValid || !isNamaValid || !isWaValid || !isDateValid || !isTimeValid) {
            btnSave.setAttribute('aria-disabled', 'true');
            btnSave.classList.toggle('opacity-75', !isItemsValid);
        } else {
            btnSave.removeAttribute('aria-disabled');
            btnSave.classList.remove('opacity-75');
        }
    }

    if (banner && bannerText) {
        if (!isAllValid && showErrors) {
            bannerText.innerText = errors[0];
            banner.classList.remove('hidden');
        } else if (isAllValid) {
            banner.classList.add('hidden');
        }
    }

    return { valid: isAllValid, errors, firstInvalidEl };
};

window.renderItemsPreOrderEditor = () => {
    const modal = document.getElementById('modal-edit-preorder');
    const container = modal ? modal.querySelector('#edit-preorder-items-list') : document.getElementById('edit-preorder-items-list');
    const totalEl = modal ? modal.querySelector('#edit-preorder-total-display') : document.getElementById('edit-preorder-total-display');
    const countBadge = modal ? modal.querySelector('#edit-preorder-items-count') : document.getElementById('edit-preorder-items-count');
    const pickerStatus = document.getElementById('preorder-picker-status-text');
    if (!container || !window._editingPreOrder) return;

    if (!Array.isArray(window._editingPreOrder.items)) {
        window._editingPreOrder.items = normalizePreOrderItemsArray(window._editingPreOrder.items);
    }

    const items = window._editingPreOrder.items;
    let runningSubtotal = 0;
    let totalQty = 0;

    const defaultToppings = [
        { name: 'Boba', price: 3000 },
        { name: 'Jelly', price: 3000 },
        { name: 'Cheese Cream', price: 5000 },
        { name: 'Pudding', price: 4000 },
        { name: 'Oreo Crumb', price: 3000 },
        { name: 'Nata de Coco', price: 3000 }
    ];

    const diskon = Number(window._editingPreOrder.diskonVoucher || window._editingPreOrder.diskonNominal || window._editingPreOrder.discount || 0);

    if (items.length === 0) {
        window._lastAddedPreOrderIdx = null;
        window._editingPreOrder.subtotal = 0;
        window._editingPreOrder.total = 0;
        window._editingPreOrder.totalAmount = 0;
        container.innerHTML = `
            <div class="preorder-item-card preorder-item-enter p-4 bg-rose-50/70 border border-dashed border-rose-300 rounded-2xl text-center text-xs text-rose-700 font-bold">
                <i class="fa-solid fa-triangle-exclamation mr-1"></i> Item pesanan kosong. Klik tombol "+ Tambah Menu" di atas untuk menambahkan minimal 1 produk sebelum menyimpan.
            </div>
        `;
        if (countBadge) countBadge.innerText = '0 item';
        if (pickerStatus) pickerStatus.innerText = 'Pesanan: 0 item';
        if (totalEl) totalEl.innerText = "Rp 0";
        window.validasiFormEditPreOrder(false);
        return;
    }

    const newlyAddedIdx = window._lastAddedPreOrderIdx;
    let html = '';
    items.forEach((item, idx) => {
        const qty = Math.max(1, Number(item.qty) || 1);
        const price = Number(item.harga ?? item.price ?? 0);
        const itemSubtotal = price * qty;
        item.qty = qty;
        item.harga = price;
        item.price = price;
        item.total = itemSubtotal;

        runningSubtotal += itemSubtotal;
        totalQty += qty;

        const currentToppings = Array.isArray(item.toppings) ? item.toppings : [];
        const cleanName = String(item.nama || item.name || 'Menu');
        const currentVarian = String(item.varian || item.notes || 'Normal Ice');
        const stdVariants = ['Normal Ice', 'Less Ice', 'Hot / Hangat', 'No Ice'];
        const hasCustomVariant = currentVarian && !stdVariants.includes(currentVarian);
        const enterAnimClass = newlyAddedIdx === idx ? ' preorder-item-enter' : '';

        const toppingsChips = defaultToppings.map(t => {
            const isSelected = currentToppings.some(ct => String(typeof ct === 'object' ? (ct.name || '') : ct).toLowerCase() === t.name.toLowerCase());
            return `
                <button type="button" onclick="window.toggleToppingItemPreOrderEdit(${idx}, '${t.name}', ${t.price})" class="px-2 py-0.5 rounded-md text-[10px] font-black border transition ${isSelected ? 'bg-amber-500 text-slate-950 border-amber-600 shadow-2xs' : 'bg-slate-100 hover:bg-slate-200 text-slate-600 border-slate-200'}">
                    ${isSelected ? '✓ ' : '+ '}${t.name} (+Rp ${t.price.toLocaleString('id-ID')})
                </button>
            `;
        }).join('');

        html += `
            <div class="preorder-item-card${enterAnimClass} p-3 bg-slate-50 border border-slate-200 rounded-2xl space-y-2" data-preorder-item-idx="${idx}">
                <div class="flex items-start justify-between gap-2">
                    <div class="min-w-0">
                        <span class="text-xs font-black text-slate-900 block truncate">${cleanName}</span>
                        <span class="text-[10px] font-bold text-slate-500">Harga Satuan: Rp ${price.toLocaleString('id-ID')}</span>
                    </div>
                    <button type="button" onclick="window.hapusItemPreOrderEdit(${idx})" class="w-6 h-6 shrink-0 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-600 flex items-center justify-center text-xs transition active:scale-90" title="Hapus Item">
                        <i class="fa-solid fa-trash-can"></i>
                    </button>
                </div>

                <div class="flex items-center justify-between gap-2 pt-1 border-t border-slate-200">
                    <div class="flex items-center gap-1.5">
                        <span class="text-[10px] font-bold text-slate-600 uppercase">Jumlah:</span>
                        <div class="flex items-center bg-white border border-slate-300 rounded-lg overflow-hidden">
                            <button type="button" onclick="window.ubahQtyItemPreOrderEdit(${idx}, -1)" class="w-7 h-7 shrink-0 bg-slate-100 hover:bg-slate-200 text-slate-700 font-black text-xs flex items-center justify-center">-</button>
                            <span class="w-8 text-center text-xs font-black text-slate-900">${qty}</span>
                            <button type="button" onclick="window.ubahQtyItemPreOrderEdit(${idx}, 1)" class="w-7 h-7 shrink-0 bg-slate-100 hover:bg-slate-200 text-slate-700 font-black text-xs flex items-center justify-center">+</button>
                        </div>
                    </div>
                    <div class="text-right">
                        <span class="text-[9px] font-bold text-slate-400 block">Subtotal:</span>
                        <span class="text-xs font-black text-indigo-700">Rp ${itemSubtotal.toLocaleString('id-ID')}</span>
                    </div>
                </div>

                <!-- Pilihan Varian & Catatan -->
                <div class="pt-1 border-t border-slate-200">
                    <label class="block text-[9px] font-black uppercase text-slate-500 mb-1">Pilihan Varian / Ice:</label>
                    <select onchange="window.ubahVarianItemPreOrderEdit(${idx}, this.value)" class="w-full bg-white border border-slate-200 p-1.5 rounded-lg text-xs font-bold text-slate-800 outline-none">
                        ${hasCustomVariant ? `<option value="${currentVarian.replace(/"/g, '&quot;')}" selected>${currentVarian}</option>` : ''}
                        <option value="Normal Ice" ${currentVarian === 'Normal Ice' ? 'selected' : ''}>Normal Ice</option>
                        <option value="Less Ice" ${currentVarian === 'Less Ice' ? 'selected' : ''}>Less Ice</option>
                        <option value="Hot / Hangat" ${currentVarian === 'Hot / Hangat' ? 'selected' : ''}>Hot / Hangat</option>
                        <option value="No Ice" ${currentVarian === 'No Ice' ? 'selected' : ''}>No Ice</option>
                    </select>
                </div>

                <!-- Topping Selection -->
                <div class="pt-1 border-t border-slate-200">
                    <label class="block text-[9px] font-black uppercase text-slate-500 mb-1">Topping:</label>
                    <div class="flex flex-wrap gap-1">
                        ${toppingsChips}
                    </div>
                </div>
            </div>
        `;
    });

    const finalDisplayTotal = Math.max(0, runningSubtotal - diskon);
    window._editingPreOrder.subtotal = runningSubtotal;
    window._editingPreOrder.total = finalDisplayTotal;
    window._editingPreOrder.totalAmount = finalDisplayTotal;
    window._lastAddedPreOrderIdx = null;

    container.innerHTML = html;
    if (countBadge) countBadge.innerText = `${items.length} menu (${totalQty} porsi)`;
    if (pickerStatus) pickerStatus.innerText = `Pesanan: ${items.length} menu (${totalQty} porsi) • Rp ${finalDisplayTotal.toLocaleString('id-ID')}`;
    if (totalEl) totalEl.innerText = `Rp ${finalDisplayTotal.toLocaleString('id-ID')}`;
    window.validasiFormEditPreOrder(false);
};

window.ubahQtyItemPreOrderEdit = (idx, delta) => {
    if (!window._editingPreOrder || !Array.isArray(window._editingPreOrder.items)) return;
    const item = window._editingPreOrder.items[idx];
    if (!item) return;

    let q = Number(item.qty) || 1;
    q += delta;
    if (q <= 0) {
        window.hapusItemPreOrderEdit(idx);
    } else {
        item.qty = q;
        item.total = (Number(item.harga ?? item.price ?? 0)) * q;
        window.renderItemsPreOrderEditor();
    }
};

window.ubahVarianItemPreOrderEdit = (idx, val) => {
    if (!window._editingPreOrder || !Array.isArray(window._editingPreOrder.items)) return;
    const item = window._editingPreOrder.items[idx];
    if (!item) return;
    item.varian = val;
    item.notes = val;
};

window.toggleToppingItemPreOrderEdit = (idx, toppingName, toppingPrice) => {
    if (!window._editingPreOrder || !Array.isArray(window._editingPreOrder.items)) return;
    const item = window._editingPreOrder.items[idx];
    if (!item) return;

    if (!Array.isArray(item.toppings)) item.toppings = [];
    const existIdx = item.toppings.findIndex(t => String(typeof t === 'object' ? (t.name || '') : t).toLowerCase() === String(toppingName).toLowerCase());
    const minBasePrice = (item.basePrice !== undefined && item.basePrice !== null)
        ? Number(item.basePrice) || 0
        : (item.hargaAwal !== undefined && item.hargaAwal !== null ? Number(item.hargaAwal) || 0 : 0);

    if (existIdx >= 0) {
        item.toppings.splice(existIdx, 1);
        item.harga = Math.max(minBasePrice, (Number(item.harga ?? item.price ?? 0) - toppingPrice));
        item.price = item.harga;
    } else {
        item.toppings.push({ name: toppingName, price: toppingPrice });
        item.harga = Number(item.harga ?? item.price ?? 0) + toppingPrice;
        item.price = item.harga;
    }
    item.total = item.harga * (Number(item.qty) || 1);

    window.renderItemsPreOrderEditor();
};

window.hapusItemPreOrderEdit = (idx) => {
    if (!window._editingPreOrder || !Array.isArray(window._editingPreOrder.items)) return;
    if (window._isRemovingPreOrderItem) return;
    if (idx < 0 || idx >= window._editingPreOrder.items.length) return;

    const editModal = document.getElementById('modal-edit-preorder');
    const listContainer = editModal ? editModal.querySelector('#edit-preorder-items-list') : document.getElementById('edit-preorder-items-list');
    const row = listContainer ? listContainer.querySelector(`[data-preorder-item-idx="${idx}"]`) : null;
    const prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (row && !prefersReducedMotion) {
        window._isRemovingPreOrderItem = true;
        row.dataset.removing = '1';
        row.classList.remove('preorder-item-enter');
        row.classList.add('preorder-item-exit');
        setTimeout(() => {
            window._isRemovingPreOrderItem = false;
            if (!window._editingPreOrder || !Array.isArray(window._editingPreOrder.items)) return;
            window._editingPreOrder.items.splice(idx, 1);
            window.renderItemsPreOrderEditor();
        }, 210);
    } else {
        window._editingPreOrder.items.splice(idx, 1);
        window.renderItemsPreOrderEditor();
    }
};

window.tambahItemKePreOrderEdit = (sourceElOrModal = null) => {
    let editModal = null;
    if (sourceElOrModal instanceof HTMLElement) {
        editModal = sourceElOrModal.id === 'modal-edit-preorder'
            ? sourceElOrModal
            : sourceElOrModal.closest('#modal-edit-preorder');
    }
    if (!editModal) {
        editModal = document.getElementById('modal-edit-preorder');
    }
    if (!editModal || editModal.classList.contains('hidden')) {
        window.tampilkanNotifikasi('Modal Edit Pre-Order tidak aktif.', 'error');
        return;
    }

    const pickerModal = document.getElementById('modal-pilih-menu-preorder');
    if (!pickerModal) {
        window.tampilkanNotifikasi('Modal pilih menu Pre-Order tidak ditemukan.', 'error');
        return;
    }

    if (!window._editingPreOrder) {
        window._editingPreOrder = { items: [] };
    } else if (!Array.isArray(window._editingPreOrder.items)) {
        window._editingPreOrder.items = normalizePreOrderItemsArray(window._editingPreOrder.items);
    }

    // Sinkronkan field form terkini tanpa menimpa daftar items yang sudah ada
    const namaInput = editModal.querySelector('#edit-preorder-nama');
    const waInput = editModal.querySelector('#edit-preorder-wa');
    const dateInput = editModal.querySelector('#edit-preorder-date');
    const timeInput = editModal.querySelector('#edit-preorder-time');
    if (namaInput) window._editingPreOrder.namaPelanggan = namaInput.value.trim();
    if (waInput) window._editingPreOrder.nomorWa = waInput.value.trim();
    if (dateInput) window._editingPreOrder.pickupDate = dateInput.value.trim();
    if (timeInput) window._editingPreOrder.pickupTime = timeInput.value.trim();

    pickerModal.dataset.sourceEditModalId = editModal.id;
    pickerModal.dataset.targetOrderId = String(editModal.dataset.activePreOrderId || window._editingPreOrderId || '');

    const searchInput = pickerModal.querySelector('#cari-menu-preorder-input');
    if (searchInput) searchInput.value = '';
    pickerModal.classList.remove('hidden');
    pickerModal.classList.add('flex');
    window.renderListPilihMenuPreOrder('');
    setTimeout(() => {
        if (searchInput) searchInput.focus();
    }, 60);
};

window.eksekusiSimpanPerubahanPreOrder = async () => {
    const orderId = window._editingPreOrderId;
    if (!orderId || !window._editingPreOrder) {
        window.tutupModalEditPreOrder();
        return;
    }

    const validation = window.validasiFormEditPreOrder(true);
    if (!validation.valid) {
        window.tampilkanNotifikasi(validation.errors[0] || "Lengkapi seluruh data pesanan dan minimal 1 menu.", "error");
        if (validation.firstInvalidEl && typeof validation.firstInvalidEl.focus === 'function') {
            try {
                validation.firstInvalidEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                validation.firstInvalidEl.focus();
            } catch (e) {}
        }
        return;
    }

    const editModal = document.getElementById('modal-edit-preorder');
    const inputNama = (editModal?.querySelector('#edit-preorder-nama')?.value || '').trim();
    const inputWa = (editModal?.querySelector('#edit-preorder-wa')?.value || '').trim();
    const inputDate = (editModal?.querySelector('#edit-preorder-date')?.value || '').trim();
    const inputTime = (editModal?.querySelector('#edit-preorder-time')?.value || '').trim();

    const items = normalizePreOrderItemsArray(window._editingPreOrder.items);

    let newSubtotal = 0;
    items.forEach(it => {
        const qty = Math.max(1, Number(it.qty) || 1);
        const unitPrice = Number(it.harga ?? it.price ?? 0);
        it.qty = qty;
        it.harga = unitPrice;
        it.price = unitPrice;
        it.total = unitPrice * qty;
        newSubtotal += it.total;
    });

    const diskon = Number(window._editingPreOrder.diskonVoucher || window._editingPreOrder.diskonNominal || window._editingPreOrder.discount || 0);
    const finalTotal = Math.max(0, newSubtotal - diskon);

    const updated = {
        ...window._editingPreOrder,
        namaPelanggan: inputNama,
        customerName: inputNama,
        nomorWa: inputWa,
        customerPhone: inputWa,
        pickupDate: inputDate,
        pickupTime: inputTime,
        items: items,
        subtotal: newSubtotal,
        total: finalTotal,
        totalAmount: finalTotal,
        bayar: finalTotal,
        lastEditedAt: new Date().toISOString()
    };

    const actualKey = window._editingPreOrderActualKey || orderId;
    if (typeof globalOrders === 'object' && globalOrders) {
        globalOrders[actualKey] = updated;
        if (orderId !== actualKey && globalOrders[orderId]) {
            globalOrders[orderId] = updated;
        }
    }
    if (typeof window.globalOrders === 'object' && window.globalOrders) {
        window.globalOrders[actualKey] = updated;
        if (orderId !== actualKey && window.globalOrders[orderId]) {
            window.globalOrders[orderId] = updated;
        }
    }

    try {
        let cached = JSON.parse(localStorage.getItem('mainstay_offline_orders') || '[]');
        if (Array.isArray(cached)) {
            cached = cached.map(o => (o && ((o.orderId || o.id) === orderId || o.firebaseKey === actualKey)) ? { ...o, ...updated } : o);
            localStorage.setItem('mainstay_offline_orders', JSON.stringify(cached));
        }
    } catch(e) {}

    if (navigator.onLine && typeof db !== 'undefined' && typeof update === 'function') {
        try {
            const payload = window.sanitizeForFirebase(updated);
            await update(ref(db, `orders/${actualKey}`), payload);
            if (updated.firebaseKey && updated.firebaseKey !== actualKey) {
                await update(ref(db, `orders/${updated.firebaseKey}`), payload);
            }
            await update(ref(db, `transaksi/${actualKey}`), payload);
        } catch(err) {
            console.warn("Gagal update cloud pre-order:", err);
        }
    }

    window.tutupModalEditPreOrder();
    if (typeof window.renderDaftarPreOrder === 'function') {
        window.renderDaftarPreOrder();
    }
    if (typeof window.renderKasirOrders === 'function') {
        window.renderKasirOrders();
    }
    if (typeof window.playScannerBeep === 'function') window.playScannerBeep('success');
    window.tampilkanNotifikasi('Perubahan Pre-Order berhasil disimpan!', 'success');
};

window.tutupModalEditPreOrder = () => {
    const modal = document.getElementById('modal-edit-preorder');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        delete modal.dataset.activePreOrderId;
        const validationBanner = modal.querySelector('#edit-preorder-validation-error');
        if (validationBanner) validationBanner.classList.add('hidden');
    }
    window._editingPreOrder = null;
    window._editingPreOrderId = null;
    window._editingPreOrderActualKey = null;
    window._lastAddedPreOrderIdx = null;
    window._isRemovingPreOrderItem = false;
};

// ============================================================================
// CONTROLLER: GOOGLE MAPS DENGAN KONVERSI OTOMATIS SEGALA FORMAT (BEBAS GAGAL)
// ============================================================================
window.convertAnyMapsUrlToEmbed = (raw) => {
    if (!raw || !String(raw).trim()) {
        return "https://maps.google.com/maps?q=-6.9412973,110.5089463&t=&z=18&ie=UTF8&iwloc=&output=embed";
    }

    let input = String(raw).trim();

    // 1. Ekstrak src jika pengguna menempelkan kode tag <iframe> lengkap
    const iframeMatch = input.match(/src=["']([^"']+)["']/i);
    if (iframeMatch && iframeMatch[1]) {
        input = iframeMatch[1].trim();
    }

    // 2. Jika sudah ada parameter output=embed atau /maps/embed
    if (input.includes('output=embed') || input.includes('/maps/embed')) {
        return input;
    }

    // 3. Ekstrak koordinat 3d dan 4d dari link panjang Google Maps
    const dCoordMatch = input.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/);
    if (dCoordMatch) {
        return `https://maps.google.com/maps?q=${dCoordMatch[1]},${dCoordMatch[2]}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
    }

    // 4. Ekstrak koordinat @lat,lng
    const atCoordMatch = input.match(/@(-?\d+\.\d+),\s*(-?\d+\.\d+)/);
    if (atCoordMatch) {
        return `https://maps.google.com/maps?q=${atCoordMatch[1]},${atCoordMatch[2]}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
    }

    // 5. Ekstrak parameter koordinat ll=lat,lng atau center=lat,lng
    const llMatch = input.match(/[?&](?:ll|center)=(-?\d+\.\d+),(-?\d+\.\d+)/);
    if (llMatch) {
        return `https://maps.google.com/maps?q=${llMatch[1]},${llMatch[2]}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
    }

    // 6. Ekstrak koordinat langsung: -6.9412973, 110.5089463
    const directCoordMatch = input.match(/^(-?\d+\.\d+)[,\s]+(-?\d+\.\d+)$/);
    if (directCoordMatch) {
        return `https://maps.google.com/maps?q=${directCoordMatch[1]},${directCoordMatch[2]}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
    }

    // 7. Ekstrak nama tempat /place/Nama+Tempat/
    const placeMatch = input.match(/\/place\/([^/@?]+)/);
    if (placeMatch && placeMatch[1]) {
        const placeName = decodeURIComponent(placeMatch[1]).replace(/\+/g, ' ');
        return `https://maps.google.com/maps?q=${encodeURIComponent(placeName)}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
    }

    // 8. Ekstrak query parameter q=...
    const qParamMatch = input.match(/[?&]q=([^&]+)/);
    if (qParamMatch && qParamMatch[1]) {
        const query = decodeURIComponent(qParamMatch[1]);
        if (!query.startsWith('http')) {
            return `https://maps.google.com/maps?q=${encodeURIComponent(query)}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
        }
    }

    // 9. Shortlink Google Maps (maps.app.goo.gl atau goo.gl/maps)
    // Catatan: Google memblokir render langsung shortlink di iframe (X-Frame-Options SAMEORIGIN).
    // Oleh karena itu, kita ubah iframe menjadi query nama/alamat toko agar frame 100% tampil normal tanpa error.
    if (input.includes('goo.gl') || input.includes('maps.app.goo.gl')) {
        const s = window.storeSettings || window.globalStoreSettings || {};
        const fallbackAddress = s.footer_address || s.store_title || 'Mainstay Drink Semarang';
        return `https://maps.google.com/maps?q=${encodeURIComponent(fallbackAddress)}&t=&z=18&ie=UTF8&iwloc=&output=embed`;
    }

    // 10. Jika teks biasa berupa nama tempat atau alamat toko
    if (!input.startsWith('http://') && !input.startsWith('https://')) {
        return `https://maps.google.com/maps?q=${encodeURIComponent(input)}&t=&z=17&ie=UTF8&iwloc=&output=embed`;
    }

    // Fallback default aman lokasi Mainstay Drink
    return "https://maps.google.com/maps?q=-6.9412973,110.5089463&t=&z=18&ie=UTF8&iwloc=&output=embed";
};

window.previewSettingMapsLive = (val) => {
    const frame = document.getElementById('fset-preview-maps-frame');
    const btnTest = document.getElementById('btn-test-maps-ext');
    const embedUrl = window.convertAnyMapsUrlToEmbed(val);
    if (frame) {
        frame.src = embedUrl;
    }
    if (btnTest) {
        const raw = (val || '').trim();
        btnTest.href = raw.startsWith('http') ? raw : (raw ? `https://maps.google.com/?q=${encodeURIComponent(raw)}` : 'https://maps.google.com');
    }
};

window.setPresetMaps = (type) => {
    const input = document.getElementById('fset-maps-input');
    if (!input) return;
    if (type === 'default') {
        input.value = "https://maps.google.com/maps?q=-6.9412973,110.5089463&t=&z=18&ie=UTF8&iwloc=&output=embed";
    } else if (type === 'address') {
        const addr = (document.getElementById('fset-footer-address')?.value || '').trim() || (window.storeSettings?.footer_address || window.storeSettings?.store_title || 'Mainstay Drink');
        input.value = addr;
    }
    window.previewSettingMapsLive(input.value);
};

// Inisialisasi awal Google Maps footer dari local cache jika ada
setTimeout(() => {
    const savedEmbed = localStorage.getItem('mainstay_footer_maps_embed');
    const frame = document.getElementById('footer-map');
    if (savedEmbed && frame) {
        frame.src = savedEmbed;
    }
}, 500);

// ============================================================================
// 1. MODUL PILIH MENU UNTUK PRE-ORDER (PENGGANTI PROMPT BLOKIR)
// ============================================================================
const getMergedPreOrderMenusMap = () => {
    const merged = {};
    if (typeof DEFAULT_MAINSTAY_CATALOG === 'object' && DEFAULT_MAINSTAY_CATALOG) {
        Object.assign(merged, DEFAULT_MAINSTAY_CATALOG);
    }
    if (typeof dummyCatalog === 'object' && dummyCatalog) {
        Object.assign(merged, dummyCatalog);
    }
    if (typeof globalMenus === 'object' && globalMenus) {
        Object.assign(merged, globalMenus);
    }
    if (window.globalMenus && typeof window.globalMenus === 'object') {
        Object.assign(merged, window.globalMenus);
    }
    return merged;
};

window.renderListPilihMenuPreOrder = (filterText = '') => {
    const listEl = document.getElementById('list-pilih-menu-preorder') || document.getElementById('list-menu-pilih-preorder');
    if (!listEl) return;

    const statusEl = document.getElementById('preorder-picker-status-text');
    const activeItems = Array.isArray(window._editingPreOrder?.items) ? window._editingPreOrder.items : [];
    const activeQtyTotal = activeItems.reduce((acc, it) => acc + (Number(it?.qty) || 1), 0);
    if (statusEl) {
        statusEl.innerText = `Pesanan: ${activeItems.length} menu (${activeQtyTotal} porsi)`;
    }

    const query = String(filterText || '').trim().toLowerCase();
    const menusMap = getMergedPreOrderMenusMap();

    if (Object.keys(menusMap).length === 0 && navigator.onLine && typeof db !== 'undefined' && typeof get === 'function') {
        listEl.innerHTML = `<div class="p-6 text-center text-xs text-slate-400 font-bold"><i class="fa-solid fa-spinner fa-spin mr-1"></i> Memuat daftar menu...</div>`;
        get(ref(db, 'menus')).then((snap) => {
            if (snap.exists()) {
                const val = snap.val() || {};
                if (typeof globalMenus === 'object' && globalMenus) {
                    Object.assign(globalMenus, val);
                }
                window.globalMenus = { ...(window.globalMenus || {}), ...val };
                window.renderListPilihMenuPreOrder(document.getElementById('cari-menu-preorder-input')?.value || filterText);
            } else {
                listEl.innerHTML = `<div class="p-6 text-center text-xs text-slate-400 font-bold italic">Belum ada menu tersedia di katalog.</div>`;
            }
        }).catch(() => {
            listEl.innerHTML = `<div class="p-6 text-center text-xs text-rose-500 font-bold italic">Gagal memuat daftar menu.</div>`;
        });
        return;
    }

    const menuList = Object.entries(menusMap)
        .filter(([, m]) => m && typeof m === 'object' && (m.name || m.nama))
        .map(([k, m]) => ({ ...m, _entryKey: k, key: k }));

    const filtered = menuList.filter(m => {
        const name = String(m.name || m.nama || '').toLowerCase();
        const cat = String(m.category || m.kategori || '').toLowerCase();
        return !query || name.includes(query) || cat.includes(query);
    });

    if (filtered.length === 0) {
        listEl.innerHTML = `<div class="p-6 text-center text-xs text-slate-400 font-bold italic">Tidak ada menu yang cocok dengan kata kunci "${query}".</div>`;
        return;
    }

    const escAttr = (s) => String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

    listEl.innerHTML = filtered.map(m => {
        const rawKey = String(m._entryKey || m.key || m.id || '');
        const name = String(m.name || m.nama || 'Menu');
        const price = Number(m.price || m.harga || 0);
        const cat = String(m.category || m.kategori || 'Minuman');
        const img = m.imageUrl || m.gambar || m.image || 'logo-192.png';
        const isAvail = m.isAvailable !== false;

        const qtyInOrder = activeItems.reduce((sum, it) => {
            if (!it) return sum;
            const sameKey = (it.rawMenuKey && String(it.rawMenuKey) === rawKey) || (it.id && String(it.id) === String(m.id || rawKey));
            return sum + (sameKey ? (Number(it.qty) || 1) : 0);
        }, 0);

        return `
            <div class="flex items-center justify-between gap-2.5 p-3 bg-white hover:bg-amber-50/50 rounded-2xl border border-slate-200 transition shadow-2xs">
                <div class="flex items-center gap-3 min-w-0 flex-1">
                    <img src="${escAttr(img)}" alt="${escAttr(name)}" class="w-12 h-12 rounded-xl object-cover border border-slate-100 bg-slate-100 shrink-0" onerror="this.onerror=null; this.src='logo-192.png'">
                    <div class="min-w-0 flex-1">
                        <div class="flex items-center gap-1.5 min-w-0">
                            <h4 class="text-xs font-black text-slate-800 truncate">${escAttr(name)}</h4>
                            ${qtyInOrder > 0 ? `<span class="text-[9px] font-black px-1.5 py-0.5 rounded-full bg-emerald-100 text-emerald-800 shrink-0">${qtyInOrder}x</span>` : ''}
                        </div>
                        <p class="text-[10px] font-bold text-slate-400 truncate">${escAttr(cat)} &bull; <span class="text-amber-600 font-black">Rp ${price.toLocaleString('id-ID')}</span></p>
                        ${!isAvail ? '<span class="text-[9px] font-black text-rose-500">Stok Habis</span>' : ''}
                    </div>
                </div>
                <button type="button" data-menu-key="${escAttr(rawKey)}" class="btn-pilih-menu-preorder px-3 py-1.5 bg-amber-500 hover:bg-amber-600 text-slate-900 font-black text-xs rounded-xl transition shadow-xs flex items-center gap-1 active:scale-95 shrink-0 cursor-pointer">
                    <i class="fa-solid fa-plus text-[10px]"></i> Tambah
                </button>
            </div>
        `;
    }).join('');

    // Binding delegasi klik satu kali pada container list agar tidak pernah menumpuk/menimpa listener
    if (listEl.dataset.boundPilihPreOrder !== '1') {
        listEl.addEventListener('click', (e) => {
            const btn = e.target.closest('.btn-pilih-menu-preorder');
            if (!btn || !listEl.contains(btn)) return;
            e.preventDefault();
            e.stopPropagation();
            const key = btn.getAttribute('data-menu-key') || '';
            window.pilihMenuUntukPreOrder(key);
        });
        listEl.dataset.boundPilihPreOrder = '1';
    }
};

window.filterMenuPilihPreOrder = (val) => {
    window.renderListPilihMenuPreOrder(val);
};

window.pilihMenuUntukPreOrder = (menuKey) => {
    const menusMap = getMergedPreOrderMenusMap();
    let m = menusMap[menuKey] || null;
    if (!m) {
        const entry = Object.entries(menusMap).find(([k, it]) =>
            k === menuKey ||
            String(k) === String(menuKey) ||
            (it && (String(it.id) === String(menuKey) || String(it.key) === String(menuKey)))
        );
        if (entry) m = entry[1];
    }
    if (!m) {
        window.tampilkanNotifikasi('Menu tidak ditemukan di katalog.', 'error');
        return;
    }

    const cleanPrice = Number(m.price || m.harga || 0);
    const cleanName = m.name || m.nama || 'Menu';
    const newItem = {
        id: m.id || menuKey,
        rawMenuKey: menuKey,
        name: cleanName,
        nama: cleanName,
        price: cleanPrice,
        harga: cleanPrice,
        basePrice: cleanPrice,
        qty: 1,
        total: cleanPrice,
        varian: 'Normal Ice',
        notes: 'Normal Ice',
        toppings: []
    };

    if (!window._editingPreOrder) window._editingPreOrder = { items: [] };
    if (!Array.isArray(window._editingPreOrder.items)) {
        window._editingPreOrder.items = normalizePreOrderItemsArray(window._editingPreOrder.items);
    }
    window._editingPreOrder.items.push(newItem);
    window._lastAddedPreOrderIdx = window._editingPreOrder.items.length - 1;

    if (typeof window.renderItemsPreOrderEditor === 'function') {
        window.renderItemsPreOrderEditor();
    }
    window.tutupModalPilihMenuPreOrder();

    const editModal = document.getElementById('modal-edit-preorder');
    const listContainer = editModal ? editModal.querySelector('#edit-preorder-items-list') : document.getElementById('edit-preorder-items-list');
    if (listContainer && listContainer.lastElementChild) {
        setTimeout(() => {
            try {
                listContainer.lastElementChild.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            } catch (e) {}
        }, 50);
    }

    window.tampilkanNotifikasi(`Menu "${newItem.name}" ditambahkan ke Pre-Order`, 'success');
};

window.tutupModalPilihMenuPreOrder = () => {
    const modal = document.getElementById('modal-pilih-menu-preorder');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

// ============================================================================
// 2. MODUL QR CODE GENERATOR DISPLAY PRODUK
// ============================================================================
window._activeQrProdukData = null;

window.getMenuQrThemePalette = (menu = {}) => {
    const rawName = String(menu.name || menu.nama || '').toLowerCase();
    const rawCat = String(menu.category || menu.kategori || '').toLowerCase();
    const combined = `${rawName} ${rawCat}`;

    const presets = [
        {
            match: /matcha|green\s*tea|pandan|avocado|alpukat|melon|mint|pistachio/,
            label: 'Matcha & Botanical',
            qrDark: '#065f46',
            headerFrom: '#059669',
            headerTo: '#0f766e',
            cardBg: '#ecfdf5',
            cardBorder: '#34d399',
            badgeBg: '#d1fae5',
            badgeText: '#065f46',
            titleColor: '#064e3b',
            priceBg: '#dcfce7',
            priceBorder: '#10b981',
            priceText: '#047857',
            btnBg: '#059669',
            btnSubBg: '#0f766e'
        },
        {
            match: /taro|ubi|grape|anggur|lavender|blueberry|violet|ungu/,
            label: 'Taro & Violet',
            qrDark: '#5b21b6',
            headerFrom: '#7c3aed',
            headerTo: '#4f46e5',
            cardBg: '#f5f3ff',
            cardBorder: '#a78bfa',
            badgeBg: '#ede9fe',
            badgeText: '#5b21b6',
            titleColor: '#4c1d95',
            priceBg: '#f3e8ff',
            priceBorder: '#8b5cf6',
            priceText: '#6d28d9',
            btnBg: '#7c3aed',
            btnSubBg: '#4f46e5'
        },
        {
            match: /thai\s*tea|mango|mangga|jeruk|orange|peach|caramel|hazelnut|palm|aren|butterscotch|cheese/,
            label: 'Thai Tea & Amber',
            qrDark: '#9a3412',
            headerFrom: '#ea580c',
            headerTo: '#d97706',
            cardBg: '#fff7ed',
            cardBorder: '#fb923c',
            badgeBg: '#ffedd5',
            badgeText: '#9a3412',
            titleColor: '#7c2d12',
            priceBg: '#fef3c7',
            priceBorder: '#f59e0b',
            priceText: '#b45309',
            btnBg: '#ea580c',
            btnSubBg: '#d97706'
        },
        {
            match: /strawberr|stroberi|berry|red\s*velvet|sakura|rose|pink|guava|jambu|semangka|raspberry|cranberry|lychee\s*rose/,
            label: 'Berry & Velvet',
            qrDark: '#9f1239',
            headerFrom: '#e11d48',
            headerTo: '#be185d',
            cardBg: '#fff1f2',
            cardBorder: '#fb7185',
            badgeBg: '#ffe4e6',
            badgeText: '#9f1239',
            titleColor: '#881337',
            priceBg: '#fce7f3',
            priceBorder: '#ec4899',
            priceText: '#be185d',
            btnBg: '#e11d48',
            btnSubBg: '#be185d'
        },
        {
            match: /cokelat|coklat|choco|milo|ovaltine|oreo|coffee|kopi|espresso|latte|mocha|cappuccino|americano|boba|brown/,
            label: 'Coffee & Choco',
            qrDark: '#451a03',
            headerFrom: '#78350f',
            headerTo: '#92400e',
            cardBg: '#fffbeb',
            cardBorder: '#d97706',
            badgeBg: '#fef3c7',
            badgeText: '#78350f',
            titleColor: '#451a03',
            priceBg: '#fde68a',
            priceBorder: '#b45309',
            priceText: '#78350f',
            btnBg: '#78350f',
            btnSubBg: '#b45309'
        },
        {
            match: /blue|ocean|lychee|leci|soda|mojito|lemon|aqua|yogurt|yakult|vanilla|coconut|kelapa|milk/,
            label: 'Fresh Ocean',
            qrDark: '#0c4a6e',
            headerFrom: '#0284c7',
            headerTo: '#0d9488',
            cardBg: '#f0f9ff',
            cardBorder: '#38bdf8',
            badgeBg: '#e0f2fe',
            badgeText: '#0369a1',
            titleColor: '#0c4a6e',
            priceBg: '#cffafe',
            priceBorder: '#06b6d4',
            priceText: '#0e7490',
            btnBg: '#0284c7',
            btnSubBg: '#0d9488'
        },
        {
            match: /makanan|food|mie|snack|roti|burger|kentang|rice|nasi|dimsum|ayam|crispy|sosis|toast/,
            label: 'Food & Snack',
            qrDark: '#7f1d1d',
            headerFrom: '#dc2626',
            headerTo: '#ea580c',
            cardBg: '#fef2f2',
            cardBorder: '#f87171',
            badgeBg: '#fee2e2',
            badgeText: '#991b1b',
            titleColor: '#7f1d1d',
            priceBg: '#ffedd5',
            priceBorder: '#ef4444',
            priceText: '#b91c1c',
            btnBg: '#dc2626',
            btnSubBg: '#ea580c'
        }
    ];

    for (const p of presets) {
        if (p.match.test(combined)) return p;
    }

    // Fallback deterministik berdasar hash nama menu agar tetap unik & berwarna
    let hash = 0;
    for (let i = 0; i < combined.length; i++) {
        hash = ((hash << 5) - hash) + combined.charCodeAt(i);
        hash |= 0;
    }
    return presets[Math.abs(hash) % presets.length];
};

window.bukaModalQrProduk = async (menuKey) => {
    const menusMap = (typeof globalMenus !== 'undefined' && globalMenus) || window.globalMenus || {};
    let m = menusMap[menuKey] || null;
    if (!m) {
        m = Object.values(menusMap).find(it => it && (it.id == menuKey || it.key == menuKey));
    }
    if (!m) {
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi("Data menu tidak ditemukan untuk QR.", "error");
        }
        return;
    }

    const s = window.storeSettings || window.globalStoreSettings || window.defaultStoreSettings || {};
    const storeTitle = s.receipt_store_name || s.store_title || 'Mainstay Drink';
    const storeLogo = s.receipt_logo || s.store_logo || 'logo-192.png';
    const menuName = m.name || m.nama || 'Menu';
    const menuPhotoUrl = m.imageUrl || m.gambar || m.image || m.foto || '';
    const rawPrice = Number(m.price || m.harga || 0);
    const effPrice = (typeof window.getMenuEffectivePrice === 'function') ? Number(window.getMenuEffectivePrice(m)) : rawPrice;
    const menuCategory = m.category || m.kategori || 'Minuman';
    const theme = window.getMenuQrThemePalette(m);

    const origin = window.location.origin || (window.location.protocol + '//' + window.location.host);
    const productUrl = `${origin}/?menu=${encodeURIComponent(menuKey)}`;

    let qrImageUrl = '';
    try {
        if (window.QRCode && typeof window.QRCode.toDataURL === 'function') {
            qrImageUrl = await window.QRCode.toDataURL(productUrl, {
                width: 600,
                margin: 2,
                errorCorrectionLevel: 'H',
                color: { dark: theme.qrDark, light: '#ffffff' }
            });
        } else {
            qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&color=${theme.qrDark.replace('#', '')}&bgcolor=ffffff&data=${encodeURIComponent(productUrl)}`;
        }
    } catch (e) {
        qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&color=${theme.qrDark.replace('#', '')}&bgcolor=ffffff&data=${encodeURIComponent(productUrl)}`;
    }

    const headerEl = document.getElementById('qr-modal-header');
    const cardPreviewEl = document.getElementById('qr-display-card-preview');
    const bgImgEl = document.getElementById('qr-preview-bg-img');
    const bgScrimEl = document.getElementById('qr-preview-bg-scrim');
    const thumbEl = document.getElementById('qr-preview-menu-thumb');
    const catBadgeEl = document.getElementById('qr-preview-category-badge');
    const qrWrapEl = document.getElementById('qr-preview-qr-wrap');
    const btnCetakEl = document.getElementById('qr-btn-cetak');
    const btnUnduhEl = document.getElementById('qr-btn-unduh');
    const logoEl = document.getElementById('qr-preview-logo');
    const storeEl = document.getElementById('qr-preview-store');
    const nameEl = document.getElementById('qr-preview-menu-name');
    const priceEl = document.getElementById('qr-preview-menu-price');
    const imgEl = document.getElementById('qr-preview-image');
    const urlInput = document.getElementById('qr-modal-url-input');

    if (headerEl) headerEl.style.background = `linear-gradient(135deg, ${theme.headerFrom}, ${theme.headerTo})`;
    if (cardPreviewEl) {
        cardPreviewEl.style.background = `linear-gradient(160deg, ${theme.headerFrom} 0%, #0f172a 100%)`;
        cardPreviewEl.style.borderColor = theme.cardBorder;
    }

    // Sinkronkan background kartu & thumbnail medallion simetris dengan foto produk menu
    if (bgImgEl && bgScrimEl) {
        if (menuPhotoUrl) {
            bgImgEl.src = menuPhotoUrl;
            bgImgEl.classList.remove('hidden');
            bgImgEl.onerror = () => {
                bgImgEl.classList.add('hidden');
                bgScrimEl.classList.add('hidden');
            };
            bgScrimEl.style.background = `linear-gradient(180deg, rgba(15,23,42,0.52) 0%, ${theme.headerFrom}bf 48%, rgba(15,23,42,0.94) 100%)`;
            bgScrimEl.classList.remove('hidden');
        } else {
            bgImgEl.src = '';
            bgImgEl.classList.add('hidden');
            bgScrimEl.classList.add('hidden');
        }
    }
    if (thumbEl) {
        if (menuPhotoUrl) {
            thumbEl.src = menuPhotoUrl;
            thumbEl.classList.remove('hidden');
            thumbEl.onerror = () => thumbEl.classList.add('hidden');
        } else {
            thumbEl.src = '';
            thumbEl.classList.add('hidden');
        }
    }

    if (catBadgeEl) {
        catBadgeEl.innerText = `${String(menuCategory).toUpperCase()} • ${theme.label.toUpperCase()}`;
        catBadgeEl.style.backgroundColor = 'transparent';
        catBadgeEl.style.color = '#fde68a';
    }
    if (qrWrapEl) qrWrapEl.style.borderColor = '#ffffff';
    if (btnCetakEl) btnCetakEl.style.backgroundColor = theme.btnBg;
    if (btnUnduhEl) btnUnduhEl.style.backgroundColor = theme.btnSubBg;

    if (logoEl) {
        logoEl.src = storeLogo;
        logoEl.onerror = () => { logoEl.src = 'logo-192.png'; };
    }
    if (storeEl) storeEl.innerText = storeTitle.toUpperCase();
    if (nameEl) {
        nameEl.innerText = menuName;
        nameEl.style.color = '#ffffff';
    }
    if (priceEl) {
        priceEl.style.backgroundColor = '#ffffff';
        priceEl.style.borderColor = theme.priceBorder;
        priceEl.style.color = theme.priceText;
        if (effPrice < rawPrice) {
            priceEl.innerHTML = `<span class="line-through text-slate-400 mr-1 text-[10px]">Rp ${rawPrice.toLocaleString('id-ID')}</span>Rp ${effPrice.toLocaleString('id-ID')}`;
        } else {
            priceEl.innerText = `Rp ${rawPrice.toLocaleString('id-ID')}`;
        }
    }
    if (imgEl) imgEl.src = qrImageUrl;
    if (urlInput) urlInput.value = productUrl;

    window._activeQrProdukData = {
        menuKey,
        menuName,
        menuCategory,
        menuPhotoUrl,
        rawPrice,
        effPrice,
        storeTitle,
        storeLogo,
        productUrl,
        qrImageUrl,
        theme
    };

    const modal = document.getElementById('modal-qr-produk');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    }
};

window.tutupModalQrProduk = () => {
    const modal = document.getElementById('modal-qr-produk');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
};

window.salinUrlMenuQr = () => {
    const input = document.getElementById('qr-modal-url-input');
    if (input) {
        input.select();
        navigator.clipboard?.writeText(input.value).then(() => {
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi("Tautan produk berhasil disalin!", "success");
            }
        }).catch(() => {
            document.execCommand('copy');
            if (typeof window.tampilkanNotifikasi === 'function') {
                window.tampilkanNotifikasi("Tautan produk disalin!", "success");
            }
        });
    }
};

window.unduhQrDisplayProduk = async () => {
    const d = window._activeQrProdukData;
    if (!d || !d.qrImageUrl) return;
    const theme = d.theme || window.getMenuQrThemePalette({ name: d.menuName, category: d.menuCategory });

    const loadImageSafe = (srcUrl) => new Promise((resolve) => {
        if (!srcUrl) return resolve(null);
        const im = new Image();
        im.crossOrigin = 'anonymous';
        im.onload = () => resolve(im);
        im.onerror = () => resolve(null);
        im.src = srcUrl;
    });

    try {
        const [qrImg, photoImg, logoImg] = await Promise.all([
            loadImageSafe(d.qrImageUrl),
            loadImageSafe(d.menuPhotoUrl),
            loadImageSafe(d.storeLogo)
        ]);
        if (!qrImg) throw new Error('QR gagal dimuat');

        const W = 900;
        const H = 1200;
        const CX = W / 2;
        const canvas = document.createElement('canvas');
        canvas.width = W;
        canvas.height = H;
        const ctx = canvas.getContext('2d');

        ctx.save();
        ctx.beginPath();
        ctx.roundRect(0, 0, W, H, 52);
        ctx.clip();

        // Gradient editorial dasar sesuai tema warna menu
        const baseGrad = ctx.createLinearGradient(0, 0, W, H);
        baseGrad.addColorStop(0, theme.headerFrom || '#4338ca');
        baseGrad.addColorStop(1, '#0f172a');
        ctx.fillStyle = baseGrad;
        ctx.fillRect(0, 0, W, H);

        // Full-bleed background foto menu + dark glass scrim simetris
        if (photoImg && photoImg.width > 0 && photoImg.height > 0) {
            const scale = Math.max(W / photoImg.width, H / photoImg.height);
            const dw = photoImg.width * scale;
            const dh = photoImg.height * scale;
            ctx.drawImage(photoImg, (W - dw) / 2, (H - dh) / 2, dw, dh);

            const scrim = ctx.createLinearGradient(0, 0, 0, H);
            scrim.addColorStop(0, 'rgba(15, 23, 42, 0.56)');
            scrim.addColorStop(0.45, `${theme.headerFrom || '#312e81'}c4`);
            scrim.addColorStop(1, 'rgba(15, 23, 42, 0.94)');
            ctx.fillStyle = scrim;
            ctx.fillRect(0, 0, W, H);
        }

        // Top Brand Pill (Strictly Centered)
        ctx.font = '900 22px Nunito, sans-serif';
        const brandTxt = String(d.storeTitle || 'MAINSTAY DRINK').toUpperCase();
        const brandTxtW = ctx.measureText(brandTxt).width;
        const pillW = Math.min(620, Math.max(260, brandTxtW + (logoImg ? 92 : 64)));
        const pillX = CX - (pillW / 2);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.96)';
        ctx.beginPath();
        ctx.roundRect(pillX, 54, pillW, 56, 28);
        ctx.fill();
        if (logoImg && logoImg.width > 0) {
            ctx.drawImage(logoImg, pillX + 18, 63, 38, 38);
            ctx.textAlign = 'left';
            ctx.fillStyle = '#0f172a';
            ctx.fillText(brandTxt, pillX + 68, 90);
        } else {
            ctx.textAlign = 'center';
            ctx.fillStyle = '#0f172a';
            ctx.fillText(brandTxt, CX, 90);
        }

        // Centered Menu Photo Medallion
        let cursorY = 148;
        if (photoImg && photoImg.width > 0) {
            const medSize = 136;
            const medX = CX - (medSize / 2);
            ctx.save();
            ctx.beginPath();
            ctx.roundRect(medX, cursorY, medSize, medSize, 32);
            ctx.clip();
            const ps = Math.max(medSize / photoImg.width, medSize / photoImg.height);
            ctx.drawImage(photoImg, medX + (medSize - photoImg.width * ps) / 2, cursorY + (medSize - photoImg.height * ps) / 2, photoImg.width * ps, photoImg.height * ps);
            ctx.restore();

            ctx.lineWidth = 5;
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.95)';
            ctx.beginPath();
            ctx.roundRect(medX, cursorY, medSize, medSize, 32);
            ctx.stroke();
            cursorY += medSize + 36;
        } else {
            cursorY = 190;
        }

        // Centered Category Label
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fde68a';
        ctx.font = '900 22px Nunito, sans-serif';
        ctx.fillText(`${String(d.menuCategory || 'MENU').toUpperCase()} • ${theme.label.toUpperCase()}`, CX, cursorY);
        cursorY += 48;

        // Centered Menu Name (with auto 2-line wrap if long)
        ctx.fillStyle = '#ffffff';
        ctx.font = '900 44px Nunito, sans-serif';
        const words = String(d.menuName || 'Menu').split(/\s+/);
        let line1 = '';
        let line2 = '';
        words.forEach(w => {
            const candidate = line1 ? `${line1} ${w}` : w;
            if (!line2 && ctx.measureText(candidate).width <= 720) {
                line1 = candidate;
            } else {
                line2 = line2 ? `${line2} ${w}` : w;
            }
        });
        ctx.fillText(line1, CX, cursorY);
        if (line2) {
            cursorY += 48;
            ctx.fillText(line2.length > 28 ? line2.substring(0, 26) + '..' : line2, CX, cursorY);
        }
        cursorY += 28;

        // Centered Price Badge Pill
        const priceText = `Rp ${Number(d.effPrice || 0).toLocaleString('id-ID')}`;
        ctx.font = '900 30px Nunito, sans-serif';
        const pW = Math.max(240, ctx.measureText(priceText).width + 72);
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.roundRect(CX - (pW / 2), cursorY, pW, 56, 28);
        ctx.fill();
        ctx.fillStyle = theme.priceText || '#047857';
        ctx.fillText(priceText, CX, cursorY + 38);

        // Centered White QR Card Frame
        const qrBoxSize = 480;
        const qrBoxY = Math.max(cursorY + 90, 520);
        const qrBoxX = CX - (qrBoxSize / 2);
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.roundRect(qrBoxX, qrBoxY, qrBoxSize, qrBoxSize, 36);
        ctx.fill();
        ctx.lineWidth = 6;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
        ctx.stroke();

        const qrInner = 416;
        ctx.drawImage(qrImg, CX - (qrInner / 2), qrBoxY + 32, qrInner, qrInner);

        // Centered Scan Footer
        const footY = qrBoxY + qrBoxSize + 52;
        ctx.textAlign = 'center';
        ctx.fillStyle = 'rgba(255, 255, 255, 0.94)';
        ctx.font = '800 23px Nunito, sans-serif';
        ctx.fillText('Scan QR di atas dengan kamera HP untuk langsung memesan', CX, footY);
        ctx.fillStyle = 'rgba(226, 232, 240, 0.72)';
        ctx.font = '700 18px Nunito, sans-serif';
        ctx.fillText(d.productUrl.replace(/^https?:\/\//, ''), CX, footY + 36);

        ctx.restore();

        // Subtle outer border frame
        ctx.lineWidth = 8;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.22)';
        ctx.beginPath();
        ctx.roundRect(4, 4, W - 8, H - 8, 48);
        ctx.stroke();

        const link = document.createElement('a');
        const safeName = d.menuName.replace(/[^a-zA-Z0-9_-]/g, '_');
        link.download = `Mainstay_QR_${safeName}.png`;
        link.href = canvas.toDataURL('image/png');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi(`QR Menu "${d.menuName}" berhasil diunduh!`, "success");
        }
    } catch (e) {
        console.error('Gagal unduh QR Produk:', e);
        if (typeof window.tampilkanNotifikasi === 'function') {
            window.tampilkanNotifikasi("Gagal mengunduh gambar QR produk.", "error");
        }
    }
};

window.cetakQrDisplayProduk = () => {
    const d = window._activeQrProdukData;
    if (!d) return;

    const receiptHtml = `
        <div class="cetak-khusus-thermal" style="padding: var(--thermal-pad-top, 2mm) var(--thermal-pad-right, 2mm) var(--thermal-pad-bottom, 4mm) var(--thermal-pad-left, 2mm); box-sizing: border-box; text-align: center; font-family: monospace, sans-serif;">
            <div style="margin-bottom: 4px;">
                <img src="${d.storeLogo}" style="height: 32px; width: auto; filter: grayscale(100%); margin: 0 auto;" onerror="this.src='logo-192.png'">
            </div>
            <div class="title" style="font-size: 13px;">${d.storeTitle.toUpperCase()}</div>
            <div class="divider"></div>
            <div class="bold" style="font-size: 12px; margin: 4px 0 2px;">${d.menuName}</div>
            <div class="bold" style="font-size: 12px; margin-bottom: 6px;">Rp ${d.effPrice.toLocaleString('id-ID')}</div>
            <div style="margin: 6px auto;">
                <img src="${d.qrImageUrl}" style="width: 44mm; height: 44mm; margin: 0 auto; display: block;">
            </div>
            <div class="divider"></div>
            <div style="font-size: 9px; margin-top: 4px;">Scan QR dengan kamera HP untuk langsung melihat & memesan menu ini.</div>
        </div>
    `;

    if (typeof window.eksekusiPrintThermalUniversal === 'function') {
        window.eksekusiPrintThermalUniversal({
            title: `QR_Produk_${d.menuName}`,
            htmlContent: receiptHtml
        });
    }
};

// ============================================================================
// 3. PWA HARDWARE BACK BUTTON NAVIGATION ENGINE
// ============================================================================
(function initPWABackButton() {
    window._mainstayExitingApp = false;
    const pushGuardState = () => {
        if (window.history && window.history.pushState) {
            window.history.pushState({ page: 'mainstay-root' }, '');
        }
    };
    pushGuardState();

    window.addEventListener('popstate', () => {
        if (window._mainstayExitingApp) return;

        // 1. Tutup modal yang sedang terbuka
        const openModals = [
            'modal-member-card-fullscreen',
            'modal-cetak-universal',
            'modal-struk-dapur',
            'modal-struk',
            'modal-form-cabang',
            'modal-riwayat-harga-menu',
            'modal-qr-produk',
            'modal-pilih-menu-preorder',
            'modal-edit-preorder',
            'modal-daftar-preorder',
            'modal-varian-pos',
            'modal-edit-pesanan-masuk',
            'modal-set-stok-modern',
            'modal-laba-bersih-info',
            'modal-scan-qr',
            'modal-voucher-detail'
        ];
        for (const modalId of openModals) {
            const el = document.getElementById(modalId);
            if (el && !el.classList.contains('hidden') && el.style.display !== 'none') {
                pushGuardState();
                if (modalId === 'modal-member-card-fullscreen' && typeof window.tutupKartuMemberFullscreenLandscape === 'function') {
                    window.tutupKartuMemberFullscreenLandscape();
                    return;
                }
                if (modalId === 'modal-struk-dapur' && typeof window.tutupStrukDapur === 'function') {
                    window.tutupStrukDapur();
                    return;
                }
                if (modalId === 'modal-struk' && typeof window.tutupStruk === 'function') {
                    window.tutupStruk();
                    return;
                }
                if (modalId === 'modal-qr-produk') {
                    window.tutupModalQrProduk();
                    return;
                }
                if (modalId === 'modal-pilih-menu-preorder') {
                    window.tutupModalPilihMenuPreOrder();
                    return;
                }
                if (modalId === 'modal-edit-preorder') {
                    window.tutupModalEditPreOrder();
                    return;
                }
                if (modalId === 'modal-daftar-preorder') {
                    window.tutupModalDaftarPreOrder();
                    return;
                }
                el.classList.add('hidden');
                el.classList.remove('flex');
                return;
            }
        }

        // 2. Tutup inner panel owner
        const ownerInnerPanels = document.getElementById('owner-inner-panels-container');
        if (ownerInnerPanels && ownerInnerPanels.children.length > 0 && ownerInnerPanels.innerHTML.trim() !== '') {
            pushGuardState();
            if (typeof window.closePanel === 'function') {
                window.closePanel();
                return;
            }
        }

        // 3. Tutup Ruang Kerja Kasir
        const ruangKerja = document.getElementById('ruang-kerja-kasir');
        if (ruangKerja && !ruangKerja.classList.contains('hidden') && ruangKerja.style.display !== 'none') {
            pushGuardState();
            if (typeof window.tutupRuangKerja === 'function') {
                window.tutupRuangKerja();
                return;
            }
        }

        // 4. Cek Peran: Jika sedang login (kasir/owner), tombol kembali melakukan LOGOUT
        const savedRole = localStorage.getItem('mainstay_session_role') || 'customer';
        const isKasirOpen = localStorage.getItem('mainstay_is_kasir_open') === 'true';

        if (savedRole !== 'customer' || isKasirOpen) {
            pushGuardState();
            if (typeof window.prosesLogout === 'function') {
                window.prosesLogout(savedRole);
            } else if (typeof window.switchRoleView === 'function') {
                window.switchRoleView('customer');
            }
            return;
        }

        // 5. Jika sudah di halaman depan: Konfirmasi keluar aplikasi tanpa menahan history guard
        window.tampilkanKonfirmasiGlobal({
            title: "Keluar Aplikasi?",
            message: "Apakah Anda yakin ingin keluar dari aplikasi Mainstay Drink?",
            subtext: "Tekan 'Keluar' untuk menutup aplikasi.",
            icon: "fa-right-from-bracket",
            confirmText: "Keluar",
            cancelText: "Batal",
            isDanger: true,
            onCancel: () => {
                window._mainstayExitingApp = false;
                pushGuardState();
            },
            onConfirm: () => {
                window._mainstayExitingApp = true;
                try {
                    if (navigator.app && typeof navigator.app.exitApp === 'function') {
                        navigator.app.exitApp();
                        return;
                    }
                    if (window.Android && typeof window.Android.exitApp === 'function') {
                        window.Android.exitApp();
                        return;
                    }
                    if (window.Capacitor?.Plugins?.App && typeof window.Capacitor.Plugins.App.exitApp === 'function') {
                        window.Capacitor.Plugins.App.exitApp();
                        return;
                    }
                } catch (e) {}

                try { window.close(); } catch (e) {}
                try { window.history.back(); } catch (e) {}

                setTimeout(() => {
                    if (document.visibilityState !== 'hidden' && !document.getElementById('mainstay-app-exited-screen')) {
                        const exitScreen = document.createElement('div');
                        exitScreen.id = 'mainstay-app-exited-screen';
                        exitScreen.className = 'fixed inset-0 z-[9999999] bg-slate-950 text-white flex flex-col items-center justify-center p-6 text-center fade-in';
                        exitScreen.innerHTML = `
                            <div class="w-16 h-16 rounded-2xl bg-amber-500/20 border border-amber-400/40 text-amber-400 flex items-center justify-center text-2xl mb-4">
                                <i class="fa-solid fa-door-open"></i>
                            </div>
                            <h2 class="text-lg font-black mb-1">Aplikasi Ditutup</h2>
                            <p class="text-xs text-slate-400 max-w-xs mb-6 leading-relaxed">Sesi Mainstay Drink selesai. Anda dapat menutup tab/jendela ini sekarang atau membuka kembali aplikasi.</p>
                            <button type="button" onclick="window._mainstayExitingApp=false; this.closest('#mainstay-app-exited-screen').remove(); window.history?.pushState?.({page:'mainstay-root'},'');" class="px-5 py-2.5 bg-amber-500 hover:bg-amber-400 text-slate-950 font-black text-xs rounded-xl shadow-lg cursor-pointer transition active:scale-95">
                                Buka Kembali Aplikasi
                            </button>
                        `;
                        document.body.appendChild(exitScreen);
                    }
                }, 380);
            }
        });
    });
})();

// =========================================================================
// TOMBOL KECIL ROLL-ON-TOP (SCROLL KE ATAS SECARA HALUS)
// =========================================================================
(function initRollOnTopButton() {
    let activeScrolledTarget = null;

    const isEligibleScrollContainer = (el) => {
        if (!el || el === document || el === window) return false;
        if (el.closest && el.closest('#view-customer, #view-kasir, #view-owner, #ruang-kerja-kasir, #panel-kasir-manual, #owner-inner-panels-container')) {
            return el.classList && el.classList.contains('overflow-y-auto') && el.scrollHeight > el.clientHeight + 200;
        }
        return false;
    };

    const updateRollBtnVisibility = (scrollEl) => {
        const btn = document.getElementById('btn-roll-on-top');
        if (!btn) return;

        const winScrollY = window.scrollY || document.documentElement.scrollTop || document.body.scrollTop || 0;
        const containerScrollY = (scrollEl && scrollEl.scrollTop) ? scrollEl.scrollTop : 0;
        const activeScrollY = Math.max(winScrollY, containerScrollY);

        // Sesuaikan jarak bawah agar rapi di atas #btn-bgm saat mode customer, atau bottom-5 saat #btn-bgm tersembunyi
        const bgmBtn = document.getElementById('btn-bgm');
        const isBgmVisible = bgmBtn && bgmBtn.offsetParent !== null && !bgmBtn.classList.contains('hidden');
        if (isBgmVisible) {
            btn.classList.add('bottom-16');
            btn.classList.remove('bottom-5');
        } else {
            btn.classList.add('bottom-5');
            btn.classList.remove('bottom-16');
        }

        if (activeScrollY > 240) {
            btn.classList.remove('opacity-0', 'translate-y-3', 'pointer-events-none');
            btn.classList.add('opacity-100', 'translate-y-0', 'pointer-events-auto');
        } else {
            btn.classList.add('opacity-0', 'translate-y-3', 'pointer-events-none');
            btn.classList.remove('opacity-100', 'translate-y-0', 'pointer-events-auto');
        }
    };

    window.rollToTop = () => {
        try {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (e) {
            window.scrollTo(0, 0);
        }
        if (activeScrolledTarget && typeof activeScrolledTarget.scrollTo === 'function') {
            try {
                activeScrolledTarget.scrollTo({ top: 0, behavior: 'smooth' });
            } catch (e) {
                activeScrolledTarget.scrollTop = 0;
            }
        }
    };

    window.addEventListener('scroll', () => {
        updateRollBtnVisibility(activeScrolledTarget);
    }, { passive: true });

    document.addEventListener('scroll', (ev) => {
        const target = ev.target;
        if (isEligibleScrollContainer(target)) {
            activeScrolledTarget = target;
            updateRollBtnVisibility(target);
        }
    }, { capture: true, passive: true });
})();
